const C: Record<string, string[]> = {"Mishneh Torah, Agents and Partners 1":["הָאוֹמֵר לִשְׁלוּחוֹ צֵא וּמְכֹר לִי קַרְקַע אוֹ מִטַּלְטְלִין אוֹ קְנֵה לִי הֲרֵי זֶה מוֹכֵר וְלוֹקֵחַ וְעוֹשֶׂה שְׁלִיחוּתוֹ וְכָל מַעֲשָׂיו קַיָּמִין. וְאֵין הָעוֹשֶׂה שָׁלִיחַ צָרִיךְ קִנְיָן וְלֹא עֵדִים אֶלָּא בַּאֲמִירָה בִּלְבַד בֵּינוֹ לְבֵין חֲבֵרוֹ. וְאֵין צְרִיכִין עֵדִים אֶלָּא לְגַלּוֹת הַדָּבָר אִם כָּפַר אֶחָד מֵהֶם כִּשְׁאָר כָּל הַטְּעָנוֹת:","שָׁלִיחַ שֶׁעָבַר עַל דִּבְרֵי מְשַׁלְּחוֹ לֹא עָשָׂה כְּלוּם. וְכֵן אִם טָעָה בְּכָל שֶׁהוּא בֵּין בְּקַרְקַע בֵּין בְּמִטַּלְטְלִין חוֹזֵר שֶׁהֲרֵי הוּא אוֹמֵר לְתַקֵּן שְׁלִיחוּתִי שְׁדַרְתִּיךָ וְלֹא לְעַוֵּת. וְלֹא אָמְרוּ שֶׁהַהוֹנָיָה בְּמִטַּלְטְלִין שְׁתוּת וְהָעֲבָדִים וְהַשְּׁטָרוֹת וְהַקַּרְקָעוֹת אֵין בָּהֶן הוֹנָיָה אֶלָּא בְּמוֹכֵר שֶׁלּוֹ אוֹ קוֹנֶה לְעַצְמוֹ אֲבָל שָׁלִיחַ שֶׁטָּעָה בְּכֻלָּם בְּכָל שֶׁהוּא חוֹזֵר:","נָתַן מָעוֹת לִשְׁלוּחוֹ לִקְנוֹת לוֹ קַרְקַע וְקָנָה לוֹ שֶׁלֹּא בְּאַחֲרָיוּת הֲרֵי זֶה עִוֵּת וְהַשָּׁלִיחַ לוֹקֵחַ אוֹתָהּ לְעַצְמוֹ שֶׁלֹּא בְּאַחֲרָיוּת כְּמוֹ שֶׁעָשָׂה וְחוֹזֵר וּמוֹכְרָהּ לַמְשַׁלֵּחַ בְּאַחֲרָיוּת הוֹאִיל וְקָנָה אוֹתָהּ בִּמְעוֹתָיו וְהָאַחֲרָיוּת עַל הַשָּׁלִיחַ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. לְפִיכָךְ אִם הִתְנָה עָלָיו שֶׁעָשָׂהוּ שָׁלִיחַ בֵּין לְתַקֵּן בֵּין לְעַוֵּת אֲפִלּוּ מָכַר לוֹ שְׁוֵה מֵאָה בְּדִינָר אוֹ לָקַח שְׁוֵה דִּינָר בְּמֵאָה אֵינוֹ יָכוֹל לַחְזֹר בּוֹ וְחַיָּב הַמְשַׁלֵּחַ לִתֵּן לוֹ כְּפִי הַתְּנַאי:","הָאוֹמֵר לִשְׁלוּחוֹ מְכֹר לִי מִשָּׂדֶה שֶׁלִּי בֵּית סְאָה וּמָכַר לוֹ בֵּית סָאתַיִם הֲרֵי זֶה מוֹסִיף עַל דְּבָרָיו וְקָנָה הַלּוֹקֵחַ בֵּית סְאָה בִּלְבַד. אָמַר לוֹ מְכֹר לִי בֵּית סָאתַיִם וּמָכַר לוֹ בֵּית סְאָה הֲרֵי זֶה מַעֲבִיר עַל דְּבָרָיו וְלֹא קָנָה הַלּוֹקֵחַ. אָמַר לוֹ מְכֹר לִי שָׂדֶה לְאָדָם אֶחָד וְהָלַךְ הַשָּׁלִיחַ וּמְכָרָהּ לִשְׁנַיִם מִמְכָּרוֹ בָּטֵל שֶׁהֲרֵי עָבַר עַל דְּבָרָיו. אָמַר לוֹ מְכֹר לִי שָׂדֶה וְלֹא פֵּרֵשׁ אֲפִלּוּ מָכַר לְמֵאָה מִמְכָּרוֹ קַיָּם:","הַנּוֹתֵן מָעוֹת לִשְׁלוּחוֹ לִקַּח בָּהֶם חִטִּים אוֹ מִין מִמִּינֵי סְחוֹרָה וְלֹא לָקַח אֵין לוֹ עָלָיו אֶלָּא תַּרְעֹמֶת. נָתַן לוֹ מָעוֹת לִקַּח בָּהֶן חִטִּים בֵּין לַאֲכִילָה בֵּין לִסְחוֹרָה וְהָלַךְ וְלָקַח בָּהֶן שְׂעוֹרִים אִם פָּחֲתוּ דְּמֵי זֶה שֶׁלָּקַח פָּחֲתוּ לַשָּׁלִיחַ מִפְּנֵי שֶׁהוּא מְשַׁנֶּה. וְאִם הוֹסִיפוּ דְּמֵיהֶן הוֹסִיפוּ לְבַעַל הַמָּעוֹת. הָיָה הַשַּׁעַר קָצוּב וְיָדוּעַ וְהוֹסִיפוּ לַשָּׁלִיחַ בַּמִּנְיָן אוֹ בַּמִּשְׁקָל אוֹ בַּמִּדָּה כָּל שֶׁהוֹסִיפוּ לוֹ הַמּוֹכְרִים הֲרֵי הוּא שֶׁל שְׁנֵיהֶם וְחוֹלֵק הַתּוֹסֶפֶת הַשָּׁלִיחַ עִם בַּעַל הַמָּעוֹת. וְאִם הָיָה הַדָּבָר שֶׁאֵין לוֹ קִצְבָה הַכּל לְבַעַל הַמָּעוֹת:","מִי שֶׁהָיָה חַיָּב לַחֲבֵרוֹ מָמוֹן בֵּין מִשּׁוּם מִלְוֶה בֵּין מִשּׁוּם פִּקָּדוֹן אוֹ שְׂכִירוּת וְנָתַן הַמָּעוֹת בְּיַד הַשָּׁלִיחַ וְאָמַר לוֹ הוֹלֵךְ מָמוֹן זֶה לְבַעַל חוֹבִי אֵין הַשָּׁלִיחַ צָרִיךְ לְהִטָּפֵל לוֹ וְלִתֵּן לוֹ בִּפְנֵי עֵדִים. וְאִם אָמַר לַשָּׁלִיחַ אַל תִּפְרַע חוֹב זֶה אֶלָּא בְּעֵדִים וּפְרָעוֹ שֶׁלֹּא בְּעֵדִים חַיָּב לְשַׁלֵּם. וְכֵן אִם הָיָה הַחוֹב בִּשְׁטָר בֵּין שֶׁאָמַר לוֹ קַח הַשְּׁטָר וְתֵן לוֹ הַמָּעוֹת בֵּין שֶׁאָמַר לוֹ תֵּן הַמָּעוֹת וְקַח הַשְּׁטָר וְנָתַן בְּלֹא עֵדִים וְלֹא לָקַח הַשְּׁטָר חַיָּב לְשַׁלֵּם שֶׁהֲרֵי לְתַקֵּן שְׁלָחוֹ וְלֹא לְעַוֵּת:","הַשּׁוֹלֵחַ מָעוֹת שֶׁבְּיָדוֹ בְּיַד שְׁלוּחוֹ וְאָמַר לוֹ הוֹלֵךְ מָמוֹן זֶה לִפְלוֹנִי שֶׁאֲנִי חַיָּב לוֹ וְהָלַךְ וְנָתַן לוֹ שֶׁלֹּא בְּעֵדִים. הַשָּׁלִיחַ אוֹמֵר נָתַתִּי וּבַעַל חוֹב אוֹ הַפּוֹעֵל אוֹמֵר לֹא לָקַחְתִּי. וַהֲרֵי שְׁלָשְׁתָּן עוֹמְדִין. הַשָּׁלִיחַ נִשְׁבָּע הֶסֵּת שֶׁנָּתַן וּבַעַל חוֹב אוֹ הַפּוֹעֵל נִשְׁבָּע [שְׁבוּעַת הַתּוֹרָה] שֶׁלֹּא לָקַח וִישַׁלֵּם הַלָּה לְבַעַל חוֹב אוֹ לְבַעַל הַפִּקָּדוֹן. וַאֲפִלּוּ הָיוּ הַשְּׁלוּחִין שְׁנַיִם אֵין עֵדוּתָן מוֹעִילָה מִפְּנֵי שֶׁהֵן נוֹגְעִין בְּעֵדוּתָן שֶׁהֲרֵי חַיָּבִין לְהִשָּׁבַע הֶסֵּת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה הַשָּׁלִיחַ מַכְחִישׁ אֶת בַּעַל חוֹב וַהֲרֵי שְׁלָשְׁתָּן עוֹמְדִין. אֲבָל אִם בָּא הַשָּׁלִיחַ וְאָמַר נָתַתִּי כְּמָה שֶׁאָמַרְתָּ לִי אֵינוֹ יָכוֹל לְהַשְׁבִּיעוֹ הֶסֵּת שֶׁעָשָׂה שְׁלִיחוּתוֹ שֶׁהֲרֵי אֵין שָׁם טוֹעֵן עָלָיו טַעֲנַת וַדַּאי שֶׁלֹּא נַעֲשָׂה שְׁלִיחוּתוֹ. וְכֵן אִם מֵתוּ הַשְּׁלוּחִין אוֹ הָלְכוּ לָהֶן לִמְדִינַת הַיָּם וּבָא בַּעַל חוֹב לִתְבֹּעַ הַלּוֶֹה אֵינוֹ יָכוֹל לְהַשְׁבִּיעוֹ הֶסֵּת שֶׁלֹּא פְּרָעוֹ הַשָּׁלִיחַ שֶׁהֲרֵי אֵין כָּאן מִי שֶׁטּוֹעֵן עָלָיו טַעֲנַת וַדַּאי שֶׁלָּקַח אֶלָּא מַחֲרִים הַלּוֶֹה חֵרֶם סְתָם וּמְשַׁלֵּם הַחוֹב שֶׁעָלָיו. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רְאוּבֵן שֶׁשָּׁלַח כְּתָב לְשִׁמְעוֹן וְאָמַר לוֹ מָנֶה שֶׁיֵּשׁ לִי בְּיָדְךָ שְׁלָחֵהוּ לִי בְּיַד לֵוִי אִם רָצָה לְשַׁלְּחוֹ אֵינוֹ חַיָּב בְּאַחֲרָיוּתָן בֵּין שֶׁהָיָה מִלְוֶה בֵּין שֶׁהָיָה פִּקָּדוֹן. וְהוּא שֶׁיַּכִּיר שֶׁהוּא כְּתַב יָדוֹ. וְאִם טָעַן הַמַּלְוֶה וְאָמַר לֹא כָּתַבְתִּי וְלֹא שָׁלַחְתִּי לְךָ יִשָּׁבַע הַלּוֶֹה הֶסֵּת שֶׁכְּתַב יָדוֹ בָּא אֵלָיו וּלְפִיכָךְ שָׁלַח וְיִפָּטֵר. וְכָזֶה הוֹרוּ רַבּוֹתַי. אֲבָל אִם לֹא הָיָה הַכְּתָב כְּתַב יָדוֹ אוֹ שֶׁאֵין הַלּוֶֹה יוֹדֵעַ שֶׁהוּא כְּתַב יָדוֹ אוֹ אֲפִלּוּ הָיוּ כְּתוּבִין בּוֹ סִימָנִין וְאוֹתִיּוֹת שֶׁבֵּינֵיהֶן בְּיִחוּד אִם טָעַן רְאוּבֵן וְאָמַר לֹא שָׁלַחְתִּי כְּתָב וַאֲחֵרִים רִמּוּ בּוֹ שִׁמְעוֹן חַיָּב בְּאַחֲרָיוּתוֹ וּמְשַׁלֵּם לִרְאוּבֵן אַחַר שֶׁיַּחֲרִים עַל מִי שֶׁשָּׁלַח כְּתָב זֶה מִדַּעְתּוֹ וְלֹא יוֹדֶה. וְיֵשׁ מִי שֶׁהוֹרָה שֶׁיִּשָּׁבַע רְאוּבֵן וְאַחַר כָּךְ יִטּל כְּדִין כָּל הַנִּשְׁבָּעִין וְנוֹטְלִין:","לֵוִי שֶׁבָּא בִּשְׁלִיחוּת רְאוּבֵן וְלָקַח חֲמִשִּׁים מִשִּׁמְעוֹן. וּבָא רְאוּבֵן וְאָמַר לֹא שְׁלַחְתִּיו לִקַּח אֶלָּא עֶשְׂרִים וְעֶשְׂרִים בִּלְבַד הֵבִיא. הֲרֵי רְאוּבֵן נִשְׁבָּע שֶׁלֹּא שְׁלָחוֹ לְהָבִיא אֶלָּא עֶשְׂרִים וְעֶשְׂרִים בִּלְבַד הֵבִיא לוֹ כְּדִין כָּל מוֹדֶה מִקְצָת. וְלֵוִי נִשְׁבָּע הֶסֵּת שֶׁהַחֲמִשִּׁים שֶׁנָּתַתָּ לִי נָתַתִּי לִרְאוּבֵן וִישַׁלֵּם שִׁמְעוֹן מִבֵּיתוֹ אִם הָיָה חַיָּב לִרְאוּבֵן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Appraisals and Devoted Property 3":["הַמַּעֲרִיךְ אֶת הַפָּחוּת מִבֶּן עֶשְׂרִים וְלֹא עָמַד בְּדִין עַד שֶׁהָיָה יֶתֶר עַל עֶשְׂרִים אֵינוֹ נוֹתֵן אֶלָּא עֵרֶךְ פָּחוּת מִבֶּן עֶשְׂרִים. שֶׁאֵין הָעֵרֶךְ אֶלָּא בִּזְמַן הָעֵרֶךְ לֹא בִּזְמַן הַהַעֲמָדָה בַּדִּין:","כָּל הָעֲרָכִין הַקְּצוּבִין בַּתּוֹרָה הֵן שֶׁנּוֹתֵן הַמַּעֲרִיךְ אִם הָיָה עָשִׁיר. אֲבָל אִם הָיָה עָנִי וְאֵין יָדוֹ מַשֶּׂגֶת נוֹתֵן כָּל הַנִּמְצָא בְּיָדוֹ אֲפִלּוּ סֶלַע אֶחָד וְנִפְטָר שֶׁנֶּאֱמַר (ויקרא כז ח) \"וְאִם מָךְ הוּא מֵעֶרְכֶּךָ\" (ויקרא כז ח) \"עַל פִּי אֲשֶׁר תַּשִּׂיג יַד הַנֹּדֵר\":","וּמִנַּיִן שֶׁהוּא נוֹתֵן אֲפִלּוּ סֶלַע אֶחָד אִם אֵין לוֹ אֶלָּא סֶלַע אֶחָד שֶׁנֶּאֱמַר (ויקרא כז כה) \"וְכָל עֶרְכְּךָ יִהְיֶה בְּשֶׁקֶל הַקֹּדֶשׁ\" הָא לָמַדְתָּ שֶׁאֵין בַּעֲרָכִין פָּחוֹת מִסֶּלַע וְלֹא יוֹתֵר עַל חֲמִשִּׁים:","הֲרֵי שֶׁלֹּא נִמְצָא בְּיָדוֹ אֲפִלּוּ סֶלַע אֵין לוֹקְחִין מִמֶּנּוּ פָּחוֹת מִסֶּלַע. אֶלָּא יִשָּׁאֵר הַכּל עָלָיו חוֹב וְאִם מָצְאָה יָדוֹ וְהֶעֱשִׁיר יִתֵּן עֵרֶךְ שָׁלֵם הַקָּצוּב בַּתּוֹרָה:","עָשִׁיר שֶׁהֶעֱרִיךְ וְהֶעֱנִי. אוֹ שֶׁהֶעֱרִיךְ כְּשֶׁהוּא עָנִי וְהֶעֱשִׁיר. הֲרֵי זֶה חַיָּב בְּעֵרֶךְ עָשִׁיר. אֲבָל אִם הֶעֱרִיךְ כְּשֶׁהוּא עָנִי וְהֶעֱשִׁיר וְחָזַר וְהֶעֱנִי נוֹתֵן עֵרֶךְ עָנִי:","עָשִׁיר שֶׁאָמַר עֶרְכִּי עָלַי אוֹ עֵרֶךְ פְּלוֹנִי וְשָׁמַע הֶעָנִי וְאָמַר מַה שֶּׁאָמַר זֶה עָלַי. הֲרֵי הֶעָנִי חַיָּב בְּעֵרֶךְ עָשִׁיר שֶׁהוּא עֵרֶךְ שָׁלֵם. אֲבָל עָנִי שֶׁהֶעֱרִיךְ אֶת הֶעָשִׁיר וְאָמַר עֵרֶךְ זֶה עָלַי אֵינוֹ חַיָּב אֶלָּא כְּעֵרֶךְ עָנִי שֶׁהוּא כְּפִי אֲשֶׁר תַּשִּׂיג יָדוֹ:","מַה בֵּין הַחַיָּב בְּעֵרֶךְ עָנִי לְהַחַיָּב בְּעֵרֶךְ עָשִׁיר שֶׁהוּא הָעֵרֶךְ הַקָּצוּב כֻּלּוֹ. שֶׁהַחַיָּב בְּעֵרֶךְ עָנִי שֶׁלָּקְחוּ מִמֶּנּוּ כָּל מַה שֶּׁיָּדוֹ מַשֶּׂגֶת אֲפִלּוּ סֶלַע אֶחָד וְאַחַר כָּךְ הֶעֱשִׁיר אֵינוֹ חַיָּב לְשַׁלֵּם. וְאִם הָיָה חַיָּב בְּעֵרֶךְ עָשִׁיר יִשָּׁאֵר שְׁאָר הָעֵרֶךְ חוֹב עָלָיו עַד שֶׁיַּעֲשִׁיר וְיַשְׁלִים הָעֵרֶךְ שֶׁעָלָיו:","הַמְפָרֵשׁ אֶת הָעֵרֶךְ וְאָמַר עֶרְכִּי עָלַי חֲמִשִּׁים סְלָעִים. אוֹ עֵרֶךְ פְּלוֹנִי עָלַי שְׁלֹשִׁים סְלָעִים. אֵינוֹ נִדּוֹן בְּהֶשֵּׂג יָד. אֶלָּא לוֹקְחִין כָּל הַנִּמְצָא בְּיָדוֹ וְהַשְּׁאָר עָלָיו חוֹב עַד שֶׁיַּעֲשִׁיר וְיִתֵּן:","וְכֵן הָאוֹמֵר דָּמַי עָלַי אוֹ דְּמֵי פְּלוֹנִי עָלַי אֵינוֹ נִדּוֹן בְּהֶשֵּׂג יָד. שֶׁחַיָּבֵי דָּמִים הֲרֵי פֵּרְשׁוּ נִדְרָן וַהֲרֵי הֵן כְּמִי שֶׁאָמַר מָנֶה עָלַי הֶקְדֵּשׁ שֶׁהוּא חַיָּב לִתֵּן מָנֶה גָּמוּר:","הָאוֹמֵר הֲרֵי עָלַי עֵרֶךְ סְתָם וְלֹא פֵּרֵשׁ אֵינוֹ כִּמְפָרֵשׁ שְׁלֹשֶׁת שְׁקָלִים אֶלָּא נִדּוֹן בְּהֶשֵּׂג יָד כִּשְׁאָר הַמַּעֲרִיכִין:","הָאוֹמֵר עֶרְכִּי עָלַי וְחָזַר וְאָמַר עֶרְכִּי עָלַי וְהָיוּ בְּיָדוֹ עֶשֶׂר סְלָעִים וְנָתַן תֵּשַׁע לַשְּׁנִיָּה וְסֶלַע לָרִאשׁוֹנָה יָצָא יְדֵי שְׁתֵּיהֶן. שֶׁהָעֲרָכִין לָאו כְּחוֹבוֹת הֵן. שֶׁאַף עַל פִּי שֶׁכָּל מַה שֶּׁבְּיָדוֹ מְשֻׁעְבָּד לָרִאשׁוֹנָה. הֶקְדֵּשׁ מְאֻחָר שֶׁגָּבָה גָּבָה. אֲבָל אִם נָתַן תֵּשַׁע לָרִאשׁוֹנָה וְאַחַת לַשְּׁנִיָּה יְדֵי שְׁנִיָּה יָצָא. שֶׁהֲרֵי כְּשֶׁנָּתַן הַסֶּלַע לֹא נִשְׁאַר בְּיָדוֹ כְּלוּם וַהֲרֵי אֵין יָדוֹ מַשֶּׂגֶת. יְדֵי רִאשׁוֹנָה לֹא יָצָא. שֶׁהֲרֵי כָּל מַה שֶּׁהָיָה בְּיָדוֹ מְשֻׁעְבָּד לָרִאשׁוֹנָה כְּשֶׁנָּתַן הַתֵּשַׁע נִשְׁאַר לוֹ סֶלַע וַהֲרֵי לֹא נָתַן כָּל מַה שֶּׁיָּדוֹ מַשֶּׂגֶת. לְפִיכָךְ יִשָּׁאֵר עָלָיו שְׁאָר עֵרֶךְ רִאשׁוֹן עַד שֶׁיַּעֲשִׁיר וְיַשְׁלִים:","הָאוֹמֵר שְׁנֵי עֲרָכַי עָלַי וְלֹא הָיָה בְּיָדוֹ אֶלָּא פָּחוֹת מִכְּדֵי שְׁנֵי עֲרָכִין. הֲרֵי הַדָּבָר סָפֵק אִם נִתְפַּס לִשְׁנֵיהֶן וְנוֹתֵן חֲצִי מַה שֶּׁיֵּשׁ לוֹ לְעֵרֶךְ אֶחָד וַחֲצִי לָעֵרֶךְ הַשֵּׁנִי וְיִפָּטֵר אוֹ יִתֵּן עֵרֶךְ אֶחָד מֵהֶן שָׁלֵם אוֹ כָּל הַנִּמְצָא בְּיָדוֹ בְּאֶחָד מֵהֶן וְיִשָּׁאֵר הָעֵרֶךְ הָאַחֵר עָלָיו חוֹב עַד שֶׁיִּתֵּן אוֹתוֹ בַּעֲנִיּוּת אוֹ בַּעֲשִׁירוּת כְּפִי הֶשֵּׂג יָדוֹ:","הַמַּפְרִישׁ עֶרְכּוֹ אוֹ דָּמָיו וְנִגְנְבוּ אוֹ אָבְדוּ אַף עַל פִּי שֶׁלֹּא אָמַר עָלַי חַיָּב בְּאַחֲרָיוּתָן עַד שֶׁיַּגִּיעוּ לְיַד הַגִּזְבָּר. שֶׁנֶּאֱמַר (ויקרא כז כג) \"וְנָתַן אֶת הָעֶרְכְּךָ בַּיּוֹם הַהוּא קֹדֶשׁ לַה'\" הֲרֵי הֵן חֻלִּין אַף עַל פִּי שֶׁהִפְרִישָׁן עַד שֶׁיַּגִּיעוּ לִידֵי הַגִּזְבָּר:","חַיָּבֵי עֲרָכִין וְדָמִים מְמַשְׁכְּנִין אוֹתָן וְלוֹקְחִין מֵהֶן בַּעַל כָּרְחָן מַה שֶּׁנָּדְרוּ וְאֵינָן חַיָּבִין לְהַחְזִיר לָהֶם הַמַּשְׁכּוֹן בַּיּוֹם אוֹ בַּלַּיְלָה. וּמוֹכְרִין כָּל הַנִּמְצָא לָהֶם מִן הַקַּרְקַע וּמִן הַמִּטַּלְטְלִין מִכְּסוּת וּכְלֵי תַּשְׁמִישׁ הַבַּיִת וַעֲבָדִים וּבְהֵמָה וְנִפְרָעִין מִן הַכּל. וְאֵין מוֹכְרִין לֹא כְּסוּת אִשְׁתּוֹ וְלֹא כְּסוּת בָּנָיו וְלֹא בְּגָדִים שֶׁצְּבָעָן לִשְׁמָן וְלֹא סַנְדָּלִים חֳדָשִׁים שֶׁלְּקָחָן לִשְׁמָן. וְכֵן הַמַּקְדִּישׁ כָּל נְכָסָיו לֹא הִקְדִּישׁ אֶת אֵלּוּ:","וְנוֹתְנִין לוֹ מִכָּל נְכָסָיו לָזֶה שֶׁיֵּשׁ עָלָיו עֲרָכִין אוֹ דָּמִים אוֹ שֶׁהִקְדִּישׁ מָנֶה לְבֶדֶק הַבַּיִת וְאֵין לוֹ. נוֹתְנִין לוֹ תְּפִלִּין שֶׁל רֹאשׁ וְשֶׁל יָד וְסַנְדָּלָיו וְכִסֵּא לֵישֵׁב עָלָיו וּמִטָּה וּמַצָּע הָרְאוּיִין לוֹ לִישֹׁן עֲלֵיהֶם. וְאִם הָיָה עָנִי נוֹתְנִין לוֹ מִטָּה וּמַפָּץ לִישֹׁן עָלָיו. וְנוֹתְנִין לוֹ מְזוֹן שְׁלֹשִׁים יוֹם וּכְסוּת שְׁנֵים עָשָׂר חֹדֶשׁ לוֹ לְבַדּוֹ אֲבָל לֹא לְאִשְׁתּוֹ וּבָנָיו אַף עַל פִּי שֶׁהוּא חַיָּב בִּמְזוֹנוֹתֵיהֶם וּבִכְסוּתָם. וְאֵין נוֹתְנִין לוֹ אֶלָּא כְּסוּת הָרְאוּיָה לוֹ:","הָיוּ עָלָיו כְּלֵי מֶשִׁי וּבְגָדִים מֻזְהָבִין מַעֲבִירִין אוֹתָן מֵעָלָיו וְנוֹתְנִין לוֹ כְּסוּת הָרְאוּיָה לְאִישׁ כְּמוֹתוֹ לְחל אֲבָל לֹא לְשַׁבָּתוֹת וְיָמִים טוֹבִים:","וְאִם הָיָה אֻמָּן נוֹתְנִין לוֹ שְׁנֵי כְּלֵי אֻמְּנוּת מִכָּל מִין וּמִין. כֵּיצַד. אִם הָיָה חָרָשׁ נוֹתְנִין לוֹ שְׁנֵי מַעְצָדִים וּשְׁתֵּי מְגֵרוֹת. הָיוּ לוֹ כֵּלִים מְרֻבִּין מִמִּין אֶחָד וּמוּעָטִין מִמִּין שֵׁנִי אֵין מוֹכְרִין מִן הַמְרֻבֶּה וְלוֹקְחִין לוֹ מִן הַמּוּעָט. אֶלָּא נוֹתְנִין לוֹ שְׁנֵי כֵּלִים מִן הַמְרֻבִּין וְכָל שֶׁיֵּשׁ לוֹ מִן הַמּוֹעָט:","הָיָה חַמָּר אוֹ אִכָּר אֵין נוֹתְנִין לוֹ בְּהֶמְתּוֹ אַף עַל פִּי שֶׁאֵין לוֹ מְזוֹנוֹת אֶלָּא מִמֶּנָּה. הָיָה סַפָּן אֵין נוֹתְנִין לוֹ סְפִינָתוֹ אֶלָּא יִמְכֹּר הַכּל:","הָיוּ בַּנְּכָסִים בְּהֵמָה וַעֲבָדִים וּמַרְגָּלִיּוֹת וְאָמְרוּ הַתַּגָּרִים אִם יִלָּקַח לְעֶבֶד זֶה כְּסוּת בִּשְׁלֹשִׁים מַשְׁבֵּחַ הוּא מֵאָה. וּפָרָה זֹאת אִם יַמְתִּינוּ בָּהּ לָאִטְלִס מַשְׁבַּחַת עֲשָׂרָה. וּמַרְגָּלִית זוֹ אִם מַעֲלִין אוֹתָהּ לְמָקוֹם פְּלוֹנִי תִּשְׁוֶה מָמוֹן רַב וְכָאן אֵינָהּ שָׁוָה אֶלָּא מְעַט. אֵין שׁוֹמְעִין לָהֶן. אֶלָּא כֵּיצַד עוֹשִׂין. מוֹכְרִין הַכּל בִּמְקוֹמוֹ וּבִשְׁעָתוֹ כְּמַה שֶּׁהוּא שֶׁנֶּאֱמַר (ויקרא כז כג) \"וְנָתַן אֶת הָעֶרְכְּךָ בַּיּוֹם הַהוּא קֹדֶשׁ לַה'\" לְרַבּוֹת כָּל דָּבָר שֶׁל הֶקְדֵּשׁ שֶׁאֵין מְפַרְכְּסִין אוֹתוֹ וְאֵין מַמְתִּינִין בּוֹ לַשּׁוּק וְלֹא מוֹלִיכִין אוֹתוֹ מִמָּקוֹם לְמָקוֹם. אֵין לַהֶקְדֵּשׁ אֶלָּא מְקוֹמוֹ וּשְׁעָתוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמִטַּלְטְלִין וַעֲבָדִים. אֲבָל הַקַּרְקָעוֹת מַכְרִיזִין עֲלֵיהֶם שִׁשִּׁים יוֹם רְצוּפִים בַּבֹּקֶר וּבָעֶרֶב וְאַחַר כָּךְ מוֹכְרִין אוֹתָם:"],"Mishneh Torah, Blessings 5":["נָשִׁים וַעֲבָדִים חַיָּבִין בְּבִרְכַּת הַמָּזוֹן. וְסָפֵק יֵשׁ בַּדָּבָר אִם הֵן חַיָּבִין מִן הַתּוֹרָה לְפִי שֶׁאֵין קָבוּעַ לָהּ זְמַן אוֹ אֵינָם חַיָּבִין מִן הַתּוֹרָה. לְפִיכָךְ אֵין מוֹצִיאִין אֶת הַגְּדוֹלִים יְדֵי חוֹבָתָן. אֲבָל הַקְּטַנִּים חַיָּבִין בְּבִרְכַּת הַמָּזוֹן מִדִּבְרֵי סוֹפְרִים כְּדֵי לְחַנְּכָן בְּמִצְוֹת:","שְׁלֹשָׁה שֶׁאָכְלוּ פַּת כְּאֶחָד חַיָּבִין לְבָרֵךְ בִּרְכַּת הַזִּמּוּן קֹדֶם בִּרְכַּת הַמָּזוֹן. וְאֵי זוֹ הִיא בִּרְכַּת הַזִּמּוּן. אִם הָיוּ הָאוֹכְלִים מִשְּׁלֹשָׁה עַד עֲשָׂרָה מְבָרֵךְ אֶחָד מֵהֶם וְאוֹמֵר נְבָרֵךְ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ וְהַכּל עוֹנִין בָּרוּךְ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ וּבְטוּבוֹ חָיִינוּ. וְהוּא חוֹזֵר וּמְבָרֵךְ בָּרוּךְ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ וּבְטוּבוֹ חָיִינוּ:","וְאַחַר כָּךְ אוֹמֵר בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַזָּן אֶת הָעוֹלָם כֻּלּוֹ בְּטוּבוֹ עַד שֶׁגּוֹמֵר אַרְבַּע בְּרָכוֹת. וְהֵן עוֹנִין אָמֵן אַחַר כָּל בְּרָכָה וּבְרָכָה:","הָיוּ הָאוֹכְלִין מֵעֲשָׂרָה וּלְמַעְלָה מְזַמְּנִין בְּשֵׁם. כֵּיצַד. הַמְבָרֵךְ אוֹמֵר נְבָרֵךְ לֵאלֹהֵינוּ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ. וְהֵן עוֹנִין בָּרוּךְ אֱלֹהֵינוּ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ וּבְטוּבוֹ חָיִינוּ. וְהוּא חוֹזֵר וְאוֹמֵר בָּרוּךְ אֱלֹהֵינוּ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ וּבְטוּבוֹ חָיִינוּ. וּמַתְחִיל בִּרְכַּת הַמָּזוֹן:","הַסּוֹעֵד בְּבֵית חֲתָנִים מִשֶּׁיַּתְחִילוּ לְהִתְעַסֵּק בְּצָרְכֵי סְעֻדַּת נִשּׂוּאִין וְלַהֲכִינָהּ עַד שְׁלֹשִׁים יוֹם אַחַר הַנִּשּׂוּאִין מְבָרֵךְ נְבָרֵךְ שֶׁהַשִּׂמְחָה בִּמְעוֹנוֹ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ. וְהֵם עוֹנִים בָּרוּךְ שֶׁהַשִּׂמְחָה בִּמְעוֹנוֹ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ וְכוּ׳‎. וְאִם הָיוּ עֲשָׂרָה מְבָרֵךְ נְבָרֵךְ לֵאלֹהֵינוּ שֶׁהַשִּׂמְחָה בִּמְעוֹנוֹ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ. וְהֵם עוֹנִין בָּרוּךְ אֱלֹהֵינוּ שֶׁהַשִּׂמְחָה וְכוּ׳‎. וְכֵן סְעֻדָּה שֶׁעוֹשִׂין אוֹתָהּ אַחַר הַנִּשּׂוּאִין מֵחֲמַת הַנִּשּׂוּאִין עַד שְׁנֵים עָשָׂר חֹדֶשׁ מְבָרֵךְ שֶׁהַשִּׂמְחָה בִּמְעוֹנוֹ:","הַכּל חַיָּבִין בְּבִרְכַּת הַזִּמּוּן כְּדֶרֶךְ שֶׁחַיָּבִין בְּבִרְכַּת הַמָּזוֹן. אֲפִלּוּ כֹּהֲנִים שֶׁאָכְלוּ קָדְשֵׁי הַקָּדָשִׁים בָּעֲזָרָה. וְכֵן כֹּהֲנִים וְיִשְׂרְאֵלִים שֶׁאָכְלוּ כְּאֶחָד וְאָכְלוּ הַכֹּהֲנִים תְּרוּמָה וְיִשְׂרָאֵל חֻלִּין חַיָּבִין בְּזִמּוּן כְּחִיּוּבָן בְּבִרְכַּת הַמָּזוֹן:","נָשִׁים וַעֲבָדִים וּקְטַנִּים אֵין מְזַמְּנִין עֲלֵיהֶן אֲבָל מְזַמְּנִין לְעַצְמָן. וְלֹא תְּהֵא חֲבוּרָה שֶׁל נָשִׁים וַעֲבָדִים וּקְטַנִּים מִפְּנֵי הַפְּרִיצוּת. אֲבָל נָשִׁים מְזַמְּנוֹת לְעַצְמָן אוֹ עֲבָדִים לְעַצְמָן וּבִלְבַד שֶׁלֹּא יְזַמְּנוּ בְּשֵׁם. אַנְדְּרוֹגִינוּס מְזַמֵּן לְמִינוֹ וְאֵינוֹ מְזַמֵּן לֹא לְנָשִׁים וְלֹא לַאֲנָשִׁים מִפְּנֵי שֶׁהוּא סָפֵק. וְהַטֻּמְטוּם אֵינוֹ מְזַמֵּן כְּלָל. קָטָן הַיּוֹדֵעַ לְמִי מְבָרְכִין מְזַמְּנִין עָלָיו וְאַף עַל פִּי שֶׁהוּא כְּבֶן שֶׁבַע אוֹ כְּבֶן שְׁמוֹנֶה. וּמִצְטָרֵף בֵּין לְמִנְיַן שְׁלֹשָׁה בֵּין לְמִנְיַן עֲשָׂרָה לְזַמֵּן עָלָיו. וְהַנָּכְרִי אֵין מְזַמְּנִין עָלָיו:","אֵין מְזַמְּנִין אֶלָּא עַל מִי שֶׁאָכַל כְּזַיִת פַּת וּלְמַעְלָה. שִׁבְעָה שֶׁאָכְלוּ פַּת וּשְׁלֹשָׁה אָכְלוּ עִמָּהֶן יָרָק אוֹ צִיר וְכַיּוֹצֵא בָּהֶן מִצְטָרְפִין לְזַמֵּן בְּשֵׁם. וְהוּא שֶׁיִּהְיֶה הַמְבָרֵךְ מֵאוֹכְלֵי הַפַּת. אֲבָל שִׁשָּׁה שֶׁאָכְלוּ פַּת וְאַרְבָּעָה יָרָק אֵין מִצְטָרְפִין עַד שֶׁיִּהְיוּ אוֹכְלֵי הַפַּת רֹב הַנִּכָּר. בַּמֶּה דְּבָרִים אֲמוּרִים בַּעֲשָׂרָה. אֲבָל בִּשְׁלֹשָׁה צָרִיךְ שֶׁיֹּאכְלוּ כָּל אֶחָד וְאֶחָד מֵהֶן כְּזַיִת פַּת וְאַחַר כָּךְ מְזַמְּנִין:","שְׁנַיִם שֶׁאָכְלוּ וְגָמְרוּ מִלֶּאֱכל וּבָא שְׁלִישִׁי וְאָכַל. אִם יְכוֹלִין לֶאֱכל עִמּוֹ כָּל שֶׁהוּא וַאֲפִלּוּ מִשְּׁאָר אֳכָלִין מִצְטָרֵף עִמָּהֶן. וְחָכָם גָּדוֹל שֶׁבַּמְסֻבִּין הוּא שֶׁמְּבָרֵךְ לְכֻלָּן אַף עַל פִּי שֶׁלֹּא בָּא אֶלָּא בָּאַחֲרוֹנָה:","שְׁלֹשָׁה שֶׁאָכְלוּ כְּאֶחָד אֵינָן רַשָּׁאִין לֵחָלֵק. וְכֵן אַרְבָּעָה וְכֵן חֲמִשָּׁה. וְשִׁשָּׁה יֵשׁ לָהֶם לֵחָלֵק עַד עֲשָׂרָה. מֵעֲשָׂרָה וּלְמַעְלָה אֵינָם רַשָּׁאִים לֵחָלֵק עַד עֶשְׂרִים. שֶׁכָּל זְמַן שֶׁיֵּחָלְקוּ וְתִהְיֶה בִּרְכַּת הַזִּמּוּן לְכָל חֵלֶק וְחֵלֶק כְּזִמּוּן הַכּל יֵשׁ לָהֶם לֵחָלֵק:","שְׁלֹשָׁה בְּנֵי אָדָם שֶׁבָּאוּ מִשָּׁלֹשׁ חֲבוּרוֹת שֶׁל שְׁלֹשָׁה שְׁלֹשָׁה אֵינָן רַשָּׁאִין לֵחָלֵק. וְאִם כְּבָר זִמֵּן כָּל אֶחָד וְאֶחָד מֵהֶן בַּחֲבוּרָה שֶׁלּוֹ רַשָּׁאִין לֵחָלֵק. וְאֵינָן חַיָּבִין בְּזִמּוּן שֶׁכְּבָר זִמְּנוּ עֲלֵיהֶן. שְׁלֹשָׁה שֶׁיָּשְׁבוּ לֶאֱכל פַּת אַף עַל פִּי שֶׁכָּל אֶחָד וְאֶחָד אוֹכֵל מִשֶּׁלּוֹ אֵינָן רַשָּׁאִין לֵחָלֵק:","שְׁתֵּי חֲבוּרוֹת שֶׁהָיוּ אוֹכְלִין בְּבַיִת אֶחָד. בִּזְמַן שֶׁמִּקְצָתָן רוֹאִין אֵלּוּ אֶת אֵלּוּ מִצְטָרְפִין לְזִמּוּן אֶחָד. וְאִם לָאו אֵלּוּ מְזַמְּנִין לְעַצְמָן וְאֵלּוּ מְזַמְּנִין לְעַצְמָן. וְאִם יֵשׁ שַׁמָּשׁ אֶחָד בֵּינֵיהֶם שֶׁהוּא הוֹלֵךְ וּמְשַׁמֵּשׁ מֵחֲבוּרָה זוֹ לַחֲבוּרָה זוֹ מִצְטָרְפִין לְזִמּוּן אֶחָד אַף עַל פִּי שֶׁאֵין מִקְצָת אֵלּוּ רוֹאִין אֶת אֵלּוּ. וְהוּא שֶׁיִּשְׁמְעוּ שְׁתֵּיהֶן כָּל דִּבְרֵי הַמְבָרֵךְ בְּבֵאוּר:","שְׁלֹשָׁה שֶׁאָכְלוּ וְיָצָא אֶחָד מֵהֶן לַשּׁוּק קוֹרְאִין לוֹ כְּדֵי שֶׁיְּכַוֵּן לִשְׁמֹעַ מַה שֶּׁהֵן אוֹמְרִים וּמְזַמְּנִין עָלָיו וְהוּא בַּשּׁוּק וְיוֹצֵא יְדֵי חוֹבָתוֹ. וְלִכְשֶׁיַּחֲזֹר לְבֵיתוֹ יַחֲזֹר וִיבָרֵךְ בִּרְכַּת הַמָּזוֹן לְעַצְמוֹ אֲבָל עֲשָׂרָה שֶׁאָכְלוּ וְיָצָא אֶחָד מֵהֶן לַשּׁוּק אֵין מְזַמְּנִין עָלָיו עַד שֶׁיַּחֲזֹר לִמְקוֹמוֹ וְיֵשֵׁב עִמָּהֶן:","שְׁלֹשָׁה שֶׁאָכְלוּ כְּאֶחָד וְקָדַם אֶחָד מֵהֶן וּבֵרֵךְ לְעַצְמוֹ מְזַמְּנִין עָלָיו וְיָצְאוּ הַשְּׁנַיִם יְדֵי חוֹבַת זִמּוּן וְהוּא לֹא יָצָא בְּזִמּוּן זֶה שֶׁאֵין זִמּוּן לְמַפְרֵעַ:","שְׁנַיִם שֶׁאָכְלוּ כְּאֶחָד כָּל אֶחָד וְאֶחָד מְבָרֵךְ לְעַצְמוֹ. וְאִם הָיָה אֶחָד מֵהֶן יוֹדֵעַ וְאֶחָד אֵינוֹ יוֹדֵעַ זֶה שֶׁיּוֹדֵעַ מְבָרֵךְ בְּקוֹל רָם וְהַשֵּׁנִי עוֹנֶה אָמֵן אַחַר כָּל בְּרָכָה וּבְרָכָה וְיוֹצֵא יְדֵי חוֹבָתוֹ. וּבֵן מְבָרֵךְ לְאָבִיו. וְעֶבֶד מְבָרֵךְ לְרַבּוֹ. וְאִשָּׁה מְבָרֶכֶת לְבַעְלָהּ. וְיוֹצְאִין יְדֵי חוֹבָתָן. אֲבָל אָמְרוּ חֲכָמִים תָּבוֹא מְאֵרָה לְמִי שֶׁאִשְׁתּוֹ וּבָנָיו מְבָרְכִין לוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁיָּצְאוּ יְדֵי חוֹבָתָן בִּזְמַן שֶׁאָכְלוּ וְלֹא שָׂבְעוּ שֶׁהֵן חַיָּבִים לְבָרֵךְ מִדִּבְרֵי סוֹפְרִים וּלְפִיכָךְ מוֹצִיאִין אוֹתָן קָטָן אוֹ עֶבֶד אוֹ אִשָּׁה מִידֵי חוֹבָתָן. אֲבָל אִם אָכַל וְשָׂבַע שֶׁהוּא חַיָּב בְּבִרְכַּת הַמָּזוֹן מִן הַתּוֹרָה. בֵּין אִשָּׁה בֵּין קָטָן אוֹ עֶבֶד אֵין מוֹצִיאִין אוֹתָן. שֶׁכָּל הַחַיָּב בְּדָבָר מִן הַתּוֹרָה אֵין מוֹצִיאִין אוֹתָן מִידֵי חוֹבָתָן אֶלָּא הַחַיָּב בְּאוֹתוֹ דָּבָר מִן הַתּוֹרָה כְּמוֹתוֹ:","הַנִּכְנָס אֵצֶל אֲחֵרִים וּמְצָאָן מְבָרְכִין בְּבִרְכַּת הַזִּמּוּן. אִם מָצָא הַמְבָרֵךְ אוֹמֵר נְבָרֵךְ הוּא עוֹנֶה בָּרוּךְ הוּא וּמְבֹרָךְ. וְאִם מָצָא הָאוֹכְלִים עוֹנִין בָּרוּךְ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ הוּא עוֹנֶה אַחֲרֵיהֶן אָמֵן:"],"Mishneh Torah, Borrowing and Deposit 8":["הַמַּפְקִיד אֵצֶל חֲבֵרוֹ בְּהֵמָה אוֹ כֵּלִים וְנִגְנְבוּ אוֹ אָבְדוּ אָמַר הֲרֵינִי מְשַׁלֵּם וְאֵינִי נִשְׁבָּע וְנִמְצָא הַגַּנָּב מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל. טָבַח אוֹ מָכַר מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. לְמִי מְשַׁלֵּם לְמִי שֶׁהָיָה הַפִּקָּדוֹן אֶצְלוֹ שֶׁהֲרֵי אָמַר אֲשַׁלֵּם. חָזְרָה הַבְּהֵמָה עַצְמָהּ חוֹזֶרֶת לִבְעָלֶיהָ הִיא וְגִזּוֹתֶיהָ וּוַלְדוֹתֶיהָ שֶׁאֵין זֶה הַשּׁוֹמֵר קוֹנֶה שֶׁבַח הַבָּא מִגּוּפָהּ אֶלָּא שֶׁבַח הַבָּא מֵאֵלָיו. וּכְבָר בֵּאַרְנוּ שֶׁאֵין הַגַּנָּב מַחְזִיר גִּזּוֹת וּוְלָדוֹת אֶלָּא לִפְנֵי יֵאוּשׁ. נִשְׁבַּע הַשּׁוֹמֵר וְלֹא רָצָה לְשַׁלֵּם וְאַחַר כָּךְ נִמְצָא הַגַּנָּב מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל. טָבַח אוֹ מָכַר מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. לְמִי מְשַׁלֵּם לְבַעַל הַפִּקָּדוֹן. וְכֵן הַשּׂוֹכֵר פָּרָה מֵחֲבֵרוֹ וְנִגְנְבָה וְאָמַר הֲרֵינִי מְשַׁלֵּם וְאֵינִי נִשְׁבָּע וְאַחַר כָּךְ הֻכַּר הַגַּנָּב מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל וְתַשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה לַשּׂוֹכֵר. שֶׁאִלּוּ רָצָה הַשּׂוֹכֵר הָיָה נִשְׁבָּע שֶׁנִּגְנְבָה בְּאֹנֶס וְנִפְטָר:","שׁוֹמֵר חִנָּם שֶׁאָמַר פָּשַׁעְתִּי זָכָה בַּכֶּפֶל שֶׁהֲרֵי חִיֵּב עַצְמוֹ לְשַׁלֵּם וְאִלּוּ רָצָה אָמַר נִגְנְבָה אוֹ אָבְדָה וְהָיָה פָּטוּר. וְכֵן נוֹשֵׂא שָׂכָר וְהַשּׂוֹכֵר שֶׁאָמַר נִגְנְבָה קָנָה הַכֶּפֶל שֶׁהֲרֵי חִיֵּב עַצְמוֹ לְשַׁלֵּם וְאִלּוּ רָצָה אָמַר מֵתָה וְהָיָה נִפְטָר. אֲבָל הַשּׁוֹאֵל אֵינוֹ קוֹנֶה הַכֶּפֶל עַד שֶׁיְּשַׁלֵּם מֵעַצְמוֹ קָדַם וְשִׁלֵּם מֵעַצְמוֹ וְאַחַר כָּךְ הֻכַּר הַגַּנָּב מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה לַשּׁוֹאֵל:","כָּל הַקוֹנֶה הַכֶּפֶל קוֹנֶה הַשֶּׁבַח הַבָּא מֵאֵלָיו. כֵּיצַד. הִפְקִיד אַרְבַּע סְאִין אֵצֶל חֲבֵרוֹ וַהֲרֵי הֵן שָׁוִין סֶלַע וְנִגְנְבוּ אוֹ אָבְדוּ וְאָמַר הֲרֵינִי מְשַׁלֵּם סֶלַע וְאֵינִי נִשְׁבָּע וְאַחַר כָּךְ נִמְצְאוּ וַהֲרֵי הֵן שָׁוִין אַרְבָּעָה סְלָעִים הֲרֵי הֵן שֶׁל שׁוֹמֵר וְאֵינוֹ מְשַׁלֵּם אֶלָּא סֶלַע. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הִטְרִיחָן לַבְּעָלִים בַּדִּין אֲבָל אִם הוֹדָה שֶׁפָּשַׁע וְחִיְּבוּהוּ בֵּית דִּין לִתֵּן וְלֹא נָתַן בִּרְצוֹנוֹ עַד שֶׁכָּפוּהוּ בֵּית דִּין עַל כָּרְחוֹ וְנָטְלוּ מִמֶּנּוּ וְאַחַר כָּךְ הֻכַּר הַגַּנָּב אוֹ נִמְצָא הַפִּקָּדוֹן יַחְזִיר לַבְּעָלִים כְּמוֹת שֶׁהוּא וּמַחְזִירִין לַשּׁוֹמֵר הַדָּמִים שֶׁלָּקְחוּ מִמֶּנּו. וְאִם כֵּלִים אוֹ קַרְקַע גָּבוּ בֵּית דִּין מִמֶּנּוּ בְּשׁוּמָא מַחְזִיר לַשּׁוֹמֵר כֵּלָיו אוֹ שָׂדֵהוּ:","תְּבָעוּהוּ בְּעָלִים לַשּׁוֹמֵר וְנִשְׁבַּע וְאַחַר כָּךְ שִׁלֵּם וְהֻכַּר הַגַּנָּב הוֹאִיל וְשִׁלֵּם בִּרְצוֹנוֹ זָכָה בַּכֶּפֶל אַף עַל פִּי שֶׁהִטְרִיחוֹ בַּתְּחִלָּה לַדִּין עַד שֶׁנִּשְׁבַּע. אָמַר הַשּׁוֹמֵר בַּתְּחִלָּה אֵינִי מְשַׁלֵּם וְחָזַר וְאָמַר הֲרֵינִי מְשַׁלֵּם זָכָה בַּכֶּפֶל:","אָמַר הֲרֵינִי מְשַׁלֵּם וְחָזַר וְאָמַר אֵינִי מְשַׁלֵּם. אוֹ שֶׁאָמַר הֲרֵינִי מְשַׁלֵּם וּמֵת וְאָמְרוּ הַבָּנִים אֵין אָנוּ מְשַׁלְּמִין. אוֹ שֶׁלֹּא הִסְפִּיק לִתְבֹּעַ אֶת הַשּׁוֹמֵר עַד שֶׁמֵּת וְתָבַע הַבָּנִים וְשִׁלְּמוּ בְּנֵי הַשּׁוֹמֵר. אוֹ שֶׁשִּׁלְּמוּ הַבָּנִים לַבָּנִים. אוֹ שֶׁשִּׁלֵּם הַשּׁוֹמֵר מֶחֱצָה. שָׁאַל שְׁתֵּי פָּרוֹת וְשִׁלֵּם אַחַת מֵהֶן. שָׁאַל מֵהַשֻּׁתָּפִין וְשִׁלֵּם לְאֶחָד מֵהֶן. שֻׁתָּפִין שֶׁשָּׁאֲלוּ וְשִׁלֵּם אֶחָד מֵהֶן. שָׁאַל מִן הָאִשָּׁה וְשִׁלֵּם לְבַעֲלָהּ. אִשָּׁה שֶׁשָּׁאֲלָה וְשִׁלֵּם בַּעְלָהּ. כָּל אֵלּוּ סָפֵק וַהֲרֵי הַכֶּפֶל מֻטָּל בְּסָפֵק וְאֵינוֹ תַּחַת יַד אֶחָד מֵהֶן לְפִיכָךְ חוֹלְקִין הַכֶּפֶל אוֹ הַשֶּׁבַח בֵּין בַּעַל הַפִּקָּדוֹן וּבֵין הַשּׁוֹמֵר. וְאִם קָדַם אֶחָד מֵהֶן וְתָפַס הַכּל אֵין מוֹצִיאִין מִיָּדוֹ וַאֲפִלּוּ בְּחוּצָה לָאָרֶץ:","נִגְנַב הַפִּקָּדוֹן בְּאֹנֶס וְאַחַר כָּךְ הֻכַּר הַגַּנָּב אֶחָד שׁוֹמֵר חִנָּם וְאֶחָד שׁוֹמֵר שָׂכָר עוֹשֶׂה דִּין עִם הַגַּנָּב וְאֵינוֹ נִשְׁבָּע. קָדַם וְנִשְׁבָּע וְאַחַר כָּךְ הֻכַּר הַגַּנָּב אִם שׁוֹמֵר חִנָּם הוּא רָצָה עוֹמֵד בִּשְׁבוּעָתוֹ רָצָה עוֹשֶׂה דִּין עִם הַגַּנָּב וְאִם שׁוֹמֵר שָׂכָר הוּא עוֹשֶׂה עִמּוֹ דִּין. נִגְנַב הַפִּקָּדוֹן בְּאֹנֶס וְהֶחֱזִירוֹ הַגַּנָּב לְבֵית הַשּׁוֹמֵר וַהֲרֵי הוּא בְּהֵמָה וּמֵתָה שָׁם בִּפְשִׁיעָה יֵשׁ בַּדָּבָר סָפֵק אִם כָּלְתָה שְׁמִירָתוֹ וְנִפְטַר אוֹ עֲדַיִן לֹא כָּלְתָה שְׁמִירָתוֹ לְפִיכָךְ הַשּׁוֹמֵר פָּטוּר מִלְּשַׁלֵּם. וְאִם תָּפְסוּ הַבְּעָלִים אֵין מוֹצִיאִין מִיָּדָם: סְלִיקוּ לְהוּ הִלְכוֹת שְׁאֵלָה וּפִּקָדוֹן"],"Mishneh Torah, Creditor and Debtor 17":["מַלְוְה שֶׁמֵּת וּבָא היּוֹרֵשׁ לִתְבֹּעַ אֶת הַלּוֶֹה בִּשְׁטָר שֶׁעָלָיו וְאָמַר פָּרַעְתִּי לְאָבִיךָ וְהַיּוֹרֵשׁ אוֹמֵר אֵינִי יוֹדֵעַ אוֹמְרִים לוֹ עֲמֹד וְשַׁלֵּם לוֹ. אָמַר יִשָּׁבַע לִי הֲרֵי זֶה נִשְׁבָּע בִּנְקִיטַת חֵפֶץ שֶׁלֹּא פְּקָדָנוּ אַבָּא עַל יְדֵי אַחֵר וְשֶׁלֹּא אָמַר לָנוּ אַבָּא בְּפִיו וְשֶׁלֹּא מָצִינוּ בֵּין שִׁטְרוֹתָיו שֶׁל אַבָּא שֶׁשְּׁטָר זֶה פָּרוּעַ וְגוֹבֶה:","מֵת הַלּוֶֹה אַחַר שֶׁמֵּת הַמַּלְוֶה וּבָא הַיּוֹרֵשׁ לְהִפָּרַע מִן הַיּוֹרֵשׁ לֹא יִפָּרַע אֶלָּא בִּשְׁבוּעָה וְאוֹמֵר לוֹ תְּחִלָּה יִשָּׁבַע שֶׁלֹּא פְּקָדָנוּ אַבָּא וְשֶׁלֹּא אָמַר לָנוּ אַבָּא וְלֹא מָצִינוּ בֵּין שִׁטְרוֹתָיו שֶׁל אַבָּא שֶׁשְּׁטָר זֶה פָּרוּעַ. וַאֲפִלּוּ הָיָה הַיּוֹרֵשׁ קָטָן הַמֻּטָּל בָּעֲרִיסָה כְּשֶׁמֵּת מוֹרִישׁוֹ הֲרֵי זֶה נִשְׁבָּע וְנוֹטֵל. וְאִם צִוָּה הַמַּלְוֶה בִּשְׁעַת מִיתָתוֹ שֶׁשְּׁטָר זֶה אֵינוֹ פָּרוּעַ יִפָּרַע הַיּוֹרֵשׁ בְּלֹא שְׁבוּעָה אֲפִלּוּ מִן הַיּוֹרֵשׁ:","מֵת הַלּוֶֹה תְּחִלָּה וְאַחַר כָּךְ מֵת הַמַּלְוֶה אֵין יוֹרְשֵׁי מַלְוֶה נוֹטְלִין מִיּוֹרְשֵׁי לוֶֹה כְּלוּם שֶׁבְּשָׁעָה שֶׁמֵּת הַלּוֶֹה נִתְחַיֵּב הַמַּלְוֶה לְהִשָּׁבַע וְאַחַר כָּךְ יִטּל כְּמוֹ שֶׁבֵּאַרְנוּ וּכְבָר מֵת וְאֵין אָדָם מוֹרִישׁ שְׁבוּעָה לְבָנָיו שֶׁאֵינָן יְכוֹלִין לְהִשָּׁבַע שֶׁלֹּא נִפְרַע אֲבִיהֶם כְּלוּם. וְאִם עָבַר הַדַּיָּן וְהִשְׁבִּיעַ יוֹרְשֵׁי מַלְוֶה וְגָבוּ אֶת חוֹבָן אֵין מוֹצִיאִין מִיָּדָם. לְפִיכָךְ שְׁטַר חוֹב שֶׁל יְתוֹמִים הַבָּאִים לְהִפָּרַע מִן הַיְתוֹמִים שֶׁמֵּת אֲבִיהֶן הַלּוֶֹה תְּחִלָּה אֵין קוֹרְעִין אוֹתוֹ וְאֵין מַגְבִּין בּוֹ. אֵין גּוֹבִין בּוֹ שֶׁאֵין אָדָם מוֹרִישׁ שְׁבוּעָה לְבָנָיו כְּמוֹ שֶׁבֵּאַרְנוּ וְאֵין קוֹרְעִין אוֹתוֹ שֶׁמָּא יָבוֹא דַּיָּן שֶׁיָּדוּן וְיוֹצִיא בּוֹ:","אֲפִלּוּ הָיָה שָׁם עָרֵב וּמֵת הַלּוֶֹה תְּחִלָּה לֹא יִפָּרְעוּ יוֹרְשֵׁי הַמַּלְוֶה מִן הֶעָרֵב. שֶׁאִם תֹּאמַר יִפָּרְעוּ מִן הֶעָרֵב הֲרֵי הֶעָרֵב חוֹזֵר וְנִפְרָע מִיּוֹרְשֵׁי לוֶֹה:","אֵין דָּנִין מִדִּין זֶה לְכָל הַדּוֹמֶה לוֹ אֶלָּא הֲרֵי הַפּוֹגֵם אֶת שְׁטָרוֹ וּמֵת אַף עַל פִּי שֶׁאֵינוֹ גּוֹבֶה אֶלָּא בִּשְׁבוּעָה הֲרֵי בָּנָיו נִשְׁבָּעִין שֶׁלֹּא פְּקָדָנוּ אַבָּא וְלֹא צִוָּנוּ אַבָּא וְלֹא מָצִינוּ בֵּין שִׁטְרוֹתָיו שֶׁל אַבָּא שֶׁכָּל הַשְּׁטָר הַזֶּה פָּרוּעַ וְגוֹבִין אֶת שְׁאָר הַשְּׁטָר בֵּין מִן הַמַּלְוֶה בֵּין מִיּוֹרְשָׁיו:","יוֹרֵשׁ שֶׁבָּא לִגְבּוֹת מִן הַיּוֹרֵשׁ וְאָמְרוּ יוֹרְשֵׁי לוֶֹה אָמַר לָנוּ אַבָּא לֹא לָוִיתִי חוֹב זֶה הֲרֵי יוֹרְשֵׁי הַמַּלְוֶה גּוֹבִין שֶׁלֹּא בִּשְׁבוּעָה שֶׁכָּל הָאוֹמֵר לֹא לָוִיתִי כְּאוֹמֵר לֹא פָּרַעְתִּי דָּמִי. וְכֵן מַלְוֶה שֶׁבָּא לְהִפָּרַע מִיּוֹרְשֵׁי לוֶֹה וְאָמְרוּ אָמַר לָנוּ אַבָּא לֹא לָוִיתִי חוֹב זֶה הֲרֵי זֶה גּוֹבֵהוּ בְּלֹא שְׁבוּעָה אֲפִלּוּ הֶאֱמִינוֹ בַּשְּׁטָר כָּל זְמַן שֶׁאָמַר פָּרַעְתִּי שֶׁכָּל הָאוֹמֵר לֹא לָוִיתִי כְּאוֹמֵר לֹא פָּרַעְתִּי:","יוֹרֵשׁ שֶׁבָּא לְהִפָּרַע מִן הַלּוֶֹה בִּשְׁטָר שֶׁיֵּשׁ בּוֹ נֶאֱמָנוּת לַלּוֶֹה כָּל זְמַן שֶׁיֹּאמַר פָּרַעְתִּי הֲרֵי הַלּוֶֹה נִשְׁבָּע הֶסֵּת שֶׁפָּרַע לִשְׁטָר זֶה וְנִפְטָר אַף עַל פִּי שֶׁלֹּא כָּתַב לוֹ וַהֲרֵי אַתָּה נֶאֱמָן עַל יוֹרְשַׁי שֶׁעִקַּר הַשְּׁטָר עַל תְּנַאי זֶה הָיָה. אִם הִתְנָה עָלָיו שֶׁיְּהֵא נֶאֱמָן בְּלֹא שׁוּם שְׁבוּעָה אֵינוֹ נִשְׁבָּע אֲפִלּוּ לְיוֹרְשֵׁי מַלְוֶה:","יוֹרֵשׁ קָטָן שֶׁהָיָה שְׁטַר חוֹב לְאָבִיו וְיָצָא עָלָיו שׁוֹבֵר אַחַר מִיתַת אָבִיו אֵין קוֹרְעִין אֶת הַשְּׁטָר וְאֵין מַגְבִּין בּוֹ עַד שֶׁיִּגְדְּלוּ הַיְתוֹמִים שֶׁמָּא שׁוֹבֵר זֶה מְזֻיָּף הוּא וּלְפִיכָךְ לֹא הוֹצִיאוֹ הַלּוֶֹה בְּחַיֵּי אָבִיו:","הַמּוֹצִיא שְׁטַר חוֹב עַל חֲבֵרוֹ וְהָיָה כָּתוּב בְּבָבֶל מַגְבֵּהוּ מִמְּעוֹת בָּבֶל. הָיָה כָּתוּב בְּאֶרֶץ יִשְׂרָאֵל מַגְבֵּהוּ מִמְּעוֹת אֶרֶץ יִשְׂרָאֵל. מַה שֶּׁאֵין כֵּן בִּכְתֻבָּה. לֹא הָיָה בַּשְּׁטָר שֵׁם מָקוֹם וְהוֹצִיאוֹ בְּבָבֶל מַגְבֵּהוּ מִמְּעוֹת בָּבֶל. הוֹצִיאוֹ בְּאֶרֶץ יִשְׂרָאֵל מַגְבֵּהוּ מִמְּעוֹת אֶרֶץ יִשְׂרָאֵל. בָּא לִגְבּוֹת מִמְּעוֹת הַמָּקוֹם שֶׁיָּצָא בּוֹ הַשְּׁטָר וְטָעַן הַלּוֶֹה שֶׁהַמָּעוֹת שֶׁאֲנִי חַיָּב לוֹ מִכֶּסֶף שֶׁהוּא פָּחוֹת מִזֶּה הַמַּטְבֵּעַ יִשָּׁבַע הַמַּלְוֶה וְיִטּל. הָיָה בּוֹ כֶּסֶף סְתָם מַה שֶּׁיִּרְצֶה לוֶֹה מַגְבֵּהוּ. מִכָּאן אַתָּה לָמֵד שֶׁשְּׁטָר שֶׁאֵין בּוֹ שֵׁם מָקוֹם שֶׁנִּכְתַּב בּוֹ כָּשֵׁר לְכָל דָּבָר. וְהוּא הַדִּין לִשְׁטָר שֶׁאֵין בּוֹ זְמַן כְּלָל שֶׁהוּא כָּשֵׁר אַף עַל פִּי שֶׁעֵדוּת זוֹ אִי אַתָּה יָכוֹל לַהֲזִמָּהּ שֶׁאֵין מְדַקְדְּקִין בְּדִינֵי מָמוֹנוֹת בִּדְרִישָׁה וַחֲקִירָה כְּמוֹ שֶׁיִּתְבָּאֵר כְּדֵי שֶׁלֹּא תִּנְעל דֶּלֶת בִּפְנֵי לוֹוִין. וּלְפִיכָךְ שִׁטְרֵי חוֹב הַמְאֻחָרִין כְּשֵׁרִין אַף עַל פִּי שֶׁאֵין אַתָּה יָכוֹל לַהֲזִמָּן כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:"],"Mishneh Torah, Creditor and Debtor 3":["אַלְמָנָה בֵּין שֶׁהִיא עֲנִיָּה בֵּין שֶׁהִיא עֲשִׁירָה אֵין מְמַשְׁכְּנִין אוֹתָהּ לֹא בִּשְׁעַת הַלְוָאָה וְלֹא שֶׁלֹּא בִּשְׁעַת הַלְוָאָה וְלֹא עַל פִּי בֵּית דִּין שֶׁנֶּאֱמַר (דברים כד יז) \"וְלֹא תַחֲבל בֶּגֶד אַלְמָנָה\". וְאִם חָבַל מַחֲזִירִין מִמֶּנּוּ בְּעַל כָּרְחוֹ. וְאִם תּוֹדֶה לוֹ תְּשַׁלֵּם וְאִם תִּכְפֹּר תִּשָּׁבַע. אָבַד הַמַּשְׁכּוֹן אוֹ נִשְׂרַף קֹדֶם שֶׁיַּחְזִיר לוֹקֶה:","וְכֵן הַמַּלְוֶה אֶת חֲבֵרוֹ בֵּין שֶׁהִלְוָהוּ עַל הַמַּשְׁכּוֹן בֵּין שֶׁמִּשְׁכְּנוֹ אַחַר הַלְוָאָה בְּיָדוֹ אוֹ עַל פִּי בֵּית דִּין לֹא יַחֲבל כֵּלִים שֶׁעוֹשִׂין בָּהֶם אֹכֶל נֶפֶשׁ כְּגוֹן הָרֵחָיִם וְהָעֲרֵבוֹת שֶׁל עֵץ וְיוֹרוֹת שֶׁמְּבַשְּׁלִין בָּהֶם וְסַכִּין שֶׁל שְׁחִיטָה וְכַיּוֹצֵא בָּהֶן שֶׁנֶּאֱמַר (דברים כד ו) \"כִּי נֶפֶשׁ הוּא חֹבֵל\". וְאִם חָבַל מַחְזִיר בְּעַל כָּרְחוֹ וְאִם אָבַד הַמַּשְׁכּוֹן אוֹ נִשְׂרַף קֹדֶם שֶׁיַּחְזִיר לוֹקֶה:","חָבַל כֵּלִים הַרְבֵּה שֶׁל אֹכֶל נֶפֶשׁ כְּגוֹן שֶׁחָבַל עֲרֵבָה וְיוֹרָה וְסַכִּין חַיָּב עַל כָּל כְּלִי וּכְלִי בִּפְנֵי עַצְמוֹ. אֲפִלּוּ שְׁנֵי כֵּלִים שֶׁהֵן עוֹשִׂין מְלָאכָה אַחַת חַיָּב עֲלֵיהֶן מִשּׁוּם שְׁנֵי כֵּלִים וְלוֹקֶה שְׁתַּיִם עַל שְׁנֵיהֶם שֶׁנֶּאֱמַר (דברים כד ו) \"לֹא יַחֲבל רֵחַיִם\" וָרָכֶב לְחַיֵּב עַל הָרֵחַיִם בִּפְנֵי עַצְמוֹ וְעַל הָרֶכֶב בִּפְנֵי עַצְמוֹ. כְּשֵׁם שֶׁהָרֶכֶב וְהָרֵחַיִם מְיֻחָדִין שֶׁהֵן שְׁנֵי כֵּלִים וּמְשַׁמְּשִׁין מְלָאכָה אַחַת וְחַיָּב עַל זֶה בִּפְנֵי עַצְמוֹ וְעַל זֶה בִּפְנֵי עַצְמוֹ כָּךְ כָּל שְׁנֵי כֵּלִים אַף עַל פִּי שֶׁמְּשַׁמְּשִׁין מְלָאכָה אַחַת חַיָּב עַל זֶה בִּפְנֵי עַצְמוֹ וְעַל זֶה בִּפְנֵי עַצְמוֹ. וְכֵן אִם חָבַל צֶמֶד בָּקָר הַחוֹרֵשׁ לוֹקֶה שְׁתַּיִם:","הַמַּלְוֶה אֶת חֲבֵרוֹ [אֶחָד] עָנִי וְאֶחָד עָשִׁיר לֹא יְמַשְׁכְּנֶנּוּ אֶלָּא בְּבֵית דִּין וַאֲפִלּוּ שְׁלִיחַ בֵּית דִּין שֶׁבָּא לְמַשְׁכֵּן לֹא יִכָּנֵס לְבֵיתוֹ וִימַשְׁכְּנֶנּוּ אֶלָּא עוֹמֵד בַּחוּץ וְהַלּוֶֹה נִכְנָס לְבֵיתוֹ וּמוֹצִיא לוֹ הַמַּשְׁכּוֹן שֶׁנֶּאֱמַר (דברים כד יא) \"בַּחוּץ תַּעֲמֹד\". אִם כֵּן מַה בֵּין בַּעַל חוֹב לִשְׁלִיחַ בֵּית דִּין. שֶׁשְּׁלִיחַ בֵּית דִּין יֵשׁ לוֹ לִקַּח הַמַּשְׁכּוֹן מִיַּד הַלּוֶֹה בִּזְרוֹעַ וְנוֹתְנוֹ לַמַּלְוֶה וּבַעַל חוֹב אֵין לוֹ לִקַּח הַמַּשְׁכּוֹן עַד שֶׁיִּתֵּן לוֹ הַלּוֶֹה מִדַּעְתּוֹ. עָבַר בַּעַל חוֹב וְנִכְנַס לְבֵית הַלּוֶֹה וּמִשְׁכְּנוֹ אוֹ שֶׁחָטַף הַמַּשְׁכּוֹן מִיָּדוֹ בִּזְרוֹעַ אֵינוֹ לוֹקֶה שֶׁהֲרֵי נִתַּק לַעֲשֵׂה שֶׁנֶּאֱמַר (דברים כד יג) \"הָשֵׁב תָּשִׁיב לוֹ אֶת הַעֲבוֹט כְּבוֹא הַשֶּׁמֶשׁ\". וְאִם לֹא קִיֵּם עֲשֵׂה שֶׁבָּהּ כְּגוֹן שֶׁאָבַד הַמַּשְׁכּוֹן אוֹ נִשְׂרַף לוֹקֶה. וּמְחַשֵּׁב דְּמֵי הַמַּשְׁכּוֹן וְתוֹבֵעַ הַשְּׁאָר בְּדִין:","אֶחָד הַמְמַשְׁכֵּן אֶת חֲבֵרוֹ בְּבֵית דִּין אוֹ שֶׁמִּשְׁכְּנוֹ בְּיָדוֹ בִּזְרוֹעַ אוֹ מִדַּעַת הַלּוֶֹה אִם אִישׁ עָנִי הוּא וּמִשְׁכְּנוֹ דָּבָר שֶׁהוּא צָרִיךְ לוֹ הֲרֵי זֶה מְצֻוֶּה לְהַחְזִיר לוֹ הָעֲבוֹט בְּעֵת שֶׁהוּא צָרִיךְ לוֹ. מַחְזִיר לוֹ אֶת הַכַּר בַּלַּיְלָה כְּדֵי לִישֹׁן עָלָיו וְאֶת הַמַּחְרֵשָׁה בַּיּוֹם כְּדֵי לַעֲשׂוֹת בָּהּ מְלַאכְתּוֹ שֶׁנֶּאֱמַר (דברים כד יג) \"הָשֵׁב תָּשִׁיב לוֹ אֶת הַעֲבוֹט\". עָבַר וְלֹא הֵשִׁיב לוֹ כְּלִי הַיּוֹם בַּיּוֹם וּכְלִי הַלַּיְלָה בַּלַּיְלָה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כד יב) \"לֹא תִשְׁכַּב בַּעֲבֹטוֹ\" לֹא תִּשְׁכַּב וַעֲבוֹטוֹ אֶצְלְךָ זוֹ כְּסוּת לַיְלָה. וּבְכֵלִים שֶׁהוּא עוֹשֶׂה בָּהֶן מְלַאכְתּוֹ בַּיּוֹם אוֹ לוֹבְשָׁן הוּא אוֹמֵר (שמות כב כה) \"עַד בֹּא הַשֶּׁמֶשׁ תְּשִׁיבֶנּוּ לוֹ\" מְלַמֵּד שֶׁיַּחֲזִירוֹ כָּל הַיּוֹם. אִם כֵּן הוּא שֶׁמַּחְזִיר לוֹ הַמַּשְׁכּוֹן בְּעֵת שֶׁהוּא צָרִיךְ לוֹ וְלוֹקֵחַ אוֹתָהּ בְּעֵת שֶׁאֵינוֹ צָרִיךְ לוֹ מַה יּוֹעִיל הַמַּשְׁכּוֹן. כְּדֵי שֶׁלֹּא יִשָּׁמֵט הַחוֹב בִּשְׁבִיעִית וְלֹא יֵעָשֶׂה מִטַּלְטְלִין אֵצֶל בָּנָיו אֶלָּא יִפָּרַע מִן הַמַּשְׁכּוֹן אַחַר שֶׁמֵּת הַלּוֶֹה. הָא לָמַדְתָּ שֶׁהַמְמַשְׁכֵּן אֶת הֶעָנִי דָּבָר שֶׁהוּא צָרִיךְ לוֹ וְלֹא הֶחֱזִירוֹ לוֹ בִּזְמַנּוֹ עוֹבֵר מִשּׁוּם שְׁלֹשָׁה שֵׁמוֹת מִשּׁוּם (דברים כד י) \"לֹא תָבֹא אֶל בֵּיתוֹ\" וּמִשּׁוּם הָשֵׁב תָּשִׁיב לוֹ אֶת הַעֲבוֹט וּמִשּׁוּם לֹא תִשְׁכַּב בַּעֲבֹטוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמִּשְׁכְּנוֹ שֶׁלֹּא בִּשְׁעַת הַלְוָאָתוֹ. אֲבָל אִם מִשְׁכְּנוֹ בִּשְׁעַת הַלְוָאָתוֹ אֵינוֹ חַיָּב לְהַחְזִיר כְּלָל וְאֵינוֹ עוֹבֵר בְּשֵׁם מִן הַשֵּׁמוֹת הָאֵלּוּ:","שְׁלִיחַ בֵּית דִּין שֶׁבָּא לְמַשְׁכֵּן לֹא יְמַשְׁכֵּן דְּבָרִים שֶׁאִי אֶפְשָׁר לָאָדָם לִתֵּן אוֹתָם מַשְׁכּוֹן כְּגוֹן בֶּגֶד שֶׁעָלָיו וּכְלִי שֶׁאוֹכֵל בּוֹ וְכַיּוֹצֵא בְּאֵלּוּ. וּמַנִּיחַ מִטָּה וּמַצָּע לֶעָשִׁיר וּמִטָּה וּמַפָּץ לֶעָנִי. וְכָל הַנִּמְצָא בְּיָדוֹ חוּץ מֵאֵלּוּ יֵשׁ לוֹ לְמַשְׁכְּנוֹ וְיַחְזִיר לוֹ כְּלִי הַיּוֹם בַּיּוֹם וּכְלִי הַלַּיְלָה בַּלַּיְלָה. הָיוּ לְפָנָיו שְׁנֵי כֵּלִים נוֹטֵל אֶחָד וּמַחֲזִיר אֶחָד. עַד מָתַי הוּא חַיָּב לְהַחְזִיר וְלִקַּח עַד לְעוֹלָם. וְאִם הָיָה הַמַּשְׁכּוֹן מִדְּבָרִים שֶׁאֵינוֹ צָרִיךְ לָהֶם וְאֵין מַנִּיחִין אוֹתָן לַלּוֶֹה הֲרֵי זֶה מַנִּיחוֹ אֶצְלוֹ עַד שְׁלֹשִׁים יוֹם וּמִשְּׁלֹשִׁים יוֹם וְאֵילָךְ מוֹכֵר הַמַּשְׁכּוֹן בְּבֵית דִּין. מֵת הַלּוֶֹה אֵינוֹ מַחְזִיר לְבָנָיו. מֵת הַלּוֶֹה אַחַר שֶׁהֵשִׁיב לוֹ הַמַּשְׁכּוֹן שׁוֹמְטוֹ הַמַּלְוֶה מֵעַל בָּנָיו וְאֵינוֹ מַחְזִיר:","הֶעָרֵב מֻתָּר לְמַשְׁכֵּן בִּזְרוֹעַ וּלְהִכָּנֵס לְבֵיתוֹ וְלִטּל הַמַּשְׁכּוֹן שֶׁנֶּאֱמַר (משלי כ טז) \"לְקַח בִּגְדוֹ כִּי עָרַב זָר\". וְכֵן מִי שֶׁיֵּשׁ לוֹ שָׂכָר אֵצֶל חֲבֵרוֹ בֵּין שְׂכַר מְלַאכְתּוֹ בֵּין שְׂכַר בְּהֶמְתּוֹ וְכֵלָיו בֵּין שְׂכַר בֵּיתוֹ הֲרֵי זֶה מֻתָּר לְמַשְׁכְּנוֹ שֶׁלֹּא עַל פִּי בֵּית דִּין וְנִכְנָס לְבֵיתוֹ וְנוֹטֵל הַמַּשְׁכּוֹן בִּשְׂכָרוֹ. וְאִם זָקַף עָלָיו הַשָּׂכָר בְּמִלְוֶה אָסוּר שֶׁנֶּאֱמַר (דברים כד י) \"כִּי תַשֶּׁה בְרֵעֲךָ מַשַּׁאת מְאוּמָה\" וְגוֹ':","מִי שֶׁהָיָה בְּיָדוֹ מַשְׁכּוֹנוֹ שֶׁל עָנִי אִם הָיָה שְׂכָרוֹ יָתֵר עַל פְּחָתוֹ כְּגוֹן קַרְדֹּם וּמַסַּר [הַגָּדוֹל] וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה מֻתָּר לְהַשְׂכִּירוֹ וּמְנַכֶּה שְׂכָרוֹ תָּמִיד בְּחוֹבוֹ מִפְּנֵי שֶׁזֶּה כְּמֵשִׁיב אֲבֵדָה וְאֵין צָרִיךְ רְשׁוּת בְּעָלִים:"],"Mishneh Torah, Daily Offerings and Additional Offerings 5":["מִצְוַת עֲשֵׂה לְסַדֵּר לֶחֶם הַפָּנִים בְּכָל יוֹם שַׁבָּת עַל הַשֻּׁלְחָן לִפְנֵי ה' בַּהֵיכָל שֶׁנֶּאֱמַר (ויקרא כד ח) \"בְּיוֹם הַשַּׁבָּת בְּיוֹם הַשַּׁבָּת יַעַרְכֶנּוּ\" וְגוֹ':","וְדָבָר בָּרוּר בַּתּוֹרָה שֶׁהוּא שְׁתֵּים עֶשְׂרֵה חַלּוֹת כָּל חַלָּה שְׁנֵי עֶשְׂרוֹנִים. וְעוֹרְכִין אוֹתוֹ שְׁנֵי סְדָרִים. שֵׁשׁ חַלּוֹת בְּכָל סֵדֶר. חַלָּה עַל גַּבֵּי חַלָּה וּבֵין כָּל שְׁתֵּי חַלּוֹת שְׁלֹשָׁה קָנִים שֶׁל זָהָב כְּדֵי שֶׁתִּהְיֶה הָרוּחַ מְנַשֶּׁבֶת בּוֹ. וְסוֹמֵךְ כָּל מַעֲרָכָה בִּשְׁתֵּי קְשָׂווֹת. וְנוֹתְנִין בְּצַד כָּל מַעֲרָכָה כְּלִי שֶׁיֵּשׁ בּוֹ קֹמֶץ לְבוֹנָה שֶׁנֶּאֱמַר (ויקרא כד ז) \"וְנָתַתָּה עַל הַמַּעֲרֶכֶת לְבֹנָה זַכָּה\". וּכְלִי זֶה הוּא הַנִּקְרָא בָּזָךְ. נִמְצְאוּ שְׁנֵי קֻמְצֵי לְבוֹנָה בִּשְׁנֵי הַבְּזִיכִין. וְשׁוּלַיִם הָיוּ לַבְּזִיכִין כְּדֵי שֶׁיַּנִּיחוּם עַל הַשֻּׁלְחָן:","שְׁנֵי הַסְּדָרִים מְעַכְּבִין זֶה אֶת זֶה. וּשְׁנֵי הַבְּזִיכִין מְעַכְּבִין זֶה אֶת זֶה. וְהַסְּדָרִין וְהַבְּזִיכִין מְעַכְּבִין זֶה אֶת זֶה. וְאֵין מְחַנְּכִין אֶת הַשֻּׁלְחָן אֶלָּא בְּלֶחֶם הַפָּנִים בְּשַׁבָּת. מִיּוֹם הַשַּׁבָּת לְיוֹם הַשַּׁבָּת מוֹצִיאִין אֶת הַלֶּחֶם שֶׁהוּא שָׁם עַל הַשֻּׁלְחָן מִשַּׁבָּת שֶׁעָבְרָה וּמְסַדְּרִין לֶחֶם אַחֵר. וְזֶה שֶׁמּוֹצִיאִין הוּא שֶׁחוֹלְקִין שְׁתֵּי הַמִּשְׁמָרוֹת הַנִּכְנֶסֶת וְהַיּוֹצֵאת עִם כֹּהֵן גָּדוֹל וְאוֹכְלִין אוֹתוֹ:","וְכֵיצַד מְסַדְּרִין אֶת הַלֶּחֶם. אַרְבָּעָה כֹּהֲנִים נִכְנָסִים. שְׁנַיִם בְּיָדָן שְׁנֵי סְדָרִין. וּשְׁנַיִם בְּיָדָם שְׁנֵי בְּזִיכִין. וְאַרְבָּעָה מַקְדִּימִין לִפְנֵיהֶם שְׁנַיִם לִטֹּל שְׁנֵי סְדָרִים וּשְׁנַיִם לִטֹּל שְׁנֵי בְּזִיכִין שֶׁהָיוּ שָׁם עַל הַשֻּׁלְחָן. הַנִּכְנָסִין עוֹמְדִין בַּצָּפוֹן וּפְנֵיהֶם לַדָּרוֹם. וְהַיּוֹצְאִין עוֹמְדִים בַּדָּרוֹם וּפְנֵיהֶם לַצָּפוֹן. אֵלּוּ מוֹשְׁכִין וְאֵלּוּ מַנִּיחִין וְטִפְחוֹ שֶׁל זֶה בְּתוֹךְ טִפְחוֹ שֶׁל זֶה שֶׁנֶּאֱמַר (שמות כה ל) \"לְפָנַי תָּמִיד\":","יָצְאוּ וְנָתְנוּ אֶת הַלֶּחֶם שֶׁהוֹצִיאוּ עַל שֻׁלְחַן זָהָב אַחַר שֶׁהָיָה בָּאוּלָם וְהִקְטִירוּ הַבְּזִיכִין. וְאַחַר כָּךְ מְחַלְּקִין הַחַלּוֹת. וְאִם חָל יוֹם הַכִּפּוּרִים לִהְיוֹת בְּשַׁבָּת הַחַלּוֹת מִתְחַלְּקוֹת לָעֶרֶב:","כֵּיצַד מַעֲשֵׂה לֶחֶם הַפָּנִים. מֵבִיא אַרְבַּע וְעֶשְׂרִים סְאִים חִטִּים הָרְאוּיִין לִמְנָחוֹת. וְשָׁפִין אוֹתָם וּבוֹעֲטִין בָּהֶן כִּשְׁאָר חִטֵּי מְנָחוֹת. וְטוֹחֲנִין אוֹתָן וּמְנַפִּין מֵהֶן בְּאַחַת עֶשְׂרֵה נָפָה אַרְבָּעָה וְעֶשְׂרִים עִשָּׂרוֹן סלֶת. וְעוֹשִׂין מֵהֶם שְׁתֵּים עֶשְׂרֵה חַלּוֹת מַצּוֹת. לֹא נִפָּה אוֹתָם בְּאַחַת עֶשְׂרֵה נָפָה אוֹ שֶׁלֹּא הוֹצִיאָן מֵעֶשְׂרִים וְאַרְבַּע סְאִים הוֹאִיל וְנַעֲשׂוּ סלֶת מִכָּל מָקוֹם כְּשֵׁרוֹת. לֹא נֶאֶמְרוּ הַשִּׁעוּרִין הָאֵלּוּ אֶלָּא לְמִצְוָה:","לִישָׁתָן וַעֲרִיכָתָן בַּחוּץ וַאֲפִיָּתָן בִּפְנִים בָּעֲזָרָה כִּשְׁאָר הַמְּנָחוֹת. וְלָשִׁין אוֹתָן אַחַת אַחַת. וְאוֹפִין אוֹתָן שְׁתַּיִם שְׁתַּיִם:","וּשְׁלֹשָׁה דְּפוּסִין שֶׁל זָהָב הָיוּ לָהֶם. אֶחָד שֶׁנּוֹתְנִין בּוֹ הַחַלָּה וְהִיא בָּצֵק. וְהַשֵּׁנִי שֶׁאוֹפִין אוֹתָהּ בּוֹ. וְהַשְּׁלִישִׁי שֶׁנּוֹתְנִין אוֹתָהּ בּוֹ כְּשֶׁרוֹדֶה אוֹתָהּ מִן הַתַּנּוּר כְּדֵי שֶׁלֹּא תִּתְקַלְקֵל:","כָּל חַלָּה מֵהֶן מְרֻבָּעַת שֶׁנֶּאֱמַר (שמות כה ל) \"לֶחֶם הַפָּנִים\" שֶׁיִּהְיוּ לוֹ פָּנִים רַבִּים. אֹרֶךְ כָּל חַלָּה מֵהֶן עֲשָׂרָה טְפָחִים. וְרָחְבָּהּ חֲמִשָּׁה טְפָחִים. וְרוּמָהּ שֶׁבַע אֶצְבָּעוֹת. וְהַשֻּׁלְחָן אָרְכּוֹ שְׁנֵים עָשָׂר טֶפַח וְרָחְבּוֹ שִׁשָּׁה טְפָחִים. נוֹתֵן אֹרֶךְ הַחַלָּה עַל רֹחַב הַשֻּׁלְחָן נִמְצֵאת הַחַלָּה יוֹצֵאת שְׁנֵי טְפָחִים מִכָּאן וּשְׁנֵי טְפָחִים מִכָּאן. וְכוֹפֵל אֶת הַיּוֹצֵא מִכָּאן וּמִכָּאן וְיִשָּׁאֵר בֵּין שְׁנֵי הַקְּצָווֹת רֶוַח בָּאֶמְצַע. וְכֵן מַנִּיחַ חַלָּה עַל גַּבֵּי חַלָּה עַד שֶׁעוֹרֵךְ שֵׁשׁ חַלּוֹת. וְכֵן עוֹשֶׂה בְּצַד הַמַּעֲרָכָה שְׁנִיָּה שֵׁשׁ חַלּוֹת:","אֵין אֲפִיַּת לֶחֶם הַפָּנִים דּוֹחָה אֶת הַשַּׁבָּת וְלֹא אֶת יוֹם טוֹב. אֶלָּא בְּעֶרֶב שַׁבָּת אוֹפִין אוֹתָן וְעוֹרְכִין אוֹתָן לְמָחָר. וְאִם חָלוּ שְׁנֵי יָמִים טוֹבִים שֶׁל רֹאשׁ הַשָּׁנָה לִהְיוֹת בַּחֲמִישִׁי וּבְעֶרֶב שַׁבָּת אוֹפִין אוֹתָן מִיּוֹם רְבִיעִי:","לֹא סִדּוּר הַקָּנִים וְלֹא נְטִילָתָן דּוֹחֶה אֶת הַשַּׁבָּת. אֶלָּא מֵעֶרֶב שַׁבָּת נִכְנָס וְשׁוֹמְטָן וְנוֹתְנָן לְאֹרֶךְ הַשֻּׁלְחָן. וּבְאֶחָד בְּשַׁבָּת נִכְנָס וּמַכְנִיס אֶת הַקָּנִים בֵּין הַחַלּוֹת:","סִדֵּר הַלֶּחֶם בְּשַׁבָּת כְּמִצְוָתוֹ וְלֹא הִנִּיחַ עִמּוֹ בְּזִיכֵי לְבוֹנָה עַד לְמָחָר וּלְשַׁבָּת הַבָּאָה הִקְטִיר הַבְּזִיכִין נִפְסַל הַלֶּחֶם וְאֵינוֹ קָדוֹשׁ. וְכֵן אִם סִדֵּר הַלֶּחֶם וְהַבְּזִיכִין בְּאֶחָד בְּשַׁבָּת וְהִקְטִיר הַבְּזִיכִין לְאַחַר שַׁבָּת הַבָּאָה הַלֶּחֶם אֵינוֹ קָדוֹשׁ וְנִפְסָל. אֲבָל אִם הִקְטִיר הַבְּזִיכִין בְּשַׁבָּת [לֹא] נִפְסַל הַלֶּחֶם:","כֵּיצַד יַעֲשֶׂה בְּלֶחֶם וּבְזִיכִין שֶׁסִּדְּרָן לְאַחַר הַשַּׁבָּת. יַנִּיחֵם שָׁם עַל הַשֻּׁלְחָן עַד שֶׁיַּעֲבֹר עֲלֵיהֶן יוֹם הַשַּׁבָּת וְהֵן מְסֻדָּרִין. וְאַחַר כָּךְ יַקְטִיר הַבְּזִיכִין לְשַׁבָּת הַבָּאָה אַחַר הַשַּׁבָּת שֶׁעָבְרָה עֲלֵיהֶן וְהֵן מְסֻדָּרִין. שֶׁאֲפִלּוּ נִשְׁאַר הַלֶּחֶם עִם הַבְּזִיכִין עַל הַשֻּׁלְחָן כַּמָּה שַׁבָּתוֹת אֵין בְּכָךְ כְּלוּם:","סִדֵּר אֶת הַלֶּחֶם וְאֶת הַבְּזִיכִין בְּשַׁבָּת כְּמִצְוָתָן וְהִקְטִיר אֶת הַבְּזִיכִין לְאַחַר הַשַּׁבָּת בֵּין לְאַחַר שַׁבָּת זוֹ בֵּין לְאַחַר שַׁבָּת אַחֶרֶת הַבָּאָה נִפְסַל הַלֶּחֶם. וַהֲרֵי הוּא כְּקָדָשִׁים שֶׁנִּפְסְלוּ שֶׁחַיָּבִין עֲלֵיהֶן מִשּׁוּם פִּגּוּל וְנוֹתַר וְטָמֵא כְּמוֹ שֶׁיִּתְבָּאֵר:","נִפְרְסָה חַלָּה אַחַת מִן הַלֶּחֶם. אִם עַד שֶׁלֹּא הֵסִיר הַלֶּחֶם מֵעַל הַשֻּׁלְחָן נִפְרְסָה הַלֶּחֶם פָּסוּל וְאֵינוֹ מַקְטִיר עָלָיו אֶת הַבְּזִיכִין. וְאִם אַחַר שֶׁהֵסִיר הַלֶּחֶם נִפְרְסָה הַלֶּחֶם פָּסוּל וּמַקְטִיר עָלָיו אֶת הַבְּזִיכִין:","הִגִּיעַ זְמַן הַלֶּחֶם לַהֲסִירוֹ הֲרֵי זֶה כְּמִי שֶׁהֱסִירוֹ. וְאִם נִפְרַס הַלֶּחֶם מַקְטִיר הַבְּזִיכִין וְאַף עַל פִּי שֶׁלֹּא פֵּרֵק הַמַּעֲרָכָה. נִטְמָא אֶחָד מִן הַסְּדָרִין בֵּין לִפְנֵי הַקְטָרָה בֵּין לְאַחַר הַקְטָרָה אוֹ שֶׁנִּטְמָא אֶחָד מִן הַבְּזִיכִין. הַטָּמֵא בְּטֻמְאָתוֹ וְהַטָּהוֹר בְּטָהֳרָתוֹ:"],"Mishneh Torah, Damages to Property 3":["הַבְּהֵמָה מוּעֶדֶת לֶאֱכל פֵּרוֹת אוֹ יְרָקוֹת וְכַיּוֹצֵא בָּהֶן. לְפִיכָךְ אִם נִכְנְסָה לִרְשׁוּת הַנִּזָּק וְאָכְלָה דְּבָרִים שֶׁדַּרְכָּהּ לְאָכְלָם מְשַׁלֵּם נֵזֶק שָׁלֵם שֶׁנֶּאֱמַר (שמות כב ד) \"וּבִעֵר בִּשְׂדֵה אַחֵר מֵיטַב שָׂדֵהוּ\" וְגוֹ'. וְאִם אֲכָלָתָם בִּרְשׁוּת הָרַבִּים פָּטוּר. וְאִם נֶהֱנֵית מְשַׁלֵּם מַה שֶּׁנֶּהֱנֵית לֹא מַה שֶּׁהִזִּיקָה:","כֵּיצַד. נִכְנְסָה לִרְשׁוּת הַנִּזָּק וְאָכְלָה שֻׁמְשְׁמִין אוֹ לוֹט וְכַיּוֹצֵא בָּהֶם בִּשְׁוֵה דִּינָר מְשַׁלֵּם דִּינָר. וְאִם אֲכָלָתָן בִּרְשׁוּת הָרַבִּים וְנֶהֱנֵית רוֹאִין אוֹתָן כְּאִלּוּ הֵן שְׂעוֹרִים אוֹ עָמִיר וּמְשַׁלֵּם דְּמֵי עָמִיר אוֹ דְּמֵי שְׂעוֹרִים בְּזוֹל:","אָכְלָה אֳכָלִין הָרָעִים לָהּ כְּגוֹן שֶׁאָכְלָה חִטִּין הוֹאִיל וְלֹא נֶהֱנֵית פָּטוּר. אָכְלָה אֳכָלִין שֶׁאֵין דַּרְכָּהּ לְאָכְלָן כְּגוֹן שֶׁאָכְלָה כְּסוּת אוֹ כֵּלִים בֵּין בִּרְשׁוּת הַנִּזָּק בֵּין בִּרְשׁוּת הָרַבִּים מְשַׁלֵּם חֲצִי נֵזֶק שֶׁזֶּה שִׁנּוּי הוּא וְדֶרֶךְ בְּנֵי אָדָם לְהַנִּיחַ כְּלֵיהֶם וּכְסוּתָן בִּרְשׁוּת הָרַבִּים עַד שֶׁיָּנוּחוּ מְעַט:","בְּהֵמָה שֶׁהָיְתָה עוֹמֶדֶת בִּרְשׁוּת הַנִּזָּק וְתָלְשָׁה פֵּרוֹת מֵרְשׁוּת הָרַבִּים וַאֲכָלָתָן בִּרְשׁוּת הַנִּזָּק הֲרֵי הַדָּבָר סָפֵק לְפִיכָךְ אֵינָהּ מְשַׁלֶּמֶת אֶלָּא מַה שֶּׁנֶּהֱנֵית. וְאִם תָּפַשׂ הַנִּזָּק כַּמָּה שֶׁהִזִּיקָה אֵין מוֹצִיאִין מִיָּדוֹ שֶׁהֲרֵי בִּרְשׁוּתוֹ אָכְלָה:","כֶּלֶב שֶׁנִּכְנַס לֶחָצֵר וְנָטַל פַּת אוֹ בָּשָׂר וְהוֹצִיאָן לִרְשׁוּת הָרַבִּים אוֹ לֶחָצֵר אַחֶרֶת וַאֲכָלָם מַה שֶּׁנֶּהֱנָה מְשַׁלֵּם. אֲכָלָם בַּשָּׂדֶה שֶׁל בַּעַל הֶחָצֵר מְשַׁלֵּם נֵזֶק שָׁלֵם כְּאִלּוּ אֲכָלָן בְּתוֹךְ הֶחָצֵר שֶׁהֲרֵי בִּרְשׁוּת הַנִּזָּק אָכַל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בְּהֵמָה שֶׁאָכְלָה אֳכָלִין שֶׁאֵין דַּרְכָּהּ לְאָכְלָן אֲבָל אוֹכַלְתָּן עַל יְדֵי הַדְּחָק. כְּגוֹן פָּרָה שֶׁאָכְלָה שְׂעוֹרִים וַחֲמוֹר שֶׁאָכַל כַּרְשִׁינִים אוֹ דָּגִים וַחֲזִיר שֶׁאָכַל חֲתִיכָה בָּשָׂר וְכֶלֶב שֶׁלִּקֵּק אֶת הַשֶּׁמֶן וְחָתוּל שֶׁאָכַל תְּמָרִים. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ. אִם אֲכָלָהּ בִּרְשׁוּת הַנִּזָּק מְשַׁלֵּם נֵזֶק שָׁלֵם. וּבִרְשׁוּת הָרַבִּים פָּטוּר וְאִם נֶהֱנֵית מְשַׁלֵּם מַה שֶּׁנֶּהֱנֵית:","חַיָּה שֶׁנִּכְנְסָה לִרְשׁוּת הַנִּזָּק וְטָרְפָה וְאָכְלָה בְּהֵמָה אוֹ בָּשָׂר מְשַׁלֵּם נֵזֶק שָׁלֵם שֶׁזֶּהוּ דַּרְכָּהּ. אֲבָל כֶּלֶב שֶׁאָכַל כְּבָשִׂים קְטַנִּים אוֹ חָתוּל שֶׁאָכַל תַּרְנְגוֹלִים גְּדוֹלִים הֲרֵי זֶה שִׁנּוּי וּמְשַׁלֵּם חֲצִי נֵזֶק:","סַל שֶׁיֵּשׁ בּוֹ לֶחֶם וְנִכְנַס חֲמוֹר וְשָׁבַר הַסַּל וְאָכַל הַלֶּחֶם מְשַׁלֵּם עַל הַסַּל וְעַל הַלֶּחֶם נֵזֶק שָׁלֵם שֶׁזֶּה הוּא דַּרְכּוֹ. וְכֵן שְׂעִיר עִזִּים שֶׁרָאָה לֶפֶת וְכַיּוֹצֵא בּוֹ עַל פִּי הֶחָבִית וְנִסְתַּבֵּךְ בֶּחָבִית וְאָכַל אֶת הַלֶּפֶת וְשָׁבַר אֶת הֶחָבִית מְשַׁלֵּם עַל שְׁנֵיהֶם נֵזֶק שָׁלֵם. כְּשֵׁם שֶׁדַּרְכּוֹ לֶאֱכל כָּךְ דַּרְכּוֹ לְהִתָּלוֹת בְּכֵלִים וְלַעֲלוֹת כְּדֵי לֶאֱכל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲבָל אִם נִכְנַס הַחֲמוֹר וְאָכַל אֶת הַלֶּחֶם וְאַחַר כָּךְ שָׁבַר אֶת הַסַּל עַל הַלֶּחֶם מְשַׁלֵּם נֵזֶק שָׁלֵם וְעַל הַסַּל חֲצִי נֵזֶק. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בְּהֵמָה שֶׁאָכְלָה מִתּוֹךְ הָרְחָבָה בֵּין דֶּרֶךְ הֲלִיכָתָהּ בֵּין שֶׁעָמְדָה וְאָכְלָה מְשַׁלֵּם מַה שֶּׁנֶּהֱנֵית וַאֲפִלּוּ חָזְרָה עַל צִדֵּי הָרְחָבָה וְאָכְלָה מֵהֶן. אֲבָל אִם הִנִּיחָה אֶת הָרְחָבָה וְהָלְכָה וְעָמְדָה בְּצִדֵּי הָרְחָבָה וְאָכְלָה מְשַׁלֵּם מַה שֶּׁהִזִּיקָה. אָכְלָה מִפֶּתַח הַחֲנוּת מְשַׁלֵּם מַה שֶּׁנֶּהֱנֵית. מִתּוֹךְ הַחֲנוּת מְשַׁלֵּם מַה שֶּׁהִזִּיקָה:","הָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים וּפָשְׁטָה צַוָּארָהּ וְאָכְלָה מֵעַל גַּבֵּי חֲבֶרְתָּהּ וַאֲפִלּוּ עָמְדָה מְשַׁלֵּם מַה שֶּׁנֶּהֱנֵית שֶׁכֵּן דֶּרֶךְ הַבְּהֵמוֹת לֶאֱכל זוֹ מֵעַל גַּבֵּי זוֹ. וְאִם קָפְצָה וְאָכְלָה עַל גַּבֵּי חֲבֶרְתָּהּ מְשַׁלֵּם מַה שֶּׁהִזִּיקָה שֶׁגַּבֵּי חֲבֶרְתָּהּ כַּחֲצַר הַנִּזָּק הוּא חָשׁוּב:","בְּהֵמָה שֶׁהֻחְלְקָה בְּאֶבֶן אוֹ בְּמֵימֵי רַגְלֶיהָ וְנָפְלָה לְגִנָּה וְנֶחְבְּטָה עַל גַּבֵּי פֵּרוֹת וִירָקוֹת אוֹ שֶׁאָכְלָה מְשַׁלֵּם מַה שֶּׁנֶּהֱנֵית. אֲפִלּוּ הָלְכָה מֵעֲרוּגָה לַעֲרוּגָה וַאֲפִלּוּ נִשְׁאֲרָה שָׁם כָּל הַיּוֹם כֻּלּוֹ אֵינוֹ מְשַׁלֵּם אֶלָּא מַה שֶּׁנֶּהֱנֵית. וּמַה הֲנָאָה יֵשׁ לָהּ בַּחֲבִיטָה שֶׁהֲרֵי מָצְאָה מָקוֹם רַךְ וְלֹא נִתְרַסְּקוּ אֵיבָרֶיהָ. אֲבָל אִם יָרְדָה כְּדַרְכָּהּ וְאָכְלָה מְשַׁלֵּם מַה שֶּׁהִזִּיקָה. וַאֲפִלּוּ טִנְּפָה פֵּרוֹת בְּמֵי לֵידָה מְשַׁלֵּם מַה שֶּׁהִזִּיקָה מִפְּנֵי שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה. וְכֵן אִם דְּחָפָתָהּ חֲבֶרְתָּהּ וְנָפְלָה מְשַׁלֵּם מַה שֶּׁהִזִּיקָה מִפְּנֵי שֶׁהָיָה לוֹ לְהַעֲבִירָן אַחַת אַחַת כְּדֵי שֶׁלֹּא יִדְחֲפוּ זוֹ אֶת זוֹ:","הֻחְלְקָה וְנָפְלָה וְיָצָאת וְחָזְרָה לַגִּנָּה אַף עַל פִּי שֶׁחָזְרָה שֶׁלֹּא לְדַעַת הַבְּעָלִים מְשַׁלֵּם מַה שֶּׁהִזִּיקָה מִפְּנֵי שֶׁהָיָה לוֹ לְשָׁמְרָהּ שֶׁלֹּא תַּחְזֹר שֶׁהַדָּבָר יָדוּעַ שֶׁכֵּיוָן שֶׁיָּדְעָה דֶּרֶךְ הַגִּנָּה הֲרֵי הִיא חוֹזֶרֶת מֵאֵלֶיהָ:","הַקַּדָּר שֶׁהִכְנִיס קְדֵרוֹתָיו לַחֲצַר בַּעַל הַבַּיִת שֶׁלֹּא בִּרְשׁוּת וּשְׁבָרָתַן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת פָּטוּר. וְאִם הֻזְּקָה בָּהֶן בַּעַל הַקְּדֵרוֹת חַיָּב. וְאִם הִכְנִיס בִּרְשׁוּת פָּטוּר. וְאִם קִבֵּל עָלָיו בַּעַל הַבַּיִת לִשְׁמֹר אֶת הַקְּדֵרוֹת בַּעַל הַבַּיִת חַיָּב:","וְכֵן אִם הִכְנִיס פֵּרוֹתָיו לַחֲצַר בַּעַל הַבַּיִת שֶׁלֹּא בִּרְשׁוּת וַאֲכָלָתַם בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת פָּטוּר. וְאִם הֻחְלְקָה בָּהֶן וְהֻזְּקָה בַּעַל הַפֵּרוֹת חַיָּב. וְאִם הִכְנִיס בִּרְשׁוּת פָּטוּר. וְאִם קִבֵּל עָלָיו בַּעַל הַבַּיִת לִשְׁמֹר אֶת הַפֵּרוֹת בַּעַל הַבַּיִת חַיָּב. הִכְנִיסָן שֶׁלֹּא בִּרְשׁוּת וַאֲכָלָתַן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת וְהֻזְּקָה בַּאֲכִילָתָן בַּעַל הַפֵּרוֹת פָּטוּר מִפְּנֵי שֶׁהָיָה לָהּ שֶׁלֹּא תֹּאכַל. וְאִם הִכְנִיסָהּ בִּרְשׁוּת וְהִנִּיחוּ בַּעֲלֵי הֶחָצֵר אֶת זֶה שֶׁהִרְשָׁהוּ בֶּחָצֵר לְשָׁמְרוֹ וַאֲכָלָתַן בְּהֶמְתּוֹ שֶׁל בַּעַל הַבַּיִת וְהֻזְּקָה בַּאֲכִילָתָן בַּעַל הַפֵּרוֹת חַיָּב. שֶׁכֵּיוָן שֶׁרָאָה הַבְּהֵמָה אוֹכֶלֶת דְּבָרִים הַמַּזִּיקִין לָהּ וְהִנִּיחָהּ חַיָּב שֶׁהֲרֵי אֵין בַּעֲלֵי הֶחָצֵר מְצוּיִין שָׁם לְהַעֲבִיר הַבְּהֵמָה מֵהֶן. וּמַעֲשֶׂה בְּאִשָּׁה שֶׁנִּכְנְסָה לֶאֱפוֹת בַּתַּנּוּר בְּבֵית שְׁכֵנוֹתֶיהָ וְהִנִּיחוּהָ וְנִתְעַלְּמוּ כְּדֵי שֶׁלֹּא יַבִּיטוּ בָּהּ בְּעֵת לִישָׁתָהּ וַאֲפִיָּתָהּ וּבָא עֵז שֶׁל בַּעַל הַבַּיִת וְאָכַל הַבָּצֵק וּמֵת וְחִיְּבוּהָ חֲכָמִים לְשַׁלֵּם דָּמָיו. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמַּגְדִּישׁ בְּתוֹךְ שְׂדֵה חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת וַאֲכָלָתָן בְּהֶמְתּוֹ שֶׁל בַּעַל הַשָּׂדֶה פָּטוּר. וְאִם הֻחְלְקָה בָּהֶן וְהֻזְּקָה בַּעַל הַפֵּרוֹת חַיָּב. אֲכָלָתָן וְהֻזְּקָה בַּאֲכִילָתָן פָּטוּר. וְאִם הִגְּדִישׁ בִּרְשׁוּת בַּעַל הַשָּׂדֶה חַיָּב אַף עַל פִּי שֶׁלֹּא קִבֵּל עָלָיו לִשְׁמֹר. שֶׁהַשּׁוֹמֵר בָּגֳרָנוֹת כֵּיוָן שֶׁאָמַר לוֹ הַגְדֵּשׁ בְּכָאן כְּמִי שֶׁאָמַר לוֹ הַגְדֵּשׁ וַאֲנִי אֶשְׁמֹר לְךָ הוּא חָשׁוּב:"],"Mishneh Torah, Defilement by Leprosy 14":["צָרַעַת בָּתִּים כִּשְׁנֵי גְּרִיסִין זֶה בְּצַד זֶה. נִמְצָא רֹחב הַנֶּגַע כְּמוֹ מְקוֹם צְמִיחַת שֵׁשׁ שְׂעָרוֹת בַּגּוּף וְאָרְכּוֹ כִּשְׁתֵּים עֶשְׂרֵה שְׂעָרוֹת בְּרִבּוּעַ. וְהַפָּחוֹת מִשִּׁעוּר זֶה בְּבָתִּים טָהוֹר. וְכָל הַשִּׁעוּרִין הֲלָכָה לְמשֶׁה מִסִּינַי:","שְׁלֹשָׁה סִימָנֵי טֻמְאָה יֵשׁ בְּבָתִּים. מַרְאֶה יְרַקְרַק וַאֲדַמְדַּם וְהַפִּשְׂיוֹן. וְכֻלָּן מְפֹרָשִׁין בַּתּוֹרָה. וּשְׁנֵי הַמַּרְאוֹת מִצְטָרְפִין זֶה עִם זֶה. וּפִשְׂיוֹן הַסָּמוּךְ כָּל שֶׁהוּא וְהָרָחוֹק כִּגְרִיס. אֲבָל הַחוֹזֵר אַחַר הִטּוֹחַ כִּשְׁנֵי גְּרִיסִין:","אֵין נִגְעֵי בָּתִּים מְטַמְּאִין עַד שֶׁיִּהְיֶה מַרְאֵה הַנֶּגַע שָׁפָל מִן הַקִּיר שֶׁנֶּאֱמַר (ויקרא יד לז) \"שְׁקַעֲרוּרֹת\" שֶׁיִּהְיוּ שׁוֹקְעִין בַּקִּירוֹת. וּבִשְׁנֵי הַמַּרְאוֹת מַסְגִּירִין אוֹ מַחְלִיטִין וּבְפִשְׂיוֹן נוֹתְצִין. וְאִם פָּשָׂה אַחֲרֵי הִטּוֹחַ נוֹתֵץ אֶת כָּל הַבַּיִת כְּמוֹ שֶׁיִּתְבָּאֵר:","כְּשֶׁיֵּרָאֶה נֶגַע בַּבַּיִת אֲפִלּוּ חָכָם שֶׁיּוֹדֵעַ וַדַּאי שֶׁזֶּה נֶגַע לֹא יִגְזֹר וְיֹאמַר נֶגַע נִרְאֶה לִי בַּבַּיִת אֶלָּא אוֹמֵר לַכֹּהֵן (ויקרא יד לה) \"כְּנֶגַע נִרְאֶה לִי בַּבַּיִת\". (ויקרא יד לו) \"וְצִוָּה הַכֹּהֵן וּפִנּוּ אֶת הַבַּיִת\" אֲפִלּוּ חֲבִילֵי עֵצִים וַחֲבִילֵי קָנִים וְאַחַר כָּךְ יָבוֹא הַכֹּהֵן וְיִכָּנֵס וְיִרְאֶה הַנֶּגַע:","בַּיִת אָפֵל אֵין פּוֹתְחִין בּוֹ חַלּוֹנוֹת לִרְאוֹת אֶת נִגְעוֹ אֶלָּא אִם אֵין הַנֶּגַע נִרְאֶה בּוֹ טָהוֹר. וְאַחַר שֶׁיִּרְאֶה הַכֹּהֵן אֶת הַנֶּגַע יֵצֵא וְיַעֲמֹד עַל פֶּתַח הַבַּיִת בְּצַד הַמַּשְׁקוֹף וְיַסְגִּיר אוֹ יַחְלִיט אוֹ יִפְטֹר שֶׁנֶּאֱמַר (ויקרא יד לח) \"וְיָצָא הַכֹּהֵן מִן הַבַּיִת\" (ויקרא יד לח) \"וְהִסְגִּיר אֶת הַבַּיִת\". לֹא שֶׁיַּסְגִּיר וְהוּא בְּתוֹךְ בֵּיתוֹ אוֹ בְּתוֹךְ בַּיִת הַמְנֻגָּע אוֹ תַּחַת הַמַּשְׁקוֹף אֶלָּא בְּצַד פִּתְחוֹ. וְאִם עָמַד תַּחַת הַמַּשְׁקוֹף אוֹ שֶׁהָלַךְ לְבֵיתוֹ וְהִסְגִּיר הֲרֵי זֶה מֻסְגָּר:","אֵין הַבַּיִת מִטַּמֵּא בִּנְגָעִים עַד שֶׁיִּהְיֶה בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אוֹ יֶתֶר וִיהֵא לוֹ אַרְבָּעָה כְּתָלִים וְהוּא בָּנוּי בָּאָרֶץ בַּאֲבָנִים וְעָפָר וְעֵצִים שֶׁנֶּאֱמַר (ויקרא יד מה) \"אֶת אֲבָנָיו וְאֶת עֵצָיו וְאֶת עֲפָרוֹ\". אֲבָל אִם הָיָה בּוֹ פָּחוֹת מֵאַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אוֹ שֶׁהָיָה עָגל אוֹ שֶׁהָיָה בַּעַל שְׁלֹשָׁה כְּתָלִים אוֹ בַּעַל חֲמִשָּׁה אוֹ שֶׁהָיָה בָּנוּי בִּסְפִינָה אוֹ תָּלוּי עַל אַרְבַּע קוֹרוֹת אֵינוֹ מִטַּמֵּא בִּנְגָעִים. הָיָה בָּנוּי עַל אַרְבָּעָה עַמּוּדִים מִטַּמֵּא בִּנְגָעִים:","כַּמָּה אֲבָנִים יִהְיוּ בּוֹ אֵין פָּחוֹת מִשְּׁמוֹנֶה שְׁתֵּי אֲבָנִים בְּכָל כֹּתֶל כְּדֵי שֶׁיִּהְיֶה כָּל כֹּתֶל רָאוּי לְנֶגַע שֶׁאֵין הַבַּיִת מִטַּמֵּא בִּנְגָעִים עַד שֶׁיֵּרָאֶה בּוֹ כִּשְׁנֵי גְּרִיסִין עַל שְׁתֵּי אֲבָנִים שֶׁנֶּאֱמַר (ויקרא יד מ) \"אֶת הָאֲבָנִים אֲשֶׁר בָּהֵן הַנֶּגַע\". וְכַמָּה עֵצִים יִהְיוּ בּוֹ כְּדֵי לִתֵּן תַּחַת הַמַּשְׁקוֹף. וְעָפָר כְּדֵי לָתֵת בֵּין פַּצִּים לַחֲבֵרוֹ. אֲבָל אִם הָיָה בּוֹ פָּחוֹת מִשִּׁעוּרִים אֵלּוּ אֵינוֹ מִטַּמֵּא בִּנְגָעִים:","הַלְּבֵנִים וְהַשַּׁיִשׁ אֵינָן חֲשׁוּבִין כַּאֲבָנִים. בַּיִת שֶׁאֶחָד מִצִּדָּיו מְחֻפֶּה בְּשַׁיִשׁ וְאֶחָד בְּסֶלַע וְאֶחָד בִּלְבֵנִים וְאֶחָד בְּעָפָר אֵינוֹ מִטַּמֵּא בִּנְגָעִים:","בַּיִת שֶׁלֹּא הָיוּ בּוֹ אֲבָנִים וְעֵצִים כַּשִּׁעוּר וְנִרְאָה בּוֹ נֶגַע וְאַחַר כָּךְ הֵבִיא לוֹ אֲבָנִים וְעֵצִים וְעָפָר טָהוֹר:","בַּיִת שֶׁסִּכְּכוֹ בִּזְרָעִים בִּטְּלָן הוֹאִיל וּמְשַׁמְּשִׁין תַּשְׁמִישׁ עֵץ הֲרֵי הֵן כְּעֵץ. וְאִם נִטְמָא הַבַּיִת נִטְמְאוּ עִמּוֹ טֻמְאָה חֲמוּרָה כְּמוֹ שֶׁיִּתְבָּאֵר:","יְרוּשָׁלַיִם וְחוּצָה לָאָרֶץ אֵין מִטַּמְּאִין בִּנְגָעִים שֶׁנֶּאֱמַר (ויקרא יד לד) \"בְּבֵית אֶרֶץ אֲחֻזַּתְכֶם\" וִירוּשָׁלַיִם לֹא נִתְחַלְּקָה לִשְׁבָטִים. וּבָתֵּי הָעַכּוּ\"ם שֶׁבְּאֶרֶץ יִשְׂרָאֵל אֵין מִטַּמְּאִין בִּנְגָעִים:","הַלּוֹקֵחַ בָּתִּים מִן הָעַכּוּ\"ם יֵרָאֶה בַּתְּחִלָּה:","בַּיִת שֶׁצִּדּוֹ אֶחָד עַכּוּ\"ם וְצִדּוֹ אֶחָד יִשְׂרָאֵל צִדּוֹ אֶחָד בָּאָרֶץ וְצִדּוֹ אֶחָד בְּחוּצָה לָאָרֶץ אֵינוֹ מִטַּמֵּא בִּנְגָעִים. וּשְׁאָר כָּל הַבָּתִּים שֶׁבְּאֶרֶץ יִשְׂרָאֵל מִטַּמְּאִין בִּנְגָעִים בֵּין צְבוּעִים בִּידֵי אָדָם בֵּין צְבוּעִים בִּידֵי שָׁמַיִם:","בֵּית הָאִשָּׁה בֵּית הַשֻּׁתָּפִין בֵּית הַכְּנֶסֶת אוֹ בֵּית הַמִּדְרָשׁ שֶׁיֵּשׁ בָּהֶן דִּירָה לְחַזָּנִין אוֹ לְתַלְמִידִים מִטַּמְּאִין בִּנְגָעִים:","קִירוֹת הָאֵבוּס וְקִירוֹת הַמְּחִצָּה שֶׁבַּבַּיִת אֵין מִטַּמְּאִין בִּנְגָעִים:"],"Mishneh Torah, Defilement by a Corpse 10":["אֵיזֶהוּ בֵּית הַפְּרָס זֶה הַמָּקוֹם שֶׁנֶּחְרַשׁ בּוֹ קֶבֶר. שֶׁהֲרֵי נִתְדַּקְדְּקוּ עַצְמוֹת הַמֵּת בְּתוֹךְ הֶעָפָר וְנִתְפָּרְסוּ בְּכָל הַשָּׂדֶה. וְגָזְרוּ טֻמְאָה עַל כָּל הַשָּׂדֶה שֶׁנֶּחְרַשׁ בָּהּ הַקֶּבֶר אֲפִלּוּ חָרַשׁ עַל גַּבֵּי הָאָרוֹן וַאֲפִלּוּ הָיָה מֻשְׁקָע בִּרְבָדִין וּבַאֲבָנִים. וַאֲפִלּוּ הָיָה עַל גַּבֵּי הָאָרוֹן רוּם שְׁתֵּי קוֹמוֹת הוֹאִיל וְחָרַשׁ עַל קֶבֶר הֲרֵי זֶה עוֹשֶׂה בֵּית הַפְּרָס. עַד כַּמָּה הִיא נַעֲשֵׂית בֵּית הַפְּרָס. מֵאָה אַמָּה עַל מֵאָה אַמָּה מִמְּקוֹם הַקֶּבֶר:","כָּל הַמְרֻבָּע שֶׁהוּא בֵּית אַרְבַּעַת סְאִין הֲרֵי הוּא בֵּית הַפְּרָס וַעֲפָרוֹ מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא כְּמוֹ שֶׁבֵּאַרְנוּ וְאֵינוֹ מְטַמֵּא בְּאֹהֶל. וְכֵן הַמַּאֲהִיל עַל בֵּית הַפְּרָס הַזֶּה טָהוֹר:","הִתְחִיל לַחְרשׁ אֶת הַקֶּבֶר וְהָיָה חוֹרְשׁוֹ וְהוֹלֵךְ וְקֹדֶם שֶׁיִּגְמֹר מֵאָה אַמָּה נִעֵר אֶת הַמַּחֲרֵשָׁה אוֹ שֶׁהֵטִיחַ בַּסֶּלַע אוֹ בַּגָּדֵר. עַד שָׁם הוּא עוֹשֶׂה בֵּית הַפְּרָס בִּלְבַד וְהַשְּׁאָר טָהוֹר שֶׁהֲרֵי לֹא הִגִּיעַ אֵלָיו בִּמְשֹׁךְ הַמַּחֲרֵשָׁה. חָרַשׁ כְּמוֹ חֲמִשִּׁים אַמָּה אוֹ יֶתֶר וְחָזַר וְחָרַשׁ עַד שֶׁהִשְׁלִים הַמֵּאָה הַכּל בֵּית הַפְּרָס. הָיָה חוֹרֵשׁ וְהוֹלֵךְ חוּץ לְמֵאָה אַמָּה מִמֵּאָה אַמָּה וְלַחוּץ טָהוֹר שֶׁאֵין עַצְמוֹת קֶבֶר מַגִּיעוֹת לְיֶתֶר מִמֵּאָה:","חֶזְקַת הָעֲצָמוֹת הַמְכֻסּוֹת שֶׁהֵן שֶׁל אָדָם עַד שֶׁיִּוָּדַע שֶׁהֵן שֶׁל בְּהֵמָה וְחֶזְקַת הָעֲצָמוֹת הַמְגֻלּוֹת שֶׁהֵן שֶׁל בְּהֵמָה עַד שֶׁיִּוָּדַע שֶׁהֵן שֶׁל אָדָם. הָיָה שָׁם חָרִיץ מָלֵא עַצְמוֹת אָדָם. אוֹ שֶׁהָיוּ עַצְמוֹת אָדָם צְבוּרוֹת עַל גַּבֵּי קַרְקַע וְחָרַשׁ עֲצָמוֹת אֵלּוּ עִם הַשָּׂדֶה. אוֹ שֶׁחָרַשׁ שָׂדֶה שֶׁאָבַד בָּהּ [אוֹ שֶׁנִּמְצָא בָּהּ] קֶבֶר. הֲרֵי זֶה אֵינוֹ עוֹשֶׂה בֵּית הַפְּרָס שֶׁלֹּא גָּזְרוּ טֻמְאָה אֶלָּא עַל שָׂדֶה שֶׁנֶּחְרַשׁ בָּהּ קֶבֶר וַדַּאי. וְכֵן הַחוֹרֵשׁ אֶת הַמֵּת בְּשָׂדֶה אֵינוֹ עוֹשֶׂה בֵּית הַפְּרָס שֶׁכָּל אֵלּוּ דָּבָר שֶׁאֵינוֹ מָצוּי הוּא וְלֹא גָּזְרוּ אֶלָּא בְּקֶבֶר שֶׁנֶּחְרַשׁ שֶׁהוּא דָּבָר הַמָּצוּי:","הַחוֹרֵשׁ אֶת הַקֶּבֶר בְּשָׂדֶה שֶׁאֵינָהּ שֶׁלּוֹ אֵינוֹ עוֹשֶׂה בֵּית הַפְּרָס שֶׁאֵין אָדָם אוֹסֵר דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ. אֲפִלּוּ שֻׁתָּף אוֹ אָרִיס אוֹ אַפּוֹטְרוֹפּוֹס אֵינוֹ עוֹשֶׂה בֵּית הַפְּרָס. חָרַשׁ קֶבֶר בְּשָׂדֶה שֶׁלּוֹ וְשֶׁל חֲבֵרוֹ כְּאֶחָד. שֶׁלּוֹ עוֹשֶׂה בֵּית הַפְּרָס וְשֶׁל חֲבֵרוֹ אֵינוֹ עוֹשֶׂה בֵּית הַפְּרָס:","עַכּוּ\"ם שֶׁחָרַשׁ קֶבֶר בְּשָׂדֵהוּ אֵינוֹ עוֹשֶׂה בֵּית הַפְּרָס שֶׁאֵין בֵּית פְּרָס לְעַכּוּ\"ם:","שָׂדֶה בֵּית פְּרָס לְמַעְלָה וְשָׂדֶה טְהוֹרָה לְמַטָּה וְשָׁטְפוּ גְּשָׁמִים מֵעֲפַר בֵּית הַפְּרָס לַטְּהוֹרָה. אֲפִלּוּ הָיְתָה אֲדֻמָּה וְהִלְבִּינָה אוֹ לְבָנָה וְהֶאֱדִימָה טְהוֹרָה שֶׁאֵין בֵּית פְּרָס עוֹשֶׂה בֵּית פְּרָס. וְלֹא גָּזְרוּ טֻמְאָה אֶלָּא עַל גּוּשׁ כִּבְרִיָּתוֹ:","בֵּית הַפְּרָס הַזֶּה מֻתָּר לִנְטֹעַ בּוֹ כָּל נֶטַע לְפִי שֶׁהַשָּׁרָשִׁים יוֹרְדִים לְמַטָּה מִשְּׁלֹשָׁה. וּלְמַטָּה מִשְּׁלֹשָׁה בְּבֵית הַפְּרָס טָהוֹר שֶׁהֲרֵי הַקֶּבֶר נִפְרָס עַל פְּנֵי הַשָּׂדֶה. אֲבָל אֵין זוֹרְעִין בְּתוֹכָהּ אֶלָּא זֶרַע הַנִּקְצָר. וְאִם זָרַע וְעָקַר צוֹבֵר אֶת גָּרְנוֹ בְּתוֹכוֹ וְכוֹבֵר אֶת הַתְּבוּאָה בִּשְׁתֵּי כְּבָרוֹת. וְאֶת הַקִּטְנִיּוֹת בִּשְׁלֹשָׁה כְּבָרוֹת. שֶׁמָּא יֵשׁ בָּהֶן עֶצֶם כִּשְׂעוֹרָה. וְשׂוֹרֵף אֶת הַקַּשׁ וְאֶת הָעֵצָה שָׁם גְּזֵרָה שֶׁמָּא יִהְיֶה בָּהֶן עֶצֶם כִּשְׂעוֹרָה. וְאִם תַּתִּיר לוֹ בַּהֲנָיָה מוֹצִיאוֹ וּמוֹכְרוֹ וְנִמְצָא מַרְגִּיל אֶת הַטֻּמְאָה:","שָׂדֶה שֶׁהֻחְזְקָה שֶׁהִיא בֵּית הַפְּרָס. אֲפִלּוּ הִיא בֵּית אַרְבָּעָה כּוֹרִין וַאֲפִלּוּ מְשׁוּכָה מִמְּקוֹם הַטִּיט הָרַךְ שֶׁאֵינוֹ נֶחְרַשׁ וְלֹא נַעֲשָׂה בֵּית הַפְּרָס. וַאֲפִלּוּ שָׂדֶה טְהוֹרָה מַקֶּפֶת אוֹתָהּ מֵאַרְבַּע רוּחוֹתֶיהָ. הֲרֵי הִיא בְּחֶזְקָתָהּ:","מָצָא שָׂדֶה מְצֻיֶּנֶת וְאֵין יוֹדֵעַ מַה טִּיבָהּ. אִם יֵשׁ בָּהּ אִילָן בְּיָדוּעַ שֶׁנֶּחְרַשׁ קֶבֶר בְּתוֹכָהּ. אֵין בָּהּ אִילָן בְּיָדוּעַ שֶׁאָבַד קֶבֶר בְּתוֹכָהּ כְּמוֹ שֶׁבֵּאַרְנוּ. וְהוּא שֶׁיִּהְיֶה בְּאוֹתוֹ מָקוֹם זָקֵן אוֹ תַּלְמִיד חָכָם. שֶׁאֵין כָּל אָדָם בְּקִיאִין בְּכָךְ וְיוֹדְעִין שֶׁמֻּתָּר לִנְטֹעַ בְּזוֹ וְאָסוּר לִנְטֹעַ בְּאַחֶרֶת:","הַמְהַלֵּךְ בְּבֵית הַפְּרָס עַל גַּבֵּי אֲבָנִים שֶׁאֵין מִתְנַדְנְדִין תַּחַת רַגְלֵי אָדָם בְּשָׁעָה שֶׁמְּהַלֵּךְ עֲלֵיהֶן. אוֹ שֶׁנִּכְנַס לָהּ וְהוּא רוֹכֵב עַל גַּבֵּי אָדָם וּבְהֵמָה שֶׁכֹּחָן יָפֶה. הֲרֵי זֶה טָהוֹר. אֲבָל אִם הָלַךְ עַל גַּבֵּי אֲבָנִים שֶׁמִּזְדַּעְזְעִין בִּשְׁעַת הִלּוּךְ. אַף עַל פִּי שֶׁנִּשְׁמַר וְלֹא נִתְנַדְנֵד הֲרֵי זֶה טָמֵא כְּמִי שֶׁהָלַךְ עַל הֶעָפָר עַצְמוֹ. וְכֵן אִם הָלַךְ עַל גַּבֵּי אָדָם שֶׁכֹּחוֹ רַע עַד שֶׁתִּהְיֶינָה אַרְכֻּבּוֹתָיו נוֹקְשׁוֹת זוֹ לְזוֹ וְשׁוֹקָיו מַרְעִידוֹת כְּשֶׁהוּא נוֹשְׂאוֹ. אוֹ עַל גַּבֵּי בְּהֵמָה שֶׁכֹּחָהּ רַע עַד שֶׁתָּטִיל גְּלָלִים בִּשְׁעַת רְכִיבָה. הֲרֵי זֶה טָמֵא וּכְאִלּוּ הָלַךְ בְּרַגְלָיו:","הַמְטַהֵר בֵּית הַפְּרָס צָרִיךְ לְטַהֲרוֹ בְּמַעֲמַד שְׁנֵי תַּלְמִידֵי חֲכָמִים. וְכֵיצַד מְטַהֲרִין אוֹתוֹ. כּוֹנֵס אֶת כָּל הֶעָפָר שֶׁהוּא יָכוֹל לַהֲסִיטוֹ מֵעַל כָּל פְּנֵי הַשָּׂדֶה וְנוֹתְנוֹ לְתוֹךְ כְּבָרָה שֶׁנְּקָבֶיהָ דַּקִּין. וּמְמַחֶה וּמוֹצִיא כָּל עֶצֶם כִּשְׂעוֹרָה הַנִּמְצָא שָׁם. וְיִטְהַר. וְכֵן אִם נָתַן עַל גַּבָּיו שְׁלֹשָׁה טְפָחִים עָפָר מִמָּקוֹם אַחֵר אוֹ שֶׁנָּטַל מֵעַל כָּל פָּנָיו שְׁלֹשָׁה טְפָחִים הֲרֵי זֶה טָהוֹר. נָטַל מֵחֶצְיוֹ אֶחָד שְׁלֹשָׁה טְפָחִים וְנָתַן עַל חֶצְיוֹ הָאַחֵר שְׁלֹשָׁה טְפָחִים הֲרֵי זֶה טָהוֹר. נָטַל מֵעַל פָּנָיו טֶפַח וּמֶחֱצָה וְנָתַן עָלֶיהָ טֶפַח וּמֶחֱצָה עָפָר מִמָּקוֹם אַחֵר. לֹא עֲשֵׂה כְּלוּם. וְכֵן אִם עֲזָקוֹ וּבָדַק בִּשְׁעַת עִזּוּק מִלְּמַטָּה וּמִלְּמַעְלָה לֹא עָשָׂה כְּלוּם. רִצְּפוֹ בַּאֲבָנִים שֶׁאֵינָן מִתְנַדְנְדִין מֵהִלּוּךְ אָדָם הֲרֵי זֶה טָהוֹר:"],"Mishneh Torah, Defilement by a Corpse 21":["מִנַּיִן לְצָמִיד פָּתִיל שֶּׁמַּצִּיל בְּאֹהֶל הַמֵּת שֶׁנֶּאֱמַר (במדבר יט טו) \"וְכל כְּלִי פָתוּחַ אֲשֶׁר אֵין צָמִיד פָּתִיל עָלָיו טָמֵא הוּא\" הָא יֵשׁ צָמִיד פָּתִיל עָלָיו טָהוֹר. וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵין הַכָּתוּב מְדַבֵּר אֶלָּא בִּכְלִי חֶרֶשׂ בִּלְבַד כְּלִי שֶׁאֵינוֹ מִטַּמֵּא אֶלָּא דֶּרֶךְ פִּתְחוֹ. לְפִיכָךְ אִם הָיָה פִּתְחוֹ סָתוּם וּמֻקָּף צָמִיד פָּתִיל הִצִּיל עַל כָּל שֶׁבְּתוֹכוֹ. קַל וָחֹמֶר לְכָל הַכֵּלִים שֶׁאֵין מְקַבְּלִין טֻמְאָה שֶׁיַּצִּילוּ בְּצָמִיד פָּתִיל וְהֵם כְּלֵי גְּלָלִים כְּלֵי אֲבָנִים כְּלֵי אֲדָמָה וּכְלֵי עַצְמוֹת הַדָּג וְעוֹרוֹ וְעַצְמוֹת הָעוֹף וּכְלִי עֵץ הַבָּא בְּמִדָּה וּנְסָרִים שֶׁל עֵץ שֶׁהֵן פְּשׁוּטִין וְאֵינָן כֵּלִים וְגָלְמֵי כְּלֵי מַתֶּכֶת. כָּל אֵלּוּ מַצִּילִין בְּצָמִיד פָּתִיל. אִם הַדְּבָרִים שֶׁבְּתוֹךְ הַכְּלִי הַמֻּקָּף נִצְּלוּ קַל וָחֹמֶר לַבְּלוּעִין וְלַכֵּלִים שֶׁתַּחַת הָאֹהָלִים. מַה בֵּין אֹהָלִים לַכֵּלִים שֶׁמַּצִּילִין בְּצָמִיד פָּתִיל. שֶׁהַכֵּלִים אֵינָן מַצִּילִין אֶלָּא בְּצָמִיד פָּתִיל וְהָאֹהָלִים מַצִּילִין בְּכִסּוּי בִּלְבַד:","מַשְׁפֵּךְ שֶׁכָּפָהוּ מַצִּיל בְּכִסּוּי אַף עַל פִּי שֶׁקְּצָתוֹ נָקוּב נֶקֶב קָטָן הֲרֵי הוּא כְּסָתוּם:","כָּל הַכֵּלִים הַמַּצִּילִין בְּצָמִיד פָּתִיל אִם הָיוּ בָּהֶן טֶפַח עַל טֶפַח עַל רוּם טֶפַח וּכְפָאָן עַל פִּיהֶם עַל הָאָרֶץ אַף עַל פִּי שֶׁלֹּא מֵרֵחַ בְּצָמִיד פָּתִיל מִן הַצְּדָדִין הֲרֵי אֵלּוּ מַצִּילִין כָּל מַה שֶּׁתַּחְתֵּיהֶן עַד הַתְּהוֹם מִפְּנֵי שֶׁהֵן כְּאֹהֶל וְהָאֹהֶל מַצִּיל. אֶלָּא אִם כֵּן הָיָה הַכְּלִי כְּלִי חֶרֶשׂ שֶׁאֵין אָהֳלֵי כְּלִי חֶרֶשׂ מַצִּילִין. כֵּיצַד. חָבִית שֶׁכְּפוּיָה עַל פִּיהָ אַף עַל פִּי שֶׁמֵּרְחָהּ בְּטִיט מִן הַצְּדָדִין כָּל מַה שֶּׁתַּחְתֶּיהָ טָמֵא. שֶׁנֶּאֱמַר (במדבר יט טו) \"צָמִיד פָּתִיל עָלָיו\" וְלֹא צָמִיד פָּתִיל עַל גַּבּוֹ. הִדְבִּיק פִּיהָ לַכֹּתֶל וּמֵרְחָהּ מִן הַצְּדָדִים מַצֶּלֶת עַל כָּל מַה שֶּׁבְּתוֹכָהּ וְעַל כָּל שֶׁכְּנֶגְדָהּ בַּכֹּתֶל. וְאִם לֹא מֵרֵחַ מִן הַצְּדָדִין אֵינָהּ מַצֶּלֶת שֶׁאֵין כְּלִי חֶרֶשׂ מַצִּיל מִשּׁוּם אֹהֶל כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל שְׁאָר כָּל הַכֵּלִים הַמַּצִּילִין בְּצָמִיד פָּתִיל שֶׁהָיוּ פִּיּוֹתֵיהֶן דְּבוּקוֹת בְּדָפְנֵי הַבַּיִת מַצִּילִין בְּלֹא צָמִיד פָּתִיל מִפְּנֵי שֶׁהֵן מַצִּילִין מִשּׁוּם אֹהֶל. לְפִיכָךְ צָרִיךְ שֶׁיִּהְיֶה בְּדֹפֶן הַכְּלִי טֶפַח שֶׁאֵין הַכֵּלִים מַצִּילִין עִם דָּפְנוֹת אֹהָלִים עַד שֶׁיִּהְיֶה לָהֶן דֹּפֶן [טֶפַח]. הָיָה לַכְּלִי דֹּפֶן חֲצִי טֶפַח וְהָיָה יוֹצֵא מִדֹּפֶן הָאֹהֶל שָׂפָה חֲצִי טֶפַח וְהִדְבִּיק זֶה לָזֶה. אַף עַל פִּי שֶׁיֵּשׁ שָׁם חֲלַל טֶפַח אֵינוֹ מַצִּיל עַד שֶׁיִּהְיֶה טֶפַח מִמָּקוֹם אֶחָד:","כְּשֵׁם שֶׁמַּצִּילִין מִבִּפְנִים עִם דָּפְנוֹת הָאֹהֶל כָּךְ מַצִּילִין חוּץ לָאֹהֶל אִם סְמָכָן לָאֹהֶל שֶׁהֲרֵי הָאֹהֶל נַעֲשָׂה כִּסּוּי מִכָּל מָקוֹם. כֵּיצַד. כְּלִי מֵחַם שֶׁיֵּשׁ לוֹ דֹּפֶן טֶפַח שֶׁהִנִּיחוֹ עַל גַּבֵּי יְתֵדוֹת חוּץ לָאֹהֶל וְסָמַךְ פִּיו לְדֹפֶן הָאֹהֶל וְהָיְתָה טֻמְאָה תַּחְתָּיו כֵּלִים שֶׁבְּתוֹכוֹ טְהוֹרִין. וְאִם הָיָה סָמוּךְ לְכֹתֶל חָצֵר אוֹ לְכֹתֶל גִּנָּה אֵינוֹ מַצִּיל לְפִי שֶׁאֵינָן כֹּתֶל אֹהֶל. וּלְפִיכָךְ כֵּלִים שֶׁבְּתוֹךְ הַכְּלִי טְמֵאִים שֶׁהֲרֵי הֶאֱהִילוּ עַל הַטֻּמְאָה:","קוֹרָה שֶׁיֵּשׁ בָּהּ פּוֹתֵחַ טֶפַח וְהִיא נְתוּנָה מִכֹּתֶל לְכֹתֶל וְטֻמְאָה תַּחְתֶּיהָ וּקְדֵרָה תְּלוּיָה מִן הַקּוֹרָה וְהָיְתָה הַקּוֹרָה נוֹגַעַת בְּפִי הַקְּדֵרָה כֻּלָּהּ וּמְכַסָּה אוֹתָהּ כֵּלִים שֶׁבַּקְּדֵרָה טְהוֹרִים שֶׁהֲרֵי הֻצְּלוּ בְּכִסּוּי הָאֹהֶל לָהֶם. וְאִם לֹא הָיָה פִּי הַקְּדֵרָה מְכֻסֶּה בַּקּוֹרָה אֶלָּא בֵּינֵיהֶם רֶוַח. כָּל מַה שֶּׁבַּקְּדֵרָה טָמֵא וְהַקְּדֵרָה עַצְמָהּ טְמֵאָה:","בּוֹר שֶׁבְּתוֹךְ הַבַּיִת וְטֻמְאָה בַּבַּיִת וְכֵלִים בַּבּוֹר אִם הָיָה מְכֻסֶּה בְּנֶסֶר חָלָק אוֹ בִּכְלִי הַמַּצִּיל שֶׁיֵּשׁ לוֹ דֹּפֶן טֶפַח הֲרֵי כָּל מַה שֶּׁבַּבּוֹר טָהוֹר. הָיָה לַבּוֹר בִּנְיָן סָבִיב לְפִיו גָּבוֹהַּ טֶפַח עַל הָאָרֶץ. בֵּין שֶׁכִּסָּהוּ בִּכְלִי הַמַּצִּיל שֶׁיֵּשׁ לוֹ דֹּפֶן בֵּין שֶׁלֹּא הָיְתָה לוֹ דֹּפֶן הֲרֵי זֶה מַצִּיל שֶׁהֲרֵי יֵשׁ לוֹ דֹּפֶן טֶפַח מִמָּקוֹם אַחֵר:","חַדּוּת הַבָּנוּי בְּתוֹךְ הַבַּיִת וּמְנוֹרָה בְּתוֹכוֹ וְהַפֶּרַח שֶׁלָּהּ יוֹצֵא וּמְכַסֶּה פִּי הֶחָדוּת וְנָתַן כְּלִי הַמַּצִּיל בְּאֹהֶל הַמֵּת עַל פִּי הֶחָדוּת וַהֲרֵי הוּא נִשְׁעָן עַל פֶּרַח הַמְּנוֹרָה. רוֹאִין אִם תִּנָּטֵל מְנוֹרָה וְהַכְּלִי הַמַּצִּיל עוֹמֵד הֲרֵי זֶה מַצִּיל עַל כָּל שֶׁבֶּחָדוּת. וְכֵלִים שֶׁבֵּין שְׂפַת הַכְּלִי וּשְׂפַת הֶחָדוּת טְהוֹרִים עַד הַתְּהוֹם. וְאַף הַמְּנוֹרָה טְהוֹרָה. אַף עַל פִּי שֶׁשְּׂפַת הַפֶּרַח נִרְאֶה בֵּין הַכִּסּוּי וְהֶחָדוּת. וְאִם לָאו הַכּל טָמֵא:","הֶחָדוּת הַבָּנוּי בְּתוֹךְ הַבַּיִת וּכְלִי הַמַּצִּיל נָתוּן עַל פִּיו וְהָיְתָה טֻמְאָה בֵּין שְׂפַת הַכְּלִי וּשְׂפַת הֶחָדוּת אוֹ בְּתוֹךְ הֶחָדוּת הַבַּיִת טָמֵא. שֶׁאֵין הָאֹהֶל שֶׁבְּתוֹךְ הַבַּיִת מוֹנֵעַ הַטֻּמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ. הָיְתָה טֻמְאָה בַּבַּיִת כֵּלִים שֶׁבְּכָתְלֵי הֶחָדוּת אִם יֵשׁ בִּמְקוֹמָן טֶפַח עַל טֶפַח עַל רוּם טֶפַח טְהוֹרִים. וְאִם לָאו טְמֵאִים. וְאִם הָיוּ כָּתְלֵי הֶחָדוּת רְחָבִים מִשֶּׁל בַּיִת בֵּין כָּךְ וּבֵין כָּךְ טְהוֹרִים. מִפְּנֵי שֶׁאֵינָן מִכָּתְלֵי הַבַּיִת. וּכְשֵׁם שֶׁמַּצִּיל הֶחָדוּת בְּתוֹכוֹ כָּךְ מַצִּיל בִּכְתָלָיו. כְּבָר בֵּאַרְנוּ שֶׁהַתַּנּוּר הַיָּשָׁן הֲרֵי הוּא כְּכָל הַכֵּלִים שֶׁהֵן מְבִיאִים אֶת הַטֻּמְאָה וְאֵינָן נַעֲשִׂין אֹהָלִים וּמִפְּנֵי זֶה אֵינוֹ מַצִּיל עַל מַה שֶּׁבְּתוֹכוֹ אֶלָּא אִם כֵּן הָיָה מֻקָּף צָמִיד פָּתִיל כִּשְׁאָר כֵּלִים הַמַּצִּילִים. וְכֵן בֵּאַרְנוּ שֶׁהַתַּנּוּר הֶחָדָשׁ אֵינוֹ כְּכֵלִים לְעִנְיָן זֶה אֶלָּא נַעֲשֶׂה אֹהֶל. וּלְפִיכָךְ מַצִּיל עַל מַה שֶּׁבְּתוֹכוֹ בְּכִסּוּי בִּלְבַד בְּלֹא צָמִיד פָּתִיל כְּאֹהָלִים. וְכִסּוּי הַתַּנּוּר הוּא נִקְרָא סְרִידָא:","תַּנּוּר יָשָׁן בְּתוֹךְ הֶחָדָשׁ וּסְרִידָא עַל פִּי הֶחָדָשׁ וַהֲרֵי הַכִּסּוּי נִשְׁעָן עַל פִּי הַתַּנּוּר הַיָּשָׁן רוֹאִין אִם כְּשֶׁיִּנָּטֵל הַיָּשָׁן תִּפּוֹל הַסְּרִידָא לֹא הִצִּיל וְכָל שֶׁבְּתוֹכוֹ טָמֵא. וְאִם לָאו הַכּל טָהוֹר. הָיָה הֶחָדָשׁ בְּתוֹךְ הַיָּשָׁן וְהַסְּרִידָא מֻנַּחַת עַל פִּי הַיָּשָׁן. אִם יֵשׁ בֵּין הֶחָדָשׁ וְהַכִּסּוּי פָּחוֹת מִטֶּפַח כָּל שֶׁבְּתוֹךְ הֶחָדָשׁ טָהוֹר וּכְאִלּוּ הַסְּרִידָא מֻנַּחַת עַל פִּיו:","סְרִידָא שֶׁל חֶרֶס שֶׁיֵּשׁ לָהּ שָׂפָה וְהִיא עוֹדֶפֶת עַל פִּי הַתַּנּוּר וּמֻקֶּפֶת צָמִיד פָּתִיל אֲפִלּוּ הָיְתָה טֻמְאָה תַּחְתֶּיהָ אוֹ עַל גַּבָּהּ הַכּל טָמֵא. אֲבָל כְּנֶגֶד אֲוִירוֹ שֶׁל תַּנּוּר טָהוֹר. הָיְתָה טֻמְאָה כְּנֶגֶד אֲוִירוֹ שֶׁל תַּנּוּר מִכְּנֶגְדּוֹ עַד לָרָקִיעַ טָמֵא וְכָל מַה שֶּׁבְּתוֹכוֹ טָהוֹר:","קְדֵרָה שֶׁכְּפָאָהּ עַל פִּי הֶחָבִית וּמֵרֵחַ דָּפְנוֹתֶיהָ עִם הֶחָבִית מַצֶּלֶת עַל כָּל מַה שֶּׁבְּתוֹכָהּ וְעַל מַה שֶּׁבֵּינָהּ וּבֵין שִׂפְתוֹת הֶחָבִית. הוֹשִׁיבָהּ עַל פִּי הֶחָבִית כְּדַרְכָּהּ וּמֵרֵחַ אֵינָהּ מַצֶּלֶת מִפְּנֵי שֶׁהַקְּדֵרָה מִתְטַמְּאָה מֵאֲוִירָהּ וְאֵין כְּלִי טָמֵא מַצִּיל כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Defilement of Foods 1":["כָּל אֹכֶל הַמְיֻחָד לְמַאֲכַל אָדָם כְּגוֹן לֶחֶם וּבָשָׂר וַעֲנָבִים וְזֵיתִים וְכַיּוֹצֵא בָּהֶן מְקַבֵּל טֻמְאָה וְכָל שֶׁאֵינוֹ מְיֻחָד לְמַאֲכַל אָדָם הֲרֵי זֶה טָהוֹר וְאֵינוֹ מְקַבֵּל טֻמְאָה אֶלָּא אִם כֵּן חִשֵּׁב עָלָיו וְיִחֲדוֹ לְמַאֲכַל אָדָם. וְזֶה וְזֶה אֵינוֹ מְקַבֵּל טֻמְאָה עַד שֶׁיִּבָּלֵל תְּחִלָּה בְּאֶחָד מִשִּׁבְעָה מַשְׁקִין וְזֶהוּ הַנִּקְרָא הֶכְשֵׁר שֶׁנֶּאֱמַר (ויקרא יא לח) \"וְכִי יֻתַּן מַיִם עַל זֶרַע\":","וְאֵלּוּ הֵן הַשִּׁבְעָה מַשְׁקִין שֶׁמַּכְשִׁירִין אֶת הָאֳכָלִין לְטֻמְאָה. הַמַּיִם וְהַטַּל וְהַשֶּׁמֶן וְהַיַּיִן וְהֶחָלָב וְהַדָּם וְהַדְּבַשׁ. וְאֵינָן מַכְשִׁירִין עַד שֶׁיִּפְּלוּ עַל הָאֳכָלִין בִּרְצוֹן הַבְּעָלִים. וְלֹא יִהְיוּ סְרוּחִין שֶׁהַמַּשְׁקֶה הַסָּרוּחַ אֵינוֹ מַכְשִׁיר. וְכֵיוָן שֶׁהֻכְשַׁר הָאֹכֶל אַף עַל פִּי שֶׁיָּבַשׁ וַהֲרֵי הוּא נָגוּב הֲרֵי זֶה מְקַבֵּל טֻמְאָה:","אֹכֶל שֶׁהָיָה בָּלוּל בְּמֵי פֵּרוֹת כְּגוֹן מֵי תּוּתִים וְרִמּוֹנִים אַף עַל פִּי שֶׁהוּא בָּלוּל וְנָגַע בּוֹ הַזָּב אוֹ בְּשַׂר הַמֵּת הֲרֵי הוּא טָהוֹר מִפְּנֵי שֶׁלֹּא הֻכְשַׁר בְּאֶחָד מִשִּׁבְעָה הַמַּשְׁקִין:","אֵין שָׁם מַשְׁקֶה שֶׁמְּקַבֵּל טֻמְאָה אֶלָּא שִׁבְעַת הַמַּשְׁקִין שֶׁמָּנִינוּ בִּלְבַד אֲבָל שְׁאָר מֵי פֵּרוֹת כְּדֶרֶךְ שֶׁאֵין מַכְשִׁירִין כָּךְ אֵין מְקַבְּלִין טֻמְאָה כְּלָל:","זֵיתִים וַעֲנָבִים שֶׁלֹּא הֵבִיאוּ שְׁלִישׁ מַשְׁקִין הַיּוֹצְאִין מֵהֶן אֵינָן מַכְשִׁירִין וְלֹא מְקַבְּלִין טֻמְאָה אֶלָּא הֲרֵי הֵן כִּשְׁאָר מֵי פֵּרוֹת שֶׁהֵן טְהוֹרִין לְעוֹלָם:","אֵלּוּ דְּבָרִים שֶׁאֵינָן מְקַבְּלִין טֻמְאָה אַף עַל פִּי שֶׁבְּנֵי אָדָם אוֹכְלִין אוֹתָן לְפִי שֶׁאֵינָן נֶאֱכָלִין לַהֲנָאַת גּוּפָן אֶלָּא מִפְּנֵי שֶּׁנּוֹתְנִין טַעַם בְּמַאֲכָלוֹת אוֹ מִפְּנֵי הָרֵיחַ אוֹ הַמַּרְאֶה. וְאֵלּוּ הֵן. הַקֹּשְׁט וְהַחָמָס וְרָאשֵׁי בְּשָׂמִים וְהַתִּיאָה וְהַחִלְתִּית וְהַפִּלְפְּלִין וְחַלּוֹת חָרִיעַ. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","הַשֶּׁבֶת סְתָמוֹ לַאֲכִילַת גּוּפוֹ כִּשְׁאָר יַרְקוֹת שָׂדֶה וְאִם חָשַׁב עָלָיו לִקְדֵרָה אֵינוֹ מִתְטַמֵּא טֻמְאַת אֳכָלִין. וְהַשֶׁבֶת מִשֶּׁנָּתְנָה טַעַם לִקְדֵרָה הֲרֵי זוֹ כְּזֶבֶל וְאֵינָהּ מִתְטַמְּאָה טֻמְאַת אֳכָלִין:","הַתְּמָרִים וְהַגְּרוֹגָרוֹת שֶׁנָּתַן לִקְדֵרָה כְּתַבְלִין עֲדַיִן הֵן מִתְטַמְּאִין טֻמְאַת אֳכָלִין עַד שֶׁיִּפָּסְדוּ מִלֶּאֱכל אָדָם:","הַכַּרְשִׁינִים אִם יִחֲדָן לְמַאֲכַל אָדָם מִתְטַמְּאִין טֻמְאַת אֳכָלִין:","הַקּוֹר הֲרֵי הוּא כְּעֵץ לְכָל דָּבָר וְאִם שְׁלָקוֹ וְטִגְּנוֹ מִתְטַמֵּא טֻמְאַת אֳכָלִין:","הַחַרְצַנִּין וְהַזַּגִּין אַף עַל פִּי שֶׁכְּנָסָן לָאֳכָלִין אֵינָן מִתְטַמְּאִין טֻמְאַת אֳכָלִין:","זֵיתִים וַעֲנָבִים הַקָּשִׁים שֶׁנִּפְרָצִין וְיוֹצְאִין מִתַּחַת הַקּוֹרָה בִּשְׁעַת הַדְּרִיכָה אֵינָן מְקַבְּלִין טֻמְאָה. וְעַד כַּמָּה עַד אַרְבָּעָה קַבִּין לְכָל כּוֹר. הָיָה הַנִּפְרָץ יֶתֶר מִזֶּה מְקַבְּלִין טֻמְאָה. וְאִם כְּנָסָן לָאֳכָלִין אַף עַל פִּי שֶׁהֵן פָּחוֹת מֵאַרְבָּעָה קַבִּין מְקַבְּלִין טֻמְאָה:","הַכַּפְנִיוֹת וְהַפַּגִּין וְהַבֹּסֶר וְהַקֶּצַח הֲרֵי הֵן כָּאֳכָלִין וּמְקַבְּלִין טֻמְאָה:","לוּלְבֵי זְרָדִים וְחָרוּבִין וְשֶׁל עֲדָל וַעֲלֵי הַלּוּף הַשּׁוֹטֶה אֵינָן מְקַבְּלוֹת טֻמְאָה עַד שֶׁיִּתְמַתְּקוּ:","הַחַרְדָּל וְהַתֻּרְמְסִין וּשְׁאָר כָּל הַנִּכְבָּשִׁין מִטַּמְּאִין טֻמְאַת אֳכָלִין בֵּין מִשֶּׁהִמְתִּיקוּ בֵּין עַד שֶׁלֹּא הִמְתִּיקוּ:","זֵיתִים שֶׁכְּבָשָׁן בְּעָלִין שֶׁלָּהֶן אֵין הֶעָלִין מְקַבְּלִין טֻמְאָה. שֶׁלֹּא כְּבָשָׁן לָאֳכָלִין אֶלָּא לְמַרְאֶה:","כְּשׁוּת שֶׁל קִשּׁוּת וְהַנֵּץ שֶׁלָּהּ אֵין מְקַבְּלִין טֻמְאָה מִפְּנֵי שֶׁאֵינוֹ אֹכֶל:","דְּבַשׁ בְּכַוַּרְתּוֹ מְטַמֵּא טֻמְאַת אֳכָלִין שֶׁלֹּא בְּמַחְשָׁבָה. רָדָה הַדְּבַשׁ מִשֶּׁיְּרַסֵּק הַחַלּוֹת מִתְטַמֵּא מִשּׁוּם מַשְׁקֶה. דְּבַשׁ הַזָּב מִכַּוַּרְתּוֹ מִתְטַמֵּא טֻמְאַת מַשְׁקִין. חָשַׁב עָלָיו לָאֳכָלִין מִתְטַמֵּא טֻמְאַת אֳכָלִין:","הַשֶּׁמֶן הַקָּרוּשׁ אֵינוֹ אֹכֶל וְלֹא מַשְׁקֶה. חָשַׁב עָלָיו כְּשֶׁהוּא קָרוּשׁ בֵּין לָאֳכָלִין בֵּין לְמַשְׁקִין בָּטְלָה דַּעְתּוֹ. וְכֵן הַדָּם שֶׁקָּרַשׁ אֵינוֹ אֹכֶל וְלֹא מַשְׁקֶה. חָשַׁב עָלָיו לָאֳכָלִין מִתְטַמֵּא טֻמְאַת אֳכָלִין. חָשַׁב עָלָיו לְמַשְׁקִין בָּטְלָה דַּעְתּוֹ:","חָלָב שֶׁקָּרַשׁ לֹא אֹכֶל וְלֹא מַשְׁקֶה. חָשַׁב עָלָיו לָאֳכָלִין מִתְטַמֵּא טֻמְאַת אֳכָלִין. לְמַשְׁקִין בָּטְלָה דַּעְתּוֹ:","דְּבַשׁ תְּמָרִים לֹא אֹכֶל וְלֹא מַשְׁקֶה. חָשַׁב עָלָיו לָאֳכָלִין מִתְטַמֵּא טֻמְאַת אֳכָלִין. לְמַשְׁקִין בָּטְלָה דַּעְתּוֹ. וּשְׁאָר כָּל מֵי פֵּרוֹת כֻּלָּן לֹא אֹכֶל וְלֹא מַשְׁקֶה. חָשַׁב עָלָיו בֵּין לָאֳכָלִין בֵּין לְמַשְׁקִין בָּטְלָה דַּעְתּוֹ:","הַשֶּׁלֶג אֵינוֹ אֹכֶל וְלֹא מַשְׁקֶה. חָשַׁב עָלָיו לָאֳכָלִין בָּטְלָה דַּעְתּוֹ. לְמַשְׁקִין מִתְטַמֵּא טֻמְאַת מַשְׁקִין. נִטְמָא מִקְצָתוֹ לֹא נִטְמָא כֻּלּוֹ. הֶעֱבִירוֹ עַל גַּבֵּי כְּלִי חֶרֶס הַטָּמֵא נִטְמָא כֻּלּוֹ:","הֶחָלָב שֶׁבַּכְּחַל שֶׁחָשַׁב עָלָיו בָּטְלָה דַּעְתּוֹ וַהֲרֵי הוּא טָהוֹר. חָשַׁב עַל הֶחָלָב שֶׁבַּקֵּיבָה הֲרֵי זֶה מִתְטַמֵּא טֻמְאַת אֳכָלִין:","עֲנָבִים שֶׁדְּרָכָן מִשֶּׁיְּהַלֵּךְ בָּהֶן הַדּוֹרֵךְ שְׁתִי וָעֵרֶב מִתְטַמְּאִין מַשְׁקִין. נִשְׁתַּיֵּר בָּהֶן גַּרְגְּרִין שְׁלֵמִים אוֹתָן גַּרְגְּרִין מִתְטַמְּאִין טֻמְאַת אֳכָלִין. וְכֵן הַזֵּיתִים מִשֶּׁיִּטְעֲנוּם מִתְטַמְּאִין טֻמְאַת מַשְׁקִין. נִשְׁתַּיְּרוּ בָּהֶן גַּרְגְּרִין שְׁלֵמִין מִתְטַמְּאִין טֻמְאַת אֳכָלִין:","הָעָרְלָה. וְכִלְאֵי הַכֶּרֶם. וְשׁוֹר הַנִּסְקָל שֶׁנִּשְׁחַט. וְעֶגְלָה עֲרוּפָה בֵּין שֶׁנִּשְׁחֲטָה בֵּין שֶׁנֶּעֶרְפָה. וְצִפֳּרֵי מְצֹרָע. וּפֶטֶר חֲמוֹר. וּבָשָׂר בְּחָלָב. וּבְשַׂר פָּרָה אֲדֻמָּה. וְהַפִּגּוּל. וְהַנּוֹתָר. אַף עַל פִּי שֶׁכָּל אֵלּוּ אֲסוּרִין בַּהֲנָאָה כֻּלָּן מִתְטַמְּאִין טֻמְאַת אֳכָלִין:"],"Mishneh Torah, Defilement of Foods 6":["הָאֱגוֹזִין וְהַשְּׁקֵדִים שֶׁנִּסְדְּקָה קְלִפָּתָן עֲדַיִן הוּא חִבּוּר לָאֹכֶל עַד שֶׁיְּרַצֵּץ אֶת הַקְּלִפָּה:","בֵּיצָה מְגֻלְגֶּלֶת מִשֶּׁיִּקֹּב בָּהּ מָקוֹם לְגָמְעָהּ מִמֶּנּוּ אֵין שְׁאָר קְלִפָּתָהּ חִבּוּר. וּשְׁלוּקָה קְלִפָּתָהּ חִבּוּר עַד שֶׁיְּרַצֵּץ אֶת הַקְּלִפָּה. וְאִם נִתַּבְּלָה בִּקְלִפָּתָהּ אַף עַל פִּי שֶׁרִצְצָהּ כֻּלָּהּ חִבּוּר:","עֶצֶם שֶׁיֵּשׁ בּוֹ מוֹחַ חִבּוּר עַד שֶׁיְּרַצֵּץ. צֶמֶר שֶׁבְּרָאשֵׁי הַכְּבָשִׂים וְשֵׂעָר שֶׁבִּזְקַן הַתְּיָשִׁים אַף עַל פִּי שֶׁחֲרָכָן בָּאוּר הֲרֵי הֵן חִבּוּר עַד שֶׁיַּתְחִיל לִתְלֹשׁ:","כַּנְפֵי חֲגָבִים וְקַשְׂקַשֵּׂי דָּגִים אַף עַל פִּי שֶׁהֶעֱבִיר סַכִּין עֲלֵיהֶן חִבּוּר עַד שֶׁיַּתְחִיל לְקַלֵּף. הָרִמּוֹן שֶׁפִּרְדּוֹ חִבּוּר עַד שֶׁיַּקִּישׁ עָלָיו בְּקָנֶה:","הַשַּׁרְבִיטִים שֶׁל תְּמָרִים אֵינָן חִבּוּר זֶה לָזֶה:","מְלָפְפוֹן שֶׁחֲתָכוֹ וּנְתָנוֹ עַל הַשֻּׁלְחָן חִבּוּר עַד שֶׁיַּתְחִיל לְפָרֵק. הִתְחִיל לְפָרֵק חֲתִיכָה וְכָל הָעוֹלֶה עִמָּהּ חִבּוּר וְהַשְּׁאָר אֵינָהּ חִבּוּר. פִּיקָה הַתַּחְתּוֹנָה חִבּוּר לְעַצְמָהּ וְאֵינָהּ חִבּוּר לַחֲתִיכוֹת. הָיוּ שְׁנַיִם אוֹ שְׁלֹשָׁה מְלָפְפוֹנוֹת וְחָתַךְ כָּל אֶחָד מֵהֶן וְהִנִּיחָן עַל הַשֻּׁלְחָן וְהִתְחִיל בְּאֶחָד מֵהֶן זֶה שֶׁהִתְחִיל בּוֹ חִבּוּר וְהַשְּׁאָר אֵינוֹ חִבּוּר. אֲפִלּוּ אָמַר חֶצְיוֹ אֲנִי אוֹכֵל שַׁחֲרִית וְחֶצְיוֹ עַרְבִית זֶה הַחֵצִי שֶׁהִתְחִיל בּוֹ חִבּוּר וְהַשְּׁאָר אֵינוֹ חִבּוּר:","הַמְחַתֵּךְ יְרָקוֹת וְכַיּוֹצֵא בָּהֶן לְבַשֵּׁל אַף עַל פִּי שֶׁלֹּא מֵרֵק וְהִבְדִּיל אֵינוֹ חִבּוּר. אֶלָּא אִם נִטְמָא זֶה לֹא נִטְמָא זֶה אַף עַל פִּי שֶׁהוּא מְעֹרֶה בּוֹ. חָתַךְ לִכְבּשׁ אוֹ לִשְׁלֹק אוֹ לְהָנִיחַ עַל הַשֻּׁלְחָן הֲרֵי זֶה חִבּוּר וַאֲפִלּוּ הִתְחִיל לְפָרֵק מַה שֶּׁחָתַךְ:","כָּל אֹכֶל שֶׁעֲדַיִן לֹא פֵּרְקוֹ חִבּוּר וְאִם נִטְמָא מִקְצָתוֹ נִטְמָא כֻּלּוֹ:","אֹכֶל שֶׁנִּפְרַס וּמְעֹרֶה בְּמִקְצָת וְנָגַע טָמֵא בְּאֶחָד מֵהֶן אִם אָחַז בְּזֶה שֶׁנָּגַע בּוֹ וְהַשֵּׁנִי עוֹלֶה עִמּוֹ הֲרֵי זֶה חִבּוּר. וְאִם כְּשֶׁאוֹחֵז בָּזֶה הַטָּמֵא וּמַגְבִּיהוֹ יִשָׁמֵט הָאַחֵר וְיִפּל אֵינוֹ חִבּוּר אֶלָּא הֲרֵי זֶה הָאַחֵר כְּנוֹגֵעַ בָּרִאשׁוֹן שֶׁנִּטְמָא:","כָּל הָאֳכָלִין שֶׁהָיוּ עָלִין אוֹ קְלָחִין מְחֻבָּרִין בָּהֶן אֶת שֶׁדַּרְכּוֹ לְהֵאָחֵז בֶּעָלֶה אוֹחֲזִין אוֹתוֹ בֶּעָלֶה. בַּקֶּלַח אוֹחֲזִין אוֹתוֹ בַּקֶּלַח. אִם נִתְלָה עִמּוֹ הֲרֵי זֶה חִבּוּר בִּטְבוּל יוֹם וְאֵין צָרִיךְ לוֹמַר בִּשְׁאָר טֻמְאוֹת. וְכֵן אִם הָיָה לוֹ יָד אוֹחֲזִין אוֹתוֹ בַּיָּד שֶׁלּוֹ. הָיְתָה לוֹ יָד וְעָלֶה אוֹחֲזִין אוֹתוֹ בְּאֵי זֶה מֵהֶן שֶׁיִּרְצֶה. לֹא הָיְתָה לוֹ יָד וְלֹא עָלֶה, בָּזֶה אָמְרוּ אִם אוֹחֵז בַּטָּמֵא וְהַשֵּׁנִי עוֹלֶה עִמּוֹ חִבּוּר וְאִם לָאו אֵינוֹ חִבּוּר:","הָאֱגוֹזִין שֶׁקְּצָצָן בְּעֵקְצֵיהֶן כְּשֶׁהֵן רַכִּין וַאֲמָנָן כֻּלָּן כְּמוֹ חֶבֶל וְכֵן הַבְּצָלִים שֶׁחִבְּרָן בַּדֶּרֶךְ הַזֹּאת הֲרֵי אֵלּוּ חִבּוּר. הִתְחִיל לְפָרֵק בָּאֱגוֹזִים וּלְפַקֵּל בַּבְּצָלִים אֵין הַשְּׁאָר חִבּוּר. אֲפִלּוּ הָיוּ לְפָנָיו מֵאָה כּוֹר אֵין כֻּלָּן חִבּוּר שֶׁהֲרֵי הוֹכִיחַ שֶׁדַּעְתּוֹ לְפָרֵק הַכּל:","קְלִיעָה שֶׁל שׁוּם שֶׁנָּפְלוּ מַשְׁקִין עַל אֶחָד מֵהֶן הוּא טָמֵא וְחִבּוּרוֹ טָהוֹר שֶׁאֵין חִבּוּרֵי אָדָם חִבּוּר לְכָל דָּבָר. וְכֵן אֶתְרוֹג שֶׁנִּפְרַשׁ וּתְחָבוֹ בְּכוּשׁ אוֹ בְּקֵיסָם אֵינוֹ חִבּוּר:","עִסָּה שֶׁלָּשָׁהּ בְּמֵי פֵּרוֹת אֵינָהּ חִבּוּר. שֶׁאֵין לְךָ דָּבָר שֶׁמְּחַבֵּר אֶת הָאֳכָלִין אֶלָּא שִׁבְעָה מַשְׁקִין בִּלְבַד:","הַמְמַעֵךְ אֳכָלִין זֶה בָּזֶה וְקִבְּצָן כְּגוֹן הַדְּבֵלָה וְהַתְּמָרִים וְהַצִּמּוּקִין שֶׁקִּבְּצָן וַעֲשָׂאָן גּוּף אֶחָד אֵינָן חִבּוּר. לְפִיכָךְ עִגּוּל שֶׁל דְּבֵלָה שֶׁנָּפְלוּ מַשְׁקִין טְמֵאִין עַל מִקְצָתוֹ הֲרֵי זֶה נוֹטֵל מִמֶּנּוּ מְקוֹם הַמַּשְׁקִין בִּלְבַד וְהַשְּׁאָר טָהוֹר:","הַתְּמָרִים וְהַגְּרוֹגָרוֹת שֶׁשְּׁלָקָן וְנַעֲשׂוּ אוֹם הֲרֵי זֶה חִבּוּר:","הַזֵּיתִים שֶׁעֲטָנָן וְנַעֲשׂוּ גּוּשׁ אֶחָד הֲרֵי זֶה חִבּוּר. מִפְּנֵי שֶׁמִּתְּחִלָּה לֹא נְתָנָן לַמַּעֲטָן אֶלָּא עַל מְנָת שֶׁיִּינְקוּ זֶה מִזֶּה. לְפִיכָךְ שֶׁרֶץ שֶׁנִּמְצָא עַל אוֹם שֶׁל זֵיתִים וְהֵן הַזֵּיתִים שֶׁנַּעֲשׂוּ כֻּלָּן גּוּף אֶחָד אֲפִלּוּ נָגַע בְּכִשְׂעוֹרָה הַכּל טָמֵא שֶׁהַכּל גּוּף אֶחָד. הָיְתָה לוֹ אוֹם שֶׁל זֵיתִים וְעָתִיד לְהָפְכָהּ כֵּיוָן שֶׁתָּקַע בָּהּ אֶת הַיָּתֵד אַף עַל פִּי שֶׁיֵּשׁ בָּהּ גּוּשִׁים הַרְבֵּה אֵינָן חִבּוּר. וְאִם מִשֶּׁהֲפָכָהּ נַעֲשׂוּ אוֹם אֵינָן חִבּוּר:","אֹכֶל פָּרוּד שֶׁהוּא כֻּלּוֹ מְכֻנָּס וְדָבֵק זֶה בָּזֶה אַף עַל פִּי שֶׁאֵינוֹ חִבּוּר לְהִתְטַמֵּא וְאֵינוֹ כְּגוּף אֶחָד כְּמוֹ שֶׁבֵּאַרְנוּ הֲרֵי הוּא מִצְטָרֵף לִכְבֵיצָה לְטַמֵּא טֻמְאַת אֳכָלִים אֲחֵרִים. וְאִם לֹא כְּנָסוֹ אֶלָּא הֲרֵי הוּא מְפֹרָד כְּמַעֲשֵׂה קְדֵרָה וְהַקִּטְנִית אֵינוֹ מִצְטָרֵף עַד שֶׁיְּקַבְּצֵם וְיַעֲשֵׂם גּוּשׁ אֶחָד. הָיוּ גּוּשִׁים הַרְבֵּה זֶה בְּצַד זֶה וְנָגַע אַב הַטֻּמְאָה בְּאֶחָד מֵהֶן הֲרֵי הוּא רִאשׁוֹן וְהַגּוּשׁ שֶׁבְּצִדּוֹ שֵׁנִי וְשֶׁבְּצַד הַשֵּׁנִי שְׁלִישִׁי וְשֶׁבְּצַד הַשְּׁלִישִׁי רְבִיעִי:","כִּכָּר שֶׁל תְּרוּמָה שֶׁהָיְתָה רִאשׁוֹן לְטֻמְאָה וְהִשִּׁיךְ לָהּ אֲחֵרוֹת כֻּלָּם רִאשׁוֹן. פֵּרְשָׁה הִיא רִאשׁוֹן וְכֻלָּן שְׁנִיּוֹת. הָיְתָה שְׁנִיָּה וְהִשִּׁיךְ לָהּ אֲחֵרוֹת כֻּלָּן שְׁנִיּוֹת. פֵּרְשָׁה הִיא שְׁנִיָּה וְכֻלָּן שְׁלִישִׁיּוֹת. הָיְתָה שְׁלִישִׁית וְהִשִּׁיךְ לָהּ אֲחֵרוֹת הִיא שְׁלִישִׁית וְכֻלָּן טְהוֹרוֹת בֵּין שֶׁפֵּרְשׁוּ בֵּין שֶׁלֹּא פֵּרְשׁוּ:","כִּכָּרוֹת שֶׁל תְּרוּמָה נוֹשְׁכוֹת זוֹ בְּזוֹ נִטְמֵאת אַחַת מֵהֶן בְּשֶׁרֶץ כֻּלָּן רִאשׁוֹן וְאַף עַל פִּי שֶׁפֵּרְשׁוּ אַחַר מִכָּאן. [נִטְמֵאת אַחַת בְּמַשְׁקִין טְמֵאִין כֻּלָּן שְׁנִיּוֹת אַף עַל פִּי שֶׁפֵּרְשׁוּ אַחַר מִכָּאן]. נִטְמֵאת אַחַת מֵהֶן בְּיָדַיִם כֻּלָּן שְׁלִישִׁיּוֹת וְאַף עַל פִּי שֶׁפֵּרְשׁוּ מִפְּנֵי שֶׁהָיוּ גּוּף אֶחָד בִּשְׁעַת טֻמְאָתָן:"],"Mishneh Torah, Diverse Species 8":["הַגְּפָנִּים שֶׁגָּדְלוּ כִּבְרִיָּתָן וַהֲרֵי הַשָּׂרִיגִים וְהָאֶשְׁכּוֹלוֹת שֶׁלָּהֶן מֻשְׁלָכִין בָּאָרֶץ הֵן הַנִּקְרָאִין כֶּרֶם. אֲבָל הָעוֹשֶׂה כְּמוֹ מִטָּה אוֹ כְּמוֹ שְׂבָכָה גְּבוֹהָה מֵעַל הָאָרֶץ כְּדֵי שֶׁיִּהְיוּ הָאֶשְׁכּוֹלוֹת וְהַשָּׂרִיגִים נִמְשָׁכִין עָלֶיהָ וְהִגְבִּיהַּ נוֹף הַגְּפָנִים מֵעַל הָאָרֶץ עַל אוֹתָהּ הַמִּטָּה וְהִדְלָה אוֹתוֹ הֲרֵי זֶה נִקְרָא עָרִיס. וְאוֹתָם הַקָּנִים וְכַיּוֹצֵא בָּהֶן שֶׁעָשָׂה מֵהֶן מִטָּה אוֹ שְׂבָכָה וְהִדְלָה עֲלֵיהֶן אֶת נוֹף הַגֶּפֶן הֵן הַנִּקְרָאִים אַפִּיפְיָרוֹת. וְדִינִים אֲחֵרִים יֵשׁ בְּעָרִיס:","הַנּוֹטֵעַ שׁוּרָה אַחַת שֶׁל חָמֵשׁ גְּפָנִים אוֹ יֶתֶר וְעִרְסָן עַל גַּבֵּי כֹּתֶל גָּבוֹהַּ עֲשָׂרָה וְכַיּוֹצֵא בּוֹ אוֹ שֶׁנְּטָעָן בְּצַד חָרִיץ עָמֹק עֲשָׂרָה וְרָחָב אַרְבָּעָה הֲרֵי אֵלּוּ נִקְרָאִין עָרִיס. וְצָרִיךְ לְהַרְחִיק מִן הֶעָרִיס אַרְבַּע אַמּוֹת וְאַחַר כָּךְ יִזְרַע. כְּדֶרֶךְ שֶׁמַּרְחִיק מִן הַכֶּרֶם:","וּמֵהֵיכָן מוֹדְדִין. מֵעִקַּר הַגָּדֵר שֶׁעֵרְסָן עָלָיו. כֵּיצַד. הִרְחִיק אֶת הַשּׁוּרָה שֶׁל גְּפָנִים מִן הַכֹּתֶל אַמָּה וְנִמְצָא הֶעָרִיס מִן הַגְּפָנִים וְלַכֹּתֶל מוֹדֵד מִן הַכֹּתֶל אַרְבַּע אַמּוֹת וְזוֹרֵעַ. וְנִמְצָא בֵּין הַזֶּרַע וּבֵין עִקְּרֵי הַגְּפָנִים חָמֵשׁ אַמּוֹת. וְאִם בָּא לִזְרֹעַ מִצַּד הַגְּפָנִים מַרְחִיק מֵעִקְּרֵי הַגְּפָנִים אַרְבַּע אַמּוֹת שֶׁנִּמְצָא רָחוֹק מִן הַכֹּתֶל חָמֵשׁ אַמּוֹת. וְעַל דֶּרֶךְ זוֹ דָּנִין בְּכָל עָרִיס:","אֶחָד הַבּוֹנֶה אֶת הַגָּדֵר וְאַחַר כָּךְ נָטַע אוֹ שֶׁנָּטַע וְאַחַר כָּךְ עָשָׂה הַגָּדֵר הוֹאִיל וְעֵרְסָן הֲרֵי זֶה עָרִיס. נֶהֱרַס הַגָּדֵר אוֹ נִסְתַּם הֶחָרִיץ אֵין כָּאן עָרִיס אֶלָּא הֲרֵי כָּל הַשּׁוּרָה כִּגְפָנִים יְחִידִים:","עָרִיס שֶׁחָרַב אֶמְצָעוֹ וְנִשְׁתַּיְּרוּ בּוֹ חָמֵשׁ גְּפָנִים בְּצַד הַגָּדֵר מִכָּאן וְחָמֵשׁ גְּפָנִים בְּצַד הַגָּדֵר הָאַחֵר מִכְּנֶגְדָּן זֶהוּ הַנִּקְרָא פִּסְקֵי עָרִיס. אִם יֵשׁ בֵּינֵיהֶן שְׁמוֹנֶה אַמּוֹת וְאֶחָד מִשִּׁשִּׁים בָּאַמָּה הֲרֵי זֶה מַרְחִיק מִכָּל שׁוּרָה שִׁשָּׁה טְפָחִים וְזוֹרֵעַ. וְהוּא שֶׁלֹּא יִזְרַע תַּחַת הָאַפִּיפְיָרוֹת כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיָה בֵּינֵיהֶן שְׁמוֹנֶה אַמּוֹת בְּצִמְצוּם הֲרֵי זֶה לֹא יִזְרַע לְשָׁם. וְאִם זְרָעָן הוֹאִיל וְהִרְחִיק מִכָּל שׁוּרָה שִׁשָּׁה טְפָחִים הֲרֵי זֶה לֹא קִדֵּשׁ. וְאִם אֵין שָׁם גָּדֵר מַרְחִיק מִכָּל שׁוּרָה שִׁשָּׁה טְפָחִים וְזוֹרֵעַ שֶׁאֵין כָּאן לֹא עָרִיס וְלֹא פִּסְקֵי עָרִיס. חָזַר וּבָנָה הַגָּדֵר חָזַר עָרִיס לִמְקוֹמוֹ וְחָזְרוּ פִּסְקֵי עָרִיס לִמְקוֹמָן:","גִּנָּה קְטַנָּה שֶׁהִיא מֻקֶּפֶת גָּדֵר וְעִרֵס אֶת הַגְּפָנִים סָבִיב לָהּ מִבַּחוּץ עַל כָּל כְּתָלֶיהָ. אִם יֵשׁ בָּהּ מְלֹא בּוֹצֵר וְסַלּוֹ מִכָּאן וּמְלֹא בּוֹצֵר וְסַלּוֹ מִכָּאן. הוֹאִיל וְהִיא מֻקֶּפֶת גָּדֵר זוֹרְעִין בְּתוֹכָהּ יְרָקוֹת. וְאִם אֵין [בָּהּ] כַּשִּׁעוּר הַזֶּה אֵין זוֹרְעִים בְּתוֹכָהּ מִפְּנֵי שֶׁנִּרְאֶה הַכּל כְּעָרִיס אֶחָד וְיָרָק בְּתוֹכוֹ:","גְּפָנִים שֶׁהָיוּ זְרוּעִים בְּמַדְרֵגָה גְּבוֹהָה וְהֶעָרִיס שֶׁלָּהֶן יוֹצֵא וּמְסַכֵּךְ עַל הַשָּׂדֶה. אִם עוֹמֵד בָּאָרֶץ וּבוֹצֵר אֶת כֻּלּוֹ רוֹאִין כָּל הַמָּקוֹם שֶׁתַּחַת הֶעָרִיס כְּאִלּוּ הוּא מְקוֹם עִקְּרֵי הַגְּפָנִים וְאוֹסֵר אַרְבַּע אַמּוֹת בַּשָּׂדֶה לְכָל רוּחַ מִשְּׂפַת הֶעָרִיס. וְאִם אֵינוֹ יָכוֹל לִבְצֹר עַד שֶׁיַּעֲלֶה בַּמַּדְרֵגָה אוֹ בַּסֻּלָּם אֵין אָסוּר לִזְרֹעַ אֶלָּא תַּחַת הֶעָרִיס בִּלְבַד:","שְׁנֵי כְּתָלִים הַסְּמוּכִין זֶה לָזֶה וְהַגְּפָנִים נְטוּעִים בְּזָוִיּוֹת בֵּינֵיהֶם וְהֶעָרִיס יוֹצֵא עִם הַכְּתָלִים מִתּוֹךְ הַקֶּרֶן וְכָלֶּה. מַרְחִיק מֵעִקְּרֵי הַגְּפָנִים כַּשִּׁעוּר וְזוֹרֵעַ בְּמָקוֹם הַכָּלֶּה שֶׁאֵין עָלָיו עָרִיס. וְאַף עַל פִּי שֶׁהַזֶּרַע מְכֻוָּן בֵּין שְׁנֵי הַכְּתָלִים שֶׁבֵּינֵיהֶן הֶעָרִיס הוֹאִיל וְהִרְחִיק כַּשִּׁעוּר הֲרֵי זֶה זוֹרֵעַ בֵּין הַכְּתָלִים:","גֶּפֶן שֶׁעָלָה הָעֵץ שֶׁלָּהּ מִן הָאָרֶץ מְעַט וְאַחַר כָּךְ נֶעֱקַם וְנִמְשָׁךְ עַל הָאָרֶץ וְחָזַר וְעָלָה כְּמוֹ אַרְכֻּבָּה. כְּשֶׁמּוֹדְדִין בֵּין הַגֶּפֶן וּבֵין הַזֶּרַע שִׁשָּׁה טְפָחִים אוֹ אַרְבַּע אַמּוֹת אֵין מוֹדְדִין אֶלָּא מִסּוֹף הָאַרְכֻּבָּה לֹא מֵעִקַּר הַגֶּפֶן הָרִאשׁוֹן:","כְּבָר בֵּאַרְנוּ שֶׁאַף עַל פִּי שֶׁמַּרְחִיק בֵּין הַזֶּרַע וּבֵין הַגֶּפֶן כַּשִּׁעוּר. צָרִיךְ לְהִזָּהֵר שֶׁלֹּא תְּסַכֵּךְ הַגֶּפֶן עַל הַיָּרָק אוֹ יְסַכֵּךְ הַיָּרָק עַל הַגֶּפֶן. זָרַע יָרָק אוֹ תְּבוּאָה וְצִמְחָה וְאַחַר כָּךְ סִכֵּךְ עָלֶיהָ אֶת הַגֶּפֶן הַקַּשִּׁין מֻתָּרִין וְהַדָּגָן יִדְלַק. הָיוּ שָׁרְשֵׁי הַגֶּפֶן יוֹצְאִין לְתוֹךְ הָאַרְבַּע אַמּוֹת שֶׁבֵּין הַכֶּרֶם וְהַתְּבוּאָה יַעֲקֹר. הָיוּ שָׁרְשֵׁי הַתְּבוּאָה יוֹצְאִין לְתוֹךְ הָאַרְבַּע אַמּוֹת מֻתָּר:","כָּל הַהַרְחָקוֹת וְהַשִּׁעוּרִין הָאֲמוּרִין בְּכִלְאַיִם בְּאַמָּה בַּת שִׁשָּׁה טְפָחִים שׂוֹחֲקוֹת. וְלֹא יְצַמְצֵם בְּמִדּוֹת הַכִּלְאַיִם שֶׁאֵין מְצַמְצְמִים אֶלָּא לְהַחֲמִיר:","כָּל הַשִּׁעוּרִין הָאֵלּוּ שֶׁמַּרְחִיקִין בֵּין הַגְּפָנִים וְהַתְּבוּאָה אוֹ הַיָּרָק אֵינָן אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל אוֹ בְּסוּרְיָא. אֲבָל בְּחוּצָה לָאָרֶץ מֻתָּר לִזְרֹעַ בְּצַד הַגְּפָנִים בְּתוֹךְ הַכֶּרֶם לְכַתְּחִלָּה. וְלֹא אָסְרוּ בְּחוּצָה לָאָרֶץ אֶלָּא לִזְרֹעַ שְׁנֵי מִינֵי יָרָק אוֹ תְּבוּאָה עִם הַחַרְצָן בְּמַפּלֶת יָד. וְאִם אָמַר לְתִינוֹק נָכְרִי לִזְרֹעַ לוֹ בְּחוּצָה לָאָרֶץ מֻתָּר. אֲבָל לֹא יֹאמַר לְנָכְרִי גָּדוֹל שֶׁלֹּא יִתְחַלֵּף בְּיִשְׂרָאֵל:","וְאַף עַל פִּי שֶׁמֻּתָּר לִזְרֹעַ הַיָּרָק בְּצַד הַכֶּרֶם בְּחוּצָה לָאָרֶץ הֲרֵי אוֹתוֹ הַיָּרָק הַזָּרוּעַ שָׁם אָסוּר בַּאֲכִילָה וַאֲפִלּוּ בְּחוּצָה לָאָרֶץ. וְהוּא שֶׁיִּרְאֶה אוֹתוֹ לוֹקֵט וּמוֹכֵר. אֲבָל סְפֵקוֹ מֻתָּר כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת:"],"Mishneh Torah, Divorce 7":["שָׁלִיחַ שֶׁהֵבִיא גֵּט מִמָּקוֹם לְמָקוֹם בְּאֶרֶץ יִשְׂרָאֵל אַף עַל פִּי שֶׁלֹּא רָאָה כְּתִיבַת הַגֵּט וְלֹא יָדַע מִי הֵם עֵדָיו אֶלָּא נָתַן לוֹ הַבַּעַל גֵּט וְאָמַר לוֹ תֵּן גֵּט זֶה לְאִשְׁתִּי הֲרֵי זֶה נוֹתְנוֹ לָהּ בִּפְנֵי עֵדִים וְאַף עַל פִּי שֶׁאֵין עֵדָיו יְדוּעִין אֶצְלֵנוּ וְתִהְיֶה מְגֹרֶשֶׁת וְתִנָּשֵׂא בּוֹ:","בָּא הַבַּעַל וְעִרְעֵר וְאָמַר לֹא גֵּרַשְׁתִּיהָ מֵעוֹלָם וְגֵט שֶׁהוּבָא לָהּ מְזֻיָּף הוּא יִתְקַיֵּם בְּחוֹתְמָיו. וְאִם לֹא נִתְקַיֵּם וְלֹא נוֹדְעוּ עֵדָיו כְּלָל תֵּצֵא וְהַוָּלָד מַמְזֵר שֶׁהֲרֵי אֵינָהּ מְגֹרֶשֶׁת. [אָבַד הַגֵּט הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת]. לְפִיכָךְ נָשִׁים שֶׁחֶזְקָתָן שֶׁהֵן שׂוֹנְאוֹת זוֹ אֶת זוֹ אֵין נֶאֱמָנוֹת לְהָבִיא גֵּט בְּאֶרֶץ יִשְׂרָאֵל זוֹ לָזוֹ שֶׁמָּא מְזֻיָּף הוּא וְתִתְכַּוֵּן לְקַלְקֵל אוֹתָהּ כְּדֵי שֶׁתִּנָּשֵׂא וְתֵאָסֵר עַל בַּעְלָהּ:","וְאֵלּוּ הֵן הַנָּשִׁים שֶׁחֶזְקָתָן שׂוֹנְאוֹת זוֹ אֶת זוֹ. חֲמוֹתָהּ וּבַת חֲמוֹתָהּ וְצָרָתָהּ אֲפִלּוּ הָיְתָה הַצָּרָה נְשׂוּאָה לְאַחֵר. וִיבִמְתָּהּ אֲפִלּוּ הָיְתָה אֲחוֹתָהּ וּבַת בַּעְלָהּ. אֲבָל שְׁאָר כָּל הַנָּשִׁים כְּשֵׁרוֹת:","הַמֵּבִיא גֵּט מִמָּקוֹם לְמָקוֹם בְּאֶרֶץ יִשְׂרָאֵל וְחָלָה אוֹ נֶאֱנַס מְשַׁלְּחוֹ בְּיַד אַחֵר. וְכֵן הַשֵּׁנִי אִם חָלָה מְשַׁלְּחוֹ בְּיַד אַחֵר. וַאֲפִלּוּ מֵאָה. וְאֵין צָרִיךְ עֵדִים לַחֲזֹר וְלַעֲשׂוֹת שָׁלִיחַ בִּפְנֵיהֶם. וְהָאַחֲרוֹן שֶׁהִגִּיעַ הַגֵּט לְיָדוֹ נוֹתְנוֹ לָהּ בִּפְנֵי שְׁנַיִם וְתִתְגָּרֵשׁ בּוֹ אַף עַל פִּי שֶׁמֵּת הָרִאשׁוֹן:","שָׁלִיחַ שֶׁהֵבִיא גֵּט מִמָּקוֹם לְמָקוֹם בְּחוּצָה לָאָרֶץ אוֹ מֵאֶרֶץ יִשְׂרָאֵל לְחוּצָה לָאָרֶץ. אוֹ מֵחוּצָה לָאָרֶץ לָאָרֶץ. אִם הָיָה הַשָּׁלִיחַ עוֹמֵד בִּשְׁעַת כְּתִיבַת הַגֵּט וַחֲתִימָתוֹ הֲרֵי זֶה אוֹמֵר בִּפְנֵי שְׁנַיִם בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם וְאַחַר כָּךְ יִתֵּן לָהּ בִּפְנֵיהֶם וְתִתְגָּרֵשׁ בּוֹ. וְאַף עַל פִּי שֶׁאֵין עֵדָיו יְדוּעִין אֶצְלֵנוּ. וַאֲפִלּוּ הָיוּ שְׁמוֹת עֵדָיו כִּשְׁמוֹת הָעַכּוּ״‎ם אֵין חוֹשְׁשִׁין לָהֶן:","בָּא הַבַּעַל וְעָמַד וְעִרְעֵר אֵין מַשְׁגִּיחִין בּוֹ. לְפִיכָךְ אַף הַנָּשִׁים שֶׁשּׂוֹנְאוֹת זוֹ אֶת זוֹ נֶאֱמָנוֹת לְהָבִיא גֵּט זֶה וְלוֹמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם:","וְכֵן שָׁלִיחַ שֶׁהֵבִיא גֵּט בְּאֶרֶץ יִשְׂרָאֵל וְאָמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ אִם יָבֹא הַבַּעַל וִיעַרְעֵר אֵין מַשְׁגִּיחִין בּוֹ. וְאִם אֵין הַשָּׁלִיחַ עוֹמֵד בִּשְׁעַת כְּתִיבָה וַחֲתִימָה לֹא יִנָּתֵן לָהּ אֶלָּא אִם כֵּן נִתְקַיֵּם בְּחוֹתְמָיו. וְיֵשׁ לַשָּׁלִיחַ לִהְיוֹת מִכְּלַל הַשְּׁלֹשָׁה שֶׁקִּיְּמוּ אוֹתָן בְּחוֹתְמָיו. וְאִם לֹא נִתְקַיֵּם וְנָתַן לָהּ הֲרֵי זֶה פָּסוּל עַד שֶׁיִּתְקַיֵּם. וְאִם בָּא הַבַּעַל וְעִרְעֵר וְלֹא נִתְקַיֵּם אֵינָהּ מְגֹרֶשֶׁת. אָבַד הַגֵּט הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת:","וּמִפְּנֵי מָה הִצְרִיכוּ לוֹמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם בְּחוּץ לָאָרֶץ. כְּדֵי שֶׁלֹּא תִּהְיֶה הָאִשָּׁה צְרִיכָה לְקַיְּמוֹ אִם יָבוֹא הַבַּעַל וִיעַרְעֵר מִפְּנֵי שֶׁאֵין הָעֵדִים מְצוּיִין לְקַיְּמוֹ מִמָּקוֹם לְמָקוֹם בְּחוּצָה לָאָרֶץ:","בַּעַל שֶׁהֵבִיא רְאָיָה בְּרוּרָה שֶׁגֵּט זֶה שֶׁנֶּאֱמַר בּוֹ בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם מְזֻיָּף הוּא הֲרֵי זֶה בָּטֵל. שֶׁלֹּא הֶאֱמִינוּ דְּבָרָיו שֶׁל אֶחָד שֶׁאָמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם אֶלָּא לִדְחוֹת עִרְעוּר הַבַּעַל שֶׁאֵין עִמּוֹ רְאָיָה. אֲבָל בִּמְקוֹם עֵדִים שֶׁמַּכְחִישִׁין אוֹתוֹ לֹא הֶאֱמִינוּהוּ:","הַנְּהָרוֹת שֶׁבְּאֶרֶץ יִשְׂרָאֵל וְהַנִּסִּין שֶׁבַּיָּם הַגָּדוֹל שֶׁבְּתוֹךְ הַתְּחוּם שֶׁל אֶרֶץ יִשְׂרָאֵל הֲרֵי הֵן כְּאֶרֶץ יִשְׂרָאֵל. וְשֶׁחוּץ לַתְּחוּם כְּחוּצָה לָאָרֶץ. וּבְהִלְכוֹת תְּרוּמוֹת יִתְבָּאֲרוּ תְּחוּמֵי אֶרֶץ יִשְׂרָאֵל. וּבָבֶל כְּאֶרֶץ יִשְׂרָאֵל לְגִטִּין:","גֵּט שֶׁכְּתָבוֹ בְּאֶרֶץ יִשְׂרָאֵל וַחֲתָמוֹ בְּחוּצָה לָאָרֶץ צָרִיךְ שֶׁיֹּאמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. כְּתָבוֹ בְּחוּצָה לָאָרֶץ וַחֲתָמוֹ בְּאֶרֶץ יִשְׂרָאֵל אֵינוֹ צָרִיךְ לוֹמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם:","נִכְתַּב מִקְצָת הַגֵּט בְּפָנָיו וְנֶחְתַּם כֻּלּוֹ בְּפָנָיו. אִם מִקְצָתוֹ הָרִאשׁוֹן הוּא הֲרֵי זֶה אוֹמֵר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם אֲפִלּוּ לֹא נִכְתַּב בּוֹ אֶלָּא שִׁיטָה אַחַת בְּפָנָיו וַאֲפִלּוּ שָׁמַע קוֹל הַקֻּלְמוֹס כּוֹתֵב וְחָתְמוּ הָעֵדִים בְּפָנָיו הֲרֵי זֶה אוֹמֵר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. וְכֵן אִם יָצָא הַסּוֹפֵר לַשּׁוּק וְחָזַר וְהִשְׁלִים אֶת הַגֵּט אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא אַחֵר מְצָאוֹ וְאָמַר לוֹ וּלְשֵׁם אִשָּׁה אַחֶרֶת כְּתָבוֹ אֶלָּא אוֹמֵר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם:","אָמַר בְּפָנַי נִכְתַּב אֲבָל לֹא בְּפָנַי נֶחְתַּם. בְּפָנַי נֶחְתַּם אֲבָל לֹא בְּפָנַי נִכְתַּב. בְּפָנַי נִכְתַּב כֻּלּוֹ וְחָתַם עֵד אֶחָד אֲבָל לֹא הָעֵד הַשֵּׁנִי. אֲפִלּוּ הָיָה הוּא הָעֵד הַשֵּׁנִי הֲרֵי זֶה יִתְקַיֵּם בְּחוֹתְמָיו וְאַחַר כָּךְ יִנָּתֵן לָהּ. וְאִם הֵעִיד הוּא וְאַחֵר עַל הָעֵד הַשֵּׁנִי שֶׁלֹּא חָתַם בְּפָנָיו הֲרֵי זֶה כָּשֵׁר וְיִנָּתֵן לָהּ. וְאֵין צָרִיךְ לוֹמַר אִם הֵעִידוּ שְׁנַיִם אֲחֵרִים עַל כְּתַב הָעֵד הַשֵּׁנִי שֶׁזֶּה כָּשֵׁר:","שְׁנַיִם שֶׁהֵבִיאוּ גֵּט בְּחוּצָה לָאָרֶץ אַף עַל פִּי שֶׁלֹּא נִכְתַּב וְנֶחְתַּם בִּפְנֵיהֶם הוֹאִיל וּנְתָנוֹ לָהֶם הַבַּעַל לִתְּנוֹ לְאִשְׁתּוֹ הֲרֵי אֵלּוּ נוֹתְנִין לָהּ וְתִהְיֶה מְגֹרֶשֶׁת. שֶׁהֲרֵי אֵין הַבַּעַל יָכוֹל לְעַרְעֵר בְּגֵט זֶה אַף עַל פִּי שֶׁאֵינוֹ מְקֻיָּם שֶׁהֲרֵי שְׁלוּחָיו הֵם עֵדָיו. שֶׁאִלּוּ אָמְרוּ הַשְּׁנַיִם בְּפָנֵינוּ נִתְגָּרְשָׁה הֲרֵי זוֹ מְגֹרֶשֶׁת אַף עַל פִּי שֶׁאֵין שָׁם גֵּט:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁהַגֵּט יוֹצֵא מִתַּחַת יְדֵי שְׁנֵיהֶם אֲבָל אִם אֵין הַגֵּט יוֹצֵא מִתַּחַת יְדֵי שְׁנֵיהֶם צְרִיכִין לוֹמַר בְּפָנֵינוּ נִכְתַּב וּבְפָנֵינוּ נֶחְתַּם. לְפִיכָךְ אִם אָמַר אֶחָד בְּפָנַי נִכְתַּב וְהָאַחֵר אוֹמֵר בְּפָנַי נֶחְתַּם וַאֲפִלּוּ שְׁנַיִם אוֹמְרִים בְּפָנֵינוּ נִכְתַּב וְאֶחָד אוֹמֵר בְּפָנַי נֶחְתַּם הוֹאִיל וְאֵינוֹ יוֹצֵא מִתַּחַת יְדֵי שְׁנֵיהֶם לֹא יִנָּתֵן לָהּ עַד שֶׁיִּתְקַיֵּם בְּחוֹתְמָיו:","אָמַר אֶחָד בְּפָנַי נִכְתַּב וּשְׁנַיִם אוֹמְרִים בְּפָנֵינוּ נֶחְתַּם כָּשֵׁר אַף עַל פִּי שֶׁאֵינוֹ יוֹצֵא מִתַּחַת יָדָם שֶׁהֲרֵי נִתְקַיֵּם בְּחוֹתְמָיו:","שָׁלִיחַ שֶׁהֵבִיא גֵּט בְּחוּצָה לָאָרֶץ וּנְתָנוֹ לָהּ בֵּינוֹ לְבֵינָהּ אוֹ שֶׁנְּתָנוֹ לָהּ בִּפְנֵי שְׁנַיִם וְלֹא אָמַר לָהּ בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם אַף עַל פִּי שֶׁנִּשֵּׂאת נוֹטְלוֹ מִמֶּנָּה וְחוֹזֵר וְנוֹתְנוֹ לָהּ בִּפְנֵי שְׁנַיִם וְאוֹמֵר בִּפְנֵיהֶם בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. וְאִם לֹא נְטָלוֹ מִמֶּנָּה הֲרֵי זֶה פָּסוּל עַד שֶׁיִּתְקַיֵּם בְּחוֹתְמָיו:","נְתָנוֹ לָהּ וְלֹא הִסְפִּיק לוֹמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם עַד שֶׁנִּשְׁתַּתֵּק הֲרֵי זֶה יִתְקַיֵּם בְּחוֹתְמָיו וְאַחַר כָּךְ יִנָּתֵן לָהּ:","הַסּוּמָא אֵינוֹ יָכוֹל לְהָבִיא גֵּט זֶה שֶׁל חוּצָה לָאָרֶץ מִפְּנֵי שֶׁאֵינוֹ יָכוֹל לוֹמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. לְפִיכָךְ אִם נִכְתַּב וְנֶחְתַּם בְּפָנָיו כְּשֶׁהוּא פָּתוּחַ וְנִסְתַּמָא הֲרֵי זֶה אוֹמֵר בִּפְנֵי שְׁלֹשָׁה בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם וְנוֹתְנוֹ לָהּ. וְכֵן הָאִשָּׁה שֶׁהֵבִיאָה גֵּט זֶה שֶׁל חוּצָה לָאָרֶץ צְרִיכָה שְׁלֹשָׁה לוֹמַר בִּפְנֵיהֶם בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. שֶׁלֹּא אָמְרוּ בִּפְנֵי שְׁנַיִם אֶלָּא בִּזְמַן שֶׁהַשָּׁלִיחַ כָּשֵׁר לְעֵדוּת שֶׁהֲרֵי הוּא מִצְטָרֵף עִם הַשְּׁנַיִם וְנִמְצָא מִכְּלַל הַשְּׁלֹשָׁה שֶׁקִּיְּמוּ גֵּט זֶה בִּדְבָרָיו. שֶׁהָעֵד נַעֲשָׂה דַּיָּן בְּדָבָר שֶׁהוּא מִדִּבְרֵיהֶם:","חָלָה הַשָּׁלִיחַ אוֹ נֶאֱנַס בָּא לְבֵית דִּין וְאוֹמֵר לָהֶם גֵּט זֶה בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם וְהֵן מְשַׁלְּחִין אוֹתוֹ בְּיַד שָׁלִיחַ אַחֵר. וְאֵין הַשָּׁלִיחַ הָאַחֲרוֹן צָרִיךְ לוֹמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם אֶלָּא אוֹמֵר שְׁלִיחַ בֵּית דִּין אֲנִי וְנוֹתְנוֹ לָהּ בִּפְנֵי עֵדִים:","חָלָה הַשֵּׁנִי אוֹ נֶאֱנַס עוֹשֶׂה שָׁלִיחַ אַחֵר בְּבֵית דִּין אֲפִלּוּ מֵאָה וְהָאַחֲרוֹן אוֹמֵר שְׁלִיחַ בֵּית דִּין אֲנִי וְנוֹתְנוֹ לָהּ. אַף עַל פִּי שֶׁמֵּת הַשָּׁלִיחַ הָרִאשׁוֹן. וּמִפְּנֵי מָה צָרִיךְ בֵּית דִּין מִפְּנֵי שֶׁהוּא צָרִיךְ לוֹמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. אֲבָל אִם נִתְקַיֵּם הַגֵּט בְּחוֹתְמָיו אַף עַל פִּי שֶׁנְּתָנוֹ שָׁלִיחַ לְשָׁלִיחַ אֲפִלּוּ מֵאָה בֵּינָם לְבֵין עַצְמָם עַד שֶׁהִגִּיעַ הַגֵּט לְיָדָהּ הֲרֵי זֶה כָּשֵׁר. וְאַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ הַבַּעַל וְלֹא אָמַר לוֹ שַׁלְּחוֹ בְּיַד אַחֵר אִם תֵּאָנֵס אִם חָלָה אוֹ נֶאֱנַס הֲרֵי זֶה מְשַׁלְּחוֹ:","כָּל הָעוֹשֶׂה שָׁלִיחַ אֵינוֹ צָרִיךְ שֶׁיְּהֵא הַשָּׁלִיחַ עִמּוֹ בְּבֵית דִּין אֶלָּא אוֹמֵר לָהֶם הֲרֵי פְּלוֹנִי שְׁלוּחִי וַאֲפִלּוּ שֶׁלֹּא בְּפָנָיו. וְכֵן הַשָּׁלִיחַ עוֹשֶׂה שָׁלִיחַ אַחֵר שֶׁלֹּא בְּפָנָיו אֲפִלּוּ הֵן מֵאָה:","הָאִישׁ שֶׁנָּתַן גֵּט לְאִשְׁתּוֹ וְנִכְתַּב וְנֶחְתַּם בְּפָנֶיהָ וְאָמַר לָהּ הֲרֵי אַתְּ שְׁלוּחָתִי לְהוֹלָכָה עַד בֵּית דִּין פְּלוֹנִי וְהֵם יַעֲמִידוּ שָׁלִיחַ וְיִתְּנוּ לִיךְ גֵּט זֶה וְתִתְגָּרְשִׁי בּוֹ הֲרֵי זוֹ נֶאֱמֶנֶת לוֹמַר בִּפְנֵיהֶם בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם וְהֵם נוֹטְלִין אוֹתוֹ וְנוֹתְנִין אוֹתוֹ לְשָׁלִיחַ לִתְּנוֹ לָהּ כְּמַאֲמַר הַבַּעַל:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהִתְנָה עָלֶיהָ הַבַּעַל תְּנַאי זֶה אֲבָל אִם לֹא הִתְנָה עָלֶיהָ אֶלָּא נָתַן לָהּ גִּטָּהּ וַהֲרֵי הַגֵּט יוֹצֵא מִתַּחַת יָדָהּ אֵינָהּ צְרִיכָה לוֹמַר כְּלוּם וַהֲרֵי הִיא בְּחֶזְקַת מְגֹרֶשֶׁת. הוֹאִיל וְגֵט שֶׁבְּיָדָהּ כָּתוּב כְּהִלְכָתוֹ וְהָעֵדִים חֲתוּמִים עָלָיו. וְאַף עַל פִּי שֶׁאֵין אָנוּ מַכִּירִין כְּתַב אוֹתָן הָעֵדִים וְלֹא נִתְקַיֵּם אֵין חוֹשְׁשִׁין לָהּ שֶׁמָּא זִיְּפָה אוֹתוֹ שֶׁהֲרֵי אֵינָהּ מְקַלְקֶלֶת עַל עַצְמָהּ. וְעוֹד שֶׁהָעֵדִים הַחֲתוּמִים עַל הַגֵּט הֲרֵי הֵן כְּמִי שֶׁנֶּחְקְרָה עֵדוּתָן בְּבֵית דִּין עַד שֶׁיְּהֵא שָׁם מְעַרְעֵר. לְפִיכָךְ נַעֲמִיד הַגֵּט בְּחֶזְקָתוֹ וְתִנָּשֵׂא. וְאֵין חוֹשְׁשִׁין שֶׁמָּא יִמָּצֵא מְזֻיָּף. כְּמוֹ שֶׁנַּעֲמִיד הַגֵּט בְּחֶזְקַת כָּשֵׁר כְּשֶׁיָּבִיא אוֹתוֹ הַשָּׁלִיחַ עַד שֶׁיְּעַרְעֵר הַבַּעַל אוֹ עַד שֶׁיָּבִיא רְאָיָה שֶׁהוּא מְזֻיָּף אוֹ בָּטֵל. שֶׁאִם נָחוּשׁ לִדְבָרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶן כָּךְ הָיָה לָנוּ לָחוּשׁ לְגֵט שֶׁיִּתֵּן הַבַּעַל בְּפָנֵינוּ שֶׁמָּא בִּטְּלוֹ וְאַחַר כָּךְ נְתָנוֹ. אוֹ שֶׁמָּא עֵדִים פְּסוּלִין חָתְמוּ בּוֹ וַהֲרֵי הוּא כִּמְזֻיָּף מִתּוֹכוֹ. אוֹ שֶׁמָּא שֶׁלֹּא לִשְׁמָהּ נִכְתַּב. וּכְשֵׁם שֶׁאֵין חוֹשְׁשִׁין לָזֶה וְכַיּוֹצֵא בּוֹ אֶלָּא נַעֲמִידֶנּוּ עַל חֶזְקָתוֹ עַד שֶׁיִּוָּדַע שֶׁהוּא בָּטֵל כָּךְ לֹא נָחוּשׁ לֹא לַשָּׁלִיחַ וְלֹא לָאִשָּׁה עַצְמָהּ שֶׁהַגֵּט יוֹצֵא מִתַּחַת יָדָהּ. שֶׁאֵין דִּינֵי הָאִסּוּרִין כְּדִינֵי הַמָּמוֹנוֹת:"],"Mishneh Torah, Fasts 2":["אֵלוּ הֵן הַצָּרוֹת שֶׁל צִבּוּר שֶׁמִּתְעַנִּין וּמַתְרִיעִין עֲלֵיהֶם. עַל הֲצָרַת שׂוֹנְאֵי יִשְׂרָאֵל לְיִשְׂרָאֵל. וְעַל הַחֶרֶב. וְעַל הַדֶּבֶר. וְעַל חַיָּה רָעָה. וְעַל הָאַרְבֶּה. וְעַל הֶחָסִיל. וְעַל הַשִּׁדָּפוֹן. וְעַל הַיֵּרָקוֹן. וְעַל הַמַּפּלֶת. וְעַל הֶחֳלָאִים. וְעַל הַמְּזוֹנוֹת. וְעַל הַמָּטָר:","כָּל עִיר שֶׁיֵּשׁ בָּהּ צָרָה מִכָּל אֵלּוּ. אוֹתָהּ הָעִיר מִתְעַנָּה וּמַתְרַעַת עַד שֶׁתַּעֲבֹר הַצָּרָה. וְכָל סְבִיבוֹתֶיהָ מִתְעַנּוֹת וְלֹא מַתְרִיעוֹת אֲבָל מְבַקְּשִׁים עֲלֵיהֶם רַחֲמִים. וּבְכָל מָקוֹם אֵין צוֹעֲקִין וְלֹא מַתְרִיעִין בְּשַׁבָּת כְּמוֹ שֶׁאָמַרְנוּ. חוּץ מִצָּרַת הַמְּזוֹנוֹת שֶׁצּוֹעֲקִין עָלֶיהָ אֲפִלּוּ בְּשַׁבָּת. אֲבָל אֵין מַתְרִיעִין עָלֶיהָ בַּחֲצוֹצְרוֹת בְּשַׁבָּת:","עַל הֲצָרַת שׂוֹנְאֵי יִשְׂרָאֵל לְיִשְׂרָאֵל כֵּיצַד. עַכּוּ\"ם שֶׁבָּאוּ לַעֲרֹךְ מִלְחָמָה עִם יִשְׂרָאֵל אוֹ לִטּל מֵהֶם מַס אוֹ לִקַּח מִיָּדָם אֶרֶץ אוֹ לִגְזֹר עֲלֵיהֶם גְּזֵרָה אֲפִלּוּ בְּמִצְוָה קַלָּה הֲרֵי אֵלּוּ מִתְעַנִּין וּמַתְרִיעִין עַד שֶׁיְּרֻחֲמוּ. וְכָל הֶעָרִים שֶׁסְּבִיבוֹתֵיהֶם מִתְעַנִּין אֲבָל אֵין מַתְרִיעִין אֶלָּא אִם כֵּן תָּקְעוּ לְהִתְקַבֵּץ לְעֶזְרָתָן:","עַל הַחֶרֶב כֵּיצַד. אֲפִלּוּ חֶרֶב שֶׁל שָׁלוֹם כְּגוֹן שֶׁעָרְכוּ מִלְחָמָה עַכּוּ\"ם עִם עַכּוּ\"ם וְעָבְרוּ בִּמְקוֹם יִשְׂרָאֵל אַף עַל פִּי שֶׁאֵין בֵּינֵיהֶם וּבֵין יִשְׂרָאֵל מִלְחָמָה הֲרֵי זוֹ צָרָה וּמִתְעַנִּין עָלֶיהָ שֶׁנֶּאֱמַר (ויקרא כו ו) \"וְחֶרֶב לֹא תַעֲבֹר בְּאַרְצְכֶם\" מִכְּלַל שֶׁרְאִיַּת הַמִּלְחָמָה צָרָה:","וְעַל הַדֶּבֶר. אֵי זוֹ הִיא דֶּבֶר עִיר שֶׁיֵּשׁ בָּהּ חֲמֵשׁ מֵאוֹת רַגְלִי וְיָצְאוּ מִמֶּנָּה שְׁלֹשָׁה מֵתִים בִּשְׁלֹשָׁה יָמִים זֶה אַחַר זֶה הֲרֵי זֶה דֶּבֶר. יָצְאוּ בְּיוֹם אֶחָד אוֹ בְּאַרְבָּעָה יָמִים אֵין זֶה דֶּבֶר. הָיוּ בָּהּ אֶלֶף וְיָצְאוּ מִמֶּנָּה שִׁשָּׁה מֵתִים בִּשְׁלֹשָׁה יָמִים זֶה אַחַר זֶה דֶּבֶר. יָצְאוּ בְּיוֹם אֶחָד אוֹ בְּאַרְבָּעָה אֵין זֶה דֶּבֶר. וְכֵן לְפִי חֶשְׁבּוֹן זֶה. וְאֵין הַנָּשִׁים וְהַקְּטַנִּים וְהַזְּקֵנִים שֶׁשָּׁבְתוּ מִמְּלָאכָה בִּכְלַל מִנְיַן אַנְשֵׁי הַמְּדִינָה לְעִנְיָן זֶה:","הָיָה דֶּבֶר בְּאֶרֶץ יִשְׂרָאֵל מִתְעַנִּין שְׁאָר גָּלֻיּוֹת יִשְׂרָאֵל עֲלֵיהֶן. הָיָה דֶּבֶר בַּמְּדִינָה וְשַׁיָּרוֹת הוֹלְכוֹת וּבָאוֹת מִמֶּנָּה לִמְדִינָה אַחֶרֶת שְׁתֵּיהֶן מִתְעַנּוֹת אַף עַל פִּי שֶׁהֵן רְחוֹקוֹת זוֹ מִזּוֹ:","אֵין מִתְעַנִּין עַל חַיָּה רָעָה אֶלָּא בִּזְמַן שֶׁהִיא מְשֻׁלַּחַת. כֵּיצַד. נִרְאֲתָה בָּעִיר בַּיּוֹם הֲרֵי זוֹ מְשֻׁלַּחַת. נִרְאֲתָה בַּשָּׂדֶה בַּיּוֹם אִם רָאֲתָה שְׁנֵי בְּנֵי אָדָם וְלֹא בָּרְחָה מִפְּנֵיהֶם הֲרֵי זוֹ מְשֻׁלַּחַת. וְאִם הָיָה שָׂדֶה הַסְּמוּכָה לָאֲגַם וְרָאֲתָה שְׁנֵי בְּנֵי אָדָם וְרָדְפָה אַחֲרֵיהֶם הֲרֵי זוֹ מְשֻׁלַּחַת. לֹא רָדְפָה אַחֲרֵיהֶם אֵינָהּ מְשֻׁלַּחַת. וְאִם הָיָה בָּאֲגַם אֲפִלּוּ רָדְפָה אַחֲרֵיהֶם אֵינָהּ מְשֻׁלַּחַת אֶלָּא אִם כֵּן טָרְפָה שְׁנֵיהֶם וְאָכְלָה אֶחָד מֵהֶן. אֲבָל אִם אָכְלָה שְׁנֵיהֶם בָּאֲגַם אֵינָהּ מְשֻׁלַּחַת מִפְּנֵי שֶׁזֶּה הוּא מְקוֹמָהּ וּמִפְּנֵי הָרְעָבוֹן טָרְפָה לֹא מִפְּנֵי שֶׁהִיא מְשֻׁלַּחַת:","בָּתִּים הַבְּנוּיִים בְּמִדְבָּרוֹת וּבָאֲרָצוֹת הַנְשַׁמּוֹת הוֹאִיל וְהֵן מְקוֹם גְּדוּדֵי חַיָּה. אִם עָלְתָה לַגַּג וְנָטְלָה תִּינוֹק מֵעֲרִיסָה הֲרֵי זוֹ מְשֻׁלַּחַת. וְאִם לֹא הִגִּיעָה לְמִדָּה זוֹ אֵינָהּ מְשֻׁלַּחַת. שֶׁאֵלּוּ בְּנֵי אָדָם הֵם שֶׁסִּכְּנוּ בְּעַצְמָם וּבָאוּ לִמְקוֹם הַחַיּוֹת:","שְׁאָר מִינֵי רֶמֶשׂ הָאָרֶץ וְרֶמֶשׂ הָעוֹף שֶׁשֻּׁלְּחוּ וְהִזִּיקוּ. כְּגוֹן שִׁלּוּחַ נְחָשִׁים וְעַקְרַבִּים וְאֵין צָרִיךְ לוֹמַר צְרָעִין וְיַתּוּשִׁין וְהַדּוֹמֶה לָהֶן אֵין מִתְעַנִּין עֲלֵיהֶם וְלֹא מַתְרִיעִין אֲבָל זוֹעֲקִין בְּלֹא תְּרוּעָה:","עַל הָאַרְבֶּה וְעַל הֶחָסִיל אֲפִלּוּ לֹא נִרְאֶה מֵהֶן אֶלָּא כָּנָף אֶחָד בְּכָל אֶרֶץ יִשְׂרָאֵל מִתְעַנִּין וּמַתְרִיעִין עֲלֵיהֶן. וְעַל הַגּוֹבַאי בְּכָל שֶׁהוּא. אֲבָל עַל הֶחָגָב אֵין מִתְעַנִּין עָלָיו וְלֹא מַתְרִיעִין אֶלָּא זוֹעֲקִין בִּלְבַד:","עַל הַשִּׁדָּפוֹן וְעַל הַיֵּרָקוֹן מִשֶּׁיַּתְחִיל בַּתְּבוּאָה. וַאֲפִלּוּ לֹא הִתְחִיל אֶלָּא מִמָּקוֹם קָטָן כִּמְלֹא פִּי תַּנּוּר גּוֹזְרִין עָלָיו תַּעֲנִית וּמַתְרִיעִין:","עַל הַמַּפּלֶת כֵּיצַד. הֲרֵי שֶׁרָבְתָה בָּעִיר מַפּלֶת כְּתָלִים בְּרִיאִים שֶׁאֵינָן עוֹמְדִים בְּצַד הַנָּהָר הֲרֵי זוֹ צָרָה וּמִתְעַנִּין וּמַתְרִיעִין עָלֶיהָ. וְכֵן עַל הָרַעַשׁ וְעַל הָרוּחוֹת שֶׁהֵן מַפִּילִין אֶת הַבִּנְיָן וְהוֹרְגִין מִתְעַנִּין וּמַתְרִיעִין עֲלֵיהֶן:","עַל הֶחֳלָיִים כֵּיצַד. הֲרֵי שֶׁיָּרַד חלִי אֶחָד לַאֲנָשִׁים הַרְבֵּה בְּאוֹתָהּ הָעִיר כְּגוֹן אַסְכָּרָה אוֹ חַרְחוּר וְכַיּוֹצֵא בָּהֶן וְהָיוּ מֵתִים בְּאוֹתוֹ הַחלִי הֲרֵי זוֹ צָרַת צִבּוּר וְגוֹזְרִין לָהּ תַּעֲנִית וּמַתְרִיעִין. וְכֵן חִכּוּךְ לַח הֲרֵי הוּא כִּשְׁחִין פּוֹרֵחַ. וְאִם פָּשַׁט בְּרֹב הַצִּבּוּר מִתְעַנִּין וּמַתְרִיעִין עָלָיו. אֲבָל חִכּוּךְ יָבֵשׁ צוֹעֲקִים עָלָיו בִּלְבַד:","עַל הַמְּזוֹנוֹת כֵּיצַד. הֲרֵי שֶׁהוּזְלוּ דְּבָרִים שֶׁל סְחוֹרָה שֶׁרֹב חַיֵּי אַנְשֵׁי אוֹתָהּ הָעִיר מֵהֶן. כְּגוֹן כְּלֵי פִּשְׁתָּן בְּבָבֶל וְיַיִן וְשֶׁמֶן בְּאֶרֶץ יִשְׂרָאֵל. וְנִתְמַעֵט הַמַּשָּׂא וְהַמַּתָּן עַד שֶׁיִּצְטָרֵךְ הַתַּגָּר לִמְכֹּר שְׁוִה עֲשָׂרָה בְּשִׁשָּׁה וְאַחַר כָּךְ יִמָּצֵא לוֹקֵחַ. הֲרֵי זוֹ צָרַת צִבּוּר וּמַתְרִיעִין עָלֶיהָ וְזוֹעֲקִין עָלֶיהָ בְּשַׁבָּת:","עַל הַמָּטָר כֵּיצַד. הֲרֵי שֶׁרַבּוּ עֲלֵיהֶן גְּשָׁמִים עַד שֶׁיָּצֵרוּ לָהֶן הֲרֵי אֵלּוּ מִתְפַּלְּלִין עֲלֵיהֶן. שֶׁאֵין לְךָ צָרָה יְתֵרָה מִזּוֹ שֶׁהַבָּתִּים נוֹפְלִין וְנִמְצְאוּ בָּתֵּיהֶן קִבְרֵיהֶן. וּבְאֶרֶץ יִשְׂרָאֵל אֵין מִתְפַּלְּלִין עַל רֹב הַגְּשָׁמִים מִפְּנֵי שֶׁהִיא אֶרֶץ הָרִים וּבָתֵּיהֶם בְּנוּיִים בַּאֲבָנִים וְרֹב הַגְּשָׁמִים טוֹבָה לָהֶן וְאֵין מִתְעַנִּין לְהַעֲבִיר הַטּוֹבָה:","תְּבוּאָה שֶׁצָּמְחָה וְנִמְנַע הַמָּטָר וְהִתְחִילוּ צְמָחִין לִיבַשׁ הֲרֵי אֵלּוּ מִתְעַנִּין וְזוֹעֲקִין עַד שֶׁיֵּרְדוּ גְּשָׁמִים אוֹ עַד שֶׁיִּיבְשׁוּ הַצְּמָחִים. וְכֵן אִם הִגִּיעַ זְמַן הַפֶּסַח אוֹ קָרוֹב לוֹ בְּאֶרֶץ יִשְׂרָאֵל שֶׁהוּא זְמַן פְּרִיחַת הָאִילָנוֹת שָׁם וְלֹא יָרְדוּ גְּשָׁמִים הֲרֵי אֵלּוּ מִתְעַנִּין וְזוֹעֲקִין עַד שֶׁיֵּרְדוּ גְּשָׁמִים הָרְאוּיִין לְאִילָנוֹת אוֹ עַד שֶׁיַּעֲבֹר זְמַנָּם:","וְכֵן אִם הִגִּיעַ זְמַן חַג הַסֻּכּוֹת וְלֹא יָרְדוּ גְּשָׁמִים הַרְבֵּה כְּדֵי לְמַלְּאוֹת מֵהֶם הַבּוֹרוֹת הַשִּׁיחִין וְהַמְּעָרוֹת הֲרֵי אֵלּוּ מִתְעַנִּין עַד שֶׁיֵּרֵד גֶּשֶׁם הָרָאוּי לְבוֹרוֹת. וְאִם אֵין לָהֶם מַיִם לִשְׁתּוֹת מִתְעַנִּים עַל הַגְּשָׁמִים בְּכָל עֵת שֶׁלֹּא יִהְיֶה לָהֶם מַיִם לִשְׁתּוֹת וַאֲפִלּוּ בִּימוֹת הַחַמָּה:","פָּסְקוּ הַגְּשָׁמִים בֵּין גֶּשֶׁם לְגֶשֶׁם אַרְבָּעִים יוֹם בִּימוֹת הַגְּשָׁמִים הֲרֵי זוֹ מַכַּת בַּצֹּרֶת וּמִתְעַנִּים וְזוֹעֲקִים עַד שֶׁיֵּרְדוּ הַגְּשָׁמִים אוֹ עַד שֶׁיַּעֲבֹר זְמַנָּם:"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 3":["הַבִּכּוּרִים נוֹתְנִין [אוֹתָן] לְאַנְשֵׁי מִשְׁמָר וְהֵן מְחַלְּקִים אוֹתָן בֵּינֵיהֶן כְּקָדְשֵׁי הַמִּקְדָּשׁ. וּכְבָר בֵּאַרְנוּ שֶׁהֵן קְרוּיִין תְּרוּמָה. וּלְפִיכָךְ זָר שֶׁאָכַל בִּכּוּרִים בְּכָל מָקוֹם חַיָּב מִיתָה בִּידֵי שָׁמַיִם. וְהוּא שֶׁיֹּאכְלֵם מֵאַחַר שֶׁנִּכְנְסוּ לְחוֹמַת יְרוּשָׁלַיִם:","הָיוּ מִקְצָתָן בִּפְנִים וּמִקְצָתָן בַּחוּץ. זֶה שֶׁבִּפְנִים חַיָּבִין עָלָיו מִיתָה וַהֲרֵי הוּא הֶקְדֵּשׁ לְכָל דְּבָרָיו. וְזֶה שֶׁבַּחוּץ הֲרֵי הוּא חֻלִּין לְכָל דְּבָרָיו:","כֹּהֵן שֶׁאָכַל בִּכּוּרִים חוּץ לִירוּשָׁלַיִם מֵאַחַר שֶׁנִּכְנְסוּ לְפָנִים מִן הַחוֹמָה לוֹקֶה מִן הַתּוֹרָה שֶׁנֶּאֱמַר (דברים יב יז) \"לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ\" וְגוֹ' (דברים יב יז) \"וּתְרוּמַת יָדֶךָ\" וְהֵם הַבִּכּוּרִים כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת תְּרוּמָה. וְכֵן אִם אֲכָלָן הַכֹּהֵן בִּירוּשָׁלַיִם קֹדֶם הַנָּחָה בָּעֲזָרָה לוֹקֶה מִן הַתּוֹרָה כְּמִי שֶׁאֲכָלָן בַּחוּץ לְפִי שֶׁהֵן טְעוּנִין הַנָּחָה בָּעֲזָרָה שֶׁנֶּאֱמַר וְהִנַּחְתּוֹ לִפְנֵי מִזְבַּח ה' אֱלֹהֶיךָ:","וּמִשֶּׁיָּנִיחֵם הַמְּבִיאָם בָּעֲזָרָה הֻתְּרוּ לַכֹּהֵן וְאַף עַל פִּי שֶׁעֲדַיִן לֹא הִתְוַדָּה עֲלֵיהֶן שֶׁאֵין הַקְּרִיאָה מְעַכֶּבֶת אֲכִילָתָן. ובִּכּוּרִים שֶׁיָּצְאוּ חוּץ לִמְחִצָּתָן וְחָזְרוּ מֻתָּרִין בַּאֲכִילָה:","אֲכִילַת בִּכּוּרִים כַּאֲכִילַת תְּרוּמָה לְכָל דְּבָרָיו. יֶתֶר בְּבִכּוּרִים שֶׁהֵן אֲסוּרִין לְאוֹנֵן וּטְעוּנִין הֲבָאַת מָקוֹם. וְכֹהֵן טָהוֹר שֶׁאָכַל בִּכּוּרִים טְמֵאִים לוֹקֶה כְּשֵׁם שֶׁלּוֹקֶה יִשְׂרָאֵל טָהוֹר שֶׁאָכַל מַעֲשֵׂר שֵׁנִי שֶׁנִּטְמָא מַה שֶּׁאֵין כֵּן בִּתְרוּמָה:","וּמִנַּיִן שֶׁהַבִּכּוּרִים אֲסוּרִין לְאוֹנֵן שֶׁהֲרֵי נֶאֱמַר בָּהֶן (דברים כו יא) \"וְשָׂמַחְתָּ בְּכָל הַטּוֹב\" מִכְּלָל שֶׁהוּא חַיָּב לְאָכְלָן בְּשִׂמְחָה לֹא בַּאֲנִינוּת. וְהָאוֹכְלָן בַּאֲנִינוּת מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","הַבִּכּוּרִים טְעוּנִין כְּלִי שֶׁנֶּאֱמַר (דברים כו ב) \"וְשַׂמְתָּ בַטֶּנֶא\". וּמִצְוָה מִן הַמֻּבְחָר לְהָבִיא כָּל מִין וּמִין בִּכְלִי בִּפְנֵי עַצְמוֹ. וְאִם הֱבִיאָם בִּכְלִי אֶחָד יָצָא. וְלֹא יְבִיאֵם בְּעִרְבּוּב אֶלָּא שְׂעוֹרִים מִלְּמַטָּה וְחִטִּים עַל גַּבֵּיהֶן וְזֵיתִים עַל גַּבֵּיהֶן וּתְמָרִים עַל גַּבֵּיהֶן וְרִמּוֹנִים עַל גַּבֵּיהֶן וּתְאֵנִים לְמַעְלָה מִן הַכְּלִי. וְיִהְיֶה דָּבָר אֶחָד מַפְסִיק בֵּין מִין וָמִין כְּגוֹן הוּצִין וְחֵלֶף אוֹ עָלִין וְכַיּוֹצֵא בָּהֶן. וּמַקִּיף לַתְּאֵנִים אֶשְׁכּוֹלוֹת שֶׁל עֲנָבִים מִבַּחוּץ:","הֱבִיאָם בִּכְלֵי מַתָּכוֹת נוֹטֵל הַכֹּהֵן הַבִּכּוּרִים וְחוֹזֵר הַכְּלִי לִבְעָלָיו. וְאִם הֱבִיאָם בִּכְלֵי עֲרָבָה וְחֵלֶף וְכַיּוֹצֵא בָּהֶן הֲרֵי הַבִּכּוּרִים וְהַסַּלִּים לַכֹּהֲנִים. וְאִם נִטְמְאוּ הַבִּכּוּרִים אֵין הַסַּלִּים לַכֹּהֲנִים:","כְּשֶׁהָיוּ מְבִיאִין אֶת הַבִּכּוּרִים הָיוּ מְבִיאִין בְּיָדָם תּוֹרִין וּבְנֵי יוֹנָה. וְכֵן הָיוּ תּוֹלִין מִצִּדֵּי הַסַּלִּים תּוֹרִין וּבְנֵי יוֹנָה כְּדֵי לְעַטֵּר אֶת הַבִּכּוּרִים. אֵלּוּ שֶׁעִם הַסַּלִּים הָיוּ קְרֵבִים עוֹלוֹת וְאֵלּוּ שֶׁבִּידֵיהֶן הָיוּ נִתָּנִין לַכֹּהֲנִים:","מִצְוַת עֲשֵׂה לְהִתְוַדּוֹת בַּמִּקְדָּשׁ עַל הַבִּכּוּרִים בְּשָׁעָה שֶׁמְּבִיאָם. מַתְחִיל וְקוֹרֵא (דברים כו ג) \"הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךָ כִּי בָאתִי אֶל הָאָרֶץ\" וְגוֹ' (דברים כו ה) \"אֲרַמִּי אֹבֵד אָבִי\" עַד שֶׁיִּגְמֹר כָּל הַפָּרָשָׁה עַד (דברים כו י) \"אֲשֶׁר נָתַתָּ לִּי ה'\". וְאֵין קוֹרִין אוֹתָהּ אֶלָּא בִּלְשׁוֹן הַקֹּדֶשׁ שֶׁנֶּאֱמַר (דברים כו ה) \"וְעָנִיתָ וְאָמַרְתָּ\". בַּלָּשׁוֹן הַזֹּאת:","בָּרִאשׁוֹנָה כָּל מִי שֶׁהָיָה יוֹדֵעַ לִקְרוֹת קוֹרֵא וְכָל מִי שֶׁאֵינוֹ יוֹדֵעַ לִקְרוֹת מַקְרִין אוֹתוֹ. נִמְנְעוּ אֵלּוּ שֶׁאֵין יוֹדְעִין לִקְרוֹת מִלְּהָבִיא כְּדֵי שֶׁלֹּא יִכָּלְמוּ. הִתְקִינוּ בֵּית דִּין שֶׁיִּהְיוּ מַקְרִין אֶת מִי שֶׁהוּא יוֹדֵעַ כְּמִי שֶׁאֵינוֹ יוֹדֵעַ:","הַמֵּבִיא אֶת הַבִּכּוּרִים יֵשׁ לוֹ רְשׁוּת לִתְּנֵם לְעַבְדּוֹ וּקְרוֹבוֹ בְּכָל הַדֶּרֶךְ עַד שֶׁמַּגִּיעַ לְהַר הַבַּיִת. הִגִּיעַ לְהַר הַבַּיִת נוֹטֵל הַסַּל עַל כְּתֵפוֹ הוּא בְּעַצְמוֹ. וַאֲפִלּוּ הָיָה מֶלֶךְ גָּדוֹל שֶׁבְּיִשְׂרָאֵל. וְנִכְנָס עַד שֶׁמַּגִּיעַ לַעֲזָרָה וְקוֹרֵא וְעוֹדֵהוּ הַסַּל עַל כְּתֵפוֹ (דברים כו ג) \"הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךָ\" וְגוֹ'. וּמוֹרִיד הַסַּל מֵעַל כְּתֵפוֹ וְאוֹחֲזוֹ בִּשְׂפָתָיו וְהַכֹּהֵן מַנִּיחַ יָדוֹ תַּחְתָּיו וּמֵנִיף וְקוֹרֵא (דברים כו ה) \"אֲרַמִּי אֹבֵד אָבִי וַיֵּרֶד מִצְרַיְמָה\" וְגוֹ' עַד שֶׁגּוֹמֵר כָּל הַפָּרָשָׁה וּמַנִּיחוֹ בְּצַד הַמִּזְבֵּחַ בְּקֶרֶן דְּרוֹמִית מַעֲרָבִית בִּדְרוֹמָהּ שֶׁל קֶרֶן וְיִשְׁתַּחֲוֶה וְיֵצֵא. וּמִנַּיִן שֶׁהֵן טְעוּנִין תְּנוּפָה שֶׁנֶּאֱמַר (דברים כו ד) \"וְלָקַח הַכֹּהֵן הַטֶּנֶא\" מִיָּדֶךָ לְרַבּוֹת אֶת הַבִּכּוּרִים לִתְנוּפָה. וּכְשֵׁם שֶׁטְּעוּנִין תְּנוּפָה כָּךְ טְעוּנִין קָרְבַּן שְׁלָמִים [וְשִׁיר] שֶׁנֶּאֱמַר בָּהֶן (דברים כו יא) \"וְשָׂמַחְתָּ בְּכָל הַטּוֹב\" וּבָרְגָלִים אוֹמֵר (דברים טז יד) \"וְשָׂמַחְתָּ בְּחַגֶּךָ\" מָה שִׂמְחַת הֶחָג בִּשְׁלָמִים אַף כָּאן בִּשְׁלָמִים. וְאֵין הַקָּרְבָּן מְעַכֶּבֶת:","וְאֵימָתַי קוֹרִין בְּשִׁיר עֲלֵיהֶן. מִשֶּׁיַּגִּיעוּ לַעֲזָרָה הַלְוִיִּם הָיוּ מַתְחִילִין וְקוֹרִין (תהילים ל ב) \"אֲרוֹמִמְךָ ה' כִּי דִלִּיתָנִי\":","הַבִּכּוּרִים טִעוּנִים לִינָה. כֵּיצַד. הֵבִיא בִּכּוּרָיו לַמִּקְדָּשׁ וְקָרָא וְהִקְרִיב שְׁלָמָיו לֹא יֵצֵא בְּאוֹתוֹ הַיּוֹם מִירוּשָׁלַיִם לַחֲזֹר לִמְקוֹמוֹ אֶלָּא יָלִין שָׁם וְיַחֲזֹר לְמָחָר לְעִירוֹ שֶׁנֶּאֱמַר (דברים טז ז) \"וּפָנִיתָ בַבֹּקֶר וְהָלַכְתָּ לְאֹהָלֶיךָ\". כָּל פּוֹנוֹת שֶׁאַתָּה פּוֹנֶה מִן הַמִּקְדָּשׁ לִכְשֶׁתָּבוֹא לוֹ לֹא יִהְיוּ אֶלָּא בַּבֹּקֶר. נִמְצֵאתָ אוֹמֵר שֶׁהַבִּכּוּרִים טְעוּנִין שִׁבְעָה דְּבָרִים. הֲבָאַת מָקוֹם. וּכְלִי. קְרִיאָה. וְקָרְבָּן. וְשִׁיר. וּתְנוּפָה. וְלִינָה:"],"Mishneh Torah, Firstlings 6":["מִצְוַת עֲשֵׂה לְהַפְרִישׁ אֶחָד מֵעֲשָׂרָה מִכָּל בְּהֵמוֹת טְהוֹרוֹת שֶׁיִּוָּלְדוּ לָאָדָם בְּכָל שָׁנָה וְשָׁנָה. וְאֵין מִצְוָה זוֹ נוֹהֶגֶת אֶלָּא בְּבָקָר וְצֹאן בִּלְבַד שֶׁנֶּאֱמַר (ויקרא כז לב) \"וְכָל מַעְשַׂר בָּקָר וָצֹאן\" וְגוֹ':","מַעֲשַׂר בְּהֵמָה נוֹהֵג בְּחֻלִּין אֲבָל לֹא בְּמֻקְדָּשִׁין. וְנוֹהֵג בָּאָרֶץ וּבְחוּצָה לָאָרֶץ בִּפְנֵי הַבַּיִת וְשֶׁלֹּא בִּפְנֵי הַבַּיִת. אֲבָל חֲכָמִים אָסְרוּ לְעַשֵּׂר בְּהֵמָה בַּזְּמַן הַזֶּה וְתִקְּנוּ שֶׁאֵין מְעַשְּׂרִין אֶלָּא בִּפְנֵי הַבַּיִת גְּזֵרָה שֶׁמָּא יֹאכְלֵהוּ תָּמִים וְנִמְצָא בָּא לִידֵי אִסּוּר כָּרֵת שֶׁהוּא שְׁחִיטַת קָדָשִׁים בַּחוּץ. וְאִם עָבַר וְעָשָׂה בַּזְּמַן הַזֶּה הֲרֵי זֶה מַעֲשֵׂר וְיֵאָכֵל בְּמוּמוֹ:","הַכֹּל חַיָּבִין בְּמַעֲשַׂר בְּהֵמָה. כֹּהֲנִים לְוִיִּים וְיִשְׂרְאֵלִים:","וְדִין מַעֲשַׂר בְּהֵמָה שֶׁיִּהְיֶה נִשְׁחָט בָּעֲזָרָה וְזוֹרְקִין אֶת דָּמוֹ זְרִיקָה אַחַת כְּנֶגֶד הַיְסוֹד וּמַקְטִירִין אֵימוּרָיו. וּשְׁאָר הַבָּשָׂר נֶאֱכָל לַבְּעָלִים בִּירוּשָׁלַיִם כִּשְׁאָר קָדָשִׁים קַלִּים וְאֵין לַכֹּהֲנִים בּוֹ כְּלוּם אֶלָּא כֻּלּוֹ לַבְּעָלִים כַּפֶּסַח. וְאִם הָיָה בַּעַל מוּם בֵּין שֶׁנָּפַל בּוֹ מוּם בֵּין שֶׁהִפְרִישׁוֹ בַּתְּחִלָּה בְּמוּמוֹ הֲרֵי זֶה נֶאֱכָל בְּכָל מָקוֹם:","מַעֲשַׂר בְּהֵמָה אָסוּר לְמָכְרוֹ כְּשֶׁהוּא תָּמִים שֶׁנֶּאֱמַר בּוֹ (ויקרא כז לג) \"לֹא יִגָּאֵל\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר לֹא יִגָּאֵל אַף אִסּוּר מְכִירָה בְּמַשְׁמָע שֶׁאֵין נִגְאָל וְאֵינוֹ נִמְכָּר כְּלָל. וְיֵרָאֶה לִי שֶׁהַמּוֹכֵר מַעֲשֵׂר לֹא עָשָׂה כְּלוּם וְלֹא קָנָה לוֹקֵחַ. וּלְפִיכָךְ אֵינוֹ לוֹקֶה כְּמוֹכֵר חֶרְמֵי כֹּהֲנִים שֶׁלֹּא קָנָה לוֹקֵחַ וּכְמוֹכֵר יְפַת תֹּאַר כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","מִדִּבְרֵי סוֹפְרִים שֶׁאָסוּר לְמָכְרוֹ בַּעַל מוּם וַאֲפִלּוּ שָׁחוּט גְּזֵרָה שֶׁמָּא יִמְכְּרֶנּוּ חַי. לְפִיכָךְ אֵין שׁוֹקְלִין מָנָה כְּנֶגֶד מָנָה בְּמַעֲשֵׂר כְּדֶרֶךְ שֶׁשּׁוֹקְלִין בִּבְכוֹר. מִפְּנֵי שֶׁהוּא נִרְאֶה כְּמוֹכֵר:","וּמַעֲשַׂר בְּהֵמָה שֶׁל יְתוֹמִים שֶׁנִּשְׁחַט בְּמוּמוֹ מֻתָּר לְמָכְרוֹ כְּדַרְכּוֹ. מִפְּנֵי הֲשָׁבַת אֲבֵדָה לִיתוֹמִים לֹא גָּזְרוּ עָלָיו:","מַעֲשַׂר בְּהֵמָה שֶׁנִּשְׁחַט בְּמוּמוֹ מֻתָּר לִמְכּוֹר חֶלְבּוֹ וְגִידָיו וְעוֹרוֹ וְעַצְמוֹתָיו. וְלֹא אָסְרוּ לִמְכֹּר אֶלָּא בְּשָׂרוֹ בִּלְבַד. וְאִם הִבְלִיעַ דְּמֵי הַבָּשָׂר בִּדְמֵי הָעוֹר וְהַחֵלֶב וְהַגִּידִין וּמָכַר הַכֹּל בְּהַבְלָעָה מֻתָּר. וְאִם הָיוּ דְּמֵי הָעֲצָמוֹת יְקָרִים וְהִבְלִיעַ דְּמֵי הַבָּשָׂר בִּדְמֵי הָעֲצָמוֹת מֻתָּר:","הַכֹּל נֶאֱמָנִים עַל מוּמֵי מַעֲשֵׂר לוֹמַר מוּם זֶה מֵאֵלָיו בָּא וְלֹא נַעֲשָׂה לְדַעַת. וַאֲפִלּוּ אֵלּוּ שֶׁאֵינָן נֶאֱמָנִים עַל הַבְּכוֹר נֶאֱמָנִים עַל הַמַּעֲשֵׂר. וְרוֹאֶה אָדָם מוּמֵי מַעֲשֵׂר שֶׁלּוֹ וּמַתִּירוֹ אִם הָיָה מֻמְחֶה. שֶׁאִם יִרְצֶה יַטִּיל מוּם בְּכָל עֶדְרוֹ וְאַחַר כָּךְ יְעַשֵּׂר וְנִמְצָא הַמַּעֲשֵׂר בַּעַל מוּם מִתְּחִלָּתוֹ:","הַלּוֹקֵחַ טְלָאִים שֶׁנּוֹלְדוּ בְּשָׁנָה זוֹ אוֹ שֶׁנִּתְּנוּ לוֹ בְּמַתָּנָה הֲרֵי הֵם פְּטוּרִים מִן הַמַּעֲשֵׂר עַד שֶׁיִּוָּלְדוּ בִּרְשׁוּתוֹ. לְפִיכָךְ הַשֻּׁתָּפִין שֶׁנִּשְׁתַּתְּפוּ בִּבְהֵמוֹת וְהֵבִיא זֶה מֵאָה טְלָאִים וְזֶה מֵאָה טְלָאִים וְעֵרְבוּם וְנִשְׁתַּתְּפוּ בָּהֶן הֲרֵי הַמָּאתַיִם פְּטוּרִים מִן הַמַּעֲשֵׂר שֶׁכָּל טָלֶה מֵהֶן כְּמָכוּר. וְכֵן הָאַחִים שֶׁיָּרְשׁוּ טְלָאִים מֵאֲבִיהֶם הֲרֵי הֵן פְּטוּרִין מִן הַמַּעֲשֵׂר. אֲבָל הַנּוֹלָדִים לָהֶם בְּשֻׁתָּפוּת לְאַחַר מִכָּאן מֵאֵלּוּ הַבְּהֵמוֹת בֵּין לַשֻּׁתָּפִין בֵּין לָאַחִים חַיָּבִין בְּמַעֲשֵׂר. וְכֵן אִם הָיוּ שֻׁתָּפִין בְּמָעוֹת וְקָנוּ בְּהֵמוֹת מִמְּעוֹת הַשֻּׁתָּפוּת וְהָאַחִים שֶׁקָּנוּ בְּהֵמוֹת מִמְּעוֹת הַיְרֻשָּׁה הֲרֵי הַנּוֹלָדִים מֵהֶם לְאַחַר מִכָּאן חַיָּבִין בְּמַעֲשֵׂר שֶׁהֲרֵי בִּרְשׁוּתָן נוֹלְדוּ וַהֲרֵי הֵן כְּאִישׁ אֶחָד. חָלְקוּ הָאַחִים וְהַשֻּׁתָּפִין אַחַר שֶׁנּוֹלְדוּ לָהֶן הַבְּהֵמוֹת בִּרְשׁוּתָן וְחָזְרוּ וְנִשְׁתַּתְּפוּ הֲרֵי אֵלּוּ פְּטוּרִין מִן הַמַּעֲשֵׂר. שֶׁבְּשָׁעָה שֶׁחָלְקוּ נַעֲשׂוּ הַכֹּל לְקוּחִין וְהַלָּקוּחַ פָּטוּר וּכְשֶׁחָזְרוּ וְנִשְׁתַּתְּפוּ הֲרֵי נִשְׁתַּתְּפוּ בַּבְּהֵמוֹת וַעֲדַיִן לֹא יָלְדוּ לָהֶן בִּרְשׁוּתָן אַחַר שִׁתּוּף זֶה הַשֵּׁנִי. וְאַף עַל פִּי שֶׁחָלְקוּ גְּדָיִים כְּנֶגֶד גְּדָיִים וּטְלָאִים כְּנֶגֶד טְלָאִים וַעֲשָׂרָה כְּנֶגֶד עֲשָׂרָה הַכֹּל פְּטוּרִין מִן הַמַּעֲשֵׂר וַהֲרֵי הֵן כִּלְקוּחִין:","הָאַחִין וְהַשֻּׁתָּפִין שֶׁחָלְקוּ בִּכְסָפִים וְלֹא חָלְקוּ בִּבְהֵמָה חַיָּבִין בְּמַעֲשֵׂר שֶׁעֲדַיִן לֹא נַעֲשׂוּ הַבְּהֵמוֹת לְקוּחִין. אֲבָל אִם חָלְקוּ הַבְּהֵמוֹת אַף עַל פִּי שֶׁעֲדַיִן לֹא חָלְקוּ הַכְּסָפִים הֲרֵי אֵלּוּ פְּטוּרִין:","הַלּוֹקֵחַ עֲשָׂרָה עֻבָּרִים בִּמְעֵי אִמָּן. כֻּלָּן נִכְנָסִין לַדִּיר לְהִתְעַשֵּׂר שֶׁהֲרֵי בִּרְשׁוּתוֹ נוֹלְדוּ:","כֹּהֵן שֶׁנָּפְלוּ לוֹ עֶשֶׂר בְּהֵמוֹת בְּגֵזֶל הַגֵּר פְּטוּרִים מִן הַמַּעֲשֵׂר. שֶׁמַּתְּנוֹת כְּהֻנָּה מַתָּנוֹת הֵם. וּכְבָר בֵּאַרְנוּ שֶׁהַנּוֹתֵן מַתָּנָה פָּטוּר מִן הַמַּעֲשֵׂר:","הַכֹּל נִכְנָסִין לַדִּיר לְהִתְעַשֵּׂר. בֵּין תְּמִימִים בֵּין בַּעֲלֵי מוּמִין. וְכָל אִסּוּרֵי מִזְבֵּחַ. חוּץ מִן הַכִּלְאַיִם. וְהַטְּרֵפָה. וְיוֹצֵא דֹּפֶן. וּמְחֻסָּר זְמַן. שֶׁכָּל אֵלּוּ פְּטוּרִין מִן הַמַּעֲשֵׂר. וְכֵן הַיָּתוֹם שֶׁמֵּתָה אִמּוֹ אוֹ נִשְׁחֲטָה עִם לֵידָתוֹ אֵינוֹ מִתְעַשֵּׂר. וּדְבָרִים אֵלּוּ מִפִּי הַשְּׁמוּעָה הֵם:","אֵין הַלּוֹקֵחַ פָּטוּר אֶלָּא אִם כֵּן נִלְקַח אַחַר שֶׁנִּרְאָה לְהִתְעַשֵּׂר. לְפִיכָךְ הַלּוֹקֵחַ טְלָאִים בְּתוֹךְ שִׁבְעַת יְמֵי הַלֵּידָה כְּשֶׁיַּגִּיעַ זְמַנָּם חַיָּב לְעַשְּׂרָן. שֶׁכֵּיוָן שֶׁאֵין מְחֻסָּר זְמַן רָאוּי לְהִתְעַשֵּׂר הֲרֵי זֶה כְּמִי שֶׁלָּקַח עֻבָּרִים וְנוֹלְדוּ בִּרְשׁוּתוֹ:","כָּל בְּהֵמָה שֶׁהִיא סָפֵק אִם בַּת מַעֲשֵׂר הִיא אוֹ אֵינָהּ בַּת מַעֲשֵׂר. הֲרֵי הִיא פְּטוּרָה מִן הַמַּעֲשֵׂר. לְפִיכָךְ טְלָאִים שֶׁנִּתְעָרֵב בָּהֶן יָתוֹם אוֹ לָקוּחַ וְכַיּוֹצֵא בָּהֶן הֲרֵי כֻּלָּן פְּטוּרִין מִן הַמַּעֲשֵׂר. שֶׁכָּל אֶחָד מֵהֶן סָפֵק הוּא:"],"Mishneh Torah, Forbidden Foods 2":["מִכְּלָל שֶׁנֶּאֱמַר (דברים יד ו) \"וְכָל בְּהֵמָה מַפְרֶסֶת פַּרְסָה וְשֹׁסַעַת שֶׁסַע שְׁתֵּי פְרָסוֹת מַעֲלַת גֵּרָה\" שׁוֹמֵעַ אֲנִי שֶׁכָּל שֶׁאֵינָהּ מַעֲלַת גֵּרָה וּמַפְרֶסֶת פַּרְסָה אֲסוּרָה. וְלָאו הַבָּא מִכְּלַל עֲשֵׂה עֲשֵׂה הוּא. וּבְגָמָל וּבַחֲזִיר וּבְאַרְנֶבֶת וּבְשָׁפָן נֶאֱמַר (ויקרא יא ד) (דברים יד ז) \"אֶת זֶה לֹא תֹאכְלוּ מִמַּעֲלֵי הַגֵּרָה וּמִמַּפְרִיסֵי הַפַּרְסָה\" וְגוֹ' הֲרֵי לָמַדְתָּ שֶׁהֵן בְּלֹא תַּעֲשֶׂה וְאַף עַל פִּי שֶׁיֵּשׁ בָּהֶן סִימָן אֶחָד. וְכָל שֶׁכֵּן שְׁאָר בְּהֵמָה טְמֵאָה וְחַיָּה טְמֵאָה שֶׁאֵין בָּהּ סִימָן כְּלָל שֶׁאִסּוּר אֲכִילָתָם בְּלֹא תַּעֲשֶׂה יֶתֶר עַל עֲשֵׂה הַבָּא מִכְּלַל אוֹתָהּ תֹּאכְלוּ:","לְפִיכָךְ כָּל הָאוֹכֵל מִבְּשַׂר בְּהֵמָה וְחַיָּה טְמֵאָה כְּזַיִת לוֹקֶה מִן הַתּוֹרָה. בֵּין שֶׁאָכַל מִן הַבָּשָׂר בֵּין שֶׁאָכַל מִן הַחֵלֶב. לֹא חִלֵּק הַכָּתוּב בִּטְמֵאִים בֵּין בְּשָׂרָם לְחֶלְבָּם:","הָאָדָם אַף עַל פִּי שֶׁנֶּאֱמַר בּוֹ (בראשית ב ז) \"וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה\" אֵינוֹ מִכְּלַל מִינֵי חַיָּה בַּעֲלַת פַּרְסָה לְפִיכָךְ אֵינוֹ בְּלֹא תַּעֲשֶׂה. וְהָאוֹכֵל מִבְּשַׂר הָאָדָם אוֹ מֵחֶלְבּוֹ בֵּין מִן הַחַי בֵּין מִן הַמֵּת אֵינוֹ לוֹקֶה. אֲבָל אָסוּר הוּא בַּעֲשֵׂה שֶׁהֲרֵי מָנָה הַכָּתוּב שִׁבְעַת מִינֵי חַיָּה וְאָמַר בָּהֶן (ויקרא יא ב) \"זֹאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ\" הָא כָּל שֶׁהוּא חוּץ מֵהֶן לֹא תֹּאכְלוּ וְלָאו הַבָּא מִכְּלַל עֲשֵׂה עֲשֵׂה:","הָאוֹכֵל כְּזַיִת מִבְּשַׂר עוֹף טָמֵא לוֹקֶה מִן הַתּוֹרָה שֶׁנֶּאֱמַר (ויקרא יא יג) \"וְאֶת אֵלֶּה תְּשַׁקְּצוּ מִן הָעוֹף לֹא יֵאָכְלוּ\". וַהֲרֵי עָבַר עַל עֲשֵׂה שֶׁנֶּאֱמַר (דברים יד יא) \"כָּל צִפּוֹר טְהֹרָה תֹּאכֵלוּ\" הָא טְמֵאָה לֹא תֹּאכְלוּ. וְכֵן הָאוֹכֵל כְּזַיִת מִדָּג טָמֵא לוֹקֶה שֶׁנֶּאֱמַר (ויקרא יא יא) \"וְשֶׁקֶץ יִהְיוּ לָכֶם\" (ויקרא יא יא) \"מִבְּשָׂרָם לֹא תֹאכֵלוּ\". וְעָבַר עַל עֲשֵׂה שֶׁנֶּאֱמַר (דברים יד ט) \"כּל אֲשֶׁר לוֹ סְנַפִּיר וְקַשְׂקֶשֶׂת תֹּאכֵלוּ\" מִכְּלַל שֶׁמִּי שֶׁאֵין לוֹ סְנַפִּיר וְקַשְׂקֶשֶׂת לֹא יֵאָכֵל. הָא לָמַדְתָּ שֶׁכָּל הָאוֹכֵל דָּג טָמֵא אוֹ בְּהֵמָה וְחַיָּה טְמֵאָה אוֹ עוֹף טָמֵא בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר עַל לֹא תַּעֲשֶׂה:","חָגָב טָמֵא הֲרֵי הוּא בִּכְלַל שֶׁרֶץ הָעוֹף וְהָאוֹכֵל כְּזַיִת מִשֶּׁרֶץ הָעוֹף לוֹקֶה שֶׁנֶּאֱמַר (דברים יד יט) \"כָּל שֶׁרֶץ הָעוֹף טָמֵא הוּא לָכֶם לֹא יֵאָכֵלוּ\". וְאֵי זֶהוּ שֶׁרֶץ הָעוֹף כְּגוֹן זְבוּב אוֹ יַתּוּשׁ וְצִרְעָה וּדְבוֹרָה וְכַיּוֹצֵא בָּהֶן:","הָאוֹכֵל כְּזַיִת מִשֶּׁרֶץ הָאָרֶץ לוֹקֶה שֶׁנֶּאֱמַר (ויקרא יא מא) \"וְכָל הַשֶּׁרֶץ הַשֹּׁרֵץ עַל הָאָרֶץ שֶׁקֶץ הוּא לֹא יֵאָכֵל\". וְאֵי זֶהוּ שֶׁרֶץ הָאָרֶץ כְּגוֹן נְחָשִׁים וְעַקְרַבִּים וְחִפְשִׁית וְנַדָּל וְכַיּוֹצֵא בָּהֶן:","וּשְׁמוֹנָה שְׁרָצִים הָאֲמוּרִים בַּתּוֹרָה שֶׁהֵן (ויקרא יא כט) \"הַחלֶד וְהָעַכְבָּר וְהַצָּב\" (ויקרא יא ל) \"וְהָאֲנָקָה וְהַכֹּחַ וְהַלְּטָאָה וְהַחֹמֶט וְהַתִּנְשֶׁמֶת\" הָאוֹכֵל מִבְּשָׂרָם כַּעֲדָשָׁה לוֹקֶה. שִׁעוּר אֲכִילָתָן כְּשִׁעוּר טֻמְאָתָן. וְכֻלָּם מִצְטָרְפִין זֶה עִם זֶה בְּכַעֲדָשָׁה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁאָכַל מֵהֶן אַחַר מִיתָתָן. אֲבָל הַחוֹתֵךְ אֵיבָר מִן הַחַי מִן אֶחָד מֵהֶן וַאֲכָלוֹ אֵינוֹ לוֹקֶה עָלָיו עַד שֶׁיִּהְיֶה בּוֹ כְּזַיִת בָּשָׂר. וְכֻלָּן מִצְטָרְפִין לִכְזַיִת. אָכַל אֵיבָר שָׁלֵם מִן הַשֶּׁרֶץ אַחַר שֶׁמֵּת אֵינוֹ לוֹקֶה עַד שֶׁיִּהְיֶה בּוֹ כַּעֲדָשָׁה:","דַּם שְׁמוֹנָה שְׁרָצִים וּבְשָׂרָן מִצְטָרֵף לְכַעֲדָשָׁה וְהוּא שֶׁיִּהְיֶה הַדָּם מְחֻבָּר לַבָּשָׂר. וְכֵן דַּם הַנָּחָשׁ מִצְטָרֵף לִבְשָׂרוֹ לִכְזַיִת וְלוֹקֶה עָלָיו לְפִי שֶׁאֵין בְּשָׂרוֹ חָלוּק מִדָּמוֹ. וְאַף עַל פִּי שֶׁאֵינוֹ מְטַמֵּא. וְכֵן כָּל כַּיּוֹצֵא בּוֹ מִשְּׁאָר שְׁרָצִים שֶׁאֵינָן מְטַמְּאִין:","דַּם שְׁרָצִים שֶׁפָּרַשׁ וּכְנָסוֹ וַאֲכָלוֹ לוֹקֶה עָלָיו בִּכְזַיִת. וְהוּא שֶׁיַּתְרוּ בּוֹ מִשּׁוּם אוֹכֵל שֶׁרֶץ. אֲבָל אִם הִתְרוּ בּוֹ מִשּׁוּם אוֹכֵל דָּם פָּטוּר. שֶׁאֵין חַיָּבִין אֶלָּא עַל דַּם בְּהֵמָה חַיָּה וְעוֹף:","כָּל הַשִּׁעוּרִין וּמַחְלְקוֹתָם הֲלָכָה לְמשֶׁה מִסִּינַי:","הָאוֹכֵל כְּזַיִת מִשֶּׁרֶץ הַמַּיִם לוֹקֶה מִן הַתּוֹרָה שֶׁנֶּאֱמַר (ויקרא יא מג) \"אַל תְּשַׁקְּצוּ אֶת נַפְשֹׁתֵיכֶם בְּכָל הַשֶּׁרֶץ הַשֹּׁרֵץ וְלֹא תִטַּמְּאוּ בָּהֶם\". הֲרֵי כָּלַל בְּלָאו זֶה שֶׁרֶץ הָאָרֶץ וְשֶׁרֶץ הָעוֹף וְשֶׁרֶץ הַמַּיִם. אֵי זֶהוּ שֶׁרֶץ הַמַּיִם אֵלּוּ הַבְּרִיּוֹת הַקְּטַנּוֹת כְּמוֹ הַתּוֹלָעִים וְהָעֲלוּקָה שֶׁבַּמַּיִם וְהַבְּרִיּוֹת הַגְּדוֹלוֹת בְּיוֹתֵר שֶׁהֵן חַיּוֹת הַיָּם. כְּלָלוֹ שֶׁל דָּבָר כָּל שֶׁאֵינוֹ בְּצוּרַת הַדָּגִים לֹא דָּג טָמֵא וְלֹא דָּג טָהוֹר כְּגוֹן כֶּלֶב הַמַּיִם וְהַדַּלְפוֹן וְהַצְּפַרְדֵּעַ וְכַיּוֹצֵא בָּהֶן:","אֵלּוּ הַמִּינִין שֶׁנִּבְרָאִין בְּאַשְׁפּוֹת וּבְגוּפֵי הַנְּבֵלוֹת כְּגוֹן רִמָּה וְתוֹלַעַת וְכַיּוֹצֵא בָּהֶן שֶׁאֵינָן נִבְרָאִין מִזָּכָר וּנְקֵבָה אֶלָּא מִן הַגְּלָלִים שֶׁהִסְרִיחוּ וְכַיּוֹצֵא בָּהֶן הֵן הַנִּקְרָאִין רוֹמֵשׂ עַל הָאָרֶץ. וְהָאוֹכֵל מֵהֶן כְּזַיִת לוֹקֶה שֶׁנֶּאֱמַר (ויקרא יא מד) \"וְלֹא תְטַמְּאוּ אֶת נַפְשֹׁתֵיכֶם בְּכָל הַשֶּׁרֶץ הָרֹמֵשׂ עַל הָאָרֶץ\" וְאַף עַל פִּי שֶׁאֵין פָּרִין וְרָבִין. אֲבָל (ויקרא יא מא מב) \"הַשֶּׁרֶץ הַשּׁוֹרֵץ עַל הָאָרֶץ\" הוּא שֶׁפָּרֶה וְרָבֶה מִזָּכָר וּנְקֵבָה:","אֵלּוּ הַמִּינִין הַנִּבְרָאִין בְּפֵרוֹת וּבְמַאֲכָלוֹת אִם פָּרְשׁוּ וְיָצְאוּ לָאָרֶץ אַף עַל פִּי שֶׁחָזְרוּ לְתוֹךְ הָאֹכֶל מִי שֶׁאָכַל מֵהֶן כְּזַיִת לוֹקֶה שֶׁנֶּאֱמַר (ויקרא יא מב) \"לְכָל הַשֶּׁרֶץ הַשֹּׁרֵץ עַל הָאָרֶץ\" לֶאֱסֹר אֵלּוּ שֶׁפָּרְשׁוּ לָאָרֶץ. אֲבָל אִם לֹא פָּרְשׁוּ מֻתָּר לֶאֱכל הַפְּרִי וְהַתּוֹלַעַת שֶׁבְּתוֹכוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהִתְלִיעַ הָאֹכֶל אַחַר שֶׁנֶּעֱקַר מִן הָאָרֶץ. אֲבָל אִם הִתְלִיעַ וְהוּא מְחֻבָּר. אוֹתָהּ הַתּוֹלַעַת אֲסוּרָה כְּאִלּוּ פֵּרְשָׁה לָאָרֶץ שֶׁעַל הָאָרֶץ נִבְרֵאת וְלוֹקִין עָלֶיהָ. וְאִם סָפֵק אֲסוּרָה. לְפִיכָךְ כָּל מִינֵי פֵּרוֹת שֶׁדַּרְכָּן לְהַתְלִיעַ כְּשֶׁהֵן מְחֻבָּרִין לֹא יֹאכַל עַד שֶׁיִּבְדֹּק הַפְּרִי מִתּוֹכוֹ שֶׁמָּא יֵשׁ בּוֹ תּוֹלַעַת. וְאִם שָׁהָה הַפְּרִי אַחַר שֶׁנֶּעֱקַר שְׁנֵים עָשָׂר חֹדֶשׁ אוֹכֵל בְּלֹא בְּדִיקָה שֶׁאֵין תּוֹלַעַת שֶׁבּוֹ מִתְקַיֶּמֶת שְׁנֵים עָשָׂר חֹדֶשׁ:","פָּרְשׁוּ לָאֲוִיר וְלֹא נָגְעוּ לָאָרֶץ. אוֹ שֶׁפָּרְשׁוּ מִקְצָתָן לָאָרֶץ. אוֹ שֶׁפָּרְשׁוּ אַחַר שֶׁמֵּתוּ. אוֹ שֶׁנִּמְצֵאת תּוֹלַעַת עַל הַגַּרְעִינָה מִבִּפְנִים. אוֹ שֶׁיָּצְאוּ מִתּוֹךְ הָאֹכֶל לְתוֹךְ אֹכֶל אַחֵר. כָּל אֵלּוּ אֲסוּרִין מִסָּפֵק וְאֵין לוֹקִין עֲלֵיהֶן:","תּוֹלַעַת הַנִּמְצֵאת בִּמְעֵי הַדָּגִים וּבַמֹּחַ שֶׁבְּרֹאשׁ הַבְּהֵמָה וְהַנִּמְצֵאת בַּבָּשָׂר אֲסוּרָה. אֲבָל דָּג מָלִיחַ שֶׁהִתְלִיעַ הֲרֵי הַתּוֹלַעַת שֶׁבּוֹ מֻתֶּרֶת. שֶׁהֵן כְּפֵרוֹת שֶׁהִתְלִיעוּ אַחַר שֶׁנֶּעֶקְרוּ מִן הָאָרֶץ שֶׁמֻּתָּר לְאָכְלָן כֻּלָּן כְּאַחַת בַּתּוֹלַעַת שֶׁבְּתוֹכָן. וְכֵן הַמַּיִם שֶׁבַּכֵּלִים שֶׁהִשְׁרִיצוּ הֲרֵי אוֹתָן שְׁרָצִים מֻתָּר לִשְׁתּוֹתָן עִם הַמַּיִם שֶׁנֶּאֱמַר (ויקרא יא ט) \"וְכָל אֲשֶׁר לוֹ סְנַפִּיר וְקַשְׂקֶשֶׂת בַּמַּיִם בַּיַּמִּים וּבַנְּחָלִים אֹתָם תֹּאכֵלוּ\". כְּלוֹמַר בַּמַּיִם וּבַיַּמִּים וּבַנְּחָלִים הוּא שֶׁאַתָּה אוֹכֵל אֶת שֶׁיֵּשׁ לוֹ וְאֵין אַתָּה אוֹכֵל אֶת שֶׁאֵין לוֹ. אֲבָל בְּכֵלִים בֵּין שֶׁיֵּשׁ לוֹ בֵּין שֶׁאֵין לוֹ מֻתָּר:","שֶׁרֶץ הַמַּיִם הַנִּבְרָא בְּבוֹרוֹת וּבְשִׁיחִין וּבִמְעָרוֹת הוֹאִיל וְאֵינָן מַיִם נוֹבְעִין וַהֲרֵי הֵן עֲצוּרִים הֲרֵי הֵן כְּמַיִם שֶׁבְּכֵלִים וּמֻתָּר. וְשׁוֹחֶה וְשׁוֹתֶה וְאֵינוֹ נִמְנָע וְאַף עַל פִּי שֶׁבּוֹלֵעַ בִּשְׁעַת שְׁתִיָּה מֵאוֹתָן הַשְּׁרָצִים הַדַּקִּים:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא פָּרְשׁוּ מִמְּקוֹם בְּרִיָּתָן. אֲבָל אִם פֵּרַשׁ הַשֶּׁרֶץ אַף עַל פִּי שֶׁחָזַר לְתוֹךְ הַכְּלִי אוֹ לְתוֹךְ הַבּוֹר אָסוּר. פָּרַשׁ לְדָפְנֵי הֶחָבִית וְחָזַר וְנָפַל לְתוֹךְ הַמַּיִם אוֹ לְתוֹךְ הַשֵּׁכָר מֻתָּר. וְכֵן אִם פָּרַשׁ לְדָפְנֵי הַבּוֹר אוֹ הַמְּעָרָה וְחָזַר לַמַּיִם מֻתָּר:","הַמְסַנֵּן אֶת הַיַּיִן אוֹ אֶת הַחֹמֶץ אוֹ אֶת הַשֵּׁכָר וְאָכַל אֶת הַיַּבְחוּשִׁים אוֹ אֶת הַיַּתּוּשִׁין וְהַתּוֹלָעוֹת שֶׁסִּנֵּן לוֹקֶה מִשּׁוּם שֶׁרֶץ הַמַּיִם אוֹ מִשּׁוּם שֶׁרֶץ הָעוֹף (וְשֶׁרֶץ הַמַּיִם) אֲפִלּוּ חָזַר לַכְּלִי אַחַר שֶׁסִּנְּנָן שֶׁהֲרֵי פָּרְשׁוּ מִמְּקוֹם בְּרִיָּתָן. אֲבָל אִם לֹא סִנְּנָן שׁוֹתֶה וְאֵינוֹ נִמְנָע כְּמוֹ שֶׁפֵּרַשְׁנוּ:","זֶה שֶׁאָמַרְנוּ בְּפֶרֶק זֶה הָאוֹכֵל כְּזַיִת. כְּשֶׁאָכַל כְּזַיִת מִבְּרִיָּה גְּדוֹלָה אוֹ שֶׁצֵּרֵף מְעַט מִבְּרִיָּה זוֹ וּמְעַט מִבְּרִיָּה זוֹ שֶׁבְּמִינָהּ עַד שֶׁיֹּאכַל כְּזַיִת. אֲבָל הָאוֹכֵל בְּרִיָּה טְמֵאָה בִּפְנֵי עַצְמָהּ כֻּלָּהּ הֲרֵי זֶה לוֹקֶה מִן הַתּוֹרָה. וַאֲפִלּוּ הָיְתָה פְּחוּתָה מִן הַחַרְדָּל. בֵּין שֶׁאֲכָלָהּ מֵתָה בֵּין שֶׁאֲכָלָהּ חַיָּה. וַאֲפִלּוּ סָרְחָה הַבְּרִיָּה וְנִשְׁתַּנֵּית צוּרָתָהּ הוֹאִיל וַאֲכָלָהּ כֻּלָּהּ לוֹקֶה:","נְמָלָה שֶׁחֲסֵרָה אֲפִלּוּ אַחַת מֵרַגְלֶיהָ אֵינוֹ לוֹקֶה עָלֶיהָ אֶלָּא בִּכְזַיִת. לְפִיכָךְ הָאוֹכֵל זְבוּב שָׁלֵם אוֹ יַתּוּשׁ שָׁלֵם בֵּין חַי וּבֵין מֵת לוֹקֶה מִשּׁוּם שֶׁרֶץ הָעוֹף:","הֲרֵי שֶׁהָיְתָה הַבְּרִיָּה מִשֶּׁרֶץ הָעוֹף וּמִשֶּׁרֶץ הַמַּיִם וּמִשֶּׁרֶץ הָאָרֶץ כְּגוֹן שֶׁהָיוּ לָהּ כְּנָפַיִם וְהִיא מְהַלֶּכֶת עַל הָאָרֶץ כִּשְׁאָר שְׁרָצִים וְהָיְתָה רָבָה בַּמַּיִם וַאֲכָלָהּ לוֹקֶה שָׁלֹשׁ מַלְקִיּוֹת. וְאִם הָיְתָה יֶתֶר עַל זֶה מִן הַמִּינִין שֶׁנִּבְרְאוּ בְּפֵרוֹת לוֹקֶה עָלֶיהָ אַרְבַּע מַלְקִיּוֹת. וְאִם הָיְתָה מִן הַמִּינִין שֶׁפָּרִין וְרָבִין לוֹקֶה חָמֵשׁ. וְאִם הָיְתָה מִכְּלַל עוֹף טָמֵא יֶתֶר עַל הֱיוֹתָהּ מִשֶּׁרֶץ הָעוֹף לוֹקֶה עָלֶיהָ שֵׁשׁ מַלְקִיּוֹת. מִשּׁוּם עוֹף טָמֵא. וּמִשּׁוּם שֶׁרֶץ הָעוֹף. וּמִשּׁוּם שֶׁרֶץ הָאָרֶץ. וּמִשּׁוּם שֶׁרֶץ הַמַּיִם. וּמִשּׁוּם רוֹמֵשׂ עַל הָאָרֶץ. וּמִשּׁוּם תּוֹלַעַת הַפֵּרוֹת. בֵּין שֶׁאֲכָלָהּ כֻּלָּהּ בֵּין שֶׁאָכַל מִמֶּנָּה כְּזַיִת. לְפִיכָךְ הָאוֹכֵל נְמָלָה הַפּוֹרַחַת הַגְּדֵלָה בַּמַּיִם לוֹקֶה חָמֵשׁ מַלְקִיּוֹת:","רִסֵּק נְמָלִים וְהֵבִיא אַחַת שְׁלֵמָה וְצֵרְפָהּ לְאֵלּוּ שֶׁנִּתְרַסְּקוּ וְנַעֲשָׂה הַכּל כְּזַיִת וַאֲכָלוֹ לוֹקֶה שֵׁשׁ מַלְקִיּוֹת. חָמֵשׁ מִשּׁוּם הַנְּמָלָה הָאַחַת וְאַחַת מִשּׁוּם כְּזַיִת מִנִּבְלַת הַטְּמֵאִים:"],"Mishneh Torah, Forbidden Intercourse 13":["בִשְׁלֹשָׁה דְּבָרִים נִכְנְסוּ יִשְׂרָאֵל לִבְרִית. בְּמִילָה וּטְבִילָה וְקָרְבָּן:","מִילָה הָיְתָה בְּמִצְרַיִם שֶׁנֶּאֱמַר (שמות יב מח) \"וְכָל עָרֵל לֹא יֹאכַל בּוֹ\". מָל אוֹתָם משֶׁה רַבֵּנוּ שֶׁכֻּלָּם בִּטְּלוּ בְּרִית מִילָה בְּמִצְרַיִם חוּץ מִשֵּׁבֶט לֵוִי וְעַל זֶה נֶאֱמַר (דברים לג ט) \"וּבְרִיתְךָ יִנְצֹרוּ\":","וּטְבִילָה הָיְתָה בַּמִּדְבָּר קֹדֶם מַתַּן תּוֹרָה שֶׁנֶּאֱמַר (שמות יט י) \"וְקִדַּשְׁתָּם הַיּוֹם וּמָחָר וְכִבְּסוּ שִׂמְלֹתָם\". וְקָרְבָּן שֶׁנֶּאֱמַר (שמות כד ה) \"וַיִּשְׁלַח אֶת נַעֲרֵי בְּנֵי יִשְׂרָאֵל וַיַּעֲלוּ עלֹת\", עַל יְדֵי כָּל יִשְׂרָאֵל הִקְרִיבוּם:","וְכֵן לְדוֹרוֹת כְּשֶׁיִּרְצֶה הָעַכּוּ\"ם לְהִכָּנֵס לִבְרִית וּלְהִסְתּוֹפֵף תַּחַת כַּנְפֵי הַשְּׁכִינָה וִיקַבֵּל עָלָיו עֹל תּוֹרָה צָרִיךְ מִילָה וּטְבִילָה וְהַרְצָאַת קָרְבָּן. וְאִם נְקֵבָה הִיא טְבִילָה וְקָרְבָּן שֶׁנֶּאֱמַר (במדבר טו טו) \"כָּכֶם כַּגֵּר\". מָה אַתֶּם בְּמִילָה וּטְבִילָה וְהַרְצָאַת קָרְבָּן אַף הַגֵּר לְדוֹרוֹת בְּמִילָה וּטְבִילָה וְהַרְצָאַת קָרְבָּן:","וּמַהוּ קָרְבַּן הַגֵּר. עוֹלַת בְּהֵמָה אוֹ שְׁתֵּי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה וּשְׁנֵיהֶם עוֹלָה. וּבַזְּמַן הַזֶּה שֶׁאֵין שָׁם קָרְבָּן צָרִיךְ מִילָה וּטְבִילָה וּכְשֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ יָבִיא קָרְבָּן:","גֵּר שֶׁמָּל וְלֹא טָבַל אוֹ טָבַל וְלֹא מָל אֵינוֹ גֵּר עַד שֶׁיָּמוּל וְיִטְבּל. וְצָרִיךְ לִטְבּל בִּפְנֵי שְׁלֹשָׁה. וְהוֹאִיל וְהַדָּבָר צָרִיךְ בֵּית דִּין אֵין מַטְבִּילִין אוֹתוֹ בְּשַׁבָּת וְלֹא בְּיוֹם טוֹב וְלֹא בַּלַּיְלָה. וְאִם הִטְבִּילוּהוּ הֲרֵי זֶה גֵּר:","גֵּר קָטָן מַטְבִּילִין אוֹתוֹ עַל דַּעַת בֵּית דִּין שֶׁזְּכוּת הִיא לוֹ. מְעֻבֶּרֶת שֶׁנִּתְגַּיְּרָה וְטָבְלָה אֵין בְּנָהּ צָרִיךְ טְבִילָה. טָבַל בֵּינוֹ לְבֵין עַצְמוֹ וְנִתְגַּיֵּר בֵּינוֹ לְבֵין עַצְמוֹ וַאֲפִלּוּ בִּפְנֵי שְׁנַיִם אֵינוֹ גֵּר. בָּא וְאָמַר נִתְגַּיַּרְתִּי בְּבֵית דִּינוֹ שֶׁל פְּלוֹנִי וְהִטְבִּילוּנִי אֵינוֹ נֶאֱמָן לָבֹא בַּקָּהָל עַד שֶׁיָּבִיא עֵדִים:","הָיָה נָשׂוּי לְיִשְׂרְאֵלִית אוֹ לְגִיֹּרֶת וְיֵשׁ לוֹ בָּנִים וְאָמַר נִתְגַּיַּרְתִּי בֵּינִי לְבֵין עַצְמִי נֶאֱמָן לִפְסל אֶת עַצְמוֹ וְאֵינוֹ נֶאֱמָן לִפְסל אֶת הַבָּנִים. וְחוֹזֵר וְטוֹבֵל בְּבֵית דִּין:","גִּיֹּרֶת שֶׁרְאִינוּהָ נוֹהֶגֶת בְּדַרְכֵי יִשְׂרָאֵל תָּמִיד כְּגוֹן שֶׁתִּטְבּל לְנִדָּתָהּ וְתַפְרִישׁ תְּרוּמָה מֵעִסָּתָהּ וְכַיּוֹצֵא בָּזֶה. וְכֵן גֵּר שֶׁנּוֹהֵג בְּדַרְכֵי יִשְׂרָאֵל שֶׁטּוֹבֵל לְקִרְיוֹ וְעוֹשֶׂה כָּל הַמִּצְוֹת. הֲרֵי אֵלּוּ בְּחֶזְקַת גֵּרֵי צֶדֶק. וְאַף עַל פִּי שֶׁאֵין שָׁם עֵדִים שֶׁמְּעִידִין לִפְנֵי מִי שֶׁנִּתְגַּיְּרוּ. וְאַף עַל פִּי כֵן אִם בָּאוּ לְהִתְעָרֵב בְּיִשְׂרָאֵל אֵין מַשִּׂיאִין אוֹתָם עַד שֶׁיָּבִיאוּ עֵדִים אוֹ עַד שֶׁיִּטְבְּלוּ בְּפָנֵינוּ הוֹאִיל וְהֻחְזְקוּ עַכּוּ\"ם:","אֲבָל מִי שֶׁבָּא וְאָמַר שֶׁהָיָה עַכּוּ\"ם וְנִתְגַּיֵּר בְּבֵית דִּין נֶאֱמָן. שֶׁהַפֶּה שֶׁאָסַר הוּא הַפֶּה שֶׁהִתִּיר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאֶרֶץ יִשְׂרָאֵל וּבְאוֹתָן הַיָּמִים שֶׁחֶזְקַת הַכּל שָׁם בְּחֶזְקַת יִשְׂרָאֵל. אֲבָל בְּחוּצָה לָאָרֶץ צָרִיךְ לְהָבִיא רְאָיָה וְאַחַר כָּךְ יִשָּׂא יִשְׂרְאֵלִית. וַאֲנִי אוֹמֵר שֶׁזּוֹ מַעֲלָה בְּיוּחֲסִין:","כְּשֵׁם שֶׁמָּלִין וּמַטְבִּילִין אֶת הַגֵּרִים כָּךְ מָלִין וּמַטְבִּילִין אֶת הָעֲבָדִים הַנִּלְקָחִים מִן הָעַכּוּ\"ם לְשֵׁם עַבְדוּת. הַלּוֹקֵחַ עֶבֶד מִן הָעַכּוּ\"ם וְקָדַם הָעֶבֶד וְטָבַל לְשֵׁם בֶּן חוֹרִין קָנָה עַצְמוֹ. וְהוּא שֶׁיֹּאמַר בְּעֵת טְבִילָה הֲרֵינִי טוֹבֵל בִּפְנֵיכֶם לְשֵׁם גֵּרוּת. וְאִם טָבַל בִּפְנֵי רַבּוֹ אֵינוֹ צָרִיךְ לְפָרֵשׁ אֶלָּא כֵּיוָן שֶׁטָּבַל נִשְׁתַּחְרֵר. לְפִיכָךְ צָרִיךְ רַבּוֹ לְתָקְפּוֹ בַּמַּיִם עַד שֶׁיַּעֲלֶה וְהוּא תַּחַת שִׁעְבּוּדוֹ וּמוֹדִיעוֹ בִּפְנֵי הַדַּיָּנִין שֶׁלְּשֵׁם עַבְדוּת מַטְבִּילוֹ. וְאֵין הָעֶבֶד טוֹבֵל אֶלָּא בִּפְנֵי שְׁלֹשָׁה וּבַיּוֹם כְּגֵר, שֶׁמִּקְצָת גֵּרוּת הוּא:","כְּשֶׁיִּשְׁתַּחְרֵר הָעֶבֶד צָרִיךְ טְבִילָה אַחֶרֶת בִּפְנֵי שְׁלֹשָׁה בַּיּוֹם שֶׁבּוֹ תִּגָּמֵר גֵּרוּתוֹ וְיִהְיֶה כְּיִשְׂרָאֵל. וְאֵין צָרִיךְ לְקַבֵּל עָלָיו מִצְוֹת וּלְהוֹדִיעוֹ עִקְּרֵי הַדָּת שֶׁכְּבָר הוֹדִיעוּהוּ כְּשֶׁטָּבַל לְשֵׁם עַבְדוּת:","וּבְמִקְוֶה הַכָּשֵׁר לִטְבִילַת נִדָּה שָׁם מַטְבִּילִין אֶת הַגֵּרִים וְאֶת הָעֲבָדִים וְאֶת הַמְשֻׁחְרָרִים. וְכָל דָּבָר שֶׁחוֹצֵץ בְּנִדָּה חוֹצֵץ בְּגֵרִים וּבַעֲבָדִים וּבִמְשֻׁחְרָרִים:","אַל יַעֲלֶה עַל דַּעְתְּךָ שֶׁשִּׁמְשׁוֹן הַמּוֹשִׁיעַ אֶת יִשְׂרָאֵל אוֹ שְׁלֹמֹה מֶלֶךְ יִשְׂרָאֵל שֶׁנִּקְרָא יְדִיד ה' נָשְׂאוּ נָשִׁים נָכְרִיּוֹת בְּגֵיוּתָן. אֶלָּא סוֹד הַדָּבָר כָּךְ הוּא. שֶׁהַמִּצְוָה הַנְּכוֹנָה כְּשֶׁיָּבֹא הַגֵּר אוֹ הַגִּיֹּרֶת לְהִתְגַּיֵּר בּוֹדְקִין אַחֲרָיו שֶׁמָּא בִּגְלַל מָמוֹן שֶׁיִּטּל אוֹ בִּשְׁבִיל שְׂרָרָה שֶׁיִּזְכֶּה לָהּ אוֹ מִפְּנֵי הַפַּחַד בָּא לְהִכָּנֵס לַדָּת. וְאִם אִישׁ הוּא בּוֹדְקִין אַחֲרָיו שֶׁמָּא עֵינָיו נָתַן בְּאִשָּׁה יְהוּדִית. וְאִם אִשָּׁה הִיא בּוֹדְקִין שֶׁמָּא עֵינֶיהָ נָתְנָה בְּבָחוּר מִבַּחוּרֵי יִשְׂרָאֵל. אִם לֹא נִמְצָא לָהֶם עִלָּה מוֹדִיעִין אוֹתָן כֹּבֶד עֹל הַתּוֹרָה וְטֹרַח שֶׁיֵּשׁ בַּעֲשִׂיָּתָהּ עַל עַמֵּי הָאֲרָצוֹת כְּדֵי שֶׁיִּפְרשׁוּ. אִם קִבְּלוּ וְלֹא פֵּרְשׁוּ וְרָאוּ אוֹתָן שֶׁחָזְרוּ מֵאַהֲבָה מְקַבְּלִים אוֹתָן שֶׁנֶּאֱמַר (רות א יח) \"וַתֵּרֶא כִּי מִתְאַמֶּצֶת הִיא לָלֶכֶת אִתָּהּ וַתֶּחְדַּל לְדַבֵּר אֵלֶיהָ\":","לְפִיכָךְ לֹא קִבְּלוּ בֵּית דִּין גֵּרִים כָּל יְמֵי דָּוִד וּשְׁלֹמֹה. בִּימֵי דָּוִד שֶׁמָּא מִן הַפַּחַד חָזְרוּ. וּבִימֵי שְׁלֹמֹה שֶׁמָּא בִּשְׁבִיל הַמַּלְכוּת וְהַטּוֹבָה וְהַגְּדֻלָּה שֶׁהָיוּ בָּהּ יִשְׂרָאֵל חָזְרוּ. שֶׁכָּל הַחוֹזֵר מִן הָעַכּוּ\"ם בִּשְׁבִיל דָּבָר מֵהַבְלֵי הָעוֹלָם אֵינוֹ מִגֵּרֵי הַצֶּדֶק. וְאַף עַל פִּי כֵן הָיוּ גֵּרִים הַרְבֵּה מִתְגַּיְּרִים בִּימֵי דָּוִד וּשְׁלֹמֹה בִּפְנֵי הֶדְיוֹטוֹת. וְהָיוּ בֵּית דִּין הַגָּדוֹל חוֹשְׁשִׁין לָהֶם לֹא דּוֹחִין אוֹתָן אַחַר שֶׁטָּבְלוּ מִכָּל מָקוֹם וְלֹא מְקָרְבִין אוֹתָן עַד שֶׁתֵּרָאֶה אַחֲרִיתָם:","וּלְפִי שֶׁגִּיֵּר שְׁלֹמֹה נָשִׁים וּנְשָׂאָן. וְכֵן שִׁמְשׁוֹן גִּיֵּר וְנָשָׂא. וְהַדָּבָר יָדוּעַ שֶׁלֹּא חָזְרוּ אֵלּוּ אֶלָּא בִּשְׁבִיל דָּבָר וְלֹא עַל פִּי בֵּית דִּין גִּיְּרוּם חֲשָׁבָן הַכָּתוּב כְּאִלּוּ הֵן עַכּוּ\"ם וּבְאִסּוּרָן עוֹמְדִין. וְעוֹד שֶׁהוֹכִיחַ סוֹפָן עַל תְּחִלָּתָן שֶׁהֵן עוֹבְדוֹת כּוֹכָבִים וּמַזָּלוֹת שֶׁלָּהֶן וּבָנוּ לָהֶן בָּמוֹת וְהֶעֱלָה עָלָיו הַכָּתוּב כְּאִלּוּ הוּא בְּנָאָן שֶׁנֶּאֱמַר (מלכים א יא ז) \"אָז יִבְנֶה שְׁלֹמֹה בָּמָה\":","גֵּר שֶׁלֹּא בָּדְקוּ אַחֲרָיו אוֹ שֶׁלֹּא הוֹדִיעוּהוּ הַמִּצְוֹת וְעָנְשָׁן וּמָל וְטָבַל בִּפְנֵי שְׁלֹשָׁה הֶדְיוֹטוֹת הֲרֵי זֶה גֵּר. אֲפִלּוּ נוֹדַע שֶׁבִּשְׁבִיל דָּבָר הוּא מִתְגַּיֵּר הוֹאִיל וּמָל וְטָבַל יָצָא מִכְּלַל הָעַכּוּ\"ם וְחוֹשְׁשִׁין לוֹ עַד שֶׁיִּתְבָּאֵר צִדְקוּתוֹ. וַאֲפִלּוּ חָזַר וְעָבַד עֲבוֹדָה זָרָה הֲרֵי הוּא כְּיִשְׂרָאֵל מוּמָר שֶׁקִּדּוּשָׁיו קִדּוּשִׁין. וּמִצְוָה לְהַחֲזִיר אֲבֵדָתוֹ מֵאַחַר שֶׁטָּבַל נַעֲשָׂה כְּיִשְׂרָאֵל. וּלְפִיכָךְ קִיְּמוּ שִׁמְשׁוֹן וּשְׁלֹמֹה נְשׁוֹתֵיהֶן וְאַף עַל פִּי שֶׁנִּגְלָה סוֹדָן:","וּמִפְּנֵי זֶה אָמְרוּ חֲכָמִים קָשִׁים לָהֶם גֵּרִים לְיִשְׂרָאֵל כְּנֶגַע צָרַעַת שֶׁרֻבָּן חוֹזְרִין בִּשְׁבִיל דָּבָר וּמַטְעִין אֶת יִשְׂרָאֵל. וְקָשֶׁה הַדָּבָר לִפְרשׁ מֵהֶם אַחַר שֶׁנִּתְגַּיְּרוּ. צֵא וּלְמַד מָה אֵרַע בַּמִּדְבָּר בְּמַעֲשֵׂה הָעֵגֶל וּבְקִבְרוֹת הַתַּאֲוָה וְכֵן רֹב הַנִּסְיוֹנוֹת הָאֲסַפְסוּף הָיוּ בָּהֶן תְּחִלָּה:"],"Mishneh Torah, Forbidden Intercourse 4":["הַנִּדָה הֲרֵי הִיא כִּשְׁאָר כָּל הָעֲרָיוֹת. הַמְעָרֶה בָּהּ [בֵּין כְּדַרְכָּהּ בֵּין שֶׁלֹּא כְּדַרְכָּהּ] חַיָּב כָּרֵת וַאֲפִלּוּ הָיְתָה קְטַנָּה בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד כִּשְׁאָר עֲרָיוֹת שֶׁהַבַּת מִתְטַמְּאָה בְּנִדָּה וַאֲפִלּוּ בְּיוֹם לֵדָתָהּ. וּבַת עֲשָׂרָה יָמִים מְטַמְּאָה בְּזִיבָה וְדָבָר זֶה מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵין הֶפְרֵשׁ בֵּין גְּדוֹלָה לִקְטַנָּה לְטֻמְאַת נִדּוֹת וְזָבוֹת:","וְאֶחָד הַבָּא עַל הַנִּדָּה כָּל שִׁבְעַת הַיָּמִים וַאֲפִלּוּ לֹא רָאֲתָה אֶלָּא יוֹם רִאשׁוֹן. וְאֶחָד הַבָּא עַל יוֹלֶדֶת זָכָר כָּל שִׁבְעָה אוֹ עַל יוֹלֶדֶת נְקֵבָה כָּל אַרְבָּעָה עָשָׂר. אוֹ עַל הַזָּבָה כָּל יְמֵי זוֹבָהּ וּסְפִירָתָהּ. בֵּין שִׁפְחָה בֵּין מְשֻׁחְרֶרֶת הַכֹּל בְּכָרֵת שֶׁנֶּאֱמַר בְּנִדָּה (ויקרא טו יט) \"שִׁבְעַת יָמִים תִּהְיֶה בְּנִדָּתָהּ\". וּבְזָבָה נֶאֱמַר (ויקרא טו כה) \"כָּל יְמֵי זוֹב טֻמְאָתָהּ כִּימֵי נִדָּתָהּ תִּהְיֶה\". וּבְיוֹלֶדֶת זָכָר הוּא אוֹמֵר (ויקרא יב ב) \"כִּימֵי נִדַּת דְּוֹתָהּ תִּטְמָא\". וּבְיוֹלֶדֶת נְקֵבָה (ויקרא יב ה) \"וְטָמְאָה שְׁבֻעַיִם כְּנִדָּתָהּ\":","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהַטֻּמְאָה תְּלוּיָה בְּיָמִים בְּשֶׁטָּבְלָה בְּמֵי מִקְוֶה אַחַר הַיָּמִים הַסְּפוּרִים. אֲבָל נִדָּה וְזָבָה וְיוֹלֶדֶת שֶׁלֹּא טָבְלוּ בְּמֵי מִקְוֶה הַבָּא עַל אַחַת מֵהֶן אֲפִלּוּ אַחַר כַּמָּה שָׁנִים חַיָּב כָּרֵת. שֶׁבְּיָמִים וּטְבִילָה תָּלָה הַכָּתוּב שֶׁנֶּאֱמַר (ויקרא טו יח) \"וְרַחֲצוּ בַמַּיִם\" זֶה בִּנְיַן אָב לְכָל טָמֵא שֶׁהוּא בְּטֻמְאָתוֹ עַד שֶׁיִּטְבֹּל:","הָעַכּוּ\"ם אֵין חַיָּבִין עֲלֵיהֶם מִשּׁוּם נִדָּה וְלֹא מִשּׁוּם זָבָה וְלֹא מִשּׁוּם יוֹלֶדֶת. וַחֲכָמִים גָּזְרוּ עַל כָּל הָעַכּוּ\"ם הַזְּכָרִים וְהַנְּקֵבוֹת שֶׁיְּהוּ כְּזָבִים תָּמִיד בֵּין רָאוּ בֵּין לֹא רָאוּ לְעִנְיַן טֻמְאָה וְטָהֳרָה:","כָּל דָּם שֶׁתִּרְאֶה הַיּוֹלֶדֶת בְּתוֹךְ ל\"ג שֶׁל זָכָר וְס\"ו שֶׁל נְקֵבָה הוּא הַנִּקְרָא דַּם טֹהַר. וְאֵין מוֹנֵעַ אֶת הָאִשָּׁה מִבַּעְלָהּ אֶלָּא טוֹבֶלֶת אַחַר שִׁבְעָה לְזָכָר וְאַחַר אַרְבָּעָה עָשָׂר לִנִקֵבָה וּמִשַׁמֵּשֵׁת מִטָּתָהּ אַף עַל פִּי שֶׁהַדָּם שׁוֹתֵת וְיוֹרֵד:","כָּל חַיָּבֵי טְבִילוֹת טְבִילָתָן בַּיּוֹם חוּץ מִנִּדָּה וְיוֹלֶדֶת שֶׁהֲרֵי הוּא אוֹמֵר בְּנִדָּה (ויקרא טו יט) \"שִׁבְעַת יָמִים תִּהְיֶה בְּנִדָּתָהּ\". הַשִּׁבְעָה כֻּלָּן בְּנִדָּתָהּ וְטוֹבֶלֶת בְּלֵיל שְׁמִינִי. וְכֵן יוֹלֶדֶת זָכָר בְּלֵיל שְׁמִינִי וְיוֹלֶדֶת נְקֵבָה בְּלֵיל חֲמִשָּׁה עָשָׂר. שֶׁהַיּוֹלֶדֶת כְּנִדָּה כְּמוֹ שֶׁבֵּאַרְנוּ:","נִתְאַחֲרָה יָמִים רַבִּים וְלֹא טָבְלָה כְּשֶׁתִּטְבֹּל לֹא תִּטְבֹּל אֶלָּא בַּלַּיְלָה שֶׁאִם תִּטְבֹּל בַּיּוֹם יִטְעוּ וְתָבוֹא נִדָּה אַחֶרֶת לִטְבֹּל בִּשְׁבִיעִי:","הָיְתָה חוֹלָה אוֹ שֶׁהָיָה מְקוֹם הַטְּבִילָה רָחוֹק וְאֵין הַנָּשִׁים יְכוֹלוֹת לְהַגִּיעַ לוֹ וְלַחֲזֹר בַּלַּיְלָה מִפְּנֵי הַלִּסְטִים אוֹ מִפְּנֵי הַצִּנָּה אוֹ מִפְּנֵי שֶׁנּוֹעֲלִין שַׁעֲרֵי הַמְּדִינָה בַּלַּיְלָה הֲרֵי זוֹ טוֹבֶלֶת בַּיּוֹם הַשְּׁמִינִי אוֹ בַּיָּמִים שֶׁל אַחֲרָיו בַּיּוֹם:","כָּל הַנָּשִׁים שֶׁיֵּשׁ לָהֶן וֶסֶת בְּחֶזְקַת טָהֳרָה לְבַעְלֵיהֶן עַד שֶׁתֹּאמַר לוֹ טְמֵאָה אֲנִי אוֹ עַד שֶׁתֻּחְזַק נִדָּה בִּשְׁכֵנוֹתֶיהָ. הָלַךְ בַּעְלָהּ לִמְדִינָה אַחֶרֶת וֶהֱנִיחָהּ טְהוֹרָה כְּשֶׁיָּבוֹא אֵינוֹ צָרִיךְ לִשְׁאֹל לָהּ אֲפִלּוּ מְצָאָהּ יְשֵׁנָה הֲרֵי זֶה מֻתָּר לָבוֹא עָלֶיהָ שֶׁלֹּא בְּעוֹנַת וִסְתָּהּ וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא נִדָּה הִיא. וְאִם הֱנִיחָהּ נִדָּה אֲסוּרָה לוֹ עַד שֶׁתֹּאמַר לוֹ טְהוֹרָה אֲנִי:","הָאִשָּׁה שֶׁאָמְרָה לְבַעְלָהּ טְמֵאָה אֲנִי וְחָזְרָה וְאָמְרָה טְהוֹרָה אֲנִי וְדֶרֶךְ שְׂחוֹק אָמַרְתִּי לְךָ תְּחִלָּה אֵינָהּ נֶאֱמֶנֶת. וְאִם נָתְנָה אֲמַתְלָא לִדְבָרֶיהָ נֶאֱמֶנֶת. כֵּיצַד. תְּבָעָהּ בַּעְלָהּ וַאֲחוֹתוֹ אוֹ אִמּוֹ עִמָּהּ בֶּחָצֵר וְאָמְרָה טְמֵאָה אֲנִי וְאַחַר כָּךְ חָזְרָה וְאָמְרָה טְהוֹרָה אֲנִי וְלֹא אָמַרְתִּי לְךָ טְמֵאָה אֶלָּא מִפְּנֵי אֲחוֹתְךָ וְאִמְּךָ שֶׁמָּא יִרְאוּ אוֹתָנוּ הֲרֵי זוֹ נֶאֱמֶנֶת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָיָה מְשַׁמֵּשׁ עִם הַטְּהוֹרָה וְאָמְרָה לוֹ נִטְמֵאתִי לֹא יִפְרשׁ מִיָּד וְהוּא בְּקִשּׁוּיוֹ שֶׁהֲנָאָה לוֹ בִּיצִיאָתוֹ כְּבִיאָתוֹ. וְאִם פֵּרֵשׁ וְהוּא בְּקִשּׁוּיוֹ חַיָּב כָּרֵת כְּמוֹ שֶׁבָּעַל נִדָּה. וְהוּא הַדִּין בִּשְׁאָר עֲרָיוֹת. אֶלָּא כֵּיצַד יַעֲשֶׂה. נוֹעֵץ צִפָּרְנֵי רַגְלָיו בַּקַּרְקַע וְשׁוֹהֶה וְאֵינוֹ מִזְדַּעֲזֵעַ עַד שֶׁיָּמוּת הָאֵיבָר וְאַחַר כָּךְ נִשְׁמָט מִמֶּנָּה:","וְאָסוּר לוֹ לָאָדָם לָבֹא עַל אִשְׁתּוֹ סָמוּךְ לְוִסְתָּהּ שֶׁמָּא תִּרְאֶה דָּם בִּשְׁעַת תַּשְׁמִישׁ שֶׁנֶּאֱמַר (ויקרא טו לא) \"וְהִזַּרְתֶּם אֶת בְּנֵי יִשְׂרָאֵל מִטֻּמְאָתָם\". וְכַמָּה. אִם הָיָה דַּרְכָּהּ לִרְאוֹת בַּיּוֹם אָסוּר לְשַׁמֵּשׁ מִתְּחִלַּת הַיּוֹם. וְאִם הָיָה דַּרְכָּהּ לִרְאוֹת בַּלַּיְלָה אָסוּר לְשַׁמֵּשׁ מִתְּחִלַּת הַלַּיְלָה:","עָבַר וִסְתָּהּ וְלֹא רָאֲתָה מֻתֶּרֶת לְשַׁמֵּשׁ אַחַר שֶׁתַּעֲבֹר עוֹנַת הַוֶּסֶת. כֵּיצַד. הָיָה דַּרְכָּהּ לִרְאוֹת בְּשֵׁשׁ שָׁעוֹת בַּיּוֹם אֲסוּרָה לְשַׁמֵּשׁ מִתְּחִלַּת הַיּוֹם. עָבְרוּ שֵׁשׁ שָׁעוֹת בַּיּוֹם וְלֹא רָאֲתָה אֲסוּרָה לְשַׁמֵּשׁ עַד לָעֶרֶב. וְכֵן אִם הָיָה דַּרְכָּהּ לִרְאוֹת בְּשֵׁשׁ שָׁעוֹת בַּלַּיְלָה וְעָבְרוּ וְלֹא רָאֲתָה אֲסוּרָה לְשַׁמֵּשׁ עַד שֶׁתִּזְרַח הַשֶּׁמֶשׁ:","דֶּרֶךְ בְּנֵי יִשְׂרָאֵל וּבְנוֹת יִשְׂרָאֵל לְעוֹלָם לִבְדֹּק עַצְמָם אַחַר הַתַּשְׁמִישׁ. כֵּיצַד. מְקַנֵּחַ הָאִישׁ עַצְמוֹ בְּמַטְלִית נְכוֹנָה לוֹ וּמְקַנַּחַת הָאִשָּׁה עַצְמָהּ בְּמַטְלִית נְכוֹנָה לָהּ וְרוֹאִין בָּהֶן שֶׁמָּא רָאֲתָה דָּם בִּשְׁעַת תַּשְׁמִישׁ. וְיֵשׁ לָאִישׁ לְהָנִיחַ אִשְׁתּוֹ שֶׁתִּבְדֹּק בְּמַטְלִית שֶׁלּוֹ מִתּוֹךְ שֶׁנֶּאֱמֶנֶת עַל שֶׁלָּהּ נֶאֱמֶנֶת עַל שֶׁלּוֹ:","בְּגָדִים אֵלּוּ שֶׁמְּקַנְּחִין בָּהֶן צְרִיכִין שֶׁיִּהְיוּ שֶׁל פִּשְׁתָּן שַׁחֲקִים וּלְבָנִים וְהֵם הַנִּקְרָאִים עֵדִים בְּעִנְיָן זֶה. וְהַבֶּגֶד שֶׁמְּקַנֵּחַ בּוֹ הוּא נִקְרָא עֵד שֶׁלּוֹ. וְהַבֶּגֶד שֶׁמְּקַנַּחַת הִיא בּוֹ נִקְרָא עֵד שֶׁלָּהּ:","הַצְּנוּעוֹת אֵין מְשַׁמְּשׁוֹת אֶלָּא עַד שֶׁיִּבְדְּקוּ עַצְמָן תְּחִלָּה קֹדֶם תַּשְׁמִישׁ. וְאִשָּׁה שֶׁאֵין לָהּ וֶסֶת אֲסוּרָה לְשַׁמֵּשׁ עַד שֶׁתִּבְדֹּק. לְפִיכָךְ הִיא מְשַׁמֶּשֶׁת בִּשְׁנֵי עֵדִים אֶחָד לִפְנֵי הַתַּשְׁמִישׁ וְאֶחָד לְאַחַר הַתַּשְׁמִישׁ. אֲבָל אִשָּׁה שֶׁיֵּשׁ לָהּ וֶסֶת אֵינָהּ צְרִיכָה עֵד לִפְנֵי תַּשְׁמִישׁ אֶלָּא מִשּׁוּם צְנִיעוּת בִּלְבַד. אֲבָל אַחַר תַּשְׁמִישׁ הַכֹּל צְרִיכִין שְׁנֵי עֵדִים אֶחָד לוֹ וְאֶחָד לָהּ אֲפִלּוּ מְעֻבֶּרֶת וּמֵינִיקָה וּזְקֵנָה. וּקְטַנָּה לֹא תְּשַׁמֵּשׁ אֶלָּא בִּשְׁנֵי עֵדִים אֶחָד לוֹ וְאֶחָד לָהּ. אֲבָל בְּתוּלָה וְיוֹשֶׁבֶת עַל דַּם טֹהַר אֵינָהּ צְרִיכָה עֵדִים שֶׁהֲרֵי הַדָּם שׁוֹתֵת מִמֶּנָּה:","הַמְשַׁמֵּשׁ מִטָּתוֹ פְּעָמִים רַבּוֹת אֵינָן צְרִיכִין לִבְדֹּק שְׁנֵי הָעֵדִים שֶׁלָּהֶן עַל כָּל בִּיאָה וּבִיאָה. אֶלָּא מְקַנֵּחַ הוּא בְּעֵד שֶׁלּוֹ וְהִיא בְּעֵד שֶׁלָּהּ אַחַר כָּל בִּיאָה וּבִיאָה שֶׁל כָּל הַלַּיְלָה וּלְמָחָר יִבְדְּקוּ הָעֵדִים. נִמְצָא הַדָּם עַל עֵד שֶׁלָּהּ אוֹ עַל עֵד שֶׁלּוֹ הֲרֵי זוֹ טְמֵאָה. שִׁמְּשָׁה מִטָּתָהּ וְקִנְּחָה עַצְמָהּ וְאָבַד הָעֵד הֲרֵי זוֹ לֹא תְּשַׁמֵּשׁ פַּעַם שְׁנִיָּה עַד שֶׁתִּבְדֹּק בְּעֵד אַחֵר תְּחִלָּה. שֶׁמָּא דָּם הָיָה עַל הָעֵד שֶׁאָבַד:","הִנִּיחָה הָעֵד תַּחַת הַכַּר אוֹ תַּחַת הַכֶּסֶת וְנִמְצָא עָלָיו דָּם. אִם מָשׁוּךְ טְמֵאָה שֶׁחֶזְקָתוֹ מִן הַקִּנּוּחַ. וְאִם הָיָה עָגֹל טְהוֹרָה שֶׁאֵין זֶה אֶלָּא דַּם מַאֲכֹלֶת שֶׁנֶּהֶרְגָה תַּחַת הַכַּר:","קִנְּחָה עַצְמָהּ בְּעֵד הַבָּדוּק לָהּ וְטָחֲתוֹ בִּירֵכָהּ וּלְמָחָר נִמְצָא עָלָיו דָּם הֲרֵי זוֹ טְמֵאָה. וְאֵין אוֹמְרִים שֶׁמָּא כְּשֶׁטָּחָה אוֹתָהּ בִּירֵכָהּ נֶהֶרְגָה מַאֲכֹלֶת. קִנְּחָה עַצְמָהּ בְּעֵד שֶׁאֵינוֹ בָּדוּק לָהּ וְלֹא יָדְעָה אִם הָיָה עָלָיו דָּם קֹדֶם שֶׁתְּקַנֵּחַ בּוֹ אוֹ לֹא הָיָה. נִמְצָא עָלָיו דָּם אִם הָיָה הַדָּם כִּגְרִיס וְעוֹד הֲרֵי זוֹ נִדָּה. הָיָה פָּחוֹת מִכֵּן טְהוֹרָה שֶׁאֵינוֹ אֶלָּא מִן הַמַאֲכֹלֶת:","מִי שֶׁרָאֲתָה דָּם בִּשְׁעַת תַּשְׁמִישׁ הֲרֵי זוֹ מֻתֶּרֶת לְשַׁמֵּשׁ כְּשֶׁתִּטְהַר פַּעַם שְׁנִיָּה. רָאֲתָה דָּם בְּפַעַם שְׁנִיָּה מְשַׁמֶּשֶׁת פַּעַם שְׁלִישִׁית. רָאֲתָה דָּם בַּשְּׁלִישִׁית הֲרֵי זוֹ אֲסוּרָה לְשַׁמֵּשׁ עִם בַּעַל זֶה לְעוֹלָם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הָיָה שָׁם דָּבָר לִתְלוֹת בּוֹ. אֲבָל אִם שִׁמְּשָׁה סָמוּךְ לְוִסְתָּהּ תּוֹלָה בַּוֶּסֶת. הָיְתָה בָּהּ מַכָּה תּוֹלָה בַּמַּכָּה. וְאִם הָיָה דַּם מַכָּתָהּ מְשֻׁנֶּה מִדָּם שֶׁתִּרְאֶה בְּעֵת הַתַּשְׁמִישׁ אֵינָהּ תּוֹלָה בַּמַּכָּה. וְנֶאֱמֶנֶת אִשָּׁה לוֹמַר מַכָּה יֵשׁ לִי בְּתוֹךְ הַמָּקוֹר שֶׁמִּמֶּנָּה הַדָּם יוֹצֵא וְתִהְיֶה מֻתֶּרֶת לְבַעְלָהּ. וְאַף עַל פִּי שֶׁדָּם יוֹצֵא מִן הַמָּקוֹר בִּשְׁעַת תַּשְׁמִישׁ:","מִי שֶׁרָאֲתָה דָּם בִּשְׁעַת תַּשְׁמִישׁ פַּעַם רִאשׁוֹנָה וּשְׁנִיָּה וּשְׁלִישִׁית וְאֵין שָׁם דָּבָר לִתְלוֹת בּוֹ הֲרֵי זוֹ תִּתְגָּרֵשׁ וּמֻתֶּרֶת לְהִנָּשֵׂא לְשֵׁנִי. נִשֵּׂאת לְשֵׁנִי וְרָאֲתָה דָּם כָּךְ בִּשְׁעַת תַּשְׁמִישׁ שָׁלֹשׁ פְּעָמִים הֲרֵי זוֹ תִּתְגָּרֵשׁ וְתִנָּשֵׂא לִשְׁלִישִׁי. נִשֵּׂאת לִשְׁלִישִׁי וְרָאֲתָה דָּם כָּךְ בִּשְׁעַת תַּשְׁמִישׁ שָׁלֹשׁ פְּעָמִים הֲרֵי זוֹ תִּתְגָּרֵשׁ וַאֲסוּרָה לְהִנָּשֵׂא עַד שֶׁתַּבְרִיא מֵחלִי זֶה:","כֵּיצַד בּוֹדֶקֶת עַצְמָהּ לֵידַע אִם נִרְפֵּאת אוֹ לֹא נִרְפֵּאת. מְבִיאָה שְׁפוֹפֶרֶת שֶׁל אֲבַר וּפִיהָ רָצוּף לְתוֹכָהּ וּמַכְנֶסֶת הַשְּׁפוֹפֶרֶת עַד מָקוֹם שֶׁהִיא יְכוֹלָה. וּמַכְנֶסֶת בְּתוֹךְ הַשְּׁפוֹפֶרֶת מִכְחוֹל וּמוֹךְ מֻנָּח עַל רֹאשׁוֹ וְדוֹפֶקֶת אוֹתוֹ עַד שֶׁיַּגִּיעַ הַמּוֹךְ לְצַוַּאר הָרֶחֶם וּמוֹצִיאָה הַמּוֹךְ. אִם נִמְצָא דָּם עַל רֹאשׁ הַמּוֹךְ בְּיָדוּעַ שֶׁהַדָּם שֶׁהִיא רוֹאָה בִּשְׁעַת תַּשְׁמִישׁ מִן הַמָּקוֹר. וְאִם לֹא נִמְצָא עַל הַמּוֹךְ כְּלוּם בְּיָדוּעַ שֶׁהַדָּם שֶׁרוֹאָה מִדֹּחַק הַצְּדָדִין וּטְהוֹרָה הִיא וּמֻתֶּרֶת לְהִנָּשֵׂא לַאֲחֵרִים כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִישׁוּת:"],"Mishneh Torah, Foreign Worship and Customs of the Nations 4":["מַדִּיחֵי עִיר מִיִּשְׂרָאֵל הֲרֵי אֵלּוּ נִסְקָלִין אַף עַל פִּי שֶׁלֹּא עָבְדוּ עֲבוֹדַת כּוֹכָבִים אֶלָּא הִדִּיחוּ אֶת יוֹשְׁבֵי עִירָם עַד שֶׁעָבְדוּ אוֹתָהּ. וְאַנְשֵׁי הָעִיר הַמֻּדָּחִין נֶהֱרָגִין בְּסַיִף וְהוּא שֶׁעָבְדוּ עֲבוֹדַת כּוֹכָבִים אוֹ שֶׁקִּבְּלוּהָ עֲלֵיהֶם בֶּאֱלוֹהַּ. וְאַזְהָרָה לַמַּדִּיחַ מִנַּיִן שֶׁנֶּאֱמַר לֹא יִשָּׁמַע עַל פִּיךָ:","אֵין הָעִיר נַעֲשֵׂית עִיר הַנִּדַּחַת עַד שֶׁיִּהְיוּ מַדִּיחֶיהָ מִתּוֹכָהּ וּמֵאוֹתוֹ הַשֵּׁבֶט שֶׁנֶּאֱמַר מִקִּרְבֶּךָ (דברים יג יד) \"וַיַּדִּיחוּ אֶת יוֹשְׁבֵי עִירָם\". וְעַד שֶׁיִּהְיוּ מַדִּיחֶיהָ שְׁנַיִם אוֹ יֶתֶר עַל שְׁנַיִם שֶׁנֶּאֱמַר (דברים יג יד) \"יָצְאוּ אֲנָשִׁים בְּנֵי בְלִיַּעַל וַיַּדִּיחוּ אֶת ישְׁבֵי עִירָם\". וְעַד שֶׁיַּדִּיחוּ רֻבָּהּ. וְיִהְיוּ הַמֻּדָּחִין מִמֵּאָה וְעַד רֻבּוֹ שֶׁל שֵׁבֶט. אֲבָל אִם הֻדַּח רֻבּוֹ שֶׁל שֵׁבֶט דָּנִין אוֹתָם כִּיחִידִים שֶׁנֶּאֱמַר (דברים יג טז) \"ישְׁבֵי הָעִיר\" לֹא כְּפָר קָטָן וְלֹא כְּרַךְ גָּדוֹל. וְכָל פָּחוֹת מִמֵּאָה כְּפָר קָטָן. וְרֻבּוֹ שֶׁל שֵׁבֶט כְּרַךְ גָּדוֹל. וְכֵן אִם הִדִּיחוּהָ נָשִׁים אוֹ קְטַנִּים אוֹ שֶׁהִדִּיחָהּ יָחִיד אוֹ שֶׁהֻדְּחָה מִעוּטָהּ אוֹ שֶׁהֻדְּחוּ מֵאֲלֵיהֶן אוֹ שֶׁהָיוּ מַדִּיחֶיהָ מִחוּצָה לָהּ אֵין דָּנִין בָּהּ דִּין עִיר הַנִּדַּחַת אֶלָּא הֲרֵי הֵן כִּיחִידִים שֶׁעָבְדוּ עֲבוֹדַת כּוֹכָבִים וְסוֹקְלִין כָּל מִי שֶׁעָבַד וּמָמוֹנָן לְיוֹרְשֵׁיהֶן כִּשְׁאָר הֲרוּגֵי בֵּית דִּין:","אֵין דָּנִין עִיר הַנִּדַּחַת אֶלָּא בְּבֵית דִּין שֶׁל אֶחָד וְשִׁבְעִים שֶׁנֶּאֱמַר (דברים יז ה) \"וְהוֹצֵאתָ אֶת הָאִישׁ הַהוּא אוֹ אֶת הָאִשָּׁה הַהִיא אֲשֶׁר עָשׂוּ אֶת הַדָּבָר הָרָע הַזֶּה אֶל שְׁעָרֶיךָ\", יְחִידִים נֶהֱרָגִים בְּבֵית דִּין שֶׁל כָּל שַׁעַר וְשַׁעַר וְאֵין הַמְרֻבִּים נֶהֱרָגִין אֶלָּא בְּבֵית דִּין הַגָּדוֹל:","אֵין אַחַת מֵעָרֵי מִקְלָט נַעֲשֵׂית עִיר הַנִּדַּחַת שֶׁנֶּאֱמַר ((דברים יז ב) \"בְּאַחַד שְׁעָרֶיךָ\") [בְּאַחַת עָרֶיךָ]. וְלֹא יְרוּשָׁלַיִם נַעֲשֵׂית עִיר הַנִּדַּחַת לְפִי שֶׁלֹּא נִתְחַלְּקָה לִשְׁבָטִים. וְאֵין עוֹשִׂין עִיר הַנִּדַּחַת בַּסְּפָר כְּדֵי שֶׁלֹּא יִכָּנְסוּ עוֹבְדֵי כּוֹכָבִים וְיַחֲרִיבוּ אֶת אֶרֶץ יִשְׂרָאֵל. וְאֵין בֵּית דִּין אֶחָד עוֹשֶׂה שָׁלֹשׁ עֲיָרוֹת הַנִּדָּחוֹת זוֹ בְּצַד זוֹ. אֲבָל אִם הָיוּ מְרֻחָקוֹת עוֹשֶׂה:","אֵין עוֹשִׂין עִיר הַנִּדַּחַת עַד שֶׁיַּדִּיחוּהָ מַדִּיחֶיהָ בִּלְשׁוֹן רַבִּים וְיֹאמְרוּ לָהֶן נֵלֵךְ וְנַעֲבֹד אוֹ נֵלֵךְ וְנִזְבַּח אוֹ נֵלֵךְ וְנַקְטִיר אוֹ נֵלֵךְ וּנְנַסֵּךְ אוֹ נֵלֵךְ וְנִשְׁתַּחֲוֶה אוֹ נֵלֵךְ וּנְקַבֵּל בֶּאֱלוֹהַּ וְהֵם שׁוֹמְעִים וְעָבְדוּ אוֹתָהּ דֶּרֶךְ עֲבוֹדָתָהּ אוֹ בְּאַחַת מֵאַרְבַּע עֲבוֹדוֹת אוֹ שֶׁקִּבְּלוּהָ בֵּאלוֹהַּ. עִיר הַנִּדַּחַת שֶׁלֹּא נִתְקַיְּמוּ בָּהּ וּבְמַדִּיחֶיהָ כָּל הַתְּנָאִים הָאֵלּוּ הֵיאַךְ עוֹשִׂים לָהֶם, מַתְרִין וּמְעִידִין בְּכָל אֶחָד וְאֶחָד מֵהֶן שֶׁעָבַד עֲבוֹדַת כּוֹכָבִים וְסוֹקְלִין אוֹתָם כִּיחִידִים שֶׁעָבְדוּ וּמָמוֹנָם לְיוֹרְשֵׁיהֶם:","וְהֵיאַךְ דִּין עִיר הַנִּדַּחַת. בִּזְמַן שֶׁתִּהְיֶה רְאוּיָה לְהֵעָשׂוֹת עִיר הַנִּדַּחַת. בֵּית דִּין הַגָּדוֹל שׁוֹלְחִין וְדוֹרְשִׁין וְחוֹקְרִין עַד שֶׁיֵּדְעוּ בִּרְאָיָה בְּרוּרָה שֶׁהֻדְּחָה כָּל הָעִיר אוֹ רֻבָּהּ וְחָזְרוּ לַעֲבוֹדַת כּוֹכָבִים. אַחַר כָּךְ שׁוֹלְחִים לָהֶם שְׁנֵי תַּלְמִידֵי חֲכָמִים לְהַזְהִירָם וּלְהַחֲזִירָם. אִם חָזְרוּ וְעָשׂוּ תְּשׁוּבָה מוּטָב וְאִם יַעַמְדוּ בְּאִוַּלְתָּן בֵּית דִּין מְצַוִּין לְכָל יִשְׂרָאֵל לַעֲלוֹת עֲלֵיהֶן לַצָּבָא וְהֵן צָרִין עֲלֵיהֶם וְעוֹרְכִין עִמָּהֶן מִלְחָמָה עַד שֶׁתִּבָּקַע הָעִיר. כְּשֶׁתִּבָּקַע מִיָּד מַרְבִּין לָהֶם בָּתֵּי דִּינִין וְדָנִים אוֹתָם. כָּל מִי שֶׁבָּאוּ עָלָיו שְׁנֵי עֵדִים שֶׁעָבַד כּוֹכָבִים אַחַר שֶׁהִתְרוּ אוֹתוֹ מַפְרִישִׁין אוֹתוֹ. נִמְצְאוּ כָּל הָעוֹבְדִים מִעוּטָהּ סוֹקְלִין אוֹתָן וּשְׁאָר הָעִיר נִצּוֹל. נִמְצְאוּ רֻבָּהּ מַעֲלִין אוֹתָן לְבֵית דִּין הַגָּדוֹל וְגוֹמְרִין שָׁם דִּינָם וְהוֹרְגִין כָּל אֵלּוּ שֶׁעָבְדוּ בְּסַיִף. וּמַכִּין אֶת כָּל נֶפֶשׁ אָדָם אֲשֶׁר בָּהּ לְפִי חָרֶב טַף וְנָשִׁים אִם הֻדְּחָה כֻּלָּהּ. וְאִם נִמְצְאוּ הָעוֹבְדִים רֻבָּהּ מַכִּים אֶת כָּל הַטַּף וְנָשִׁים שֶׁל עוֹבְדִים לְפִי חָרֶב. וּבֵין שֶׁהֻדְּחָה כֻּלָּהּ בֵּין שֶׁהֻדְּחָה רֻבָּהּ סוֹקְלִין אֶת מַדִּיחֶיהָ וּמְקַבְּצִין כָּל שְׁלָלָהּ אֶל תּוֹךְ רְחוֹבָהּ. אֵין לָהּ רְחוֹב עוֹשִׂין לָהּ רְחוֹב. הָיָה רְחוֹבָהּ חוּצָה לָהּ בּוֹנִין חוֹמָה חוּץ מִמֶּנּוּ עַד שֶׁיִּכָּנֵס לְתוֹכָהּ שֶׁנֶּאֱמַר אֶל תּוֹךְ רְחֹבָהּ. וְהוֹרְגִין כָּל נֶפֶשׁ חַיָּה אֲשֶׁר בָּהּ וְשׂוֹרְפִין אֶת כָּל שְׁלָלָהּ עִם הַמְּדִינָה בָּאֵשׁ. וּשְׂרֵפָתָהּ מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (דברים יג יז) \"וְשָׂרַפְתָּ בָאֵשׁ אֶת הָעִיר וְאֶת כָּל שְׁלָלָהּ\":","נִכְסֵי הַצַּדִּיקִים שֶׁבְּתוֹכָהּ וְהֵם שְׁאָר יוֹשְׁבֵי הָעִיר שֶׁלֹּא הֻדְּחוּ עִם רֻבָּהּ נִשְׂרָפִין בִּכְלַל שְׁלָלָהּ הוֹאִיל וְיָשְׁבוּ שָׁם מָמוֹנָן אָבַד. וְכָל הַנֶּהֱנֶה מִמֶּנָּה בְּכָל שֶׁהוּא לוֹקֶה אַחַת שֶׁנֶּאֱמַר (דברים יג יח) \"וְלֹא יִדְבַּק בְּיָדְךָ מְאוּמָה מִן הַחֵרֶם\":","וְעִיר הַנִּדַּחַת שֶׁהוּזְמוּ עֵדֵיהָ כָּל הַמַּחֲזִיק בִּנְכָסֶיהָ זָכָה וּמֻתָּר לֵהָנוֹת בּוֹ שֶׁהֲרֵי הוּזְמוּ. וְלָמָּה זָכָה בָּהּ שֶׁכָּל אֶחָד וְאֶחָד כְּבָר הִפְקִיר מָמוֹנוֹ מִשָּׁעָה שֶׁנִּגְמַר דִּינוֹ. וְאֵינָהּ נִבְנֵית לְעוֹלָם וְכָל הַבּוֹנֶה אוֹתָהּ לוֹקֶה שֶׁנֶּאֱמַר (דברים יג יז) \"לֹא תִבָּנֶה עוֹד\". וּמֻתָּר לַעֲשׂוֹתָהּ גִּנּוֹת וּפַרְדֵּסִים שֶׁנֶּאֱמַר לֹא תִבָּנֶה עוֹד לֹא תִבָּנֶה מְדִינָה כְּמוֹ שֶׁהָיְתָה:","שַׁיָּרָא הָעוֹבֶרֶת מִמָּקוֹם לְמָקוֹם אִם עָבְרָה בָּעִיר הַנִּדַּחַת וְהֻדְּחָה עִמָּהּ. אִם שָׁהֲתָה שָׁם שְׁלֹשִׁים יוֹם נֶהֱרָגִין בְּסַיִף וּמָמוֹנָם אָבֵד וְאִם לָאו הֵן בִּסְקִילָה וּמָמוֹנָם לְיוֹרְשֵׁיהֶן:","נִכְסֵי אַנְשֵׁי מְדִינָה אַחֶרֶת שֶׁהָיוּ מֻפְקָדִין בְּתוֹכָהּ אַף עַל פִּי שֶׁקִּבְּלוּ עֲלֵיהֶן אַחֲרָיוּת אֵין נִשְׂרָפִין אֶלָּא יַחְזְרוּ לְבַעֲלֵיהֶן שֶׁנֶּאֱמַר (דברים יג יז) \"שְׁלָלָהּ\" וְלֹא שְׁלַל חֲבֵרְתָהּ. נִכְסֵי הָרְשָׁעִים שֶׁהֻדְּחוּ שֶׁהָיוּ מֻפְקָדִין בִּמְדִינָה אַחֶרֶת אִם נִקְבְּצוּ עִמָּהּ נִשְׂרָפִין בִּכְלָלָהּ וְאִם לָאו אֵין מְאַבְּדִים אוֹתָם אֶלָּא יִנָּתְנוּ לְיוֹרְשֵׁיהֶם:","בְּהֵמָה חֶצְיָהּ שֶׁל עִיר הַנִּדַּחַת וְחֶצְיָהּ שֶׁל עִיר אַחֶרֶת שֶׁהָיְתָה בְּתוֹכָהּ הֲרֵי זוֹ אֲסוּרָה. וְעִסָּה שֶׁהִיא כֵּן מֻתֶּרֶת לְפִי שֶׁאֶפְשָׁר לְחַלְּקָהּ:","בְּהֵמָה שֶׁל עִיר הַנִּדַּחַת שֶׁנִּשְׁחֲטָה אֲסוּרָה בַּהֲנָאָה כְּשׁוֹר הַנִּסְקָל שֶׁנִּשְׁחַט. שְׂעַר הָרֹאשׁ בֵּין שֶׁל אֲנָשִׁים בֵּין שֶׁל נָשִׁים שֶׁבָּהּ מֻתָּר בַּהֲנָאָה אֲבָל שֶׁל פֵּאָה נָכְרִית הֲרֵי הוּא מִכְּלַל שְׁלָלָהּ וְאָסוּר:","פֵּרוֹת הַמְחֻבָּרִין שֶׁבְּתוֹכָהּ מֻתָּרִין שֶׁנֶּאֱמַר (דברים יג יז) \"תִּקְבֹּץ\" (דברים יג יז) \"וְשָׂרַפְתָּ\" מִי שֶׁאֵינוֹ מְחֻסָּר אֶלָּא קִבּוּץ וּשְׂרֵפָה יָצְאוּ פֵּרוֹת הַמְחֻבָּרִין שֶׁהֵן מְחֻסָּרִין תְּלִישָׁה וְקִבּוּץ וּשְׂרֵפָה. וְהוּא הַדִּין לִשְׂעַר הָרֹאשׁ וְאֵין צָרִיךְ לוֹמַר הָאִילָנוֹת עַצְמָן שֶׁהֵן מֻתָּרִים וַהֲרֵי הֵן שֶׁל יוֹרְשֵׁיהֶם. הַהֶקְדֵּשׁוֹת שֶׁבְּתוֹכָהּ קָדְשֵׁי מִזְבֵּחַ יָמוּתוּ [שֶׁנֶּאֱמַר] זֶבַח רְשָׁעִים תּוֹעֵבָה. קָדְשֵׁי בֶּדֶק הַבַּיִת יִפָּדוּ וְאַחַר כָּךְ שׂוֹרְפִין אוֹתָן שֶׁנֶּאֱמַר (דברים יג יז) \"שְׁלָלָהּ\" וְלֹא שְׁלַל שָׁמַיִם:","הַבְּכוֹר וְהַמַּעֲשֵׂר שֶׁבְּתוֹכָהּ תְּמִימִים הֲרֵי הֵן קָדְשֵׁי מִזְבֵּחַ וְיָמוּתוּ. וּבַעֲלֵי מוּמִים הֲרֵי הֵן בִּכְלַל בְּהֶמְתָּהּ וְנֶהֱרָגִין. הַתְּרוּמוֹת שֶׁבְּתוֹכָהּ אִם הִגִּיעוּ לְיַד כֹּהֵן יֵרָקְבוּ מִפְּנֵי שֶׁהֵם נְכָסָיו. וְאִם עֲדַיִן הֵן בְּיַד יִשְׂרָאֵל יִנָּתְנוּ לְכֹהֵן שֶׁל מְדִינָה אַחֶרֶת מִפְּנֵי שֶׁהֵן נִכְסֵי שָׁמַיִם וּקְדֻשָּׁתָן קְדֻשַּׁת הַגּוּף:","מַעֲשֵׂר שֵׁנִי וְכֶסֶף מַעֲשֵׂר שֵׁנִי וְכִתְבֵי הַקֹּדֶשׁ שֶׁבְּתוֹכָהּ הֲרֵי אֵלּוּ יִגָּנְזוּ:","כָּל הָעוֹשֶׂה דִּין בְּעִיר הַנִּדַּחַת הֲרֵי זֶה כְּמַקְרִיב עוֹלָה כָּלִיל שֶׁנֶּאֱמַר (דברים יג יז) \"כָּלִיל לַה' אֱלֹהֶיךָ\". וְלֹא עוֹד אֶלָּא שֶׁמְּסַלֵּק חֲרוֹן אַף מִיִּשְׂרָאֵל שֶׁנֶּאֱמַר (דברים יג יח) \"לְמַעַן יָשׁוּב ה' מֵחֲרוֹן אַפּוֹ\". וּמֵבִיא עֲלֵיהֶם בְּרָכָה וְרַחֲמִים שֶׁנֶּאֱמַר (דברים יג יח) \"וְנָתַן לְךָ רַחֲמִים וְרִחַמְךָ וְהִרְבֶּךָ\":"],"Mishneh Torah, Foundations of the Torah 6":["כָּל הַמְאַבֵּד שֵׁם מִן הַשֵּׁמוֹת הַקְּדוֹשִׁים הַטְּהוֹרִים שֶׁנִּקְרָא בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לוֹקֶה מִן הַתּוֹרָה. שֶׁהֲרֵי הוּא אוֹמֵר בַּעֲבוֹדַת כּוֹכָבִים (גמרא שבת קכ ב) \"וְאִבַּדְתֶּם אֶת שְׁמָם מִן הַמָּקוֹם הַהוּא לֹא תַעֲשׂוּן כֵּן לַה' אֱלֹהֵיכֶם\":","וְשִׁבְעָה שֵׁמוֹת הֵם. הַשֵּׁם הַנִּכְתָּב יוּ\"ד הֵ\"א וָא\"ו הֵ\"א וְהוּא הַשֵּׁם הַמְפֹרָשׁ. אוֹ הַנִּכְתָּב אֲדֹנָי. וְאֵל. אֱלוֹהַּ. וֵאלֹהִים. וֵאלֹהֵי. וְשַׁדַּי. וּצְבָאוֹת. כָּל הַמּוֹחֵק אֲפִלּוּ אוֹת אַחַת מִשִּׁבְעָה אֵלּוּ לוֹקֶה:","כָּל הַנִּטְפָּל לַשֵּׁם מִלְּפָנָיו מֻתָּר לְמָחֳקוֹ כְּגוֹן לָמֶ\"ד מִלַּיהוָֹה וּבֵי\"ת מִבֵּאלֹהִים וְכַיּוֹצֵא בָּהֶן אֵינָן כִּקְדֻשַּׁת הַשֵּׁם. וְכָל הַנִּטְפָּל לַשֵּׁם מֵאַחֲרָיו כְּגוֹן ךְ' שֶׁל אֱלֹהֶיךָ וְכֶ\"ם שֶׁל אֱלֹהֵיכֶם וְכַיּוֹצֵא בָּהֶן אֵינָם נִמְחָקִים וַהֲרֵי הֵם כִּשְׁאָר אוֹתִיּוֹת שֶׁל שֵׁם מִפְּנֵי שֶׁהַשֵּׁם מְקַדְּשָׁם. וְאַף עַל פִּי שֶׁנִּתְקַדְּשׁוּ וְאָסוּר לְמָחֳקָם הַמּוֹחֵק אֵלּוּ הָאוֹתִיּוֹת הַנִּטְפָּלוֹת אֵינוֹ לוֹקֶה. אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","כָּתַב אָלֶ\"ף לָמֶ\"ד מֵאלֹהִים, יוּ\"ד הֵ\"א מֵיְהוָֹה, אֵינוֹ נִמְחָק. וְאֵין צָרִיךְ לוֹמַר יָהּ שֶׁהוּא שֵׁם בִּפְנֵי עַצְמוֹ. מִפְּנֵי שֶׁזֶּה הַשֵּׁם מִקְצָת שֵׁם הַמְפֹרָשׁ הוּא. אֲבָל הַכּוֹתֵב שִׁי\"ן דָּלֶ\"ת מִשַּׁדַּי, צַדִּ\"י בֵּי\"ת מִצְּבָאוֹת, הֲרֵי זֶה נִמְחָק:","שְׁאָר הַכִּנּוּיִין שֶׁמְּשַׁבְּחִין בָּהֶן אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כְּגוֹן חַנּוּן וְרַחוּם הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא הַנֶּאֱמָן קַנֹּא וְחָזָק וְכַיּוֹצֵא בָּהֶן הֲרֵי הֵן כִּשְׁאָר כִּתְבֵי הַקֹּדֶשׁ וּמֻתָּר לְמָחֳקָן:","כְּלִי שֶׁהָיָה שֵׁם כָּתוּב עָלָיו קוֹצֵץ אֶת מְקוֹם הַשֵּׁם וְגוֹנְזוֹ. וַאֲפִלּוּ הָיָה הַשֵּׁם חָקוּק בִּכְלֵי מַתָּכוֹת אוֹ בִּכְלֵי זְכוּכִית וְהִתִּיךְ הַכְּלִי הֲרֵי זֶה לוֹקֶה אֶלָּא חוֹתֵךְ אֶת מְקוֹמוֹ וְגוֹנְזוֹ. וְכֵן אִם הָיָה שֵׁם כָּתוּב עַל בְּשָׂרוֹ הֲרֵי זֶה לֹא יִרְחַץ וְלֹא יָסוּךְ וְלֹא יַעֲמֹד בִּמְקוֹם הַטִּנֹּפֶת. נִזְדַּמְּנָה לוֹ טְבִילָה שֶׁל מִצְוָה כּוֹרֵךְ עָלָיו גֶּמִי וְטוֹבֵל. וְאִם לֹא מָצָא גֶּמִי מְסַבֵּב בִּבְגָדָיו וְלֹא יְהַדֵּק כְּדֵי שֶׁלֹּא יָחֹץ. שֶׁלֹּא אָמְרוּ לִכְרֹךְ עָלָיו אֶלָּא מִפְּנֵי שֶׁאָסוּר לַעֲמֹד בִּפְנֵי הַשֵּׁם כְּשֶׁהוּא עָרֹם:","הַסּוֹתֵר אֲפִלּוּ אֶבֶן אַחַת דֶּרֶךְ הַשְׁחָתָה מִן הַמִּזְבֵּחַ אוֹ מִן הַהֵיכָל אוֹ מִשְּׁאָר הָעֲזָרָה לוֹקֶה שֶׁנֶּאֱמַר בַּעֲבוֹדַת כּוֹכָבִים (שמות לד יג) \"כִּי אֶת מִזְבְּחֹתָם תִּתֹּצוּן\" וְכָתוּב (דברים יב ד) \"לֹא תַעֲשׂוּן כֵּן לַה' אֱלֹהֵיכֶם\". וְכֵן הַשּׂוֹרֵף עֲצֵי הַקֹּדֶשׁ דֶּרֶךְ הַשְׁחָתָה לוֹקֶה שֶׁנֶּאֱמַר (דברים יב ג) \"וַאֲשֵׁרֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ\" וּכְתִיב לֹא תַעֲשׂוּן כֵּן לַה' אֱלֹהֵיכֶם:","כִּתְבֵי הַקֹּדֶשׁ כֻּלָּן וּפֵרוּשֵׁיהֶן וּבֵאוּרֵיהֶן אָסוּר לְשָׂרְפָם אוֹ לְאַבְּדָם בַּיָּד וְהַמְאַבְּדָן בַּיָּד מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּכִתְבֵי הַקֹּדֶשׁ שֶׁכְּתָבָם יִשְׂרָאֵל בִּקְדֻשָּׁה אֲבָל אֶפִּיקוֹרוֹס יִשְׂרָאֵל שֶׁכָּתַב סֵפֶר תּוֹרָה שׂוֹרְפִין אוֹתוֹ עִם הָאַזְכָּרוֹת שֶׁבּוֹ. מִפְּנֵי שֶׁאֵינוֹ מַאֲמִין בִּקְדֻשַּׁת הַשֵּׁם וְלֹא כְּתָבוֹ לִשְׁמוֹ אֶלָּא שֶׁהוּא מַעֲלֶה בְּדַעְתּוֹ שֶׁזֶּה כִּשְׁאָר הַדְּבָרִים וְהוֹאִיל וְדַעְתּוֹ כֵּן לֹא נִתְקַדֵּשׁ הַשֵּׁם. וּמִצְוָה לְשָׂרְפוֹ כְּדֵי שֶׁלֹּא לְהַנִּיחַ שֵׁם לָאֶפִּיקוֹרוֹסִים וְלֹא לְמַעֲשֵׂיהֶם. אֲבָל עוֹבֵד כּוֹכָבִים שֶׁכָּתַב אֶת הַשֵּׁם גּוֹנְזִין אוֹתוֹ. וְכֵן כִּתְבֵי הַקֹּדֶשׁ שֶׁבָּלוּ אוֹ שֶׁכְּתָבָן עוֹבֵד כּוֹכָבִים יִגָּנְזוּ:","כָּל הַשֵּׁמוֹת הָאֲמוּרִים בְּאַבְרָהָם קֹדֶשׁ אַף זֶה שֶׁנֶּאֱמַר (בראשית יח ג) \"אֲדֹנָי אִם נָא מָצָאתִי חֵן\" הֲרֵי הוּא קֹדֶשׁ. כָּל הַשֵּׁמוֹת הָאֲמוּרִים בְּלוֹט חֹל חוּץ מִזֶּה (גמרא שבועות לה ב) \"אַל נָא אֲדֹנָי הִנֵּה נָא מָצָא עַבְדְּךָ חֵן\". כָּל הַשֵּׁמוֹת הָאֲמוּרִים בְּגִבְעַת בִּנְיָמִין קֹדֶשׁ. כָּל הַשֵּׁמוֹת הָאֲמוּרִים בְּמִיכָה חֹל. כָּל הַשֵּׁמוֹת הָאֲמוּרִים בְּנָבוֹת קֹדֶשׁ. כָּל שְׁלֹמֹה הָאָמוּר בְּשִׁיר הַשִּׁירִים קֹדֶשׁ וַהֲרֵי הוּא כִּשְׁאָר הַכִּנּוּיִין חוּץ מִזֶּה (שיר השירים ח יב) \"הָאֶלֶף לְךָ שְׁלֹמֹה\". כָּל מַלְכַיָּא הָאָמוּר בְּדָנִיֵּאל חֹל חוּץ מִזֶּה (דניאל ב לז) \"אַנְתְּ מַלְכָּא מֶלֶךְ מַלְכַיָּא\" וַהֲרֵי הוּא כִּשְׁאָר הַכִּנּוּיִין:"],"Mishneh Torah, Gifts to the Poor 5":["הָעֹמֶר שֶׁשְּׁכָחוּהוּ פּוֹעֲלִים וְלֹא שְׁכָחוֹ בַּעַל הַשָּׂדֶה. שְׁכָחוֹ בַּעַל הַשָּׂדֶה וְלֹא שְׁכָחוּהוּ פּוֹעֲלִים. שְׁכָחוּהוּ אֵלּוּ וְאֵלּוּ וְהָיוּ שָׁם אֲחֵרִים עוֹבְרִין וְרוֹאִין אוֹתָן בְּעֵת שֶׁשְּׁכָחוּהוּ. אֵינָהּ שִׁכְחָה עַד שֶׁיִּשְׁכְּחוּהוּ כָּל אָדָם. וַאֲפִלּוּ עֹמֶר הַטָּמוּן אִם נִשְׁכָּח הֲרֵי זֶה שִׁכְחָה:","הָיָה בַּעַל הַשָּׂדֶה בָּעִיר וְאָמַר יוֹדֵעַ אֲנִי שֶׁהַפּוֹעֲלִים שָׁכְחוּ עֹמֶר שֶׁבְּמָקוֹם פְּלוֹנִי וּשְׁכָחוּהוּ הֲרֵי זֶה שִׁכְחָה. וְאִם הָיָה בַּשָּׂדֶה וְאָמַר כֵּן וּשְׁכָחוּהוּ אֵינָהּ שִׁכְחָה שֶׁהַשָּׁכוּחַ מֵעִקָּרוֹ בַּשָּׂדֶה הוּא הַשִּׁכְחָה. אֲבָל בָּעִיר אֲפִלּוּ זָכוּר וּלְבַסּוֹף שָׁכוּחַ הֲרֵי זוֹ שִׁכְחָה שֶׁנֶּאֱמַר (דברים כד יט) \"וְשָׁכַחְתָּ עֹמֶר בַּשָּׂדֶה\" וְלֹא בָּעִיר:","עָמְדוּ הָעֲנִיִּים בְּפָנָיו אוֹ חִפּוּהוּ בְּקַשׁ וְהוּא זוֹכֵר אֶת הַקַּשׁ אוֹ שֶׁהֶחֱזִיק בּוֹ לְהוֹלִיכוֹ לָעִיר וְהִנִּיחוֹ בַּשָּׂדֶה וּשְׁכָחוֹ אֵינוֹ שִׁכְחָה. אֲבָל אִם נְטָלוֹ מִמָּקוֹם לְמָקוֹם אַף עַל פִּי שֶׁהִנִּיחוֹ סָמוּךְ לַגַּפָּה אוֹ לַגָּדִישׁ אוֹ לַבָּקָר אוֹ לַכֵּלִים וּשְׁכָחוֹ הֲרֵי זֶה שִׁכְחָה:","נָטַל עֹמֶר לְהוֹלִיכוֹ לָעִיר וְהִנִּיחוֹ עַל גַּבֵּי חֲבֵרוֹ וְשָׁכַח אֶת שְׁנֵיהֶן. אִם זָכַר הָעֶלְיוֹן קֹדֶם שֶׁיִּפְגַּע בּוֹ אֵין הַתַּחְתּוֹן שִׁכְחָה וְאִם לָאו הַתַּחְתּוֹן שִׁכְחָה:","עָפוּ עֳמָרָיו בְּרוּחַ חֲזָקָה לְתוֹךְ שְׂדֵה חֲבֵרוֹ וְשָׁכַח שָׁם עֹמֶר אֵינוֹ שִׁכְחָה שֶׁנֶּאֱמַר (דברים כד יט) \"קְצִירְךָ בְשָׂדֶךָ\". אֲבָל אִם פִּזֵּר הָעֳמָרִים בְּתוֹךְ שָׂדֵהוּ וְשָׁכַח הֲרֵי זוֹ שִׁכְחָה:","הַנּוֹטֵל עֹמֶר רִאשׁוֹן וְשֵׁנִי וּשְׁלִישִׁי וְשָׁכַח הָרְבִיעִי. אִם הָיָה שָׁם שִׁשִּׁי אֵין הָרְבִיעִי שִׁכְחָה עַד שֶׁיִּטּל הַחֲמִישִׁי. וְאִם הָיוּ חֲמִשָּׁה בִּלְבַד מִשֶּׁיִּשְׁהֶא כְּדֵי לִטּל הַחֲמִישִׁי הֲרֵי הָרְבִיעִי שִׁכְחָה:","שְׁנֵי עֳמָרִים מְעֻרְבָּבִין וְשָׁכַח אֶחָד מֵהֶן אֵינָהּ שִׁכְחָה עַד שֶׁיִּטּל אֶת כָּל סְבִיבוֹתָיו:","הַלּוּף וְהַשּׁוּם וְהַבְּצָלִים וְכַיּוֹצֵא בָּהּ אַף עַל פִּי שֶׁהֵן טְמוּנִין בָּאָרֶץ יֵשׁ לָהֶן שִׁכְחָה. הַקּוֹצֵר בַּלַּיְלָה וְשָׁכַח קָמָה אוֹ שֶׁעִמֵּר בַּלַּיְלָה וְשָׁכַח עֹמֶר וְכֵן הַסּוּמָא שֶׁשָּׁכַח יֵשׁ לָהֶן שִׁכְחָה. וְאִם הָיָה הַסּוּמָא אוֹ הַקּוֹצֵר בַּלַּיְלָה מִתְכַּוֵּן לִטּל אֶת הַגַּס אֵין לוֹ שִׁכְחָה. וְכָל הָאוֹמֵר הֲרֵינִי קוֹצֵר עַל מְנָת מַה שֶּׁאֲנִי שׁוֹכֵחַ אֲנִי אֶטּל יֵשׁ לוֹ שִׁכְחָה שֶׁכָּל הַמַּתְנֶה עַל מַה שֶּׁכָּתוּב בַּתּוֹרָה תְּנָאוֹ בָּטֵל:","תְּבוּאָה שֶׁקְּצָרָהּ עַד שֶׁלֹּא נִגְמְרָה לְהַאֲכִילָהּ לִבְהֵמָה. וְכֵן אִם קְצָרָהּ אֲגֻדּוֹת קְטַנּוֹת וְלֹא עֲשָׂאָהּ עֳמָרִים. וְכֵן הַשּׁוּמִים וְהַבְּצָלִים שֶׁתְּלָשָׁן אֲגֻדּוֹת קְטַנּוֹת לְהִמָּכֵר לַשּׁוּק וְלֹא עֲשָׂאָן עֳמָרִים לְהַעֲמִיד מֵהֶן גֹּרֶן אֵין לָהֶם שִׁכְחָה:","הַקּוֹצֵר שֶׁהִתְחִיל לִקְצֹר מֵרֹאשׁ הַשּׁוּרָה וְשָׁכַח לְפָנָיו וּלְאַחֲרָיו. שֶׁל אַחֲרָיו שִׁכְחָה וְשֶׁלְּפָנָיו אֵינוֹ שִׁכְחָה שֶׁנֶּאֱמַר (דברים כד יט) \"לֹא תָשׁוּב לְקַחְתּוֹ\" אֵינוֹ שִׁכְחָה עַד שֶׁיַּעֲבֹר מִמֶּנּוּ וְיַנִּיחֶנּוּ לְאַחֲרָיו. זֶה הַכְּלָל כָּל שֶׁהוּא בְּבַל תָּשׁוּב שִׁכְחָה וְכָל שֶׁאֵינוֹ בְּבַל תָּשׁוּב אֵינוֹ שִׁכְחָה:","שְׁנַיִם שֶׁהִתְחִילוּ לִקְצֹר מֵאֶמְצַע הַשּׁוּרָה זֶה פָּנָיו לְצָפוֹן וְזֶה פָּנָיו לְדָרוֹם וְשָׁכְחוּ לִפְנֵיהֶם וּלְאַחֲרֵיהֶן. שֶׁלִּפְנֵיהֶם שִׁכְחָה. מִפְּנֵי שֶׁכָּל אֶחָד מֵהֶן זֶה שֶׁלְּפָנָיו הוּא לַאֲחוֹרָיו שֶׁל חֲבֵרוֹ. וְהָעֹמֶר שֶׁשְּׁכָחוּהוּ לַאֲחוֹרֵיהֶן בְּמָקוֹם שֶׁהִתְחִילוּ מִמֶּנּוּ אֵינוֹ שִׁכְחָה. מִפְּנֵי שֶׁהוּא מְעֹרָב עִם הַשּׁוּרוֹת שֶׁמִּן הַמִּזְרָח לְמַעֲרָב וְהֵן מוֹכִיחִין עָלָיו שֶׁאֵינוֹ שָׁכוּחַ. וְכֵן הַשּׁוּרוֹת שֶׁל עֳמָרִים שֶׁפִּינוּ אוֹתָן לְגֹרֶן וְהִתְחִילוּ שְׁנַיִם מֵאֶמְצַע שׁוּרָה וְשָׁכְחוּ עֹמֶר בָּאֶמְצַע בֵּין אֲחוֹרֵיהֶן אֵינוֹ שִׁכְחָה מִפְּנֵי שֶׁהוּא בְּאֶמְצַע הַשּׁוּרָה שֶׁמִּן מַעֲרָב לַמִּזְרָח שֶׁעֲדַיִן לֹא הִתְחִילוּ בָּהּ וְהִיא מוֹכָחַת עָלָיו שֶׁאֵינוֹ שָׁכוּחַ:","הַקּוֹצֵר וְאִלֵּם אֲלֻמּוֹת אֲלֻמּוֹת. וּפִנָּה הָאֲלֻמּוֹת וְהֵן הַנִּקְרָאִין עֳמָרִים מִמָּקוֹם זֶה לְמָקוֹם אַחֵר. וּמִמָּקוֹם הַשֵּׁנִי לַמָּקוֹם הַשְּׁלִישִׁי. וּמִמָּקוֹם הַשְּׁלִישִׁי לַגֹּרֶן וְשָׁכַח הָעֹמֶר בְּשָׁעָה שֶׁפִּנָּה מִמָּקוֹם לְמָקוֹם. אִם פִּנָּה הָעֳמָרִים לְמָקוֹם שֶׁהוּא גְּמַר מְלָאכָה וּשְׁכָחָהּ יֵשׁ לוֹ שִׁכְחָה וּכְשֶׁיְּפַנֶּה מִמָּקוֹם שֶׁהוּא גְּמַר מְלָאכָה לַגֹּרֶן אֵין לוֹ שִׁכְחָה. וְאִם פִּנָּה הָעֳמָרִים לְמָקוֹם שֶׁאֵינוֹ גְּמַר מְלָאכָה וְשָׁכַח אֵינוֹ שִׁכְחָה וּכְשֶׁיְּפַנֶּה מִמָּקוֹם שֶׁאֵינוֹ גְּמַר מְלָאכָה לַגֹּרֶן יֵשׁ לוֹ שִׁכְחָה:","אֵי זֶהוּ מָקוֹם שֶׁהוּא גְּמַר מְלָאכָה. זֶה מָקוֹם שֶׁדַּעְתּוֹ לְקַבֵּץ כָּל הָעֳמָרִין שָׁם וְלָדוּשׁ אוֹתָן שָׁם אוֹ לְהוֹלִיכָן שָׁם לִמְקוֹם גָּדִישׁ שֶׁהוּא הַגֹּרֶן. וּמָקוֹם שֶׁאֵינוֹ גְּמַר מְלָאכָה הוּא הַמָּקוֹם שֶׁמְּקַבְּצִין בּוֹ הָעֳמָרִים כְּדֵי לַעֲשׂוֹת מֵהֶן אֲלֻמּוֹת גְּדוֹלוֹת כְּדֵי לְהוֹלִיכָן לְמָקוֹם אַחֵר:","שְׁתֵּי כְּרִיכוֹת הַמֻּבְדָּלוֹת זוֹ מִזּוֹ שִׁכְחָה. וְשָׁלֹשׁ אֵינָן שִׁכְחָה. שְׁנֵי עֳמָרִים הַמֻּבְדָּלִין זֶה מִזֶּה שִׁכְחָה. וּשְׁלֹשָׁה אֵינָן שִׁכְחָה:","שְׁנֵי צִבּוּרֵי זֵיתִים וְחָרוּבִין הַמֻּבְדָּלִין זֶה מִזֶּה שִׁכְחָה. וּשְׁלֹשָׁה אֵינָם שִׁכְחָה. שְׁנֵי הוּצְנֵי פִּשְׁתָּן שִׁכְחָה וּשְׁלֹשָׁה אֵינָם שִׁכְחָה:","שְׁתֵּי גְּפָנִים וְכֵן בִּשְׁאָר הָאִילָנוֹת שְׁנַיִם הַמֻּבְדָּלִין זֶה מִזֶּה שִׁכְחָה. וּשְׁלֹשָׁה אֵינָן שִׁכְחָה שֶׁנֶּאֱמַר (ויקרא יט י) (ויקרא כג כב) \"לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם\" אֲפִלּוּ הָיוּ שְׁנַיִם אֶחָד לְעָנִי וְאֶחָד לַגֵּר:","הָיוּ כָּל הָעֳמָרִים שֶׁל קַב קַב וְאֶחָד שֶׁל אַרְבָּעָה קַבִּין וּשְׁכָחוֹ הֲרֵי זֶה שִׁכְחָה. יֶתֶר עַל הָאַרְבָּעָה אֵינוֹ שִׁכְחָה. וְכֵן אִם הָיוּ שֶׁל שְׁנֵי שְׁנֵי קַבִּין וְאֶחָד יֶתֶר עַל שְׁמוֹנָה קַבִּין אֵינוֹ שִׁכְחָה:","הָעֹמֶר שֶׁיֵּשׁ בּוֹ סָאתַיִם וּשְׁכָחוֹ אֵינוֹ שִׁכְחָה שֶׁנֶּאֱמַר (דברים כד יט) \"וְשָׁכַחְתָּ עֹמֶר בַּשָּׂדֶה\" וְלֹא גָּדִישׁ אַף עַל פִּי שֶׁכֻּלָּן סָאתַיִם סָאתַיִם. שָׁכַח שְׁנֵי עֳמָרִים אַף עַל פִּי שֶׁיֵּשׁ מִשְּׁנֵיהֶן סָאתַיִם הֲרֵי אֵלּוּ שִׁכְחָה. וְכֵן יֵרָאֶה לִי שֶׁהֵן שִׁכְחָה אֲפִלּוּ הָיָה בִּשְׁנֵיהֶן יוֹתֵר מִסָּאתַיִם:","קָמָה שֶׁיֵּשׁ בָּהּ סָאתַיִם וּשְׁכָחָהּ אֵינָהּ שִׁכְחָה. אֵין בָּהּ סָאתַיִם רוֹאִין אֶת הַשִּׁבֳּלִים הַדַּקּוֹת כְּאִלּוּ הֵן בְּרִיאוֹת וַאֲרֻכּוֹת וְאֶת הַשְּׁדוּפוֹת כְּאִלּוּ הֵן מְלֵאוֹת. וְאִם הָיְתָה רְאוּיָה (לִהְיוֹת) הַקָּמָה אַחַר אֻמְדָּן זֶה לַעֲשׂוֹת סָאתַיִם וּשְׁכָחָהּ אֵינָהּ שִׁכְחָה:","שָׁכַח סְאָה תְּבוּאָה עֲקוּרָה וּסְאָה שֶׁאֵינָהּ עֲקוּרָה אֵינָן מִצְטָרְפִים. וּשְׁנֵיהֶם שִׁכְחָה. וְכֵן בְּשׁוּם וּבִבְצָלִים וּבְפֵרוֹת הָאִילָן אִם שָׁכַח מִקְצָתָן בַּקַּרְקַע וּמִקְצָתָן תָּלוּשׁ וּבִשְׁנֵיהֶם סָאתַיִם אֵינָן מִצְטָרְפִין אֶלָּא שְׁנֵיהֶם שִׁכְחָה","הַשּׁוֹכֵחַ עֹמֶר בְּצַד הַקָּמָה שֶׁאֵינָהּ שְׁכוּחָה אֵינָהּ שִׁכְחָה. שֶׁנֶּאֱמַר (דברים כד יט) \"כִּי תִקְצֹר וְשָׁכַחְתָּ עֹמֶר\". עֹמֶר שֶׁסְּבִיבוֹתָיו קָצִיר שִׁכְחָה אֲבָל עֹמֶר שֶׁסְּבִיבוֹתָיו קָמָה אֵינָהּ שִׁכְחָה. וְכֵן אִם שָׁכַח קָמָה בְּצַד קָמָה שֶׁאֵינָהּ שְׁכוּחָה אֲפִלּוּ קֶלַח אֶחָד הֲרֵי זוֹ מַצֶּלֶת אֶת הַשְּׁכוּחָה וְיִהְיֶה מֻתָּר לְקַחְתָּהּ. אֲבָל אִם שָׁכַח עֹמֶר אוֹ קָמָה בְּצַד עֹמֶר שֶׁאֵינוֹ שָׁכוּחַ אֲפִלּוּ הָיָה בּוֹ סָאתַיִם אֵינוֹ מַצִּיל אוֹתָהּ וַהֲרֵי הַשָּׁכוּחַ לָעֲנִיִּים. אֵין קָמַת חֲבֵרוֹ מַצֶּלֶת עַל עֹמֶר שֶׁלּוֹ וְאֵין קָמַת שְׂעוֹרִים מַצֶּלֶת עַל עֹמֶר חִטִּים עַד שֶׁתִּהְיֶה הַקָּמָה מִמִּין הָעֹמֶר:","הַשּׁוֹכֵחַ אִילָן בֵּין הָאִילָנוֹת אֲפִלּוּ הָיָה בּוֹ כַּמָּה סְאִין פֵּרוֹת אוֹ שֶׁשָּׁכַח שְׁנֵי אִילָנוֹת הֲרֵי הֵן שִׁכְחָה. שְׁלֹשָׁה אֵינָן שִׁכְחָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּאִילָן שֶׁאֵינוֹ יָדוּעַ וּמְפֻרְסָם בַּמָּקוֹם כְּגוֹן שֶׁהָיָה עוֹמֵד בְּצַד הַגַּת אוֹ בְּצַד הַפִּרְצָה. אוֹ בְּמַעֲשָׂיו כְּגוֹן שֶׁהָיָה עוֹשֶׂה זֵיתִים הַרְבֵּה. אוֹ בִּשְׁמוֹ כְּגוֹן שֶׁהָיָה לוֹ שֵׁם יָדוּעַ כְּגוֹן זַיִת הַנְּטוּפָה בֵּין הַזֵּיתִים שֶׁהוּא נוֹטֵף שֶׁמֶן הַרְבֵּה אוֹ הַשַּׁפְכָנִי אוֹ הַבֵּיְשָׁנִי. אֲבָל אִם הָיָה בּוֹ אֶחָד מִשְּׁלֹשָׁה דְּבָרִים אֵלּוּ אֵינוֹ שִׁכְחָה. שֶׁנֶּאֱמַר (דברים כד יט) \"וְשָׁכַחְתָּ עֹמֶר בַּשָּׂדֶה\" עֹמֶר שֶׁאַתָּה שׁוֹכְחוֹ לְעוֹלָם וְאֵין אַתָּה יוֹדֵעַ בּוֹ אֶלָּא אִם תָּשׁוּב וְתִרְאֵהוּ. יָצָא זֶה שֶׁאַתָּה זוֹכְרוֹ לְאַחַר זְמַן וְאַף עַל פִּי שֶׁלֹּא תִּפְגַּע בּוֹ מִפְּנֵי שֶׁהוּא יָדוּעַ וּמְפֻרְסָם:","הָיָה מְסֻיָּם בְּדַעְתּוֹ הֲרֵי זֶה כִּמְפֻרְסָם וְיָדוּעַ. הָיָה עוֹמֵד בְּצַד הַדֶּקֶל הַדֶּקֶל מְסַיְּמוֹ. הָיוּ שְׁנֵיהֶן זַיִת נְטוּפָה זֶה מְסַיֵּם אֶת זֶה. הָיְתָה כָּל שָׂדֵהוּ זַיִת נְטוּפָה וְשָׁכַח אַחַת מֵהֶן אוֹ שְׁתַּיִם יֵשׁ לוֹ שִׁכְחָה. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא הִתְחִיל בְּאִילָן זֶה הַמְפֻרְסָם. אֲבָל אִם הִתְחִיל בּוֹ וְשָׁכַח מִקְצָתוֹ הֲרֵי זֶה שִׁכְחָה. וְאַף עַל פִּי שֶׁהוּא מְפֻרְסָם. וְהוּא שֶׁיִּהְיֶה הַנִּשְׁאָר בּוֹ פָּחוֹת מִסָּאתַיִם. אֲבָל סָאתַיִם אֵינָהּ שִׁכְחָה אֶלָּא אִם כֵּן שָׁכַח כָּל הָאִילָן כְּמוֹ שֶׁבֵּאַרְנוּ:","זַיִת הָעוֹמֵד בְּאֶמְצַע הַשּׁוּרוֹת לְבַדּוֹ וְשָׁלֹשׁ שׁוּרוֹת שֶׁל זֵיתִים מַקִּיפִין אוֹתוֹ מִשְּׁלֹשׁ רוּחוֹתָיו אַף עַל פִּי שֶׁאֵין בְּכָל שׁוּרָה מֵהֶן אֶלָּא שְׁנֵי זֵיתִים שָׁכַח אֶת הָאֶמְצָעִי אֵינוֹ שִׁכְחָה. שֶׁהֲרֵי הַשּׁוּרוֹת הִסְתִּירוּהוּ. וְלָמָּה אָמְרוּ זַיִת בִּלְבַד מִפְּנֵי שֶׁהָיָה חָשׁוּב בְּאֶרֶץ יִשְׂרָאֵל בְּאוֹתוֹ הַזְּמַן:","אֵיזֶהוּ שִׁכְחָה בְּעָרִיס. כָּל שֶׁאֵינוֹ יָכוֹל לִפְשֹׁט אֶת יָדוֹ וְלִטְּלָהּ. וּבְכֶרֶם מִשֶּׁיַּעֲבֹר מִן הַגֶּפֶן (אוֹ) וּמִן הַגְּפָנִים וְיִשְׁכַּח אוֹתָהּ. בְּדָלִית וּבְדֶקֶל מִשֶּׁיֵּרֵד הֵימֶנּוּ. וּשְׁאָר כָּל הָאִילָנוֹת מִשֶּׁיִּפְנֶה וְיֵלֵךְ לוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא הִתְחִיל בּוֹ. אֲבָל אִם הִתְחִיל בּוֹ וּשְׁכָחוֹ אֵינָהּ שִׁכְחָה עַד שֶׁיִּבְצֹר אֶת כָּל סְבִיבָיו:","הַמַּפְקִיר אֶת כַּרְמוֹ וְהִשְׁכִּים בַּבֹּקֶר וְזָכָה בּוֹ לְעַצְמוֹ וּבְצָרוֹ חַיָּב בְּפֶרֶט וּבְעוֹלֵלוֹת וּבְשִׁכְחָה וּבְפֵאָה שֶׁהֲרֵי שָׂדְךָ וְכַרְמְךָ אֲנִי קוֹרֵא בּוֹ מִפְּנֵי שֶׁהָיָה שֶׁלּוֹ וַהֲרֵי הוּא שֶׁלּוֹ. אֲבָל אִם זָכָה מִן הַהֶפְקֵר בְּשָׂדֶה שֶׁל אֲחֵרִים הֲרֵי זֶה פָּטוּר מִן הַכּל. וּבֵין כָּךְ וּבֵין כָּךְ פָּטוּר מִן הַמַּעַשְׂרוֹת כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Heave Offerings 2":["כָּל אֹכֶל אָדָם הַנִּשְׁמָר שֶׁגִּדּוּלָיו מִן הָאָרֶץ חַיָּב בִּתְרוּמָה. וּמִצְוַת עֲשֵׂה לְהַפְרִישׁ מִמֶּנּוּ רֵאשִׁית לַכֹּהֵן שֶׁנֶּאֱמַר (דברים יח ד) \"רֵאשִׁית דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ\" (דברים יח ד) \"תִּתֶּן לּוֹ\". מַה דָּגָן תִּירוֹשׁ וְיִצְהָר מַאֲכַל בְּנֵי אָדָם וְגִדּוּלָיו מִן הָאָרֶץ וְיֵשׁ לוֹ בְּעָלִים שֶׁנֶּאֱמַר דְּגָנְךָ אַף כָּל כַּיּוֹצֵא בָּהֶן חַיָּב בִּתְרוּמוֹת וְכֵן בְּמַעַשְׂרוֹת:","הַכַּרְשִׁינִין אַף עַל פִּי שֶׁאֵינָם מַאֲכַל אָדָם הוֹאִיל וְאוֹכְלִין אוֹתָן בִּשְׁנֵי רְעָבוֹן חַיָּבִין בִּתְרוּמָה וּמַעַשְׂרוֹת. הַסִּיאָה וְהָאֵזוֹב וְהַקּוֹרָנִית שֶׁזְּרָעָן מִתְּחִלָּה לְאָדָם חַיָּבִין בְּמַעֲשֵׂר. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן. זְרָעָן לְמַאֲכַל בְּהֵמָה אַף עַל פִּי שֶׁנִּמְלַךְ וְחִשֵּׁב עֲלֵיהֶן לְאָדָם כְּשֶׁהֵן מְחֻבָּרִין פְּטוּרִין שֶׁמַּחְשֶׁבֶת חִבּוּר אֵינָהּ כְּלוּם. עָלוּ מֵאֲלֵיהֶן בֶּחָצֵר. אִם הִיא חָצֵר הַמְשַׁמֶּרֶת פֵּרוֹתֶיהָ הֲרֵי אֵלּוּ חַיָּבִין שֶׁסְּתָמָן לְאָדָם וְאִם אֵינָהּ מְשַׁמֶּרֶת פֵּרוֹתֶיהָ פְּטוּרָה:","זֵרְעוֹנֵי גִּנָּה שֶׁאֵינָן נֶאֱכָלִים כְּגוֹן זֶרַע לֶפֶת וְזֶרַע צְנוֹן וְזֶרַע בְּצָלִים וְכַיּוֹצֵא בָּהֶן פְּטוּרִים מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת מִפְּנֵי שֶׁאֵינָן אֹכֶל אָדָם. אֲבָל הַקֶּצַח חַיָּב בִּתְרוּמָה וּבְמַעַשְׂרוֹת:","תְּמָרוֹת שֶׁל תִּלְתָּן וְשֶׁל חַרְדָּל וְשֶׁל פּוֹל הַלָּבָן וְשֶׁל צָלָף וְהַקַּפְרִיסִין שֶׁל צָלָף פְּטוּרִים מִפְּנֵי שֶׁאֵינָן פְּרִי. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁזְּרָעָן לְזֶרַע. אֲבָל זְרָעָן לְיָרָק הֲרֵי אֵלּוּ חַיָּבִים. וְכֵן הָאֶבְיוֹנוֹת שֶׁל צָלָף חַיָּבִים מִפְּנֵי שֶׁהֵן פְּרִי:","כֻּסְבַּר שֶׁזְּרָעָהּ לְזֶרַע יַרְקָהּ פָּטוּר מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת. זְרָעָהּ לְיָרָק מַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת מִן הַיְרָקוֹת וּמִן הַזֶּרַע. וְכֵן הַשֶּׁבֶת שֶׁזְּרָעָהּ לְזֶרַע יַרְקָהּ פָּטוּר. זְרָעָהּ לְיָרָק מִתְעַשֶּׂרֶת זֶרַע וְיָרָק. וְאֵינָהּ מִתְעַשֶּׂרֶת זִרִין. זְרָעָהּ לְזִרִין מַפְרִישׁ תְּרוּמָה וּמַעַשְׂרוֹת מִן הַזֶּרַע וּמִן הַיָּרָק וּמִן הַזִּרִין. וְכֵן הַשִּׁחֲלַיִם וְהַגַּרְגֵּר שֶׁזְּרָעָן לְזֶרַע מִתְעַשְּׂרִין זֶרַע וְיָרָק. כֵּיצַד מִתְעַשְּׂרִין לְזֶרַע וּלְיָרָק. שֶׁאִם לִקֵּט הַיָּרָק לְאָכְלוֹ מַפְרִישׁ תְּרוּמָה וּמַעַשְׂרוֹת וְאַחַר כָּךְ יֹאכַל. וּכְשֶׁיִּיבַשׁ וְיֶאֱסֹף הַזֶּרַע שֶׁלּוֹ מַפְרִישׁ מִן הַזֶּרַע:","הַיְרָקוֹת אַף עַל פִּי שֶׁהֵן מַאֲכַל אָדָם אֵינָן חַיָּבִין בְּמַעַשְׂרוֹת אֶלָּא מִדִּבְרֵיהֶן. לְפִי שֶׁנֶּאֱמַר בְּמַעֲשֵׂר (דברים יד כב) \"תְּבוּאַת זַרְעֶךָ\". תְּבוּאָה וְכַיּוֹצֵא בָּהּ. אֲבָל הַיְרָקוֹת אֵינָן בִּכְלַל הַתְּבוּאָה. וְכֵן יֵרָאֶה לִי שֶׁהוּא הַדִּין בִּתְרוּמָה. שֶׁהֲרֵי נֶאֱמַר בָּהּ (דברים יח ד) \"דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ\" כָּל הַדּוֹמֶה לְאֵלּוּ אֲבָל תְּרוּמַת הַיָּרָק מִדִּבְרֵיהֶם כְּמַעֲשֵׂר:","אֵין מַפְרִישִׁין תְּרוּמוֹת וּמַעַשְׂרוֹת מִן הַיָּרָק בְּחוּצָה לָאָרֶץ. וַאֲפִלּוּ בִּמְקוֹמוֹת שֶׁאָמַרְנוּ שֶׁמַּפְרִישִׁין בָּהֶן מַעַשְׂרוֹת. וְכֵן יָרָק הַבָּא מִחוּצָה לָאָרֶץ לָאָרֶץ אַף עַל פִּי שֶׁיֵּשׁ עָפָר בְּעִקָּרֶיהָ הֲרֵי זֶה פָּטוּר וְלֹא גָּזְרוּ עָלָיו. הַתְּבוּאָה וְהַקִּטְנִית שֶׁזְּרָעָן לְיָרָק בָּטְלָה דַּעְתּוֹ אֵצֶל כָּל אָדָם. וְהַיָּרָק שֶׁלָּהֶן פָּטוּר. וְהַזֶּרַע חַיָּב בִּתְרוּמָה וּמַעַשְׂרוֹת:","הַתִּלְתָּן אַף עַל פִּי שֶׁאֵינוֹ אֹכֶל אָדָם כְּשֶׁיִּקְשׁוּ הוֹאִיל וְרֹב הָאָדָם אוֹכְלִין אוֹתָן בִּתְחִלָּתָן הֲרֵי הֵן חַיָּבִין בִּתְרוּמָה וּמַעֲשֵׂר:","וְאֵלּוּ פְּטוּרִין מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת. הַלֶּקֶט וְהַשִּׁכְחָה וְהַפֵּאָה וְהַפֶּרֶט וְהָעוֹלֵלוֹת. אֲפִלּוּ הֶעֱמִיד מֵהֶן כְּרִי. וְאִם עָשָׂה מֵהֶן גֹּרֶן בַּשָּׂדֶה הֻקְבְּעוּ לְמַעַשְׂרוֹת וּמַפְרִישׁ מֵהֶן תְּרוּמָה וּמַעַשְׂרוֹת. אֲבָל אִם עָשָׂה הַגֹּרֶן בָּעִיר פְּטוּרִין. שֶׁהֲרֵי קוֹל יֵשׁ לָהֶן שֶׁהַכּל יוֹדְעִין שֶׁהֵן לֶקֶט אוֹ שִׁכְחָה אוֹ פֵּאָה:","הַלֶּקֶט וְהַשִּׁכְחָה וְהַפֵּאָה שֶׁל עַכּוּ\"ם חַיָּבִין בִּתְרוּמָה וּמַעַשְׂרוֹת. אֶלָּא אִם כֵּן הִפְקִיר. וְכֵן הַתְּבוּאָה וְהַזֵּיתִים שֶׁלֹּא הֵבִיאוּ שְׁלִישׁ פְּטוּרִין מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת. וּמִנַּיִן יוֹדֵעַ. כָּל שֶׁזּוֹרְעָהּ וּמַצְמַחַת בְּיָדוּעַ שֶׁהֵבִיאָה שְׁלִישׁ. עָבַר וְהִפְרִישׁ מִתְּבוּאָה וְזֵיתִים שֶׁלֹּא הֵבִיאוּ שְׁלִישׁ אֵינָהּ תְּרוּמָה:","וְכֵן הַהֶפְקֵר פָּטוּר מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת. וַאֲפִלּוּ הִפְקִירוֹ הָעַכּוּ\"ם לוֹ. אֲבָל הַזּוֹרֵעַ שְׂדֵה הֶפְקֵר חַיָּב בִּתְרוּמָה וּמַעַשְׂרוֹת:","הִפְקִיר קָמָה וְזָכָה בָּהּ וְעָבַר וְהִפְרִישׁ מִמֶּנָּה תְּרוּמָה הֲרֵי זוֹ תְּרוּמָה. אֲבָל אִם הִפְקִיר שִׁבֳּלִים וְזָכָה בָּהֶן וְעָבַר וְהִפְרִישׁ מֵהֶן תְּרוּמָה אֵינָהּ תְּרוּמָה. וְכֵן כָּל הַמַּפְרִישׁ מִדָּבָר שֶׁאֵינוֹ חַיָּב תְּרוּמָה אֵינָהּ תְּרוּמָה. וְכֵן בְּמַעַשְׂרוֹת. דְּבָרִים שֶׁאֵין דֶּרֶךְ רֹב בְּנֵי אָדָם לְזָרְעָן בַּגִּנּוֹת וּבַשָּׂדוֹת אֶלָּא חֶזְקָתָן מִן הַהֶפְקֵר פְּטוּרִין מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת. כְּגוֹן הַשּׁוּם בַּעַל בֶּכִי. וּבָצָל שֶׁל רִכְפָּה. וּגְרִיס הַקִּלְקְלִי. וַעֲדָשִׁים הַמִּצְרִיּוֹת וְכַיּוֹצֵא בָּהֶן:","נִתְעָרֵב דָּבָר שֶׁחַיָּב בִּתְרוּמָה בְּדָבָר שֶׁאֵינוֹ חַיָּב. כְּגוֹן זֵיתֵי נִקּוּף שֶׁנִּתְעָרְבוּ בְּזֵיתֵי מָסִיק וְעִנְבֵי עוֹלֵלוֹת בְּעִנְבֵי בָּצִיר. אִם יֵשׁ לוֹ פֵּרוֹת אֲחֵרוֹת מוֹצִיא עַל הַחַיָּב לְפִי חֶשְׁבּוֹן. וְאִם אֵין לוֹ אֶלָּא אֵלּוּ מַפְרִישׁ תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר עַל הַכּל וּכְאִלּוּ הַכּל חַיָּב בִּתְרוּמָה. וּמַפְרִישׁ מַעֲשֵׂר רִאשׁוֹן וְשֵׁנִי לְפִי חֶשְׁבּוֹן דָּבָר הַחַיָּב:","הַתְּרוּמָה לַכֹּהֵן בֵּין טְהוֹרָה בֵּין טְמֵאָה אֲפִלּוּ נִטְמָא הַדָּגָן אוֹ הַתִּירוֹשׁ כֻּלּוֹ קֹדֶם שֶׁיַּפְרִישׁ הֲרֵי זֶה חַיָּב לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמָה בְּטֻמְאָה וְלִתְּנָהּ לַכֹּהֵן שֶׁנֶּאֱמַר (במדבר יח ח) \"וַאֲנִי נָתַתִּי לְךָ אֶת מִשְׁמֶרֶת תְּרוּמֹתָי\", אַחַת טְהוֹרָה וְאַחַת טְמֵאָה. הַטְּהוֹרָה נֶאֱכֶלֶת לַכֹּהֲנִים וְהַטְּמֵאָה יֵהָנוּ בִּשְׂרֵפָתָהּ. אִם הָיָה שֶׁמֶן מַדְלִיקִין אוֹתוֹ. וְאִם הָיָה דָּגָן וְכַיּוֹצֵא בּוֹ מַסִּיקִין בּוֹ אֶת הַתַּנּוּר:","וְכֵן תְּרוּמַת מַעֲשֵׂר אִם נִטְמֵאת אוֹ נִטְמָא הַמַּעֲשֵׂר מַפְרִישִׁין אוֹתָהּ בְּטֻמְאָה וְנִתֶּנֶת לַכֹּהֵן לֵהָנוֹת בִּשְׂרֵפָתָהּ:","וְכָל הַמַּפְרִישׁ תְּרוּמָה גְּדוֹלָה אוֹ תְּרוּמַת מַעֲשֵׂר מְבָרֵךְ קֹדֶם שֶׁיַּפְרִישׁ כְּדֶרֶךְ שֶׁמְּבָרְכִין עַל כָּל הַמִּצְוֹת כְּמוֹ שֶׁבֵּאַרְנוּ בִּבְרָכוֹת:","אֵין מוֹצִיאִין תְּרוּמָה מֵהָאָרֶץ לְחוּצָה לָאָרֶץ אֲפִלּוּ טְמֵאָה. וְאֵין מְבִיאִין תְּרוּמָה מִחוּצָה לָאָרֶץ לָאָרֶץ. וְאִם הֵבִיא לֹא תֵּאָכֵל מִפְּנֵי שֶׁהִיא טְמֵאָה בְּאֶרֶץ הַכּוּתִים. וְלֹא תִּשָּׂרֵף שֶׁלֹּא יֹאמְרוּ רָאִינוּ תְּרוּמָה שֶׁלֹּא נִטְמֵאת נִשְׂרֶפֶת. וְלֹא תַּחֲזֹר לְחוּצָה לָאָרֶץ שֶׁמָּא יֹאמְרוּ מוֹצִיאִין תְּרוּמָה לְחוּצָה לָאָרֶץ. אֶלָּא מַנִּיחִין אוֹתָהּ עַד שֶׁתִּטָּמֵא טֻמְאָה יְדוּעָה לַכּל אוֹ עַד שֶׁיָּבוֹא עֶרֶב הַפֶּסַח אִם הָיְתָה חָמֵץ וְתִשָּׂרֵף:"],"Mishneh Torah, Hiring 13":["הַבְּהֵמָה אוֹכֶלֶת כָּל זְמַן שֶׁהִיא עוֹשָׂה בְּגִדּוּלֵי קַרְקַע בֵּין בִּמְחֻבָּר בֵּין בְּתָלוּשׁ. וְאוֹכֶלֶת מִמַּשּׂאוֹי שֶׁעַל גַּבָּהּ עַד שֶׁתִּהְיֶה פּוֹרֶקֶת וּבִלְבַד שֶׁלֹּא יִטּל בְּיָדוֹ וְיַאֲכִילֶנָּה:","כָּל הַמּוֹנֵעַ הַבְּהֵמָה מִלֶּאֱכל בִּשְׁעַת מְלַאכְתָּהּ לוֹקֶה שֶׁנֶּאֱמַר (דברים כה ד) \"לֹא תַחְסֹם שׁוֹר בְּדִישׁוֹ\". אֶחָד שׁוֹר וְאֶחָד כָּל מִינֵי בְּהֵמָה וְחַיָּה בֵּין טְמֵאִין בֵּין טְהוֹרִין וְאֶחָד הַדִּישָׁה וְאֶחָד כָּל שְׁאָר הַמְּלָאכוֹת שֶׁל גִּדּוּלֵי קַרְקַע וְלֹא נֶאֱמַר שׁוֹר בְּדִישׁוֹ אֶלָּא בָּהוֹוֶה. וְהַחוֹסֵם אֶת הַפּוֹעֵל פָּטוּר. אֶחָד הַחוֹסֵם אוֹתָהּ בִּשְׁעַת מְלָאכָה וְאֶחָד הַחוֹסֵם אוֹתָהּ מִקֹּדֶם וְעָשָׂה בָּהּ מְלָאכָה וְהִיא חֲסוּמָה אֲפִלּוּ חֲסָמָהּ בְּקוֹל לוֹקֶה. שָׂכַר בְּהֵמָה וַחֲסָמָהּ וְדָשׁ בָּהּ לוֹקֶה וּמְשַׁלֵּם לַבְּעָלִים אַרְבַּעַת קַבִּין לְפָרָה וּשְׁלֹשֶׁת קַבִּין לַחֲמוֹר שֶׁמִּשְּׁעַת מְשִׁיכָה נִתְחַיֵּב בִּמְזוֹנוֹתֶיהָ. וְאֵינוֹ חַיָּב מַלְקוֹת עַד שֶׁיָּדוּשׁ בָּהּ חֲסוּמָה:","יִשְׂרָאֵל הַדָּשׁ בְּפָרָתוֹ שֶׁל עַכּוּ\"ם עוֹבֵר מִשּׁוּם בַּל (דברים כה ד) \"תַחְסֹם\". וְהָעַכּוּ\"ם הַדָּשׁ בְּפָרָתוֹ שֶׁל יִשְׂרָאֵל אֵינוֹ עוֹבֵר מִשּׁוּם בַּל תַחְסֹם. אָמַר לְעַכּוּ\"ם חֲסֹם פָּרָתִי וְדוּשׁ בָּהּ. יָשַׁב לָהּ קוֹץ בְּפִיהָ וְדָשׁ בָּהּ וַהֲרֵי אֵינָהּ אוֹכֶלֶת. הִרְבִּיץ לָהּ אֲרִי מִבַּחוּץ אוֹ שֶׁהִרְבִּיץ בְּנָהּ מִבַּחוּץ. הֲרֵי שֶׁצָּמְאָה וְאֵינוֹ מַשְׁקֶה אוֹתָהּ. פָּרַס עוֹר עַל גַּבֵּי הַדַּיִשׁ כְּדֵי שֶׁלֹּא תֹּאכַל. כָּל זֶה וְכַיּוֹצֵא בּוֹ אָסוּר וְאֵינוֹ לוֹקֶה. הָיָה הַדָּבָר שֶׁהִיא עוֹשָׂה בּוֹ רַע לִבְנֵי מֵעֶיהָ וּמַזִּיקָהּ אוֹ שֶׁהָיְתָה חוֹלָה וְאִם תֹּאכַל מִזֶּה מַתְרֶזֶת מֻתָּר לְמָנְעָהּ. שֶׁלֹּא הִקְפִּידָה תּוֹרָה אֶלָּא עַל הֲנָאָתָהּ וַהֲרֵי אֵינָהּ נֶהֱנֵית:","פָּרָה שֶׁל יִשְׂרָאֵל שֶׁהָיָה כֹּהֵן דָּשׁ בָּהּ בִּתְרוּמָה וּבִתְרוּמַת מַעֲשֵׂר שֶׁל וַדַּאי. וְכֵן פָּרוֹת הַדָּשׁוֹת בְּמַעֲשֵׂר שֵׁנִי. וּפָרוֹת הַמְהַלְּכוֹת עַל הַתְּבוּאָה. לְפִי שֶׁיָּרַט לָהֶן הַדֶּרֶךְ אֵינוֹ עוֹבֵר עֲלֵיהֶן מִשּׁוּם בַּל (דברים כה ד) \"תַּחְסֹם\". אֲבָל מִפְּנֵי מַרְאִית הָעַיִן אִם הָיוּ דָּשׁוֹת בִּתְרוּמָה וּמַעֲשֵׂר שֵׁנִי מֵבִיא מְעַט מֵאוֹתוֹ הַמִּין וְתוֹלֶה לָהֶן בַּקְּרֻסְטְלִין שֶׁבְּפִיהֶן:","הַדָּשׁ בְּמַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי וּבִתְרוּמַת מַעֲשֵׂר שֶׁל דְּמַאי וּבְגִדּוּלֵי תְּרוּמָה עוֹבֵר מִשּׁוּם בַּל (דברים כה ד) \"תַּחְסֹם\":","רַשַּׁאי בַּעַל הַפָּרָה לְהַרְעִיב פָּרָתוֹ וּלְסַגְּפָהּ כְּדֵי שֶׁתֹּאכַל הַרְבֵּה מִן הַדַּיִשׁ. וְרַשַּׁאי הַשּׂוֹכֵר לְהַאֲכִילָהּ פְּקִיעֵי עָמִיר כְּדֵי שֶׁלֹּא תֹּאכַל הַרְבֵּה מִן הַדַּיִשׁ. כַּיּוֹצֵא בּוֹ רַשַּׁאי בַּעַל הַבַּיִת לְהַשְׁקוֹת פּוֹעֲלִים יַיִן כְּדֵי שֶׁלֹּא יֹאכְלוּ עֲנָבִים הַרְבֵּה. וְרַשָּׁאִין פּוֹעֲלִין לִטְבּל פִּתָּן בְּצִיר כְּדֵי שֶׁיֹּאכְלוּ עֲנָבִים הַרְבֵּה. אֲבָל אֵין הַפּוֹעֵל רַשַּׁאי לַעֲשׂוֹת מְלַאכְתּוֹ בַּלַּיְלָה וּלְהַשְׂכִּיר עַצְמוֹ בַּיּוֹם אוֹ לָדוּשׁ בְּפָרָתוֹ עַרְבִית וּלְהַשְׂכִּירָהּ שַׁחֲרִית. וְלֹא יִהְיֶה מַרְעִיב וּמְסַגֵּף עַצְמוֹ וּמַאֲכִיל מְזוֹנוֹתָיו לְבָנָיו מִפְּנֵי גֵּזֶל מְלַאכְתּוֹ שֶׁל בַּעַל הַבַּיִת. שֶׁהֲרֵי תָּשֵׁשׁ כֹּחוֹ וְתֵחָלֵשׁ דַּעְתּוֹ וְלֹא יַעֲשֶׂה מְלָאכָה בְּכֹחַ:","כְּדֶרֶךְ שֶׁמֻּזְהָר בַּעַל הַבַּיִת שֶׁלֹּא יִגְזל שְׂכַר עָנִי וְלֹא יְעַכְּבֶנּוּ כָּךְ הֶעָנִי מֻזְהָר שֶׁלֹּא יִגְזל מְלֶאכֶת בַּעַל הַבַּיִת וְיִבָּטֵל מְעַט בְּכָאן וּמְעַט בְּכָאן וּמוֹצִיא כָּל הַיּוֹם בְּמִרְמָה אֶלָּא חַיָּב לְדַקְדֵּק עַל עַצְמוֹ בַּזְּמַן שֶׁהֲרֵי הִקְפִּידוּ עַל בְּרָכָה רְבִיעִית שֶׁל בִּרְכַּת הַמָּזוֹן שֶׁלֹּא יְבָרֵךְ אוֹתָהּ. וְכֵן חַיָּב לַעֲבֹד בְּכָל כֹּחוֹ שֶׁהֲרֵי יַעֲקֹב הַצַּדִּיק אָמַר (בראשית לא ו) \"כִּי בְּכָל כֹּחִי עָבַדְתִּי אֶת אֲבִיכֶן\". לְפִיכָךְ נָטַל שְׂכַר זֹאת אַף בָּעוֹלָם הַזֶּה שֶׁנֶּאֱמַר (בראשית ל מג) \"וַיִּפְרֹץ הָאִישׁ מְאֹד מְאֹד\": סְלִיקוּ לְהוּ הִלְכוֹת שְׂכִירוּת"],"Mishneh Torah, Human Dispositions 4":["הוֹאִיל וֶהֱיוֹת הַגּוּף בָּרִיא וְשָׁלֵם מִדַּרְכֵי הַשֵּׁם הוּא. שֶׁהֲרֵי אִי אֶפְשָׁר שֶׁיָּבִין אוֹ יֵדַע דָּבָר מִידִיעַת הַבּוֹרֵא וְהוּא חוֹלֶה. לְפִיכָךְ צָרִיךְ לְהַרְחִיק אָדָם עַצְמוֹ מִדְּבָרִים הַמְאַבְּדִין אֶת הַגּוּף. וּלְהַנְהִיג עַצְמוֹ בִּדְבָרִים הַמַּבְרִין וְהַמַּחֲלִימִים. וְאֵלּוּ הֵן: לְעוֹלָם לֹא יֹאכַל אָדָם אֶלָּא כְּשֶׁהוּא רָעֵב. וְלֹא יִשְׁתֶּה אֶלָּא כְּשֶׁהוּא צָמֵא. וְאַל יַשְׁהֵא נְקָבָיו אֲפִלּוּ רֶגַע אֶחָד. אֶלָּא כָּל זְמַן שֶׁצָּרִיךְ לְהַשְׁתִּין אוֹ לְהָסֵךְ אֶת רַגְלָיו יַעֲמֹד מִיָּד:","לֹא יֹאכַל אָדָם עַד שֶׁתִּתְמַלֵּא כְּרֵסוֹ אֶלָּא יִפְחֹת כְּמוֹ רְבִיעַ מִשָּׂבְעָתוֹ. וְלֹא יִשְׁתֶּה מַיִם בְּתוֹךְ הַמָּזוֹן אֶלָּא מְעַט וּמָזוּג בְּיַיִן. וּכְשֶׁיַּתְחִיל הַמָּזוֹן לְהִתְעַכֵּל בְּמֵעָיו שׁוֹתֶה מַה שֶּׁהוּא צָרִיךְ לִשְׁתּוֹת. וְלֹא יַרְבֶּה לִשְׁתּוֹת מַיִם וַאֲפִלּוּ כְּשֶׁיִּתְעַכֵּל הַמָּזוֹן. וְלֹא יֹאכַל עַד שֶׁיִּבְדֹּק עַצְמוֹ יָפֶה יָפֶה שֶׁמָּא יִהְיֶה צָרִיךְ לִנְקָבָיו. לֹא יֹאכַל אָדָם עַד שֶׁיֵּלֵךְ קדֶם אֲכִילָה עַד שֶׁיַּתְחִיל גּוּפוֹ לָחֹם. אוֹ יַעֲשֶׂה מְלַאכְתּוֹ אוֹ יִתְיַגֵּעַ בְּיֶגַע אַחֵר. כְּלָלוֹ שֶׁל דָּבָר יְעַנֶּה גּוּפוֹ וְיִיגַע כָּל יוֹם בַּבֹּקֶר עַד שֶׁיַּתְחִיל גּוּפוֹ לָחֹם וְיִשְׁקֹט מְעַט עַד שֶׁתִּתְיַשֵּׁב נַפְשׁוֹ וְאוֹכֵל. וְאִם רָחַץ בְּחַמִּין אַחַר שֶׁיָּגַע הֲרֵי זֶה טוֹב וְאַחַר כָּךְ שׁוֹהֶה מְעַט וְאוֹכֵל:","לְעוֹלָם כְּשֶׁיֹּאכַל אָדָם יֵשֵׁב בִּמְקוֹמוֹ אוֹ יִטֶּה עַל שְׂמֹאל. וְלֹא יְהַלֵּךְ וְלֹא יִרְכַּב וְלֹא יִיגַע וְלֹא יְזַעֲזֵעַ גּוּפוֹ וְלֹא יְטַיֵּל עַד שֶׁיִּתְעַכֵּל הַמָּזוֹן שֶׁבְּמֵעָיו. וְכָל הַמְטַיֵּל אַחַר אֲכִילָתוֹ אוֹ שֶׁיָּגֵעַ הֲרֵי זֶה מֵבִיא עַל עַצְמוֹ חֳלָאִים רָעִים וְקָשִׁים:","הַיּוֹם וְהַלַּיְלָה כ\"ד שָׁעוֹת. דַּי לוֹ לָאָדָם לִישֹׁן שְׁלִישָׁן שֶׁהוּא שְׁמוֹנֶה שָׁעוֹת. וְיִהְיוּ בְּסוֹף הַלַּיְלָה כְּדֵי שֶׁתִּהְיֶה מִתְּחִלַּת שְׁנָתוֹ עַד שֶׁתַּעֲלֶה הַשֶּׁמֶשׁ שְׁמוֹנֶה שָׁעוֹת. וְנִמְצָא עוֹמֵד מִמִּטָּתוֹ קֹדֶם שֶׁתַּעֲלֶה הַשֶּׁמֶשׁ:","לֹא יִישַׁן אָדָם לֹא עַל פָּנָיו וְלֹא עַל עָרְפּוֹ אֶלָּא עַל צִדּוֹ. בִּתְחִלַּת הַלַּיְלָה עַל צַד שְׂמֹאל. וּבְסוֹף הַלַּיְלָה עַל צַד יָמִין. וְלֹא יִישַׁן סָמוּךְ לַאֲכִילָה אֶלָּא יַמְתִּין אַחַר אֲכִילָה כְּמוֹ שָׁלֹשׁ אוֹ אַרְבַּע שָׁעוֹת. וְלֹא יִישַׁן בַּיּוֹם:","דְּבָרִים הַמְשַׁלְשְׁלִין אֶת בְּנֵי מֵעַיִם כְּגוֹן עֲנָבִים וּתְאֵנִים וְתוּתִים וַאֲגַסִּים וַאֲבַטִּיחִים וּמִינֵי הַקִּשּׁוּאִים וּמִינֵי מְלָפְפוֹנוֹת אוֹכֵל אוֹתָם הָאָדָם בַּתְּחִלָּה קֹדֶם אֲכִילָה. וְלֹא יְעָרְבֵם עִם הַמָּזוֹן. אֶלָּא שׁוֹהֶה מְעַט עַד שֶׁיֵּצְאוּ מִבֶּטֶן הָעֶלְיוֹן וְאוֹכֵל מְזוֹנוֹ. וּדְבָרִים שֶׁמְּאַמְּצִין אֶת בְּנֵי מֵעַיִם כְּגוֹן רִמּוֹנִים וּפְרִישִׁים וְתַפּוּחִים וּקְרוֹסְטוֹמוֹלִין אוֹכֵל אוֹתָן תֵּכֶף לִמְזוֹנוֹ. וְלֹא יַרְבֶּה לֶאֱכל מֵהֶן:","כְּשֶׁיִּרְצֶה אָדָם לֶאֱכל בְּשַׂר עוֹף וּבְשַׂר בְּהֵמָה כְּאֶחָד. אוֹכֵל בַּתְּחִלָּה בְּשַׂר הָעוֹף. וְכֵן בֵּיצִים וּבְשַׂר עוֹף אוֹכֵל בַּתְּחִלָּה בֵּיצִים. בְּשַׂר בְּהֵמָה דַּקָּה וּבְשַׂר בְּהֵמָה גַּסָּה אוֹכֵל בַּתְּחִלָּה בְּשַׂר דַּקָּה. לְעוֹלָם יַקְדִּים אָדָם דָּבָר הַקַּל וּמְאַחֵר הַכָּבֵד:","בִּימוֹת הַחַמָּה אוֹכֵל מַאֲכָלִים הַקָּרִים וְלֹא יַרְבֶּה בִּתְבָלִים וְאוֹכֵל אֶת הַחֹמֶץ. וּבִימוֹת הַגְּשָׁמִים אוֹכֵל מַאֲכָלִים הַחַמִּים וּמַרְבֶּה בִּתְבָלִים וְאוֹכֵל מְעַט מִן הַחַרְדָּל וּמִן הַחִלְתִּית. וְעַל דֶּרֶךְ זוֹ הוֹלֵךְ וְעוֹשֶׂה בַּמְּקוֹמוֹת הַקָּרִים וּבַמְּקוֹמוֹת הַחַמִּים בְּכָל מָקוֹם וּמָקוֹם הָרָאוּי לוֹ:","יֵשׁ מַאֲכָלוֹת שֶׁהֵם רָעִים בְּיוֹתֵר עַד מְאֹד וְרָאוּי לָאָדָם שֶׁלֹּא לְאָכְלָן לְעוֹלָם. כְּגוֹן הַדָּגִים הַגְּדוֹלִים הַמְּלוּחִים הַיְשָׁנִים. וְהַגְּבִינָה הַמְּלוּחָה הַיְשָׁנָה. וְהַכְּמֵהִין וּפִטְרִיּוֹת וְהַבָּשָׂר הַמָּלִיחַ הַיָּשָׁן. וְיַיִן מִגִּתּוֹ. וְתַבְשִׁיל שֶׁשָּׁהָא עַד שֶׁנָּדַף רֵיחוֹ. וְכֵן כָּל מַאֲכָל שֶׁרֵיחוֹ רַע אוֹ מַר בְּיוֹתֵר. הֲרֵי אֵלּוּ לַגּוּף כְּמוֹ סַם הַמָּוֶת. וְיֵשׁ מַאֲכָלוֹת שֶׁהֵן רָעִים אֲבָל אֵינָן כְּמוֹ הָרִאשׁוֹנִים לְרֹעַ. לְפִיכָךְ רָאוּי לָאָדָם שֶׁלֹּא לֶאֱכל מֵהֶן אֶלָּא מְעַט וְאַחַר יָמִים הַרְבֵּה. וְלֹא יַרְגִּיל עַצְמוֹ לִהְיוֹת מְזוֹנוֹ מֵהֶם אוֹ לְאָכְלָן עִם מְזוֹנוֹ תָּמִיד. כְּגוֹן דָּגִים גְּדוֹלִים וּגְבִינָה וְחָלָב שֶׁשָּׁהָא אַחַר שֶׁנֶּחְלַב כ\"ד שָׁעוֹת. וּבְשַׂר שְׁוָרִים גְּדוֹלִים וּתְיָשִׁים גְּדוֹלִים וְהַפּוֹל וְהָעֲדָשִׁים וְהַסַּפִּיר וְלֶחֶם שְׂעוֹרִים וְלֶחֶם מַצּוֹת וְהַכְּרוּב וְהֶחָצִיר וְהַבְּצָלִים וְהַשּׁוּמִים וְהַחַרְדָּל וְהַצְּנוֹן. כָּל אֵלּוּ מַאֲכָלִים רָעִים הֵם אֵין רָאוּי לָאָדָם לֶאֱכל מֵאֵלּוּ אֶלָּא מְעַט עַד מְאֹד וּבִימוֹת הַגְּשָׁמִים. אֲבָל בִּימוֹת הַחַמָּה לֹא יֹאכַל מֵהֶן כְּלָל. וְהַפּוֹל וְהָעֲדָשִׁים בִּלְבַד אֵין רָאוּי לְאָכְלָן לֹא בִּימוֹת הַחַמָּה וְלֹא בִּימוֹת הַגְּשָׁמִים. וְהַדְּלוּעִין אוֹכְלִין מֵהֶן בִּימוֹת הַחַמָּה:","וְיֵשׁ מַאֲכָלוֹת שֶׁהֵם רָעִים וְאֵינָן כְּמוֹ אֵלּוּ. וְהֵם עוֹף הַמַּיִם וּבְנֵי יוֹנָה הַקְּטַנִּים וְהַתְּמָרִים וְלֶחֶם קָלוּי בְּשֶׁמֶן אוֹ לֶחֶם שֶׁנִּלּוֹשׁ בְּשֶׁמֶן וְהַסּלֶת שֶׁנִּפּוּ אוֹתָהּ כָּל צָרְכָּהּ עַד שֶׁלֹּא נִשְׁאֲרָה בָּהּ רֵיחַ מוּרְסָן. וְהַצִּיר וְהַמּוּרְיָיס. אֵין רָאוּי לְהַרְבּוֹת מַאֲכָלוֹת אֵלּוּ. וְאָדָם שֶׁהוּא חָכָם וְכוֹבֵשׁ אֶת יִצְרוֹ וְלֹא יִמָּשֵׁךְ אַחַר תַּאֲוָתוֹ וְלֹא יֹאכַל מִן הַנִּזְכָּרִים כְּלוּם אֶלָּא אִם נִצְרָךְ לָהֶם לִרְפוּאָה הֲרֵי זֶה גִּבּוֹר:","לְעוֹלָם יִמְנַע אָדָם עַצְמוֹ מִפֵּרוֹת הָאִילָנוֹת. וְלֹא יַרְבֶּה מֵהֶן וַאֲפִלּוּ יְבֵשִׁין וְאֵין צָרִיךְ לוֹמַר רְטֻבִּים. אֲבָל קֹדֶם שֶׁיִּתְבַּשְּׁלוּ כָּל צָרְכָּן הֲרֵי הֵן כַּחֲרָבוֹת לַגּוּף. וְכֵן הַחֲרוּבִים רָעִים לְעוֹלָם. וְכָל הַפֵּרוֹת הַחֲמוּצִין רָעִים וְאֵין אוֹכְלִין מֵהֶן אֶלָּא מְעַט בִּימוֹת הַחַמָּה וּבַמְּקוֹמוֹת הַחַמִּים. וְהַתְּאֵנִים וְהָעֲנָבִים וְהַשְּׁקֵדִים לְעוֹלָם טוֹבִים בֵּין רְטֻבִּין בֵּין יְבֵשִׁין וְאוֹכֵל אָדָם מֵהֶם כָּל צָרְכּוֹ. וְלֹא יַתְמִיד אֲכִילָתָם אַף עַל פִּי שֶׁהֵן טוֹבִים מִכָּל פְּרִי הָאִילָנוֹת:","הַדְּבַשׁ וְהַיַּיִן רַע לַקְּטַנִּים וְיָפֶה לַזְּקֵנִים וְכָל שֶׁכֵּן בִּימוֹת הַגְּשָׁמִים. וְצָרִיךְ אָדָם לֶאֱכל בִּימוֹת הַחַמָּה שְׁנֵי שְׁלִישִׁים מַה שֶּׁהוּא אוֹכֵל בִּימוֹת הַגְּשָׁמִים:","לְעוֹלָם יִשְׁתַּדֵּל אָדָם שֶׁיִּהְיוּ מֵעָיו רָפִין כָּל יָמָיו וְיִהְיֶה קָרוֹב לְשִׁלְשׁוּל מְעַט. וְזֶה כְּלָל גָּדוֹל בָּרְפוּאָה כָּל זְמַן שֶׁהָרְעִי נִמְנָע אוֹ יוֹצֵא בְּקֹשִׁי חֳלָאִים רָעִים בָּאִים. וּבַמֶּה יַרְפֶּה אָדָם מֵעָיו אִם יִתְאַמְּצוּ מְעַט. אִם הָיָה בָּחוּר יֹאכַל בַּבֹּקֶר בַּבֹּקֶר מְלוּחִים שְׁלוּקִים מְתֻבָּלִין בְּשֶׁמֶן זַיִת וּבְמוּרְיָיס וּבְמֶלַח בְּלֹא פַּת. אוֹ יִשְׁתֶּה מֵי שֶׁלֶק שֶׁל תְּרָדִין אוֹ כְּרוּב בְּשֶׁמֶן זַיִת וּמוּרְיָיס וּמֶלַח. וְאִם הָיָה זָקֵן יִשְׁתֶּה דְּבַשׁ מָזוּג בְּמַיִם חַמִּים בַּבֹּקֶר וְיִשְׁהֵא כְּמוֹ אַרְבַּע שָׁעוֹת וְאַחַר כָּךְ יֹאכַל סְעֻדָּתוֹ. וְיַעֲשֶׂה כֵן יוֹם אֶחָד אוֹ שְׁלֹשָׁה אוֹ אַרְבָּעָה יָמִים אִם צָרִיךְ לְכָךְ עַד שֶׁיִּרְפּוּ מֵעָיו:","וְעוֹד כְּלָל אַחֵר אָמְרוּ בִּבְרִיאוּת הַגּוּף. כָּל זְמַן שֶׁאָדָם מִתְעַמֵּל וְיָגֵעַ הַרְבֵּה וְאֵינוֹ שָׂבֵעַ וּמֵעָיו רָפִין אֵין חלִי בָּא עָלָיו וְכֹחוֹ מִתְחַזֵּק. וַאֲפִלּוּ אוֹכֵל מַאֲכָלוֹת הָרָעִים:","וְכָל מִי שֶׁהוּא יוֹשֵׁב לָבֶטַח וְאֵינוֹ מִתְעַמֵּל. אוֹ מִי שֶׁמַּשְׁהֵא נְקָבָיו. אוֹ מִי שֶׁמֵּעָיו קָשִׁין. אֲפִלּוּ אָכַל מַאֲכָלוֹת טוֹבִים וְשָׁמַר עַצְמוֹ עַל פִּי הָרְפוּאָה. כָּל יָמָיו יִהְיוּ מַכְאוֹבִים וְכֹחוֹ תָּשֵׁשׁ. וַאֲכִילָה גַּסָּה לְגוּף כָּל אָדָם כְּמוֹ סַם הַמָּוֶת. וְהוּא עִקָּר לְכָל הֶחֳלָאִים. וְרֹב הֶחֳלָאִים שֶׁבָּאִים עַל הָאָדָם אֵינָם אֶלָּא אוֹ מִפְּנֵי מַאֲכָלִים רָעִים. אוֹ מִפְּנֵי שֶׁהוּא מְמַלֵּא בִּטְנוֹ וְאוֹכֵל אֲכִילָה גַּסָּה אֲפִלּוּ מִמַּאֲכָלִים טוֹבִים. הוּא שֶׁשְּׁלֹמֹה אָמַר בְּחָכְמָתוֹ (משלי כא כג) \"שֹׁמֵר פִּיו וּלְשׁוֹנוֹ שֹׁמֵר מִצָּרוֹת נַפְשׁוֹ\". כְּלוֹמַר שׁוֹמֵר פִּיו מִלֶּאֱכל מַאֲכָל רַע אוֹ מִלִּשְׂבֹּעַ וּלְשׁוֹנוֹ מִלְּדַבֵּר אֶלָּא בִּצְרָכָיו:","דֶּרֶךְ הָרְחִיצָה. שֶׁיִּכָּנֵס אָדָם לַמֶּרְחָץ מִשִּׁבְעָה יָמִים לְשִׁבְעָה יָמִים. וְלֹא יִכָּנֵס סָמוּךְ לַאֲכִילָה. וְלֹא כְּשֶׁהוּא רָעֵב. אֶלָּא כְּשֶׁיַּתְחִיל הַמָּזוֹן לְהִתְעַכֵּל. וְרוֹחֵץ כָּל גּוּפוֹ בְּחַמִּין שֶׁאֵין הַגּוּף נִכְוֶה בָּהֶן. וְרֹאשׁוֹ בִּלְבַד בְּחַמִּין שֶׁהַגּוּף נִכְוֶה בָּהֶן. וְאַחַר כָּךְ יִרְחַץ גּוּפוֹ בְּפוֹשְׁרִין וְאַחַר כָּךְ בְּפוֹשְׁרִין מִן הַפּוֹשְׁרִין עַד שֶׁיִּרְחַץ בְּצוֹנֵן. וְלֹא יַעֲבֹר עַל רֹאשׁוֹ מַיִם לֹא פּוֹשְׁרִין וְלֹא צוֹנֵן. וְלֹא יִרְחַץ בְּצוֹנֵן בִּימוֹת הַגְּשָׁמִים. וְלֹא יִרְחַץ עַד שֶׁיַּזִּיעַ וִיפָרֵךְ כָּל גּוּפוֹ. וְלֹא יַאֲרִיךְ בַּמֶּרְחָץ אֶלָּא כְּשֶׁיַּזִּיעַ וִיפָרֵךְ גּוּפוֹ יִשְׁתַּטֵּף וְיֵצֵא. וּבוֹדֵק עַצְמוֹ קֹדֶם שֶׁיִּכָּנֵס לַמֶּרְחָץ וְאַחַר שֶׁיֵּצֵא שֶׁמָּא יְהֵא צָרִיךְ לִנְקָבָיו. וְכֵן בּוֹדֵק אָדָם עַצְמוֹ תָּמִיד קֹדֶם אֲכִילָה וְאַחַר אֲכִילָה. וְקֹדֶם בְּעִילָה וְאַחַר בְּעִילָה. וְקֹדֶם שֶׁיִּיגַע וְיִתְעַמֵּל וְאַחַר שֶׁיִּיגַע וְיִתְעַמֵּל. וְקֹדֶם שֶׁיִּישַׁן וְאַחַר שֶׁיִּישַׁן. וּבְשִׁעוּר הַכּל עֲשָׂרָה:","כְּשֶׁיֵּצֵא אָדָם מִן הַמֶּרְחָץ יִלְבַּשׁ בְּגָדָיו וִיכַסֶּה רֹאשׁוֹ בַּבַּיִת הַחִיצוֹן כְּדֵי שֶׁלֹּא תִּשְׁלֹט בּוֹ רוּחַ קָרָה. וַאֲפִלּוּ בִּימוֹת הַחַמָּה צָרִיךְ לְהִזָּהֵר. וְיִשְׁהֵא אַחַר שֶׁיֵּצֵא עַד שֶׁתִּתְיַשֵּׁב נַפְשׁוֹ וְיָנוּחַ גּוּפוֹ וְתָסוּר הַחֲמִימוּת וְאַחַר כָּךְ יֹאכַל. וְאִם יָשֵׁן מְעַט כְּשֶׁיֵּצֵא מִן הַמֶּרְחָץ קֹדֶם אֲכִילָה הֲרֵי זֶה יָפֶה מְאֹד. וְלֹא יִשְׁתֶּה מַיִם קָרִים בְּצֵאתוֹ מִן הַמֶּרְחָץ וְאֵין צָרִיךְ לוֹמַר שֶׁלֹּא יִשְׁתֶּה בַּמֶּרְחָץ. וְאִם צָמֵא כְּשֶׁיָּצָא מִן הַמֶּרְחָץ וְאֵינוֹ יָכוֹל לִמְנֹעַ עַצְמוֹ יְעָרֵב הַמַּיִם בְּיַיִן אוֹ בִּדְבַשׁ וְיִשְׁתֶּה. וְאִם סָךְ בְּשֶׁמֶן בַּמֶּרְחָץ בִּימוֹת הַגְּשָׁמִים אַחַר שֶׁיִּשְׁתַּטֵּף הֲרֵי זֶה טוֹב:","לֹא יַרְגִּיל אָדָם לְהַקִּיז דָּם תָּמִיד. וְלֹא יַקִּיז אֶלָּא אִם יִהְיֶה צָרִיךְ לוֹ בְּיוֹתֵר. וְלֹא יַקִּיז לֹא בִּימוֹת הַחַמָּה וְלֹא בִּימוֹת הַגְּשָׁמִים אֶלָּא מְעַט בִּימֵי נִיסָן וּמְעַט בִּימֵי תִּשְׁרֵי. וּמֵאַחַר חֲמִשִּׁים שָׁנָה לֹא יַקִּיז כְּלָל. וְלֹא יַקִּיז אָדָם דָּם וְיִכָּנֵס לַמֶּרְחָץ בּוֹ בַּיּוֹם. וְלֹא יַקִּיז וְיֵצֵא לַדֶּרֶךְ. וְלֹא בְּיוֹם שֶׁיָּבוֹא מִן הַדֶּרֶךְ. וְיֹאכַל וְיִשְׁתֶּה בְּיוֹם הַהַקָּזָה פָּחוֹת מִמַּה שֶּׁהוּא רָגִיל. וְיָנוּחַ בְּיוֹם הַהַקָּזָה וְלֹא יִיגַע וְלֹא יִתְעַמֵּל וְלֹא יְטַיֵּל:","שִׁכְבַת זֶרַע הִיא כֹּחַ הַגּוּף וְחַיָּיו וּמְאוֹר הָעֵינַיִם וְכָל שֶׁתֵּצֵא בְּיוֹתֵר הַגּוּף כָּלֶה וְכֹחוֹ כָּלֶה וְחַיָּיו אוֹבְדִים. הוּא שֶׁאָמַר שְׁלֹמֹה בְּחָכְמָתוֹ (משלי לא ג) \"אַל תִּתֵּן לַנָּשִׁים חֵילֶךָ\". כָּל הַשָּׁטוּף בִּבְעִילָה זִקְנָה קוֹפֶצֶת עָלָיו. וְכֹחוֹ תָּשֵׁשׁ. וְעֵינָיו כֵּהוֹת. וְרֵיחַ רַע נוֹדֵף מִפִּיו וּמִשֶּׁחְיוֹ. וּשְׂעַר רֹאשׁוֹ וְגַבּוֹת עֵינָיו וְרִיסֵי עֵינָיו נוֹשְׁרוֹת. וּשְׂעַר זְקָנוֹ וְשֶׁחְיוֹ וּשְׂעַר רַגְלָיו רַבֶּה. שִׁנָּיו נוֹפְלוֹת. וְהַרְבֵּה כְּאֵבִים חוּץ מֵאֵלּוּ בָּאִים עָלָיו. אָמְרוּ חַכְמֵי הָרוֹפְאִים אֶחָד מֵאֶלֶף מֵת בִּשְׁאָר חֳלָאִים וְהָאֶלֶף מֵרֹב הַתַּשְׁמִישׁ. לְפִיכָךְ צָרִיךְ אָדָם לְהִזָּהֵר בְּדָבָר זֶה אִם רָצָה לִחְיוֹת בְּטוֹבָה. וְלֹא יִבְעֹל אֶלָּא כְּשֶׁיִּמָּצֵא גּוּפוֹ בָּרִיא וְחָזָק בְּיוֹתֵר וְהוּא מִתְקַשֶּׁה הַרְבֵּה שֶׁלֹּא לְדַעְתּוֹ. וּמַסִּיחַ עַצְמוֹ לְדָבָר אַחֵר וְהַקִּשּׁוּי בּוֹ כְּשֶׁהָיָה. וְיִמָּצֵא כֹּבֶד מִמָּתְנָיו וּלְמַטָּה וּכְאִלּוּ חוּטֵי הַבֵּיצִים נִמְשָׁכִים וּבְשָׂרוֹ חַם. זֶה צָרִיךְ לִבְעל וּרְפוּאָה לוֹ שֶׁיִּבְעל. לֹא יִבְעֹל אָדָם וְהוּא שָׂבֵעַ וְלֹא רָעֵב אֶלָּא אַחַר שֶׁיִּתְעַכֵּל הַמָּזוֹן שֶׁבְּמֵעָיו. וְיִבְדֹק נְקָבָיו קֹדֶם בְּעִילָה וּלְאַחַר בְּעִילָה. וְלֹא יִבְעֹל מְעֻמָּד וְלֹא מְיֻשָּׁב. וְלֹא בְּבֵית הַמֶּרְחָץ וְלֹא בְּיוֹם שֶׁיִּכָּנֵס לַמֶּרְחָץ. וְלֹא בְּיוֹם הַקָּזָה. וְלֹא בְּיוֹם יְצִיאָה לַדֶּרֶךְ אוֹ בִּיאָה מִן הַדֶּרֶךְ לֹא לִפְנֵיהֶם וְלֹא לְאַחֲרֵיהֶם:","כָּל הַמַּנְהִיג עַצְמוֹ בִּדְרָכִים אֵלּוּ שֶׁהוֹרִינוּ אֲנִי עָרֵב לוֹ שֶׁאֵינוֹ בָּא לִידֵי חֹלִי כָּל יָמָיו עַד שֶׁיַּזְקִין הַרְבֵּה וְיָמוּת וְאֵינוֹ צָרִיךְ לְרוֹפֵא. וְיִהְיֶה גּוּפוֹ שָׁלֵם וְעוֹמֵד עַל בֻּרְיוֹ כָּל יָמָיו. אֶלָּא אִם כֵּן הָיָה גּוּפוֹ רַע מִתְּחִלַּת בְּרִיָּתוֹ. אוֹ אִם הָיָה רָגִיל בְּמִנְהָג מִן הַמִּנְהָגוֹת הָרָעִים מִתְּחִלַּת מוֹלַדְתּוֹ. אוֹ אִם תָּבוֹא מַכַּת דֶּבֶר אוֹ מַכַּת בַּצֹּרֶת לָעוֹלָם:","וְכָל הַמִּנְהָגוֹת הַטּוֹבִים הָאֵלּוּ שֶׁאָמַרְנוּ אֵין רָאוּי לִנְהֹג בָּהֶן אֶלָּא הַבָּרִיא. אֲבָל הַחוֹלֶה אוֹ מִי שֶׁאֶחָד מֵאֵיבָרָיו חוֹלֶה אוֹ מִי שֶׁנָּהַג מִנְהָג רַע שָׁנִים רַבּוֹת. יֵשׁ לְכָל אֶחָד מֵהֶם דְּרָכִים אֲחֵרִים וְהַנְהָגוֹת כְּפִי חָלְיוֹ כְּמוֹ שֶׁיִּתְבָּאֵר בְּסֵפֶר הָרְפוּאוֹת. וְשִׁנּוּי וֶסֶת תְּחִלַּת חלִי:","כָּל מָקוֹם שֶׁאֵין בּוֹ רוֹפֵא. אֶחָד הַבָּרִיא וְאֶחָד הַחוֹלֶה אֵין רָאוּי לוֹ לָזוּז מִכָּל הַדְּרָכִים הָאֵלּוּ שֶׁנֶּאֶמְרוּ בְּפֶרֶק זֶה. שֶׁכָּל אֶחָד מֵהֶן לְאַחֲרִית טוֹבָה מֵבִיא:","כָּל עִיר שֶׁאֵין בָּהּ עֲשָׂרָה דְּבָרִים הָאֵלּוּ אֵין תַּלְמִיד חָכָם רַשַּׁאי לָדוּר בְּתוֹכָהּ. וְאֵלּוּ הֵן: רוֹפֵא. וְאֻמָּן. וּבֵית הַמֶּרְחָץ. וּבֵית הַכִּסֵּא. וּמַיִם מְצוּיִין כְּגוֹן נָהָר וּמַעְיָן. וּבֵית הַכְּנֶסֶת. וּמְלַמֵּד תִּינוֹקוֹת. וְלַבְלָר. וְגַבַּאי צְדָקָה. וּבֵית דִּין מַכִּים וְחוֹבְשִׁים:"],"Mishneh Torah, Immersion Pools 7":["אֵין הַמִּקְוֶה נִפְסָל לֹא בְּשִׁנּוּי הַטַּעַם וְלֹא בְּשִׁנּוּי הָרֵיחַ אֶלָּא בְּשִׁנּוּי מַרְאֶה בִּלְבַד. וְכָל דָּבָר שֶׁאֵין עוֹשִׂין בּוֹ מִקְוֶה לְכַתְּחִלָּה פּוֹסֵל אֶת הַמִּקְוֶה בְּשִׁנּוּי מַרְאֶה. כֵּיצַד. הַיַּיִן אוֹ הֶחָלָב וְהַדָּם וְכַיּוֹצֵא בָּהֶן מִמֵּי כָּל הַפֵּרוֹת אֵינָן פּוֹסְלִין אֶת הַמִּקְוֶה בִּשְׁלֹשָׁה לוֹגִין שֶׁלֹּא אָמְרוּ אֶלָּא מַיִם שְׁאוּבִין. וּפוֹסְלִין בְּשִׁנּוּי מַרְאֶה אֲפִלּוּ מִקְוֶה שֶׁיֵּשׁ בּוֹ מֵאָה סְאָה וְנָפַל לוֹ לוֹג יַיִן אוֹ מֵי פֵּרוֹת וְשִׁנָּה אֶת מַרְאָיו פָּסוּל. וְכֵן מִקְוֶה שֶׁיֵּשׁ בּוֹ עֶשְׂרִים סְאָה מַיִם כְּשֵׁרִים אוֹ פָּחוֹת מִזֶּה וְנָפַל לְתוֹכוֹ סְאָה יַיִן אוֹ מֵי פֵּרוֹת וְלֹא שִׁנּוּ אֶת מַרְאָיו הֲרֵי אֵלּוּ כְּשֵׁרִים כְּשֶׁהָיוּ. וְאֵין הַסְּאָה שֶׁנָּפְלָה עוֹלָה לְמִדַּת הַמִּקְוֶה. וְאִם נוֹסַף עַל הָעֶשְׂרִים עֶשְׂרִים אֲחֵרִים מַיִם כְּשֵׁרִים הֲרֵי זֶה מִקְוֶה כָּשֵׁר:","יֵשׁ מַעֲלִין אֶת הַמִּקְוֶה וְלֹא פּוֹסְלִין פּוֹסְלִין וְלֹא מַעֲלִין לֹא מַעֲלִין וְלֹא פּוֹסְלִין:","וְאֵלּוּ מַעֲלִין וְלֹא פּוֹסְלִין. הַשֶּׁלֶג. וְהַבָּרָד. וְהַכְּפוֹר. וְהַגְּלִיד. וְהַמֶּלַח. וְטִיט הַנֵּרוֹק. כֵּיצַד. מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה חָסֵר אַחַת וְנָפַל לְתוֹכוֹ סְאָה מֵאֶחָד מֵאֵלּוּ הֲרֵי זֶה עוֹלֶה לְמִדָּתוֹ וַהֲרֵי הַמִּקְוֶה כָּשֵׁר וְשָׁלֵם. נִמְצְאוּ מַעֲלִין וְלֹא פּוֹסְלִין. אֲפִלּוּ הֵבִיא אַרְבָּעִים סְאָה שֶׁלֶג בַּתְּחִלָּה וְהִנִּיחָן בַּעֵקָּה וְרִסְּקוֹ שָׁם הֲרֵי זֶה מִקְוֶה שָׁלֵם וְכָשֵׁר:","וְאֵלּוּ פּוֹסְלִין וְלֹא מַעֲלִין. מַיִם שְׁאוּבִין בֵּין טְהוֹרִין בֵּין טְמֵאִים. וּמֵי כְּבָשִׁים. וּמֵי שְׁלָקוֹת. וְהַתֶּמֶד עַד שֶׁלֹּא הֶחְמִיץ. וְהַשֵּׁכָר. כֵּיצַד. מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה חָסֵר מִשְׁקַל דִּינָר וְנָפַל מֵאֶחָד מֵאֵלּוּ מִשְׁקַל דִּינָר לְתוֹכָן אֵינוֹ עוֹלֶה לְמִדַּת הַמִּקְוֶה וְלֹא הִשְׁלִימוֹ. וְאִם נָפַל מֵאֶחָד מֵהֶן שְׁלֹשָׁה לוֹגִין מֵהֶן פּוֹסְלִין אֶת הַמִּקְוֶה:","וְאֵלּוּ לֹא פּוֹסְלִין וְלֹא מַעֲלִין. שְׁאָר הַמַּשְׁקִין. וּמֵי פֵּרוֹת. וְהַצִּיר. וְהַמֻּרְיָס. וְהַתֶּמֶד מִשֶּׁהֶחְמִיץ. כֵּיצַד. מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה חָסֵר אֶחָד וְנָפַל מֵאֶחָד מֵאֵלּוּ סְאָה לְתוֹכָן לֹא הֶעֱלָהוּ וַהֲרֵי הַמַּיִם כְּשֵׁרִים כְּשֶׁהָיוּ שֶׁאֵין אֵלּוּ פּוֹסְלִין אֶלָּא בְּשִׁנּוּי מַרְאֶה כְּמוֹ שֶׁבֵּאַרְנוּ:","וּפְעָמִים שֶׁאֵלּוּ מַעֲלִין אֶת הַמִּקְוֶה. כֵּיצַד. מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה וְנָפַל לְתוֹכוֹ סְאָה מֵאֶחָד מֵאֵלּוּ וְחָזַר וְלָקַח סְאָה מִמֶּנָּה הֲרֵי הָאַרְבָּעִים שֶׁנִּשְׁאֲרוּ מִקְוֶה כָּשֵׁר:","מִקְוֶה שֶׁהֵדִיחַ בּוֹ סַלֵּי זֵיתִים וַעֲנָבִים וְשִׁנּוּ אֶת מַרְאָיו כָּשֵׁר:","מֵי הַצֶּבַע פּוֹסְלִין אֶת הַמִּקְוֶה בִּשְׁלֹשָׁה לוֹגִין. וְאֵין פּוֹסְלִין אוֹתוֹ בְּשִׁנּוּי מַרְאָיו:","מִקְוֶה שֶׁנָּפַל יַיִן אוֹ מֹהַל אוֹ שְׁאָר מֵי פֵּרוֹת וְשִׁנּוּ אֶת מַרְאָיו וְנִפְסַל כֵּיצַד תַּקָּנָתוֹ. יַמְתִּין עַד שֶׁיֵּרְדוּ גְּשָׁמִים וְיַחְזְרוּ מַרְאָיו לְמַרְאֵה מַיִם. וְאִם הָיָה בַּמִּקְוֶה אַרְבָּעִים סְאָה מַיִם כְּשֵׁרִים מְמַלֵּא וְשׁוֹאֵב לְתוֹכָן עַד שֶׁיַּחְזְרוּ מַרְאָיו לְמַרְאֵה מַיִם. נָפַל לְתוֹכוֹ יַיִן אוֹ מֹהַל וְכַיּוֹצֵא בָּהּ וְנִשְׁתַּנָּה מַרְאֵה מִקְצָתוֹ. אִם אֵין בָּהּ מַרְאֵה מַיִם שֶׁלֹּא נִשְׁתַּנָּה כְּדֵי אַרְבָּעִים סְאָה הֲרֵי זֶה לֹא יִטְבּל בּוֹ. וְהַטּוֹבֵל בְּמָקוֹם שֶׁנִּשְׁתַּנָּה לֹא עָלְתָה לוֹ טְבִילָה. אֲפִלּוּ חָבִית שֶׁל יַיִן שֶׁנִּשְׁבְּרָה בַּיָּם הַגָּדוֹל וּמַרְאֵה אוֹתוֹ מָקוֹם כְּמַרְאֶה שֶׁל יַיִן הַטּוֹבֵל בְּאוֹתוֹ מָקוֹם לֹא עָלְתָה לוֹ טְבִילָה:","שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין שֶׁנָּפַל לְתוֹכָן אֲפִלּוּ מִשְׁקַל דִּינָר יַיִן וְשִׁנָּה מַרְאֵיהֶן וַהֲרֵי מַרְאֵה הַכּל מַרְאֵה יַיִן וְנָפְלוּ לַמִּקְוֶה לֹא פְּסָלוּהוּ אֶלָּא אִם שִׁנּוּ אֶת מַרְאָיו:","שְׁלֹשָׁה לוֹגִין חָסֵר דִּינָר מַיִם שְׁאוּבִין שֶׁנָּפַל לְתוֹכָן דִּינַר חָלָב אוֹ מֵי פֵּרוֹת וַהֲרֵי מַרְאֵה הַכּל מַיִם וְנָפְלוּ לַמִּקְוֶה לֹא פְּסָלוּהוּ עַד שֶׁיִּפְּלוּ שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין שֶׁאֵין בָּהֶן תַּעֲרֹבֶת מַשְׁקֶה אַחֵר וְלֹא מֵי פֵּרוֹת:","מִקְוֶה שֶׁנִּשְׁתַּנָּה מַרְאֵה מֵימָיו מֵחֲמַת עַצְמוֹ וְלֹא נָפַל לוֹ דָּבָר הֲרֵי זֶה כָּשֵׁר. לֹא אָמְרוּ אֶלָּא שֶׁנִּשְׁתַּנָּה מֵחֲמַת מַשְׁקֶה אַחֵר:"],"Mishneh Torah, Inheritances 8":["כְּשֶׁמּוֹרִידִין קָרוֹב לְנִכְסֵי הַשָּׁבוּי אוֹ בּוֹרֵחַ אוֹ לְנִכְסֵי הַיּוֹצֵא לְדַעַת שֶׁשָּׁמְעוּ בּוֹ שֶׁמֵּת. לֹא יוֹרִידוּ קָטָן שֶׁמָּא יַפְסִיד הַנְּכָסִים. וְאֵין מוֹרִידִין קָרוֹב לְנִכְסֵי קָטָן שֶׁמָּא יִטְעֹן וְיֹאמַר זֶה חֶלְקִי הַמַּגִּיעַ לִי בִּירֻשָּׁתִי. וַאֲפִלּוּ קָרוֹב מֵחֲמַת קָרוֹב אֵין מוֹרִידִין. כֵּיצַד. הָיוּ שְׁנֵי אַחִים אֶחָד גָּדוֹל וְאֶחָד קָטָן וְנִשְׁבָּה הַקָּטָן אוֹ בָּרַח. אֵין מוֹרִידִין הַגָּדוֹל לְתוֹךְ שָׂדֵהוּ מִפְּנֵי שֶׁהַקָּטָן אֵינוֹ יָכוֹל לִמְחוֹת. וְשֶׁמָּא יַחֲזִיק זֶה הָאָח וּלְאַחַר שָׁנִים יֹאמַר זֶה חֶלְקִי שֶׁהִגִּיעַ לִי בִּירֻשָּׁתִי וּמֵחֲמַת יְרוּשָׁה בָּאתִי. וַאֲפִלּוּ בֶּן אָחִיו שֶׁל זֶה הַקָּטָן הַנִּשְׁבָּה אֵין מוֹרִידִין אוֹתוֹ לִנְכָסָיו שֶׁמָּא יֹאמַר שֶׁמֵּחֲמַת אָבִי יָרַשְׁתִּי חֵלֶק זֶה:","לְעוֹלָם אֵין מוֹרִידִין קָרוֹב לְנִכְסֵי קָטָן אֲפִלּוּ קָרוֹב מֵחֲמַת אֲחֵי הַאֵם שֶׁאֵינָן רְאוּיִין לִירַשׁ. הַרְחָקָה יְתֵרָה הִיא זוֹ וַאֲפִלּוּ יֵשׁ בֵּינֵיהֶן שְׁטַר חֲלוּקָה בֵּין בְּבָתִּים בֵּין בְּשָׂדוֹת לֹא יֵרֵד. וַאֲפִלּוּ אָמַר כִּתְבוּ עָלַי שְׁטַר אֲרִיסוּת לֹא יֵרֵד שֶׁמָּא יֹאבְדוּ הַשְּׁטָרוֹת וְיַאַרְכוּ הַיָּמִים וְיִטְעֹן וְיֹאמַר שֶׁזֶּה חֵלֶק יְרֻשָּׁה בָּא לוֹ (מֵחֲמָתוֹ אוֹ) מֵחֲמַת מוֹרִישָׁיו. מַעֲשֶׂה בְּאִשָּׁה אַחַת שֶׁהָיוּ לָהּ שָׁלֹשׁ בָּנוֹת וְנִשְׁבֵּית הַזְּקֵנָה הִיא וּבַת אַחַת וּמֵתָה בַּת שְׁנִיָּה וְהִנִּיחָה בֵּן קָטָן. וְאָמְרוּ חֲכָמִים אֵין מוֹרִידִין זוֹ הַבַּת הַנִּשְׁאָרָה לַנְּכָסִים שֶׁמָּא מֵתָה הַזְּקֵנָה וְנִמְצְאוּ שְׁלִישׁ נְכָסִים אֵלּוּ לַקָּטָן וְאֵין מוֹרִידִין קָרוֹב לְנִכְסֵי קָטָן. וְכֵן אֵין מוֹרִידִין לְזֶה הַקָּטָן בַּנְּכָסִים שֶׁמָּא עֲדַיִן הַזְּקֵנָה בַּחַיִּים וְאֵין מוֹרִידִין קָטָן לְנִכְסֵי שָׁבוּי. אֶלָּא כֵּיצַד עוֹשִׂין. מִתּוֹךְ שֶׁצָּרִיךְ לְהַעֲמִיד אַפּוֹטְרוֹפּוֹס לַחֲצִי שֶׁל קָטָן מַעֲמִידִין אַפּוֹטְרוֹפּוֹס עַל כָּל נִכְסֵי הַזְּקֵנָה. אַחַר זְמַן שָׁמְעוּ שֶׁמֵּתָה הַזְּקֵנָה אָמְרוּ חֲכָמִים תֵּרֵד הַבַּת הַנִּשְׁאָרָה לִשְׁלִישׁ הַנְּכָסִים שֶׁהוּא חֵלֶק יְרֻשָּׁתָהּ וְיֵרֵד הַקָּטָן לִשְׁלִישׁ שֶׁהוּא חֶלְקוֹ מִנִּכְסֵי הַזְּקֵנָה. וְהַשְּׁלִישׁ שֶׁל בַּת הַשְּׁבוּיָה מַעֲמִידִין לוֹ אַפּוֹטְרוֹפּוֹס מִפְּנֵי חֵלֶק הַקָּטָן שֶׁמָּא מֵתָה גַּם הַבַּת הַשְּׁבוּיָה וְיֵשׁ לְזֶה הַקָּטָן חֲצִי הַשְּׁלִישׁ שֶׁלָּהּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Kings and Wars 8":["חֲלוּצֵי צָבָא כְּשֶׁיִּכָּנְסוּ בִּגְבוּל הָעַכּוּ\"ם וְיִכְבְּשׁוּם וְיִשְׁבּוּ מֵהֶן. מֻתָּר לָהֶן לֶאֱכל נְבֵלוֹת וּטְרֵפוֹת וּבְשַׂר חֲזִיר וְכַיּוֹצֵא בּוֹ אִם יִרְעַב וְלֹא מָצָא מַה יֹּאכַל אֶלָּא מַאֲכָלוֹת אֵלּוּ הָאֲסוּרִים. וְכֵן שׁוֹתֶה יֵין נֶסֶךְ. מִפִּי הַשְּׁמוּעָה לָמְדוּ וּבָתִּים מְלֵאִים כָּל טוּב עָרְפֵּי חֲזִירִים וְכַיּוֹצֵא בָּהֶן:","וְכֵן בּוֹעֵל אִשָּׁה בְּגֵיוּתָהּ אִם תְּקָפוֹ יִצְרוֹ. אֲבָל לֹא יִבְעָלֶנָּה וְיֵלֵךְ לוֹ. אֶלָּא מַכְנִיסָהּ לְתוֹךְ בֵּיתוֹ. שֶׁנֶּאֱמַר (דברים כא, יא) \"וְרָאִיתָ בַּשִּׁבְיָה אֵשֶׁת יְפַת תֹּאַר\". וְאָסוּר לִבְעל אוֹתָהּ בִּיאָה שְׁנִיָּה עַד שֶׁיִּשָּׂאֶנָּה:","אֵין אֵשֶׁת יְפַת תֹּאַר מֻתֶּרֶת אֶלָּא בִּשְׁעַת הַשִּׁבְיָה. שֶׁנֶּאֱמַר (דברים כא, יא) \"וְרָאִיתָ בַּשִּׁבְיָה\". בֵּין בְּתוּלָה בֵּין בְּעוּלָה בֵּין אֵשֶׁת אִישׁ. שֶׁאֵין אִישׁוּת לְעַכּוּ\"ם. וְחָשַׁקְתָּ אַף עַל פִּי שֶׁאֵינָהּ יָפָה. בָהּ וְלֹא בַּחֲבֶרְתָּהּ שֶׁלֹּא יִבְעל שְׁתַּיִם. וְלָקַחְתָּ לְךָ לְאִשָּׁה שֶׁלֹּא יִקַּח שְׁתַּיִם וְיִבְעל אַחַת וְיַנִּיחַ אַחַת לְאָבִיו אוֹ לְאָחִיו. וּמִנַּיִן שֶׁלֹּא יִלְחָצֶנָּה בַּמִּלְחָמָה. שֶׁנֶּאֱמַר (דברים כא, יב) \"וַהֲבֵאתָהּ אֶל תּוֹךְ בֵּיתֶךָ\". יַכְנִיסָהּ לְמָקוֹם וְאַחַר כָּךְ יִבְעל:","הַכֹּהֵן מֻתָּר בִּיפַת תֹּאַר בְּבִיאָה רִאשׁוֹנָה. שֶׁלֹּא דִּבְּרָה תּוֹרָה אֶלָּא כְּנֶגֶד הַיֵּצֶר. אֲבָל אֵינוֹ יָכוֹל לִשָּׂאֶנָּה אַחַר כָּךְ מִפְּנֵי שֶׁהִיא גִּיֹּרֶת:","וְכֵיצַד דִּין יִשְׂרָאֵל בִּיפַת תֹּאַר. אַחֲרֵי שֶׁיִּבְעָלֶנָּה בִּיאָה רִאשׁוֹנָה וְהִיא בְּגֵיוּתָהּ אִם קִבְּלָה עָלֶיהָ לְהִכָּנֵס תַּחַת כַּנְפֵי הַשְּׁכִינָה מַטְבִּילָהּ לְשֵׁם גֵּרוּת מִיָּד. וְאִם לֹא קִבְּלָה תֵּשֵׁב בְּבֵיתוֹ שְׁלֹשִׁים יוֹם. שֶׁנֶּאֱמַר (דברים כא, יג) \"וּבָכְתָה אֶת אָבִיהָ וְאֶת אִמָּהּ יֶרַח יָמִים\". וְכֵן בּוֹכָה עַל דָּתָהּ וְאֵינוֹ מוֹנְעָהּ. וּמְגַדֶּלֶת אֶת צִפָּרְנֶיהָ. וּמְגַלַּחַת אֶת רֹאשָׁהּ כְּדֵי שֶׁתִּתְגַּנֶּה בְּעֵינָיו. וְתִהְיֶה עִמּוֹ בַּבַּיִת. נִכְנָס וְרוֹאֶה אוֹתָהּ. יוֹצֵא וְרוֹאֶה אוֹתָהּ. כְּדֵי שֶׁיָּקוּץ בָּהּ. וּמְגַלְגֵּל עִמָּהּ כְּדֵי שֶׁתְּקַבֵּל. אִם קִבְּלָה וְרָצָה בָּהּ. הֲרֵי זוֹ מִתְגַיֶּרֶת וְטוֹבֶלֶת כְּכָל הַגֵּרִים:","וּצְרִיכָה לְהַמְתִּין שְׁלֹשָׁה חֳדָשִׁים. חֹדֶשׁ שֶׁל בְּכִיָּה וּשְׁנֵי חֳדָשִׁים אַחֲרָיו. וְנוֹשְׂאָהּ בִּכְתֻבָּה וְקִדּוּשִׁין. אִם לֹא חָפֵץ בָּהּ מְשַׁלְּחָהּ לְנַפְשָׁהּ. וְאִם מְכָרָהּ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כא, יד) \"וּמָכֹר לֹא תִמְכְּרֶנָּה בַּכָּסֶף\". [וְאִם מְכָרָהּ] אֵינָהּ מְכוּרָה וּמַחֲזִיר הַדָּמִים. וְכֵן אִם כְּבָשָׁהּ אַחַר שֶׁנִּבְעֲלָה לְשֵׁם שִׁפְחָה מִשֶּׁיִּשְׁתַּמֵּשׁ בָּהּ עוֹבֵר בְּלֹא תַּעֲשֶׂה. שֶׁנֶּאֱמַר (דברים כא, יד) \"לֹא תִתְעַמֵּר בָּהּ\" שֶׁלֹּא יִשְׁתַּמֵּשׁ בָּהּ:","לֹא רָצְתָה לְהִתְגַּיֵּר מְגַלְגְּלִין עִמָּהּ שְׁנֵים עָשָׂר חֹדֶשׁ. לֹא רָצְתָה מְקַבֶּלֶת שֶׁבַע מִצְוֹת שֶׁנִּצְטַוּוּ בְּנֵי נֹחַ וּמְשַׁלְּחָהּ לְנַפְשָׁהּ. וַהֲרֵי הִיא כְּכָל הַגֵּרִים הַתּוֹשָׁבִים. וְאֵינוֹ נוֹשְׂאָהּ שֶׁאָסוּר לִשָּׂא אִשָּׁה שֶׁלֹּא נִתְגַּיְּרָה:","נִתְעַבְּרָה מִבִּיאָה רִאשׁוֹנָה הֲרֵי הַוָּלָד גֵּר. וְאֵינוֹ בְּנוֹ לְדָבָר מִן הַדְּבָרִים מִפְּנֵי שֶׁהוּא מִן הָעַכּוּ\"ם. אֶלָּא בֵּית דִּין מַטְבִּילִין אוֹתוֹ עַל דַּעְתָּם. וְתָמָר מִבִּיאָה רִאשׁוֹנָה שֶׁל יְפַת תֹּאַר הָיְתָה. אֲבָל אַבְשָׁלוֹם נוֹלַד מֵאַחַר הַנִּשּׂוּאִין. נִמְצֵאת תָּמָר אֲחוֹת אַבְשָׁלוֹם מֵאִמּוֹ וּמֻתֶּרֶת לְהִנָּשֵׂא לְאַמְנוֹן. וְכֵן הוּא אוֹמֵר (שמואל ב יג, יג) \"דַּבֶּר נָא אֶל הַמֶּלֶךְ כִּי לֹא יִמְנָעֵנִי מִמֶּךָּ\":","יְפַת תֹּאַר שֶׁלֹּא רָצְתָה לְהָנִיחַ עֲבוֹדָה זָרָה אַחַר הַשְּׁנֵים עָשָׂר חֹדֶשׁ. הוֹרְגִין אוֹתָהּ. וְכֵן עִיר שֶׁהִשְׁלִימָה אֵין כּוֹרְתִין לָהֶן בְּרִית עַד שֶׁיִּכְפְּרוּ בַּעֲבוֹדָה זָרָה וִיאַבְּדוּ אֶת כָּל מְקוֹמוֹתֶיהָ וִיקַבְּלוּ שְׁאָר הַמִּצְוֹת שֶׁנִּצְטַוּוּ בְּנֵי נֹחַ. שֶׁכָּל עַכּוּ\"ם שֶׁלֹּא קִבֵּל מִצְוֹת שֶׁנִּצְטַוּוּ בְּנֵי נֹחַ הוֹרְגִין אוֹתוֹ אִם יֶשְׁנוֹ תַּחַת יָדֵינוּ:","משֶׁה רַבֵּנוּ לֹא הִנְחִיל הַתּוֹרָה וְהַמִּצְוֹת אֶלָּא לְיִשְׂרָאֵל. שֶׁנֶּאֱמַר (דברים לג, ד) \"מוֹרָשָׁה קְהִלַּת יַעֲקֹב\". וּלְכָל הָרוֹצֶה לְהִתְגַּיֵּר מִשְּׁאָר הָאֻמּוֹת. שֶׁנֶּאֱמַר (במדבר טו, טו) \"כָּכֶם כַּגֵּר\". אֲבָל מִי שֶׁלֹּא רָצָה אֵין כּוֹפִין אוֹתוֹ לְקַבֵּל תּוֹרָה וּמִצְוֹת. וְכֵן צִוָּה משֶׁה רַבֵּנוּ מִפִּי הַגְּבוּרָה לָכֹף אֶת כָּל בָּאֵי הָעוֹלָם לְקַבֵּל מִצְוֹת שֶׁנִּצְטַוּוּ בְּנֵי נֹחַ. וְכָל מִי שֶׁלֹּא יְקַבֵּל יֵהָרֵג. וְהַמְקַבֵּל אוֹתָם הוּא הַנִּקְרָא גֵּר תּוֹשָׁב בְּכָל מָקוֹם. וְצָרִיךְ לְקַבֵּל עָלָיו בִּפְנֵי שְׁלֹשָׁה חֲבֵרִים. וְכָל הַמְקַבֵּל עָלָיו לָמוּל וְעָבְרוּ עָלָיו שְׁנֵים עָשָׂר חֹדֶשׁ וְלֹא מָל הֲרֵי זֶה כְּמִן הָאֻמּוֹת:","כָּל הַמְקַבֵּל שֶׁבַע מִצְוֹת וְנִזְהָר לַעֲשׂוֹתָן הֲרֵי זֶה מֵחֲסִידֵי אֻמּוֹת הָעוֹלָם. וְיֵשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא. וְהוּא שֶׁיְּקַבֵּל אוֹתָן וְיַעֲשֶׂה אוֹתָן מִפְּנֵי שֶׁצִּוָּה בָּהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה וְהוֹדִיעָנוּ עַל יְדֵי משֶׁה רַבֵּנוּ שֶׁבְּנֵי נֹחַ מִקֹּדֶם נִצְטַוּוּ בָּהֶן. אֲבָל אִם עֲשָׂאָן מִפְּנֵי הֶכְרֵעַ הַדַּעַת אֵין זֶה גֵּר תּוֹשָׁב וְאֵינוֹ מֵחֲסִידֵי אֻמּוֹת הָעוֹלָם וְלֹא מֵחַכְמֵיהֶם:"],"Mishneh Torah, Levirate Marriage and Release 2":["מִדִּבְרֵי סוֹפְרִים שֶׁלֹּא יָבֹא הַיָּבָם עַל יְבִמְתּוֹ עַד שֶׁיְּקַדֵּשׁ אוֹתָהּ בִּפְנֵי שְׁנֵי עֵדִים בִּפְרוּטָה אוֹ בִּשְׁוֵה פְּרוּטָה וְזֶהוּ הַנִּקְרָא מַאֲמָר. וְאֵין הַמַּאֲמָר קוֹנֶה בַּיְבָמָה קִנְיָן גָּמוּר כְּמוֹ הַבִּיאָה. וְהָעוֹשֶׂה מַאֲמָר בִּיבִמְתּוֹ שֶׁלֹּא מִדַּעְתָּהּ לֹא עָשָׂה כְּלוּם שֶׁאֵין הָאִשָּׁה מִתְקַדֶּשֶׁת אֶלָּא לִרְצוֹנָהּ. וּקְטַנָּה מִן הָאֵרוּסִין אֵין עוֹשִׂין בָּהּ מַאֲמָר אֶלָּא מִדַּעַת אָבִיהָ:","וּכְשֵׁם שֶׁהוּא מְקַדֵּשׁ אֶת יְבִמְתּוֹ כָּךְ הוּא מְבָרֵךְ בִּרְכַּת נִשּׂוּאִין בַּעֲשָׂרָה וְכוֹתֵב כְּתֻבָּה כְּדִין כָּל נוֹשֵׂא אִשָּׁה. הַבָּא עַל יְבִמְתּוֹ וְלֹא עָשָׂה בָּהּ מַאֲמָר קָנָה קִנְיָן גָּמוּר וְאֵינוֹ צָרִיךְ לַחֲזֹר וּלְקַדֵּשׁ אַחַר הַבְּעִילָה. וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְכוֹתֵב לָהּ כְּתֻבָּה:","הַבָּא עַל יְבִמְתּוֹ בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד בֵּין בְּאֹנֶס בֵּין בְּרָצוֹן. בֵּין שֶׁהָיָה הוּא מֵזִיד וְהִיא שׁוֹגֶגֶת אוֹ אֲנוּסָה. בֵּין שֶׁהָיְתָה הִיא מְזִידָה וְהוּא שׁוֹגֵג אוֹ אָנוּס. בֵּין שֶׁהָיְתָה יְשֵׁנָה בֵּין שֶׁהָיְתָה עֵרָה (בֵּין שֶׁבָּא עָלֶיהָ כְּדַרְכָּהּ בֵּין שֶׁלֹּא כְּדַרְכָּהּ). אֶחָד הַמְעָרֶה וְאֶחָד הַגּוֹמֵר קָנָה:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁנִּתְכַּוֵּן לִבְעל אֲבָל (אִם נָפַל מִן הַגַּג וְנִתְקַע בָּהּ אוֹ) שֶׁבָּא עָלֶיהָ שִׁכּוֹר שֶׁאֵינוֹ מַכִּיר כְּלוּם אוֹ יָשֵׁן לֹא קָנָה. נִתְכַּוֵּן לְדָבָר אַחֵר וְהֵטִיחַ בִּיבִמְתּוֹ לֹא קָנָה. לְהָטִיחַ בִּבְהֵמָה וְהֵטִיחַ בִּיבִמְתּוֹ קָנָה שֶׁהֲרֵי נִתְכַּוִּן לְשׁוּם בְּעִילָה מִכָּל מָקוֹם:","יְבָמָה שֶׁנִּתְיַבְּמָה וְאָמְרָה בְּתוֹךְ שְׁלֹשִׁים יוֹם לֹא נִבְעַלְתִּי וְאַף עַל פִּי שֶׁהוּא אוֹמֵר בָּעַלְתִּי וְגֵרְשָׁהּ כּוֹפִין אוֹתוֹ שֶׁיַּחֲלֹץ הוֹאִיל וְקִדֵּם וְגֵרְשָׁהּ בְּגֵט. וְאִם עֲדַיִן לֹא גֵּרֵשׁ כּוֹפִין אוֹתוֹ שֶׁיִּבְעל אוֹ יַחֲלֹץ וְיוֹצִיא בְּגֵט. גֵּרְשָׁהּ לְאַחַר שְׁלֹשִׁים יוֹם וְהִיא אוֹמֶרֶת לֹא נִבְעַלְתִּי מְבַקְּשִׁים מִמֶּנּוּ שֶׁיַּחֲלֹץ לָהּ. וְאִם הָיָה מוֹדֶה שֶׁלֹּא בָּעַל כּוֹפִין אוֹתוֹ לַחֲלֹץ. הִיא אוֹמֶרֶת נִבְעַלְתִּי וְהוּא אוֹמֵר לֹא בָּעַלְתִּי אֵינָהּ צְרִיכָה חֲלִיצָה שֶׁאֵין זֶה נֶאֱמָן לְאָסְרָהּ עַל כָּל אָדָם אַחַר שֶׁכְּנָסָהּ:","מִי שֶׁמֵּת וְהִנִּיחַ אַחִים רַבִּים מִצְוָה עַל הַגָּדוֹל לְיַבֵּם אוֹ לַחֲלֹץ שֶׁנֶּאֱמַר (דברים כה ו) ״וְהָיָה הַבְּכוֹר אֲשֶׁר תֵּלֵד״‎‎. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בִּבְכוֹר שֶׁבָּאַחִין כְּלוֹמַר גְּדוֹל הָאַחִין יָקוּם עַל שֵׁם אָחִיו הַמֵּת. וְזֶה שֶׁנֶּאֱמַר אֲשֶׁר תֵּלֵד מַשְׁמָעוֹ אֲשֶׁר יָלְדָה הָאֵם וְאֵין מַשְׁמָעוֹ אֲשֶׁר תֵּלֵד הַיְבָמָה:","לֹא רָצָה הַגָּדוֹל לְיַבֵּם מְחַזְּרִין עַל כָּל הָאַחִין. לֹא רָצוּ חוֹזְרִין אֵצֶל הַגָּדוֹל וְאוֹמְרִין עָלֶיךָ מִצְוָה אוֹ חֲלֹץ אוֹ יַבֵּם. וְאֵין כּוֹפִין אֶת הַיָּבָם לְיַבֵּם אֲבָל כּוֹפִין אוֹתוֹ לַחֲלֹץ:","אָמַר הַגָּדוֹל הַמְתִּינוּ לִי עַד שֶׁיַּגְדִּיל הַקָּטָן אוֹ עַד שֶׁיָּבוֹא הַהוֹלֵךְ אוֹ עַד שֶׁיַּבְרִיא הַחֵרֵשׁ וְנִמָּלֵךְ בּוֹ וְאִם לֹא יִרְצֶה אֲנִי אֲיַבֵּם אוֹ אֲנִי אֶחְלֹץ אֵין שׁוֹמְעִין לוֹ. אֶלָּא אוֹמְרִין לוֹ עָלֶיךָ מִצְוָה אוֹ יַבֵּם אוֹ חֲלֹץ:","וְכֵן אִם הָיָה הַגָּדוֹל בִּמְדִינָה אַחֶרֶת אֵין אָחִיו הַקָּטָן יָכוֹל לוֹמַר עַל אָחִי הַגָּדוֹל הִיא הַמִּצְוָה הַמְתִּינוּ לוֹ עַד שֶׁיָּבוֹא אֶלָּא אוֹמְרִין לְזֶה שֶׁהוּא כָּאן יַבֵּם אוֹ חֲלֹץ:","יְבָמָה הָרְאוּיָה לְיִבּוּם שֶׁלֹּא רָצְתָה לְהִתְיַבֵּם דִּינָהּ כְּדִין מוֹרֶדֶת עַל בַּעְלָהּ וְכוֹפִין אֶת יְבָמָהּ לַחֲלֹץ לָהּ וְתֵצֵא בְּלֹא כְּתֻבָּה. וְאִם הִנִּיחַ אָחִיו נָשִׁים רַבּוֹת כָּל מִי שֶׁתְּבָעָהּ הַיָּבָם מֵהֶן לְיִבּוּם וְלֹא רָצְתָה הִיא הַמּוֹרֶדֶת וְחוֹלֵץ לָהּ וְתֵצֵא בְּלֹא כְּתֻבָּה. וּשְׁאָר צָרוֹתֶיהָ שֶׁלֹּא נִתְבְּעוּ נוֹטְלוֹת כְּתֻבָּתָן כִּשְׁאָר הָאַלְמָנוֹת:","הָיוּ הַיְבָמִין רַבִּים וְתָבַע אוֹתָהּ הַגָּדוֹל לְיִבּוּם וְהִיא אֵינָהּ רוֹצָה בּוֹ וְרוֹצָה בְּאָחִיו אֵין שׁוֹמְעִין לָהּ, שֶׁמִּצְוָה בַּגָּדוֹל לְיַבֵּם:","אָמַר הַגָּדוֹל אֵינִי רוֹצֶה לֹא לְיַבֵּם וְלֹא לַחֲלֹץ. הֲרֵי אַחַי לְפָנַיִךְ. וְתָבַע אוֹתָהּ אֶחָד מִן הָאַחִין לְיִבּוּם וְהִיא אֵינָהּ רוֹצָה בּוֹ וְרָצְתָה בְּאָח אַחֵר וְהוּא רוֹצֶה בָּהּ. אֵין זוֹ מוֹרֶדֶת מֵאַחַר שֶׁנִּסְתַּלֵּק הַגָּדוֹל שֶׁמִּצְוָה בּוֹ הֲרֵי כֻּלָּן שָׁוִין וְהוֹאִיל וְהִיא רוֹצָה בְּאֶחָד מֵהֶן וְהוּא רוֹצֶה בָּהּ הֲרֵי זֹאת לֹא מָרְדָה. וְלֹא עוֹד אֶלָּא אִם הָיָה אֶחָד מֵהֶן בִּמְדִינָה אַחֶרֶת וְאָמְרָה הֲרֵי אֲנִי מַמְתֶּנֶת אוֹתוֹ עַד שֶׁיָּבוֹא וִייַבֵּם אוֹתִי אֲבָל זֶה אֵינִי רוֹצָה בּוֹ אֵין זוֹ מוֹרֶדֶת. וְאוֹמְרִים לְזֶה שֶׁאֵינוֹ הַגָּדוֹל הַתּוֹבֵעַ אוֹתָהּ אִם תִּרְצֶה לַחֲלֹץ לָהּ וְלִתֵּן לָהּ כְּתֻבָּה חֲלֹץ. וְאִם לָאו הֲרֵי רָצְתָה שֶׁתֵּשֵׁב עַד שֶׁיָּבוֹא אָחִיךָ הוֹאִיל וְאֵין לְךָ דִּין קְדִימָה עָלָיו:","בָּא זֶה שֶׁתָּלְתָה בּוֹ וְלֹא רָצָה בָּהּ. חוֹזְרִין אֵצֶל זֶה שֶׁתָּבַע אוֹתָהּ לְיַבֵּם וְהִיא אֵינָהּ רוֹצָה בּוֹ. וְאוֹמְרִין לָהּ אֵין כָּאן מִי שֶׁרָצָה לְיַבֵּם אֶלָּא זֶה וּמִצְוַת יִבּוּם קוֹדֶמֶת. אוֹ תִּתְיַבֵּם לוֹ אוֹ תֵּצֵא בְּלֹא כְּתֻבָּה כְּדִין כָּל מוֹרֶדֶת:","כָּל יְבָמָה שֶׁאָמַרְנוּ שֶׁדִּינָהּ שֶׁתַּחֲלֹץ וְלֹא תִּתְיַבֵּם הֲרֵי זוֹ נוֹטֶלֶת כְּתֻבָּתָהּ אִם יֵשׁ לָהּ כְּתֻבָּה כִּשְׁאָר כָּל הָאַלְמָנוֹת. וְכֵן אִם הָיָה יְבָמָהּ מֻכֶּה שְׁחִין אוֹ שֶׁיֵּשׁ בּוֹ שְׁאָר מוּמֵי אֲנָשִׁים חוֹלֵץ לָהּ וְנוֹטֶלֶת כְּתֻבָּתָהּ. נוֹלְדוּ בָּהּ מוּמִין כְּשֶׁהִיא שׁוֹמֶרֶת יָבָם, נִסְתַּחֲפָה שָׂדֵהוּ. אִם לֹא רָצָה לְיַבֵּם יַחֲלֹץ וְיִתֵּן כְּתֻבָּה:","יְבָמָה שֶׁנָּדְרָה הֲנָיָה מִיבָמָהּ בְּחַיֵּי בַּעְלָהּ. אוֹ שֶׁנָּדְרָה הֲנָיָה מִכָּל הַיְּהוּדִים. כּוֹפִין אוֹתוֹ שֶׁיַּחֲלֹץ לָהּ וְתִטּל כְּתֻבָּתָהּ. וְאִם נָדְרָה לְאַחַר מִיתַת בַּעְלָהּ מְבַקְּשִׁים מִמֶּנּוּ שֶׁיַּחֲלֹץ לָהּ וְאִם לֹא רָצָה הֲרֵי זוֹ מוֹרֶדֶת. וְכֵן אִם נִתְכַּוְּנָה בְּנִדְרָהּ אֲפִלּוּ בְּחַיֵּי בַּעְלָהּ כְּדֵי שֶׁלֹּא יְיַבֵּם אוֹתָהּ אֵין כּוֹפִין אוֹתוֹ לַחֲלֹץ אֶלָּא אִם כֵּן מָרְדָה וְתֵצֵא בְּלֹא כְּתֻבָּה:","יְבָמָה שֶׁתְּבָעָהּ הַיָּבָם לַחֲלִיצָה וְהִיא אוֹמֶרֶת אֵינִי חוֹלֶצֶת וְלֹא נוֹטֶלֶת כְּתֻבָּה אֶלָּא אֵשֵׁב בְּבֵית בַּעְלִי וְכִשְׁאָר כָּל הָאַלְמָנוֹת אֵין שׁוֹמְעִין לָהּ. שֶׁהֲרֵי הִקְנוּ אוֹתָהּ לְזֶה מִן הַשָּׁמַיִם. רָצָה מְיַבֵּם רָצָה חוֹלֵץ וְנוֹתֵן כְּתֻבָּה. וְלֹא עוֹד אֶלָּא אֲפִלּוּ אָמְרָה אֲנִי נִזּוֹנֶת מִשֶּׁלִּי וְאֵשֵׁב עֲגוּנָה כָּל יְמֵי חַיַּי אֵין שׁוֹמְעִין לָהּ. שֶׁהֲרֵי הַיָּבָם אוֹמֵר לָהּ כָּל זְמַן שֶׁאַתְּ זְקוּקָה לִי אֵין נוֹתְנִין לִי אִשָּׁה אַחֶרֶת. וַאֲפִלּוּ הָיָה נָשׂוּי אֶפְשָׁר שֶׁיִּשָּׂא אִשָּׁה אַחֶרֶת אוֹ תִּהְיֶה לוֹ מְרִיבָה בְּתוֹךְ בֵּיתוֹ מִפְּנֵי הַיְבָמָה:","יְבָמָה שֶׁלֹּא הָיָה לָהּ עַל בַּעְלָהּ כְּתֻבָּה מִפְּנֵי שֶׁהָיְתָה אֲסוּרָה עָלָיו וַהֲרֵי הִיא מֻתֶּרֶת לַיָּבָם כְּמוֹ שֶׁיִּתְבָּאֵר. אִם רָצָה הַיָּבָם לְיַבֵּם מְיַבֵּם וְאֵין לָהּ עָלָיו כְּתֻבָּה כְּדֶרֶךְ שֶׁלֹּא הָיָה לָהּ עַל בַּעְלָהּ. וְדִינָהּ עִם יְבָמָהּ בַּתּוֹסֶפֶת כְּמוֹ שֶׁהָיְתָה עִם בַּעְלָהּ. אֲבָל אִם לֹא כָּתַב לָהּ בַּעְלָהּ כְּתֻבָּה אוֹ שֶׁמָּכְרָה לוֹ כְּתֻבָּתָהּ אוֹ מָחֲלָה אוֹתָהּ צָרִיךְ הַיָּבָם לִכְתֹּב לָהּ כְּתֻבָּה כִּשְׁאָר הָאַלְמָנוֹת:","הַיְבָמָה קֹדֶם שֶׁיָּבוֹא עָלֶיהָ יְבָמָהּ אוֹ קֹדֶם שֶׁיַּחֲלֹץ לָהּ הֲרֵי הִיא אֲסוּרָה לְהִנָּשֵׂא לְזָר שֶׁנֶּאֱמַר (דברים כה ה) ״לֹא תִהְיֶה אֵשֶׁת הַמֵּת הַחוּצָה לְאִישׁ זָר״‎‎. וְאִם נִשֵּׂאת לְאַחֵר וּבָעַל לוֹקֶה הוּא וְהִיא וּמוֹצִיאָהּ בְּגֵט. וַאֲפִלּוּ הָיוּ לוֹ כַּמָּה בָּנִים מִמֶּנָּה. וְנֶאֶסְרָה עָלָיו וְעַל יְבָמָהּ. וִיבָמָהּ חוֹלֵץ לָהּ וְאַחַר כָּךְ תִּהְיֶה מֻתֶּרֶת לַאֲחֵרִים:","נִתְקַדְּשָׁה לְאַחֵר לֹא נֶאֶסְרָה עַל יְבָמָהּ אֶלָּא נוֹתֵן לָהּ הַזָּר שֶׁקִּדְּשָׁהּ גֵּט וִיבָמָהּ מְיַבֵּם אוֹ חוֹלֵץ. וְאִם הָיָה יְבָמָהּ כֹּהֵן שֶׁאֵינוֹ יָכוֹל לִשָּׂא גְּרוּשָׁה תֵּצֵא מִן הַזָּר בְּגֵט כְּדֵי שֶׁלֹּא יְהֵא הַחוֹטֵא נִשְׂכָּר. וְיַחֲלֹץ לָהּ יְבָמָהּ:","חָזַר הַזָּר שֶׁגֵּרְשָׁהּ מִן הָאֵרוּסִין וּנְשָׂאָהּ אַחַר שֶׁחָלַץ לָהּ יְבָמָהּ אֵין מוֹצִיאִין אוֹתָהּ מִיָּדוֹ. אֲבָל אִם גֵּרְשָׁהּ מִן הַנִּשּׂוּאִין וְחָזַר וּנְשָׂאָהּ אַחַר שֶׁחָלְצָה מוֹצִיאִין אוֹתָהּ מִיָּדוֹ מִפְּנֵי שֶׁהִיא דּוֹמָה לְאֵשֶׁת אִישׁ שֶׁנִּשֵּׂאת וּבָא בַּעְלָהּ שֶׁהִיא אֲסוּרָה עַל זֶה וְעַל זֶה כְּמוֹ שֶׁבֵּאַרְנוּ. וְהַיְבָמָה שֶׁזִּנְּתָה וְהִיא זְקוּקָה לֹא נֶאֶסְרָה עַל יְבָמָהּ אֶלָּא רָצָה חוֹלֵץ רָצָה מְיַבֵּם:","כָּל יְבָמָה שֶׁהִיא סָפֵק מִדִּבְרֵיהֶם אִם יֵשׁ עָלֶיהָ זִקַּת יָבָם אוֹ אֵין עָלֶיהָ זִקַּת יָבָם. כְּגוֹן יְבָמָה שֶׁיָּלְדָה וָלָד שֶׁלֹּא כָּלוּ לוֹ חֳדָשָׁיו וּמֵת בְּתוֹךְ שְׁלֹשִׁים יוֹם שֶׁדִּינָהּ שֶׁתַּחֲלֹץ מִסָּפֵק מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ. אִם הָלְכָה וְנִתְקַדְּשָׁה לְאַחֵר קֹדֶם חֲלִיצָה חוֹלֵץ לָהּ יְבָמָהּ וְתֵשֵׁב עִם בַּעְלָהּ. וְאִם נִתְקַדְּשָׁה לְכֹהֵן שֶׁהוּא אָסוּר בַּחֲלוּצָה אֵינוֹ חוֹלֵץ לָהּ. שֶׁאֵין אוֹסְרִין עַל זֶה אִשְׁתּוֹ מִשּׁוּם סְפֵק דִּבְרֵיהֶן. גֵּרְשָׁהּ הַכֹּהֵן אוֹ מֵת הֲרֵי זוֹ חוֹלֶצֶת וְאַחַר כָּךְ מֻתֶּרֶת לַאֲחֵרִים לְכַתְּחִלָּה:"],"Mishneh Torah, Marriage 14":["עוֹנָּה הָאֲמוּרָה בַּתּוֹרָה. לְכָל אִישׁ וְאִישׁ כְּפִי כֹּחוֹ וּכְפִי מְלַאכְתּוֹ. כֵּיצַד. בְּנֵי אָדָם הַבְּרִיאִים וְהָרַכִּים וְהָעֲנֻגִּים שֶׁאֵין לָהֶם מְלָאכָה שֶׁמַּכְשֶׁלֶת כֹּחָן אֶלָּא אוֹכְלִין וְשׁוֹתִין וְיוֹשְׁבִין בְּבָתֵּיהֶן עוֹנָתָן בְּכָל לַיְלָה. הַפּוֹעֲלִין כְּגוֹן הַחַיָּטִין וְהָאוֹרְגִין וְהַבּוֹנִים וְכַיּוֹצֵא בָּהֶן. אִם הָיְתָה מְלַאכְתָּן בָּעִיר עוֹנָתָן פַּעֲמַיִם בְּשַׁבָּת. וְאִם הָיְתָה מְלַאכְתָּן בְּעִיר אַחֶרֶת עוֹנָתָן פַּעַם אַחַת בְּשַׁבָּת. הַחַמָּרִים פַּעַם אַחַת בְּשַׁבָּת. וְהַגַּמָּלִים אַחַת לִשְׁלֹשִׁים יוֹם. וְהַמַּלָּחִין אַחַת לְשִׁשָּׁה חֳדָשִׁים. תַּלְמִידֵי חֲכָמִים עוֹנָתָן פַּעַם אַחַת בְּשַׁבָּת מִפְּנֵי שֶׁתַּלְמוּד תּוֹרָה מַתִּישׁ כֹּחָן וְדֶרֶךְ תַּלְמִידֵי חֲכָמִים לְשַׁמֵּשׁ מִטָּתָן מִלֵּילֵי שַׁבָּת לְלֵילֵי שַׁבָּת:","יֵשׁ לְאִשָּׁה לְעַכֵּב עַל בַּעְלָהּ שֶׁלֹּא יֵצֵא לִסְחוֹרָה אֶלָּא לְמָקוֹם קָרוֹב שֶׁלֹּא יִמָּנַע מֵעוֹנָתָהּ וְלֹא יֵצֵא אֶלָּא בִּרְשׁוּתָהּ. וְכֵן יֵשׁ לָהּ לְמָנְעוֹ לָצֵאת מִמְּלָאכָה שֶׁעוֹנָתָהּ קְרוֹבָה לִמְלָאכָה שֶׁעוֹנָתָהּ רְחוֹקָה. כְּגוֹן חַמָּר שֶׁבִּקֵּשׁ לְהֵעָשׂוֹת גַּמָּל אוֹ גַּמָּל לְהֵעָשׂוֹת מַלָּח. וְתַלְמִידֵי חֲכָמִים יוֹצְאִין לְתַלְמוּד תּוֹרָה שֶׁלֹּא בִּרְשׁוּת נְשׁוֹתֵיהֶן שְׁתַּיִם וְשָׁלֹשׁ שָׁנִים. וְכֵן רַךְ וְעָנֹג שֶׁנַּעֲשָׂה תַּלְמִיד חָכָם אֵין אִשְׁתּוֹ יְכוֹלָה לְעַכֵּב:","נוֹשֵׂא אָדָם כַּמָּה נָשִׁים אֲפִלּוּ מֵאָה בֵּין בְּבַת אַחַת בֵּין בָּזוֹ אַחַר זוֹ וְאֵין אִשְׁתּוֹ יְכוֹלָה לְעַכֵּב. וְהוּא שֶׁיִּהְיֶה יָכוֹל לִתֵּן שְׁאֵר כְּסוּת וְעוֹנָה כָּרָאוּי לְכָל אַחַת וְאַחַת. וְאֵינוֹ יָכוֹל לָכוֹף אוֹתָן לִשְׁכֹּן בְּחָצֵר אַחַת. אֶלָּא כָּל אַחַת וְאַחַת לְעַצְמָהּ:","וְכַמָּה הִיא עוֹנָתָן. לְפִי מִנְיָן. כֵּיצַד. פּוֹעֵל שֶׁהָיוּ לוֹ שְׁתֵּי נָשִׁים יֵשׁ לָזוֹ עוֹנָה אַחַת בְּשַׁבָּת וְיֵשׁ לָזוֹ עוֹנָה אַחַת בְּשַׁבָּת. הָיוּ לוֹ אַרְבַּע נָשִׁים נִמְצָא עוֹנַת כָּל אַחַת מֵהֶן פַּעַם אַחַת בִּשְׁתֵּי שַׁבָּתוֹת. וְכֵן אִם הָיָה מַלָּח וְיֵשׁ לוֹ אַרְבַּע נָשִׁים תִּהְיֶה עוֹנַת כָּל אַחַת מֵהֶן פַּעַם אַחַת בִּשְׁתֵּי שָׁנִים. לְפִיכָךְ צִוּוּ חֲכָמִים שֶׁלֹּא יִשָּׂא אָדָם יוֹתֵר עַל אַרְבַּע נָשִׁים אַף עַל פִּי שֶׁיֵּשׁ לוֹ מָמוֹן הַרְבֵּה כְּדֵי שֶׁתַּגִּיעַ לָהֶן עוֹנָה פַּעַם אַחַת בְּחֹדֶשׁ:","הַמַּדִּיר אֶת אִשְׁתּוֹ שֶׁתֹּאמַר לַאֲחֵרִים מַה שֶּׁאָמַר לָהּ אוֹ מַה שֶּׁאָמְרָה לוֹ מִדִּבְרֵי שְׂחוֹק וְקַלּוּת רֹאשׁ שֶׁמְּדַבֵּר אָדָם עִם אִשְׁתּוֹ עַל עִסְקֵי תַּשְׁמִישׁ הֲרֵי זֶה יוֹצִיא וְיִתֵּן כְּתֻבָּה שֶׁאֵין זוֹ יְכוֹלָה לְהָעֵז פָּנֶיהָ וְלוֹמַר לַאֲחֵרִים דִּבְרֵי קָלוֹן. וְכֵן אִם הִדִּירָהּ שֶׁתִּהְיֶה פּוֹעֶלֶת בְּעֵת תַּשְׁמִישׁ שֶׁלֹּא תִּתְעַבֵּר. אוֹ שֶׁהִדִּירָהּ שֶׁתַּעֲשֶׂה מַעֲשֵׂה שׁוֹטִים וּדְבָרִים שֶׁאֵין בָּהֶן מַמָּשׁ אֶלָּא כִּשְׁטוּת. הֲרֵי זֶה יוֹצִיא וְיִתֵּן כְּתֻבָּה:","הַמַּדִּיר אֶת אִשְׁתּוֹ מִתַּשְׁמִישׁ הַמִּטָּה שַׁבָּת אַחַת מַמְתִּינִין לוֹ. יֶתֶר עַל כֵּן יוֹצִיא וְיִתֵּן כְּתֻבָּה אוֹ יָפֵר נִדְרוֹ. אֲפִלּוּ הָיָה מַלָּח שֶׁעוֹנָתוֹ לְשִׁשָּׁה חֳדָשִׁים. שֶׁכֵּיוָן שֶׁנָּדַר הֲרֵי צִעֲרָהּ וְנִתְיָאֲשָׁה. וְכֵיצַד מַדִּירָהּ. אִם אָמַר לָהּ תַּשְׁמִישִׁי אָסוּר עָלַיִךְ אוֹ שֶׁנִּשְׁבַּע שֶׁלֹּא יְשַׁמֵּשׁ מִטָּתוֹ לֹא נָדַר כְּלוּם. וְאִם נִשְׁבַּע נִשְׁבַּע לַשָּׁוְא מִפְּנֵי שֶׁהוּא מְשֻׁעְבָּד לָהּ. אָמַר לָהּ הֲנָאַת תַּשְׁמִישֵׁךְ אֲסוּרָה עָלַי הֲרֵי זֶה נֵדֶר וְאָסוּר לְשַׁמֵּשׁ שֶׁאֵין מַאֲכִילִין לָאָדָם דָּבָר הָאָסוּר לוֹ:","אָסוּר לָאָדָם לִמְנֹעַ אִשְׁתּוֹ מֵעוֹנָתָהּ וְאִם עָבַר וּמָנַע כְּדֵי לְצַעֲרָהּ עָבַר בְּלֹא תַּעֲשֶׂה שֶׁבַּתּוֹרָה שֶׁנֶּאֱמַר (שמות כא י) \"שְׁאֵרָהּ כְּסוּתָהּ וְעֹנָתָהּ לֹא יִגְרָע\". וְאִם חָלָה אוֹ תָּשַׁשׁ כֹּחוֹ וְאֵינוֹ יָכוֹל לִבְעל יַמְתִּין שִׁשָּׁה חֳדָשִׁים שֶׁמָּא יַבְרִיא שֶׁאֵין לְךָ עוֹנָה גְּדוֹלָה מִזּוֹ. וְאַחַר כָּךְ אוֹ יִטּל מִמֶּנָּה רְשׁוּת אוֹ יוֹצִיא וְיִתֵּן כְּתֻבָּה:","הָאִשָּׁה שֶׁמָּנְעָה בַּעְלָהּ מִתַּשְׁמִישׁ הַמִּטָּה הִיא הַנִּקְרֵאת מוֹרֶדֶת וְשׁוֹאֲלִין אוֹתָהּ מִפְּנֵי מָה מָרְדָה. אִם אָמְרָה מְאַסְתִּיהוּ וְאֵינִי יְכוֹלָה לְהִבָּעֵל לוֹ מִדַּעְתִּי כּוֹפִין אוֹתוֹ לִשְׁעָתוֹ לְגָרְשָׁהּ לְפִי שֶׁאֵינָהּ כִּשְׁבוּיָה שֶׁתִּבָּעֵל לְשָׂנוּא לָהּ וְתֵצֵא בְּלֹא כְּתֻבָּה כְּלָל וְתִטּל בְּלָאוֹתֶיהָ הַקַּיָּמִין בֵּין מִנְּכָסִים שֶׁהִכְנִיסָה לְבַעְלָהּ וְנִתְחַיֵּב בְּאַחְרָיוּתָן בֵּין מִנִּכְסֵי מְלוֹג שֶׁלֹּא נִתְחַיֵּב בְּאַחְרָיוּתָן. וְאֵינָהּ נוֹטֶלֶת בְּשֶׁל בַּעַל כְּלוּם וַאֲפִלּוּ מִנְעָל שֶׁבְּרַגְלֶיהָ וּמִטְפַּחַת שֶׁבְּרֹאשָׁהּ שֶׁלְּקָחָן לָהּ פּוֹשֶׁטֶת וְנוֹתֶנֶת לוֹ וְכָל מַה שֶּׁנָּתַן לָהּ מַתָּנָה מְחַזֶּרֶת אוֹתוֹ. שֶׁלֹּא נָתַן לָהּ עַל מְנָת שֶׁתִּטּל וְתֵצֵא:","וְאִם מָרְדָה מִתַּחַת בַּעְלָהּ כְּדֵי לְצַעֲרוֹ וְאָמְרָה הֲרֵינִי מְצַעֶרֶת אוֹתוֹ בְּכָךְ מִפְּנֵי שֶׁעָשָׂה לִי כָּךְ וְכָךְ אוֹ מִפְּנֵי שֶׁקִּלְּלַנִי אוֹ מִפְּנֵי שֶׁעָשָׂה עִמִּי מְרִיבָה וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. שׁוֹלְחִים לָהּ מִבֵּית דִּין וְאוֹמְרִין לָהּ הֱוֵי יוֹדַעַת שֶׁאִם אַתְּ עוֹמֶדֶת בְּמִרְדֵּךְ אֲפִלּוּ כְּתֻבָּתֵךְ מֵאָה מָנֶה הִפְסַדְתְּ אוֹתָהּ. וְאַחַר כָּךְ מַכְרִיזִין עָלֶיהָ בְּבָתֵּי כְּנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת בְּכָל יוֹם אַרְבַּע שַׁבָּתוֹת זוֹ אַחַר זוֹ וְאוֹמְרִים פְּלוֹנִית מָרְדָה עַל בַּעְלָהּ:","וְאַחַר הַהַכְרָזָה שׁוֹלְחִין לָהּ בֵּית דִּין פַּעַם שְׁנִיָּה וְאוֹמְרִים לָהּ אִם אַתְּ עוֹמֶדֶת בְּמִרְדֵּךְ הִפְסַדְתְּ כְּתֻבָּתֵךְ. אִם עָמְדָה בְּמִרְדָּהּ וְלֹא חָזְרָה נִמְלָכִין בָּהּ וּתְאַבֵּד כְּתֻבָּתָהּ וְלֹא יִהְיֶה לָהּ כְּתֻבָּה כְּלָל. וְאֵין נוֹתְנִין לָהּ גֵּט עַד י\"ב חֹדֶשׁ וְאֵין לָהּ מְזוֹנוֹת כָּל י\"ב חֹדֶשׁ. וְאִם מֵתָה קֹדֶם הַגֵּט בַּעְלָהּ יוֹרְשָׁהּ:","כַּסֵּדֶר הַזֶּה עוֹשִׂין לָהּ אִם מָרְדָה כְּדֵי לְצַעֲרוֹ. וַאֲפִלּוּ הָיְתָה נִדָּה אוֹ חוֹלָה שֶׁאֵינָהּ רְאוּיָה לְתַשְׁמִישׁ וַאֲפִלּוּ הָיָה בַּעְלָהּ מַלָּח שֶׁעוֹנָתוֹ לְשִׁשָּׁה חֳדָשִׁים וַאֲפִלּוּ יֵשׁ לוֹ אִשָּׁה אַחֶרֶת:","וְכֵן אֲרוּסָה שֶׁהִגִּיעַ זְמַנָּה לְהִנָּשֵׂא וּמָרְדָה כְּדֵי לְצַעֲרוֹ וְלֹא נִשֵּׂאת הֲרֵי זוֹ מוֹרֶדֶת מִתַּשְׁמִישׁ. וְכֵן יְבָמָה שֶׁלֹּא רָצְתָה לְהִתְיַבֵּם כְּדֵי לְצַעֲרוֹ כַּסֵּדֶר הַזֶּה עוֹשִׂין לָהּ:","הַמּוֹרֶדֶת הַזֹּאת כְּשֶׁהִיא יוֹצֵאת אַחַר י\"ב חֹדֶשׁ בְּלֹא כְּתֻבָּה תַּחֲזִיר כָּל דָּבָר שֶׁהוּא שֶׁל בַּעַל. אֲבָל נְכָסִים שֶׁהִכְנִיסָה לוֹ וּבְלָאוֹתֵיהֶן קַיָּמִים אִם תָּפְסָה אֵין מוֹצִיאִים מִיָּדָהּ וְאִם תְּפָסָן הַבַּעַל אֵין מוֹצִיאִין מִיָּדוֹ. וְכֵן כָּל מַה שֶּׁאָבַד מִנְּכָסֶיהָ שֶׁקִּבֵּל הַבַּעַל אַחֲרָיוּתָן עָלָיו אֵינוֹ מְשַׁלֵּם לָהּ כְּלוּם. זֶה הוּא דִּין הַגְּמָרָא בְּמוֹרֶדֶת:","וְאָמְרוּ הַגְּאוֹנִים שֶׁיֵּשׁ לָהֶם בְּבָבֶל מִנְהָגוֹת אֲחֵרוֹת בְּמוֹרֶדֶת. וְלֹא פָּשְׁטוּ אוֹתָן הַמִּנְהָגוֹת בְּרֹב יִשְׂרָאֵל וְרַבִּים וּגְדוֹלִים חוֹלְקִין עֲלֵיהֶם בְּרֹב הַמְּקוֹמוֹת וּכְדִין הַגְּמָרָא רָאוּי לִתְפֹּס וְלָדוּן:","הַמּוֹרֵד עַל אִשְׁתּוֹ וְאָמַר הֲרֵינִי זָן וּמְפַרְנֵס אוֹתָהּ אֲבָל אֵינִי בָּא עָלֶיהָ מִפְּנֵי שֶׁשְּׂנֵאתִיהָ מוֹסִיפִין לָהּ עַל כְּתֻבָּתָהּ מִשְׁקַל שֵׁשׁ וּשְׁלֹשִׁים שְׂעוֹרוֹת שֶׁל כֶּסֶף בְּכָל שַׁבָּת וְשַׁבָּת. וְיֵשֵׁב וְלֹא יְשַׁמֵּשׁ כָּל זְמַן שֶׁתִּרְצֶה הִיא לֵישֵׁב. וְאַף עַל פִּי שֶׁכְּתֻבָּתָהּ הוֹלֶכֶת וְנוֹסֶפֶת הֲרֵי הוּא עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כא י) \"לֹא יִגְרָע\". שֶׁאִם שְׂנֵאָהּ יְשַׁלְּחָהּ אֲבָל לְעַנּוֹת אָסוּר. וְלָמָּה לֹא יִלְקֶה עַל לָאו זֶה מִפְּנֵי שֶׁאֵין בּוֹ מַעֲשֶׂה:","אִישׁ וְאִשְׁתּוֹ שֶׁבָּאוּ לְבֵית דִּין הוּא אוֹמֵר זוֹ מוֹרֶדֶת מִתַּשְׁמִישׁ וְהִיא אוֹמֶרֶת לֹא כִּי אֶלָּא כְּדֶרֶךְ כָּל הָאָרֶץ אֲנִי עִמּוֹ. וְכֵן אִם טָעֲנָה הִיא וְאָמְרָה שֶׁהוּא מוֹרֵד מִתַּשְׁמִישׁ וְהוּא אוֹמֵר לֹא כִּי אֶלָּא כְּדֶרֶךְ כָּל הָאָרֶץ אֲנִי עִמָּהּ. מַחְרִימִין בַּתְּחִלָּה עַל מִי שֶׁהוּא מוֹרֵד וְלֹא יוֹדֶה בְּבֵית דִּין. וְאַחַר כָּךְ אִם לֹא הוֹדוּ אוֹמְרִין לָהֶם הִתְיַחֲדוּ בִּפְנֵי עֵדִים. נִתְיַחֲדוּ וַעֲדַיִן הֵם טוֹעֲנִין מְבַקְּשִׁין מִן הַנִּטְעָן וְעוֹשִׂין פְּשָׁרָה כְּפִי כֹּחַ הַדַּיָּן. אֲבָל לִבְעל בִּפְנֵי בְּנֵי אָדָם אִי אֶפְשָׁר לְפִי שֶׁאָסוּר לִבְעל בִּפְנֵי כָּל בְּרִיָּה:","הָאִשָּׁה שֶׁחָלְתָה חַיָּב לְרַפְּאוֹת אוֹתָהּ עַד שֶׁתַּבְרִיא. רָאָה שֶׁהַחלִי אָרֹךְ וְיַפְסִיד מָמוֹן הַרְבֵּה לִרְפוּאָה וְאָמַר לָהּ הֲרֵי כְּתֻבָּתֵךְ מֻנַּחַת אוֹ רַפְּאִי עַצְמֵךְ מִכְּתֻבָּתֵךְ אוֹ הֲרֵינִי מְגָרְשֵׁךְ וְנוֹתֵן כְּתֻבָּה וְהוֹלֵךְ שׁוֹמְעִין לוֹ. וְאֵין רָאוּי לַעֲשׂוֹת כֵּן מִפְּנֵי דֶּרֶךְ אֶרֶץ:","נִשְׁבֵּית חַיָּב לִפְדּוֹתָהּ. וְאִם הָיָה כֹּהֵן שֶׁכְּבָר נֶאֶסְרָה עָלָיו פּוֹדֶה אוֹתָהּ וּמַחֲזִירָהּ לְבֵית אָבִיהָ. אֲפִלּוּ הָיָה בְּעִיר אַחֶרֶת מְטַפֵּל לָהּ עַד שֶׁמַּחֲזִירָהּ לִמְדִינָתָהּ וּמְגָרְשָׁהּ וְנוֹתֵן לָהּ כָּל כְּתֻבָּתָהּ. הָיָה בַּעְלָהּ יִשְׂרָאֵל שֶׁהַשְּׁבוּיָה מֻתֶּרֶת לוֹ מַחֲזִירָהּ לוֹ לְאִשָּׁה כְּמוֹ שֶׁהָיְתָה וְאִם רָצָה אַחַר כָּךְ מְגָרְשָׁהּ וְנוֹתֵן לָהּ כְּתֻבָּתָהּ:","אֵין מְחַיְּבִין אֶת הַבַּעַל לִפְדּוֹת אֶת אִשְׁתּוֹ יוֹתֵר עַל דָּמֶיהָ אֶלָּא כַּמָּה שֶׁהִיא שָׁוָה כִּשְׁאָר הַשְּׁבוּיוֹת. הָיוּ דָּמֶיהָ יוֹתֵר עַל כְּדֵי כְּתֻבָּתָהּ וְאָמַר הֲרֵינִי מְגָרְשָׁהּ וְזוֹ כְּתֻבָּתָהּ וְתֵלֵךְ וְתִפְדֶּה אֶת עַצְמָהּ אֵין שׁוֹמְעִין לוֹ אֶלָּא כּוֹפִין אוֹתוֹ וּפוֹדֶה אוֹתָהּ אֲפִלּוּ הָיוּ דָּמֶיהָ עַד עֲשָׂרָה בִּכְתֻבָּתָהּ וַאֲפִלּוּ אֵין לוֹ אֶלָּא כְּדֵי פִּדְיוֹנָהּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּפַעַם רִאשׁוֹנָה אֲבָל אִם פְּדָאָהּ וְנִשְׁבֵּית פַּעַם שְׁנִיָּה וְרָצָה לְגָרְשָׁהּ הֲרֵי זֶה מְגָרְשָׁהּ וְנוֹתֵן כְּתֻבָּה וְהִיא תִּפְדֶּה אֶת עַצְמָהּ:","מִי שֶׁנִּשְׁבֵּית אִשְׁתּוֹ וְהוּא בִּמְדִינַת הַיָּם בֵּית דִּין יוֹרְדִין לִנְכָסָיו וּמוֹכְרִין בְּהַכְרָזָה וּפוֹדִין אוֹתָהּ כְּדֶרֶךְ שֶׁהַבַּעַל פּוֹדֶה:","הַמַּדִּיר אֶת אִשְׁתּוֹ נֵדֶר שֶׁהוּא חַיָּב בִּגְלָלוֹ לְגָרְשָׁהּ וְלִתֵּן כְּתֻבָּה וְנִשְׁבֵּית אַחַר שֶׁהִדִּירָהּ אֵינוֹ חַיָּב לִפְדּוֹתָהּ. שֶׁמִּשָּׁעָה שֶׁהִדִּירָהּ נִתְחַיֵּב לְגָרְשָׁהּ וְלִתֵּן לָהּ כְּתֻבָּה:","הָאִשָּׁה שֶׁהָיְתָה אֲסוּרָה עַל בַּעְלָהּ מֵאִסּוּרֵי לָאוִין וְנִשְׁבֵּית אֵינוֹ חַיָּב לִפְדּוֹתָהּ אֶלָּא נוֹתֵן לָהּ כְּתֻבָּתָהּ וְהִיא תִּפְדֶּה אֶת עַצְמָהּ. וַהֲלֹא הַשְּׁבוּיָה אֲסוּרָה לְכֹהֵן וַהֲרֵי הוּא פּוֹדֶה אוֹתָהּ מִפְּנֵי שֶׁלֹּא הָיְתָה אֲסוּרָה מִקֹּדֶם וְאִסּוּר הַשְּׁבִיָּה הוּא שֶׁגָּרַם לָהּ:","מֵתָה אִשְׁתּוֹ חַיָּב בִּקְבוּרָתָהּ וְלַעֲשׂוֹת לָהּ מִסְפֵּד וְקִינִים כְּדֶרֶךְ כָּל הַמְּדִינָה. וַאֲפִלּוּ עָנִי שֶׁבְּיִשְׂרָאֵל לֹא יִפְחֲתוּ לוֹ מִשְּׁנֵי חֲלִילִין וּמְקוֹנֶנֶת. אִם הָיָה עָשִׁיר הַכּל לְפִי כְּבוֹדוֹ. וְאִם הָיָה כְּבוֹדָהּ יוֹתֵר מִכְּבוֹדוֹ קוֹבְרִין אוֹתָהּ לְפִי כְּבוֹדָהּ שֶׁהָאִשָּׁה עוֹלָה עִם בַּעְלָהּ וְאֵינָהּ יוֹרֶדֶת אֲפִלּוּ לְאַחַר מִיתָה:","לֹא רָצָה לִקְבֹּר אֶת אִשְׁתּוֹ וְעָמַד אֶחָד מִדַּעַת עַצְמוֹ וּקְבָרָהּ מוֹצִיאִין מִבַּעְלָהּ עַל כָּרְחוֹ וְנוֹתְנִין לָזֶה כְּדֵי שֶׁלֹּא תִּהְיֶה זוֹ מֻשְׁלֶכֶת לַכְּלָבִים. הָיָה בִּמְדִינָה אַחֶרֶת כְּשֶׁמֵּתָה אִשְׁתּוֹ בֵּית דִּין יוֹרְדִין לִנְכָסָיו וּמוֹכְרִין בְּלֹא הַכְרָזָה וְקוֹבְרִין אוֹתָהּ לְפִי מָמוֹן הַבַּעַל וּלְפִי כְּבוֹדוֹ אוֹ לְפִי כְּבוֹדָהּ:"],"Mishneh Torah, Marriage 25":["הַנּוֹשֵׂא אִשָּׁה סְתָם וְנִמְצְאוּ עָלֶיהָ נְדָרִים תֵּצֵא בְּלֹא כְּתֻבָּה לֹא עִקָּר וְלֹא תּוֹסֶפֶת. בְּאֵלּוּ נְדָרִים אָמְרוּ שֶׁלֹּא תֹּאכַל בָּשָׂר אוֹ שֶׁלֹּא תִּשְׁתֶּה יַיִן אוֹ שֶׁלֹּא תִּתְקַשֵּׁט בְּמִינֵי צִבְעוֹנִין וְהוּא הַדִּין לִשְׁאָר הַמִּינִים שֶׁדֶּרֶךְ כָּל נְשֵׁי הַמָּקוֹם לְהִתְקַשֵּׁט בָּהֶן. אֲבָל נִמְצָא עָלֶיהָ נֵדֶר אַחֵר חוּץ מֵאֵלּוּ לֹא הִפְסִידָה כְּלוּם:","וְכֵן הַכּוֹנֵס אִשָּׁה סְתָם וְנִמְצָא בָּהּ מוּם מִמּוּמֵי הַנָּשִׁים שֶׁכְּבָר בֵּאַרְנוּם וְלֹא יָדַע הַבַּעַל בְּמוּם זֶה וְלֹא שָׁמַע בּוֹ וְרָצָה הֲרֵי זוֹ תֵּצֵא בְּלֹא כְּתֻבָּה לֹא עִקָּר וְלֹא תּוֹסֶפֶת. כֵּיצַד. הָיָה מֶרְחָץ בָּעִיר וְהָיוּ לוֹ קְרוֹבִים אֵינוֹ יָכוֹל לוֹמַר לֹא יָדַעְתִּי מוּמִין אֵלּוּ וַאֲפִלּוּ מוּמִין שֶׁבַּסֵּתֶר מִפְּנֵי שֶׁהוּא בּוֹדֵק בִּקְרוֹבוֹתָיו וַחֲזָקָה שֶׁשָּׁמַע וְרָצָה. וְאִם אֵין שָׁם מֶרְחָץ אוֹ שֶׁלֹּא הָיוּ לוֹ קְרוֹבִים טוֹעֵן בְּמוּמִין שֶׁבַּסֵּתֶר. וְנִכְפָּה בְּעִתִּים יְדוּעִים הֲרֵי הוּא מִמּוּמֵי סֵתֶר. אֲבָל בְּמוּמִין שֶׁבְּגָלוּי אֵינוֹ יָכוֹל לִטְעֹן שֶׁהֲרֵי הַכּל רוֹאִין אוֹתָן וְאוֹמְרִין לוֹ וְחֶזְקָתוֹ שֶׁשָּׁמַע וְנִתְפַּיֵּס. דָּבָר יָדוּעַ הוּא שֶׁאֵין דִּין זֶה אֶלָּא בְּאוֹתָן הַמְּקוֹמוֹת שֶׁהָיָה מִנְהַג הַנָּשִׁים שָׁם לְהַלֵּךְ בַּשּׁוּק וּפְנֵיהֶן גְּלוּיוֹת וְהַכּל יוֹדְעִין אוֹתָן וְאוֹמְרִין זוֹ הִיא בִּתּוֹ שֶׁל פְּלוֹנִי וְזוֹ הִיא אֲחוֹתוֹ שֶׁל פְּלוֹנִי כְּמוֹ עָרֵי אֱדוֹם בַּזְּמַן הַזֶּה. אֲבָל מְקוֹמוֹת שֶׁאֵין דֶּרֶךְ הַבָּנוֹת שָׁם לָצֵאת לַשּׁוּק כְּלָל וְאִם תֵּצֵא הַבַּת לַמֶּרְחָץ בַּנֶּשֶׁף תֵּצֵא מִתְנַכֵּרָה וְלֹא יִרְאֶה אוֹתָהּ אָדָם חוּץ מִקְּרוֹבוֹתֶיהָ הֲרֵי זֶה טוֹעֵן אַף בְּמוּמִין שֶׁבְּגָלוּי. וְהוּא שֶׁלֹּא הָיָה שָׁם מֶרְחָץ וְשֶׁלֹּא הָיְתָה לוֹ קְרוֹבָה לִבְדֹּק בָּהּ. אֲבָל אִם הָיָה שָׁם מֶרְחָץ בְּעִיר זוֹ שֶׁאֵין דֶּרֶךְ הַנָּשִׁים לָצֵאת בָּהּ וּפְנֵיהֶם מְגֻלּוֹת אִם יֵשׁ לוֹ קְרוֹבָה אֵינוֹ יָכוֹל לִטְעֹן שֶׁהֲרֵי הַכּל רוֹאִין אוֹתָהּ עֲרֻמָּה בַּמֶּרְחָץ. וְאִם דַּרְכָּן לְהִתְנַכֵּר וּלְהִתְחַבֵּא אַף בַּמֶּרְחָץ וְשֶׁתִּהְיֶה הַבַּת רוֹחֶצֶת בַּלַּיְלָה אוֹ בְּבַיִת קָטָן בַּמֶּרְחָץ לְבַדָּהּ עַד שֶׁלֹּא תֵּרָאֶה וְלֹא תִּוָּדַע הֲרֵי זֶה טוֹעֵן אַף בְּמוּמִין שֶׁבַּגָּלוּי. וְהַדְּבָרִים אֵלּוּ דְּבָרִים שֶׁל טַעַם הֵם וְאֵינָם גְּזֵרַת הַכָּתוּב:","הוֹרוּ מִקְצָת הַגְּאוֹנִים שֶׁזֶּה שֶׁאָמְרוּ חֲכָמִים מִפְּנֵי שֶׁהוּא בּוֹדֵק בִּקְרוֹבוֹתָיו אֵינוֹ קְרוֹבוֹתָיו בִּלְבַד אֶלָּא אֲפִלּוּ מְיֻדָּעָיו. וַאֲפִלּוּ הָיָה גָּר בְּעִיר שֶׁאֵין לוֹ קָרוֹב כְּלָל אִם יֵשׁ שָׁם מֶרְחָץ אֵינוֹ יָכוֹל לִטְעֹן. שֶׁאִי אֶפְשָׁר שֶׁלֹּא יִהְיוּ לוֹ רֵעִים וְאוֹמֵר לְאֶחָד מֵרֵעָיו שֶׁתִּבְדֹּק לוֹ אִשְׁתּוֹ אוֹ אֲחוֹתוֹ עַל פְּלוֹנִית. וּלְפִיכָךְ חֶזְקָתוֹ שֶׁשָּׁמַע וְנִתְפַּיֵּס. וְלֹא יֵרָאֶה לִי דִּין זֶה שֶׁאֵין כָּל אָדָם מוֹצִיא כָּל מַה שֶּׁיֵּשׁ בְּלִבּוֹ מִדְּבָרִים אֵלּוּ לַכּל אֶלָּא לִקְרוֹבָיו וְעוֹד שֶׁאֵין דַּעְתּוֹ סוֹמֶכֶת אֶלָּא לְדִבְרֵי קְרוֹבָיו בְּיוֹתֵר:","כֵּיצַד הִיא טַעֲנַת הַמּוּמִין. אִם הָיוּ הַמּוּמִין שֶׁנִּמְצְאוּ בָּהּ מוּמִין שֶׁוַּדַּאי הָיוּ בָּהּ קֹדֶם שֶׁתִּתְאָרֵס כְּגוֹן אֶצְבַּע יְתֵרָה וְכַיּוֹצֵא בּוֹ. עַל הָאָב לְהָבִיא רְאָיָה שֶׁיָּדַע בָּהֶן הַבַּעַל וְרָצָה. אוֹ שֶׁחֶזְקָתוֹ שֶׁיָּדַע. וְאִם לֹא הֵבִיא רְאָיָה תֵּצֵא בְּלֹא כְּתֻבָּה כְּלָל. הָיוּ מוּמִים שֶׁאֶפְשָׁר שֶׁנּוֹלְדוּ בָּהּ אַחַר הָאֵרוּסִין אִם נִמְצְאוּ בָּהּ אַחַר שֶׁנִּכְנְסָה לְבֵית הַבַּעַל עַל הַבַּעַל לְהָבִיא רְאָיָה שֶׁעַד שֶׁלֹּא נִתְאָרְסָה הָיוּ בָּהּ וְהָיָה מִקָּחוֹ מִקַּח טָעוּת. וְאִם נִמְצְאוּ בָּהּ וְהִיא בְּבֵית אָבִיהָ עַל הָאָב לְהָבִיא רְאָיָה שֶׁאַחַר הָאֵרוּסִין נוֹלְדוּ וְנִסְתַּחֲפָה שָׂדֵהוּ:","הֵבִיא הַבַּעַל רְאָיָה שֶׁעַד שֶׁלֹּא תִּתְאָרֵס הָיוּ בָּהּ אוֹ שֶׁהוֹדָה לוֹ בְּכָךְ. וְהֵבִיא הָאָב רְאָיָה שֶׁרָאָה וְשָׁתַק וְנִתְפַּיֵּס אוֹ שֶׁחֶזְקָתוֹ שֶׁיָּדַע בָּהֶן וְנִתְפַּיֵּס הֲרֵי זֶה חַיָּב בִּכְתֻבָּה:","בָּא עַל אִשְׁתּוֹ וְשָׁהָה כַּמָּה יָמִים וְטָעַן שֶׁמּוּם זֶה לֹא נִרְאָה לִי עַד עַתָּה אֲפִלּוּ הָיָה בְּתוֹךְ הַקְּמָטִים אוֹ בְּכַף הָרֶגֶל אֵין שׁוֹמְעִין לוֹ. חֲזָקָה שֶׁאֵין אָדָם שׁוֹתֶה בְּכוֹס אֶלָּא אִם כֵּן בּוֹדְקוֹ יָפֶה וְחֶזְקָתוֹ שֶׁיָּדַע וְרָצָה:","הַנּוֹשֵׂא אִשָּׁה וְנִמְצָא שֶׁאֵין לָהּ וֶסֶת קָבוּעַ לְנִדָּתָהּ אֶלָּא לֹא תַּרְגִּישׁ בְּעַצְמָהּ עַד שֶׁתִּרְאֶה דַּם נִדָּה הֲרֵי זוֹ לֹא תְּשַׁמֵּשׁ אֶלָּא בִּשְׁנֵי עֵדִים שֶׁבּוֹדֶקֶת בָּהֶן עַצְמָהּ אֶחָד לִפְנֵי תַּשְׁמִישׁ וְאֶחָד לְאַחַר תַּשְׁמִישׁ חוּץ מִן הָעֵד שֶׁל אִישׁ שֶׁמְּקַנֵּחַ בּוֹ עַצְמוֹ כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת אִסּוּרֵי בִּיאָה:","וְאַף עַל פִּי שֶׁמּוּם גָּדוֹל הוּא זֶה לֹא הִפְסִידָה כְּלוּם שֶׁהֲרֵי בּוֹדֶקֶת עַצְמָהּ תְּחִלָּה וּמְשַׁמֶּשֶׁת. הֲרֵי שֶׁבָּדְקָה עַצְמָהּ וְנִבְעֲלָה וּבְעֵת שֶׁקִּנְּחָה עַצְמָהּ הִיא וְהוּא נִמְצָא דָּם עַל עֵד שֶׁלָּהּ אוֹ עַל עֵד שֶׁלּוֹ אִם אֵרַע זֶה פַּעַם אַחַר פַּעַם שָׁלֹשׁ פְּעָמִים סְמוּכוֹת זוֹ לָזוֹ הֲרֵי זוֹ אֲסוּרָה לֵישֵׁב עִם בַּעְלָהּ וְתֵצֵא בְּלֹא כְּתֻבָּה לֹא עִקָּר וְלֹא תּוֹסֶפֶת. וְאֵין לָהּ תְּנַאי מִתְּנָאֵי כְּתֻבָּה שֶׁהֲרֵי אֵינָהּ רְאוּיָה לְתַשְׁמִישׁ וְיוֹצִיא וְלֹא יַחֲזִיר לְעוֹלָם. שֶׁמָּא תִּתְרַפֵּא וְנִמְצָא שֶׁלֹּא גָּמַר לְגָרְשָׁהּ בִּשְׁעַת גֵּרוּשִׁין. וּמֻתֶּרֶת לְהִנָּשֵׂא לְאַחֵר כְּמוֹ שֶׁיִּתְבָּאֵר בְּעִנְיַן הַנִּדָּה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיְתָה כָּךְ מִתְּחִלַּת נִשּׂוּאֶיהָ וּמִבְּעִילָה רִאשׁוֹנָה רָאֲתָה דָּם. אֲבָל אִם אֵרַע לָהּ חלִי זֶה אַחַר שֶׁנִּשֵּׂאת נִסְתַּחֲפָה שָׂדֵהוּ. לְפִיכָךְ אִם בָּעַל פַּעַם אַחַת וְלֹא נִמְצָא דָּם וְאַחַר כָּךְ חָזְרָה לִהְיוֹת רוֹאָה דָּם בְּכָל עֵת תַּשְׁמִישׁ יוֹצִיא וְיִתֵּן כְּתֻבָּה כֻּלָּהּ וְלֹא יַחֲזִיר עוֹלָמִית כְּמוֹ שֶׁבֵּאַרְנוּ:","וְכֵן אִשָּׁה שֶׁנּוֹלְדוּ בָּהּ מוּמִין אַחַר שֶׁנִּשֵּׂאת אֲפִלּוּ נַעֲשֵׂית מֻכַּת שְׁחִין אִם רָצָה לְקַיֵּם יְקַיֵּם וְאִם רָצָה לְהוֹצִיא יִתֵּן כְּתֻבָּה:","הָאִישׁ שֶׁנּוֹלְדוּ בּוֹ מוּמִין אַחַר שֶׁנִּשָּׂא אֲפִלּוּ נִקְטְעָה יָדוֹ אוֹ רַגְלוֹ אוֹ נִסְמֵית עֵינוֹ וְלֹא רָצְתָה אִשְׁתּוֹ לֵישֵׁב עִמּוֹ אֵין כּוֹפִין אוֹתוֹ לְהוֹצִיא וְלִתֵּן כְּתֻבָּה אֶלָּא אִם רָצְתָה תֵּשֵׁב וְאִם לֹא רָצְתָה תֵּצֵא בְּלֹא כְּתֻבָּה כְּדִין כָּל מוֹרֶדֶת. אֲבָל אִם נוֹלַד לוֹ רֵיחַ הַפֶּה אוֹ רֵיחַ הַחֹטֶם אוֹ שֶׁחָזַר לִלְקֹט צוֹאַת כְּלָבִים אוֹ לַחְצֹב נְחשֶׁת מֵעִקָּרוֹ אוֹ לְעַבֵּד עוֹרוֹת. כּוֹפִין אוֹתוֹ לְהוֹצִיא וְלִתֵּן כְּתֻבָּה. וְאִם רָצְתָה תֵּשֵׁב עִם בַּעְלָהּ:","נַעֲשָׂה הָאִישׁ מֻכֶּה שְׁחִין כּוֹפִין אוֹתוֹ לְהוֹצִיא וְלִתֵּן כְּתֻבָּה. וְאַף עַל פִּי שֶׁהִיא רוֹצָה לֵישֵׁב אֵין שׁוֹמְעִין לָהּ אֶלָּא שֶׁמַּפְרִישִׁין אוֹתָן בְּעַל כָּרְחָן מִפְּנֵי שֶׁהִיא מְמִיקַתּוֹ. וְאִם אָמְרָה אֵשֵׁב עִמּוֹ בְּעֵדִים כְּדֵי שֶׁלֹּא יָבוֹא עָלֶיהָ שׁוֹמְעִין לָהּ:","מִי שֶׁהָיָה בַּעְלָהּ בַּעַל רֵיחַ הַפֶּה אוֹ רֵיחַ הַחֹטֶם אוֹ מְלַקֵּט צוֹאַת כְּלָבִים וְכַיּוֹצֵא בָּהֶן וּמֵת וְנָפְלָה לִפְנֵי אָחִיו וְיֵשׁ בּוֹ אוֹתוֹ מוּם שֶׁהָיָה בְּבַעְלָהּ. יְכוֹלָה הִיא לוֹמַר לְאָחִיךָ הָיִיתִי יְכוֹלָה לְקַבֵּל וּלְךָ אֵינִי יְכוֹלָה לְקַבֵּל וְיַחֲלֹץ וְיִתֵּן כְּתֻבָּה. וּרְאֵה בָנִים לְבָנֶיךָ שָׁלוֹם עַל יִשְׂרָאֵל:"],"Mishneh Torah, Mourning 13":["כֵּיצַד מְנַחֲמִין אֶת הָאֲבֵלִים. אַחַר שֶׁקּוֹבְרִין אֶת הַמֵּת מִתְקַבְּצִין הָאֲבֵלִים וְעוֹמְדִין בְּצַד בֵּית הַקְּבָרוֹת. וְכָל הַמְלַוִּין אֶת הַמֵּת עוֹמְדִין סָבִיב לָהֶן שׁוּרָה לִפְנֵי שׁוּרָה. וְאֵין שׁוּרָה פְּחוּתָה מֵעֲשָׂרָה וְאֵין אֲבֵלִים מִן הַמִּנְיָן:","הָאֲבֵלִים עוֹמְדִין לִשְׂמֹאל הַמְנַחֲמִין וְכָל הַמְנַחֲמִין בָּאִין אֵצֶל הָאֲבֵלִים אֶחָד אֶחָד. וְאוֹמְרִים לָהֶן תְּנֻחֲמוּ מִן הַשָּׁמַיִם. וְאַחַר כָּךְ הוֹלֵךְ הָאָבֵל לְבֵיתוֹ. וְכָל יוֹם וְיוֹם מִשִּׁבְעַת יְמֵי אֲבֵלוּת בָּאִין בְּנֵי אָדָם לְנַחֲמוֹ. בֵּין שֶׁבָּאוּ פָּנִים חֲדָשׁוֹת בֵּין שֶׁלֹּא בָּאוּ:","הָאָבֵל מֵסֵב בָּרֹאשׁ. וְאֵין הַמְנַחֲמִין רַשָּׁאִין לֵישֵׁב אֶלָּא עַל גַּבֵּי קַרְקַע. שֶׁנֶּאֱמַר (איוב ב יג) \"וַיֵּשְׁבוּ אִתּוֹ לָאָרֶץ\". וְאֵין רַשָּׁאִין לוֹמַר דָּבָר עַד שֶׁיִּפְתַּח הָאָבֵל אֶת פִּיו תְּחִלָּה. שֶׁנֶּאֱמַר (איוב ב יג) \"וְאֵין דֹּבֵר אֵלָיו דָּבָר\" וּכְתִיב (איוב ג א) \"אַחֲרֵי כֵן פָּתַח אִיּוֹב אֶת פִּיהוּ\" וְגוֹ' (איוב ד א) \"וַיַּעַן אֱלִיפַז\". וְכֵיוָן שֶׁנִּעְנֵעַ בְּרֹאשׁוֹ שׁוּב אֵין הַמְנַחֲמִין רַשָּׁאִין לֵישֵׁב אֶצְלוֹ. שֶׁלֹּא יַטְרִיחוּהוּ יוֹתֵר מִדַּאי:","מֵת שֶׁאֵין לוֹ אֲבֵלִים לְהִתְנַחֵם. בָּאִים עֲשָׂרָה בְּנֵי אָדָם כְּשֵׁרִין וְיוֹשְׁבִין בִּמְקוֹמוֹ כָּל שִׁבְעַת יְמֵי הָאֲבֵלוּת. וּשְׁאָר הָעָם מִתְקַבְּצִין עֲלֵיהֶן. וְאִם לֹא הָיוּ שָׁם עֲשָׂרָה קְבוּעִין בְּכָל יוֹם וְיוֹם מִתְקַבְּצִין עֲשָׂרָה מִשְּׁאָר הָעָם וְיוֹשְׁבִין בִּמְקוֹמוֹ:","הַכּל חַיָּבִין לַעֲמֹד בִּפְנֵי נָשִׂיא חוּץ מֵאָבֵל וְחוֹלֶה. וּלְכָל הָעוֹמֵד מִפָּנָיו אוֹמֵר לוֹ שֵׁב חוּץ מֵאָבֵל וְחוֹלֶה שֶׁמַּשְׁמָע יֵשֵׁב בְּאֶבְלוֹ יֵשֵׁב בְּחָלְיוֹ:","מְכַבְּדִין וּמְרַבְּצִין בְּבֵית הָאָבֵל. וּמְדִיחִין קְעָרוֹת וְכוֹסוֹת וְקִיתוֹנוֹת וּצְלוֹחִיּוֹת וּמַדְלִיקִין אֶת הַנֵּרוֹת. אֲבָל אֵין מְבִיאִין שָׁם לֹא אֶת הַמֻּגְמָר וְלֹא אֶת הַבְּשָׂמִים:","אֵין מוֹלִיכִין לְבֵית הָאָבֵל הַמַּאֲכָל שֶׁמַּבְרִין בּוֹ. לֹא בִּכְלֵי כֶּסֶף וְלֹא בִּכְלֵי שַׁעַם וְכַיּוֹצֵא בָּהֶן. אֶלָּא בִּכְלֵי נְסָרִים שֶׁל עֲרָבָה קְלוּפָה וְכַיּוֹצֵא בָּהֶן. שֶׁלֹּא לְבַיֵּשׁ אֶת מִי שֶׁאֵין לוֹ. וְאֵין מַשְׁקִין בִּזְכוּכִית לְבָנָה אֶלָּא בִּצְבוּעָה. שֶׁלֹּא לְבַיֵּשׁ אֶת הָעֲנִיִּים שֶׁאֵין יֵינוֹתֵיהֶן טוֹבוֹת:","אֵין שׁוֹתִין בְּבֵית הָאָבֵל יֶתֶר עַל עֲשָׂרָה כּוֹסוֹת לְכָל אֶחָד וְאֶחָד. שְׁלֹשָׁה קֹדֶם אֲכִילָה. וּשְׁלֹשָׁה בְּתוֹךְ אֲכִילָה. וְאַרְבָּעָה לְאַחַר אֲכִילָה. וְלֹא יוֹסִיף שֶׁמָּא יִשְׁתַּכֵּר:","אֵין אוֹמְרִין שְׁמוּעָה וְהַגָּדָה בְּבֵית הָאָבֵל אֶלָּא יוֹשְׁבִין דָּוִין. וְכֵן אֵין אוֹמְרִין בִּפְנֵי הַמֵּת אֶלָּא דְּבָרִים שֶׁל מֵת. אֲבָל לַעֲסֹק בְּדִבְרֵי תּוֹרָה בְּפָנָיו אוֹ בְּבֵית הַקְּבָרוֹת אָסוּר:","אֵין בּוֹכִין עַל הַמֵּת יֶתֶר מִשְּׁלֹשָׁה יָמִים. וְאֵין מַסְפִּידִין יֶתֶר מִשִּׁבְעָה. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר הָעָם. אֲבָל תַּלְמִידֵי חֲכָמִים הַכּל לְפִי חָכְמָתָן. וְאֵין בּוֹכִיִן עֲלֵיהֶם יוֹתֵר מִשְּׁלֹשִׁים יוֹם. שֶׁאֵין לָנוּ גָּדוֹל מִמּשֶׁה רַבֵּנוּ וּכְתִיב (דברים לד ח) \"וַיִּתְּמוּ יְמֵי בְכִי אֵבֶל משֶׁה\". וְכֵן אֵין מַסְפִּידִין יֶתֶר עַל שְׁנֵים עָשָׂר חֹדֶשׁ. אֵין לָנוּ בְּחָכְמָה גָּדוֹל מֵרַבֵּנוּ הַקָּדוֹשׁ וּשְׁנֵים עָשָׂר חֹדֶשׁ בִּלְבַד נִסְפַּד. וְכֵן חָכָם שֶׁבָּאָה שְׁמוּעָתוֹ לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ אֵין סוֹפְדִין אוֹתוֹ:","אַל יִתְקַשֶּׁה אָדָם עַל מֵתוֹ יֶתֶר מִדַּאי. שֶׁנֶּאֱמַר (ירמיה כב י) \"אַל תִּבְכּוּ לְמֵת וְאַל תָּנֻדוּ לוֹ\". כְּלוֹמַר יֶתֶר מִדַּאי שֶׁזֶּהוּ מִנְהָגוֹ שֶׁל עוֹלָם. וְהַמְצַעֵר [עַצְמוֹ יוֹתֵר] עַל מִנְהָגוֹ שֶׁל עוֹלָם הֲרֵי זֶה טִפֵּשׁ. אֶלָּא כֵּיצַד יַעֲשֶׂה. שְׁלֹשָׁה לִבְכִי. שִׁבְעָה לְהֶסְפֵּד. שְׁלֹשִׁים יוֹם לְתִסְפֹּרֶת וְלִשְׁאָר הַחֲמִשָּׁה דְּבָרִים:","כָּל מִי שֶׁאֵינוֹ מִתְאַבֵּל כְּמוֹ שֶׁצִּוּוּ חֲכָמִים הֲרֵי זֶה אַכְזָרִי. אֶלָּא יִפְחַד וְיִדְאַג וִיפַשְׁפֵּשׁ בְּמַעֲשָׂיו וְיַחְזֹר בִּתְשׁוּבָה. וְאֶחָד מִבְּנֵי חֲבוּרָה שֶׁמֵּת תִּדְאַג כָּל הַחֲבוּרָה כֻּלָּהּ. כָּל שְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים יִרְאֶה אֶת עַצְמוֹ כְּאִלּוּ חֶרֶב מֻנַּחַת לוֹ עַל צַוָּארוֹ. וּמִשְּׁלֹשָׁה וְעַד שִׁבְעָה [כְּאִלּוּ הִיא] מֻנַּחַת בְּקֶרֶן זָוִית. מִכָּאן וְאֵילָךְ [כְּאִלּוּ] עוֹבֶרֶת כְּנֶגְדּוֹ בַּשּׁוּק. כָּל זֶה לְהָכִין עַצְמוֹ וְיַחְזֹר וְיֵעוֹר מִשְּׁנָתוֹ. וַהֲרֵי הוּא אוֹמֵר הִכִּיתָה אֹתָם וְלֹא חָלוּ מִכְלַל שֶׁצָּרִיךְ לְהָקִיץ וְלָחוּל:"],"Mishneh Torah, Murderer and the Preservation of Life 11":["מִצְוַת עֲשֵׂה לַעֲשׂוֹת אָדָם מַעֲקֶה לְגַגּוֹ שֶׁנֶּאֱמַר (דברים כב ח) \"וְעָשִׂיתָ מַעֲקֶה לְגַגֶּךָ\". וְהוּא שֶׁיִּהְיֶה בֵּית דִּירָה. אֲבָל בֵּית הָאוֹצָרוֹת וּבֵית הַבָּקָר וְכַיּוֹצֵא בָּהֶן אֵינוֹ זָקוּק לוֹ. וְכָל בַּיִת שֶׁאֵין בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת פָּטוּר מִן הַמַּעֲקֶה:","בַּיִת שֶׁל שְׁנֵי שֻׁתָּפִין חַיָּבִין בְּמַעֲקֶה שֶׁנֶּאֱמַר (דברים כב ח) \"כִּי יִפּל הַנֹּפֵל מִמֶּנּוּ\" לֹא תָּלָה אֶלָּא בְּנוֹפֵל. אִם כֵּן לָמָּה נֶאֱמַר (דברים כב ח) \"גַּגֶּךָ\" לְמַעֵט בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת לְפִי שֶׁאֵינָן עֲשׂוּיִים לְדִירָה. הָיְתָה רְשׁוּת הָרַבִּים גְּבוֹהָה מִגַּגּוֹ אֵינוֹ זָקוּק לְמַעֲקֶה שֶׁנֶּאֱמַר כִּי יִפּל הַנֹּפֵל מִמֶּנּוּ וְלֹא לְתוֹכוֹ:","גֹּבַהּ הַמַּעֲקֶה אֵין פָּחוֹת מֵעֲשָׂרָה טְפָחִים כְּדֵי שֶׁלֹּא יִפּל מִמֶּנּוּ הַנּוֹפֵל. וְצָרִיךְ לִהְיוֹת הַמְחִצָּה חֲזָקָה כְּדֵי שֶׁיִּשָּׁעֵן אָדָם עָלֶיהָ וְלֹא תִּפּל. וְכָל הַמֵּנִיחַ גַּגּוֹ בְּלֹא מַעֲקֶה בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר עַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כב ח) \"וְלֹא תָשִׂים דָּמִים בְּבֵיתֶךָ\". וְאֵין לוֹקִין עַל לָאו זֶה מִפְּנֵי שֶׁאֵין בּוֹ מַעֲשֶׂה:","אֶחָד הַגַּג וְאֶחָד כָּל דָּבָר שֶׁיֵּשׁ בּוֹ סַכָּנָה וְרָאוּי שֶׁיִּכָּשֵׁל בָּהּ אָדָם וְיָמוּת. כְּגוֹן שֶׁהָיְתָה לוֹ בְּאֵר אוֹ בּוֹר בַּחֲצֵרוֹ בֵּין שֶׁיֵּשׁ בּוֹ מַיִם בֵּין שֶׁאֵין בּוֹ מַיִם חַיָּב לַעֲשׂוֹת חֻלְיָא גְּבוֹהָה עֲשָׂרָה טְפָחִים. אוֹ לַעֲשׂוֹת לָהּ כִּסּוּי כְּדֵי שֶׁלֹּא יִפּל בָּהּ אָדָם וְיָמוּת. וְכֵן כָּל מִכְשׁל שֶׁיֵּשׁ בּוֹ סַכָּנַת נְפָשׁוֹת מִצְוַת עֲשֵׂה לַהֲסִירוֹ וּלְהִשָּׁמֵר מִמֶּנּוּ וּלְהִזָּהֵר בַּדָּבָר יָפֶה יָפֶה. שֶׁנֶּאֱמַר (דברים ד ט) \"הִשָּׁמֶר לְךָ וּשְׁמֹר נַפְשְׁךָ\". וְאִם לֹא הֵסִיר וְהֵנִיחַ הַמִּכְשׁוֹלוֹת הַמְּבִיאִין לִידֵי סַכָּנָה בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר בְּ(דברים כב ח) \"לֹא תָשִׂים דָּמִים\":","הַרְבֵּה דְּבָרִים אָסְרוּ חֲכָמִים מִפְּנֵי שֶׁיֵּשׁ בָּהֶם סַכָּנַת נְפָשׁוֹת. וְכָל הָעוֹבֵר עֲלֵיהֶן וְאוֹמֵר הֲרֵינִי מְסַכֵּן בְּעַצְמִי וּמַה לַּאֲחֵרִים עָלַי בְּכָךְ אוֹ אֵינִי מַקְפִּיד בְּכָךְ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","וְאֵלּוּ הֵן. לֹא יַנִּיחַ אָדָם פִּיו עַל הַסִּילוֹן הַמְקַלֵּחַ וְיִשְׁתֶּה. וְלֹא יִשְׁתֶּה בַּלַּיְלָה מִן הַנְּהָרוֹת וּמִן הָאֲגַמִּים שֶׁמָּא יִבְלַע עֲלוּקָה וְהוּא אֵינוֹ רוֹאֶה. וְלֹא יִשְׁתֶּה מַיִם מְגֻלִּים שֶׁמָּא שָׁתָה מֵהֶן נָחָשׁ וְכַיּוֹצֵא בּוֹ מִזּוֹחֲלֵי עָפָר וְיָמוּת:","וְאֵלּוּ הֵן הַמַּשְׁקִין הָאֲסוּרִין מִשּׁוּם גִּלּוּי. הַמַּיִם. וְהַיַּיִן. וַאֲפִלּוּ מָזוּג וַאֲפִלּוּ הִתְחִיל טַעֲמוֹ לְהִשְׁתַּנּוֹת לְחֹמֶץ. וְהֶחָלָב. וְהַדְּבַשׁ. וְהַצִּיר. אֲבָל שְׁאָר כָּל הַמַּשְׁקִין אֵין מַקְפִּידִין עַל גִּלּוּיָן שֶׁאֵין בַּעֲלֵי אֶרֶס שׁוֹתִין מֵהֶן:","הַשּׁוּם שֶׁנִּתְרַסֵּק וַאֲבַטִּיחַ שֶׁנֶּחְתַּךְ וְנִתְגַּלָּה אָסוּר. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן. יַיִן מְבֻשָּׁל וְיַיִן תּוֹסֵס אֵין בָּהֶן מִשּׁוּם גִּלּוּי. וְתוֹסֵס הוּא הַיַּיִן מִשְּׁעַת דְּרִיכָתוֹ עַד שְׁלֹשָׁה יָמִים. וְיַיִן אוֹ מַיִם אוֹ חָלָב שֶׁהָיוּ חַמִּין כָּל זְמַן שֶׁהַהֶבֶל עוֹלֶה מֵהֶן וְכֵן מַשְׁקִין שֶׁהָיָה הַמַּשְׁקֶה יוֹרֵד מִלְּמַעְלָה לְתוֹכָן טִפָּה אַחַר טִפָּה וְהוּא שֶׁיִּהְיֶה טוֹרֵד וְיוֹרֵד כָּל אֵלּוּ אֵין בָּהֶן מִשּׁוּם גִּלּוּי שֶׁזּוֹחֲלֵי עָפָר מִתְיָרְאִים מִבִּעְבּוּעַ הַמַּשְׁקֶה וּמִן הַהֶבֶל וְאֵין שׁוֹתִין מִמֶּנּוּ:","מֵי כְּבָשִׁין וּמִי שְׁלָקוֹת וּמֵי תּוּרְמוּסִין אֵין בָּהֶן מִשּׁוּם גִּלּוּי. מַיִם שֶׁשָּׁרָה בָּהֶן כְּבָשִׁין וּשְׁלָקוֹת וְתוּרְמוּסִין אִם נִשְׁתַּנָּה טַעְמָן אֵין בָּהֶם מִשּׁוּם גִּלּוּי. וְאִם אֵין בָּהֶם נוֹתֵן טַעַם אֲסוּרִין. וְכֵן מַיִם שֶׁהֵדִיחַ בָּהֶן פְּרִישִׁים וְדַרְמוּסְקִין לַחוֹלֶה אֲסוּרִין מִשּׁוּם גִּלּוּי:","יַיִן שֶׁנִּתְחַבֵּר בּוֹ דְּבָרִים חַדִּין כְּפִלְפְּלִין אוֹ דְּבָרִים מָרִים כְּאַפְסַנְתִּין עַד שֶׁנִּשְׁתַּנָּה טַעֲמָם אֵין בּוֹ מִשּׁוּם גִּלּוּי. וְהוּא הַדִּין בִּשְׁאָר הַמַּשְׁקִין:","כָּל הַמַּשְׁקִין הָאֲסוּרִין מִשּׁוּם גִּלּוּי שֶׁנִּתְגַּלּוּ בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה אֲסוּרִין וַאֲפִלּוּ הָיָה בְּצִדָּן אָדָם יָשֵׁן אֵין אֵימַת יָשֵׁן עַל הַזּוֹחֲלִין. וְכַמָּה יִשְׁהוּ וְיֵאָסְרוּ. כְּדֵי שֶׁיֵּצֵא הָרַחַשׁ מִתַּחַת אֹזֶן כְּלִי וְיִשְׁתֶּה וְיַחְזֹר לִמְקוֹמוֹ:","שִׁעוּר הַמַּיִם שֶׁיֵּאָסְרוּ אִם נִתְגַּלּוּ כְּדֵי שֶׁיִּהְיֶה הַסַּם נִכָּר בָּהֶן וּמַזִּיק. אֲבָל אִם הָיוּ הַמַּיִם מְרֻבִּין כְּדֵי שֶׁתֹּאבַד בָּהֶן הַמָּרָה הֲרֵי אֵלּוּ מֻתָּרִין בֵּין בְּכֵלִים בֵּין בְּקַרְקָעוֹת. וְכֵן הַדִּין בִּשְׁאָר הַמַּשְׁקִין:","מַעְיָן הַמּוֹשֵׁךְ כָּל שֶׁהוּא אֵין בּוֹ מִשּׁוּם גִּלּוּי. לָגִין מְגֻלֶּה שֶׁהִנִּיחוֹ בְּשִׁדָּה תֵּבָה וּמִגְדָּל אוֹ בַּתִּיק שֶׁלּוֹ אוֹ בַּבּוֹר אֲפִלּוּ עָמֹק מֵאָה אַמָּה אוֹ בְּמִגְדָּל גָּבוֹהַּ מֵאָה אַמָּה אוֹ בִּטְרַקְלִין מְיֻפֶּה וּמְסֻיָּד הֲרֵי זֶה אָסוּר. בָּדַק אֶת הַתֵּבָה אוֹ אֶת הַמִּגְדָּל וְאַחַר כָּךְ הִנִּיחוֹ הֲרֵי זֶה מֻתָּר. וְאִם הָיָה בָּהֶן נֶקֶב אָסוּר. כַּמָּה יְהֵא בַּנֶּקֶב. כְּדֵי שֶׁתִּכָּנֵס אֶצְבַּע קְטַנָּה שֶׁל קָטָן:","חָבִית שֶׁנִּתְגַּלְּתָה אַף עַל פִּי שֶׁשָּׁתוּ מִמֶּנּוּ תִּשְׁעָה וְלֹא מֵתוּ לֹא יִשְׁתֶּה עֲשִׂירִי. מַעֲשֶׂה הָיָה וְאָמְרוּ שֶׁשָּׁתָה עֲשִׂירִי וּמֵת מִפְּנֵי שֶׁאֶרֶס הַנָּחָשׁ שָׁקַע לְמַטָּה. וְיֵשׁ סַם חֲמַת זוֹחֲלֵי עָפָר שֶׁעוֹלֶה וְצָף לְמַעְלָה וְיֵשׁ סַם שֶׁהִיא נִתְלֵית בְּאֶמְצַע הַמַּשְׁקֶה. לְפִיכָךְ הַכּל אָסוּר וַאֲפִלּוּ סִנְּנוֹ בְּמִסְנֶנֶת. וְכֵן אֲבַטִּיחַ שֶׁנִּתְגַּלָּה אַף עַל פִּי שֶׁאָכְלוּ מִמֶּנּוּ תִּשְׁעָה וְלֹא מֵתוּ לֹא יֹאכַל עֲשִׂירִי:","מַיִם שֶׁנִּתְגַּלּוּ לֹא יִשְׁפְּכֵם לִרְשׁוּת הָרַבִּים וְלֹא יְרַבֵּץ בָּהֶם אֶת הַבַּיִת וְלֹא יְגַבֵּל בָּהֶן אֶת הַטִּיט וְלֹא יִרְחַץ בָּהֶן פָּנָיו יָדָיו וְרַגְלָיו וְלֹא יַשְׁקֶה מֵהֶן לֹא בְּהֶמְתּוֹ וְלֹא בֶּהֱמַת חֲבֵרוֹ. אֲבָל מַשְׁקֶה אוֹתָן לֶחָתוּל:","עִסָּה שֶׁנִּלּוֹשָׁה בְּמַיִם מְגֻלִּין אֲפִלּוּ הִיא שֶׁל תְּרוּמָה תִּשָּׂרֵף וַאֲפִלּוּ נֶאֱפֵת הַפַּת אֲסוּרָה:"],"Mishneh Torah, Nazariteship 10":["אֵין אָדָם מְגַלֵּחַ תִּגְלַחַת אַחַת וְעוֹלָה לוֹ לְנִזְרוֹ וּלְצָרַעְתּוֹ. וְתִגְלַחַת הַצָּרַעַת בִּזְמַן שֶׁהוּא סְפֵק מְצֹרָע אֵינוֹ דּוֹחֶה אֶת הַנְּזִירוּת. לְפִיכָךְ מִי שֶׁנָּזַר שָׁנָה אַחַת וְהָיָה בְּכָל הַשָּׁנָה הַזֹּאת סְפֵק מְצֹרָע וּסְפֵק טְמֵא מֵת אוֹ שֶׁהָיָה בָּהּ סְפֵק מְצֹרָע וּבְסוֹף הַשָּׁנָה נִטְמָא בְּסָפֵק הֲרֵי זֶה מוֹנֶה שִׁבְעָה יָמִים וּמַזֶּה בַּשְּׁלִישִׁי וּשְׁבִיעִי וְאֵינוֹ מְגַלֵּחַ בַּשְּׁבִיעִי וְאֵינוֹ יָכוֹל לִשְׁתּוֹת בְּיַיִן וּלְהִטַּמֵּא לְמֵת אֶלָּא לְאַחַר אַרְבַּע שָׁנִים. וְאוֹכֵל בְּקָדָשִׁים לְאַחַר שְׁתֵּי שָׁנִים מִפְּנֵי שֶׁהוּא צָרִיךְ לְגַלֵּחַ אַרְבַּע תִּגְלָחִיּוֹת. תִּגְלַחַת טָהֳרָה וְתִגְלַחַת טֻמְאָה מִסָּפֵק וּשְׁתֵּי תִּגְלָחִיּוֹת שֶׁמְּגַלֵּחַ הַמְצֹרָע. שֶׁהֲרֵי הוּא סְפֵק מְצֹרָע:","תִּגְלַחַת רִאשׁוֹנָה מְגַלֵּחַ אוֹתָהּ אַחַר שָׁנָה רִאשׁוֹנָה וּמְגַלֵּחַ בָּהּ רֹאשׁוֹ וּזְקָנוֹ וְגַבּוֹת עֵינָיו. וּמִטַּהֵר בְּעֵץ אֶרֶז וְאֵזוֹב וְצִפֳּרִים כִּשְׁאָר מְצֹרָעִים. אִם אֵינוֹ טְמֵא מֵת וְלֹא מְצֹרָע הֲרֵי הִיא תִּגְלַחַת טָהֳרָה שֶׁל נְזִירוּתוֹ. וְאִם הוּא מְצֹרָע וַדַּאי בְּשָׁנָה רִאשׁוֹנָה הֲרֵי הִיא תִּגְלַחַת רִאשׁוֹנָה שֶׁל מְצֹרָע. וְשׁוֹהֶה שָׁנָה אַחֶרֶת כְּמִנְיַן יְמֵי הַנְּזִירוּת. וְאַחַר כָּךְ מְגַלֵּחַ תִּגְלַחַת שְׁנִיָּה שֶׁל מְצֹרָע. שֶׁאֵינוֹ יָכוֹל לְגַלֵּחַ אַחַר שִׁבְעָה כִּשְׁאָר מְצֹרָעִין שֶׁמָּא אֵינוֹ מְצֹרָע אֶלָּא טְמֵא מֵת וַדַּאי הָיָה וְשָׁנָה שְׁנִיָּה זוֹ הֲרֵי הוּא בָּהּ נָזִיר שֶׁאָסוּר לְגַלֵּחַ. וּמֵאַחַר שֶׁגִּלֵּחַ שְׁתֵּי תִּגְלָחִיּוֹת אֵלּוּ שָׁלְמָה טָהֳרַת הַצָּרַעַת וּמֻתָּר לֶאֱכל בְּקָדָשִׁים וְשׁוֹהֶה שָׁנָה שְׁלִישִׁית וְאַחַר כָּךְ מְגַלֵּחַ תִּגְלַחַת שְׁלִישִׁית שֶׁמָּא מְצֹרָע וַדַּאי הָיָה בְּשָׁנָה רִאשׁוֹנָה וְלֹא הָיָה טְמֵא מֵת וְשָׁנָה רִאשׁוֹנָה לֹא עָלְתָה לוֹ מִפְּנֵי שֶׁהִיא יְמֵי חִלּוּטוֹ וְשָׁנָה שְׁנִיָּה לֹא עָלְתָה לוֹ מִפְּנֵי שֶׁהִיא יְמֵי סְפִירוֹ שֶׁל מְצֹרָע שֶׁבֵּין תִּגְלַחַת רִאשׁוֹנָה וּשְׁנִיָּה. לְפִיכָךְ צָרִיךְ לִשְׁהוֹת שָׁנָה שְׁלִישִׁית בִּנְזִירוּתוֹ וּמְגַלֵּחַ תִּגְלַחַת שְׁלִישִׁית לִנְזִירוּתוֹ וְהִיא תִּגְלַחַת טָהֳרָה. אוֹ שֶׁמָּא טְמֵא מֵת וַדַּאי הָיָה וּמְצֹרָע וַדַּאי וְאֵין תִּגְלַחַת אַחַת עוֹלָה לִנְזִירוּתוֹ וּלְצָרַעְתּוֹ וְנִמְצֵאת תִּגְלַחַת רִאשׁוֹנָה וּשְׁנִיָּה תִּגְלַחַת צָרָעַת וְתִגְלַחַת שְׁלִישִׁית תִּגְלַחַת טֻמְאָה וְאֵין אַחַת מִשָּׁלֹשׁ שָׁנִים עוֹלָה שֶׁהֲרֵי הַשְּׁלִישִׁית תִּגְלַחַת טֻמְאָה. לְפִיכָךְ צָרִיךְ לִשְׁהוֹת שָׁנָה רְבִיעִית בִּנְזִירוּת וּמְגַלֵּחַ תִּגְלַחַת רְבִיעִית. וּשְׂעָרוֹ בְּכָל תִּגְלַחַת סָפֵק אָסוּר בַּהֲנָיָה מִסָּפֵק. שֶׁשְּׂעַר נָזִיר שֶׁנִּצְטָרֵעַ מֻתָּר בַּהֲנָיָה:","וְכֵן אִם נָדַר עֶשֶׂר שָׁנִים נְזִירוּת וְהָיָה בָּהֶן סְפֵק מְצֹרָע וְנוֹלַד לוֹ סְפֵק טֻמְאָה בְּסוֹפָן הֲרֵי זֶה אֵינוֹ שׁוֹתֶה בְּיַיִן עַד אַרְבָּעִים שָׁנָה וּמְגַלֵּחַ אַרְבַּע תִּגְלָחוֹת אַחַת בְּסוֹף כָּל עֶשֶׂר שָׁנִיִם. תִּגְלַחַת רִאשׁוֹנָה לִסְפֵק יְמֵי צָרַעְתּוֹ. שְׁנִיָּה לִסְפֵק יְמֵי סְפִירוֹ שֶׁל מְצֹרָע. שְׁלִישִׁית לִסְפֵק טֻמְאָתוֹ. רְבִיעִית תִּגְלַחַת טָהֳרָה:","וְכֵיצַד מֵבִיא זֶה קָרְבְּנוֹתָיו. אִם הָיָה עָשִׁיר כּוֹתֵב נְכָסָיו לַאֲחֵרִים שֶׁמְּצֹרָע עָשִׁיר שֶׁהֵבִיא קָרְבַּן עָנִי לֹא יָצָא. וְאַחַר כָּךְ מֵבִיא חַטַּאת הָעוֹף וְעוֹלַת בְּהֵמָה בְּתִגְלַחַת רִאשׁוֹנָה וּשְׁנִיָּה וּשְׁלִישִׁית. וְכָל חַטַּאת עוֹף מֵהֶן לֹא תֵּאָכֵל מִפְּנֵי שֶׁהִיא סָפֵק. וּמֵבִיא בְּתִגְלַחַת רְבִיעִית קָרְבַּן נָזִיר טָהוֹר שֶׁהוּא שָׁלֹשׁ בְּהֵמוֹת כְּמוֹ שֶׁבֵּאַרְנוּ:","שָׁלֹשׁ חַטְּאוֹת הָעוֹף שֶׁמֵּבִיא בִּשְׁלֹשׁ הַתִּגְלָחוֹת. חַטָּאת רִאשׁוֹנָה לִסְפֵק טֻמְאָתוֹ. שְׁנִיָּה לִסְפֵק צָרַעְתּוֹ שֶׁאֵין הַמְצֹרָע מֵבִיא קָרְבָּנוֹ אֶלָּא לְאַחַר תִּגְלַחַת שְׁנִיָּה. וְכֵן חַטָּאת שְׁלִישִׁית לִסְפֵק טֻמְאָתוֹ שֶׁאֵין תִּגְלַחַת אַחַת עוֹלָה לְנִזְרוֹ וּלְצָרַעְתּוֹ וְשֶׁמָּא מְצֹרָע וַדַּאי וּטְמֵא מֵת וַדַּאי הָיָה שֶׁהַתִּגְלַחַת הָרִאשׁוֹנָה וְהַשְּׁנִיָּה לְצָרַעְתּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וְתִגְלַחַת שְׁלִישִׁית תִּגְלַחַת טֻמְאָה וּלְפִיכָךְ צָרִיךְ לְהָבִיא קָרְבַּן טֻמְאָה בַּשְּׁלִישִׁית:","שָׁלֹשׁ עוֹלוֹת בְּהֵמָה שֶׁמֵּבִיא עִמָּהֶן עַל הָרִאשׁוֹנָה הוּא מַתְנֶה וְאוֹמֵר אִם טָהוֹר אֲנִי זוֹ מֵחוֹבָתִי וְאִם טָמֵא אֲנִי הֲרֵי הִיא נְדָבָה. וְכֵן הוּא אוֹמֵר בַּשְּׁנִיָּה וּבַשְּׁלִישִׁית:","וּמֵבִיא קָרְבַּן טָהֳרָה בְּתִגְלַחַת רְבִיעִית. וְאוֹמֵר וּמַתְנֶה אִם טָמֵא הָיִיתִי עוֹלָה רִאשׁוֹנָה נְדָבָה וְזוֹ חוֹבָה. וְאִם מֻחְלָט הָיִיתִי רִאשׁוֹנָה חוֹבַת מְצֹרָע וְזוֹ חוֹבַת נְזִירוּת וּשְׁתַּיִם הָאֶמְצָעִיּוֹת נְדָבָה. וְאִם טָהוֹר מִטֻּמְאַת מֵת הָיִיתִי וּמְצֹרָע עוֹלָה הָרִאשׁוֹנָה חוֹבָה וְכֵן הַשְּׁנִיָּה אַחַת לְחוֹבַת מְצֹרָע וְאַחַת לְחוֹבַת נְזִירוּת וּשְׁלִישִׁית וּרְבִיעִית נְדָבָה וְהַשְּׁאָר קָרְבַּן טָהֳרָתִי. וְאִם טָמֵא הָיִיתִי וּמְצֹרָע עוֹלָה רִאשׁוֹנָה חוֹבַת צָרָעַת וּשְׁנִיָּה וּשְׁלִישִׁית נְדָבָה וְזֶה קָרְבַּן תִּגְלַחַת טָהֳרָה:","אֲבָל הָאָשָׁם וְהָעוֹלָה אֵינָן מְעַכְּבִין לֹא בְּתִגְלַחַת טֻמְאָה וְלֹא בְּצָרַעַת. נִמְצֵאתָ אוֹמֵר אִם הוּא מְצֹרָע וַדַּאי וְלֹא נִטְמָא בְּמֵת הֲרֵי טָהַר בְּצִפֳּרִין וְחַטַּאת הָעוֹף הִיא חַטָּאתוֹ וְלֹא תֵּאָכֵל מִפְּנֵי שֶׁהוּא סָפֵק וְעוֹלַת בְּהֵמָה שֶׁעִמָּהּ מִקָּרְבַּן תִּגְלַחַת טָהֳרָה כְּדֵי שֶׁיְּגַלֵּחַ עַל הַבְּהֵמָה. וְאִם טְמֵא מֵת הוּא הֲרֵי עוֹלַת בְּהֵמָה נְדָבָה. וְאִם אֵינוֹ מְצֹרָע וּטְמֵא מֵת הוּא חַטַּאת הָעוֹף קָרְבַּן נָזִיר שֶׁנִּטְמָא וְעוֹלַת בְּהֵמָה נְדָבָה וַהֲרֵי הֵבִיא קָרְבַּן טָהֳרָה בָּאַחֲרוֹנָה. וְאִם אֵינוֹ טְמֵא מֵת וְלֹא מְצֹרָע עוֹלַת בְּהֵמָה שֶׁהֵבִיא בַּתִּגְלַחַת הָרִאשׁוֹנָה הִיא מֵחוֹבַת תִּגְלַחַת וְחַטַּאת הָעוֹף בָּאָה עַל סָפֵק וַהֲרֵי לֹא נֶאֱכֶלֶת:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהוּא מְגַלֵּחַ אַרְבַּע תִּגְלָחוֹת כְּשֶׁהָיָה קָטָן אוֹ אִשָּׁה. אֲבָל הָאִישׁ אֵינוֹ מְגַלֵּחַ מִסָּפֵק לֹא תִּגְלַחַת טֻמְאָה וְלֹא תִּגְלַחַת צָרָעַת. שֶׁמָּא טָהוֹר הוּא וְנִמְצָא מַקִּיף פְּאַת רֹאשׁוֹ שֶׁלֹּא בִּמְקוֹם מִצְוָה. לְפִיכָךְ אֵינוֹ מְגַלֵּחַ אֶלָּא תִּגְלַחַת טָהֳרָה בִּלְבַד. שֶׁאֵין אַרְבַּע תִּגְלָחוֹת אֵלּוּ לְעַכֵּב אֶלָּא לְמִצְוָה:","נָזִיר שֶׁנִּצְטָרֵעַ וַדַּאי וְנִטְמָא בְּסָפֵק כֵּיצַד הוּא עוֹשֶׂה. אַחַר שֶׁיִּטְהַר מִצָּרַעְתּוֹ מַזֶּה בַּשְּׁלִישִׁי וּבַשְּׁבִיעִי וּמְגַלֵּחַ תִּגְלַחַת טֻמְאָה וּמַתְחִיל לִמְנוֹת נְזִירוּתוֹ כֻּלָּהּ שֶׁהֲרֵי נָפְלוּ הַיָּמִים הָרִאשׁוֹנִים בִּסְפֵק טֻמְאָה שֶׁנִּטְמָא וּמֵבִיא קָרְבַּן טָהֳרָה וְשׁוֹתֶה בְּיַיִן. וּמֵאַחַר שֶׁיָּבִיא קָרְבַּן צָרָעַת אוֹכֵל בְּקָדָשִׁים:","נִטְמָא וַדַּאי וְהָיָה מְצֹרָע בְּסָפֵק וְטָהַר מִסְּפֵק צָרַעְתּוֹ מוֹנֶה יְמֵי נְזִירוּתוֹ שְׁלֵמָה וְאַחַר כָּךְ מְגַלֵּחַ תִּגְלַחַת הַנֶּגַע. שֶׁאֵין תִּגְלַחַת סְפֵק נִגְעוֹ דּוֹחָה נְזִירוּת. וְאַחַר כָּךְ מוֹנֶה שִׁבְעַת יָמִים שֶׁבֵּין תִּגְלַחַת מְצֹרָע הָרִאשׁוֹנָה לְתִגְלַחַת שְׁנִיָּה וּמְגַלֵּחַ וּמֵבִיא קָרְבְּנוֹתָיו וְאוֹכֵל בְּקָדָשִׁים. וּמַזֶּה בִּשְׁלִישִׁי וּשְׁבִיעִי. וְאַחַר כָּךְ מוֹנֶה שִׁבְעָה אֲחֵרִים לְטֻמְאַת מֵת וּמְגַלֵּחַ תִּגְלַחַת טֻמְאָה וְאַחַר כָּךְ מוֹנֶה נְזִירוּתוֹ כֻּלָּהּ:","וְכֵן אִם הָיָה טָמֵא וּמְצֹרָע בְּוַדַּאי. לְאַחַר שֶׁיִּטְהַר מִצָּרַעְתּוֹ מְגַלֵּחַ תִּגְלַחַת צָרָעַת הָרִאשׁוֹנָה וּמַזֶּה בַּשְּׁלִישִׁי וּבַשְּׁבִיעִי וּמְגַלֵּחַ רֹאשׁוֹ וּזְקָנוֹ בַּשְּׁבִיעִי וְהִיא תִּגְלַחַת שְׁנִיָּה שֶׁל צָרָעַת וּמֵבִיא קָרְבְּנוֹתָיו בַּשְּׁמִינִי וְאוֹכֵל בְּקָדָשִׁים וְסוֹפֵר שִׁבְעָה וּמְגַלֵּחַ תִּגְלַחַת טֻמְאָה וְאַחַר כָּךְ סוֹפֵר יְמֵי נְזִירוּת שְׁלֵמָה וּמֵבִיא קָרְבַּן טָהֳרָה וְשׁוֹתֶה בְּיַיִן:","לָמָּה סוֹפֵר שִׁבְעָה. שֶׁאֵין שִׁבְעַת יְמֵי הַטֻּמְאָה עוֹלִין בְּשִׁבְעַת יְמֵי סְפִירָה שֶׁבֵּין תִּגְלַחַת וְתִגְלַחַת שֶׁל מְצֹרָע:","הָאוֹמֵר הֲרֵינִי נָזִיר אִם אֶעֱשֶׂה כָּךְ וְכָךְ אוֹ אִם לֹא אֶעֱשֶׂה וְכַיּוֹצֵא בָּזֶה הֲרֵי זֶה רָשָׁע וּנְזִירוּת כָּזוֹ מִנְּזִירוּת רְשָׁעִים הוּא. אֲבָל הַנּוֹדֵר לַה' דֶּרֶךְ קְדֻשָּׁה הֲרֵי זֶה נָאֶה וּמְשֻׁבָּח וְעַל זֶה נֶאֱמַר (במדבר ו ז) \"נֵזֶר אֱלֹהָיו עַל רֹאשׁוֹ\" (במדבר ו ח) \"קָדשׁ הוּא לַה'\". וּשְׁקָלוֹ הַכָּתוּב כְּנָבִיא (שֶׁנֶּאֱמַר) (עמוס ב יא) \"וָאָקִים מִבְּנֵיכֶם לִנְבִיאִים וּמִבַּחוּרֵיכֶם לִנְזִרִים\": סְלִיקוּ לְהוּ הִלְכוֹת נְזִירוּת בְּסִיַעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Negative Mitzvot 101":["שלא לשחוט אותו ואת בנו, שנאמר \"אותו ואת בנו, לא תשחטו ביום אחד\" (ויקרא כב,כח)."],"Mishneh Torah, Negative Mitzvot 112":["שלא יבדיל ראש חטאת העוף, שנאמר \"ומלק את ראשו ממול עורפו [ולא יבדיל]\" (ויקרא ה,ח)."],"Mishneh Torah, Negative Mitzvot 123":["שלא להוציא מבשר הפסח מן החבורה, שנאמר \"לא תוציא מן הבית\" (שמות יב,מו)."],"Mishneh Torah, Negative Mitzvot 134":["שלא יאכל אפילו תושב כוהן ושכירו תרומה, שנאמר \"תושב כוהן ושכיר, לא יאכל קודש\" (ויקרא כב,י)."],"Mishneh Torah, Negative Mitzvot 145":["שלא יאכלו הכוהנים חטאת ואשם חוץ לעזרה, שנאמר \"לא תוכל . . . בקרך, וצאנך\" (דברים יב,יז); מפי השמועה למדו שלא בא הכתוב אלא לאסור בשר חטאות ואשמות חוץ לעזרה, לפי שכל דבר שייאכל חוץ למקום אכילתו \"לא תוכל לאכול בשעריך\" (שם) אקרא בו."],"Mishneh Torah, Negative Mitzvot 156":["שלא לעלות לחג בלא קרבן, שנאמר \"ולא ייראו פניי, ריקם\" (שמות כג,טו)."],"Mishneh Torah, Negative Mitzvot 167":["שלא ייטמא כוהן גדול ואפילו לקרוביו, שנאמר \"לאביו ולאימו, לא ייטמא\" (ויקרא כא,יא)."],"Mishneh Torah, Negative Mitzvot 178":["שלא לאכול תולעת הפירות כשתצא לאוויר, שנאמר \"לכל השרץ, השורץ על הארץ--לא תאכלום\" (ויקרא יא,מב)."],"Mishneh Torah, Negative Mitzvot 189":["שלא לאכול פת תבואה חדשה קודם הפסח, שנאמר \"ולחם . . . לא תאכלו\" (ויקרא כג,יד)."],"Mishneh Torah, Negative Mitzvot 2":["שלא לעשות פסל, לא יעשה בידו ולא יעשו לו אחרים, שנאמר \"לא תעשה לך פסל\" (שמות כ,ג; דברים ה,ז)."],"Mishneh Torah, Negative Mitzvot 21":["שלא ישתוק המוסת מללמד חובה על המסית, אם ידע לו חובה, שנאמר \"ולא תכסה עליו\" (דברים יג,ט)."],"Mishneh Torah, Negative Mitzvot 220":["שלא לעבוד אדמה בשביעית, שנאמר \"שדך לא תזרע\" (ויקרא כה,ד)."],"Mishneh Torah, Negative Mitzvot 231":["שלא יימנע מלהלוות לעני מפני השמיטה, שנאמר \"הישמר לך פן יהיה דבר\" (דברים טו,ט). .זה הכלל--כל מקום שנאמר הישמר או פן או אל, אינו אלא מצות לא תעשה."],"Mishneh Torah, Negative Mitzvot 242":["שלא לחבול כלים שעושין בהם אוכל נפש, שנאמר \"לא יחבול ריחיים, ורכב\" (דברים כד,ו)."],"Mishneh Torah, Negative Mitzvot 253":["שלא להונות את הגר במקח וממכר, שנאמר \"וְלֹא תִלְחָצֶנּוּ\" (שמות כב, כ)."],"Mishneh Torah, Negative Mitzvot 264":["שלא לכבוש אשת יפת תואר שפחה, שנאמר \"לֹא תִתְעַמֵּר בָּהּ\" (דברים כא, יד)."],"Mishneh Torah, Negative Mitzvot 275":["שלא לכבד גדול בדין, שנאמר \"וְלֹא תֶהְדַּר פְּנֵי גָּדוֹל\" (ויקרא יט, טו)."],"Mishneh Torah, Negative Mitzvot 286":["שלא יעיד בעל עבירה, שנאמר \"אַל תָּשֶׁת יָדְךָ עִם רָשָׁע לִהְיוֹת עֵד חָמָס\" (שמות כג, א)."],"Mishneh Torah, Negative Mitzvot 297":["שלא לעמוד על הדם, שנאמר \"לֹא תַעֲמֹד עַל דַּם רֵעֶךָ\" (ויקרא יט, טז)."],"Mishneh Torah, Negative Mitzvot 307":["שלא לגלח שיער הנתק, שנאמר \"ואת הנתק, לא יגלח\" (ויקרא יג,לג)."],"Mishneh Torah, Negative Mitzvot 318":["שלא לקלל אב ואם, שנאמר \"ומקלל אביו ואימו, מות יומת\" (שמות כא,יז)."],"Mishneh Torah, Negative Mitzvot 329":["שלא לעשות מלאכה ביום שמיני של חג, שנאמר בו \"כל מלאכת עבודה, לא תעשו\" (ויקרא כג,לו; במדבר כט,לה)."],"Mishneh Torah, Negative Mitzvot 34":["שלא לכשף, שנאמר \"לא יימצא בך . . . ומכשף\" (דברים יח,י)."],"Mishneh Torah, Negative Mitzvot 350":["שלא לשכב עם זכר, שנאמר \"ואת זכר--לא תשכב\" (ויקרא יח,כב)."],"Mishneh Torah, Negative Mitzvot 361":["שלא לסרס זכר מכל המינין, לא אדם ולא בהמה חיה ועוף, שנאמר \"ובארצכם, לא תעשו\" (ויקרא כב,כד)."],"Mishneh Torah, Negative Mitzvot 43":["שלא להקיף פיאת ראש ככומרי עבודה זרה, שנאמר \"ולא תקיפו, פאת ראשכם\" (ראה ויקרא יט,כז)."],"Mishneh Torah, Negative Mitzvot 54":["שלא להרחיק זרע עשיו מן הקהל אלא עד שלושה דורות, שנאמר \"לא תתעב אדומי\" (דברים כג,ח)."],"Mishneh Torah, Negative Mitzvot 65":["שלא לאבד בית המקדש, או בתי כנסייות, או בתי מדרשות; וכן אין מוחקין את השמות המוקדשין, ואין מאבדין כתבי הקודש, שנאמר \"אַבֵּד תְּאַבְּדוּן\" (דברים יב, ב), \"לֹא תַעֲשׂוּן כֵּן לַה' אֱלֹהֵיכֶם\" (שם, ד)."],"Mishneh Torah, Negative Mitzvot 76":["שלא יעבוד כהן טבול יום עד שיעריב שמשו, שנאמר \"וְלֹא יְחַלְּלוּ\" (ויקרא כא, ו)."],"Mishneh Torah, Negative Mitzvot 87":["שלא ייזח החושן מעל האיפוד, שנאמר \"ולא ייזח החושן, מעל האיפוד\" (שמות כח,כח; שמות לט,כא)."],"Mishneh Torah, Negative Mitzvot 98":["שלא להקריב שאור או דבש, שנאמר (ויקרא ב, יא): \"כִּי כָל שְׂאוֹר וְכָל דְבַשׁ, לֹא תַקְטִירוּ\"."],"Mishneh Torah, Neighbors 6":["כּוֹפִין בְּנֵי הָעִיר זֶה אֶת זֶה לַעֲשׂוֹת חוֹמָה דְּלָתַיִם וּבָרִיחַ לָעִיר וְלִבְנוֹת לָהֶן בֵּית הַכְּנֶסֶת וְלִקְנוֹת סֵפֶר תּוֹרָה וּנְבִיאִים וּכְתוּבִים כְּדֵי שֶׁיִּקְרָא בָּהֶן כָּל מִי שֶׁיִּרְצֶה לִקְרוֹת מִן הַצִּבּוּר:","מִי שֶׁלָּקַח עִיר בְּאֶרֶץ יִשְׂרָאֵל כּוֹפִין אוֹתוֹ בֵּית דִּין לִקַּח לוֹ דֶּרֶךְ מֵאַרְבַּע רוּחוֹתֶיהָ מִשּׁוּם יִשּׁוּב אֶרֶץ יִשְׂרָאֵל. וְכוֹפִין בְּנֵי בִּקְעָה זֶה אֶת זֶה לַעֲשׂוֹת בֵּינֵיהֶם חָרִיץ וּבֶן חָרִיץ:","מִי שֶׁיֵּשׁ לוֹ חָצֵר בְּעִיר אַחֶרֶת בְּנֵי הָעִיר מְשַׁעְבְּדִין אוֹתוֹ לַחְפֹּר עִמָּהֶם בּוֹרוֹת שִׁיחִין וּמְעָרוֹת וְאַמַּת הַמַּיִם. אֲבָל בִּשְׁאָר כָּל הַדְּבָרִים אֵין מְשַׁעְבְּדִין אוֹתוֹ. וְאִם הָיָה שָׁרוּי עִמָּהֶם בְּאוֹתָהּ הָעִיר מְשַׁעְבְּדִין אוֹתוֹ עַל הַכּל:","כְּשֶׁהֵן גּוֹבִין מֵאַנְשֵׁי הָעִיר לִבְנוֹת הַחוֹמָה גּוֹבִין לְפִי קְרִיבַת הַבָּתִּים מִן הַחוֹמָה כָּל הַסָּמוּךְ לַחוֹמָה נוֹתֵן יוֹתֵר:","וְכָל הַדָּר בְּעִיר שְׁנֵים עָשָׂר חֹדֶשׁ אוֹ שֶׁקָּנָה בָּהּ בֵּית דִּירָה נוֹתֵן עִם בְּנֵי הָעִיר בְּכָל הַדְּבָרִים הַצְּרִיכִין לְתִקּוּן הַחוֹמָה וְהַדְּלָתוֹת וּשְׂכַר הַפָּרָשִׁין הַשּׁוֹמְרִין אֶת הַמְּדִינָה. וְכָל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ שֶׁשּׁוֹמְרִין אֶת הָעִיר:","כָּל הַדְּבָרִים שֶׁצְּרִיכִין לִשְׁמִירַת הָעִיר לוֹקְחִין מִכָּל אַנְשֵׁי הָעִיר וַאֲפִלּוּ מִן הַיְתוֹמִים חוּץ מִתַּלְמִידֵי חֲכָמִים. שֶׁאֵין תַּלְמִידֵי חֲכָמִים צְרִיכִין שְׁמִירָה שֶׁהַתּוֹרָה שׁוֹמַרְתָּן. אֲבָל לְתִקּוּן הַדְּרָכִים וְהָרְחוֹבוֹת אֲפִלּוּ מִן הַחֲכָמִים. וְאִם כָּל הָעָם יוֹצְאִין וּמְתַקְּנִין בְּעַצְמָן לֹא יֵצְאוּ תַּלְמִידֵי חֲכָמִים עִמָּהֶן שֶׁאֵין דֶּרֶךְ תַּלְמִידֵי חֲכָמִים לְהִזְדַּלְזֵל לִפְנֵי עַם הָאָרֶץ:","הָיוּ חוֹפְרִין נָהָר לְהָבִיא בּוֹ מַיִם לַמְּדִינָה גּוֹבִין אַף מִן הַיְתוֹמִים שֶׁזּוֹ זְכוּת לָהֶם כְּדֵי שֶׁיַּשְׁקוּ מִמֶּנּוּ שְׂדוֹתֵיהֶם וְכַרְמֵיהֶם. לְפִיכָךְ אִם אֵרַע לָהֶם דָּבָר שֶׁלֹּא בָּאוּ הַמַּיִם הוֹאִיל וְלֹא נֶהֱנוּ מֵהֶן הַיְתוֹמִים מַחֲזִירִין לָהֶם כָּל מַה שֶּׁנִּלְקַח מֵהֶן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כּוֹפִין בְּנֵי מָבוֹי זֶה אֶת זֶה שֶׁלֹּא לְהוֹשִׁיב בֵּינֵיהֶן לֹא חַיָּט וְלֹא בּוּרְסִי וְלֹא אֶחָד מִבַּעֲלֵי אֻמָּנֻיּוֹת. הָיָה שָׁם בַּמָּבוֹי אֶחָד מִבְּנֵי מָבוֹי אֻמָּן וְלֹא מִחוּ בּוֹ. אוֹ שֶׁהָיְתָה שָׁם מֶרְחָץ אוֹ חֲנוּת אוֹ רֵחַיִם וּבָא חֲבֵרוֹ וְעָשָׂה מֶרְחָץ אַחֶרֶת כְּנֶגְדּוֹ אוֹ טָחוֹן אַחֶרֶת. אֵינוֹ יָכוֹל לְמָנְעוֹ וְלוֹמַר לוֹ אַתָּה פּוֹסֵק חַיַּי. וַאֲפִלּוּ הָיָה מִבְּנֵי מָבוֹי אַחֵר אֵינָן יְכוֹלִין לְמָנְעוֹ שֶׁהֲרֵי יֵשׁ בֵּינֵיהֶם אוֹתָהּ אֻמָּנוּת. אֲבָל גֵּר מִמְּדִינָה אַחֶרֶת שֶׁבָּא לַעֲשׂוֹת חֲנוּת בְּצַד חֲנוּתוֹ שֶׁל זֶה. אוֹ מֶרְחָץ מִצַּד מֶרְחָץ שֶׁל זֶה. יֵשׁ לָהֶן לְמָנְעוֹ. וְאִם הָיָה נוֹתֵן עִמָּהֶם מְנַת הַמֶּלֶךְ אֵינוֹ יָכוֹל לְמָנְעוֹ:","רוֹכְלִין הַמַּחְזִירִין בַּעֲיָרוֹת אֵין בְּנֵי הַמְּדִינָה יְכוֹלִין לְעַכְּבָן שֶׁתַּקָּנַת עֶזְרָא הִיא שֶׁיִּהְיוּ מַחֲזִירִין כְּדֵי שֶׁיִּהְיוּ הַבְּשָׂמִים מְצוּיִין לִבְנוֹת יִשְׂרָאֵל. אֲבָל אֵינָן קוֹבְעִין מָקוֹם וְיוֹשְׁבִין בּוֹ אֶלָּא מִדַּעַת בְּנֵי הָעִיר. וְאִם תַּלְמִיד חָכָם הוּא קוֹבֵעַ מָקוֹם בְּכָל מָקוֹם שֶׁיִּרְצֶה:","הַסּוֹחֲרִים שֶׁמְּבִיאִין סְחוֹרָתָם לִמְכֹּר בְּתוֹךְ הָעֲיָרוֹת בְּנֵי הָעִיר מְעַכְּבִין עֲלֵיהֶם. וְאִם מָכְרוּ בְּיוֹם הַשּׁוּק בִּלְבַד אֵין מוֹנְעִין אוֹתָם. וְהוּא שֶׁיִּמְכְּרוּ בַּשּׁוּק אֲבָל לֹא יְחַזְּרוּ עַל הַפְּתָחִים אֲפִלּוּ בְּיוֹם הַשּׁוּק. וְאִם יֵשׁ לָהֶן מִלְוֶה בָּעִיר מוֹכְרִין כְּדֵי פַּרְנָסָתָם אֲפִלּוּ בְּלֹא יוֹם הַשּׁוּק עַד שֶׁיִּפְרְעוּ חוֹבָן וְיֵלְכוּ לָהֶן:","אֶחָד מִבְּנֵי מָבוֹי שֶׁאֵינוֹ מְפֻלָּשׁ שֶׁבִּקֵּשׁ לְהֵעָשׂוֹת רוֹפֵא אֻמָּן אוֹ גַּרְדִּי אוֹ מְלַמֵּד תִּינוֹקוֹת שֶׁל עַכּוּ\"ם בְּנֵי מָבוֹי מְעַכְּבִין עָלָיו מִפְּנֵי שֶׁמַּרְבֶּה עֲלֵיהֶם הַנִּכְנָסִין וְהַיּוֹצְאִין. וְכֵן מִי שֶׁיֵּשׁ לוֹ בַּיִת בַּחֲצַר הַשֻּׁתָּפִין לֹא יַשְׂכִּירֶנּוּ לֹא לְרוֹפֵא וְלֹא לְאֻמָּן וְלֹא לְגַרְדִּי וְלֹא לְסוֹפֵר יְהוּדִי שֶׁכּוֹתֵב הַשְּׁטָרוֹת וְלֹא לִמְלַמְּדֵי תִּינוֹקוֹת שֶׁל עַכּוּ\"ם:","חֲנוּת שֶׁבֶּחָצֵר יְכוֹלִין הַשְּׁכֵנִים לִמְחוֹת בְּיָדוֹ וְלוֹמַר לוֹ אֵין אָנוּ יְכוֹלִין לִישֹׁן מִקּוֹל הַנִּכְנָסִים וְהַיּוֹצְאִין אֶלָּא עוֹשֶׂה מְלַאכְתּוֹ בַּחֲנוּתוֹ וּמוֹכֵר בַּשּׁוּק. אֲבָל אֵינָן יְכוֹלִין לִמְחוֹת בְּיָדוֹ וְלוֹמַר לוֹ אֵין אָנוּ יְכוֹלִין לִישֹׁן מִקּוֹל הַפַּטִּישׁ אוֹ מִקּוֹל הָרֵחָיִם שֶׁהֲרֵי הֶחֱזִיק לַעֲשׂוֹת כֵּן. וְכֵן יֵשׁ לוֹ לְלַמֵּד תִּינוֹקוֹת שֶׁל יִשְׂרָאֵל תּוֹרָה בְּתוֹךְ בֵּיתוֹ וְאֵין הַשֻּׁתָּפִין יְכוֹלִין לִמְחוֹת בְּיָדוֹ וְלוֹמַר לוֹ אֵין אָנוּ יְכוֹלִין לִישֹׁן מִקּוֹל הַתִּינוֹקוֹת שֶׁל בֵּית רַבָּן:","מִי שֶׁיֵּשׁ לוֹ בּוֹר לְפָנִים מִבֵּיתוֹ שֶׁל חֲבֵרוֹ נִכְנָס בְּשָׁעָה שֶׁדֶּרֶךְ בְּנֵי אָדָם נִכְנָסִין וְיוֹצֵא בְּשָׁעָה שֶׁדֶּרֶךְ בְּנֵי אָדָם יוֹצְאִין. וְאֵינוֹ מַכְנִיס בְּהֶמְתּוֹ וּמַשְׁקֶה מִבּוֹרוֹ אֶלָּא מְמַלֵּא וּמַשְׁקֶה מִבַּחוּץ. וּשְׁנֵיהֶם עוֹשִׂין פּוֹתַחַת עַל הַבּוֹר. בַּעַל הַבּוֹר כְּדֵי לִשְׁמֹר אֶת מֵימָיו. וּבַעַל חָצֵר מִשּׁוּם חֲשַׁד אִשְׁתּוֹ שֶׁלֹּא תִּכָּנֵס לְשָׁם אֶלָּא מִדַּעְתּוֹ:","מִי שֶׁיֵּשׁ לוֹ גִּנָּה לְפָנִים מִגִּנָּתוֹ שֶׁל חֲבֵרוֹ נִכְנָס בְּשָׁעָה שֶׁדֶּרֶךְ בְּנֵי אָדָם נִכְנָסִין וְיוֹצֵא בְּשָׁעָה שֶׁדֶּרֶךְ בְּנֵי אָדָם יוֹצְאִין. וְאֵין מַכְנִיס לְתוֹכָהּ תַּגָּרִים וְלֹא יִכָּנֵס מִתּוֹכָהּ לְשָׂדֶה אַחֶרֶת. וְהַחִיצוֹן זוֹרֵעַ אֶת הַדֶּרֶךְ. הֶחְזִירוּ אֶת הַדֶּרֶךְ מִן הַצַּד מִדַּעַת שְׁנֵיהֶם הֲרֵי זֶה נִכְנָס וְיוֹצֵא בְּשָׁעָה שֶׁהוּא רוֹצֶה. וּמַכְנִיס לְתוֹכָהּ תַּגָּרִים. וְלֹא יִכָּנֵס מִתּוֹכָהּ לְשָׂדֶה אַחֶרֶת. וְכָל אֶחָד מֵהֶן יֵשׁ לוֹ לְעַכֵּב עַל חֲבֵרוֹ בִּזְרִיעַת הַדֶּרֶךְ שֶׁנָּתְנוּ מִן הַצַּד:"],"Mishneh Torah, Oaths 6":["מִי שֶׁנִּשְׁבַּע שְׁבוּעַת בִּטּוּי וְנִחַם עַל שְׁבוּעָתוֹ וְרָאָה שֶׁהוּא מִצְטַעֵר אִם יְקַיֵּם שְׁבוּעָה זוֹ וְנֶהְפְּכָה דַּעְתּוֹ לְדַעַת אַחֶרֶת. אוֹ שֶׁנּוֹלַד לוֹ דָּבָר שֶׁלֹּא הָיָה בְּדַעְתּוֹ בִּשְׁעַת הַשְּׁבוּעָה וְנִחַם בִּגְלָלוֹ. הֲרֵי זֶה נִשְׁאַל לְחָכָם אֶחָד אוֹ לִשְׁלֹשָׁה הֶדְיוֹטוֹת בְּמָקוֹם שֶׁאֵין שָׁם חָכָם וּמַתִּירִין לוֹ שְׁבוּעָתוֹ. וְיִהְיֶה מֻתָּר לַעֲשׂוֹת דָּבָר שֶׁנִּשְׁבַּע שֶׁלֹּא לַעֲשׂוֹתוֹ. אוֹ שֶׁלֹּא לַעֲשׂוֹת דָּבָר שֶׁנִּשְׁבַּע לַעֲשׂוֹתוֹ. וְזֶהוּ הַנִּקְרָא הֶתֵּר שְׁבוּעוֹת:","וְדָבָר זֶה אֵין לוֹ עִקָּר כְּלָל בַּתּוֹרָה שֶׁבִּכְתָב. אֶלָּא כָּךְ לָמְדוּ מִמּשֶׁה רַבֵּנוּ מִפִּי הַקַּבָּלָה שֶׁזֶּה הַכָּתוּב (במדבר ל ג) \"לֹא יַחֵל דְּבָרוֹ\" שֶׁלֹּא יְחַלֵּל הוּא בְּעַצְמוֹ דֶּרֶךְ קַלּוּת רֹאשׁ בִּשְׁאָט נֶפֶשׁ כָּעִנְיָן שֶׁנֶּאֱמַר (ויקרא יט יב) \"וְחִלַּלְתָּ אֶת שֵׁם אֱלֹהֶיךָ\". אֲבָל אִם נִחַם וְחָזַר בּוֹ חָכָם מַתִּיר לוֹ:","וְאֵין אָדָם יָכוֹל לְהַתִּיר שְׁבוּעַת עַצְמוֹ. וְאֵין אָדָם רַשַּׁאי לְהַתִּיר שְׁבוּעָה אוֹ נֵדֶר בְּמָקוֹם שֶׁיֵּשׁ גָּדוֹל מִמֶּנּוּ בְּחָכְמָה. וּבְמָקוֹם שֶׁיֵּשׁ בּוֹ רַבּוֹ אָסוּר לוֹ לְהַתִּיר אֶלָּא מִדַּעַת רַבּוֹ:","זֶה שֶׁנִּשְׁבַּע הוּא שֶׁיָּבוֹא לִפְנֵי הֶחָכָם לְהַתִּיר לוֹ בֵּין אִישׁ בֵּין אִשָּׁה. וְאֵינוֹ עוֹשֶׂה שָׁלִיחַ לְהִשָּׁאֵל לוֹ עַל נִדְרוֹ. וְהַבַּעַל נַעֲשֶׂה שָׁלִיחַ לַחֲרָטַת אִשְׁתּוֹ וּמַתִּירִין לָהּ וּבִלְבַד שֶׁיִּהְיוּ הַשְּׁלֹשָׁה מְקֻבָּצִים אֲבָל לֹא יְקַבֵּץ אוֹתָן לְהַתִּיר לָהּ לְכַתְּחִלָּה. וְאֵינוֹ נַעֲשֶׂה שָׁלִיחַ לְהַתִּיר נֵדֶר לְאִשְׁתּוֹ:","כֵּיצַד מַתִּירִין. יָבוֹא הַנִּשְׁבָּע לְחָכָם הַמֻּבְהָק אוֹ לִשְׁלֹשָׁה הֶדְיוֹטוֹת אִם אֵין שָׁם מֻמְחֶה. וְאוֹמֵר אֲנִי נִשְׁבַּעְתִּי עַל כָּךְ וְכָךְ וְנִחַמְתִּי. וְאִלּוּ הָיִיתִי יוֹדֵעַ שֶׁאֲנִי מִצְטַעֵר בְּדָבָר זֶה עַד כֹּה אוֹ שֶׁאֵרַע לִי כָּךְ וְכָךְ לֹא הָיִיתִי נִשְׁבַּע וְאִלּוּ הָיְתָה דַּעְתִּי בְּעֵת הַשְּׁבוּעָה כְּמוֹ עַתָּה לֹא הָיִיתִי נִשְׁבַּע. וְהֶחָכָם אוֹ גְּדוֹל הַשְּׁלֹשָׁה אוֹמֵר לוֹ וּכְבָר נִחַמְתָּ. וְהוּא אוֹמֵר לוֹ הֵן. חוֹזֵר וְאוֹמֵר לוֹ שָׁרוּי לְךָ אוֹ מֻתָּר לְךָ אוֹ מָחוּל לְךָ וְכָל כַּיּוֹצֵא בְּעִנְיָן זֶה בְּכָל לָשׁוֹן. אֲבָל אִם אָמַר לוֹ מוּפָר לְךָ אוֹ נֶעֶקְרָה שְׁבוּעָתְךָ וְכָל כַּיּוֹצֵא בְּעִנְיָן זֶה לֹא אָמַר כְּלוּם. שֶׁאֵין מֵפֵר אֶלָּא הַבַּעַל אוֹ הָאָב אֲבָל הֶחָכָם אֵינוֹ אוֹמֵר אֶלָּא לְשׁוֹן הַתָּרָה וּמְחִילָה:","הַקְּרוֹבִים כְּשֵׁרִים לְהַתִּיר נְדָרִים וּשְׁבוּעוֹת. וּמַתִּירִין בַּלַּיְלָה וּמְעֻמָּד. שֶׁאֵין הַהֶתֵּר הַזֶּה דִּין. לְפִיכָךְ נִשְׁאָלִין לִשְׁבוּעוֹת וְלִנְדָרִים בְּשַׁבָּת אִם הָיוּ לְצֹרֶךְ הַשַּׁבָּת. כְּגוֹן שֶׁיַּתִּירוּ לוֹ שְׁבוּעָתוֹ כְּדֵי שֶׁיֹּאכַל וְיִשְׁתֶּה הַיּוֹם. וַאֲפִלּוּ הָיָה לוֹ פְּנַאי לְהַתִּיר שְׁבוּעָתוֹ אוֹ נִדְרוֹ מֵעֶרֶב שַׁבָּת הֲרֵי זֶה מַתִּיר בְּשַׁבָּת הוֹאִיל וְהוּא לְצֹרֶךְ הַשַּׁבָּת:","רְאוּבֵן שֶׁהִשְׁבִּיעַ לְשִׁמְעוֹן וְעָנָה אָמֵן. אוֹ קִבֵּל הַשְּׁבוּעָה וְנִחַם שִׁמְעוֹן עַל שְׁבוּעָתוֹ וְנִשְׁאַל עָלֶיהָ. אֵין מַתִּירִין לוֹ אֶלָּא בִּפְנֵי רְאוּבֵן שֶׁהִשְׁבִּיעוֹ. וְכֵן אִם נִשְׁבַּע רְאוּבֵן אוֹ נָדַר שֶׁלֹּא יֵהָנֶה מִשִּׁמְעוֹן אוֹ שֶׁלֹּא יֵהָנֶה בּוֹ שִׁמְעוֹן וְנִחַם וְנִשְׁאַל לְחָכָם אֵין מַתִּירִין לוֹ אֶלָּא בִּפְנֵי שִׁמְעוֹן שֶׁנָּדַר מִמֶּנּוּ הֲנָיָה. וַאֲפִלּוּ הָיָה שִׁמְעוֹן קָטָן אוֹ עַכּוּ\"ם אֵין מַתִּירִין לוֹ אֶלָּא בְּפָנָיו כְּדֵי שֶׁיֵּדַע הַנִּדָּר שֶׁהִתִּיר זֶה נִדְרוֹ אוֹ שְׁבוּעָתוֹ וּלְפִיכָךְ יֵהָנֶה מִמֶּנּוּ אוֹ יַהֲנֶה לוֹ:","אֶחָד הַנִּשְׁבָּע בֵּינוֹ לְבֵין עַצְמוֹ וְאֶחָד הַנִּשְׁבָּע בָּרַבִּים. וַאֲפִלּוּ נִשְׁבַּע בַּשֵּׁם הַמְיֻחָד בַּה' אֱלֹהֵי יִשְׂרָאֵל וְנִחַם הֲרֵי זֶה נִשְׁאָל עַל שְׁבוּעָתוֹ וּמַתִּירִין לוֹ. נִשְׁבַּע עַל דַּעַת רַבִּים אוֹ שֶׁנָּדַר עַל דַּעַת רַבִּים אֵין מַתִּירִין לוֹ לְעוֹלָם אֶלָּא לִדְבַר מִצְוָה:","כֵּיצַד. נִשְׁבַּע וְתָלָה שְׁבוּעָתוֹ בְּדַעַת רַבִּים שֶׁלֹּא יֵהָנֶה בִּפְלוֹנִי לְעוֹלָם וְהֻצְרְכוּ בְּנֵי אוֹתָהּ הָעִיר לִלְמֹד תּוֹרָה אוֹ לְמִי שֶׁיָּמוּל אֶת בְּנֵיהֶם אוֹ שֶׁיִּזְבַּח לָהֶם וְלֹא נִמְצָא אֶלָּא זֶה בִּלְבַד הֲרֵי זֶה נִשְׁאַל לְחָכָם אוֹ לִשְׁלֹשָׁה הֶדְיוֹטוֹת וּמַתִּירִין לוֹ שְׁבוּעָתוֹ וְעוֹשֶׂה לָהֶם מִצְוֹת אֵלּוּ וְנוֹטֵל שְׂכָרוֹ מֵאוֹתָן הָאֲנָשִׁים שֶׁנִּשְׁבַּע שֶׁלֹּא יֵהָנֶה מֵהֶם:","מִי שֶׁנִּשְׁבַּע וְלֹא נִחַם עַל שְׁבוּעָתוֹ וּבָא לְבֵית דִּין לְקַיֵּם שְׁבוּעָתוֹ. אִם רָאוּ הַדַּיָּנִין שֶׁהֶתֵּר שְׁבוּעָה זוֹ גּוֹרֵם לְמִצְוָה וּלְשָׁלוֹם בֵּין אִישׁ לְאִשְׁתּוֹ בֵּין אָדָם לַחֲבֵרוֹ וְשֶׁקִּיּוּם שְׁבוּעָה זוֹ גּוֹרֵם לַעֲבֵרָה וְלִקְטָטָה פּוֹתְחִין לוֹ פֶּתַח וְנוֹשְׂאִין וְנוֹתְנִין עִמּוֹ בַּדָּבָר וּמוֹדִיעִין לוֹ דְּבָרִים שֶׁגּוֹרֶמֶת שְׁבוּעָתוֹ עַד שֶׁיִּתְנַחֵם. אִם נִחַם בְּדִבְרֵיהֶם מַתִּירִין לוֹ וְאִם לֹא נִחַם וְעָמַד בְּמִרְיוֹ הֲרֵי זֶה יְקַיֵּם שְׁבוּעָתוֹ:","כֵּיצַד. נִשְׁבַּע שֶׁיְּגָרֵשׁ אֶת אִשְׁתּוֹ אוֹ שֶׁלֹּא יֵהָנֶה יִשְׂרָאֵל מִנְּכָסָיו אוֹ שֶׁלֹּא יֹאכַל בָּשָׂר וְשֶׁלֹּא יִשְׁתֶּה יַיִן שְׁלֹשִׁים יוֹם וְכַיּוֹצֵא בָּזֶה אוֹמְרִים לוֹ בְּנִי אִם תְּגָרֵשׁ אֶת אִשְׁתְּךָ אַתָּה מוֹצִיא לַעַז עַל בָּנֶיךָ וְאוֹמְרִים הָעָם מִפְּנֵי מָה נִתְגָּרְשָׁה אִמָּן שֶׁל אֵלּוּ וּלְמָחָר קוֹרְאִים לָהֶם בְּנֵי גְּרוּשָׁה וְשֶׁמָּא תִּנָּשֵׂא לְאַחֵר וְאִי אַתָּה יָכוֹל לְהַחְזִירָהּ וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. וְכֵן זֶה שֶׁנִּשְׁבַּעְתָּ שֶׁלֹּא יֵהָנֶה יִשְׂרָאֵל מִנְּכָסֶיךָ לְמָחָר יִצְטָרֵךְ זֶה וְתִהְיֶה עוֹבֵר עַל (ויקרא כה לו) \"וְחֵי אָחִיךָ עִמָּךְ\" (ויקרא כה לה) \"וְהֶחֱזַקְתָּ בּוֹ\" אוֹ (דברים טו ח) (דברים טו יא) \"פָּתֹחַ תִּפְתַּח\" וְכַיּוֹצֵא בָּהֶן. וְזֶה שֶׁנִּשְׁבַּעְתָּ שֶׁלֹּא תֹּאכַל בָּשָׂר וְשֶׁלֹּא תִּשְׁתֶּה יַיִן שְׁלֹשִׁים יוֹם הֲרֵי אַתָּה פּוֹגֵעַ בָּרֶגֶל וּמְבַטֵּל שִׂמְחַת יוֹם טוֹב וְעֹנֶג שַׁבָּת. אִם אָמַר אִלּוּ הָיִיתִי יוֹדֵעַ זֶה לֹא הָיִיתִי נִשְׁבַּע מַתִּירִין לוֹ וְאִם אָמַר אַף עַל פִּי כֵן לֹא נִחַמְתִּי וְרוֹצֶה אֲנִי בְּכָל זֶה אֵין מַתִּירִין לוֹ:","אֵין פּוֹתְחִין בְּנוֹלָד. כֵּיצַד. נִשְׁבַּע שֶׁלֹּא יֵהָנֶה בִּפְלוֹנִי וְנַעֲשָׂה סוֹפֵר הָעִיר. הוֹאִיל וְלֹא נִחַם עַל שְׁבוּעָתוֹ אֵין פּוֹתְחִין לוֹ בְּדָבָר זֶה. וַאֲפִלּוּ אָמַר הוּא מֵעַצְמוֹ אִלּוּ הָיִיתִי יוֹדֵעַ לֹא הָיִיתִי נִשְׁבַּע אֵין מַתִּירִין לוֹ הוֹאִיל וַעֲדַיִן לֹא נִחַם אֶלָּא רְצוֹנוֹ שֶׁלֹּא יֵהָנֶה לוֹ וְשֶׁלֹּא יֵעָשֶׂה זֶה סוֹפֵר. אֲבָל אִם נִחַם הוּא מֵעַצְמוֹ מִפְּנֵי הַנּוֹלָד וְנֶהֶפְכָה דַּעְתּוֹ מַתִּירִין לוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁנִּשְׁבַּע עַל דָּבָר וְנִשְׁבַּע שֶׁלֹּא יַתִּיר שְׁבוּעָה זוֹ וְנִחַם. הֲרֵי זֶה נִשְׁאַל עַל הַשְּׁבוּעָה הָאַחֲרוֹנָה תְּחִלָּה שֶׁנִּשְׁבַּע שֶׁלֹּא יַתִּיר וְאַחַר כָּךְ יִשְׁאַל עַל הָרִאשׁוֹנָה:","נִשְׁבַּע שֶׁלֹּא יְדַבֵּר עִם פְּלוֹנִי וְנִשְׁבַּע אַחַר כָּךְ שֶׁאִם יִשְׁאַל עַל שְׁבוּעָה זוֹ וְיַתִּירָהּ יִהְיֶה אָסוּר לִשְׁתּוֹת יַיִן לְעוֹלָם וְנִחַם. הֲרֵי זֶה נִשְׁאָל עַל הַשְּׁבוּעָה הָרִאשׁוֹנָה וּמַתִּירָהּ. וְאַחַר כָּךְ יִשְׁאַל עַל הַשְּׁנִיָּה. שֶׁאֵין מַתִּירִין נֵדֶר אוֹ שְׁבוּעָה שֶׁעֲדַיִן לֹא חָלוּ. לְפִיכָךְ אִם הָיָה עוֹמֵד בְּנִיסָן וְנִשְׁבַּע שֶׁלֹּא יֹאכַל בָּשָׂר שְׁלֹשִׁים יוֹם מֵרֹאשׁ חֹדֶשׁ אִיָּר וְנִחַם אֵינוֹ נִשְׁאָל עַד שֶׁיִּכָּנֵס אִיָּר:","נִשְׁבַּע שֶׁלֹּא יֵהָנֶה לִפְלוֹנִי וְשֶׁלֹּא יֵהָנֶה לְחָכָם שֶׁיִּשְׁאַל לוֹ עַל שְׁבוּעָה זוֹ. נִשְׁאַל עַל הָרִאשׁוֹנָה וְאַחַר כָּךְ יִשְׁאַל עַל הַשְּׁנִיָּה:","נִשְׁבַּע שֶׁלֹּא יֵהָנֶה לִפְלוֹנִי וַהֲרֵי הוּא נָזִיר אִם יִשְׁאַל עַל שְׁבוּעָה זוֹ. יִשְׁאַל עַל שְׁבוּעָתוֹ תְּחִלָּה וְאַחַר כָּךְ עַל נְזִירוּתוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שְׁבוּעָה שֶׁלֹּא אֹכַל הַיּוֹם שְׁבוּעָה שֶׁלֹּא אֹכַל הַיּוֹם שְׁבוּעָה שֶׁלֹּא אֹכַל הַיּוֹם. אוֹ שֶׁאָמַר עַל כִּכָּר זוֹ שְׁבוּעָה שֶׁלֹּא אֹכָלֶנָּה שְׁבוּעָה שֶׁלֹּא אֹכָלֶנָּה שְׁבוּעָה שֶׁלֹּא אֹכָלֶנָּה. וְנִשְׁאַל עַל שְׁבוּעָה רִאשׁוֹנָה וְהֻתְּרָה הֲרֵי זֶה חַיָּב מִשּׁוּם שְׁבוּעָה שְׁנִיָּה. וְכֵן אִם נִשְׁאַל עַל הַשְּׁנִיָּה חַיָּב מִשּׁוּם שְׁלִישִׁית. נִשְׁאַל עַל הַשְּׁלִישִׁית בִּלְבַד חַיָּב מִשּׁוּם רִאשׁוֹנָה וּשְׁנִיָּה. נִשְׁאַל עַל הַשְּׁנִיָּה חַיָּב מִשּׁוּם רִאשׁוֹנָה [וּשְׁלִישִׁית]. אִם כֵּן מִפְּנֵי מָה אָמְרוּ אֵין שְׁבוּעָה חָלָה עַל שְׁבוּעָה. שֶׁאִם לֹא נִשְׁאַל וַאֲכָלָהּ אֵינוֹ חַיָּב אֶלָּא אַחַת כְּמוֹ שֶׁבֵּאַרְנוּ:","מִי שֶׁנִּשְׁבַּע שְׁבוּעַת בִּטּוּי לְהַבָּא וְשִׁקֵּר בִּשְׁבוּעָתוֹ. כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא יֹאכַל פַּת זוֹ וַאֲכָלָהּ וְאַחַר שֶׁאֲכָלָהּ קֹדֶם שֶׁיָּבִיא קָרְבָּנוֹ אִם הָיָה שׁוֹגֵג אוֹ קֹדֶם שֶׁיִּלְקֶה אִם הָיָה מֵזִיד נִחַם וְנִשְׁאַל לְחָכָם וְהִתִּירָהּ לוֹ. הֲרֵי זֶה פָּטוּר מִן הַקָּרְבָּן אוֹ מִן הַמַּלְקוֹת. וְלֹא עוֹד אֶלָּא אֲפִלּוּ כְּפָתוּהוּ לִלְקוֹת וְנִשְׁאַל וְהִתִּירוּ לוֹ קֹדֶם שֶׁיַּתְחִילוּ לְהַלְקוֹתוֹ הֲרֵי זֶה פָּטוּר:"],"Mishneh Torah, Offerings for Unintentional Transgressions 12":["כָּל דָּבָר שֶׁחַיָּבִין עַל שִׁגְגָתוֹ חַטָּאת קְבוּעָה אִם שָׁגְגוּ בֵּית דִּין הַגָּדוֹל בְּהוֹרָאָה וְהוֹרוּ לְהַתִּירוֹ וְשָׁגְגוּ הָעָם בְּהוֹרָאָתָן וְעָשׂוּ הָעָם וְהֵם סוֹמְכִין עַל הוֹרָאָתָן וְאַחַר כָּךְ נוֹדַע לְבֵית דִּין שֶׁטָּעוּ הֲרֵי בֵּית דִּין חַיָּבִין לְהָבִיא קָרְבַּן חַטָּאת עַל שִׁגְגָתָן בְּהוֹרָאָה וְאַף עַל פִּי שֶׁלֹּא עָשׂוּ הֵן בְּעַצְמָן מַעֲשֶׂה שֶׁאֵין מַשְׁגִּיחִין עַל עֲשִׂיַּת בֵּית דִּין כְּלָל בֵּין עָשׂוּ בֵּין לֹא עָשׂוּ אֶלָּא עַל הוֹרָאָתָן בִּלְבַד. וּשְׁאָר הָעָם פְּטוּרִין מִן הַקָּרְבָּן וְאַף עַל פִּי שֶׁהֵם הָעוֹשִׂין מִפְּנֵי שֶׁתָּלוּ בְּבֵית דִּין. וּמַה הוּא הַקָּרְבָּן שֶׁמְּבִיאִין עַל שְׁגָגָה זוֹ. אִם בַּעֲבוֹדָה זָרָה שָׁגְגוּ וְהוֹרוּ מְבִיאִין פַּר לְעוֹלָה וְשָׂעִיר לְחַטָּאת מִכָּל שֵׁבֶט וְשֵׁבֶט וְקָרְבָּן זֶה הוּא הָאָמוּר בְּפָרָשַׁת שְׁלַח לְךָ שֶׁנֶּאֱמַר (במדבר טו כד) \"וְהָיָה אִם מֵעֵינֵי הָעֵדָה נֶעֶשְׂתָה לִשְׁגָגָה\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁבְּשִׁגְגַת עֲבוֹדָה זָרָה הוּא מְדַבֵּר. וְאִם בִּשְׁאָר כְּרֵתוֹת שֶׁחַיָּבִין עַל שִׁגְגָתָן חַטָּאת קְבוּעָה שָׁגְגוּ וְהוֹרוּ. מֵבִיא כָּל שֵׁבֶט וְשֵׁבֶט פַּר חַטָּאת וְזֶהוּ הָאָמוּר בְּפָרָשַׁת וַיִּקְרָא שֶׁנֶּאֱמַר (ויקרא ד יג) \"וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ\". נִמְצֵאתָ לָמֵד שֶׁאִם שָׁגְגוּ בֵּית דִּין הַגָּדוֹל בְּהוֹרָאָה בַּעֲבוֹדָה זָרָה מְבִיאִין כָּל הַקָּהָל שְׁנֵים עָשָׂר פָּרִים עוֹלוֹת וּשְׁנֵים עָשָׂר שְׂעִירִים חַטָּאוֹת וְהֵם נִשְׂרָפוֹת שֶׁהֲרֵי דָּמָן נִכְנָס לְפָנִים וְהֵם הַנִּקְרָאִין שְׂעִירֵי עֲבוֹדָה זָרָה. וְאִם בִּשְׁאָר הַמִּצְוֹת שָׁגְגוּ מְבִיאִין שְׁנֵים עָשָׂר פָּרִים חַטָּאוֹת וְהֵן נִשְׂרָפוֹת מִפְּנֵי שֶׁדָּמָם נִכְנַס לְפָנִים. וְכָל פַּר מֵהֶן נִקְרָא פַּר הֶעְלֵם דָּבָר שֶׁל צִבּוּר שֶׁנֶּאֱמַר (ויקרא ד יד) \"וְהִקְרִיב הַקָּהָל\" כָּל קָהָל וְקָהָל וְכָל שֵׁבֶט וְשֵׁבֶט קָרוּי קָהָל שֶׁנֶּאֱמַר (דברי הימים ב כ ה) \"וַיַּעֲמֹד יְהוֹשָׁפָט בִּקְהַל יְהוּדָה\". בֵּין שֶׁעָשׂוּ כָּל יִשְׂרָאֵל שֶׁבְּאֶרֶץ יִשְׂרָאֵל עַל פִּי בֵּית דִּין שֶׁהוֹרוּ בֵּין שֶׁעָשׂוּ רֹב יִשְׂרָאֵל אַף עַל פִּי שֶׁהֵן מִעוּט מִנְיַן הַשְּׁבָטִים. בֵּין שֶׁעָשׂוּ רֹב הַשְּׁבָטִים אַף עַל פִּי שֶׁהֵן מִעוּט כָּל יִשְׂרָאֵל. מְבִיאִין כְּמִנְיַן כָּל הַשְּׁבָטִים פַּר לְכָל שֵׁבֶט וְשֵׁבֶט וּבַעֲבוֹדָה זָרָה פַּר וְשָׂעִיר לְכָל שֵׁבֶט וְשֵׁבֶט. שֶׁאַף אֵלּוּ שֶׁלֹּא חָטְאוּ מְבִיאִין עַל יְדֵי הַחוֹטְאִים. אֲפִלּוּ עָשָׂה שֵׁבֶט אֶחָד בִּלְבַד וְהוּא רֹב הַקָּהָל הֲרֵי כָּל הַצִּבּוּר מְבִיאִין שְׁנֵים עָשָׂר פָּרִים וּבַעֲבוֹדָה זָרָה שְׁנֵים עָשָׂר פָּרִים וּשְׁנֵים עָשָׂר שְׂעִירִים:","בֵּית דִּין שֶׁנִּסְתַּפֵּק לָהֶן אִם שָׁגְגוּ בְּהוֹרָאָה אוֹ לֹא שָׁגְגוּ אֵינָן חַיָּבִין בְּאָשָׁם תָּלוּי שֶׁנֶּאֱמַר (ויקרא ד יד) \"וְנוֹדְעָה הַחַטָּאת\" עַד שֶׁתִּוָּדַע וְאַחַר כָּךְ יִתְחַיְּבוּ בְּקָרְבָּן כְּמוֹ שֶׁיִּתְבָּאֵר. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁבֵּית דִּין חַיָּבִין וְאֵלּוּ הָעוֹשִׂים עַל פִּיהֶם פְּטוּרִין מִן הַקָּרְבָּן. כְּשֶׁהָיוּ הַמּוֹרִים בֵּית דִּין הַגָּדוֹל שֶׁל שִׁבְעִים וְאֶחָד וְיִהְיֶה רֹאשׁ יְשִׁיבָה עִמָּהֶן בְּהוֹרָאָה וְיִהְיוּ כֻּלָּן רְאוּיִין לְהוֹרָאָה וְיִטְעוּ כֻּלָּן אוֹ רֻבָּן בְּדָבָר זֶה שֶׁהוֹרוּ בּוֹ וְיוֹרוּ בְּפֵרוּשׁ וְיֹאמְרוּ לָעָם מֻתָּרִין אַתֶּם לַעֲשׂוֹת. וְכֵן אֵלּוּ שֶׁשָּׁמְעוּ מִפִּי בֵּית דִּין אִם אָמְרוּ לַאֲחֵרִים מֻתָּרִים אַתֶּם לַעֲשׂוֹת וְיַעֲשׂוּ כָּל הַקָּהָל אוֹ רֻבּוֹ עַל פִּיהֶם וְיִהְיוּ הָעוֹשִׂים שׁוֹגְגִים עַל פִּיהֶם וּמְדַמִּים שֶׁהַדָּבָר שֶׁהוֹרוּ בּוֹ כַּדָּת הוֹרוּ. וְיוֹרוּ לְבַטֵּל מִקְצָת וּלְקַיֵּם מִקְצָת לֹא שֶׁיַּעַקְרוּ כָּל הַגּוּף וּכְשֶׁיִּוָּדַע לָהֶם יֵדְעוּ גּוּפוֹ שֶׁל דָּבָר שֶׁהוֹרוּ בּוֹ בִּשְׁגָגָה. בְּכָל אֵלּוּ הַמְאֹרָעִים הוּא שֶׁהָיוּ בֵּית דִּין חַיָּבִין בְּקָרְבָּן וְהָעוֹשֶׂה עַל פִּיהֶם פָּטוּר. אֲבָל אִם חָסֵר אַחַת מִכָּל אֵלּוּ הַדְּרָכִים הֲרֵי בֵּית דִּין פְּטוּרִין מִן הַקָּרְבָּן וְכָל מִי שֶׁשָּׁגַג וְעָשָׂה מַעֲשֶׂה מֵבִיא חַטָּאת קְבוּעָה עַל שִׁגְגָתוֹ:"],"Mishneh Torah, One Who Injures a Person or Property 1":["הַחוֹבֵל בַּחֲבֵרוֹ חַיָּב לְשַׁלֵּם לוֹ חֲמִשָּׁה דְּבָרִים וְאֵלּוּ הֵם. נֵזֶק וְצַעַר וְרִפּוּי וְשֶׁבֶת וּבשֶׁת. וַחֲמִשָּׁה דְּבָרִים אֵלּוּ כֻּלָּן מִשְׁתַּלְּמִים מִן הַיָּפֶה שֶׁבִּנְכָסָיו כְּדִין כָּל הַמַּזִּיקִין:","נֵזֶק כֵּיצַד. שֶׁאִם קָטַע יַד חֲבֵרוֹ אוֹ רַגְלוֹ רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא עֶבֶד נִמְכָּר בַּשּׁוּק כַּמָּה הָיָה יָפֶה [אָז] וְכַמָּה הוּא יָפֶה עַתָּה וּמְשַׁלֵּם הַפְּחָת שֶׁהִפְחִית מִדָּמָיו. שֶׁנֶּאֱמַר (שמות כא כד) (ויקרא כד כ) \"עַיִן תַּחַת עַיִן\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר תַּחַת לְשַׁלֵּם מָמוֹן הוּא:","זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (ויקרא כד כ) \"כַּאֲשֶׁר יִתֵּן מוּם בָּאָדָם כֵּן יִנָּתֶן בּוֹ\" אֵינוֹ לַחֲבל בָּזֶה כְּמוֹ שֶׁחָבַל בַּחֲבֵרוֹ אֶלָּא שֶׁהוּא רָאוּי לְחַסְּרוֹ אֵיבָר אוֹ לַחֲבל בּוֹ כַּאֲשֶׁר עָשָׂה וּלְפִיכָךְ מְשַׁלֵּם נִזְקוֹ. וַהֲרֵי הוּא אוֹמֵר (במדבר לה לא) \"וְלֹא תִקְחוּ כֹפֶר לְנֶפֶשׁ רֹצֵחַ\" לְרוֹצֵחַ בִּלְבַד הוּא שֶׁאֵין בּוֹ כֹּפֶר אֲבָל לְחֶסְרוֹן אֵיבָרִים אוֹ לְחַבָּלוֹת יֵשׁ בּוֹ כֹּפֶר:","וְכֵן זֶה שֶׁנֶּאֱמַר בְּחוֹבֵל בַּחֲבֵרוֹ וּמַזִּיקוֹ (דברים כה יב) \"לֹא תָחוֹס עֵינֶךָ\" שֶׁלֹּא תָּחוּס בְּתַשְׁלוּמִין שֶׁמָּא תֹּאמַר עָנִי הוּא זֶה וְשֶׁלֹּא בְּכַוָּנָה חָבַל בּוֹ אֲרַחֲמֶנּוּ לְכָךְ נֶאֱמַר לֹא תָחוֹס עֵינֶךָ:","וּמִנַּיִן שֶׁזֶּה שֶׁנֶּאֱמַר בְּאֵיבָרִים (שמות כא כד) (ויקרא כד כ) \"עַיִן תַּחַת עַיִן\" תַּשְׁלוּמִין הוּא. שֶׁנֶּאֱמַר בּוֹ (שמות כא כה) \"חַבּוּרָה תַּחַת חַבּוּרָה\" וּבְפֵרוּשׁ נֶאֱמַר (שמות כא יח) \"וְכִי יַכֶּה אִישׁ אֶת רֵעֵהוּ בְּאֶבֶן אוֹ בְּאֶגְרוֹף\" וְגוֹ' (שמות כא יט) \"רַק שִׁבְתּוֹ יִתֵּן וְרַפֹּא יְרַפֵּא\". הָא לָמַדְתָּ שֶׁתַּחַת שֶׁנֶּאֱמַר בְּחַבּוּרָה תַּשְׁלוּמִין. וְהוּא הַדִּין לְתַחַת הָאָמוּר בְּעַיִן וּבִשְׁאָר אֵיבָרִים:","וְאַף עַל פִּי שֶׁדְּבָרִים אֵלּוּ נִרְאִים מֵעִנְיַן תּוֹרָה שֶׁבִּכְתָב וְכֻלָּן מְפֹרָשִׁין הֵן מִפִּי משֶׁה רַבֵּנוּ מֵהַר סִינַי. כֻּלָּן הֲלָכָה לְמשֶׁה הֵן בְּיָדֵינוּ וְכָזֶה רָאוּ אֲבוֹתֵינוּ דָּנִין בְּבֵית דִּינוֹ שֶׁל יְהוֹשֻׁעַ וּבְבֵית דִּינוֹ שֶׁל שְׁמוּאֵל הָרָמָתִי וּבְכָל בֵּית דִּין וּבֵית דִּין שֶׁעָמְדוּ מִימוֹת משֶׁה רַבֵּנוּ וְעַד עַכְשָׁו:","וּמִנַּיִן שֶׁמַּזִּיק בַּחֲבֵרוֹ חַיָּב בְּצַעַר בִּפְנֵי עַצְמוֹ. שֶׁהֲרֵי נֶאֱמַר בְּאוֹנֵס (דברים כב כט) \"תַּחַת אֲשֶׁר עִנָּהּ\". וְהוּא הַדִּין לְכָל הַמְצַעֵר אֶת חֲבֵרוֹ בְּגוּפוֹ שֶׁהוּא חַיָּב לְשַׁלֵּם דְּמֵי הַצַּעַר:","וּמִנַּיִן שֶׁהוּא חַיָּב בְּשֶׁבֶת בִּפְנֵי עַצְמוֹ וְרִפּוּי בִּפְנֵי עַצְמוֹ. שֶׁנֶּאֱמַר (שמות כא יט) \"רַק שִׁבְתּוֹ יִתֵּן וְרַפֹּא יְרַפֵּא\":","וּמִנַּיִן שֶׁהוּא חַיָּב בְּבשֶׁת בִּפְנֵי עַצְמוֹ שֶׁהֲרֵי נֶאֱמַר (דברים כה יא) \"וְשָׁלְחָה יָדָהּ וְהֶחֱזִיקָה בִּמְבֻשָׁיו\" (דברים כה יב) \"וְקַצֹּתָה אֶת כַּפָּהּ\" בִּכְלַל דִּין זֶה כָּל הַמְבַיֵּשׁ:","הַמְבַיֵּשׁ אֵינוֹ חַיָּב עַל הַבּשֶׁת עַד שֶׁיִּהְיֶה מִתְכַּוֵּן שֶׁנֶּאֱמַר (דברים כה יא) \"וְשָׁלְחָה יָדָהּ\". אֲבָל הַמְבַיֵּשׁ חֲבֵרוֹ בְּלֹא כַּוָּנָה פָּטוּר. לְפִיכָךְ יָשֵׁן וְכַיּוֹצֵא בּוֹ שֶׁבִּיֵּשׁ פָּטוּר:","אָדָם מוּעָד לְעוֹלָם בֵּין שׁוֹגֵג בֵּין מֵזִיד בֵּין עֵר בֵּין יָשֵׁן בֵּין שִׁכּוֹר אִם חָבַל בַּחֲבֵרוֹ אוֹ הִזִּיק מָמוֹן חֲבֵרוֹ מְשַׁלֵּם מִן הַיָּפֶה שֶׁבִּנְכָסָיו. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהַיָּשֵׁן חַיָּב לְשַׁלֵּם בִּשְׁנַיִם שֶׁיָּשְׁנוּ כְּאֶחָד וְנִתְהַפֵּךְ אֶחָד מֵהֶן וְהִזִּיק אֶת חֲבֵרוֹ אוֹ קָרַע בִּגְדוֹ. אֲבָל אִם הָיָה אֶחָד יָשֵׁן וּבָא אַחֵר וְשָׁכַב בְּצִדּוֹ. זֶה שֶׁבָּא בָּאַחֲרוֹנָה הוּא הַמּוּעָד וְאִם הִזִּיקוֹ הַיָּשֵׁן פָּטוּר. וְכֵן אִם הִנִּיחַ כְּלִי בְּצַד הַיָּשֵׁן וּשְׁבָרוֹ פָּטוּר שֶׁזֶּה שֶׁהִנִּיחוֹ הוּא הַמּוּעָד שֶׁפָּשַׁע:","מִי שֶׁנָּפַל מִן הַגַּג בְּרוּחַ מְצוּיָה וְהִזִּיק חַיָּב בְּאַרְבָּעָה דְּבָרִים וּפָטוּר מִן הַבּשֶׁת. נָפַל בְּרוּחַ שֶׁאֵינָהּ מְצוּיָה חַיָּב בְּנֵזֶק בִּלְבַד וּפָטוּר מֵאַרְבָּעָה דְּבָרִים. וְאִם נִתְהַפֵּךְ חַיָּב בַּכּל אַף בְּבשֶׁת שֶׁכָּל הַמִּתְכַּוֵּן לְהַזִּיק אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן לְבַיֵּשׁ חַיָּב בְּבשֶׁת:","שְׁנַיִם שֶׁחָבְלוּ בְּאֶחָד כְּאֶחָד שְׁנֵיהֶם חַיָּבִין וּמְשַׁלְּשִׁין בֵּינֵיהֶן. הָיָה אֶחָד מִתְכַּוֵּן וְאֶחָד שֶׁאֵינוֹ מִתְכַּוֵּן זֶה שֶׁאֵינוֹ מִתְכַּוֵּן פָּטוּר מִן הַבּשֶׁת:","הַמִּתְכַּוֵּן לְבַיֵּשׁ אֶת הַקָּטָן וּבִיֵּשׁ אֶת הַגָּדוֹל נוֹתֵן לַגָּדוֹל דְּמֵי בָּשְׁתּוֹ שֶׁל קָטָן. נִתְכַּוֵּן לְבַיֵּשׁ הָעֶבֶד וּבִיֵּשׁ אֶת בֶּן חוֹרִין נוֹתֵן לְבֶן חוֹרִין דְּמֵי בָּשְׁתּוֹ שֶׁל עֶבֶד:","הָיְתָה לוֹ אֶבֶן מֻנַּחַת בְּחֵיקוֹ בֵּין שֶׁלֹּא הִכִּיר בָּהּ מֵעוֹלָם בֵּין שֶׁהִכִּיר בָּהּ וּשְׁכָחָהּ וְעָמַד וְנָפְלָה וְהִזִּיקָה חַיָּב בְּנֵזֶק בִּלְבַד וּפָטוּר מֵאַרְבָּעָה דְּבָרִים. וְכֵן אִם נִתְכַּוֵּן לִזְרֹק שְׁתַּיִם וְזָרַק אַרְבַּע וְהִזִּיק אוֹ שֶׁהִזִּיק כְּשֶׁהוּא יָשֵׁן חַיָּב בְּנֵזֶק וּפָטוּר מֵאַרְבָּעָה דְּבָרִים:","הַמַּזִּיק אֶת חֲבֵרוֹ בְּכַוָּנָה בְּכָל מָקוֹם חַיָּב בַּחֲמִשָּׁה דְּבָרִים. וַאֲפִלּוּ נִכְנַס לִרְשׁוּת חֲבֵרוֹ שֶׁלֹּא בִּרְשׁוּת וְהִזִּיקוֹ בַּעַל הַבַּיִת חַיָּב שֶׁיֵּשׁ לוֹ רְשׁוּת לְהוֹצִיאוֹ וְאֵין לוֹ רְשׁוּת לְהַזִּיקוֹ. אֲבָל אִם הֻזַּק זֶה שֶׁנִּכְנַס בְּבַעַל הַבַּיִת הֲרֵי בַּעַל הַבַּיִת פָּטוּר. וְאִם הֻזַּק בּוֹ בַּעַל הַבַּיִת חַיָּב מִפְּנֵי שֶׁנִּכְנַס שֶׁלֹּא בִּרְשׁוּת. הָיוּ שְׁנֵיהֶם בִּרְשׁוּת אוֹ שְׁנֵיהֶם שֶׁלֹּא בִּרְשׁוּת וְהֻזְּקוּ זֶה בָּזֶה שְׁנֵיהֶם פְּטוּרִין:","הַמְבַקֵּעַ עֵצִים בִּרְשׁוּת הָרַבִּים וּפָרַח עֵץ מֵהֶן וְהִזִּיק בִּרְשׁוּת הַיָּחִיד. אוֹ שֶׁבִּקֵּעַ בִּרְשׁוּת הַיָּחִיד וְהִזִּיק בִּרְשׁוּת הָרַבִּים. אוֹ שֶׁבִּקֵּעַ בִּרְשׁוּת הַיָּחִיד וְהִזִּיק בִּרְשׁוּת הַיָּחִיד אַחֵר. אוֹ שֶׁנִּכְנַס לַחֲנוּתוֹ שֶׁל נַגָּר בֵּין בִּרְשׁוּת בֵּין שֶׁלֹּא בִּרְשׁוּת וְנִתְּזָה בְּקַעַת וְטָפְחָה עַל פָּנָיו. בְּכָל אֵלּוּ חַיָּב בְּאַרְבָּעָה דְּבָרִים וּפָטוּר מִן הַבֹּשֶׁת:","כְּשֵׁם שֶׁאוֹמְדִין לְמִיתָה כָּךְ אוֹמְדִין לִנְזָקִין. כֵּיצַד. הֲרֵי שֶׁהִכָּה חֲבֵרוֹ בִּצְרוֹר קָטָן שֶׁאֵין בּוֹ כְּדֵי לְהַזִּיק אוֹ בְּקֵיסָם שֶׁל עֵץ קָטָן וְחָבַל בּוֹ חַבָּלָה שֶׁאֵין חֵפֶץ זֶה רָאוּי לַעֲשׂוֹתוֹ הֲרֵי זֶה פָּטוּר. שֶׁנֶּאֱמַר (שמות כא יח) \"בְּאֶבֶן אוֹ בְאֶגְרֹף\" דָּבָר הָרָאוּי לְהַזִּיק. אֲבָל חַיָּב הוּא בְּבֹשֶׁת בִּלְבַד. אֲפִלּוּ רָקַק בְּגוּפוֹ שֶׁל חֲבֵרוֹ חַיָּב בְּבשֶׁת. לְפִיכָךְ צְרִיכִין הָעֵדִים לֵידַע בְּמָה הִזִּיק וּמְבִיאִין הַחֵפֶץ שֶׁהִזִּיק בּוֹ לְבֵית דִּין עַד שֶׁאוֹמְדִין אוֹתוֹ וְדָנִין עָלָיו. וְאִם אָבַד הַחֵפֶץ וְאָמַר הַחוֹבֵל לֹא הָיָה בּוֹ כְּדֵי לְהַזִּיק וּכְמוֹ אָנוּס אֲנִי. וְהַנֶּחְבָּל אוֹמֵר הָיָה בּוֹ כְּדֵי לְהַזִּיק. יִשָּׁבַע הַנֶּחְבָּל וְיִטּל כְּמוֹ שֶׁיִּתְבָּאֵר:","הַבַּרְזֶל אֵין לוֹ אֹמֶד אֲפִלּוּ מַחַט קְטַנָּה רְאוּיָה הִיא לְהָמִית וְאֵין צָרִיךְ לוֹמַר לְהַזִּיק. הַזּוֹרֵק אֶבֶן וּלְאַחַר שֶׁיָּצָא מִתַּחַת יָדוֹ הוֹצִיא הַלָּה אֶת רֹאשׁוֹ מִן הַחַלּוֹן וְקִבְּלָהּ פָּטוּר מִכְּלוּם שֶׁנֶּאֱמַר (דברים יט ה) \"וּמָצָא אֶת רֵעֵהוּ\" פְּרָט לְמַמְצִיא אֶת עַצְמוֹ:"],"Mishneh Torah, Other Sources of Defilement 13":["חָמֵשׁ מַעֲלוֹת עָשׂוּ חֲכָמִים בִּבְגָדִים וְאֵלּוּ הֵן. בִּגְדֵי עַם הָאָרֶץ מִדְרָס לְאוֹכְלֵי חֻלֵּיהֶן בְּטָהֳרָה וְכֵן עַמֵּי הָאָרֶץ עַצְמָן כְּזָבִין לְטָהֳרוֹת כְּמוֹ שֶׁבֵּאַרְנוּ. וּבִגְדֵי אוֹכְלֵי חֻלֵּיהֶן בְּטָהֳרָה מִדְרָס לְאוֹכְלֵי מַעֲשֵׂר שֵׁנִי אֲבָל אוֹכְלֵי חֻלֵּיהֶן בְּטָהֳרָה וְהֵן הַנִּקְרָאִים פְּרוּשִׁים אֵינָם כְּזָבִים אֲפִלּוּ לִתְרוּמָה הֲרֵי זֶה הַפָּרוּשׁ טָהוֹר אֲפִלּוּ אִם נָגַע בָּהּ בְּגוּפוֹ. וּבִגְדֵי אוֹכְלֵי מַעֲשֵׂר שֵׁנִי מִדְרָס לְאוֹכְלֵי תְּרוּמָה. וּבִגְדֵי אוֹכְלֵי תְּרוּמָה מִדְרָס לְקֹדֶשׁ אֲבָל אוֹכְלֵי תְּרוּמָה עַצְמָן אֵינָן כְּזָבִין בְּקֹדֶשׁ. וּבִגְדֵי אוֹכְלֵי קֹדֶשׁ מִדְרָס לְחַטָּאת כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת פָּרָה אֲדֻמָּה אֲבָל הַטָּהוֹר לְקֹדֶשׁ אֵינוֹ כְּזָב לְחַטָּאת:","וְכֵן עָשׂוּ חֲכָמִים מַעֲלוֹת בִּטְבִילָה. כֵּיצַד. מִי שֶׁטָּבַל בְּלֹא כַּוָּנָה הֲרֵי זֶה טָהוֹר לְחֻלִּין וְאָסוּר בְּמַעֲשֵׂר שֵׁנִי עַד שֶׁיִּתְכַּוֵּן לִטְבּל לְמַעֲשֵׂר. טָבַל לְמַעֲשֵׂר הֲרֵי זֶה בְּחֶזְקַת טָהֳרָה לְמַעֲשֵׂר וְאָסוּר בִּתְרוּמָה. טָבַל לִתְרוּמָה הֻחְזַק לִתְרוּמָה וְאָסוּר בְּקֹדֶשׁ. טָבַל לְקֹדֶשׁ הֻחְזַק לְקֹדֶשׁ וְאָסוּר לְחַטָּאת. טָבַל לְחַטָּאת הֻחְזַק לַכּל שֶׁהַטּוֹבֵל לְחָמוּר הֻחְזַק לְקַל. טָבַל סְתָם וְלֹא נִתְכַּוֵּן לְאֶחָד מִכָּל אֵלּוּ הֲרֵי זֶה טָהוֹר לְחֻלִּין בִּלְבַד וְטָמֵא כְּשֶׁהָיָה אֲפִלּוּ לְמַעֲשֵׂר. וְכֵן הַנּוֹטֵל יָדָיו אוֹ הִטְבִּילָן צָרִיךְ כַּוָּנָה אֲפִלּוּ לְמַעֲשֵׂר. וּמִן הַמַּעֲשֵׂר וָמַעְלָה צָרִיךְ כַּוָּנָה אֲבָל לְחֻלִּין אֵינוֹ צָרִיךְ כַּוָּנָה. וְכָל הַמַּעֲלוֹת הָאֵלּוּ מִדִּבְרֵי סוֹפְרִים אֲבָל דִּין תּוֹרָה הוֹאִיל וְטָבַל מִכָּל מָקוֹם הֲרֵי הוּא טָהוֹר לַכּל:","מִי שֶׁהָיָה טָהוֹר לִתְרוּמָה וְהִסִּיחַ אֶת לִבּוֹ מִלֶּאֱכל נִטְמָא בְּהֶסֵּחַ הַדַּעַת וְאָסוּר לֶאֱכל תְּרוּמָה עַד שֶׁיִּטְבּל פַּעַם שְׁנִיָּה וְאֵינוֹ צָרִיךְ הַעֲרֵב שֶׁמֶשׁ. הָיוּ יָדָיו טְהוֹרוֹת לִתְרוּמָה וְהִסִּיחַ לִבּוֹ מִלֶּאֱכל אַף עַל פִּי שֶׁאוֹמֵר יוֹדֵעַ אֲנִי שֶׁלֹּא נִטְמְאוּ יָדַי הֲרֵי יָדָיו טְמֵאוֹת בְּהֶסֵּחַ הַדַּעַת שֶׁהַיָּדַיִם עַסְקָנִיּוֹת. אִם לִתְרוּמָה כֵּן קַל וָחֹמֶר לְקֹדֶשׁ שֶׁכָּל הַמַּסִּיחַ דַּעְתּוֹ צָרִיךְ טְבִילָה. וְאִם לֹא שָׁמַר עַצְמוֹ מִטֻּמְאַת מֵת וְלֹא יָדַע בְּוַדַּאי שֶׁלֹּא נִטְמָא הֲרֵי זֶה צָרִיךְ הַזָּאָה שְׁלִישִׁי וּשְׁבִיעִי מִפְּנֵי הֶסֵּחַ הַדַּעַת. וְאִם יָדַע שֶׁלֹּא נִטְמָא בְּמֵת וְהִסִּיחַ דַּעְתּוֹ מִשְּׁאָר טֻמְאוֹת הֲרֵי זֶה צָרִיךְ טְבִילָה וְהַעֲרֵב שֶׁמֶשׁ אַף לִתְרוּמָה. וְדָבָר בָּרוּר הוּא שֶׁכָּל אֵלּוּ הַטְּבִילוֹת מִדִּבְרֵיהֶן:","וְכֵן גָּזְרוּ חֲכָמִים עַל הַכֵּלִים הַנִּמְצָאִים בַּשְּׁוָקִים וּבָרְחוֹבוֹת אֲפִלּוּ בַּמִּדְבָּרוֹת שֶׁיִּהְיוּ בְּחֶזְקַת טֻמְאָה. שֶׁמָּא בְּזָב אוֹ בְּמֵת נִטְמְאוּ. וְכֵן הָרֻקִּין הַנִּמְצָאִין שָׁם בְּחֶזְקַת טֻמְאָה שֶׁמָּא רֹק זָב וְכַיּוֹצֵא בּוֹ הוּא הָרֹק הַזֶּה:","כָּל הַכֵּלִים הַנִּמְצָאִין בִּירוּשָׁלַיִם טְהוֹרִין אֲפִלּוּ נִמְצְאוּ דֶּרֶךְ יְרִידָה לְבֵית הַטְּבִילָה. שֶׁלֹּא גָּזְרוּ טֻמְאָה עַל הַכֵּלִים הַנִּמְצָאִים בִּירוּשָׁלַיִם חוּץ מִן הַסַּכִּינִים לִשְׁחִיטַת הַקָּדָשִׁים מִפְּנֵי חֻמְרַת הַקָּדָשִׁים. בַּמֶּה דְּבָרִים אֲמוּרִים בְּסַכִּין הַנִּמְצֵאת בִּירוּשָׁלַיִם בִּשְׁאָר יְמוֹת הַשָּׁנָה. אֲבָל אִם מָצָא סַכִּין בִּירוּשָׁלַיִם בְּאַרְבָּעָה עָשָׂר בְּנִיסָן שׁוֹחֵט בָּהּ הַקָּדָשִׁים מִיָּד וַאֲפִלּוּ חָל אַרְבָּעָה עָשָׂר לִהְיוֹת בְּשַׁבָּת שֶׁלֹּא גָּזְרוּ עַל הַסַּכִּינִין הַנִּמְצָאִים בַּיּוֹם הַזֶּה. וְכֵן אִם מְצָאָהּ בְּיוֹם טוֹב שׁוֹחֵט בָּהּ מִיָּד שֶׁחֶזְקַת כָּל הַכֵּלִים בְּיוֹם טוֹב טְהוֹרִין:","מָצָא הַסַּכִּין בִּשְׁלֹשָׁה עָשָׂר מַזֶּה עָלֶיהָ וּמַטְבִּילָהּ וְשׁוֹחֵט בָּהּ לְמָחָר מִפְּנֵי שֶׁעֲשָׂאוּהוּ בְּיוֹם זֶה כְּאִלּוּ יוֹם שְׁלֹשָׁה עָשָׂר שְׁבִיעִי שֶׁלָּהּ:","מָצָא סַכִּין קְשׁוּרָה לַסַּכִּין הַיְדוּעָה אֶצְלוֹ בֵּין בְּיוֹם טוֹב בֵּין בִּשְׁאָר הַיָּמִים הֲרֵי הִיא כָּמוֹהָ אִם טְהוֹרָה טְהוֹרָה וְאִם טְמֵאָה טְמֵאָה:","כָּל הָרֻקִּין הַנִּמְצָאִים בִּירוּשָׁלַיִם בְּאֶמְצַע הַדֶּרֶךְ גָּזְרוּ עֲלֵיהֶן טֻמְאָה כִּשְׁאָר הָרֻקִּין הַנִּמְצָאִים בְּכָל מָקוֹם. וְכָל הָרֻקִּין הַנִּמְצָאִים בַּצְּדָדִין בִּירוּשָׁלַיִם טְהוֹרִים. שֶׁהַפְּרוּשִׁים הֵן שֶׁמְּהַלְּכִין בַּצְּדָדִין כְּדֵי שֶׁלֹּא יִתְטַמְּאוּ בְּמַגַּע עַמֵּי הָאָרֶץ. וּבִשְׁעַת הָרֶגֶל שֶׁבְּאֶמְצַע הַדֶּרֶךְ טְהוֹרִים שֶׁכָּל יִשְׂרָאֵל טְהוֹרִים בָּרֶגֶל. וְשֶׁבַּצְּדָדִין טְמֵאִים שֶׁהַטְּמֵאִים בָּרֶגֶל מְעַטִּים וְהֵן פּוֹרְשִׁים לְצִדֵּי הַדְּרָכִים:","כְּשֵׁם שֶׁהָרִאשׁוֹן עוֹשֶׂה שֵׁנִי וְהַשֵּׁנִי עוֹשֶׂה שְׁלִישִׁי כֵּן סְפֵק רִאשׁוֹן עוֹשֶׂה סְפֵק שֵׁנִי וּסְפֵק שֵׁנִי עוֹשֶׂה סְפֵק שְׁלִישִׁי:","תְּרוּמָה וְקָדָשִׁים שֶׁנִּטְמְאוּ בִּסְפֵק אָב מֵאֲבוֹת הַטֻּמְאוֹת שֶׁל תּוֹרָה הֲרֵי אֵלּוּ נִשְׂרָפִין בְּטֻמְאָה זוֹ כְּגוֹן שֶׁנִּסְתַּפֵּק לוֹ אִם נָגַע בְּאָב זֶה אוֹ לֹא נָגַע:","וְיֵשׁ שָׁם סְפֵקוֹת שֶׁאֵין שׂוֹרְפִין עֲלֵיהֶן וְאֵין אוֹכְלִין אוֹתָן אֳכָלִין שֶׁנִּסְתַּפֵּק לוֹ בָּהֶן אֶלָּא תּוֹלִין לֹא אוֹכְלִין וְלֹא שׂוֹרְפִין. וְיֵשׁ שָׁם סְפֵקוֹת שֶׁשּׂוֹרְפִין עֲלֵיהֶן אֶת הַתְּרוּמָה וְאֵין צָרִיךְ לוֹמַר קָדָשִׁים:","אֲבָל עַל סְפֵק סְפֵק הַטֻּמְאָה אֵין שׂוֹרְפִין עָלָיו תְּרוּמָה לְעוֹלָם וְאֵין צָרִיךְ לוֹמַר קָדָשִׁים. אֶלָּא תּוֹלִין לֹא אוֹכְלִין וְלֹא שׂוֹרְפִין:","עַל שִׁשָּׁה סְפֵקוֹת שׂוֹרְפִין אֶת הַתְּרוּמָה וְכֻלָּם גְּזֵרָה מִדִּבְרֵיהֶם וְאֵלּוּ הֵן. עַל בֵּית הַפְּרָס. וְעַל עָפָר הַבָּא מֵאֶרֶץ הָעַמִּים. וְעַל בִּגְדֵי עַם הָאָרֶץ. וְעַל הַכֵּלִים הַנִּמְצָאִים. וְעַל הָרֻקִּים הַנִּמְצָאִים. וְעַל מֵי רַגְלֵי אָדָם טָמֵא שֶׁנִּתְעָרֵב בְּמֵי רַגְלֵי בְּהֵמָה מֶחֱצָה לְמֶחֱצָה וְאֵין יָדוּעַ אִם בָּטְלוּ מַרְאִיתָן אִם לֹא. כֵּיצַד. אִם נִטְמֵאת תְּרוּמָה מֵחֲמַת אֶחָד מִשִּׁשָּׁה אֵלּוּ אַף עַל פִּי שֶׁעִקַּר טֻמְאָתָן בְּסָפֵק הֲרֵי זוֹ תִּשָּׂרֵף. הוֹאִיל וּוַדַּאי סְפֵקוֹת אֵלּוּ טֻמְאָתָן מִן הַתּוֹרָה שֶׁהַמֵּת וְהַזָּב טְמֵאִין מִן הַתּוֹרָה. וְאַחַת תְּרוּמָה שֶׁנָּגְעָה בְּאַחַת מִשֵּׁשׁ טֻמְאוֹת הָאֵלּוּ. אוֹ שֶׁנִּטְמֵאת מֵחֲמַת אַחַת מֵהֶן וַהֲרֵי הִיא שְׁלִישִׁי לְאַחַת מֵהֶן הֲרֵי זוֹ תִּשָּׂרֵף. אֲבָל אִם נִסְתַּפֵּק לוֹ בְּכָל מָקוֹם אִם נָגַע בְּבֵית הַפְּרָס וּבְאֶרֶץ הָעַמִּים אוֹ לֹא נָגַע. אִם נָגַע בִּבְגָדִים וְרֻקִּין וְכֵלִים וּמֵי רְגָלִים אוֹ לֹא נָגַע. הֲרֵי אֵלּוּ תּוֹלִין מִפְּנֵי שֶׁעִקַּר טֻמְאָתָן מִפְּנֵי הַסָּפֵק שֶׁמָּא טְמֵאִין הֵן אוֹ טְהוֹרִים וְאִם תֹּאמַר טְמֵאִין שֶׁמָּא נָגַע שֶׁמָּא לֹא נָגַע וְנִמְצְאוּ שְׁנֵי סְפֵקוֹת וְאֵין שׂוֹרְפִין עַל שְׁנֵי סְפֵקוֹת אֶלָּא תּוֹלִין כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Other Sources of Defilement 6":["טֻמְאַת עֲבוֹדָה זָרָה מִדִּבְרֵי סוֹפְרִים וְיֵשׁ לָהּ רֶמֶז בַּתּוֹרָה (בראשית לה ב) \"הָסִרוּ אֶת אֱלֹהֵי הַנֵּכָר אֲשֶׁר בְּתֹכְכֶם וְהִטַּהֲרוּ וְהַחֲלִיפוּ שִׂמְלֹתֵיכֶם\". וְאַרְבָּעָה אֲבוֹת הַטֻּמְאוֹת יֵשׁ בָּהּ. עֲבוֹדָה זָרָה עַצְמָהּ. וּמְשַׁמְּשֶׁיהָ. וְתִקְרֹבֶת שֶׁלָּהּ. וְיַיִן שֶׁנִּתְנַסֵּךְ לָהּ. וְטֻמְאַת כֻּלָּן מִדִּבְרֵיהֶן:","עֲבוֹדָה זָרָה עַצְמָהּ מְטַמְּאָה אָדָם וְכֵלִים בְּמַגָּע וּכְלֵי חֶרֶס בָּאֲוִיר וְאֵינָהּ מְטַמְּאָה בְּמַשָּׂא כְּשֶׁרֶץ שֶׁנֶּאֱמַר (דברים ז כו) \"שַׁקֵּץ תְּשַׁקְּצֶנּוּ\". וְשִׁעוּרָהּ כְּזַיִת לֹא תִּהְיֶה זוֹ חֲמוּרָה מִן הַמֵּת. אֲבָל אִם הָיְתָה הַצּוּרָה פְּחוּתָה מִכְּזַיִת טְהוֹרָה:","קָצַץ אֵיבָר מִמֶּנָּה אֲפִלּוּ הָיָה כְּמַרְדֵּעַ הֲרֵי זֶה טָהוֹר שֶׁעֲבוֹדָה זָרָה אֵינָהּ מְטַמְּאָה לְאֵיבָרִים אֶלָּא הַצּוּרָה כֻּלָּהּ כְּשֶׁהִיא שְׁלֵמָה שֶׁנֶּאֱמַר (ישעיה ל כב) \"תִּזְרֵם כְּמוֹ דָוָה\" מָה דָּוָה אֵינָהּ מְטַמְּאָה לְאֵיבָרִים אַף עֲבוֹדָה זָרָה אֵינָהּ מְטַמְּאָה לְאֵיבָרִים. כְּקֻלֵּי אֲבוֹת הַטֻּמְאוֹת דָּנוּ בָּהּ מִפְּנֵי שֶׁטֻּמְאָתָהּ מִדִּבְרֵיהֶם עֲשָׂאוּהָ כְּשֶׁרֶץ שֶׁאֵינוֹ מְטַמֵּא בְּמַשָּׂא וּכְמֵת שֶׁאֵינוֹ מְטַמֵּא אֶלָּא בִּכְזַיִת וּכְנִדָּה שֶׁאֵינָהּ מְטַמְּאָה לְאֵיבָרִים:","נִתְפָּרְקָה עֲבוֹדָה זָרָה אַף עַל פִּי שֶׁהַהֶדְיוֹט יָכוֹל לְהַחְזִירָהּ וַהֲרֵי כָּל אֵיבָרֶיהָ קַיָּמִים אֵינָהּ מְטַמְּאָה:","כָּל מְשַׁמְּשֵׁי עֲבוֹדָה זָרָה כְּשֶׁרֶץ מְטַמְּאִין אָדָם וְכֵלִים בְּמַגָּע וּכְלֵי חֶרֶס בַּאֲוִיר וְאֵינָן מְטַמְּאִין בְּמַשָּׂא. וְשִׁעוּר טֻמְאָתָן בִּכְזַיִת וַאֲפִלּוּ קִצֵּץ מִמְּשַׁמְּשֶׁיהָ כְּזַיִת מִן הַכְּלִי מְטַמֵּא כְּשֶׁרֶץ. זוֹ חֹמֶר בִּמְשַׁמְּשֶׁיהָ יוֹתֵר מֵעֲבוֹדָה זָרָה עַצְמָהּ. וּבֵית עֲבוֹדָה זָרָה עַצְמוֹ אֲבָנָיו וְעֵצָיו וַעֲפָרוֹ מְטַמְּאִין בִּכְזַיִת בְּמַגָּע כְּכָל הַמְשַׁמְּשִׁין:","הַמַּכְנִיס רֹאשׁוֹ וְרֻבּוֹ לְבֵית עֲבוֹדָה זָרָה נִטְמָא כְּנוֹגֵעַ. וְכֵן כְּלִי חֶרֶס שֶׁהִכְנִיס אֲוִירוֹ לְבֵית עֲבוֹדָה זָרָה נִטְמָא. סַפְסָלִים וְקָתֵדְרָאוֹת שֶׁהִכְנִיס רֻבָּן לְבֵית עֲבוֹדָה זָרָה טְמֵאִים וְכֻלָּן רִאשׁוֹן לְטֻמְאָה:","תִּקְרֹבֶת עֲבוֹדָה זָרָה מְטַמְּאָה בְּמַגָּע וּבְמַשָּׂא כִּנְבֵלָה וְשִׁעוּרָהּ בִּכְזַיִת. כָּל דָּבָר שֶׁמַּקְרִיבִין לָהּ בֵּין בָּשָׂר בֵּין שְׁאָר אֳכָלִים וּמַשְׁקִין הַכּל כִּנְבֵלָה שֶׁהַכָּתוּב קְרָאָן (תהילים קו כח) \"זִבְחֵי מֵתִים\". וְאַף עַל פִּי שֶׁאֵין תִּקְרֹבֶת עֲבוֹדָה זָרָה שֶׁל אֳכָלִין בְּטֵלִין לְעוֹלָם לְהַתִּירָהּ בַּהֲנָאָה אִם בִּטְּלָה הֲרֵי זוֹ סָפֵק לְטֻמְאָה. אֲבָל כְּלִי שֶׁהוּא תִּקְרֹבֶת עֲבוֹדָה זָרָה שֶׁבִּטְּלוֹ טָהוֹר וְכֵן עֲבוֹדָה זָרָה וּמְשַׁמְּשֶׁיהָ שֶׁבִּטְּלָן טְהוֹרִין:","יַיִן שֶׁנִּתְנַסֵּךְ לַעֲבוֹדָה זָרָה מְטַמֵּא אָדָם וְכֵלִים בְּמַגָּע וּכְלֵי חֶרֶס בַּאֲוִיר. וּמְטַמֵּא אָדָם בְּמַשָּׂא כִּנְבֵלָה וְטֻמְאָתוֹ בִּכְזַיִת שֶׁנֶּאֱמַר (דברים לב לח) \"אֲשֶׁר חֵלֶב זְבָחֵימוֹ יֹאכֵלוּ יִשְׁתּוּ יֵין נְסִיכָם\" הֲרֵי יֵין נְסִיכָם כְּחֵלֶב זְבָחֵימוֹ. וְאֵין מְטַמֵּא טֻמְאָה זוֹ אֶלָּא יַיִן שֶׁנִּתְנַסֵּךְ בַּיָּד לִפְנֵי עֲבוֹדָה זָרָה אֲבָל סְתָם יֵינָן שֶׁל עַכּוּ\"ם מְטַמֵּא טֻמְאָה קַלָּה כִּשְׁאָר כָּל מַשְׁקִין טְמֵאִין:","מִכָּל הַדְּבָרִים שֶׁבֵּאַרְנוּ מִתְּחִלַּת הַסֵּפֶר עַד כָּאן אַתָּה לָמֵד שֶׁאֲבוֹת הַטֻּמְאוֹת מֵהֶן אָבוֹת שֶׁל תּוֹרָה וּמֵהֶן אָבוֹת שֶׁל דִּבְרֵי סוֹפְרִים:","כָּל הַמִּתְטַמֵּא מֵחֲמַת אָב שֶׁל תּוֹרָה הֲרֵי הוּא וְלַד טֻמְאָה שֶׁל תּוֹרָה וְכָל הַמִּתְטַמֵּא מֵחֲמַת אָב שֶׁל דִּבְרֵיהֶם הֲרֵי זֶה וָלָד שֶׁל דִּבְרֵיהֶם:","כָּל אַב טֻמְאָה שֶׁמְּטַמֵּא בְּמַגָּע וְאֵינוֹ מְטַמֵּא בְּמַשָּׂא בֵּין אָב שֶׁל תּוֹרָה בֵּין אָב שֶׁל דִּבְרֵיהֶם אָדָם הַנּוֹגֵעַ בּוֹ אֵינוֹ מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ. וְלֹא אָדָם וְלֹא כְּלִי חֶרֶס אַף עַל פִּי שֶׁעֲדַיִן לֹא פֵּרַשׁ מִמְּטַמְּאָיו. וְהִנּוֹ אַחַר שֶׁפֵּרַשׁ מִמְּטַמְּאָיו אוֹ קֹדֶם שֶׁיִּפְרשׁ וָלָד שֶׁהוּא מְטַמֵּא אֳכָלִין וְעוֹשֶׂה אוֹתָן שֵׁנִי לְטֻמְאָה מִפְּנֵי שֶׁהוּא רִאשׁוֹן:","וְכָל אַב טֻמְאָה שֶׁמְּטַמֵּא בְּמַגָּע וּבְמַשָּׂא בֵּין אָב שֶׁל תּוֹרָה בֵּין אָב שֶׁל דִּבְרֵיהֶם אָדָם הַנּוֹגֵעַ בּוֹ אוֹ הַנּוֹשְׂאוֹ מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ וּבִשְׁעַת נְשִׂיאָתוֹ וְעוֹשֶׂה אוֹתָן רִאשׁוֹן לְטֻמְאָה. וְכֵן אִם נָגַע בָּאֳכָלִין עֲשָׂאָן רִאשׁוֹן כָּל זְמַן שֶׁלֹּא פֵּרַשׁ מִמְּטַמְּאָיו. פֵּרַשׁ מִמְּטַמְּאָיו הֲרֵי הוּא רִאשׁוֹן לְטֻמְאָה לְכָל דָּבָר וְאֵינוֹ מְטַמֵּא בְּגָדִים וְאִם נָגַע בָּאֳכָלִין הֲרֵי הֵן שֵׁנִי. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר כָּל הָאָבוֹת חוּץ מִן הַנְּבֵלוֹת וְהַמֶּרְכָּב. אֲבָל הַנְּבֵלָה וְהַמֶּרְכָּב אַף עַל פִּי שֶׁמְּטַמְּאִין בְּמַגָּע וּבְמַשָּׂא הַנּוֹגֵעַ בָּהֶן אֵינוֹ מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ וְאִם נָגַע בָּאֳכָלִין הֲרֵי הֵן שֵׁנִי לְטֻמְאָה. וְהַנּוֹשֵׂא מְטַמֵּא בְּגָדִים בִּשְׁעַת נְשִׂיאָתוֹ וְאִם נָגַע בָּאֳכָלִין עַד שֶׁלֹּא פֵּרַשׁ הִנָּם רִאשׁוֹן לְטֻמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ:","מֵי חַטָּאת שֶׁיֵּשׁ בָּהֶן כְּדֵי הַזָּאָה אַף עַל פִּי שֶׁהֵן כִּנְבֵלָה וּכְמֶרְכָּב שֶׁאֵין מְטַמְּאִין בְּגָדִים אֶלָּא הַנּוֹשְׂאָן הֲרֵי הַנּוֹגֵעַ בָּהֶן מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ מִשּׁוּם נוֹשֵׂא שֶׁאִי אֶפְשָׁר שֶׁיִּגַּע בַּמַּיִם שֶׁלֹּא יָסִיט אוֹתָן. וּכְבָר בֵּאַרְנוּ שֶׁאֶחָד הַנּוֹשֵׂא וְאֶחָד הַמֵּסִיט. וְכֵן הַנּוֹגֵעַ בְּצֶמֶר הַנְּבֵלָה אוֹ שֶׁנָּגַע בְּנִימֵי הַמֶּרְכָּב מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ מִשּׁוּם נוֹשֵׂא. שֶׁאִי אֶפְשָׁר לִנְגֹּעַ בִּדְבָרִים אֵלּוּ שֶׁלֹּא יָסִיט אוֹתָן. וּלְפִיכָךְ מְטַמֵּא בְּגָדִים עַד שֶׁלֹּא פֵּרַשׁ כְּדִין הַנּוֹשֵׂא:","הַבּוֹלֵעַ נִבְלַת עוֹף הַטָּהוֹר בִּשְׁעַת בְּלִיעָתוֹ מְטַמֵּא בְּגָדִים כְּמוֹ שֶׁבֵּאַרְנוּ וְהֵן רִאשׁוֹן לְטֻמְאָה. וְכֵן אִם נָגַע בָּאֳכָלִין הֲרֵי הֵן רִאשׁוֹן לְטֻמְאָה. וְאַחַר שֶׁבָּלַע הֲרֵי זֶה פֵּרַשׁ מִמְּטַמְּאָיו:","הַשּׂוֹרֵף פָּרָה אֲדֻמָּה וּשְׂעִירִים הַנִּשְׂרָפִים וְהַמְשַׁלֵּחַ אֶת הַשָּׂעִיר אַף עַל פִּי שֶׁבִּשְׁעַת מַעֲשֵׂיהֶן מְטַמֵּא בְּגָדִים כְּמוֹ שֶׁבֵּאַרְנוּ. אִם נָגְעוּ בָּאֳכָלִין אֲפִלּוּ בִּשְׁעַת מַעֲשֵׂיהֶן הֲרֵי הֵן שֵׁנִי לְטֻמְאָה:","הַנּוֹגֵעַ בְּאָב מֵאֲבוֹת הַטֻּמְאוֹת הַמֻּשְׁלָךְ בְּתוֹךְ הַמִּקְוֶה. כְּגוֹן נְבֵלָה אוֹ שֶׁרֶץ אוֹ מִשְׁכָּב שֶׁהוּא בְּמִקְוֶה וְנָגַע בּוֹ הֲרֵי זֶה טָמֵא. שֶׁנֶּאֱמַר (ויקרא יא לו) \"אַךְ מַעְיָן וּבוֹר מִקְוֵה מַיִם יִהְיֶה טָהוֹר וְנֹגֵעַ בְּנִבְלָתָם יִטְמָא\" אֲפִלּוּ כְּשֶׁהֵן בְּתוֹךְ הַמִּקְוֶה מְטַמְּאִין. וּכְשֶׁיַּעֲלֶה מִן הַמִּקְוֶה זֶה הַנּוֹגֵעַ יִטְהַר. [וְהַנּוֹשְׂאָן מְטַמֵּא בְּגָדִים בִּשְׁעַת נְשִׂיאָתָן. וְאִם נָגַע בָּאֳכָלִים עַד שֶׁלֹּא פֵּרַשׁ הֲרֵי הֵן רִאשׁוֹן לְטֻמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ]. וְכֵן זָב שֶׁדָּרַס עַל הַמִּשְׁכָּב שֶׁהוּא מֻנָּח בַּמִּקְוֶה הֲרֵי הַמִּשְׁכָּב טָמֵא. וּכְשֶׁיַּעֲלֶה הַמִּשְׁכָּב מִן הַמִּקְוֶה יִטְהַר שֶׁהֲרֵי עָלְתָה לוֹ טְבִילָה וְזֶה הַנּוֹגֵעַ בַּמִּשְׁכָּב כְּשֶׁהוּא בַּמִּקְוֶה אִם פָּשַׁט יָדוֹ וְנוֹגֵעַ חוּץ לַמִּקְוֶה הֲרֵי זֶה מְטַמֵּא בְּגָדִים וְאֵין צָרִיךְ לוֹמַר שֶׁהוּא מְטַמֵּא אֳכָלִין וּמַשְׁקִין:"],"Mishneh Torah, Overview of Mishneh Torah Contents 4":["ספר נשים","הלכותיו חמש, וזה הוא סידורן: הלכות אישות, הלכות גירושין, הלכות ייבום וחליצה, הלכות נערה בתולה, הלכות סוטה.","הלכות אישות. יש בכללן ארבע מצוות – שתי מצוות עשה, ושתי מצוות לא תעשה; וזה הוא פרטן: (א) לישא אישה בכתובה וקידושין; (ב) שלא תיבעל אישה בלא כתובה וקידושין; (ג) שלא ימנע שאר כסות ועונה; (ד) לפרות ולרבות ממנה.","הלכות גירושין. יש בכללן שתי מצוות: (א) מצות עשה, והוא שיגרש המגרש בספר; (ב) שלא יחזיר גרושתו משנישאת.","הלכות ייבום וחליצה. יש בכללן שלוש מצוות – שתי מצוות עשה, ואחת מצות לא תעשה; וזה הוא פרטן: (א) לייבם; (ב) לחלוץ; (ג) שלא תינשא יבמה לאיש זר עד שתסור רשות היבם מעליה.","הלכות נערה בתולה. יש בכללן חמש מצוות – שלוש מצוות עשה, ושתי מצוות לא תעשה; וזה הוא פרטן: (א) לקנוס המפתה; (ב) שיישא האונס אנוסתו; (ג) שלא יגרש האונס; (ד) שתשב אשת מוציא שם רע תחת בעלה לעולם; (ה) שלא יגרש מוציא שם רע את אשתו.","הלכות סוטה. יש בכללן שלוש מצוות – אחת מצות עשה, ושתיים מצוות לא תעשה; וזה הוא פרטן: (א) לעשות לסוטה כתורת הקנאות הסדורה בתורה; (ב) שלא ליתן שמן על קרבנה; (ג) שלא ליתן עליו לבונה.","נמצאו כל המצוות הנכללות בספר זה, שבע עשרה – מהן תשע מצוות עשה, ושמונה מצוות לא תעשה."],"Mishneh Torah, Ownerless Property and Gifts 4":["הַמְקַבֵּל אֶת הַמַּתָּנָה וְזָכָה בָּהּ. וְאַחַר שֶׁבָּאָה לְיָדוֹ וְהוּא שׁוֹתֵק חָזַר בּוֹ וְאָמַר אֵינִי רוֹצֶה בָּהּ. אוֹ אֵינִי מְקַבְּלָהּ. אוֹ הֲרֵי הִיא בְּטֵלָה. אוֹ שֶׁאָמַר מוּם זֶה נִרְאֶה לִי בָּהּ. לֹא אָמַר כְּלוּם. וּכְשֵׁם שֶׁאֵין הַנּוֹתֵן יָכוֹל לַחְזֹר בּוֹ כָּךְ הַמְקַבֵּל אֵינוֹ יָכוֹל לַחְזֹר בּוֹ אַחַר שֶׁזָּכָה. מַתָּנָה זוֹ שֶׁאָמַר הַמְקַבֵּל אֵינִי רוֹצֶה בָּהּ אַחַר שֶׁבָּאת לְיָדוֹ הֲרֵי הִיא הֶפְקֵר וְכָל הַקּוֹדֵם בָּהּ זָכָה בָּהּ שֶׁהֲרֵי הִפְקִירָהּ הַמְקַבֵּל אַחַר שֶׁזָּכָה בָּהּ. אֲבָל אִם הָיָה צוֹוֵחַ מֵעִקָּרוֹ לֹא קָנָה הַמְקַבֵּל וְחוֹזֶרֶת לַבְּעָלִים הָרִאשׁוֹנִים:","הַמְזַכֶּה לַחֲבֵרוֹ בְּמַתָּנָה עַל יְדֵי אַחֵר כֵּיוָן שֶׁהֶחְזִיק בָּהּ אַחֵר כְּגוֹן שֶׁמָּשַׁךְ הַמִּטַּלְטְלִין אוֹ הִגִּיעַ שְׁטַר הַקַּרְקַע לְיָדוֹ אוֹ הֶחֱזִיק בַּקַּרְקַע זָכָה חֲבֵרוֹ אַף עַל פִּי שֶׁלֹּא הִגִּיעַ הַמַּתָּנָה לְיָדוֹ וְאֵין הַנּוֹתֵן יָכוֹל לַחְזֹר בּוֹ. אֲבָל הַמְקַבֵּל יָדוֹ עַל הָעֶלְיוֹנָה אִם רָצָה מְקַבֵּל אִם לֹא רָצָה אֵינוֹ מְקַבֵּל שֶׁזָּכִין לְאָדָם שֶׁלֹּא בְּפָנָיו וְאֵין חָבִין לוֹ אֶלָּא בְּפָנָיו וּזְכוּת הוּא שֶׁתִּנָּתֵן לוֹ מַתָּנָה אִם יִרְצֶה. אֲבָל אִם לֹא יִרְצֶה אֵין נוֹתְנִין מַתָּנָה לְאָדָם בְּעַל כָּרְחוֹ:","זִכָּה לוֹ עַל יְדֵי אַחֵר וּכְשֶׁשָּׁמַע הַמְקַבֵּל שָׁתַק וְאַחַר כָּךְ צָוַח וְאָמַר אֵינִי מְקַבְּלָהּ. הֲרֵי זֶה סָפֵק אִם זֶה שֶׁשָּׁתַק כְּבָר רָצָה וְזֶה שֶׁחָזַר וְצָוַח חָזַר בּוֹ. אוֹ שֶׁשָּׁתַק מִפְּנֵי שֶׁעֲדַיִן לֹא הִגִּיעַ לְיָדוֹ כְּלוּם וְזֶה שֶׁצָּוַח הוֹכִיחַ סוֹפוֹ עַל תְּחִלָּתוֹ. לְפִיכָךְ אִם קָדַם אַחֵר וְזָכָה בָּהּ לְעַצְמוֹ אֵין מוֹצִיאִין מִיָּדוֹ. שֶׁמָּא הַמְקַבֵּל זָכָה וְכֵיוָן שֶׁאָמַר אֵינִי רוֹצֶה בָּהּ הֲרֵי הִפְקִירָהּ כְּמוֹ שֶׁבֵּאַרְנוּ. וְזֶה שֶׁקָּדַם וּלְקָחָהּ מִן הַהֶפְקֵר זָכָה. וְאִם חָזְרוּ הַבְּעָלִים הָרִאשׁוֹנִים וּתְפָשׂוּהָ מִיַּד זֶה שֶׁקָּדַם וְזָכָה בָּהּ אֵין מוֹצִיאִין אוֹתָהּ מִיָּדָם. שֶׁמָּא הַמְקַבֵּל לֹא זָכָה וְכֵיוָן שֶׁאָמַר אֵינִי רוֹצֶה הוֹכִיחַ סוֹפוֹ עַל תְּחִלָּתוֹ וְלֹא קָנָה אוֹתָהּ וּבִרְשׁוּת בְּעָלִים הָרִאשׁוֹנִים הִיא קַיֶּמֶת עֲדַיִן:","רְאוּבֵן שֶׁרָצָה לִתֵּן מֵאָה דִּינָרִין לְשִׁמְעוֹן וְשָׁלַח לוֹ הַמֵּאָה עַל יְדֵי לֵוִי. אִם אָמַר לוֹ זְכֵה בְּמֵאָה זוּז לְשִׁמְעוֹן. אוֹ תֵּן מֵאָה זוּז לְשִׁמְעוֹן. אֵינוֹ יָכוֹל לַחְזֹר בּוֹ. אֲבָל אִם אָמַר לוֹ הוֹלֵךְ מֵאָה זוּז לְשִׁמְעוֹן יָכוֹל לַחְזֹר בּוֹ עַד שֶׁיַּגִּיעַ הַמֵּאָה לְיַד שִׁמְעוֹן:","הָלַךְ לֵוִי בְּמֵאָה זוּז שֶׁנִּשְׁתַּלְּחוּ עִמּוֹ לְהוֹלִיכָן לְשִׁמְעוֹן וּבִקֵּשׁ שִׁמְעוֹן וְלֹא מְצָאָהוּ יַחְזִיר לִרְאוּבֵן. מֵת שִׁמְעוֹן בְּחַיֵּי רְאוּבֵן יַחְזִיר לִרְאוּבֵן אוֹ לְיוֹרְשָׁיו. מֵת רְאוּבֵן בְּחַיֵּי שִׁמְעוֹן יִתֵּן הַמֵּאָה לְשִׁמְעוֹן אוֹ לְיוֹרְשָׁיו שֶׁמִּצְוָה לְקַיֵּם דִּבְרֵי הַמֵּת וְאַף עַל פִּי שֶׁאָמַר הַדְּבָרִים וְהוּא בָּרִיא. שֶׁהֲרֵי הַמֵּאָה בְּיָדוֹ שֶׁל שָׁלִיחַ עֲדַיִן:","אֵין אָדָם זוֹכֶה בְּמַתָּנָה לַחֲבֵרוֹ עַד שֶׁיִּהְיֶה הַזּוֹכֶה גָּדוֹל וּבֶן דַּעַת. וְאֶחָד אִישׁ וְאֶחָד אִשָּׁה וַאֲפִלּוּ אֵשֶׁת אִישׁ וְעֶבֶד וְשִׁפְחָה. אֲבָל הָעַכּוּ\"ם אֵינוֹ זוֹכֶה הוֹאִיל וְאֵין רָאוּי לִשְׁלִיחוּת לְעוֹלָם כָּךְ אֵינוֹ זוֹכֶה לְיִשְׂרָאֵל. וּכְשֵׁם שֶׁאֵין יִשְׂרָאֵל נַעֲשֶׂה שָׁלִיחַ לְעַכּוּ\"ם כָּךְ אֵינוֹ זוֹכֶה לְעַכּוּ\"ם:","קָטָן שֶׁנּוֹתְנִין לוֹ צְרוֹר וְזוֹרְקוֹ אֱגוֹז וְנוֹטְלוֹ זוֹכֶה לְעַצְמוֹ וְאֵינוֹ זוֹכֶה לַאֲחֵרִים. פָּחוֹת מִזֶּה לֹא זָכָה לְעַצְמוֹ וְלֹא לַאֲחֵרִים. וְכֵן הַשּׁוֹטֶה אֵינוֹ זוֹכֶה לֹא לוֹ וְלֹא לַאֲחֵרִים. וְהַמְזַכֶּה לְשׁוֹטֶה עַל יְדֵי בֶּן דַּעַת זָכָה. אֲבָל הַחֵרֵשׁ זוֹכֶה לְעַצְמוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת גְּזֵלָה:","זָכִין לְקָטָן אֲפִלּוּ בֶּן יוֹם אֶחָד. וּלְגָדוֹל בֵּין בְּפָנָיו בֵּין שֶׁלֹּא בְּפָנָיו. וַחֲצֵרוֹ שֶׁל אָדָם קוֹנָה לוֹ שֶׁלֹּא מִדַּעְתּוֹ אַף עַל פִּי שֶׁאֵינוֹ עוֹמֵד שָׁם כֵּיוָן שֶׁהִגִּיעַ הַמַּתָּנָה לַחֲצֵרוֹ כְּאִלּוּ זָכָה בָּהּ אַחֵר:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּחָצֵר הַמִּשְׁתַּמֶּרֶת. אֲבָל בְּחָצֵר שֶׁאֵינָהּ מִשְׁתַּמֶּרֶת כְּגוֹן שָׂדֵהוּ וְחֻרְבָּתוֹ עַד שֶׁיִּהְיֶה עוֹמֵד בְּצִדָּהּ וְיֹאמַר זָכְתָה לִי שָׂדִי. וְכֵן אַרְבַּע אַמּוֹת שֶׁל אָדָם שֶׁהוּא עוֹמֵד בְּצִדָּן קוֹנִין לוֹ בְּסִמְטָא אוֹ בְּצִדֵּי רְשׁוּת הָרַבִּים אוֹ בְּחָצֵר שֶׁאֵין לָהּ בְּעָלִים. אֲבָל בִּרְשׁוּת הָרַבִּים אוֹ בִּשְׂדֵה חֲבֵרוֹ אֵינוֹ זוֹכֶה עַד שֶׁיַּגִּיעַ מַתָּנָה לְיָדוֹ. וּקְטַנָּה תִּזְכֶּה לָהּ חֲצֵרָהּ וְאַרְבַּע אַמּוֹת שֶׁלָּהּ. אֲבָל הַקָּטָן אֵינוֹ זוֹכֶה עַד שֶׁתַּגִּיעַ מַתָּנָה לְיָדוֹ אוֹ עַד שֶׁיִּזְכֶּה לוֹ אַחֵר:","הַמַּתָּנָה כְּגֵט, שֶׁאֵין אָדָם יָכוֹל לִמְסֹר דְּבָרִים לְשָׁלִיחַ. כֵּיצַד. אָמַר לִשְׁלֹשָׁה אִמְרוּ לִפְלוֹנִי וּפְלוֹנִי שֶׁיִּכְתְּבוּ וְיַחְתְּמוּ בִּשְׁטַר מַתָּנָה וְיִתְּנוּהָ לִפְלוֹנִי אֵין זֶה כְּלוּם. וְאִם אָמְרוּ לְאוֹתָן הָעֵדִים וְכָתְבוּ וְנָתְנוּ לַמְקַבֵּל לֹא קָנָה. וְכֵן אִם אָמַר לִשְׁנַיִם כִּתְבוּ וְחִתְמוּ בִּשְׁטַר מַתָּנָה וּתְנוּהוּ לִפְלוֹנִי אֵינָן יְכוֹלִין לוֹמַר לַסּוֹפֵר לִכְתֹּב אֶלָּא הֵן עַצְמָן כּוֹתְבִין כְּמוֹ בְּגֵט:","הַכּוֹתֵב בִּשְׁטָר נָתַתִּי שָׂדֶה פְּלוֹנִית לִפְלוֹנִי. אוֹ שֶׁכָּתַב נְתַתִּיהָ לוֹ אוֹ הֲרֵי הִיא שֶׁלּוֹ. הֲרֵי זוֹכֶה בָּהּ כְּשֶׁיַּגִּיעַ הַשְּׁטָר לְיָדוֹ. אֲבָל אִם כָּתַב בַּשְּׁטָר אֶתְּנֶנָּה לוֹ. אַף עַל פִּי שֶׁהֵעִידוּ עָלָיו הָעֵדִים. לֹא זָכָה הַמְקַבֵּל עַד שֶׁיֹּאמַר לָעֵדִים כִּתְבוּ שְׁטַר מַתָּנָה וּתְנוּ לוֹ וְכוֹתְבִין וְנוֹתְנִין לוֹ. שֶׁאֵין הַמְקַבֵּל זוֹכֶה עַד שֶׁיַּגִּיעַ שְׁטַר הַמַּתָּנָה לְיָדוֹ אוֹ עַד שֶׁיִּזְכֶּה לוֹ בּוֹ עַל יְדֵי אֲחֵרִים כְּמוֹ שֶׁבֵּאַרְנוּ:","הָאוֹמֵר נָתַתִּי שָׂדֶה פְּלוֹנִית לִפְלוֹנִי וְהוּא אוֹמֵר לֹא נָתַן לִי. חוֹשְׁשִׁין שֶׁמָּא זִכָּה לוֹ עַל יְדֵי אַחֵר. אֲבָל אִם אָמַר כָּתַבְתִּי וְנָתַתִּי לוֹ וְהוּא אוֹמֵר לֹא כָּתַב וְלֹא נָתַן לִי. אִם הַמְקַבֵּל מַתָּנָה הוּא שֶׁאָמַר כֵּן. הוֹדָאַת בַּעַל דִּין כְּמֵאָה עֵדִים הוּא וְהַנּוֹתֵן אוֹכֵל פֵּרוֹת שָׂדֵהוּ. וְאִם בֶּן הַמְקַבֵּל הוּא שֶׁאָמַר לֹא נָתַתָּ לְאָבִי שָׂדֶה זוֹ וְהוּא אוֹמֵר כָּתַבְתִּי וְנָתַתִּי לוֹ. מַנִּיחִין אֶת הַפֵּרוֹת עַל יְדֵי שָׁלִישׁ עַד שֶׁיִּוָּדַע הַדָּבָר הֵיאַךְ הוּא:","מְקַבֵּל מַתָּנָה שֶׁטָּעַן וְאָמַר זוֹ שֶׁתַּחַת יָדִי אֵינָהּ מַתָּנָה בְּיָדִי אֶלָּא שׁוֹמֵר אֲנִי עָלֶיהָ וְכַיּוֹצֵא בּוֹ. אוֹ שֶׁאָמַר בְּטֵלָה הָיְתָה מִתְּחִלָּתָהּ לְפִי שֶׁלֹּא קִבַּלְתִּיהָ אוֹ בְּעַל כָּרְחִי בְּאֹנֶס אוֹ בְּטָעוּת וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ דְּבָרָיו קַיָּמִין. וְנִשְׁבָּע עַל זֶה שְׁבוּעַת הֶסֵּת וְתַחְזֹר לִבְעָלֶיהָ:","טָעַן הַנּוֹתֵן וְאָמַר שׁוֹמֵר אַתָּה עָלֶיהָ אוֹ שֶׁאָמַר שֶׁלֹּא מִדַּעְתִּי נְתַתִּיהָ אוֹ גְּזוּלָה הִיא בְּיָדְךָ וְזֶה אוֹמֵר אַתָּה נָתַתָּ לִי. נִשְׁבָּע הַמְקַבֵּל שְׁבוּעַת הֶסֵּת וְנִפְטָר:"],"Mishneh Torah, Paschal Offering 6":["אֵי זֶהוּ טָמֵא שֶׁנִּדְחֶה לְפֶסַח שֵׁנִי. כָּל מִי שֶׁאֵינוֹ יָכוֹל לֶאֱכל אֶת הַפֶּסַח בְּלֵילֵי ט\"ו בְּנִיסָן מִפְּנֵי טֻמְאָתוֹ כְּגוֹן זָבִים וְזָבוֹת נִדּוֹת וְיוֹלְדוֹת וּבוֹעֲלֵי נִדּוֹת. אֲבָל הַנּוֹגֵעַ בִּנְבֵלָה וְשֶׁרֶץ וְכַיּוֹצֵא בָּהֶן בְּיוֹם אַרְבָּעָה עָשָׂר הֲרֵי זֶה טוֹבֵל וְשׁוֹחֲטִין עָלָיו אַחַר שֶׁיִּטְבּל. וְלָעֶרֶב כְּשֶׁיַּעֲרִיב שִׁמְשׁוֹ אוֹכֵל אֶת הַפֶּסַח:","טְמֵא מֵת שֶׁחָל שְׁבִיעִי שֶׁלּוֹ לִהְיוֹת בְּאַרְבָּעָה עָשָׂר אַף עַל פִּי שֶׁטָּבַל וְהֻזָּה עָלָיו וַהֲרֵי הוּא רָאוּי לֶאֱכל קָדָשִׁים לָעֶרֶב. אֵין שׁוֹחֲטִין עָלָיו אֶלָּא נִדְחֶה לְפֶסַח שֵׁנִי. שֶׁנֶּאֱמַר (במדבר ט ו) \"וַיְהִי אֲנָשִׁים אֲשֶׁר הָיוּ טְמֵאִים לְנֶפֶשׁ אָדָם וְלֹא יָכְלוּ לַעֲשֹׂת הַפֶּסַח בַּיּוֹם הַהוּא\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁשְּׁבִיעִי שֶׁלָּהֶן הָיָה וְעַל זֶה שָׁאֲלוּ אִם יִשָּׁחֵט עֲלֵיהֶן וְהֵם יֹאכְלוּ לָעֶרֶב וּפֵרֵשׁ לָהֶן שֶׁאֵין שׁוֹחֲטִין עֲלֵיהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁנִּטְמָא בְּטֻמְאוֹת מִן הַמֵּת שֶׁהַנָּזִיר מְגַלֵּחַ עֲלֵיהֶן אֲבָל אִם הָיָה טָמֵא בִּשְׁאָר טֻמְאוֹת מִן הַמֵּת שֶׁאֵין הַנָּזִיר מְגַלֵּחַ עֲלֵיהֶן. שׁוֹחֲטִין עָלָיו בַּשְּׁבִיעִי שֶׁלּוֹ אַחַר שֶׁיִּטְבּל וְיַזֶּה עָלָיו וּכְשֶׁיַּעֲרִיב שִׁמְשׁוֹ אוֹכֵל פִּסְחוֹ:","זָב שֶׁרָאָה שְׁתֵּי רְאִיּוֹת וְסָפַר שִׁבְעָה יָמִים וְטָבַל בַּשְּׁבִיעִי שׁוֹחֲטִין עָלָיו וְהוּא אוֹכֵל לָעֶרֶב. וְאִם רָאָה זוֹב אַחַר שֶׁנִּזְרַק הַדָּם הֲרֵי זֶה פָּטוּר מִלַּעֲשׂוֹת פֶּסַח שֵׁנִי. וְכֵן שׁוֹמֶרֶת יוֹם כְּנֶגֶד יוֹם טוֹבֶלֶת בְּיוֹם הַשִּׁמּוּר כְּמוֹ שֶׁבֵּאַרְנוּ בְּבִיאוֹת אֲסוּרוֹת. וְשׁוֹחֲטִין עָלֶיהָ וְהִיא אוֹכֶלֶת לָעֶרֶב. וְאִם רָאֲתָה דָּם אַחַר שֶׁנִּזְרַק דַּם הַפֶּסַח פְּטוּרָה מִלַּעֲשׂוֹת פֶּסַח שֵׁנִי. וְאֵין שׁוֹחֲטִין עַל הַנִּדָּה בַּשְּׁבִיעִי שֶׁלָּהּ. שֶׁהֲרֵי אֵינָהּ טוֹבֶלֶת עַד לֵיל שְׁמִינִי וְאֵינָהּ רְאוּיָה לֶאֱכל קָדָשִׁים עַד לֵיל תְּשִׁיעִי:","מְחֻסְּרֵי כִּפּוּרִים שֶׁחָל יוֹם הֲבָאַת קָרְבְּנוֹתֵיהֶן בְּאַרְבָּעָה עָשָׂר. שׁוֹחֲטִין עֲלֵיהֶן וּמַקְרִיבִין קָרְבְּנוֹתֵיהֶן בְּאַרְבָּעָה עָשָׂר בְּנִיסָן בֵּין קֹדֶם שְׁחִיטַת הַפֶּסַח בֵּין אַחַר שְׁחִיטָתוֹ. וְאוֹכְלִין פִּסְחֵיהֶן לָעֶרֶב. וְאֵין שׁוֹחֲטִין עֲלֵיהֶן עַד שֶׁיִּמְסְרוּ קָרְבְּנוֹתֵיהֶן בְּיַד בֵּית דִּין שֶׁמָּא יִפְשְׁעוּ וְלֹא יַקְרִיבוּ אוֹתָם:","מְצֹרָע שֶׁחָל שְׁמִינִי שֶׁלּוֹ לִהְיוֹת בְּאַרְבָּעָה עָשָׂר וְרָאָה קֶרִי בּוֹ בַּיּוֹם הֲרֵי זֶה טוֹבֵל וְנִכְנָס לְעֶזְרַת נָשִׁים וּמֵבִיא קָרְבְּנוֹתָיו. וְאַף עַל פִּי שֶׁטְּבוּל יוֹם אָסוּר לְהִכָּנֵס לְעֶזְרַת נָשִׁים. הוֹאִיל וְאִסּוּרוֹ לְהִכָּנֵס שָׁם מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת בִּיאַת מִקְדָּשׁ. וְיוֹם זֶה הוּא יוֹם הַקְרָבַת הַפֶּסַח בְּמוֹעֲדוֹ. יָבוֹא עֲשֵׂה שֶׁיֵּשׁ בּוֹ כָּרֵת וְיִדְחֶה אִסּוּר שֶׁל דִּבְרֵיהֶם:","טְמֵא מֵת שֶׁחָל שְׁבִיעִי שֶׁלּוֹ לִהְיוֹת בְּשַׁבָּת. אֵין מַזִּין עָלָיו אֶלָּא לְמָחָר. וַאֲפִלּוּ חָל שְׁבִיעִי שֶׁלּוֹ לִהְיוֹת בִּשְׁלֹשָׁה עָשָׂר בְּנִיסָן וְהוּא שַׁבָּת יִדָּחֶה לְיוֹם אַרְבָּעָה עָשָׂר. וּמַזִּין עָלָיו וְאֵין שׁוֹחֲטִין עָלָיו כְּמוֹ שֶׁבֵּאַרְנוּ. אֶלָּא יִדָּחֶה לְפֶסַח שֵׁנִי. וַהֲלֹא אִסּוּר הַזָּיָה בְּשַׁבָּת מִשּׁוּם שְׁבוּת וְהַפֶּסַח בְּכָרֵת וְהֵיאַךְ יַעֲמִידוּ דִּבְרֵיהֶם בִּמְקוֹם כָּרֵת. מִפְּנֵי שֶׁבְּיוֹם שֶׁהוּא אָסוּר בְּהַזָּיָה מִשּׁוּם שְׁבוּת אֵינוֹ זְמַן הַקָּרְבָּן שֶׁחַיָּבִין עָלָיו כָּרֵת. לְפִיכָךְ הֶעֱמִידוּ דִּבְרֵיהֶן בִּמְקוֹמָן אַף עַל פִּי שֶׁהַדָּבָר גּוֹרֵם לֶעָתִיד לָבוֹא לַעֲמֹד בִּמְקוֹם כָּרֵת:","יִשְׂרָאֵל עָרֵל שֶׁמָּל בְּעֶרֶב הַפֶּסַח שׁוֹחֲטִין עָלָיו אַחַר שֶׁמָּל. אֲבָל גֵּר שֶׁנִּתְגַּיֵּר בְּיוֹם אַרְבָּעָה עָשָׂר וּמָל וְטָבַל אֵין שׁוֹחֲטִין עָלָיו שֶׁאֵינוֹ אוֹכֵל לָעֶרֶב וַהֲרֵי הוּא כְּפוֹרֵשׁ מִן הַקֶּבֶר שֶׁצָּרִיךְ שִׁבְעָה יָמִים וְאַחַר כָּךְ יִטְהַר. גְּזֵרָה שֶׁמָּא יִטָּמֵא גֵּר זֶה לְמֵת לְשָׁנָה הַבָּאָה בְּיוֹם אַרְבָּעָה עָשָׂר וְיִטְבּל וְיֹאכַל לָעֶרֶב וְיֹאמַר אֶשְׁתָּקַד כָּךְ עָשׂוּ לִי יִשְׂרָאֵל כְּשֶׁמַּלְתִּי טָבַלְתִּי וְאָכַלְתִּי לָעֶרֶב. וַהֲלֹא גְּזֵרָה זוֹ מִדִּבְרֵיהֶם וּפֶסַח בְּכָרֵת וְהֵיאַךְ הֶעֱמִידוּ דִּבְרֵיהֶם בִּמְקוֹם כָּרֵת בְּיוֹם הַקָּרְבָּן שֶׁהוּא יוֹם אַרְבָּעָה עָשָׂר. מִפְּנֵי שֶׁאֵין הַגֵּר מִתְחַיֵּב בְּמִצְוֹת עַד שֶׁיָּמוּל וְיִטְבּל. וְאֵינוֹ טוֹבֵל עַד שֶׁיֵּרָפֵא מִן הַמִּילָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן הַגֵּרוּת. לְפִיכָךְ הֶעֱמִידוּ דִּבְרֵיהֶם בְּמָקוֹם זֶה. שֶׁהֲרֵי זֶה הַמָּל יֵשׁ לוֹ שֶׁלֹּא לִטְבּל עַד שֶׁיַּבְרִיא וְלֹא יָבוֹא לִידֵי חִיּוּב כְּלָל:","מִי שֶׁבָּא בְּבֵית הַפְּרָס הֲרֵי זֶה מְנַפֵּחַ וְהוֹלֵךְ וְאִם לֹא מָצָא עֶצֶם וְלֹא נִטְמָא שׁוֹחֵט וְאוֹכֵל פִּסְחוֹ וְאַף עַל פִּי שֶׁהָלַךְ בְּבֵית הַפְּרָס. שֶׁטֻּמְאַת בֵּית הַפְּרָס מִדִּבְרֵיהֶן כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת טְמֵא מֵת וְלֹא הֶעֱמִידוּ דִּבְרֵיהֶם בִּמְקוֹם כָּרֵת כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן בֵּית הַפְּרָס שֶׁנִּדּוֹשׁ טָהוֹר לָעוֹשֶׂה פֶּסַח:","הָאוֹנֵן רָאוּי לֶאֱכל הַפֶּסַח לָעֶרֶב. מִפְּנֵי שֶׁאֲנִינוּת לַיְלָה מִדִּבְרֵיהֶם לֹא הֶעֱמִידוּ דִּבְרֵיהֶם בִּמְקוֹם כָּרֵת בְּדָבָר זֶה אֶלָּא שׁוֹחֲטִין עָלָיו וְטוֹבֵל וְאַחַר כָּךְ אוֹכֵל כְּדֵי שֶׁיִּפְרשׁ מֵאֲנִינוּתוֹ וְלֹא יַסִּיחַ דַּעְתּוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמֵּת לוֹ הַמֵּת אַחַר חֲצוֹת שֶׁכְּבָר נִתְחַיֵּב בְּקָרְבַּן פֶּסַח. אֲבָל אִם מֵת לוֹ הַמֵּת קֹדֶם חֲצוֹת אֵין שׁוֹחֲטִין עָלָיו אֶלָּא יִדָּחֶה לַשֵּׁנִי. וְאִם שָׁחֲטוּ עָלָיו וְזָרְקוּ הַדָּם טוֹבֵל וְאוֹכֵל לָעֶרֶב. מֵת לוֹ מֵת בִּשְׁלֹשָׁה עָשָׂר וּקְבָרוֹ בְּאַרְבָּעָה עָשָׂר הֲרֵי הוּא בְּיוֹם קְבוּרָה אוֹנֵן מִדִּבְרֵיהֶם וְאֵינוֹ תּוֹפֵס לֵילוֹ מִדִּבְרֵיהֶם. לְפִיכָךְ שׁוֹחֲטִין עָלָיו וְטוֹבֵל וְאוֹכֵל לָעֶרֶב אַף בִּשְׁאָר הַקֳדָשִׁים. וְיוֹם שְׁמוּעָה וְיוֹם לִקּוּט עֲצָמוֹת הֲרֵי הוּא כְּיוֹם קְבוּרָה. לְפִיכָךְ מִי שֶׁלִּקֵּט עַצְמוֹת מֵתוֹ בְּיוֹם אַרְבָּעָה עָשָׂר אוֹ שֶׁשָּׁמַע שֶׁמֵּת לוֹ מֵת שׁוֹחֲטִין עָלָיו וְטוֹבֵל וְאוֹכֵל בְּקָדָשִׁים לָעֶרֶב:","מִי שֶׁחוֹפֵר בְּגַל לְבַקֵּשׁ עַל הַמֵּת אֵין שׁוֹחֲטִין עָלָיו שֶׁמָּא יִמָּצֵא שָׁם הַמֵּת בַּגַּל וַהֲרֵי הוּא טָמֵא בִּשְׁעַת שְׁחִיטָה. שָׁחֲטוּ עָלָיו וְלֹא נִמְצָא שָׁם מֵת הֲרֵי זֶה אוֹכֵל לָעֶרֶב. נִמְצָא שָׁם מֵת אַחַר שֶׁנִּזְרַק הַדָּם. אִם נוֹדַע לוֹ בְּוַדַּאי שֶׁהָיָה טָמֵא בִּשְׁעַת זְרִיקַת הַדָּם כְּגוֹן שֶׁהָיָה גַּל עָגל הֲרֵי זֶה חַיָּב בְּפֶסַח שֵׁנִי. וְאִם סָפֵק הַדָּבָר וְשֶׁמָּא לֹא הָיָה עוֹמֵד עַל הַטֻּמְאָה בְּעֵת זְרִיקָה וְלֹא נִטְמָא אֶלָּא אַחַר זְרִיקָה הֲרֵי זֶה פָּטוּר מִפֶּסַח שֵׁנִי:","מִי שֶׁעָבַר בַּדֶּרֶךְ וּמָצָא מֵת מֻשְׁכָּב לְרָחְבָּהּ שֶׁל דֶּרֶךְ. אִם הָיָה הַמֵּת טֻמְאַת הַתְּהוֹם אַף עַל פִּי שֶׁהוּא טָמֵא לִתְרוּמָה הֲרֵי זֶה טָהוֹר לְפֶסַח וְשׁוֹחֵט וְאוֹכֵל פִּסְחוֹ וְאַף עַל פִּי שֶׁאֶפְשָׁר שֶׁנָּגַע. הוֹאִיל וְהִיא טֻמְאַת הַתְּהוֹם טָהוֹר לְפֶסַח. וְאַף עַל פִּי שֶׁהַמֵּת שָׁלֵם וְהוּא מִן הַקָּצֶה אֶל הַקָּצֶה הֲרֵי זֶה עוֹשֶׂה פִּסְחוֹ עַד שֶׁיֵּדַע בְּוַדַּאי שֶׁנִּטְמָא בּוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה מְהַלֵּךְ בְּרַגְלָיו שֶׁהֲרֵי אֶפְשָׁר שֶׁלֹּא יִגַּע אֲבָל אִם הָיָה רוֹכֵב אוֹ טָעוּן מַשָּׂא הֲרֵי זֶה טָמֵא אַף עַל פִּי שֶׁהִיא טֻמְאַת הַתְּהוֹם. לְפִי שֶׁאִי אֶפְשָׁר שֶׁלֹּא יִגַּע וְשֶׁלֹּא יָסִיט וְשֶׁלֹּא יַאֲהִיל. וּכְבָר בֵּאַרְנוּ טֻמְאַת הַתְּהוֹם בְּהִלְכוֹת נְזִירוּת:","מִי שֶׁעָשָׂה פֶּסַח בְּחֶזְקַת שֶׁהוּא טָהוֹר וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁהָיָה טָמֵא בְּטֻמְאַת הַתְּהוֹם אֵינוֹ חַיָּב בְּפֶסַח שֵׁנִי. וְדָבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה. אֲבָל אִם נוֹדַע לוֹ שֶׁהָיָה טָמֵא בְּטֻמְאָה יְדוּעָה חַיָּב בְּפֶסַח שֵׁנִי:","מִי שֶׁנִּטְמָא בְּמֵת וְהֻזָּה עָלָיו שְׁלִישִׁי וּשְׁבִיעִי וּבַשְּׁבִיעִי שֶׁלּוֹ נִטְמָא בְּקֶבֶר הַתְּהוֹם וְלֹא יָדַע וְעָשָׂה פֶּסַח בְּחֶזְקַת שֶׁהוּא טָהוֹר וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁהוּא טָמֵא בְּטֻמְאַת הַתְּהוֹם אֵינוֹ חַיָּב בְּפֶסַח שֵׁנִי. שֶׁכֵּיוָן שֶׁטָּבַל בַּשְּׁבִיעִי פָּסְקָה טֻמְאָה הָרִאשׁוֹנָה. אֲבָל אִם נִטְמָא בְּטֻמְאַת הַתְּהוֹם בַּשִּׁשִּׁי לְטֻמְאָתוֹ וְלֹא יָדַע עַד שֶׁעָשָׂה הַפֶּסַח. הֲרֵי זֶה חַיָּב בְּפֶסַח שֵׁנִי שֶׁחֶזְקַת הַטָּמֵא טָמֵא עַד שֶׁיִּהְיֶה טָהוֹר וַדַּאי שֶׁרַגְלַיִם לַדָּבָר:"],"Mishneh Torah, Plaintiff and Defendant 2":["כָּל חָשׁוּד עַל הַשְּׁבוּעָה אֵין מַשְׁבִּיעִין אוֹתוֹ לֹא שְׁבוּעַת הַתּוֹרָה וְלֹא שְׁבוּעָה מִדִּבְרֵיהֶם וְלֹא שְׁבוּעַת הֶסֵּת. וַאֲפִלּוּ רָצָה הַתּוֹבֵעַ אֵין שׁוֹמְעִין לוֹ:","אֶחָד הַנִּשְׁבָּע לַשֶּׁקֶר שְׁבוּעַת בִּטּוּי. אוֹ שְׁבוּעַת עֵדוּת. אוֹ שְׁבוּעַת הַפִּקָּדוֹן. אוֹ שְׁבוּעַת שָׁוְא. הֲרֵי הוּא חָשׁוּד עַל הַשְּׁבוּעָה. וְכֵן כָּל הַפָּסוּל לְעֵדוּת מִשּׁוּם עֲבֵרָה. בֵּין פַּסְלָנוּת שֶׁל תּוֹרָה כְּגוֹן בַּעֲלֵי רִבִּית וְאוֹכְלֵי נְבֵלוֹת וְגַזְלָנִין. בֵּין פַּסְלָנוּת שֶׁל דִּבְרֵיהֶם כְּגוֹן מִשְׂחָק בְּקֻבִּיָּא וּמַפְרִיחֵי יוֹנִים. הֲרֵי הוּא חָשׁוּד עַל הַשְּׁבוּעָה וְאֵין מַשְׁבִּיעִין אוֹתוֹ:","אֵין אָדָם נַעֲשֶׂה חָשׁוּד עַד שֶׁיָּבוֹאוּ עָלָיו עֵדִים שֶׁהוּא עָבַר עֲבֵרָה שֶׁנִּפְסַל בָּהּ. אֲבָל הַמּוֹדֶה מִפִּי עַצְמוֹ שֶׁהוּא חָשׁוּד וְשֶׁעָבַר עֲבֵרָה שֶׁנִּפְסַל בָּהּ. אַף עַל פִּי שֶׁחוֹשְׁשִׁין לוֹ וְאֵין רָאוּי לַעֲשׂוֹתוֹ עֵד בַּתְּחִלָּה. אִם נִתְחַיֵּב שְׁבוּעָה מַשְׁבִּיעִין אוֹתוֹ שֶׁהֲרֵי אוֹמְרִים לוֹ אִם אֱמֶת אַתָּה אוֹמֵר הִשָּׁבַע וְלֹא מִפְּנֵי שֶׁעָבַרְתָּ עֲבֵרָה אָסוּר לְךָ לְהִשָּׁבַע בֶּאֱמֶת. וְאִם שֶׁקֶר אַתָּה אוֹמֵר הוֹדֵה לְבַעַל דִּינְךָ. אֲבָל הַנֶּחְשָׁד בְּעֵדִים אֵין אָנוּ מַאֲמִינִים אוֹתוֹ שֶׁיִּשָּׁבַע:","תַּקָּנַת חֲכָמִים הִיא שֶׁכָּל הַמְחֻיָּב שְׁבוּעָה מִן הַתּוֹרָה עַל טַעֲנַת וַדַּאי. אִם הָיָה חָשׁוּד הֲרֵי הַתּוֹבֵעַ נִשְׁבָּע מִדִּבְרֵיהֶם וְנוֹטֵל מַה שֶּׁטָּעַן. הָיוּ שְׁנֵיהֶם חֲשׁוּדִין חָזְרָה שְׁבוּעָה לַמְחֻיָּב לָהּ שֶׁהוּא הַנִּתְבָּע וּמִתּוֹךְ שֶׁאֵינוֹ יָכוֹל לִשָּׁבַע מְשַׁלֵּם. הָיָה הֶחָשׁוּד שׁוֹמֵר וְטָעַן שֶׁאָבַד הַפִּקָּדוֹן אוֹ נִגְנַב שֶׁכְּנֶגְדוֹ אֵינוֹ יָכוֹל לְהִשָּׁבַע וְלִטּל שֶׁהֲרֵי אֵינוֹ טוֹעֲנוֹ וַדַּאי שֶׁאֲכָלוֹ. לְפִיכָךְ אִם טָעַן בַּעַל הַפִּקָּדוֹן וְאָמַר בְּפָנַי שָׁלַח יָד בְּפִקְדוֹנִי אוֹ פָּשַׁע בּוֹ הֲרֵי הַתּוֹבֵעַ נִשְׁבָּע בְּתַקָּנַת חֲכָמִים וְנוֹטֵל:","נִתְחַיֵּב הֶחָשׁוּד שְׁבוּעָה מִדִּבְרֵיהֶם אִם הָיָה מִן הַנִּשְׁבָּעִין וְנוֹטְלִין אֵינוֹ יָכוֹל לְהִשָּׁבַע וְלִטּל אֶלָּא הַנִּתְבָּע שֶׁכְּנֶגְדוֹ יִשָּׁבַע הֶסֵּת וְיִפָּטֵר. וְכֵן פּוֹגֵם שְׁטָרוֹ וְכָל כַּיּוֹצֵא בָּזֶה שֶׁהָיָה חָשׁוּד וְטָעַן הַלּוֶֹה שֶׁפְּרָעוֹ וְאָמַר יִשָּׁבַע לִי הֲרֵי הַנִּתְבָּע נִשְׁבָּע הֶסֵּת וְיִפָּטֵר מִן הַשְּׁטָר:","הָיָה הֶחָשׁוּד מִן הַנִּשְׁבָּעִין בְּטַעֲנַת סָפֵק אֵינוֹ נִשְׁבָּע וְאֵין שֶׁכְּנֶגְדוֹ נִשְׁבָּע לְפִי שֶׁלֹּא נִתְחַיֵּב זֶה שְׁבוּעָה מִן הַתּוֹרָה. וּלְפִי שֶׁאֵין הַתּוֹבֵעַ טוֹעֲנוֹ טַעֲנַת וַדַּאי כְּדֵי שֶׁיִּשָּׁבַע עַל טַעֲנָתוֹ:","נִתְחַיֵּב הֶחָשׁוּד שְׁבוּעַת הֶסֵּת אֵין שֶׁכְּנֶגְדוֹ נִשְׁבָּע וְנוֹטֵל. שֶׁשְּׁבוּעַת הֶסֵּת עַצְמָהּ תַּקָּנָה הִיא וְלֹא עָשׂוּ לָהּ תַּקָּנָה אַחֶרֶת שֶׁיִּשָּׁבַע הַתּוֹבֵעַ אֶלָּא הֲרֵי הַנִּתְבָּע נִפְטָר בְּלֹא שְׁבוּעָה:","מִי שֶׁנִּתְחַיֵּב שְׁבוּעַת הֶסֵּת וְהָיָה הַתּוֹבֵעַ חָשׁוּד. אֵין הַנִּתְבָּע יָכוֹל לַהֲפֹךְ עָלָיו הַשְּׁבוּעָה שֶׁהֲרֵי אֵין יָכוֹל לְהִשָּׁבַע. אֶלָּא יְשַׁלֵּם אוֹ יִשָּׁבַע הֶסֵּת. וְאֵין שׁוֹמְעִין לָזֶה לִתְלוֹת בְּדָבָר שֶׁאִי אֶפְשָׁר. וַהֲרֵי זֶה כְּמִי שֶׁהָפַךְ שְׁבוּעָתוֹ עַל הַקָּטָן שֶׁאֵין שׁוֹמְעִין לוֹ אֶלָּא אוֹ יִשָּׁבַע הֶסֵּת אוֹ יְשַׁלֵּם:","מִי שֶׁנִּתְחַיֵּב שְׁבוּעָה בֵּין שֶׁל תּוֹרָה בֵּין שֶׁל דִּבְרֵיהֶם וְנִשְׁבַּע וְנָטַל אוֹ נִשְׁבַּע וְנִפְטַר. וְאַחַר כָּךְ בָּאוּ עָלָיו עֵדִים שֶׁהוּא חָשׁוּד. אֵין שְׁבוּעָתוֹ שֶׁנִּשְׁבַּע כְּלוּם וְיֵשׁ לְבַעַל דִּינוֹ לְהוֹצִיא מִיָּדוֹ מַה שֶּׁנָּטַל אוֹ יִשָּׁבַע זֶה שֶׁכְּנֶגְדוֹ וְיִטּל מִמֶּנּוּ:","לְעוֹלָם כָּזֶה דָּנִין לֶחָשׁוּד עַד שֶׁיִּלְקֶה בְּבֵית דִּין. אִם הָיוּ עָלָיו עֵדִים שֶׁלָּקָה וְעָשָׂה תְּשׁוּבָה יַחְזֹר לְכַשְׁרוּתוֹ בֵּין לְעֵדוּת בֵּין לִשְׁבוּעָה:","מִי שֶׁטָּעַן עַל חֲבֵרוֹ וְכָפַר בּוֹ וְנִשְׁבַּע בֵּין שְׁבוּעַת הַתּוֹרָה בֵּין שְׁבוּעַת הֶסֵּת. וְאַחַר כָּךְ בָּאוּ עֵדִים וְהֵעִידוּ עָלָיו שֶׁעַל שֶׁקֶר נִשְׁבַּע. הֲרֵי זֶה מְשַׁלֵּם וְהֻחְזַק חָשׁוּד עַל הַשְּׁבוּעָה. וּכְבָר בֵּאַרְנוּ בִּשְׁבוּעוֹת שֶׁכָּל הַנִּשְׁבָּע עַל מָמוֹן חֲבֵרוֹ וְעָשָׂה תְּשׁוּבָה חַיָּב לְהוֹסִיף חֹמֶשׁ:","טְעָנוֹ שֶׁיֵּשׁ לוֹ חוֹב אֶצְלוֹ בְּעֵדִים וְקִנְיָן וְאָמַר כֵּן הָיָה וּפְרַעְתִּיךָ. אוֹ שֶׁאָמַר אֵינִי חַיָּב לְךָ כְּלוּם וְנִשְׁבַּע. וְאַחַר כָּךְ בָּאוּ עֵדֵי הַקִּנְיָן אוֹ הוֹצִיא הַשְּׁטָר וְנִתְקַיֵּם הֲרֵי זֶה מְשַׁלֵּם וְאֵינוֹ חָשׁוּד. שֶׁהֲרֵי לֹא הֱעִידוֹ שֶׁלֹּא פְּרָעוֹ וְלֹא אָמַר הַנִּתְבָּע לֹא הָיוּ דְּבָרִים מֵעוֹלָם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Positive Mitzvot 102":["להיות בגד מנוגע טמא ומטמא."],"Mishneh Torah, Positive Mitzvot 113":["לעשות פרה אדומה להיות אפרה מוכן, שנאמר: \"וְהָיְתָה לַעֲדַת בְּנֵי יִשְׂרָאֵל\" (במדבר יט, ט)."],"Mishneh Torah, Positive Mitzvot 124":["להניח פרט הכרם לפי שבכל אלו נאמר \"לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם\" (ויקרא יט, י) (ויקרא כג, כב) וזו היא מצות עשה שלהם."],"Mishneh Torah, Positive Mitzvot 135":["לשבות מעבודת הארץ, שנאמר: \"בחריש ובקציר, תשבות\" (שמות לד,כא)."],"Mishneh Torah, Positive Mitzvot 146":["לשחוט בהמה חיה ועוף ואחר כך יאכל בשרם, שנאמר: \"וזבחת מבקרך ומצאנך\" (דברים יב,כא)."],"Mishneh Torah, Positive Mitzvot 157":["לספר ביציאת מצריים בלילה הראשון של חג המצות, שנאמר: \"והגדת לבנך\" (שמות יג,ח)."],"Mishneh Torah, Positive Mitzvot 168":["לישב בסוכה שבעת ימים, שנאמר: \"בסוכות תשבו, שבעת ימים\" (ויקרא כג,מב)."],"Mishneh Torah, Positive Mitzvot 179":["לחקור העדים הרבה, שנאמר: \"ודרשת וחקרת ושאלת, היטב\" (דברים יג,טו)."],"Mishneh Torah, Positive Mitzvot 19":["לְבָרַךְ אַחַר הַמָּזוֹן, שֶׁנֶּאֱמָר: \"וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת יְיָ אֱלֹהֶיךָ\" (דברים ח, י)."],"Mishneh Torah, Positive Mitzvot 20":["לִבְנוֹת בֵּית הַבְּחִירָה, שֶׁנֶּאֱמָר: \"וְעָשׂוּ לִי מִקְדָּשׁ\" (שמות כה, ח)."],"Mishneh Torah, Positive Mitzvot 210":["לכבד אב ואם, שנאמר \"כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ\" (שמות כ, יא); (דברים ה, טו)."],"Mishneh Torah, Positive Mitzvot 221":["לעשות ליפת תואר ככתוב, שנאמר: \"וראית, בשביה, אשת, יפת תואר\" (דברים כא,יא)."],"Mishneh Torah, Positive Mitzvot 232":["לדון בעבד עברי כהלכותיו, שנאמר: \"כי תקנה עבד עברי\" (שמות כא,ב)."],"Mishneh Torah, Positive Mitzvot 243":["לדון בדין נושא שכר ושוכר, שנאמר: \"כי ייתן איש אל ריעהו חמור או שור\" (שמות כב,ט)."],"Mishneh Torah, Positive Mitzvot 30":["לְהָרִים הַדֶּשֶׁן מֵעַל הַמִּזְבֵּחַ בְּכָל יוֹם, שֶׁנֶּאֱמָר: \"וְהֵרִים אֶת הַדֶּשֶׁן\" (ויקרא ו, ג)."],"Mishneh Torah, Positive Mitzvot 41":["להוסיף קרבן אחר בכל שבת, שנאמר: \"וּבְיוֹם הַשַּׁבָּת שְׁנֵי כְּבָשִׂים\" (במדבר כח, ט)."],"Mishneh Torah, Positive Mitzvot 52":["לחוג ברגלים, שנאמר: \"שָׁלֹשׁ רְגָלִים תָּחֹג לִי\" (שמות כג, יד)."],"Mishneh Torah, Positive Mitzvot 63":["מעשה העולה, שנאמר: \"אִם עוֹלָה קָרְבָּנוֹ\" (ויקרא א, ג)."],"Mishneh Torah, Positive Mitzvot 74":["להקריב הזב קרבן אחר שיטהר, שנאמר: \"וכי יטהר הזב, מזובו\" (ויקרא טו,יג)."],"Mishneh Torah, Positive Mitzvot 85":["להיטפל בהבאת הקרבנות מחוצה לארץ לבית הבחירה, שנאמר: \"רק קודשיך אשר יהיו לך, ונדריך, תישא ובאת\" (דברים יב,כו); מפי השמועה למדו שאינו מדבר אלא בקודשי חוצה לארץ."],"Mishneh Torah, Positive Mitzvot 96":["להיות כל נוגע בנבילה טמא, שנאמר \"וכי ימות מן הבהמה\" (ויקרא יא, לט)."],"Mishneh Torah, Prayer and the Priestly Blessing 3":["תְּפִלַת הַשַּׁחַר מִצְוָתָהּ שֶׁיַּתְחִיל לְהִתְפַּלֵּל עִם הָנֵץ הַחַמָּה וּזְמַנָּהּ עַד סוֹף שָׁעָה רְבִיעִית שֶׁהִיא שְׁלִישִׁית הַיּוֹם. וְאִם עָבַר אוֹ טָעָה וְהִתְפַּלֵּל אַחַר אַרְבַּע עַד חֲצוֹת הַיּוֹם יָצָא יְדֵי חוֹבַת תְּפִלָּה. אֲבָל לֹא יָצָא יְדֵי חוֹבַת תְּפִלָּה בִּזְמַנָּהּ. שֶׁכְּשֵׁם שֶׁתְּפִלָּה מִצְוָה מִן הַתּוֹרָה כָּךְ מִצְוָה מִדִּבְרֵיהֶם לְהִתְפַּלֵּל אוֹתָהּ בִּזְמַנָּהּ כְּמוֹ שֶׁתִּקְנוּ לָנוּ חֲכָמִים וּנְבִיאִים:","כְּבָר אָמַרְנוּ שֶׁתְּפִלַּת הַמִּנְחָה כְּנֶגֶד תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם תִּקְּנוּ זְמַנָּהּ. וּלְפִי שֶׁהָיָה הַתָּמִיד קָרֵב בְּכָל יוֹם בְּתֵשַׁע שָׁעוֹת וּמֶחֱצָה תִּקְּנוּ זְמַנָּהּ מִתֵּשַׁע שָׁעוֹת וּמֶחֱצָה וְהִיא הַנִּקְרֵאת מִנְחָה קְטַנָּה. וּלְפִי שֶׁבְּעֶרֶב הַפֶּסַח שֶׁחָל לִהְיוֹת בְּעֶרֶב שַׁבָּת הָיוּ שׁוֹחֲטִין אֶת הַתָּמִיד בְּשֵׁשׁ שָׁעוֹת וּמֶחֱצָה, אָמְרוּ שֶׁהַמִּתְפַּלֵּל מֵאַחַר שֵׁשׁ שָׁעוֹת וּמֶחֱצָה יָצָא. וּמִשֶּׁהִגִּיעַ זְמַן זֶה הִגִּיעַ זְמַן חִיּוּבָהּ וְזוֹ הִיא הַנִּקְרֵאת מִנְחָה גְּדוֹלָה:","נָהֲגוּ אֲנָשִׁים הַרְבֵּה לְהִתְפַּלֵּל גְּדוֹלָה וּקְטַנָּה וְהָאַחַת רְשׁוּת. וְהוֹרוּ מִקְצָת הַגְּאוֹנִים שֶׁאֵין רָאוּי לְהִתְפַּלֵּל רְשׁוּת אֶלָּא הַגְּדוֹלָה. וְכֵן הַדִּין נוֹתֵן מִפְּנֵי שֶׁהִיא כְּנֶגֶד דָּבָר שֶׁאֵינוֹ תָּדִיר בְּכָל יוֹם. וְאִם הִתְפַּלֵּל הַגְּדוֹלָה חוֹבָה לֹא יִתְפַּלֵּל קְטַנָּה אֶלָּא רְשׁוּת:","הָא לָמַדְתָּ שֶׁזְּמַן מִנְחָה גְּדוֹלָה מִשֵּׁשׁ שָׁעוֹת וּמֶחֱצָה עַד תֵּשַׁע שָׁעוֹת וּמֶחֱצָה. וּזְמַן מִנְחָה קְטַנָּה מִתֵּשַׁע שָׁעוֹת וּמֶחֱצָה עַד שֶׁיִּשָּׁאֵר מִן הַיּוֹם שָׁעָה וּרְבִיעַ. וְיֵשׁ לוֹ לְהִתְפַּלֵּל אוֹתָהּ עַד שֶׁתִּשְׁקַע הַחַמָּה:","תְּפִלַּת הַמּוּסָפִין זְמַנָּהּ אַחַר תְּפִלַּת הַשַּׁחַר עַד שֶׁבַע שָׁעוֹת בַּיּוֹם. וְהַמִּתְפַּלֵּל אוֹתָהּ אַחַר שֶׁבַע שָׁעוֹת אַף עַל פִּי שֶׁפָּשַׁע יָצָא יְדֵי חוֹבָתוֹ מִפְּנֵי שֶׁזְּמַנָּהּ כָּל הַיּוֹם:","תְּפִלַּת הָעֶרֶב אַף עַל פִּי שֶׁאֵינָהּ חוֹבָה הַמִּתְפַּלֵּל אוֹתָהּ זְמַנָּהּ מִתְּחִלַּת הַלַּיְלָה עַד שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר. ותְּפִלַּת נְעִילָה זְמַנָּה כְּדֵי שֶׁיַּשְׁלִים אוֹתָהּ סָמוּךְ לִשְׁקִיעַת הַחַמָּה:","הַמִּתְפַּלֵּל תְּפִלָּה קֹדֶם זְמַנָּהּ לֹא יָצָא יְדֵי חוֹבָתוֹ וְחוֹזֵר וּמִתְפַּלֵּל אוֹתָהּ בִּזְמַנָּהּ. וְאִם הִתְפַּלֵּל תְּפִלַּת שַׁחֲרִית בִּשְׁעַת הַדְּחָק אַחַר שֶׁעָלָה עַמּוּד הַשַּׁחַר יָצָא. וְיֵשׁ לוֹ לְהִתְפַּלֵּל תְּפִלַּת עַרְבִית שֶׁל לֵילֵי שַׁבָּת בְּעֶרֶב שַׁבָּת קֹדֶם שֶׁתִּשְׁקַע הַחַמָּה. וְכֵן יִתְפַּלֵּל עַרְבִית שֶׁל מוֹצָאֵי שַׁבָּת בְּשַׁבָּת לְפִי שֶׁתְּפִלַּת עַרְבִית רְשׁוּת אֵין מְדַקְדְּקִין בִּזְמַנָּהּ. וּבִלְבַד שֶׁיִּקְרָא קְרִיאַת שְׁמַע בִּזְמַנָּהּ אַחַר צֵאת הַכּוֹכָבִים:","כָּל מִי שֶׁעָבַר עָלָיו זְמַן תְּפִלָּה וְלֹא הִתְפַּלֵּל בְּמֵזִיד אֵין לוֹ תַּקָּנָה וְאֵינוֹ מְשַׁלֵּם. בְּשׁוֹגֵג אוֹ שֶׁהָיָה אָנוּס אוֹ טָרוּד מְשַׁלֵּם אוֹתָהּ תְּפִלָּה בִּזְמַן תְּפִלָּה הַסְּמוּכָה לָהּ. וּמַקְדִּים תְּפִלָּה שֶׁבִּזְמַנָּהּ וְאַחֲרֶיהָ מִתְפַּלֵּל אֶת הַתַּשְׁלוּמִין:","כֵּיצַד. טָעָה וְלֹא הִתְפַּלֵּל שַׁחֲרִית וְעָבַר חֲצִי הַיּוֹם יִתְפַּלֵּל מִנְחָה שְׁתַּיִם. רִאשׁוֹנָה תְּפִלַּת מִנְחָה וְהַשְּׁנִיָּה תַּשְׁלוּמֵי שַׁחֲרִית. טָעָה וְלֹא הִתְפַּלֵּל מִנְחָה עַד שֶׁשָּׁקְעָה הַחַמָּה יִתְפַּלֵּל עַרְבִית שְׁתַּיִם. רִאשׁוֹנָה עַרְבִית וּשְׁנִיָּה תַּשְׁלוּמֵי מִנְחָה. טָעָה וְלֹא הִתְפַּלֵּל עַרְבִית עַד שֶׁעָלָה עַמּוּד הַשַּׁחַר מִתְפַּלֵּל שַׁחֲרִית שְׁתַּיִם. רִאשׁוֹנָה שַׁחֲרִית וְהַשְּׁנִיָּה תַּשְׁלוּמֵי עַרְבִית:","טָעָה וְלֹא הִתְפַּלֵּל לֹא תְּפִלָּה זוֹ וְלֹא תְּפִלָּה הַסְּמוּכָה לָהּ אֵינוֹ מְשַׁלֵּם אֶלָּא אַחֲרוֹנָה בִּלְבַד. כֵּיצַד. טָעָה וְלֹא הִתְפַּלֵּל לֹא שַׁחֲרִית וְלֹא מִנְחָה מִתְפַּלֵּל עַרְבִית שְׁתַּיִם רִאשׁוֹנָה עַרְבִית וְהָאַחֲרוֹנָה תַּשְׁלוּמֵי מִנְחָה. אֲבָל שַׁחֲרִית אֵין לָהּ תַּשְׁלוּמִין שֶׁכְּבָר עָבַר זְמַנָּהּ. וְכֵן בִּשְׁאָר תְּפִלּוֹת:","הָיוּ לְפָנָיו שְׁתֵּי תְּפִלּוֹת שֶׁל מִנְחָה וְשֶׁל מוּסָפִין מִתְפַּלֵּל שֶׁל מִנְחָה וְאַחַר כָּךְ מִתְפַּלֵּל שֶׁל מוּסָפִין. וְיֵשׁ מִי שֶׁמּוֹרֶה שֶׁאֵין עוֹשִׂין בְּצִבּוּר כֵּן כְּדֵי שֶׁלֹּא יִטְעוּ:"],"Mishneh Torah, Rebels 2":["בֵּית דִּין הַגָּדוֹל שֶׁדָּרְשׁוּ בְּאַחַת מִן הַמִּדּוֹת כְּפִי מַה שֶּׁנִּרְאָה בְּעֵינֵיהֶם שֶׁהַדִּין כָּךְ וְדָנוּ דִּין. וְעָמַד אַחֲרֵיהֶם בֵּית דִּין אַחֵר וְנִרְאֶה לוֹ טַעַם אַחֵר לִסְתֹּר אוֹתוֹ. הֲרֵי זֶה סוֹתֵר וְדָן כְּפִי מַה שֶּׁנִּרְאֶה בְּעֵינָיו. שֶׁנֶּאֱמַר (דברים יז ט) \"אֶל הַשֹּׁפֵט אֲשֶׁר יִהְיֶה בַּיָּמִים הָהֵם\". אֵינְךָ חַיָּב לָלֶכֶת אֶלָּא אַחַר בֵּית דִּין שֶׁבְּדוֹרְךָ:","בֵּית דִּין שֶׁגָּזְרוּ גְּזֵרָה אוֹ תִּקְּנוּ תַּקָּנָה וְהִנְהִיגוּ מִנְהָג וּפָשַׁט הַדָּבָר בְּכָל יִשְׂרָאֵל. וְעָמַד אַחֲרֵיהֶם בֵּית דִּין אַחֵר וּבִקֵּשׁ לְבַטֵּל דְּבָרִים הָרִאשׁוֹנִים וְלַעֲקֹר אוֹתָהּ הַתַּקָּנָה וְאוֹתָהּ הַגְּזֵרָה וְאוֹתוֹ הַמִּנְהָג. אֵינוֹ יָכוֹל עַד שֶׁיִּהְיֶה גָּדוֹל מִן הָרִאשׁוֹנִים בְּחָכְמָה וּבְמִנְיָן. הָיָה גָּדוֹל בְּחָכְמָה אֲבָל לֹא בְּמִנְיָן. בְּמִנְיָן אֲבָל לֹא בְּחָכְמָה. אֵינוֹ יָכוֹל לְבַטֵּל אֶת דְּבָרָיו. אֲפִלּוּ בָּטַל הַטַּעַם שֶׁבִּגְלָלוֹ גָּזְרוּ הָרִאשׁוֹנִים אוֹ הִתְקִינוּ אֵין הָאַחֲרוֹנִים יְכוֹלִין לְבַטֵּל עַד שֶׁיְּהוּ גְּדוֹלִים מֵהֶם. וְהֵיאַךְ יִהְיוּ גְּדוֹלִים מֵהֶם בְּמִנְיָן הוֹאִיל וְכָל בֵּית דִּין וּבֵית דִּין שֶׁל שִׁבְעִים וְאֶחָד הוּא. זֶה מִנְיַן חַכְמֵי הַדּוֹר שֶׁהִסְכִּימוּ וְקִבְּלוּ הַדָּבָר שֶׁאָמְרוּ בֵּית דִּין הַגָּדוֹל וְלֹא חָלְקוּ בּוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּדְבָרִים שֶׁלֹּא אָסְרוּ אוֹתָן כְּדֵי לַעֲשׂוֹת סְיָג לַתּוֹרָה אֶלָּא כִּשְׁאָר דִּינֵי תּוֹרָה. אֲבָל דְּבָרִים שֶׁרָאוּ בֵּית דִּין לִגְזֹר וּלְאָסְרָן לַעֲשׂוֹת סְיָג אִם פָּשַׁט אִסּוּרָן בְּכָל [יִשְׂרָאֵל] אֵין בֵּית דִּין גָּדוֹל אַחֵר יָכוֹל לְעָקְרָן וּלְהַתִּירָן אֲפִלּוּ הָיָה גָּדוֹל מִן הָרִאשׁוֹנִים:","וְיֵשׁ לְבֵית דִּין לַעֲקֹר אַף דְּבָרִים אֵלּוּ לְפִי שָׁעָה אַף עַל פִּי שֶׁהוּא קָטָן מִן הָרִאשׁוֹנִים שֶׁלֹּא יְהוּ גְּזֵרוֹת אֵלּוּ חֲמוּרִין מִדִּבְרֵי תּוֹרָה עַצְמָהּ שֶׁאֲפִלּוּ דִּבְרֵי תּוֹרָה יֵשׁ לְכָל בֵּית דִּין לְעָקְרוֹ הוֹרָאַת שָׁעָה. כֵּיצַד. בֵּית דִּין שֶׁרָאוּ לְחַזֵּק הַדָּת וְלַעֲשׂוֹת סְיָג כְּדֵי שֶׁלֹּא יַעַבְרוּ הָעָם עַל דִּבְרֵי תּוֹרָה. מַכִּין וְעוֹנְשִׁין שֶׁלֹּא כַּדִּין אֲבָל אֵין קוֹבְעִין הַדָּבָר לְדוֹרוֹת וְאוֹמְרִים שֶׁהֲלָכָה כָּךְ הוּא. וְכֵן אִם רָאוּ לְפִי שָׁעָה לְבַטֵּל מִצְוַת עֲשֵׂה אוֹ לַעֲבֹר עַל מִצְוַת לֹא תַּעֲשֶׂה כְּדֵי לְהַחְזִיר רַבִּים לַדָּת אוֹ לְהַצִּיל רַבִּים מִיִּשְׂרָאֵל מִלְּהִכָּשֵׁל בִּדְבָרִים אֲחֵרִים עוֹשִׂין לְפִי מַה שֶּׁצְּרִיכָה הַשָּׁעָה. כְּשֵׁם שֶׁהָרוֹפֵא חוֹתֵךְ יָדוֹ אוֹ רַגְלוֹ שֶׁל זֶה כְּדֵי שֶׁיִּחְיֶה כֻּלּוֹ כָּךְ בֵּית דִּין מוֹרִים בִּזְמַן מִן הַזְּמַנִּים לַעֲבֹר עַל קְצָת מִצְוֹת לְפִי שָׁעָה כְּדֵי שֶׁיִּתְקַיְּמוּ [כֻּלָּם] כְּדֶרֶךְ שֶׁאָמְרוּ חֲכָמִים הָרִאשׁוֹנִים חַלֵּל עָלָיו שַׁבָּת אַחַת כְּדֵי שֶׁיִּשְׁמֹר שַׁבָּתוֹת הַרְבֵּה:","בֵּית דִּין שֶׁנִּרְאֶה לָהֶן לִגְזֹר גְּזֵרָה אוֹ לְתַקֵּן תַּקָּנָה אוֹ לְהַנְהִיג מִנְהָג צְרִיכִין לְהִתְיַשֵּׁב בַּדָּבָר וְלֵידַע תְּחִלָּה אִם רֹב הַצִּבּוּר יְכוֹלִין לַעֲמֹד בָּהֶן אוֹ אִם אֵין יְכוֹלִין לַעֲמֹד. וּלְעוֹלָם אֵין גּוֹזְרִין גְּזֵרָה עַל הַצִּבּוּר אֶלָּא אִם כֵּן רֹב הַצִּבּוּר יְכוֹלִין לַעֲמֹד בָּהּ:","הֲרֵי שֶׁגָּזְרוּ בֵּית דִּין גְּזֵרָה וְדִמּוּ שֶׁרֹב הַקָּהָל יְכוֹלִין לַעֲמֹד בָּהּ. וְאַחַר שֶׁגְּזָרוּהָ פִּקְפְּקוּ הָעָם בָּהּ וְלֹא פָּשְׁטָה בְּרֹב הַקָּהָל הֲרֵי זוֹ בְּטֵלָה וְאֵינָן רַשָּׁאִין לָכֹף אֶת הָעָם לָלֶכֶת בָּהּ:","גָּזְרוּ וְדִמּוּ שֶׁפָּשְׁטָה בְּכָל יִשְׂרָאֵל וְעָמַד הַדָּבָר כֵּן שָׁנִים רַבּוֹת וּלְאַחַר זְמַן מְרֻבֶּה עָמַד בֵּית דִּין אַחֵר וּבָדַק בְּכָל יִשְׂרָאֵל וְרָאָה שֶׁאֵין אוֹתָהּ הַגְּזֵרָה פּוֹשֶׁטֶת בְּכָל יִשְׂרָאֵל. יֵשׁ לוֹ רְשׁוּת לְבַטֵּל וַאֲפִלּוּ הָיָה פָּחוּת מִבֵּית דִּין הָרִאשׁוֹן בְּחָכְמָה וּבְמִנְיָן:","וְכָל בֵּית דִּין שֶׁהִתִּיר שְׁנֵי דְּבָרִים אַל יְמַהֵר לְהַתִּיר דָּבָר שְׁלִישִׁי:","הוֹאִיל וְיֵשׁ לְבֵית דִּין לִגְזֹר וְלֶאֱסֹר דָּבָר הַמֻּתָּר וְיַעֲמֹד אִסּוּרוֹ לְדוֹרוֹת וְכֵן יֵשׁ לָהֶן לְהַתִּיר אִסּוּרֵי תּוֹרָה לְפִי שָׁעָה. מַהוּ זֶה שֶׁהִזְהִירָה תּוֹרָה (דברים יג א) \"לֹא תּוֹסִיף עָלָיו וְלֹא תִגְרַע מִמֶּנּוּ\". שֶׁלֹּא לְהוֹסִיף עַל דִּבְרֵי תּוֹרָה וְלֹא לִגְרֹעַ מֵהֶן וְלִקְבֹּעַ הַדָּבָר לְעוֹלָם בְּדָבָר שֶׁהוּא מִן הַתּוֹרָה בֵּין בַּתּוֹרָה שֶׁבִּכְתָב בֵּין בַּתּוֹרָה שֶׁבְּעַל פֶּה. כֵּיצַד. הֲרֵי כָּתוּב בַּתּוֹרָה (שמות כג יט) \"לֹא תְבַשֵּׁל גְּדִי בַּחֲלֵב אִמּוֹ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה הַכָּתוּב אָסַר לְבַשֵּׁל ולֶאֱכל בָּשָׂר בְּחָלָב. בֵּין בְּשַׂר בְּהֵמָה בֵּין בְּשַׂר חַיָּה. אֲבָל בְּשַׂר הָעוֹף מֻתָּר בְּחָלָב מִן הַתּוֹרָה. אִם יָבוֹא בֵּית דִּין וְיַתִּיר בְּשַׂר חַיָּה בְּחָלָב הֲרֵי זֶה גּוֹרֵעַ. וְאִם יֶאֱסֹר בְּשַׂר הָעוֹף וְיֹאמַר שֶׁהוּא בִּכְלַל הַגְּדִי וְהוּא אָסוּר מִן הַתּוֹרָה הֲרֵי זֶה מוֹסִיף. אֲבָל אִם אָמַר בְּשַׂר הָעוֹף מֻתָּר מִן הַתּוֹרָה וְאָנוּ נֶאֱסֹר אוֹתוֹ וְנוֹדִיעַ לָעָם שֶׁהוּא גְּזֵרָה שֶׁלֹּא יָבוֹא מִן הַדָּבָר חוֹבָה וְיֹאמְרוּ הָעוֹף מֻתָּר מִפְּנֵי שֶׁלֹּא נִתְפָּרֵשׁ כָּךְ הַחַיָּה מֻתֶּרֶת שֶׁהֲרֵי לֹא נִתְפָּרְשָׁה. וְיָבוֹא אַחֵר לוֹמַר אַף בְּשַׂר בְּהֵמָה מֻתֶּרֶת חוּץ מִן הָעֵז. וְיָבוֹא אַחֵר לוֹמַר אַף בְּשַׂר הָעֵז מֻתָּר בַּחֲלֵב פָּרָה אוֹ הַכִּבְשָׂה שֶׁלֹּא נֶאֱמַר אֶלָּא אִמּוֹ שֶׁהִיא מִינוֹ. וְיָבוֹא אַחֵר לוֹמַר אַף בַּחֲלֵב הָעֵז שֶׁאֵינָהּ אִמּוֹ מֻתָּר שֶׁלֹּא נֶאֱמַר אֶלָּא אִמּוֹ. לְפִיכָךְ נֶאֱסֹר כָּל בָּשָׂר בְּחָלָב אֲפִלּוּ בְּשַׂר עוֹף. אֵין זֶה מוֹסִיף אֶלָּא עוֹשֶׂה סְיָג לַתּוֹרָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Red Heifer 15":["הַנּוֹגֵעַ בְּמֵי חַטָּאת שֶׁלֹּא לְצֹרֶךְ הַזָּאָה בֵּין אָדָם בֵּין כֵּלִים טָמֵא וְאֵינוֹ מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ. שֶׁנֶּאֱמַר (במדבר יט כא) \"וְהַנֹּגֵעַ בְּמֵי הַנִּדָּה יִטְמָא עַד הָעָרֶב\". הִנֵּה לָמַדְתָּ שֶׁמֵּי הַנִּדָּה אָב מֵאֲבוֹת הַטֻּמְאוֹת שֶׁל תּוֹרָה. וְטֻמְאַת מַגָּעָן בְּכָל שֶׁהוּא. וְאִם הָיָה בָּהֶן כְּדֵי הַזָּאָה מְטַמְּאִין בְּמַגָּע וּבְמַשָּׂא. וְהַנּוֹגֵעַ בָּהֶן אוֹ שֶׁנּוֹשְׂאָן שֶׁלֹּא לְצֹרֶךְ מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ אוֹ בִּשְׁעַת מַשָּׂאוֹ עַד שֶׁיִּפְרשׁ מִמְּטַמְּאָיו שֶׁנֶּאֱמַר (במדבר יט כא) \"וּמַזֵּה מֵי הַנִּדָּה יְכַבֵּס בְּגָדָיו\". אֵינוֹ מְדַבֵּר בְּמַזֶּה עַל הַטָּמֵא אִם טִהֵר אֶת הַטָּמֵא קַל וָחֹמֶר שֶׁיִּהְיֶה הוּא טָהוֹר. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר בַּתּוֹרָה וּמַזֵּה מֵי הַנִּדָּה לֹא נֶאֱמַר אֶלָּא לְשִׁעוּר שֶׁהַנּוֹגֵעַ אוֹ הַנּוֹשֵׂא מֵי נִדָּה שֶׁיֵּשׁ בָּהֶן כְּדֵי הַזָּיָה שֶׁלֹּא לְצֹרֶךְ הַזָּאָה טָמֵא וּמְטַמֵּא בְּגָדִים דִּין תּוֹרָה. וְכַמָּה הוּא שִׁעוּר הַזָּאָה כְּדֵי שֶׁיִּטְבּל רָאשֵׁי גִּבְעוֹלִין שֶׁל אֵזוֹב בְּמַיִם. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמֵּי חַטָּאת מְטַמְּאִין בִּזְמַן שֶׁנָּגַע בָּהֶן אוֹ נְשָׂאָן שֶׁלֹּא לְצֹרֶךְ קֹדֶם שֶׁיַּעֲשׂוּ מִצְוָתָן. אֲבָל אַחַר שֶׁעָשׂוּ מִצְוָתָן אֵינָן מְטַמְּאִין כְּלָל. כֵּיצַד. הֲרֵי שֶׁטָּבַל אֶת הָאֵזוֹב וְהִזָּה עַל הָאָדָם הַטָּמֵא אוֹ עַל הַכֵּלִים וְהָיוּ הַמַּיִם שׁוֹתְתִין וְיוֹרְדִין מֵעַל הַטָּמֵא לָאָרֶץ. וְכֵן הַמַּיִם הַנִּתָּזִין בִּשְׁעַת הַזָּאָה עַל הָאָרֶץ אוֹ עַל הַטָּהוֹר הֲרֵי אוֹתָן הַמַּיִם טְהוֹרִים וְהַנּוֹגֵעַ בָּהֶן וְהַנּוֹשְׂאָן טָהוֹר. הִטְבִּיל אֶת הָאֵזוֹב לְהַזּוֹת עַל דָּבָר שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה הֲרֵי הַמַּיִם הַמְנַטְּפִין כְּשֵׁרִין לְהַזּוֹת מֵהֶן כְּמוֹ שֶׁבֵּאַרְנוּ. לְפִיכָךְ מְטַמְּאִין טֻמְאַת מֵי חַטָּאת לְפִי שֶׁלֹּא עָשׂוּ מִצְוָתָן שֶׁהֲרֵי הַטְּבִילָה הָיְתָה לְשֵׁם דָּבָר שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה:","אֵין מֵי חַטָּאת מְטַמְּאִין אֶת הַכּל קֹדֶם שֶׁיַּעֲשׂוּ מִצְוָתָן עַד שֶׁיִּהְיוּ טְהוֹרִין וּכְשֵׁרִין לְהַזָּאָה. אֲבָל מֵי חַטָּאת שֶׁנִּפְסְלוּ כְּגוֹן שֶׁנִּתְעָרֵב בָּהֶן מַיִם אוֹ שֶׁשָּׁתְתָה מֵהֶן בְּהֵמָה וְכַיּוֹצֵא בָּהֶן מֵאֵלּוּ הַדְּבָרִים הַפּוֹסְלִין אוֹתָן אִם נָגַע בָּהֶן הַטָּהוֹר לִתְרוּמָה נִטְמָא בֵּין שֶׁנָּגַע בְּיָדָיו בֵּין שֶׁנָּגַע בִּשְׁאָר גּוּפוֹ. נָגַע בָּהֶן אָדָם הַטָּהוֹר לְחַטָּאת וַאֲפִלּוּ בְּיָדָיו הֲרֵי הוּא טָהוֹר כְּמוֹת שֶׁהָיוּ:","מֵי חַטָּאת שֶׁנִּטְמְאוּ וְנָגַע בָּהֶן אַחַר שֶׁנִּטְמְאוּ אָדָם הַטָּהוֹר לִתְרוּמָה בֵּין בְּיָדָיו בֵּין בְּגוּפוֹ נִטְמָא. וְאִם נָגַע בָּהֶן הַטָּהוֹר לְחַטָּאת בְּיָדָיו נִטְמָא. נָגַע בִּשְׁאָר גּוּפוֹ הֲרֵי הוּא טָהוֹר כְּמוֹת שֶׁהָיָה:","מֵי חַטָּאת שֶׁנָּפְלוּ לְתוֹכָן מֵי מַעְיָן אוֹ מֵי מִקְוֶה אוֹ מֵי פֵּרוֹת. אִם רֹב מֵי חַטָּאת מְטַמְּאִין בְּמַשָּׂא. וְאִם רֹב מֵי פֵּרוֹת אֵין מְטַמְּאִין. מֶחֱצָה לְמֶחֱצָה מְטַמְּאִין. אֵפֶר פָּרָה שֶׁנִּתְעָרֵב בְּאֵפֶר מַקְלֶה וְקִדֵּשׁ בְּכֻלָּן אִם הָיָה הָרֹב אֵפֶר פָּרָה מְטַמְּאִין בְּמֵי נִדָּה. וְאִם הָיָה הָרֹב אֵפֶר מַקְלֶה אֵין מְטַמְּאִין בְּמַגָּע אֲבָל מְטַמְּאִין בְּמַשָּׂא:","אֵפֶר כָּשֵׁר שֶׁנְּתָנוֹ עַל גַּבֵּי הַמַּיִם שֶׁאֵינָן רְאוּיִין לְקַדְּשָׁן וְנָגַע בָּהֶן הַטָּהוֹר לִתְרוּמָה בֵּין בְּיָדָיו בֵּין בְּגוּפוֹ נִטְמָא. נָגַע בָּהֶן הַטָּהוֹר לְחַטָּאת אֲפִלּוּ בְּיָדָיו הֲרֵי זֶה טָהוֹר כְּמוֹת שֶׁהָיָה:","מֵי חַטָּאת שֶׁנִּפְסְלוּ לֹא יְגַבְּלֵם בְּטִיט שֶׁלֹּא יַעֲשֵׂם תַּקָּלָה לַאֲחֵרִים שֶׁמָּא יִגַּע בַּטִּיט וִיטַמֵּא. שֶׁמֵּי חַטָּאת אֵינָם בְּטֵלִין בְּטִיט שֶׁנֶּאֱמַר (במדבר יט ט) \"חַטָּאת הִיא\":","פָּרָה שֶׁשָּׁתָת מֵי חַטָּאת אַף עַל פִּי שֶׁנִּשְׁחֲטָה בְּתוֹךְ כ\"ד שָׁעוֹת בְּשָׂרָהּ טָהוֹר שֶׁנֶּאֱמַר (במדבר יט ט) \"לְמִשְׁמֶרֶת לְמֵי נִדָּה\". בִּזְמַן שֶׁהֵן שְׁמוּרִין אֵינָן בְּטֵלִין. אֲבָל בִּזְמַן שֶׁשְּׁתָאָתָן פָּרָה בָּטְלוּ שֶׁהֲרֵי אֵינָם שְׁמוּרִין:","הַמַּזֶּה מֵחַלּוֹן שֶׁמַּזִּין מִמֶּנּוּ עַל הָרַבִּים. וְהֻזָּה עָלָיו וְנִכְנַס לַמִּקְדָּשׁ וְאַחַר כָּךְ נִמְצְאוּ הַמַּיִם פְּסוּלִין הֲרֵי זֶה פָּטוּר. שֶׁחֶזְקַת הַמַּיִם שֶׁמַּזִּין מֵהֶן עַל הָרַבִּים שֶׁהֵן כְּשֵׁרִין וַהֲרֵי זֶה כְּאָנוּס. אֲבָל אִם הֻזָּה עָלָיו מֵחַלּוֹן שֶׁל יָחִיד וְנִכְנַס לַמִּקְדָּשׁ וְנִמְצְאוּ הַמַּיִם פְּסוּלִין חַיָּב בְּקָרְבָּן עוֹלֶה וְיוֹרֵד מִפְּנֵי שֶׁהָיָה לוֹ לִבְדֹּק עַל הַמַּיִם וְאַחַר כָּךְ יִכָּנֵס לַמִּקְדָּשׁ. מַחֲלִיקִים הָיוּ הָעָם בַּמַּיִם שֶׁשּׁוֹתְתִים בָּאָרֶץ מֵחַלּוֹן שֶׁל רַבִּים וְדוֹרְסִים אוֹתָן וְנִכְנָסִים לַמִּקְדָּשׁ וְלֹא הָיוּ חוֹשְׁשִׁין לָהֶן שֶׁמָּא פְּסוּלִין הֵן:","הַמַּזֶּה בְּאֵזוֹב הַטָּמֵא לְחַטָּאת. אִם יֵשׁ בּוֹ כְּבֵיצָה הַמַּיִם פְּסוּלִין וְהַזָּיָתוֹ [פְּסוּלָה]. אֵין בּוֹ כְּבֵיצָה הַמַּיִם כְּשֵׁרִים וְהַזָּאָתוֹ פְּסוּלָה. וְאֵזוֹב זֶה מְטַמֵּא חֲבֵרוֹ וַחֲבֵרוֹ לַחֲבֵרוֹ אֲפִלּוּ הֵן מֵאָה שֶׁאֵין מוֹנִין לְחַטָּאת:","הַמַּגְבִּיהַּ כְּלִי שֶׁהֻזָּה עָלָיו וַהֲרֵי עָלָיו הַמַּיִם כְּדֵי הַזָּאָה טָהוֹר שֶׁהַמַּיִם שֶׁעָשׂוּ מִצְוָתָן אֵינָן מְטַמְּאִין כְּמוֹ שֶׁבֵּאַרְנוּ: בְּרִיךְ רַחֲמָנָא דְּסַיְּעָן"],"Mishneh Torah, Repentance 3":["כָּל אֶחָד וְאֶחָד מִבְּנֵי הָאָדָם יֵשׁ לוֹ זְכֻיּוֹת וַעֲוֹנוֹת. מִי שֶׁזְּכֻיּוֹתָיו יְתֵרוֹת עַל עֲוֹנוֹתָיו צַדִּיק. וּמִי שֶׁעֲוֹנוֹתָיו יְתֵרוֹת עַל זְכֻיּוֹתָיו רָשָׁע. מֶחֱצָה לְמֶחֱצָה בֵּינוֹנִי. וְכֵן הַמְּדִינָה אִם הָיוּ זְכֻיּוֹת כָּל יוֹשְׁבֶיהָ מְרֻבּוֹת עַל עֲוֹנוֹתֵיהֶן הֲרֵי זוֹ צַדֶּקֶת. וְאִם הָיוּ עֲוֹנוֹתֵיהֶם מְרֻבִּין הֲרֵי זוֹ רְשָׁעָה. וְכֵן כָּל הָעוֹלָם כֻּלּוֹ:","אָדָם שֶׁעֲוֹנוֹתָיו מְרֻבִּין עַל זְכֻיּוֹתָיו מִיָּד הוּא מֵת בְּרִשְׁעוֹ שֶׁנֶּאֱמַר עַל רֹב עֲוֹנֵךְ. וְכֵן מְדִינָה שֶׁעֲוֹנוֹתֶיהָ מְרֻבִּין מִיָּד הִיא אוֹבֶדֶת שֶׁנֶּאֱמַר (בראשית יח כ) \"זַעֲקַת סְדֹם וַעֲמֹרָה כִּי רָבָּה\" וְגוֹ'. וְכֵן כָּל הָעוֹלָם כֻּלּוֹ אִם הָיוּ עֲוֹנוֹתֵיהֶם מְרֻבִּין מִזְּכֻיּוֹתֵיהֶן מִיָּד הֵן נִשְׁחָתִין שֶׁנֶּאֱמַר (בראשית ו ה) \"וַיַּרְא ה' כִּי רַבָּה רָעַת הָאָדָם\". וְשִׁקּוּל זֶה אֵינוֹ לְפִי מִנְיַן הַזְּכֻיּוֹת וְהָעֲוֹנוֹת אֶלָּא לְפִי גָּדְלָם. יֵשׁ זְכוּת שֶׁהִיא כְּנֶגֶד כַּמָּה עֲוֹנוֹת שֶׁנֶּאֱמַר (מלכים א יד יג) \"יַעַן נִמְצָא בוֹ דָּבָר טוֹב\". וְיֵשׁ עָוֹן שֶׁהוּא כְּנֶגֶד כַּמָּה זְכֻיּוֹת שֶׁנֶּאֱמַר (קהלת ט יח) \"וְחוֹטֶא אֶחָד יְאַבֵּד טוֹבָה הַרְבֵּה\". וְאֵין שׁוֹקְלִין אֶלָּא בְּדַעְתּוֹ שֶׁל אֵל דֵּעוֹת וְהוּא הַיּוֹדֵעַ הֵיאַךְ עוֹרְכִין הַזְּכֻיּוֹת כְּנֶגֶד הָעֲוֹנוֹת:","כָּל מִי שֶׁנִּחַם עַל הַמִּצְוֹת שֶׁעָשָׂה וְתָהָה עַל הַזְּכֻיּוֹת וְאָמַר בְּלִבּוֹ וּמַה הוֹעַלְתִּי בַּעֲשִׂיָּתָן הַלְוַאי לֹא עָשִׂיתִי אוֹתָן הֲרֵי זֶה אִבֵּד אֶת כֻּלָּן וְאֵין מַזְכִּירִים לוֹ שׁוּם זְכוּת בָּעוֹלָם שֶׁנֶּאֱמַר (יחזקאל לג יב) \"וְצִדְקַת הַצַּדִּיק לֹא תַצִּילֶנּוּ בְּיוֹם רִשְׁעוֹ\", אֵין זֶה אֶלָּא בְּתוֹהֶה עַל הָרִאשׁוֹנוֹת. וּכְשֵׁם שֶׁשּׁוֹקְלִין זְכֻיּוֹת אָדָם וַעֲוֹנוֹתָיו בִּשְׁעַת מִיתָתוֹ כָּךְ בְּכָל שָׁנָה וְשָׁנָה שׁוֹקְלִין עֲוֹנוֹת כָּל אֶחָד וְאֶחָד מִבָּאֵי הָעוֹלָם עִם זְכֻיּוֹתָיו, בְּיוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה. מִי שֶׁנִּמְצָא צַדִּיק נֶחְתָּם לְחַיִּים. וּמִי שֶׁנִּמְצָא רָשָׁע נֶחְתָּם לְמִיתָה. וְהַבֵּינוֹנִי תּוֹלִין אוֹתוֹ עַד יוֹם הַכִּפּוּרִים אִם עָשָׂה תְּשׁוּבָה נֶחְתָּם לְחַיִּים וְאִם לָאו נֶחְתָּם לְמִיתָה:","אַף עַל פִּי שֶׁתְּקִיעַת שׁוֹפָר בְּרֹאשׁ הַשָּׁנָה גְּזֵרַת הַכָּתוּב רֶמֶז יֵשׁ בּוֹ כְּלוֹמַר עוּרוּ יְשֵׁנִים מִשְּׁנַתְכֶם וְנִרְדָּמִים הָקִיצוּ מִתַּרְדֵּמַתְכֶם וְחַפְּשׂוּ בְּמַעֲשֵׂיכֶם וְחִזְרוּ בִּתְשׁוּבָה וְזִכְרוּ בּוֹרַאֲכֶם. אֵלּוּ הַשּׁוֹכְחִים אֶת הָאֱמֶת בְּהַבְלֵי הַזְּמַן וְשׁוֹגִים כָּל שְׁנָתָם בְּהֶבֶל וָרִיק אֲשֶׁר לֹא יוֹעִיל וְלֹא יַצִּיל, הַבִּיטוּ לְנַפְשׁוֹתֵיכֶם וְהֵיטִיבוּ דַּרְכֵיכֶם וּמַעַלְלֵיכֶם וְיַעֲזֹב כָּל אֶחָד מִכֶּם דַּרְכּוֹ הָרָעָה וּמַחֲשַׁבְתּוֹ אֲשֶׁר לֹא טוֹבָה. לְפִיכָךְ צָרִיךְ כָּל אָדָם שֶׁיִּרְאֶה עַצְמוֹ כָּל הַשָּׁנָה כֻּלָּהּ כְּאִלּוּ חֶצְיוֹ זַכַּאי וְחֶצְיוֹ חַיָּב. וְכֵן כָּל הָעוֹלָם חֶצְיוֹ זַכַּאי וְחֶצְיוֹ חַיָּב. חָטָא חֵטְא אֶחָד הֲרֵי הִכְרִיעַ אֶת עַצְמוֹ וְאֶת כָּל הָעוֹלָם כֻּלּוֹ לְכַף חוֹבָה וְגָרַם לוֹ הַשְׁחָתָה. עָשָׂה מִצְוָה אַחַת הֲרֵי הִכְרִיעַ אֶת עַצְמוֹ וְאֶת כָּל הָעוֹלָם כֻּלּוֹ לְכַף זְכוּת וְגָרַם לוֹ וְלָהֶם תְּשׁוּעָה וְהַצָּלָה שֶׁנֶּאֱמַר (משלי י כה) \"וְצַדִּיק יְסוֹד עוֹלָם\" זֶה שֶׁצָּדַק הִכְרִיעַ אֶת כָּל הָעוֹלָם לִזְכוּת וְהִצִּילוֹ. וּמִפְּנֵי עִנְיָן זֶה נָהֲגוּ כָּל בֵּית יִשְׂרָאֵל לְהַרְבּוֹת בִּצְדָקָה וּבְמַעֲשִׂים טוֹבִים וְלַעֲסֹק בְּמִצְוֹת מֵרֹאשׁ הַשָּׁנָה וְעַד יוֹם הַכִּפּוּרִים יֶתֶר מִכָּל הַשָּׁנָה. וְנָהֲגוּ כֻּלָּם לָקוּם בַּלַּיְלָה בַּעֲשָׂרָה יָמִים אֵלּוּ וּלְהִתְפַּלֵּל בְּבָתֵּי כְּנֵסִיּוֹת בְּדִבְרֵי תַּחֲנוּנִים וּבְכִבּוּשִׁין עַד שֶׁיֵּאוֹר הַיּוֹם:","בְּשָׁעָה שֶׁשּׁוֹקְלִין עֲוֹנוֹת אָדָם עִם זְכֻיּוֹתָיו אֵין מְחַשְּׁבִין עָלָיו עָוֹן שֶׁחָטָא בּוֹ תְּחִלָּה וְלֹא שֵׁנִי אֶלָּא מִשְּׁלִישִׁי וְאֵילָךְ. אִם נִמְצְאוּ עֲוֹנוֹתָיו מִשְּׁלִישִׁי וְאֵילָךְ מְרֻבִּין עַל זְכֻיּוֹתָיו אוֹתָם שְׁתֵּי עֲוֹנוֹת מִצְטָרְפִים וְדָנִין אוֹתוֹ עַל הַכּל. וְאִם נִמְצְאוּ זְכֻיּוֹתָיו כְּנֶגֶד עֲוֹנוֹתָיו אֲשֶׁר מֵעָוֹן שְׁלִישִׁי וְאֵילָךְ מַעֲבִירִים כָּל עֲוֹנוֹתָיו רִאשׁוֹן רִאשׁוֹן. לְפִי שֶׁהַשְּׁלִישִׁי נֶחְשָׁב רִאשׁוֹן שֶׁכְּבָר נִמְחֲלוּ הַשְּׁנַיִם. וְכֵן הָרְבִיעִי הֲרֵי הוּא רִאשׁוֹן שֶׁכְּבָר נִמְחַל הַשְּׁלִישִׁי וְכֵן עַד סוֹפָן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּיָחִיד שֶׁנֶּאֱמַר (איוב לג כט) \"הֶן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלוֹשׁ עִם גָּבֶר\". אֲבָל הַצִּבּוּר תּוֹלִין לָהֶן עָוֹן רִאשׁוֹן שֵׁנִי וּשְׁלִישִׁי שֶׁנֶּאֱמַר (עמוס ב ו) \"עַל שְׁלֹשָׁה פִּשְׁעֵי יִשְׂרָאֵל וְעַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ\". וּכְשֶׁמְּחַשְּׁבִין לָהֶן עַל דֶּרֶךְ זֶה מְחַשְּׁבִין לָהֶן מֵרְבִיעִי וְאֵילָךְ. הַבֵּינוֹנִים אִם הָיָה בִּכְלַל מֶחֱצָה עֲוֹנוֹת שֶׁלָּהֶן שֶׁלֹּא הֵנִיחַ תְּפִלִּין מֵעוֹלָם דָּנִין אוֹתוֹ כְּפִי חֶטְאוֹ וְיֵשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא. וְכֵן כָּל הָרְשָׁעִים שֶׁעֲוֹנוֹתֵיהֶן מְרֻבִּים דָּנִין אוֹתָן כְּפִי חֲטָאֵיהֶם וְיֵשׁ לָהֶן חֵלֶק לָעוֹלָם הַבָּא שֶׁכָּל יִשְׂרָאֵל יֵשׁ לָהֶם חֵלֶק לָעוֹלָם הַבָּא אַף עַל פִּי שֶׁחָטְאוּ שֶׁנֶּאֱמַר (ישעיה ס כא) \"וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ\". אֶרֶץ זוֹ מָשָׁל כְּלוֹמַר אֶרֶץ הַחַיִּים וְהוּא הָעוֹלָם הַבָּא. וְכֵן חֲסִידֵי אֻמּוֹת הָעוֹלָם יֵשׁ לָהֶם חֵלֶק לָעוֹלָם הַבָּא:","וְאֵלּוּ הֵן שֶׁאֵין לָהֶן חֵלֶק לָעוֹלָם הַבָּא אֶלָּא נִכְרָתִים וְאוֹבְדִין וְנִדּוֹנִין עַל גֹּדֶל רִשְׁעָם וְחַטָּאתָם לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. הַמִּינִים. וְהָאֶפִּיקוֹרוֹסִין. וְהַכּוֹפְרִים בַּתּוֹרָה. וְהַכּוֹפְרִים בִּתְחִיַּת הַמֵּתִים וּבְבִיאַת הַגּוֹאֵל. הַמּוֹרְדִים. וּמַחֲטִיאֵי הָרַבִּים. וְהַפּוֹרְשִׁין מִדַּרְכֵי צִבּוּר. וְהָעוֹשֶׂה עֲבֵרוֹת בְּיָד רָמָה בְּפַרְהֶסְיָא כִּיהוֹיָקִים. וְהַמּוֹסְרִים. וּמַטִּילֵי אֵימָה עַל הַצִּבּוּר שֶׁלֹּא לְשֵׁם שָׁמַיִם. וְשׁוֹפְכֵי דָּמִים. וּבַעֲלֵי לָשׁוֹן הָרַע. וְהַמּוֹשֵׁךְ עָרְלָתוֹ:","חֲמִשָּׁה הֵן הַנִּקְרָאִים מִינִים. הָאוֹמֵר שֶׁאֵין שָׁם אֱלוֹהַּ וְאֵין לָעוֹלָם מַנְהִיג. וְהָאוֹמֵר שֶׁיֵּשׁ שָׁם מַנְהִיג אֲבָל הֵן שְׁנַיִם אוֹ יוֹתֵר. וְהָאוֹמֵר שֶׁיֵּשׁ שָׁם רִבּוֹן אֶחָד אֲבָל שֶׁהוּא גּוּף וּבַעַל תְּמוּנָה. וְכֵן הָאוֹמֵר שֶׁאֵינוֹ לְבַדּוֹ הָרִאשׁוֹן וְצוּר לַכֹּל. וְכֵן הָעוֹבֵד כּוֹכָב אוֹ מַזָּל וְזוּלָתוֹ כְּדֵי לִהְיוֹת מֵלִיץ בֵּינוֹ וּבֵין רִבּוֹן הָעוֹלָמִים. כָּל אֶחָד מֵחֲמִשָּׁה אֵלּוּ הוּא מִין:","שְׁלֹשָׁה הֵן הַנִּקְרָאִים אֶפִּיקוֹרְסִין. הָאוֹמֵר שֶׁאֵין שָׁם נְבוּאָה כְּלָל וְאֵין שָׁם מַדָּע שֶׁמַּגִּיעַ מֵהַבּוֹרֵא לְלֵב בְּנֵי הָאָדָם. וְהַמַּכְחִישׁ נְבוּאָתוֹ שֶׁל משֶׁה רַבֵּנוּ. וְהָאוֹמֵר שֶׁאֵין הַבּוֹרֵא יוֹדֵעַ מַעֲשֵׂה בְּנֵי הָאָדָם. כָּל אֶחָד מִשְּׁלֹשָׁה אֵלּוּ הֵן אֶפִּיקוֹרוֹסִים. שְׁלֹשָׁה הֵן הַכּוֹפְרִים בַּתּוֹרָה. הָאוֹמֵר שֶׁאֵין הַתּוֹרָה מֵעִם ה' אֲפִלּוּ פָּסוּק אֶחָד אֲפִלּוּ תֵּבָה אַחַת אִם אָמַר משֶׁה אֲמָרוֹ מִפִּי עַצְמוֹ הֲרֵי זֶה כּוֹפֵר בַּתּוֹרָה. וְכֵן הַכּוֹפֵר בְּפֵרוּשָׁהּ וְהוּא תּוֹרָה שֶׁבְּעַל פֶּה וְהַמַּכְחִישׁ מַגִּידֶיהָ כְּגוֹן צָדוֹק וּבַיְתּוֹס. וְהָאוֹמֵר שֶׁהַבּוֹרֵא הֶחֱלִיף מִצְוָה זוֹ בְּמִצְוָה אַחֶרֶת וּכְבָר בָּטְלָה תּוֹרָה זוֹ אַף עַל פִּי שֶׁהִיא הָיְתָה מֵעִם ה' כְּגוֹן הָהַגְרִים. כָּל אֶחָד מִשְּׁלֹשָׁה אֵלּוּ כּוֹפֵר בַּתּוֹרָה:","שְׁנַיִם הֵם הַמּוּמָרִים מִיִּשְׂרָאֵל. הַמּוּמָר לַעֲבֵרָה אַחַת וְהַמּוּמָר לְכָל הַתּוֹרָה כֻּלָּהּ. מוּמָר לַעֲבֵרָה אַחַת זֶה שֶׁהֶחֱזִיק עַצְמוֹ לַעֲשׂוֹת אוֹתָהּ עֲבֵרָה בְּזָדוֹן וְהֻרְגָּל וְנִתְפַּרְסֵם בָּהּ אֲפִלּוּ הָיְתָה מִן הַקַּלּוֹת כְּגוֹן שֶׁהֻחְזַק תָּמִיד לִלְבֹּשׁ שַׁעַטְנֵז אוֹ לְהַקִּיף פֵּאָה וְנִמְצָא כְּאִלּוּ בָּטְלָה מִצְוָה זוֹ מִן הָעוֹלָם אֶצְלוֹ הֲרֵי זֶה מוּמָר לְאוֹתוֹ דָּבָר וְהוּא שֶׁיַּעֲשֶׂה לְהַכְעִיס. מוּמָר לְכָל הַתּוֹרָה כֻּלָּהּ כְּגוֹן הַחוֹזְרִים לְדָתֵי הָעוֹבְדֵי כּוֹכָבִים בְּשָׁעָה שֶׁגּוֹזְרִין גְּזֵרָה וְיִדְבַּק בָּהֶם וְיֹאמַר מַה בֶּצַע לִי לְהִדַּבֵּק בְּיִשְׂרָאֵל שֶׁהֵם שְׁפָלִים וְנִרְדָּפִים טוֹב לִי שֶׁאֶדַּבֵּק בְּאֵלּוּ שֶׁיָּדָם תַּקִּיפָה. הֲרֵי זֶה מוּמָר לְכָל הַתּוֹרָה כֻּלָּהּ:","מַחֲטִיאֵי הָרַבִּים כֵּיצַד. אֶחָד שֶׁהֶחְטִיא בְּדָבָר גָּדוֹל כְּגוֹן יָרָבְעָם וְצָדוֹק וּבַיְתּוֹס. וְאֶחָד שֶׁהֶחְטִיא בְּדָבָר קַל אֲפִלּוּ לְבַטֵּל מִצְוַת עֲשֵׂה. וְאֶחָד הָאוֹנֵס אֲחֵרִים עַד שֶׁיֶּחְטְאוּ כִּמְנַשֶּׁה שֶׁהָיָה הוֹרֵג אֶת יִשְׂרָאֵל עַד שֶׁיַּעַבְדוּ עֲבוֹדַת כּוֹכָבִים, אוֹ שֶׁהִטְעָה אֲחֵרִים וְהִדִּיחָם כְּיֵשׁוּעַ:","הַפּוֹרֵשׁ מִדַּרְכֵי צִבּוּר אַף עַל פִּי שֶׁלֹּא עָבַר עֲבֵרוֹת אֶלָּא נִבְדָּל מֵעֲדַת יִשְׂרָאֵל וְאֵינוֹ עוֹשֶׂה מִצְוֹת בִּכְלָלָן וְלֹא נִכְנָס בְּצָרָתָן וְלֹא מִתְעַנֶּה בְּתַעֲנִיתָן אֶלָּא הוֹלֵךְ בְּדַרְכּוֹ כְּאֶחָד מִגּוֹיֵי הָאָרֶץ וּכְאִלּוּ אֵינוֹ מֵהֶן אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. הָעוֹשֶׂה עֲבֵרוֹת בְּיָד רָמָה כִּיהוֹיָקִים בֵּין שֶׁעָשָׂה קַלּוֹת בֵּין שֶׁעָשָׂה חֲמוּרוֹת אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. וְזֶהוּ הַנִּקְרָא מְגַלֶּה פָּנִים בַּתּוֹרָה מִפְּנֵי שֶׁהֵעֵז מִצְחוֹ וְגִלָּה פָּנָיו וְלֹא בּוֹשׁ מִדִּבְרֵי תּוֹרָה:","שְׁנַיִם הֵם הַמּוֹסְרִין. הַמּוֹסֵר חֲבֵרוֹ בְּיַד עַכּוּ\"ם לְהָרְגוֹ אוֹ לְהַכּוֹתוֹ. וְהַמּוֹסֵר מָמוֹן חֲבֵרוֹ בְּיַד עַכּוּ\"ם אוֹ בְּיַד אַנָּס שֶׁהוּא כְּעַכּוּ\"ם. וּשְׁנֵיהֶם אֵין לָהֶם חֵלֶק לָעוֹלָם הַבָּא:","מַטִּילֵי אֵימָה עַל הַצִּבּוּר שֶׁלֹּא לְשֵׁם שָׁמַיִם זֶה הָרוֹדֶה צִבּוּר בְּחָזְקָה וְהֵם יְרֵאִים וּמְפַחֲדִים מִמֶּנּוּ וְכַוָּנָתוֹ לִכְבוֹד עַצְמוֹ וְכָל חֲפָצָיו שֶׁלֹּא לִכְבוֹד שָׁמַיִם כְּגוֹן מַלְכֵי הָעַכּוּ\"ם:","כָּל אֶחָד וְאֶחָד מֵעֶשְׂרִים וְאַרְבָּעָה אֲנָשִׁים אֵלּוּ שֶׁמָּנִינוּ אַף עַל פִּי שֶׁהֵן מִיִּשְׂרָאֵל אֵין לָהֶם חֵלֶק לָעוֹלָם הַבָּא. וְיֵשׁ עֲבֵרוֹת קַלּוֹת מֵאֵלּוּ וְאַף עַל פִּי כֵן אָמְרוּ חֲכָמִים שֶׁהָרָגִיל בָּהֶן אֵין לָהֶם חֵלֶק לָעוֹלָם הַבָּא (וּכְדֵי) [וּכְדַאי] הֵן לְהִתְרַחֵק מֵהֶן וּלְהִזָּהֵר בָּהֶן. וְאֵלּוּ הֵן. הַמְכַנֶּה שֵׁם לַחֲבֵרוֹ. וְהַקּוֹרֵא לַחֲבֵרוֹ בְּכִנּוּיוֹ. וְהַמַּלְבִּין פְּנֵי חֲבֵרוֹ בָּרַבִּים. וְהַמִּתְכַּבֵּד בִּקְלוֹן חֲבֵרוֹ. וְהַמְבַזֶּה תַּלְמִידֵי חֲכָמִים. וְהַמְבַזֶּה רַבּוֹתָיו. וְהַמְבַזֶּה אֶת הַמּוֹעֲדוֹת. וְהַמְחַלֵּל אֶת הַקָּדָשִׁים. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁכָּל אֶחָד מֵאֵלּוּ אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא כְּשֶׁמֵּת בְּלֹא תְּשׁוּבָה אֲבָל אִם שָׁב מֵרִשְׁעוֹ וּמֵת וְהוּא בַּעַל תְּשׁוּבָה הֲרֵי זֶה מִבְּנֵי הָעוֹלָם הַבָּא שֶׁאֵין לְךָ דָּבָר שֶׁעוֹמֵד בִּפְנֵי הַתְּשׁוּבָה. אֲפִלּוּ כָּפַר בָּעִקָּר כָּל יָמָיו וּבָאַחֲרוֹנָה שָׁב יֵשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא שֶׁנֶּאֱמַר (ישעיה נז יט) \"שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב אָמַר ה' וּרְפָאתִיו\". כָּל הָרְשָׁעִים וְהַמּוּמָרִים וְכַיּוֹצֵא בָּהֶן שֶׁחָזְרוּ בִּתְשׁוּבָה בֵּין בְּגָלוּי בֵּין בְּמַטְמוֹנִיּוֹת מְקַבְּלִין אוֹתָן שֶׁנֶּאֱמַר (ירמיה ג יד) \"שׁוּבוּ בָּנִים שׁוֹבָבִים\". אַף עַל פִּי שֶׁעֲדַיִן שׁוֹבָב הוּא שֶׁהֲרֵי בַּסֵּתֶר שָׁב וְלֹא בְּגָלוּי מְקַבְּלִין אוֹתוֹ בִּתְשׁוּבָה:"],"Mishneh Torah, Rest on a Holiday 6":["יוֹם טוֹב שֶׁחָל לִהְיוֹת עֶרֶב שַׁבָּת אֵין אוֹפִין וּמְבַשְּׁלִין בְּיוֹם טוֹב מַה שֶּׁהוּא אוֹכֵל לְמָחָר בְּשַׁבָּת. וְאִסּוּר זֶה מִדִּבְרֵי סוֹפְרִים כְּדֵי שֶׁלֹּא יָבֹא לְבַשֵּׁל מִיּוֹם טוֹב לְחל. שֶׁקַּל וָחֹמֶר הוּא לְשַׁבָּת אֵינוֹ מְבַשֵּׁל כָּל שֶׁכֵּן לְחל. לְפִיכָךְ אִם עָשָׂה תַּבְשִׁיל מֵעֶרֶב יוֹם טוֹב שֶׁיִּהְיֶה סוֹמֵךְ עָלָיו וּמְבַשֵּׁל וְאוֹפֶה בְּיוֹם טוֹב לְשַׁבָּת הֲרֵי זֶה מֻתָּר. וְתַבְשִׁיל שֶׁסּוֹמֵךְ עָלָיו הוּא הַנִּקְרָא עֵרוּבֵי תַּבְשִׁילִין:","וְלָמָּה נִקְרָא שְׁמוֹ עֵרוּב. שֶׁכְּשֵׁם שֶׁהָעֵרוּב שֶׁעוֹשִׂין בַּחֲצֵרוֹת וּמְבוֹאוֹת מֵעֶרֶב שַׁבָּת מִשּׁוּם הֶכֵּר כְּדֵי שֶׁלֹּא יַעֲלֶה עַל דַּעְתָּם שֶׁמֻּתָּר לְהוֹצִיא מֵרְשׁוּת לִרְשׁוּת בְּשַׁבָּת. כָּךְ זֶה הַתַּבְשִׁיל מִשּׁוּם הֶכֵּר וְזִכָּרוֹן כְּדֵי שֶׁלֹּא יְדַמּוּ וְיַחְשְׁבוּ שֶׁמֻּתָּר לֶאֱפוֹת בְּיוֹם טוֹב מַה שֶּׁאֵינוֹ נֶאֱכָל בּוֹ בַּיּוֹם. וּלְפִיכָךְ נִקְרָא תַּבְשִׁיל זֶה עֵרוּבֵי תַּבְשִׁילִין:","עֵרוּבֵי תַּבְשִׁילִין שִׁעוּרוֹ אֵין פָּחוֹת מִכְּזַיִת בֵּין לְאֶחָד בֵּין לַאֲלָפִים. וְאֵין עוֹשִׂין עֵרוּב זֶה לֹא בְּפַת וְלֹא בְּרִיפוֱֹת וְכַיּוֹצֵא בָּהֶן אֶלָּא בְּתַבְשִׁיל שֶׁהוּא פַּרְפֶּרֶת כְּגוֹן בָּשָׂר וְדָגִים וּבֵיצִים וְכַיּוֹצֵא בָּהֶן. וַאֲפִלּוּ עֲדָשִׁים שֶׁבְּשׁוּלֵי קְדֵרָה וַאֲפִלּוּ שַׁמְנוּנִית שֶׁעַל גַּבֵּי הַסַּכִּין שֶׁחוֹתְכִין בָּהּ הַצָּלִי גּוֹרְדוֹ אִם יֵשׁ בּוֹ כְּזַיִת סוֹמֵךְ עָלָיו מִשּׁוּם עֵרוּבֵי תַּבְשִׁילִין:","תַּבְשִׁיל שֶׁאָמְרוּ לְעִנְיַן עֵרוּב זֶה אֲפִלּוּ צָלִי אֲפִלּוּ שָׁלוּק אֲפִלּוּ כָּבוּשׁ אוֹ מְעֵשָּׁן אֲפִלּוּ דָּגִים קְטַנִּים שֶׁהֵדִיחָן בְּמַיִם חַמִּין וַהֲדָחָתָן הִיא בִּשּׁוּלָן לַאֲכִילָה הֲרֵי זֶה סוֹמֵךְ עֲלֵיהֶן:","וְצָרִיךְ שֶׁיִּהְיֶה עֵרוּב זֶה מָצוּי עַד שֶׁיֹּאפֶה כָּל מַה שֶּׁהוּא צָרִיךְ לֶאֱפוֹת וּלְבַשֵּׁל כָּל שֶׁהוּא צָרִיךְ לְבַשֵּׁל. וְיָחֵם חַמִּין כָּל שֶׁהוּא צָרִיךְ. וְאִם נֶאֱכַל הָעֵרוּב אוֹ אָבַד אוֹ נִשְׂרַף קֹדֶם שֶׁיְּבַשֵּׁל אוֹ יֹאפֶה הֲרֵי זֶה אָסוּר לֶאֱפוֹת וּלְבַשֵּׁל אוֹ לְהָחֵם אֶלָּא מַה שֶּׁהוּא אוֹכֵל בְּיוֹם טוֹב בִּלְבַד. הִתְחִיל בְּעִסָּתוֹ אוֹ בְּתַבְשִׁילוֹ וְנֶאֱכַל הָעֵרוּב אוֹ אָבַד הֲרֵי זֶה גּוֹמֵר:","הַמֵּנִיחַ עֵרוּבֵי תַּבְשִׁילִין כְּדֵי שֶׁיִּסְמֹךְ עֲלֵיהֶם הוּא וַאֲחֵרִים צָרִיךְ לְזַכּוֹת לָהֶן כְּדֶרֶךְ שֶׁמְּזַכֶּה בְּעֵרוּבֵי שַׁבָּת. וְכָל שֶׁזּוֹכֶה בְּעֵרוּבֵי שַׁבָּת זוֹכֶה בְּעֵרוּבֵי תַּבְשִׁילִין. וְכָל שֶׁאֵינוֹ זוֹכֶה בְּאוֹתוֹ עֵרוּב אֵינוֹ זוֹכֶה בָּזֶה:","וְאֵינוֹ צָרִיךְ לְהוֹדִיעַ לְאֵלּוּ שֶׁזִּכָּה לָהֶן מֵעֶרֶב יוֹם טוֹב. אֲבָל הֵן צְרִיכִין לֵידַע שֶׁכְּבָר זִכָּה לָהֶן אַחֵר וְעֵרֵב לָהֶן וְאַחַר כָּךְ יִסְמְכוּ עָלָיו וִיבַשְּׁלוּ וְיֹאפוּ. אַף עַל פִּי שֶׁלֹּא יָדְעוּ אֶלָּא בְּיוֹם טוֹב הֲרֵי אֵלּוּ מֻתָּרִין. וְיֵשׁ לוֹ לְאָדָם לְעָרֵב עַל כָּל הָעִיר וְעַל כָּל הַקָּרוֹב אֵלֶיהָ בְּתוֹךְ הַתְּחוּם וּלְמָחָר מַכְרִיז וְאוֹמֵר כָּל מִי שֶׁלֹּא הִנִּיחַ עֵרוּבֵי תַּבְשִׁילִין יִסְמֹךְ עַל עֵרוּבִי:","הַמַּנִּיחַ עֵרוּבֵי תַּבְשִׁילִין חַיָּב לְבָרֵךְ. בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל מִצְוַת עֵרוּב. וְאוֹמֵר בְּעֵרוּב זֶה יֻתַּר לִי לֶאֱפוֹת וּלְבַשֵּׁל מִיּוֹם טוֹב שֶׁלְּמָחָר לְשַׁבָּת. וְאִם זָכָה בּוֹ לַאֲחֵרִים יֹאמַר לִי וְלִפְלוֹנִי וְלִפְלוֹנִי אוֹ לְאַנְשֵׁי הָעִיר כֻּלָּם לֶאֱפוֹת וּלְבַשֵּׁל מִיּוֹם טוֹב לְשַׁבָּת:","מִי שֶׁלֹּא הִנִּיחַ עֵרוּבֵי תַּבְשִׁילִין וְלֹא הִנִּיחוּ לוֹ אֲחֵרִים. כְּשֵׁם שֶׁאָסוּר לוֹ לְבַשֵּׁל וְלֶאֱפוֹת כָּךְ קִמְחוֹ וּמַאֲכָלוֹ אָסוּר. וְאָסוּר לְאַחֵר שֶׁהִנִּיחַ לְעַצְמוֹ לְבַשֵּׁל וְלֶאֱפוֹת לָזֶה שֶׁלֹּא הִנִּיחַ עַד שֶׁיַּקְנֶה לוֹ שֶׁנִּמְצָא זֶה מְבַשֵּׁל וְאוֹפֶה שֶׁלּוֹ שֶׁהֲרֵי קָנָהוּ. וְאִם רָצָה יִתֵּן אַחַר כָּךְ לָזֶה שֶׁלֹּא הִנִּיחַ בְּמַתָּנָה:","מִי שֶׁלֹּא הִנִּיחַ עֵרוּבֵי תַּבְשִׁילִין וּבִשֵּׁל וְאָפָה לֶאֱכל בַּיּוֹם וְהוֹתִיר אוֹ שֶׁזִּמֵּן אוֹרְחִים וְלֹא בָּאוּ הֲרֵי זֶה אוֹכֵל הַמּוֹתָר לְמָחָר. וְאִם הֶעֱרִים הֲרֵי זֶה אָסוּר לְאָכְלוֹ. עָבַר וְאָפָה וּבִשֵּׁל לְשַׁבָּת אֵין אוֹסְרִין עָלָיו. וְלָמָּה הֶחְמִירוּ וְאָסְרוּ עַל הַמַּעֲרִים וְלֹא אָסְרוּ עַל הַמֵּזִיד שֶׁאִם תַּתִּיר לַמַּעֲרִים נִמְצְאוּ הַכּל מַעֲרִימִין וְיִשְׁתַּקֵּעַ שֵׁם עֵרוּבֵי תַּבְשִׁילִין. אֲבָל הַמֵּזִיד אֵינוֹ מָצוּי וְאִם עָבַר הַיּוֹם לֹא יַעֲבֹר פַּעַם אַחֶרֶת:","שְׁנֵי יָמִים טוֹבִים שֶׁחָלוּ לִהְיוֹת בַּחֲמִישִׁי וְעֶרֶב שַׁבָּת עוֹשֶׂה עֵרוּבֵי תַּבְשִׁילִין מִיּוֹם רְבִיעִי שֶׁהוּא עֶרֶב יוֹם טוֹב. שָׁכַח וְלֹא הִנִּיחַ מַנִּיחוֹ בָּרִאשׁוֹן וּמַתְנֶה. כֵּיצַד. מַנִּיחַ עֵרוּבֵי תַּבְשִׁילִין בְּיוֹם חֲמִישִׁי וְאוֹמֵר אִם הַיּוֹם יוֹם טוֹב וּלְמָחָר חֹל לְמָחָר אֲבַשֵּׁל וְאוֹפֶה לְשַׁבָּת וְאֵינִי צָרִיךְ כְּלוּם וְאִם הַיּוֹם חֹל וּלְמָחָר יוֹם טוֹב בָּעֵרוּב זֶה יֵתַּר לִי לֶאֱפוֹת וּלְבַשֵּׁל לְמָחָר מִיּוֹם טוֹב לְשַׁבָּת:","כַּיּוֹצֵא בּוֹ הָיוּ לְפָנָיו שְׁתֵּי כַּלְכָּלוֹת שֶׁל טֶבֶל בְּיוֹם טוֹב רִאשׁוֹן אוֹמֵר אִם הַיּוֹם חֹל תִּהְיֶה זוֹ תְּרוּמָה עַל זוֹ וְאִם הַיּוֹם קֹדֶשׁ אֵין בִּדְבָרַי כְּלוּם. וְקוֹרֵא עָלֶיהָ שֵׁם וּמַנִּיחָהּ. וּלְמָחָר בַּשֵּׁנִי חוֹזֵר וְאוֹמֵר אִם הַיּוֹם קֹדֶשׁ אֵין בִּדְבָרַי כְּלוּם וְאִם הַיּוֹם חֹל תִּהְיֶה זוֹ תְּרוּמָה עַל זוֹ וְקוֹרֵא עָלֶיהָ שֵׁם וּמַנִּיחָהּ כְּדֶרֶךְ שֶׁקָּרָא עָלֶיהָ בָּרִאשׁוֹן. וּמַנִּיחַ אֶת זוֹ שֶׁקָּרָא עָלֶיהָ שֵׁם תְּרוּמָה וְאוֹכֵל אֶת הַשְּׁנִיָּה:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁנֵי יָמִים טוֹבִים שֶׁל גָּלֻיּוֹת אֲבָל בִּשְׁנֵי יָמִים טוֹבִים שֶׁל רֹאשׁ הַשָּׁנָה אִם שָׁכַח וְלֹא הִנִּיחַ בְּיוֹם רְבִיעִי שׁוּב אֵינוֹ מַנִּיחַ אֶלָּא סוֹמֵךְ עַל אֲחֵרִים אִם עֵרְבוּ עָלָיו אוֹ מַקְנֶה קִמְחוֹ לְמִי שֶׁעֵרֵב אוֹ יִהְיֶה אָסוּר לֶאֱפוֹת וּלְבַשֵּׁל לְשַׁבָּת. וְכֵן אִם שָׁכַח וְלֹא הִפְרִישׁ תְּרוּמָה מִיּוֹם רְבִיעִי שׁוּב אֵינוֹ מַפְרִישׁ עַד מוֹצָאֵי שַׁבָּת:","כָּל הַדְּבָרִים הָאֵלּוּ שֶׁאָמַרְנוּ הָיוּ בִּזְמַן שֶׁהָיוּ בֵּית דִּין שֶׁל אֶרֶץ יִשְׂרָאֵל מְקַדְּשִׁין עַל פִּי הָרְאִיָּה וְהָיוּ בְּנֵי הַגָּלֻיּוֹת עוֹשִׂין שְׁנֵי יָמִים כְּדֵי לְהִסְתַּלֵּק מִן הַסָּפֵק לְפִי שֶׁלֹּא הָיוּ יוֹדְעִין יוֹם שֶׁקִּדְּשׁוּ בְּנֵי אֶרֶץ יִשְׂרָאֵל. אֲבָל הַיּוֹם שֶׁבְּנֵי אֶרֶץ יִשְׂרָאֵל סוֹמְכִין עַל הַחֶשְׁבּוֹן וּמְקַדְּשִׁין עָלָיו אֵין יוֹם טוֹב שֵׁנִי לְהִסְתַּלֵּק מִן הַסָּפֵק אֶלָּא מִנְהָג בִּלְבַד:","וּלְפִיכָךְ אֲנִי אוֹמֵר שֶׁאֵין מְעָרֵב אָדָם וּמַתְנֶה בַּזְּמַן הַזֶּה לֹא עֵרוּבֵי תַּבְשִׁילִין וְלֹא עֵרוּבֵי חֲצֵרוֹת וְלֹא שִׁתּוּפֵי מְבוֹאוֹת וְאֵינוֹ מְעַשֵּׂר הַטֶּבֶל עַל תְּנַאי אֶלָּא הַכּל מֵעֶרֶב יוֹם טוֹב בִּלְבַד:","כְּשֵׁם שֶׁמִּצְוָה לְכַבֵּד שַׁבָּת וּלְעַנְּגָהּ כָּךְ כָּל יָמִים טוֹבִים שֶׁנֶּאֱמַר (ישעיה נח יג) \"לִקְדוֹשׁ ה' מְכֻבָּד\" וְכָל יָמִים טוֹבִים נֶאֱמַר בָּהֶן (ויקרא כג ז) \"מִקְרָא קֹדֶשׁ\". וּכְבָר בֵּאַרְנוּ הַכִּבּוּד וְהָעִנּוּג בְּהִלְכוֹת שַׁבָּת. וְכֵן רָאוּי לְאָדָם שֶׁלֹּא יִסְעֹד בְּעַרְבֵי יָמִים טוֹבִים מִן הַמִּנְחָה וּלְמַעְלָה כְּעֶרֶב שַׁבָּת שֶׁדָּבָר זֶה בִּכְלַל הַכָּבוֹד. וְכָל הַמְבַזֶּה אֶת הַמּוֹעֲדוֹת כְּאִלּוּ נִטְפָּל לַעֲבוֹדַת כּוֹכָבִים:","שִׁבְעַת יְמֵי הַפֶּסַח וּשְׁמוֹנַת יְמֵי הֶחָג עִם שְׁאָר יָמִים טוֹבִים כֻּלָּם אֲסוּרִים בְּהֶסְפֵּד וְתַעֲנִית. וְחַיָּב אָדָם לִהְיוֹת בָּהֶן שָׂמֵחַ וְטוֹב לֵב הוּא וּבָנָיו וְאִשְׁתּוֹ וּבְנֵי בֵּיתוֹ וְכָל הַנִּלְוִים עָלָיו שֶׁנֶּאֱמַר (דברים טז יד) \"וְשָׂמַחְתָּ בְּחַגֶּךָ\" וְגוֹ'. אַף עַל פִּי שֶׁהַשִּׂמְחָה הָאֲמוּרָה כָּאן הִיא קָרְבַּן שְׁלָמִים כְּמוֹ שֶׁאָנוּ מְבָאֲרִין בְּהִלְכוֹת חֲגִיגָה יֵשׁ בִּכְלַל אוֹתָהּ שִׂמְחָה לִשְׂמֹחַ הוּא וּבָנָיו וּבְנֵי בֵּיתוֹ כָּל אֶחָד כָּרָאוּי לוֹ:","כֵּיצַד. הַקְּטַנִּים נוֹתֵן לָהֶם קְלָיוֹת וֶאֱגוֹזִים וּמִגְדָּנוֹת. וְהַנָּשִׁים קוֹנֶה לָהֶן בְּגָדִים וְתַכְשִׁיטִין נָאִים כְּפִי מָמוֹנוֹ. וְהָאֲנָשִׁים אוֹכְלִין בָּשָׂר וְשׁוֹתִין יַיִן שֶׁאֵין שִׂמְחָה אֶלָּא בְּבָשָׂר וְאֵין שִׂמְחָה אֶלָּא בְּיַיִן. וּכְשֶׁהוּא אוֹכֵל וְשׁוֹתֶה חַיָּב לְהַאֲכִיל לַגֵּר לַיָּתוֹם וְלָאַלְמָנָה עִם שְׁאָר הָעֲנִיִּים הָאֻמְלָלִים. אֲבָל מִי שֶׁנּוֹעֵל דַּלְתוֹת חֲצֵרוֹ וְאוֹכֵל וְשׁוֹתֶה הוּא וּבָנָיו וְאִשְׁתּוֹ וְאֵינוֹ מַאֲכִיל וּמַשְׁקֶה לַעֲנִיִּים וּלְמָרֵי נֶפֶשׁ אֵין זוֹ שִׂמְחַת מִצְוָה אֶלָּא שִׂמְחַת כְּרֵסוֹ. וְעַל אֵלּוּ נֶאֱמַר (הושע ט ד) \"זִבְחֵיהֶם כְּלֶחֶם אוֹנִים לָהֶם כָּל אֹכְלָיו יִטַּמָּאוּ כִּי לַחְמָם לְנַפְשָׁם\". וְשִׂמְחָה כָּזוֹ קָלוֹן הִיא לָהֶם שֶׁנֶּאֱמַר (מלאכי ב ג) \"וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם פֶּרֶשׁ חַגֵּיכֶם\":","אַף עַל פִּי שֶׁאֲכִילָה וּשְׁתִיָּה בַּמּוֹעֲדוֹת בִּכְלַל מִצְוַת עֲשֵׂה. לֹא יִהְיֶה אוֹכֵל וְשׁוֹתֶה כָּל הַיּוֹם כֻּלּוֹ. אֶלָּא כָּךְ הִיא הַדָּת. בַּבֹּקֶר מַשְׁכִּימִין כָּל הָעָם לְבָתֵּי כְּנֵסִיּוֹת וּלְבָתֵּי מִדְרָשׁוֹת וּמִתְפַּלְּלִין וְקוֹרִין בַּתּוֹרָה בְּעִנְיַן הַיּוֹם וְחוֹזְרִין לְבָתֵּיהֶם וְאוֹכְלִין. וְהוֹלְכִין לְבָתֵּי מִדְרָשׁוֹת קוֹרִין וְשׁוֹנִין עַד חֲצִי הַיּוֹם. וְאַחַר חֲצוֹת הַיּוֹם מִתְפַּלְּלִין תְּפִלַּת הַמִּנְחָה וְחוֹזְרִין לְבָתֵּיהֶן לֶאֱכל וְלִשְׁתּוֹת שְׁאָר הַיּוֹם עַד הַלַּיְלָה:","כְּשֶׁאָדָם אוֹכֵל וְשׁוֹתֶה וְשָׂמֵחַ בָּרֶגֶל לֹא יִמָּשֵׁךְ בְּיַיִן וּבִשְׂחוֹק וְקַלּוּת רֹאשׁ וְיֹאמַר שֶׁכָּל מִי שֶׁיּוֹסִיף בָּזֶה יַרְבֶּה בְּמִצְוַת שִׂמְחָה. שֶׁהַשִּׁכְרוּת וְהַשְּׂחוֹק הָרַבָּה וְקַלּוּת הָרֹאשׁ אֵינָהּ שִׂמְחָה אֶלָּא הוֹלְלוּת וְסִכְלוּת וְלֹא נִצְטַוֵּינוּ עַל הַהוֹלְלוּת וְהַסִּכְלוּת אֶלָּא עַל הַשִּׂמְחָה שֶׁיֵּשׁ בָּהּ עֲבוֹדַת יוֹצֵר הַכּל שֶׁנֶּאֱמַר (דברים כח מז) \"תַּחַת אֲשֶׁר לֹא עָבַדְתָּ אֶת ה' אֱלֹהֶיךָ בְּשִׂמְחָה וּבְטוּב לֵבָב מֵרֹב כּל\". הָא לָמַדְתָּ שֶׁהָעֲבוֹדָה בְּשִׂמְחָה. וְאִי אֶפְשָׁר לַעֲבֹד אֶת הַשֵּׁם לֹא מִתּוֹךְ שְׂחוֹק וְלֹא מִתּוֹךְ קַלּוּת רֹאשׁ וְלֹא מִתּוֹךְ שִׁכְרוּת:","חַיָּבִין בֵּית דִּין לְהַעֲמִיד שׁוֹטְרִים בָּרְגָלִים שֶׁיִּהְיוּ מְסַבְּבִין וּמְחַפְּשִׂין בַּגַּנּוֹת וּבַפַּרְדֵּסִים וְעַל הַנְּהָרוֹת כְּדֵי שֶׁלֹּא יִתְקַבְּצוּ לֶאֱכל וְלִשְׁתּוֹת שָׁם אֲנָשִׁים וְנָשִׁים וְיָבוֹאוּ לִידֵי עֲבֵרָה. וְכֵן יַזְהִירוּ בְּדָבָר זֶה לְכָל הָעָם כְּדֵי שֶׁלֹּא יִתְעָרְבוּ אֲנָשִׁים וְנָשִׁים בְּבָתֵּיהֶם לְשִׂמְחָה. וְלֹא יִמָּשְׁכוּ בַּיַּיִן שֶׁמָּא יָבוֹאוּ לִידֵי עֲבֵרָה:","יָמִים שֶׁבֵּין רִאשׁוֹן וּשְׁבִיעִי שֶׁל פֶּסַח וְרִאשׁוֹן וּשְׁמִינִי שֶׁל חַג הַסֻּכּוֹת וְהֵן בַּגּוֹלָה אַרְבָּעָה בְּתוֹךְ הַפֶּסַח וַחֲמִשָּׁה בְּתוֹךְ הֶחָג הֵם הַנִּקְרָאִין חֻלּוֹ שֶׁל מוֹעֵד וְנִקְרָאִין מוֹעֵד. וְאַף עַל פִּי שֶׁהֵם חַיָּבִין בְּשִׂמְחָה וַאֲסוּרִין בְּהֶסְפֵּד וְתַעֲנִית מֻתָּר לִסְפֹּד בָּהֶן תַּלְמִיד חָכָם בְּפָנָיו. אֲבָל לְאַחַר שֶׁיִּקָּבֵר אָסוּר לְסָפְדוֹ בָּהֶן. וְאֵין צָרִיךְ לוֹמַר בְּרָאשֵׁי חֳדָשִׁים בַּחֲנֻכָּה וּבְפוּרִים שֶׁסּוֹפְדִין בָּהֶן תַּלְמִידֵי חֲכָמִים בְּפָנָיו אַף עַל פִּי שֶׁיָּמִים אֵלּוּ אֲסוּרִין בְּהֶסְפֵּד וְתַעֲנִית. אֲבָל לְאַחַר הַקְּבוּרָה אָסוּר לִסְפֹּד בָּהֶן:","אֵין מַנִּיחִין מִטַּת הַמֵּת בָּרְחוֹב בַּמּוֹעֵד שֶׁלֹּא לְהַרְגִּיל אֶת הַהֶסְפֵּד אֶלָּא מִבֵּיתוֹ לְקִבְרוֹ. וְאֵין מִתְאַבְּלִין בַּמּוֹעֵד. וְכֵן אֵין קוֹרְעִין וְלֹא מַבְרִין וְלֹא חוֹלְצִין הַכָּתֵף בַּמּוֹעֵד עַל הַמֵּת אֶלָּא קְרוֹבָיו שֶׁהֵן חַיָּבִין לְהִתְאַבֵּל עָלָיו. וְאִם הָיָה חָכָם אוֹ אָדָם כָּשֵׁר אוֹ שֶׁהָיָה עוֹמֵד עָלָיו בִּשְׁעַת נְטִילַת נְשָׁמָה הֲרֵי זֶה קוֹרֵעַ עָלָיו בַּמּוֹעֵד אַף עַל פִּי שֶׁאֵינוֹ קְרוֹבוֹ. וְאֵין קוֹרְעִין בְּיוֹם טוֹב שֵׁנִי כְּלָל וַאֲפִלּוּ קְרוֹבָיו שֶׁל מֵת:","נָשִׁים בַּמּוֹעֵד בִּפְנֵי הַמֵּת מְעַנּוֹת אֲבָל לֹא מְטַפְּחוֹת וְלֹא מְקוֹנְנוֹת. נִקְבַּר הַמֵּת אֵינָן מְעַנּוֹת. בְּרָאשֵׁי חֳדָשִׁים וַחֲנֻכָּה וּפוּרִים בִּפְנֵי הַמֵּת מְעַנּוֹת וּמְטַפְּחוֹת אֲבָל לֹא מְקוֹנְנוֹת. אֵי זֶהוּ עִנּוּי שֶׁכֻּלָּן עוֹנוֹת כְּאַחַת. קִינָה אַחַת אוֹמֶרֶת וְכֻלָּן עוֹנוֹת. וְאָסוּר לְאָדָם שֶׁיְּעוֹרֵר עַל מֵתוֹ קֹדֶם לָרֶגֶל שְׁלֹשִׁים יוֹם כְּדֵי שֶׁלֹּא יָבֹא הָרֶגֶל וְהוּא נֶעֱצָב וְלִבּוֹ דּוֹאֵג וְכוֹאֵב מִזִּכְרוֹן הַצַּעַר אֶלָּא יָסִיר הַדְּאָגָה מִלִּבּוֹ וִיכַוֵּן דַּעְתּוֹ לְשִׂמְחָה:"],"Mishneh Torah, Ritual Slaughter 2":["בְכָל מָקוֹם מֻתָּר לִשְׁחֹט חוּץ מִן הָעֲזָרָה. שֶׁאֵין שׁוֹחֲטִין בָּעֲזָרָה אֶלָּא קָדְשֵׁי מִזְבֵּחַ בִּלְבַד. אֲבָל הַחֻלִּין אָסוּר לְשָׁחֳטָן בָּעֲזָרָה בֵּין בְּהֵמָה בֵּין חַיָּה בֵּין עוֹף. וְכֵן הוּא אוֹמֵר בִּבְשַׂר תַּאֲוָה (דברים יב כא) \"כִּי יִרְחַק מִמְּךָ הַמָּקוֹם אֲשֶׁר יִבְחַר ה'\" וְגוֹ' (דברים יב כא) \"וְזָבַחְתָּ מִבְּקָרְךָ וּמִצֹּאנְךָ\" וְגוֹ' (דברים יב כא) \"וְאָכַלְתָּ בִּשְׁעָרֶיךָ\". הָא לָמַדְתָּ שֶׁאֵין שׁוֹחֲטִין בְּשַׂר תַּאֲוָה אֶלָּא חוּץ לַמָּקוֹם (דברים יב כא) \"אֲשֶׁר בָּחַר ה'\":","וְזֶה שֶׁנִּשְׁחַט חוּץ לַמָּקוֹם הוּא שֶׁמֻּתָּר לְאָכְלוֹ בְּכָל הַשְּׁעָרִים. אֲבָל הַשּׁוֹחֵט חֻלִּין בָּעֲזָרָה אוֹתוֹ הַבָּשָׂר טָהוֹר וְאָסוּר בַּהֲנָיָה כְּבָשָׂר בְּחָלָב וְכַיּוֹצֵא בּוֹ. וְקוֹבְרִים אוֹתוֹ וְאֶפְרוֹ אָסוּר אֲפִלּוּ שָׁחַט לִרְפוּאָה אוֹ לַאֲכִילַת עַכּוּ\"ם אוֹ לְהַאֲכִיל לִכְלָבִים. אֲבָל הַנּוֹחֵר בָּעֲזָרָה. וְהַמְעַקֵּר. וְעַכּוּ\"ם שֶׁשָּׁחַט. וְהַשּׁוֹחֵט וְנִמְצָא טְרֵפָה. וְהַשּׁוֹחֵט בְּהֵמָה חַיָּה וְעוֹף הַטְּמֵאִים בָּעֲזָרָה. הֲרֵי אֵלּוּ כֻּלָּן מֻתָּרִין בַּהֲנָיָה:","וְלֹא בְּהֵמָה וְחַיָּה בִּלְבַד אֶלָּא כָּל הַחֻלִּין אָסוּר לְהַכְנִיסָן לַעֲזָרָה. אֲפִלּוּ בְּשַׂר שְׁחוּטָה אוֹ פֵּרוֹת וּפַת. אִם עָבַר וְהִכְנִיסָן מֻתָּרִין בַּאֲכִילָה כְּשֶׁהָיוּ. וּדְבָרִים אֵלּוּ כֻּלָּן דִּבְרֵי קַבָּלָה הֵן. וְכָל הַשּׁוֹחֵט חֻלִּין בָּעֲזָרָה אוֹ הָאוֹכֵל כְּזַיִת מִבְּשַׂר חֻלִּין שֶׁנִּשְׁחֲטוּ בָּעֲזָרָה מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","הָאוֹמֵר בְּהֵמָה זוֹ שְׁלָמִים וּוְלָדָהּ חֻלִּין. אִם נִשְׁחֲטָה בָּעֲזָרָה וְלָדָהּ מֻתָּר בַּאֲכִילָה. לְפִי שֶׁאֵינוֹ יָכוֹל לִשְׁחֹט אוֹתוֹ בְּרִחוּק מָקוֹם:","אֵין שׁוֹחֲטִין לְתוֹךְ יַמִּים וּנְהָרוֹת שֶׁמָּא יֹאמְרוּ עוֹבֵד מַיִם הוּא זֶה וְנִרְאֶה כְּמַקְרִיב לַמַּיִם. וְלֹא יִשְׁחֹט לִכְלִי מָלֵא מַיִם שֶׁמָּא יֹאמְרוּ לַצּוּרָה שֶׁתֵּרָאֶה בַּמַּיִם שָׁחַט. וְלֹא יִשְׁחֹט בְּתוֹךְ כֵּלִים וְלֹא לְתוֹךְ הַגֻּמָּא שֶׁכֵּן דֶּרֶךְ עוֹבְדֵי עַכּוּ\"ם. וְאִם שָׁחַט שְׁחִיטָתוֹ כְּשֵׁרָה:","שׁוֹחֲטִין לִכְלִי מַיִם עֲכוּרִין שֶׁאֵין הַצּוּרָה נִרְאֵית בָּהֶן. וְכֵן שׁוֹחֵט חוּץ לְגֻמָּא וְהַדָּם שׁוֹתֵת וְיוֹרֵד לַגֻּמָּא. וּבַשּׁוּק לֹא יַעֲשֶׂה כֵּן שֶׁמָּא יְחַקֶּה אֶת הַמִּינִים. וְאִם שָׁחַט לְגֻמָּא בַּשּׁוּק אָסוּר לֶאֱכל מִשְּׁחִיטָתוֹ עַד שֶׁיִּבְדְּקוּ אַחֲרָיו שֶׁמָּא מִין הוּא. וּמֻתָּר לִשְׁחֹט עַל דֹּפֶן הַסְּפִינָה וְהַדָּם שׁוֹתֵת עַל הַדֹּפֶן וְיוֹרֵד לַמַּיִם. וּמֻתָּר לִשְׁחֹט עַל גַּבֵּי הַכֵּלִים:","כֵּיצַד שׁוֹחֲטִין. מוֹתֵחַ אֶת הַצַּוָּאר וּמוֹלִיךְ הַסַּכִּין וּמְבִיאָהּ עַד שֶׁשּׁוֹחֵט. בֵּין שֶׁהָיְתָה הַבְּהֵמָה רְבוּצָה בֵּין שֶׁהָיְתָה עוֹמֶדֶת וְאָחַז בְּעָרְפָּהּ וְהַסַּכִּין בְּיָדוֹ מִלְּמַטָּה וְשָׁחַט הֲרֵי זוֹ כְּשֵׁרָה:","נָעַץ אֶת הַסַּכִּין בַּכֹּתֶל וְהֶעֱבִיר הַצַּוָּאר עָלֶיהָ עַד שֶׁנִּשְׁחַט שְׁחִיטָתוֹ כְּשֵׁרָה. וְהוּא שֶׁיִּהְיֶה צַוָּאר הַבְּהֵמָה לְמַטָּה וְסַכִּין לְמַעְלָה. שֶׁאִם הָיָה צַוַּאר בְּהֵמָה לְמַעְלָה מִן הַסַּכִּין שֶׁמָּא תֵּרֵד הַבְּהֵמָה בְּכֹבֶד גּוּפָהּ וְתֵחָתֵךְ בְּלֹא הוֹלָכָה וַהֲבָאָה וְאֵין זוֹ שְׁחִיטָה כְּמוֹ שֶׁיִּתְבָּאֵר. לְפִיכָךְ אִם הָיָה עוֹף בֵּין שֶׁהָיָה צַוָּארוֹ לְמַעְלָה מִן הַסַּכִּין הַנְּעוּצָה אוֹ לְמַטָּה מִמֶּנּוּ שְׁחִיטָתוֹ כְּשֵׁרָה:","הַשּׁוֹחֵט וְהוֹלִיךְ אֶת הַסַּכִּין וְלֹא הֱבִיאָהּ אוֹ הֱבִיאָהּ וְלֹא הוֹלִיכָהּ וְשָׁחַט שְׁחִיטָתוֹ כְּשֵׁרָה. הוֹלִיךְ וְהֵבִיא עַד שֶׁחָתַךְ הָרֹאשׁ וְהִתִּיזוֹ שְׁחִיטָתוֹ כְּשֵׁרָה. הוֹלִיךְ וְלֹא הֵבִיא אוֹ הֵבִיא וְלֹא הוֹלִיךְ וְהִתִּיז אֶת הָרֹאשׁ בְּהוֹלָכָה בִּלְבַד אוֹ בַּהֲבָאָה בִּלְבַד. אִם יֵשׁ בַּסַּכִּין כִּמְלֹא שְׁנֵי צַוָּארִים מִצַּוְּארֵי הַנִּשְׁחָט שְׁחִיטָתוֹ כְּשֵׁרָה וְאִם לָאו שְׁחִיטָתוֹ פְּסוּלָה. שָׁחַט שְׁנֵי רָאשִׁים כְּאֶחָד שְׁחִיטָתוֹ כְּשֵׁרָה:","שְׁנַיִם שֶׁאָחֲזוּ בְּסַכִּין אֲפִלּוּ אֶחָד מִצַּד זֶה וְשֵׁנִי מִצַּד אַחֵר כְּנֶגְדּוֹ וְשָׁחֲטוּ שְׁחִיטָתָן כְּשֵׁרָה. וְכֵן שְׁנַיִם שֶׁאָחֲזוּ שְׁנֵי סַכִּינִין וְשָׁחֲטוּ כְּאֶחָד בִּשְׁנֵי מְקוֹמוֹת בַּצַּוָּאר שְׁחִיטָתָן כְּשֵׁרָה. וַאֲפִלּוּ שָׁחַט זֶה הַוֵּשֶׁט בִּלְבַד אוֹ רֻבּוֹ וְהַשֵּׁנִי שָׁחַט בְּמָקוֹם אַחֵר הַקָּנֶה אוֹ רֻבּוֹ הֲרֵי שְׁחִיטָה זוֹ כְּשֵׁרָה וְאַף עַל פִּי שֶׁאֵין הַשְּׁחִיטָה כֻּלָּהּ בְּמָקוֹם אֶחָד. וְכֵן שְׁחִיטָה הָעֲשׂוּיָה כְּקֻלְמוֹס וּשְׁחִיטָה הָעֲשׂוּיָה כְּמַסְרֵק כְּשֵׁרָה:","אֵין שְׁחִיטַת הַחֻלִּין צְרִיכָה כַּוָּנָה אֶלָּא אֲפִלּוּ שָׁחַט כְּמִתְעַסֵּק אוֹ דֶּרֶךְ שְׂחוֹק אוֹ שֶׁזָּרַק סַכִּין לְנָעֳצָהּ בַּכֹּתֶל וְשָׁחֲטָה בַּהֲלִיכָתָהּ הוֹאִיל וְהַשְּׁחִיטָה כָּרָאוּי בִּמְקוֹמָהּ וְשִׁעוּרָהּ הֲרֵי זוֹ כְּשֵׁרָה:","לְפִיכָךְ חֵרֵשׁ אוֹ שׁוֹטֶה אוֹ קָטָן אוֹ שִׁכּוֹר שֶׁנִּתְבַּלְבְּלָה דַּעְתּוֹ וּמִי שֶׁאֲחָזַתּוּ רוּחַ רָעָה שֶׁשָּׁחֲטוּ וַאֲחֵרִים רוֹאִין אוֹתָם שֶׁהַשְּׁחִיטָה כְּתִקְנָהּ הֲרֵי זוֹ כְּשֵׁרָה. אֲבָל סַכִּין שֶׁנָּפְלָה וְשָׁחֲטָה אַף עַל פִּי שֶׁשָּׁחֲטָה כְּדַרְכָּהּ הֲרֵי זוֹ פְּסוּלָה שֶׁנֶּאֱמַר (דברים יב כא) \"וְזָבַחְתָּ\" עַד שֶׁיִּהְיֶה הַזּוֹבֵחַ אָדָם וְאַף עַל פִּי שֶׁאֵינוֹ מִתְכַּוֵּן לִשְׁחִיטָה:","גַּלְגַּל שֶׁל אֶבֶן אוֹ שֶׁל עֵץ שֶׁהָיְתָה הַסַּכִּין קְבוּעָה בּוֹ וְסִבֵּב אָדָם אֶת הַגַּלְגַּל וְשָׂם צַוַּאר הָעוֹף אוֹ הַבְּהֵמָה כְּנֶגְדּוֹ עַד שֶׁנִּשְׁחַט בִּסְבִיבַת הַגַּלְגַּל הֲרֵי זוֹ כְּשֵׁרָה. וְאִם הַמַּיִם הֵן הַמְסַבְּבִין אֶת הַגַּלְגַּל וְשָׂם אֶת הַצַּוָּאר כְּנֶגְדּוֹ בְּשָׁעָה שֶׁסִּבֵּב וְנִשְׁחַט הֲרֵי זוֹ פְּסוּלָה. וְאִם פָּטַר אָדָם אֶת הַמַּיִם עַד שֶׁבָּאוּ וְסִבְּבוּ אֶת הַגַּלְגַּל וְשָׁחַט בִּסְבִיבָתוֹ הֲרֵי זוֹ כְּשֵׁרָה שֶׁהֲרֵי מִכֹּחַ אָדָם בָּא. בַּמֶּה דְּבָרִים אֲמוּרִים בִּסְבִיבָה רִאשׁוֹנָה שֶׁהִיא מִכֹּחַ הָאָדָם אֲבָל מִסְּבִיבָה שְׁנִיָּה וּלְאַחֲרֶיהָ אֵינָהּ מִכֹּחַ הָאָדָם אֶלָּא מִכֹּחַ הַמַּיִם בְּהִלּוּכָן:","הַשּׁוֹחֵט לְשֵׁם הָרִים לְשֵׁם גְּבָעוֹת לְשֵׁם יַמִּים לְשֵׁם נְהָרוֹת לְשֵׁם מִדְבָּרוֹת אַף עַל פִּי שֶׁלֹּא נִתְכַּוִּן לְעָבְדָן אֶלָּא לִרְפוּאָה וְכַיּוֹצֵא בָּהּ מִדִּבְרֵי הֲבַאי שֶׁאוֹמְרִין הָעַכּוּ\"ם הֲרֵי שְׁחִיטָתוֹ פְּסוּלָה. אֲבָל אִם שָׁחַט לְשֵׁם מַזַּל הַיָּם אוֹ מַזַּל הָהָר אוֹ לְכוֹכָבִים וּמַזָּלוֹת וְכַיּוֹצֵא בָּהֶן הֲרֵי זוֹ אֲסוּרָה בַּהֲנָיָה כְּכָל תִּקְרֹבֶת עַכּוּ\"ם:","הַשּׁוֹחֵט אֶת הַבְּהֵמָה לִזְרֹק דָּמָהּ לְעַכּוּ\"ם אוֹ לְהַקְטִיר חֶלְבָּהּ לְעַכּוּ\"ם הֲרֵי זוֹ אֲסוּרָה. שֶׁלְּמֵדִין מַחֲשָׁבָה בַּחוּץ בְּחֻלִּין מִמַּחְשֶׁבֶת הַקָּדָשִׁים בִּפְנִים. שֶׁמַּחֲשָׁבָה כָּזוֹ פּוֹסֶלֶת בָּהֶן כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת פְּסוּלֵי הַמֻּקְדָּשִׁין:","שְׁחָטָהּ וְאַחַר כָּךְ חָשַׁב לִזְרֹק דָּמָהּ לְעַכּוּ\"ם אוֹ לְהַקְטִיר חֶלְבָּהּ לְעַכּוּ\"ם הֲרֵי זוֹ אֲסוּרָה מִסָּפֵק. שֶׁמָּא סוֹפוֹ הוֹכִיחַ עַל תְּחִלָּתוֹ וּבְמַחֲשָׁבָה כָּזוֹ שָׁחַט:","הַשּׁוֹחֵט לְשֵׁם קָדָשִׁים שֶׁמִּתְנַדְּבִין וְנִדָּרִים כְּמוֹתָן שְׁחִיטָתוֹ פְּסוּלָה שֶׁזֶּה כְּשׁוֹחֵט קָדָשִׁים בַּחוּץ. שָׁחַט לְשֵׁם קָדָשִׁים שֶׁאֵינָן בָּאִין בְּנֵדֶר וּנְדָבָה שְׁחִיטָתוֹ כְּשֵׁרָה:","כֵּיצַד. הַשּׁוֹחֵט לְשֵׁם עוֹלָה לְשֵׁם שְׁלָמִים לְשֵׁם תּוֹדָה לְשֵׁם פֶּסַח שְׁחִיטָתוֹ פְּסוּלָה. הוֹאִיל וְהַפֶּסַח מַפְרִישׁ אוֹתוֹ בְּכָל הַשָּׁנָה בְּכָל עֵת שֶׁיִּרְצֶה הֲרֵי הוּא דּוֹמֶה לְדָבָר הַנִּדָּר וְהַנִּדָּב. שָׁחַט לְשֵׁם חַטָּאת לְשֵׁם אָשָׁם וַדַּאי לְשֵׁם אָשָׁם תָּלוּי לְשֵׁם בְּכוֹר לְשֵׁם מַעֲשֵׂר לְשֵׁם תְּמוּרָה שְׁחִיטָתוֹ כְּשֵׁרָה:","הָיָה מְחֻיָּב חַטָּאת וְשָׁחַט וְאָמַר לְחַטָּאתִי שְׁחִיטָתוֹ פְּסוּלָה. הָיָה לוֹ קָרְבָּן בְּתוֹךְ בֵּיתוֹ וְשָׁחַט וְאָמַר לְשֵׁם תְּמוּרַת זִבְחִי שְׁחִיטָתוֹ פְּסוּלָה שֶׁהֲרֵי הֵמִיר בּוֹ:","הָאִשָּׁה שֶׁשָּׁחֲטָה לְשֵׁם עוֹלַת יוֹלֶדֶת וְאָמְרָה זוֹ לְעוֹלָתִי שְׁחִיטָתָהּ כְּשֵׁרָה. שֶׁאֵין עוֹלַת יוֹלֶדֶת בָּאָה בְּנֵדֶר וּנְדָבָה וַהֲרֵי אֵינָהּ יוֹלֶדֶת שֶׁנִּתְחַיְּבָה בְּעוֹלָה. וְאֵין חוֹשְׁשִׁין לָהּ שֶׁמָּא הִפִּילָה. שֶׁכָּל הַמַּפֶּלֶת קוֹל יֵשׁ לָהּ. אֲבָל הַשּׁוֹחֵט לְשֵׁם עוֹלַת נָזִיר אַף עַל פִּי שֶׁאֵינוֹ נָזִיר שְׁחִיטָתוֹ פְּסוּלָה שֶׁעִקַּר הַנְּזִירוּת נֵדֶר מִן הַנְּדָרִים:","שְׁנַיִם אוֹחֲזִין בְּסַכִּין וְשׁוֹחֲטִין. אֶחָד מִתְכַּוֵּן לְשֵׁם דָּבָר שֶׁהַשּׁוֹחֵט לוֹ שְׁחִיטָתוֹ אֲסוּרָה. וְהַשֵּׁנִי לֹא הָיְתָה לוֹ כַּוָּנָה כְּלָל וַאֲפִלּוּ נִתְכַּוֵּן לְשֵׁם דָּבָר הַמֻּתָּר לְהִתְכַּוֵּן לוֹ הֲרֵי זוֹ פְּסוּלָה. וְכֵן אִם שָׁחַט זֶה אַחַר זֶה וְהִתְכַּוֵּן הָאֶחָד מֵהֶן לְשֵׁם דָּבָר הַפָּסוּל פּוֹסֵל. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה לוֹ בָּהּ שֻׁתָּפוּת אֲבָל אִם אֵין לוֹ בָּהּ שֻׁתָּפוּת אֵינָהּ אֲסוּרָה. שֶׁאֵין אָדָם מִיִּשְׂרָאֵל אוֹסֵר דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ שֶׁאֵין כַּוָּנָתוֹ אֶלָּא לְצַעֲרוֹ:","יִשְׂרָאֵל שֶׁשָּׁחַט לְעַכּוּ\"ם אַף עַל פִּי שֶׁהָעַכּוּ\"ם מִתְכַּוֵּן לְכָל מַה שֶּׁיִּרְצֶה שְׁחִיטָתוֹ כְּשֵׁרָה. שֶׁאֵין חוֹשְׁשִׁין אֶלָּא לְמַחְשֶׁבֶת הַזּוֹבֵחַ לֹא לְמַחְשֶׁבֶת בַּעַל הַבְּהֵמָה. לְפִיכָךְ עַכּוּ\"ם שֶׁשָּׁחַט לְיִשְׂרָאֵל אֲפִלּוּ הָיָה קָטָן שְׁחִיטָתוֹ נְבֵלָה כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Robbery and Lost Property 13":["הַמּוֹצֵא אֲבֵדָה שֶׁהוּא חַיָּב לְהַחְזִירָהּ חַיָּב לְהַכְרִיז עָלֶיהָ וּלְהוֹדִיעָהּ וְלוֹמַר מִי שֶׁאָבַד לוֹ מִין פְּלוֹנִי יָבוֹא וְיִתֵּן סִימָנִין וְיִטּל. אֲפִלּוּ הָיְתָה שָׁוָה פְּרוּטָה בְּעֵת הַמְּצִיאָה וְהוּזְלָה חַיָּב לְהַכְרִיז עָלֶיהָ. וְאֶבֶן גְּבוֹהָה הָיְתָה חוּץ לִירוּשָׁלַיִם שֶׁעָלֶיהָ הָיוּ מַכְרִיזִין:","כֵּיצַד מַכְרִיז. אִם מָצָא מָעוֹת מַכְרִיז מִי שֶׁאָבַד לוֹ מַטְבֵּעַ. וְכֵן מַכְרִיז מִי שֶׁאָבַד לוֹ כְּסוּת אוֹ בְּהֵמָה אוֹ שְׁטָרוֹת יָבוֹא וְיִתֵּן סִימָנִים וְיִטּל וְאֵינוֹ חוֹשֵׁשׁ מִפְּנֵי שֶׁהוֹדִיעַ מִין הָאֲבֵדָה לְפִי שֶׁאֵינוֹ מַחְזִירוֹ עַד שֶׁיִּתֵּן סִימָנִים מֻבְהָקִין:","בָּא בַּעַל הָאֲבֵדָה וְנָתַן סִימָנִים שֶׁאֵינָן מֻבְהָקִין אֵין מַחֲזִירִין לוֹ עַד שֶׁיֹּאמַר סִימָנִים מֻבְהָקִין. וְהָרַמַּאי אַף עַל פִּי שֶׁאָמַר סִימָנִים מֻבְהָקִין אֵין מַחֲזִירִין לוֹ עַד שֶׁיֳּבִיא עֵדִים שֶׁהִיא שֶׁלּוֹ. אָמְרוּ חֲכָמִים (דברים כב ב) \"וְהָיָה עִמְּךָ עַד דְּרשׁ אָחִיךָ\" עַד שֶׁתַּחְקֹר אַחֲרָיו אִם רַמַּאי הוּא אִם לָאו:","בָּרִאשׁוֹנָה כָּל מִי שֶׁאָבַד לוֹ אֲבֵדָה וּבָא וְנָתַן סִימָנֶיהָ מַחֲזִירִין אוֹתָהּ לוֹ אֶלָּא אִם כֵּן הֻחְזַק רַמַּאי. מִשֶּׁרַבּוּ הָרַמָּאִין הִתְקִינוּ בֵּית דִּין שֶׁיְּהוּ אוֹמְרִין לוֹ הָבֵא עֵדִים שֶׁאֵין אַתָּה רַמַּאי וְטל:","הַסִּימָנִים הַמֻּבְהָקִין סוֹמְכִין עֲלֵיהֶם וְדָנִין עַל פִּיהֶם בְּכָל מָקוֹם דִּין תּוֹרָה. וְהַמִּדָּה אוֹ הַמִּשְׁקָל אוֹ הַמִּנְיָן אוֹ מְקוֹם הָאֲבֵדָה סִימָנִין מֻבְהָקִין הֵן:","בָּאוּ שְׁנַיִם זֶה נָתַן סִימָנֵי הָאֲבֵדָה וְזֶה נָתַן סִימָנֵי הָאֲבֵדָה כְּמוֹ שֶׁנָּתַן הָאַחֵר לֹא יִתֵּן לֹא לָזֶה וְלֹא לָזֶה אֶלָּא תִּהְיֶה מֻנַּחַת עַד שֶׁיּוֹדֶה הָאֶחָד לַחֲבֵרוֹ אוֹ יַעֲשׂוּ בֵּינֵיהֶן פְּשָׁרָה. נָתַן הָאֶחָד אֶת הַסִּימָנִים וְהַשֵּׁנִי הֵבִיא עֵדִים יִתֵּן לְבַעַל הָעֵדִים. זֶה נָתַן סִימָנִים וְזֶה נָתַן סִימָנִים וְעֵד אֶחָד הֲרֵי הָעֵד הָאֶחָד כְּמוֹ שֶׁאֵינוֹ וְיַנִּיחַ:","מָצָא שִׂמְלָה וְכַיּוֹצֵא בָּהּ וְזֶה הֵבִיא עֵדֵי אֲרִיגָה שֶׁאֲרָגוּהָ לוֹ וְזֶה הֵבִיא עֵדִים שֶׁנָּפְלָה מִמֶּנּוּ יִתֵּן לְעֵדֵי נְפִילָה. זֶה נָתַן מִדַּת אָרְכָּהּ וְזֶה נָתַן מִדַּת רָחְבָּהּ יִתֵּן לְמִי שֶׁנָּתַן מִדַּת אָרְכָּהּ שֶׁאֶפְשָׁר שֶׁיְּשַׁעֵר הָרַמַּאי מִדַּת רָחְבָּהּ כְּשֶׁהָיָה בְּעָלֶיהָ מִתְכַּסֶּה בָּהּ. זֶה נָתַן מִדַּת אָרְכָּהּ וְרָחְבָּהּ וְזֶה כִּוֵּן מִשְׁקְלוֹתֶיהָ יִתֵּן לְמִי שֶׁכִּוֵּן מִשְׁקָלָהּ. זֶה נָתַן מִדַּת אָרְכָּהּ וְרָחְבָּהּ וְזֶה נָתַן מִדַּת הָאִמְרִיּוֹת שֶׁבָּהּ יִתֵּן לְמִי שֶׁנָּתַן מִדַּת אָרְכָּהּ וְרָחְבָּהּ:","בָּרִאשׁוֹנָה כָּל מִי שֶׁמָּצָא אֲבֵדָה הָיָה מַכְרִיז עָלֶיהָ שְׁלֹשָׁה רְגָלִים. רֶגֶל רִאשׁוֹן אוֹמֵר רִאשׁוֹן. שֵׁנִי אוֹמֵר שֵׁנִי. שְׁלִישִׁי מַכְרִיז סְתָם כְּדֵי שֶׁלֹּא יִתְחַלֵּף לוֹ שֵׁנִי בִּשְׁלִישִׁי. וְאַחַר רֶגֶל הָאַחֲרוֹן בְּשִׁבְעַת יָמִים מַכְרִיז פַּעַם רְבִיעִית. כְּדֵי שֶׁיֵּלֵךְ הַשּׁוֹמֵעַ לְבֵיתוֹ בִּשְׁלֹשָׁה יָמִים וִימַשֵּׁשׁ כֵּלָיו וְיַחְזֹר בִּשְׁלֹשֶׁת הַיָּמִים וְיִמְצָא זֶה הַמַּכְרִיז מַכְרִיז בַּשְּׁבִיעִי:","מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ הִתְקִינוּ שֶׁיְּהוּ מַכְרִיזִין בְּבָתֵּי כְּנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת. מִשֶּׁרַבּוּ הָאֳנָסִין וְאָמְרוּ הַמְּצִיאָה שֶׁל מֶלֶךְ הִיא הִתְקִינוּ שֶׁיִּהְיוּ מוֹדִיעִין לִשְׁכֵנָיו וְלִמְיֻדָּעָיו וְדַיּוֹ:","הִכְרִיז אוֹ הוֹדִיעַ וְלֹא בָּאוּ הַבְּעָלִים תִּהְיֶה הַמְּצִיאָה מֻנַּחַת אֶצְלוֹ עַד שֶׁיָּבוֹא אֵלִיָּהוּ. וּבְכָל זְמַן שֶׁהָאֲבֵדָה אֶצְלוֹ אִם נִגְנְבָה אוֹ אָבְדָה חַיָּב בְּאַחֲרָיוּתָהּ. וְאִם נֶאֶנְסָה פָּטוּר שֶׁשּׁוֹמֵר אֲבֵדָה כְּשׁוֹמֵר שָׂכָר הוּא מִפְּנֵי שֶׁהוּא עוֹסֵק בְּמִצְוָה וְנִפְטָר מִכַּמָּה מִצְוֹת עֲשֵׂה כָּל זְמַן שֶׁהוּא עוֹסֵק בִּשְׁמִירָתָהּ:","וְצָרִיךְ לְבַקֵּר אֶת הָאֲבֵדָה וּלְבָדְקָהּ כְּדֵי שֶׁלֹּא תִּפָּסֵד וְתֹאבַד מֵאֵלֶיהָ שֶׁנֶּאֱמַר (דברים כב ב) \"וַהֲשֵׁבֹתוֹ לוֹ\" רְאֵה הֵיאַךְ תְּשִׁיבֶנּוּ לוֹ. כֵּיצַד. מָצָא כְּסוּת שֶׁל צֶמֶר מְנַעֲרָהּ אַחַת לִשְׁלֹשִׁים יוֹם. וְלֹא יְנַעֲרֶנָּה בְּמַקֵּל וְלֹא בִּשְׁנֵי בְּנֵי אָדָם. וְשׁוֹטְחָהּ עַל גַּבֵּי מִטָּה לְצָרְכָּהּ בִּלְבַד אֲבָל לֹא לְצָרְכָּהּ וּלְצָרְכּוֹ. נִזְדַּמְּנוּ לוֹ אוֹרְחִים לֹא יִשְׁטְחֶנָּה בִּפְנֵיהֶם וַאֲפִלּוּ לְצָרְכָּהּ שֶׁמָּא תִּגָּנֵב:","מָצָא כְּלֵי עֵץ מִשְׁתַּמֵּשׁ בָּהֶן כְּדֵי שֶׁלֹּא יֵרָקְבוּ. כְּלֵי נְחשֶׁת מִשְׁתַּמֵּשׁ בָּהֶן בְּחַמִּין אֲבָל לֹא עַל יְדֵי הָאוּר מִפְּנֵי שֶׁמַּשְׁחִיקָן. כְּלֵי כֶּסֶף מִשְׁתַּמֵּשׁ בָּהֶן בְּצוֹנֵן אֲבָל לֹא בְּחַמִּין מִפְּנֵי שֶׁמַּשְׁחִירָן. מָצָא מַגְּרֵפוֹת וְקַרְדֻּמּוֹת יִשְׁתַּמֵּשׁ בָּהֶן בְּרַךְ אֲבָל לֹא בְּקָשֶׁה מִפְּנֵי שֶׁמַּפְחִיתָן. מָצָא כְּלֵי זָהָב וּכְלֵי זְכוּכִית וּכְסוּת שֶׁל פִּשְׁתָּן הֲרֵי זֶה לֹא יִגַּע בָּהֶן עַד שֶׁיָּבוֹא אֵלִיָּהוּ. וּכְדֶרֶךְ שֶׁאָמְרוּ בַּאֲבֵדָה כָּךְ אָמְרוּ בְּפִקָּדוֹן שֶׁהָלְכוּ בְּעָלָיו לִמְדִינַת הַיָּם:","מָצָא סְפָרִים קוֹרֵא בָּהֶן אַחַת לִשְׁלֹשִׁים יוֹם וְאִם אֵינוֹ יוֹדֵעַ לִקְרוֹת גּוֹלְלָן כָּל שְׁלֹשִׁים יוֹם. וּלְעוֹלָם לֹא יִלְמֹד בָּהֶן לְכַתְּחִלָּה. וְלֹא יִקְרָא פָּרָשָׁה וְיִשְׁנֶה. וְלֹא יִקְרָא פָּרָשָׁה וִיתַרְגֵּם. וְלֹא יִפְתַּח בּוֹ יֶתֶר מִשְּׁלֹשָׁה דַּפִּין. וְלֹא יִהְיוּ שְׁנַיִם קוֹרִין בִּשְׁנֵי עִנְיָנִין שֶׁמָּא יִמְשֹׁךְ זֶה וְיִמְשֹׁךְ זֶה וְיִבְלֶה הַסֵּפֶר. אֲבָל קוֹרִין הֵן בְּעִנְיָן אֶחָד. וְלֹא יִקְרְאוּ שְׁלֹשָׁה בְּסֵפֶר אֶחָד וַאֲפִלּוּ בְּעִנְיָן אֶחָד:","מָצָא תְּפִלִּין שָׁם דְּמֵיהֶן וּמֵנִיחָן עָלָיו שֶׁדָּבָר מָצוּי הוּא בְּיַד הַכּל וְאֵין עֲשׂוּיִין אֶלָּא לְמִצְוָתָן בִּלְבַד:","מָצָא דָּבָר שֶׁיֵּשׁ בּוֹ רוּחַ חַיִּים שֶׁהֲרֵי צָרִיךְ הוּא לְהַאֲכִילוֹ. אִם הָיָה דָּבָר שֶׁעוֹשֶׂה וְאוֹכֵל כְּגוֹן פָּרָה וַחֲמוֹר מְטַפֵּל בָּהֶן שְׁנֵים עָשָׂר חֹדֶשׁ מִיּוֹם הַמְּצִיאָה וּמַשְׂכִּירָן וְלוֹקֵחַ שָׂכָר וּמַאֲכִיל. וְאִם הָיָה שְׂכָרָן יֶתֶר עַל אֲכִילָתָן הֲרֵי הַיֶּתֶר לַבְּעָלִים. וְכֵן הַתַּרְנְגוֹלִין מוֹכֵר בֵּיצֵיהֶן וּמַאֲכִילָן כָּל שְׁנֵים עָשָׂר חֹדֶשׁ. מִיכַּן וְאֵילָךְ שָׁם דְּמֵיהֶן עָלָיו וַהֲרֵי הֵן שֶׁלּוֹ וְשֶׁל בְּעָלִים בְּשֻׁתָּפוּת כְּדִין כָּל הַשָּׁם בְּהֵמָה מֵחֲבֵרוֹ:","מָצָא עֲגָלִים וּסְיָחִין שֶׁל רְעִי מְטַפֵּל בָּהֶן שְׁלֹשָׁה חֳדָשִׁים. וְשֶׁל בְּרִיאָה שְׁלֹשִׁים יוֹם. אֲוָזִים וְתַרְנְגוֹלִין גְּדוֹלִים מְטַפֵּל בָּהֶן שְׁלֹשִׁים יוֹם. מָצָא קְטַנִּים וְכָל דָּבָר שֶׁטִּפּוּלוֹ מְרֻבֶּה מִשְּׂכָרוֹ מְטַפֵּל בָּהֶן שְׁלֹשָׁה יָמִים. מִכַּן וְאֵילָךְ מוֹכְרָן בְּבֵית דִּין. וְכֵן פֵּרוֹת שֶׁהִתְחִילוּ לְהַרְקִיב וְכַיּוֹצֵא בָּהֶן מוֹכְרָן בְּבֵית דִּין:","מַה יַּעֲשֶׂה בַּדָּמִים. יִנָּתְנוּ לַמּוֹצֵא וְיֵשׁ לוֹ רְשׁוּת לְהִשְׁתַּמֵּשׁ בָּהֶן. לְפִיכָךְ אִם נֶאֶנְסוּ כְּגוֹן שֶׁטְּרָפָם גַּיִס אוֹ טָבְעוּ בַּיָּם חַיָּב לְשַׁלֵּם וְאַף עַל פִּי שֶׁלֹּא נִשְׁתַּמֵּשׁ בָּהֶן שֶׁכֵּיוָן שֶׁיֵּשׁ לוֹ רְשׁוּת לְהִשְׁתַּמֵּשׁ בָּהֶן הֲרֵי הֵן אֶצְלוֹ כִּשְׁאֵלָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּדְמֵי הָאֲבֵדָה הוֹאִיל וְנִטְפַּל בָּהֶן. אֲבָל מְעוֹת אֲבֵדָה לֹא יִשְׁתַּמֵּשׁ בָּהֶן. לְפִיכָךְ אִם אָבְדוּ בְּאֹנֶס פָּטוּר שֶׁהֲרֵי הוּא שׁוֹמֵר שָׂכָר כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל אוֹתָן הַיָּמִים שֶׁמְּטַפֵּל בָּאֲבֵדָה קֹדֶם שֶׁיִּמְכְּרֶנָּה בְּבֵית דִּין אִם הֶאֱכִילָם מִשֶּׁלּוֹ נוֹטֵל מִן הַבְּעָלִים. וְיֵרָאֶה לִי שֶׁהוּא נוֹטֵל בְּלֹא שְׁבוּעָה מִפְּנֵי תִּקּוּן הָעוֹלָם:","הַמּוֹצֵא מְצִיאָה לֹא יִשָּׁבַע מִפְּנֵי תִּקּוּן הָעוֹלָם שֶׁאִם אַתָּה אוֹמֵר יִשָּׁבַע יַנִּיחַ הַמְּצִיאָה וְיֵלֵךְ לוֹ כְּדֵי שֶׁלֹּא יִשָּׁבַע. אֲפִלּוּ מָצָא כִּיס וְטָעַן בַּעַל הַמְּצִיאָה שֶׁשְּׁנֵי כִּיסִים קְשׁוּרִים הָיוּ וְאִי אֶפְשָׁר שֶׁיִּמְצָא הָאֶחָד אֶלָּא אִם נִמְצָא הָאַחֵר הַקָּשׁוּר עִמּוֹ הֲרֵי זֶה לֹא יִשָּׁבַע:"],"Mishneh Torah, Robbery and Lost Property 8":["הַגּוֹזֵל אֶת חֲבֵרוֹ וּמֵת הַנִּגְזָל יַחְזִיר הַגְּזֵלָה לַיּוֹרְשִׁים. וְאִם אָבְדָה אוֹ נִשְׁתַּנֵּית נוֹתֵן לָהֶם דָּמֶיהָ. וְאִם נִשְׁבַּע לוֹ וְאַחַר כָּךְ מֵת נוֹתֵן לַיּוֹרְשִׁים הַקֶּרֶן וְהַחֹמֶשׁ:","הַגּוֹזֵל אֶת אָבִיו וְנִשְׁבַּע לוֹ וּמֵת הָאָב. אִם אֵין הַגְּזֵלָה קַיֶּמֶת אוֹ נִשְׁתַּנֵּית עוֹשֶׂה חֶשְׁבּוֹן עִם אֶחָיו עַל הַקֶּרֶן וְעַל הַחֹמֶשׁ. וְאִם הַגְּזֵלָה קַיֶּמֶת חַיָּב לְהוֹצִיא הַגְּזֵלָה עַצְמָהּ מִתַּחַת יָדוֹ. לְפִיכָךְ נוֹתֵן אֶת הַגְּזֵלָה וְאֶת הַחֹמֶשׁ לְאֶחָיו וְעוֹשֶׂה עִמָּהֶן חֶשְׁבּוֹן:","אִם אֵין לוֹ אַחִין שֶׁנִּמְצָא זֶה הַגַּזְלָן לְבַדּוֹ הוּא הַיּוֹרֵשׁ מוֹצִיא הַגְּזֵלָה מִתַּחַת יָדוֹ לְבָנָיו וְאִם אֵין בָּנִים לְזֶה הַבֵּן הַגַּזְלָן נוֹתְנָהּ לְבַעַל חוֹבוֹ אוֹ בְּהַלְוָאָתוֹ אוֹ לִצְדָקָה. הוֹאִיל וְיָצְאָה הַגְּזֵלָה עַצְמָהּ מִתַּחַת יָדוֹ נִפְטַר אַף עַל פִּי שֶׁנְּתָנָהּ מַתָּנָה אוֹ פְּרָעָהּ בְּחוֹבוֹ. וְהוּא שֶׁיּוֹדִיעֵם וְיֹאמַר זֶה גֵּזֶל אַבָּא:","וְכֵן הַגּוֹזֵל אֶת הַגֵּר וְנִשְׁבַּע לוֹ וְחָזַר וְהוֹדָה לוֹ וְזָקַף עָלָיו הַכּל מִלְוֶה וְאַחַר כָּךְ מֵת הַגֵּר אַף עַל פִּי שֶׁזָּכָה בַּגְּזֵלָה חַיָּב לְהוֹצִיאָהּ מִתַּחַת יָדוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהוֹדָה בֵּינְתַיִם. אֲבָל אִם גָּזַל אֶת הַגֵּר שֶׁאֵין לוֹ יוֹרְשִׁים וְנִשְׁבַּע לוֹ וּמֵת הַגֵּר הֲרֵי זֶה חַיָּב לְשַׁלֵּם הַקֶּרֶן וְחֹמֶשׁ לַכֹּהֲנִים שֶׁל אוֹתוֹ מִשְׁמָר וּמֵבִיא אֲשָׁמוֹ וְאַחַר כָּךְ יִתְכַּפֵּר בּוֹ:","מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר בַּתּוֹרָה (במדבר ה ח) \"וְאִם אֵין לָאִישׁ גֹּאֵל\" בְּגֵר שֶׁמֵּת וְאֵין לוֹ יוֹרְשִׁים הַכָּתוּב מְדַבֵּר וְאָשָׁם זֶה הָאָמוּר כָּאן הוּא הַגְּזֵלָה אוֹ דָּמֶיהָ. לְפִיכָךְ הַמַּחֲזִיר גֵּזֶל הַגֵּר בַּלַּיְלָה לֹא יָצָא. שֶׁהֲרֵי אָשָׁם קְרָאוֹ הַכָּתוּב וְאֵין מַקְרִיבִין בַּלַּיְלָה. וְאֵין הַכֹּהֲנִים חוֹלְקִין גֵּזֶל הַגֵּר כְּנֶגֶד גֵּזֶל הַגֵּר כְּדֶרֶךְ שֶׁאֵין חוֹלְקִין בְּשַׂר אָשָׁם נֶגֶד בְּשַׂר אָשָׁם אַחֵר:","כָּל גֵּזֶל הַגֵּר שֶׁאֵין בּוֹ שְׁוֵה פְּרוּטָה לְכָל כֹּהֵן וְכֹהֵן מֵאַנְשֵׁי מִשְׁמָר לֹא יָצָא הַמַּחְזִירוֹ יְדֵי הֲשָׁבָה שֶׁנֶּאֱמַר (במדבר ה ח) \"הַמּוּשָׁב לַה' לַכֹּהֵן\" עַד שֶׁתִּהְיֶה הֲשָׁבָה לְכָל כֹּהֵן. וְלָמָּה נֶאֱמַר בְּגֵזֶל הַגֵּר (במדבר ה ח) \"אִישׁ\" שֶׁהָאִישׁ אַתָּה צָרִיךְ לַחְקֹר וּלְחַזֵּר עָלָיו אִם יֵשׁ לוֹ יוֹרְשִׁים אוֹ אִם אֵין לוֹ אֲבָל אִם הָיָה הַגֵּר קָטָן אִי אַתָּה צָרִיךְ לְחַזֵּר עָלָיו אֶלָּא חֶזְקָתוֹ שֶׁאֵין לוֹ יוֹרְשִׁים:","הַכֹּהֲנִים בְּגֵזֶל הַגֵּר כִּמְקַבְּלֵי מַתָּנוֹת הֵן. לְפִיכָךְ הַגּוֹזֵל חָמֵץ מִן הַגֵּר שֶׁאֵין לוֹ יוֹרְשִׁים וְעָבַר עָלָיו הַפֶּסַח חַיָּב לִתֵּן לַכֹּהֲנִים אֶת דָּמָיו כִּשְׁעַת הַגְּזֵלָה. שֶׁאִם יִתְּנֵהוּ לָהֶן עַכְשָׁו אֵינָהּ מַתָּנָה שֶׁהֲרֵי הוּא אָסוּר בַּהֲנָאָה. וְאִלּוּ הָיָה הַגֵּר קַיָּם הָיָה אוֹמֵר לוֹ הֲרֵי שֶׁלְּךָ לְפָנֶיךָ כְּמוֹ שֶׁבֵּאַרְנוּ:","כֹּהֵן שֶׁגָּזַל גֵּר שֶׁאֵין לוֹ יוֹרְשִׁים וְנִשְׁבַּע לוֹ וּמֵת הַגֵּר לֹא זָכָה זֶה בִּגְזֵלוֹ שֶׁתַּחַת יָדוֹ אֶלָּא יוֹצִיא מִתַּחַת יָדוֹ לְכָל אֶחָיו הַכֹּהֲנִים בְּנֵי הַמִּשְׁמֶרֶת:","הַגּוֹזֵל אֶת הַגֵּר וְנִשְׁבַּע לוֹ וּמֵת הַגֵּר וְהִפְרִישׁ אֲשָׁמוֹ וּגְזֵלָתוֹ לְהַעֲלוֹתָן לַכֹּהֲנִים וּמֵת הַגַּזְלָן קֹדֶם כַּפָּרָה הֲרֵי בְּנֵי הַגַּזְלָן יוֹרְשִׁים אֶת כֶּסֶף הַגְּזֵלָה אוֹ הַגְּזֵלָה עַצְמָהּ וְהָאָשָׁם יִרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְקוֹמוֹ:","נָתַן הַגַּזְלָן אֶת הַכֶּסֶף לְאַנְשֵׁי מִשְׁמָר וּמֵת קֹדֶם כַּפָּרָה אֵין יוֹרְשֵׁי הַגַּזְלָן יְכוֹלִין לְהוֹצִיא מִיַּד הַכֹּהֲנִים שֶׁנֶּאֱמַר (במדבר ה י) \"אִישׁ אֲשֶׁר יִתֵּן לַכֹּהֵן לוֹ יִהְיֶה\". וַאֲפִלּוּ הָיָה הַגַּזְלָן קָטָן שֶׁאֵין מַתְּנָתוֹ מַתָּנָה אֵין יוֹרְשָׁיו מוֹצִיאִין מִיַּד הַכֹּהֲנִים:","נָתַן אֶת הַכֶּסֶף לְאַחַת מִן הַמִּשְׁמָרוֹת וְאֶת הָאָשָׁם לְמִשְׁמָרָה זוֹ שֶׁהִיא שַׁבַּתָּהּ יַחְזִיר הַכֶּסֶף אֵצֶל הָאָשָׁם לְאַנְשֵׁי הַמִּשְׁמָרָה הַקְּבוּעָה שֶׁהַמִּשְׁמָרָה שֶׁלָּקְחָה כֶּסֶף בְּלֹא שַׁבַּתָּהּ לֹא זָכְתָה וּמוֹצִיאִין מִיָּדָהּ:","אֵין מַקְרִיבִין אֶת הָאָשָׁם עַד שֶׁיַּחְזִיר הַגַּזְלָן הַקֶּרֶן לַבְּעָלִים אוֹ לַכֹּהֲנִים אִם הָיָה גֵּזֶל גֵּר שֶׁאֵין לוֹ יוֹרְשִׁים. נָתַן אֶת הַקֶּרֶן וְהִקְרִיב אֲשָׁמוֹ נִתְכַּפֵּר לוֹ וְאֵין הַחֹמֶשׁ מְעַכֵּב הַכַּפָּרָה וְחַיָּב לִתֵּן אֶת הַחֹמֶשׁ אַחַר כַּפָּרָה:","הָעֲבָדִים וְהַשְּׁטָרוֹת וְהַקַּרְקָעוֹת אֵין בָּהֶן תּוֹסֶפֶת חֹמֶשׁ שֶׁנֶּאֱמַר (ויקרא ה כא) \"וְכִחֵשׁ בַּעֲמִיתוֹ בְּפִקָּדוֹן\". כָּל הָאָמוּר בָּעִנְיַן מִטַּלְטְלִין הוּא וְגוּפָן מָמוֹן. יָצְאוּ קַרְקָעוֹת וַעֲבָדִים שֶׁהֻקְּשׁוּ לְקַרְקָעוֹת וְיָצְאוּ שְׁטָרוֹת שֶׁאֵין גּוּפָן מָמוֹן. וְכֵן אִם הָיוּ גֵּזֶל גֵּר שֶׁאֵין לוֹ יוֹרְשִׁים אֵינָן חוֹזְרִים לַכֹּהֲנִים. וְכֵן הַקַּרְקַע אֵינָהּ נִקְנֵית לְעוֹלָם לַגַּזְלָן אֶלָּא בִּרְשׁוּת בְּעָלֶיהָ עוֹמֶדֶת. וַאֲפִלּוּ נִמְכְּרָה לְאֶלֶף זֶה אַחַר זֶה וְנִתְיָאֲשׁוּ הַבְּעָלִים הֲרֵי זוֹ חוֹזֶרֶת לַנִּגְזָל בְּלֹא דָּמִים. וְכָל מִי שֶׁיָּצְאָה מִתַּחַת יָדוֹ חוֹזֶרֶת עַל זֶה שֶׁמְּכָרָהּ לוֹ וְחוֹזֵר הַמּוֹכֵר הַשֵּׁנִי עַל הַמּוֹכֵר הָרִאשׁוֹן עַד שֶׁיַּחֲזֹר הַלּוֹקֵחַ מִן הַגַּזְלָן עַל הַגַּזְלָן וְיִטּל מִמֶּנּוּ כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Sabbath 19":["כָּל כְּלֵי הַמִּלְחָמָה אין יוֹצְאִין בָּהֶן בְּשַׁבָּת. וְאִם יָצָא אִם הָיוּ כֵּלִים שֶׁהֵן דֶּרֶךְ מַלְבּוּשׁ כְּגוֹן שִׁרְיוֹן וְכוֹבַע וּמַגָּפַיִם שֶׁעַל הָרַגְלַיִם הֲרֵי זֶה פָּטוּר. וְאִם יָצָא בְּכֵלִים שֶׁאֵינָן דֶּרֶךְ מַלְבּוּשׁ כְּגוֹן רֹמַח וְסַיִף וְקֶשֶׁת וְאַלָּה וּתְרִיס הֲרֵי זֶה חַיָּב:","אֵין יוֹצְאִין בְּסַנְדָּל מְסֻמָּר שֶׁסְּמָרוֹ לְחַזְּקוֹ. וַאֲפִלּוּ בְּיוֹם טוֹב גָּזְרוּ עָלָיו שֶׁלֹּא יֵצֵא בּוֹ. וּמֻתָּר לָצֵאת בְּאַבְנֵט שֶׁיֵּשׁ עָלָיו חֲתִיכוֹת קְבוּעוֹת שֶׁל כֶּסֶף וְשֶׁל זָהָב כְּמוֹ שֶׁהַמְּלָכִים עוֹשִׂין. מִפְּנֵי שֶׁהוּא תַּכְשִׁיט וְכָל שֶׁהוּא תַּכְשִׁיט מֻתָּר. וְהוּא שֶׁלֹּא יְהֵא רָפוּי שֶׁמָּא יִפּל בִּרְשׁוּת הָרַבִּים וְיָבוֹא לַהֲבִיאוֹ:","טַבַּעַת שֶׁיֵּשׁ עָלֶיהָ חוֹתָם מִתַּכְשִׁיטֵי הָאִישׁ הִיא וְאֵינָהּ מִתַּכְשִׁיטֵי הָאִשָּׁה. וְשֶׁאֵין עָלֶיהָ חוֹתָם מִתַּכְשִׁיטֵי אִשָּׁה וְאֵינָהּ מִתַּכְשִׁיטֵי הָאִישׁ. לְפִיכָךְ אִשָּׁה שֶׁיָּצָאת בְּטַבַּעַת שֶׁיֵּשׁ עָלֶיהָ חוֹתָם. וְאִישׁ שֶׁיָּצָא בְּטַבַּעַת שֶׁאֵין עָלֶיהָ חוֹתָם חַיָּבִין. וּמִפְּנֵי מָה הֵן חַיָּבִין וַהֲרֵי הוֹצִיאוּ אוֹתָן שֶׁלֹּא כְּדֶרֶךְ הַמּוֹצִיאִין שֶׁאֵין דֶּרֶךְ הָאִישׁ לְהוֹצִיא בְּאֶצְבָּעוֹ אֶלָּא טַבַּעַת הָרְאוּיָה לוֹ וְכֵן הָאִשָּׁה אֵין דַּרְכָּהּ לְהוֹצִיא בְּאֶצְבָּעָהּ אֶלָּא טַבַּעַת הָרְאוּיָה לָהּ. מִפְּנֵי שֶׁפְּעָמִים נוֹתֵן הָאִישׁ טַבַּעְתּוֹ לְאִשְׁתּוֹ לְהַצְנִיעָהּ בַּבַּיִת וּמַנַּחַת אוֹתָהּ בְּאֶצְבָּעָהּ בְּעֵת הוֹלָכָה. וְכֵן הָאִשָּׁה נוֹתֶנֶת טַבַּעְתָּהּ לְבַעְלָהּ לְתַקְּנָהּ אֵצֶל הָאֻמָּן וּמַנִּיחַ אוֹתָהּ בְּאֶצְבָּעוֹ בְּעֵת הוֹלָכָה עַד חֲנוּת הָאֻמָּן וְנִמְצְאוּ שֶׁהוֹצִיאוּ אוֹתָן כְּדֶרֶךְ שֶׁדַּרְכָּן לְהוֹצִיאָן וּלְפִיכָךְ חַיָּבִין:","לֹא תֵּצֵא אִשָּׁה בְּטַבַּעַת שֶׁאֵין עָלֶיהָ חוֹתָם אַף עַל פִּי שֶׁהוּא מִתַּכְשִׁיטֶיהָ גְּזֵרָה שֶׁמָּא תּוֹצִיאָהּ בִּרְשׁוּת הָרַבִּים לְהַרְאוֹת לְחַבְרוֹתֶיהָ כְּדֶרֶךְ שֶׁהַנָּשִׁים עוֹשׂוֹת תָּמִיד. וְאִם יָצָאת בָּהּ פְּטוּרָה. אֲבָל הָאִישׁ מֻתָּר לָצֵאת בְּטַבַּעַת שֶׁיֵּשׁ עָלֶיהָ חוֹתָם מִפְּנֵי שֶׁהוּא תַּכְשִׁיט וְאֵין דַּרְכּוֹ לְהֵרָאוֹת. וְנָהֲגוּ כָּל הָעָם שֶׁלֹּא יֵצְאוּ בְּטַבַּעַת כְּלָל:","אִשָּׁה שֶׁיָּצְאָה בְּמַחַט נְקוּבָה חַיֶּבֶת וְהָאִישׁ פָּטוּר. וְאִישׁ שֶׁיָּצָא בְּמַחַט שֶׁאֵינָהּ נְקוּבָה חַיָּב וְהָאִשָּׁה פְּטוּרָה מִפְּנֵי שֶׁהִיא מִתַּכְשִׁיטֶיהָ וְאֵינָהּ אֲסוּרָה אֶלָּא גְּזֵרָה שֶׁמָּא תַּרְאֶה לְחַבְרוֹתֶיהָ. זֶה הַכְּלָל כָּל הַיּוֹצֵא בְּדָבָר שֶׁאֵינוֹ מִתַּכְשִׁיטָיו וְאֵינוֹ דֶּרֶךְ מַלְבּוּשׁ וְהוֹצִיאוֹ כְּדֶרֶךְ שֶׁמּוֹצִיאִין אוֹתוֹ דָּבָר חַיָּב. וְכָל הַיּוֹצֵא בְּדָבָר שֶׁהוּא מִתַּכְשִׁיטָיו וְהָיָה רָפוּי וְאֶפְשָׁר שֶׁיִּפּל בִּמְהֵרָה וְיָבֹא לַהֲבִיאוֹ בִּרְשׁוּת הָרַבִּים. וְכֵן אִשָּׁה שֶׁיָּצָאת בְּתַכְשִׁיטִין שֶׁדַּרְכָּן לִשְׁלֹף אוֹתָן וּלְהַרְאוֹתָן הֲרֵי אֵלּוּ פְּטוּרִין. וְכָל דָּבָר שֶׁהוּא תַּכְשִׁיט וְאֵינוֹ נוֹפֵל וְאֵין דַּרְכָּהּ לְהַרְאוֹתוֹ הֲרֵי זֶה מֻתָּר לָצֵאת בּוֹ. לְפִיכָךְ אֶצְעָדָה שֶׁמַּנִּיחִין אוֹתָהּ בַּזְּרוֹעַ אוֹ בַּשּׁוֹק יוֹצְאִין בָּהּ בְּשַׁבָּת וְהוּא שֶׁתִּהְיֶה דְּבוּקָה לַבָּשָׂר וְלֹא תִּשָּׁמֵט. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","לֹא תֵּצֵא אִשָּׁה בְּחוּטֵי צֶמֶר אוֹ בְּחוּטֵי פִּשְׁתָּן אוֹ בִּרְצוּעוֹת הַקְּשׁוּרוֹת לָהּ עַל רֹאשָׁהּ שֶׁמָּא תַּחְלֹץ אוֹתָהּ בִּשְׁעַת טְבִילָה וְתַעֲבִירָהּ בִּרְשׁוּת הָרַבִּים. וְלֹא בְּצִיץ שֶׁמַּנַּחַת בֵּין עֵינֶיהָ וְלֹא בִּלְחָיַיִם שֶׁל זָהָב שֶׁיּוֹרְדִין מִן הַצִּיץ עַל לְחָיֶיהָ בִּזְמַן שֶׁאֵינָן תְּפוּרִין זֶה בָּזֶה. וְלֹא בַּעֲטָרָה שֶׁל זָהָב שֶׁמֻּנַּחַת בְּרֹאשָׁהּ וְלֹא בִּכְבָלִים שֶׁיּוֹצְאִין בָּהֶן הַבָּנוֹת בְּרַגְלֵיהֶן כְּדֵי שֶׁלֹּא יִפְסְעוּ פְּסִיעָה גַּסָּה שֶׁלֹּא יַפְסִידוּ בְּתוּלֵיהֶן. כָּל אֵלּוּ אֲסוּרִין לָצֵאת בָּהֶן בְּשַׁבָּת שֶׁמָּא יִפְּלוּ וּתְבִיאֵן בְּיָדָהּ:","לֹא תֵּצֵא אִשָּׁה בְּקַטְלָא שֶׁבְּצַוָּארָה וְלֹא בְּנִזְמֵי הָאַף וְלֹא בִּצְלוֹחִית שֶׁל פְּלַיָּיטוֹן הַקְּבוּעָה עַל זְרוֹעָהּ. וְלֹא בַּכִּיס הַקָּטָן הֶעָגל שֶׁמַּנִּיחִין בּוֹ שֶׁמֶן הַטּוֹב וְהוּא הַנִּקְרָא כּוֹבֶלֶת. וְלֹא בְּפֵאָה שֶׁל שֵׂעָר שֶׁמַּנַּחַת עַל רֹאשָׁהּ כְּדֵי שֶׁתֵּרָאֶה בַּעֲלַת שֵׂעָר הַרְבֵּה. וְלֹא בְּכָבוּל שֶׁל צֶמֶר שֶׁמַּקֶּפֶת אוֹתוֹ סָבִיב לְפָנֶיהָ. וְלֹא בְּשֵׁן שֶׁמַּנַּחַת בְּפִיהָ בִּמְקוֹם שֵׁן שֶׁנָּפַל. וְלֹא בְּשֵׁן שֶׁל זָהָב שֶׁמַּנַּחַת עַל שֵׁן שָׁחֹר אוֹ אָדֹם שֶׁיֵּשׁ בְּשִּׁנֶּיהָ. אֲבָל שֵׁן שֶׁל כֶּסֶף מֻתָּר מִפְּנֵי שֶׁאֵינוֹ נִכָּר. כָּל אֵלּוּ אֲסוּרִין לָצֵאת בָּהֶן שֶׁמָּא יִפְּלוּ וּתְבִיאֵם בְּיָדָהּ אוֹ תַּחְלֹץ וְתַרְאֶה לְחַבְרוֹתֶיהָ:","כָּל שֶׁאָסְרוּ חֲכָמִים לָצֵאת בּוֹ לִרְשׁוּת הָרַבִּים אָסוּר לוֹ לָצֵאת בּוֹ אֲפִלּוּ בְּחָצֵר שֶׁאֵינָהּ מְעֹרֶבֶת. חוּץ מִכָּבוּל וּפֵאָה שֶׁל שֵׂעָר שֶׁמֻּתָּר לָצֵאת בָּהֶן לְחָצֵר שֶׁאֵינָהּ מְעֹרֶבֶת כְּדֵי שֶׁלֹּא תִּתְגַּנֶּה עַל בַּעְלָהּ. וְהַיּוֹצֵאת בִּצְלוֹחִית שֶׁל פְּלַיָּיטוֹן שֶׁאֵין בָּהּ בּשֶֹׁם כְּלָל חַיֶּבֶת:","יוֹצְאָה אִשָּׁה בְּחוּטֵי שֵׂעָר הַקְּשׁוּרִים לָהּ עַל רֹאשָׁהּ מִפְּנֵי שֶׁהַמַּיִם בָּאִין בָּהֶן וְאֵינָן חוֹצְצִין וְאֵינָהּ חוֹלַצְתָּן אִם אֵרְעָה לָהּ טְבִילָה עַד שֶׁנִּגְזֹר שֶׁמָּא תְּבִיאֵם לִרְשׁוּת הָרַבִּים. בֵּין שֶׁהָיוּ הַחוּטִין שֶׁלָּהּ בֵּין שֶׁל חֲבֶרְתָּהּ בֵּין שֶׁל בְּהֵמָה. וְלֹא תֵּצֵא הַזְּקֵנָה בְּשֶׁל יַלְדָּה שֶׁשֶּׁבַח הֵן לָהּ וְשֶׁמָּא תַּחְלֹץ וְתַרְאֵם לְחַבְרוֹתֶיהָ. אֲבָל יַלְדָּה יוֹצֵאת בְּחוּטֵי זְקֵנָה. וְכָל שֶׁהוּא אָרוּג יוֹצֵאת בּוֹ עַל רֹאשָׁהּ:","יוֹצְאָה אִשָּׁה בְּחוּטִין שֶׁבְּצַוָּארָה מִפְּנֵי שֶׁאֵינָהּ חוֹנֶקֶת עַצְמָהּ בָּהֶן וְאֵינָן חוֹצְצִין. וְאִם הָיוּ צְבוּעִין אֲסוּרִים שֶׁמָּא תַּרְאֶה אוֹתָן לְחַבְרוֹתֶיהָ. וְיוֹצְאָה אִשָּׁה בְּכָלִיל שֶׁל זָהָב בְּרֹאשָׁהּ שֶׁאֵין יוֹצְאָה בּוֹ אֶלָּא אִשָּׁה חֲשׁוּבָה שֶׁאֵין דַּרְכָּהּ לַחֲלֹץ וּלְהַרְאוֹת. וְיוֹצְאָה בְּצִיץ וּבִלְחָיַיִם שֶׁל זָהָב בִּזְמַן שֶׁהֵן תְּפוּרִין בִּשְׂבָכָה שֶׁעַל רֹאשָׁהּ כְּדֵי שֶׁלֹּא יִפּלוּ. וְכֵן כָּל כַּיּוֹצֵא בָּהֶם:","יוֹצְאָה אִשָּׁה בְּמוֹךְ שֶׁבְּאָזְנָהּ וְהוּא שֶׁיִּהְיֶה קָשׁוּר בְּאָזְנָהּ. וּבְמוֹךְ שֶׁבְּסַנְדָּלָהּ וְהוּא שֶׁיִּהְיֶה קָשׁוּר בְּסַנְדָּלָהּ. וּבְמוֹךְ שֶׁהִתְקִינָה לְנִדָּתָהּ וְאַף עַל פִּי שֶׁאֵינוֹ קָשׁוּר וַאֲפִלּוּ עָשְׂתָה לוֹ בֵּית יָד שֶׁאִם נָפַל אֵינָהּ מְבִיאָה אוֹתוֹ מִפְּנֵי מְאִיסוּתוֹ:","וְיוֹצְאָה בְּפִלְפֵּל וּבְגַרְגִּיר מֶלַח וּבְכָל דָּבָר שֶׁתִּתֵּן לְתוֹךְ פִּיהָ מִפְּנֵי רֵיחַ הַפֶּה. וְלֹא תִּתֵּן לְכַתְּחִלָּה בְּשַׁבָּת. יוֹצְאוֹת הַנָּשִׁים בְּקֵיסָמִין שֶׁבְּאָזְנֵיהֶן וּבִרְעָלוֹת שֶׁבְּצַוָּארָן אוֹ שֶׁבִּכְסוּתָן וּבָרְדִיד הַפָּרוּף וּפוֹרֶפֶת בַּתְּחִלָּה בְּשַׁבָּת עַל הָאֶבֶן וְעַל הָאֱגוֹז וְיוֹצְאָה. וְלֹא תַּעֲרִים וְתִפְרֹף עַל הָאֱגוֹז כְּדֵי לְהוֹצִיאוֹ לִבְנָהּ הַקָּטָן. וְכֵן לֹא תִּפְרֹף עַל הַמַּטְבֵּעַ לְכַתְּחִלָּה מִפְּנֵי שֶׁאָסוּר לְטַלְטְלוֹ. וְאִם פָּרְפָה יוֹצְאָה בּוֹ:","יוֹצֵא אָדָם בְּקֵיסָם שֶׁבְּשִׁנָּיו וְשֶׁבְּסַנְדָּלוֹ לִרְשׁוּת הָרַבִּים. וְאִם נָפַל לֹא יַחֲזִיר. וּבְמוֹךְ וּבִסְפוֹג שֶׁעַל גַּבֵּי הַמַּכָּה וּבִלְבַד שֶׁלֹּא יִכְרֹךְ עֲלֵיהֶן חוּט אוֹ מְשִׁיחָה שֶׁהֲרֵי הַחוּט וְהַמְּשִׁיחָה חֲשׁוּבִין אֶצְלוֹ וְאֵינָם מוֹעִילִין לַמַּכָּה. וְיוֹצֵא בִּקְלִפַּת הַשּׁוּם וּבִקְלִפַּת הַבָּצָל שֶׁעַל הַמַּכָּה וּבְאֶגֶד שֶׁעַל גַּבֵּי מַכָּה וְקוֹשְׁרוֹ וּמַתִּירוֹ בְּשַׁבָּת. וּבְאִסְפְּלָנִית וּמְלוּגְמָא וּרְטִיָּה שֶׁעַל גַּבֵּי הַמַּכָּה וּבְסֶלַע שֶׁעַל הִצִּינִית וּבְבֵיצַת הַחַרְגּוֹל וּבְשֵׁן הַשּׁוּעָל וּבְמַסְמֵר הַצָּלוּב. וּבְכָל דָּבָר שֶׁתּוֹלִין אוֹתוֹ מִשּׁוּם רְפוּאָה וְהוּא שֶׁיֹּאמְרוּ הָרוֹפְאִים שֶׁהוּא מוֹעִיל:","יוֹצֵאת הָאִשָּׁה בְּאֶבֶן תְּקוּמָה וּבְמִשְׁקַל אֶבֶן תְּקוּמָה שֶׁנִּתְכַּוֵּן וּשְׁקָלוֹ לִרְפוּאָה. וְלֹא אִשָּׁה עֻבָּרָה בִּלְבַד אֶלָּא אֲפִלּוּ שְׁאָר הַנָּשִׁים שֶׁמָּא תִּתְעַבֵּר וְתַפִּיל. וְיוֹצְאִין בְּקָמֵעַ מֻמְחֶה. וְאֵי זֶה הוּא קָמֵעַ מֻמְחֶה זֶה שֶׁרִפֵּא לִשְׁלֹשָׁה בְּנֵי אָדָם אוֹ שֶׁעֲשָׂהוּ אָדָם שֶׁרִפֵּא שְׁלֹשָׁה בְּנֵי אָדָם בִּקְמֵעִין אֲחֵרִים. וְאִם יָצָא בְּקָמֵעַ שֶׁאֵינוֹ מֻמְחֶה פָּטוּר. מִפְּנֵי שֶׁהוֹצִיאוֹ דֶּרֶךְ מַלְבּוּשׁ. וְכֵן הַיּוֹצֵא בִּתְפִלִּין פָּטוּר:","מִי שֶׁיֵּשׁ בְּרַגְלוֹ מַכָּה יוֹצֵא בְּסַנְדָּל יְחִידִי בְּרַגְלוֹ הַבְּרִיאָה. וְאִם אֵין בְּרַגְלוֹ מַכָּה לֹא יֵצֵא בְּסַנְדָּל יָחִיד. וְלֹא יֵצֵא קָטָן בְּמִנְעָל גָּדוֹל אֲבָל יוֹצֵא הוּא בְּחָלוּק גָּדוֹל. וְלֹא תֵּצֵא אִשָּׁה בְּמִנְעָל רָפוּי וְלֹא בְּמִנְעָל חָדָשׁ שֶׁלֹּא יָצְאָה בּוֹ שָׁעָה אַחַת מִבְּעוֹד יוֹם. וְאֵין הַקִּטֵּעַ יוֹצֵא בְּקַב שֶׁלּוֹ. אַנְקַּטְמִין שֶׁל עֵץ אֵין יוֹצְאִין בָּהֶן בְּשַׁבָּת מִפְּנֵי שֶׁאֵינָן מִדַּרְכֵי הַמַּלְבּוּשׁ. וְאִם יָצְאוּ פְּטוּרִין:","יוֹצְאִין בִּפְקָרִיוֹן וּבְצִיפָה שֶׁבְּרָאשֵׁי בַּעֲלֵי חֲטָטִין. אֵימָתַי בִּזְמַן שֶׁצְּבָעָן בְּשֶׁמֶן וּכְרָכָן אוֹ שֶׁיָּצָא בָּהֶן שָׁעָה אַחַת מִבְּעוֹד יוֹם. אֲבָל אִם לֹא עָשָׂה בָּהֶן מַעֲשֶׂה וְלֹא יָצָא בָּהֶן קֹדֶם הַשַּׁבָּת אָסוּר לָצֵאת בָּהֶן:","יוֹצְאִין בְּשַׂק עָבֶה וּבִירִיעָה וּבְסָגוֹס עָבֶה וּבַחֲמִילָה מִפְּנֵי הַגְּשָׁמִים. אֲבָל לֹא בְּתֵבָה וְלֹא בְּקֻפָּה וְלֹא בְּמַחְצֶלֶת מִפְּנֵי הַגְּשָׁמִים. הַכַּר וְהַכֶּסֶת אִם הָיוּ רַכִּין וְדַקִּין כְּמוֹ הַבְּגָדִים מֻתָּר לְהוֹצִיאָן מֻנָּחִין עַל רֹאשׁוֹ בְּשַׁבָּת דֶּרֶךְ מַלְבּוּשׁ. וְאִם הָיוּ קָשִׁין הֲרֵי הֵן כְּמַשּׂאוֹי וַאֲסוּרִין:","יוֹצְאִין בְּזוֹגִין הָאֲרוּגִין בַּבְּגָדִים. וְיוֹצֵא הָעֶבֶד בְּחוֹתָם שֶׁל טִיט שֶׁבְּצַוָּארוֹ אֲבָל לֹא בְּחוֹתָם שֶׁל מַתֶּכֶת שֶׁמָּא יִפּל וִיבִיאֶנּוּ. הַמִּתְעַטֵּף בְּטַלִּיתוֹ וְקִפְּלָהּ מִכָּאן וּמִכָּאן בְּיָדוֹ אוֹ עַל כְּתֵפוֹ אִם נִתְכַּוֵּן לְקַבֵּץ כְּנָפָיו כְּדֵי שֶׁלֹּא יִקָּרְעוּ אוֹ שֶׁלֹּא יִתְלַכְלְכוּ אָסוּר. וְאִם קִבְּצָן לְהִתְנָאוֹת בָּהֶן כְּמִנְהַג אַנְשֵׁי הַמָּקוֹם בְּמַלְבּוּשָׁן מֻתָּר:","הַיּוֹצֵא בְּטַלִּית מְקֻפֶּלֶת וּמֻנַּחַת עַל כְּתֵפוֹ חַיָּב. אֲבָל יוֹצֵא הוּא בְּסוּדָר שֶׁעַל כְּתֵפוֹ אַף עַל פִּי שֶׁאֵין נִימָה קְשׁוּרָה לוֹ בְּאֶצְבָּעוֹ. וְכָל סוּדָר שֶׁאֵינוֹ חוֹפֶה רֹאשׁוֹ וְרֻבּוֹ אָסוּר לָצֵאת בּוֹ. הָיְתָה סַכְנִית קְצָרָה שֶׁאֵינָהּ רְחָבָה קוֹשֵׁר שְׁנֵי רָאשֶׁיהָ לְמַטָּה מִכְּתֵפַיִם וְנִמְצֵאת כְּמוֹ אַבְנֵט וּמֻתָּר לָצֵאת בָּהּ:","מֻתָּר לְהִתְעַטֵּף בְּטַלִּית שֶׁיֵּשׁ בְּשִׂפְתוֹתֶיהָ מֶלֶל אַף עַל פִּי שֶׁהֵן חוּטִין אֲרֻכִּין וְאַף עַל פִּי שֶׁאֵינָן נוֹי הַטַּלִּית מִפְּנֵי שֶׁהֵן בְּטֵלִים לְגַבֵּי הַטַּלִּית וְאֵינוֹ מַקְפִּיד עֲלֵיהֶן בֵּין הָיוּ בֵּין לֹא הָיוּ. לְפִיכָךְ הַיּוֹצֵא בְּטַלִּית שֶׁאֵינָהּ מְצֻיֶּצֶת כְּהִלְכָתָהּ חַיָּב מִפְּנֵי שֶׁאוֹתָן הַחוּטִין חֲשׁוּבִין הֵן אֶצְלוֹ וְדַעְתּוֹ עֲלֵיהֶן עַד שֶׁיַּשְׁלִים חֶסְרוֹנָן וְיֵעָשׂוּ צִיצִית. אֲבָל טַלִּית הַמְצֻיֶּצֶת כְּהִלְכָתָהּ מֻתָּר לָצֵאת בָּהּ בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה. שֶׁאֵין הַצִּיצִית הַגְּמוּרָה מַשּׂאוֹי אֶלָּא הֲרֵי הִיא מִנּוֹי הַבֶּגֶד וּמִתַּכְסִיסָיו כְּמוֹ הָאִמְרָא וְכַיּוֹצֵא בָּהּ. וְאִלּוּ הָיוּ חוּטֵי הַצִּיצִית שֶׁהִיא מְצֻיֶּצֶת כְּהִלְכָתָהּ מַשּׂאוֹי הָיָה חַיָּב הַיּוֹצֵא בָּהּ אֲפִלּוּ בְּיוֹם הַשַּׁבָּת שֶׁאֵין מִצְוַת עֲשֵׂה שֶׁאֵין בָּהּ כָּרֵת דּוֹחָה שַׁבָּת:","לֹא יֵצֵא הַחַיָּט בְּשַׁבָּת בְּמַחַט הַתְּחוּבָה לוֹ בְּבִגְדוֹ. וְלֹא נַגָּר בְּקֵיסָם שֶׁבְּאָזְנוֹ. וְלֹא גַּרְדִּי בָּאִירָא שֶׁבְּאָזְנוֹ. וְלֹא סוֹרֵק בִּמְשִׁיחָה שֶׁבְּאָזְנוֹ. וְלֹא שֻׁלְחָנִי בְּדִינָר שֶׁבְּצַוָּארוֹ. וְלֹא צַבָּע בְּדֻגְמָא שֶׁבְּאָזְנוֹ. וְאִם יָצָא פָּטוּר אַף עַל פִּי שֶׁיָּצָא דֶּרֶךְ אֻמָּנוּתוֹ מִפְּנֵי שֶׁלֹּא הוֹצִיא כְּדֶרֶךְ הַמּוֹצִיאִין:","הַזָּב שֶׁיָּצָא בְּכִיס שֶׁלּוֹ חַיָּב מִפְּנֵי שֶׁאֵין דֶּרֶךְ כִּיס זֶה לְהוֹצִיאוֹ אֶלָּא כַּדֶּרֶךְ הַזֹּאת וְאַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ לְגוּף הַהוֹצָאָה אֶלָּא כְּדֵי שֶׁלֹּא יִתְלַכְלְכוּ בְּגָדָיו שֶׁהַמְּלָאכָה שֶׁאֵינָהּ צְרִיכָה לְגוּפָהּ חַיָּב עָלֶיהָ:","הַמּוֹצֵא תְּפִלִּין בְּשַׁבָּת בִּרְשׁוּת הָרַבִּים כֵּיצַד הוּא עוֹשֶׂה. לוֹבְשָׁן כְּדַרְכָּן, מֵנִיחַ שֶׁל יָד בְּיָדוֹ שֶׁל רֹאשׁ בְּרֹאשׁוֹ וְנִכְנָס וְחוֹלְצָן בְּבַיִת וְחוֹזֵר וְיוֹצֵא וְלוֹבֵשׁ זוּג שֵׁנִי וְחוֹלְצָן עַד שֶׁיַּכְנִיס אֶת כֻּלָּן. וְאִם הָיוּ הַרְבֵּה וְלֹא נִשְׁאַר מִן הַיּוֹם כְּדֵי לְהַכְנִיסָן דֶּרֶךְ מַלְבּוּשׁ הֲרֵי זֶה מַחְשִׁיךְ עֲלֵיהֶם וּמַכְנִיסָן בְּמוֹצָאֵי שַׁבָּת. וְאִם הָיָה בִּימֵי הַגְּזֵרָה שֶׁמִּתְיָרֵא לֵישֵׁב וּלְשָׁמְרָן עַד הָעֶרֶב מִפְּנֵי הַכּוּתִים מְכַסָּן בִּמְקוֹמָן וּמַנִּיחָן וְהוֹלֵךְ:","הָיָה מִתְיָרֵא לְהַחְשִׁיךְ עֲלֵיהֶן מִפְּנֵי הַלִּסְטִים נוֹטֵל אֶת כֻּלָּן כְּאַחַת וּמוֹלִיכָן פָּחוֹת פָּחוֹת מֵאַרְבַּע אַמּוֹת אוֹ נוֹתְנָן לַחֲבֵרוֹ בְּתוֹךְ אַרְבַּע אַמּוֹת וַחֲבֵרוֹ לַחֲבֵרוֹ עַד שֶׁמַּגִּיעַ לֶחָצֵר הַחִיצוֹנָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיוּ בָּהֶן רְצוּעוֹתֵיהֶן וְהֵן מְקֻשָּׁרִין קֶשֶׁר שֶׁל תְּפִלִּין שֶׁוַּדַּאי תְּפִלִּין הֵן אֲבָל אִם לֹא הָיוּ רְצוּעוֹתֵיהֶן מְקֻשָּׁרוֹת אֵינוֹ נִזְקָק לָהֶן:","הַמּוֹצֵא סֵפֶר תּוֹרָה יוֹשֵׁב וּמְשַׁמְּרוֹ וּמַחְשִׁיךְ עָלָיו. וּבַסַּכָּנָה מַנִּיחוֹ וְהוֹלֵךְ לוֹ. וְאִם הָיוּ גְּשָׁמִים יוֹרְדִין מִתְעַטֵּף בְּעוֹר וְחוֹזֵר וּמְכַסֶּה אוֹתוֹ וְנִכְנָס בּוֹ:","לֹא יֵצֵא הַחַיָּט בְּמַחֲטוֹ בְּיָדוֹ וְלֹא הַלַּבְלָר בְּקֻלְמוֹסוֹ עֶרֶב שַׁבָּת סָמוּךְ לַחֲשֵׁכָה שֶׁמָּא יִשְׁכַּח וְיוֹצִיא. וְחַיָּב אָדָם לְמַשְׁמֵשׁ בְּבִגְדוֹ עֶרֶב שַׁבָּת עִם חֲשֵׁכָה שֶׁמָּא יִהְיֶה שָׁם דָּבָר שָׁכוּחַ וְיֵצֵא בּוֹ בְּשַׁבָּת. מֻתָּר לָצֵאת בִּתְפִלִּין עֶרֶב שַׁבָּת עִם חֲשֵׁכָה הוֹאִיל וְחַיָּב אָדָם לְמַשְׁמֵשׁ בִּתְפִלָּיו בְּכָל עֵת אֵינוֹ שׁוֹכְחָן. שָׁכַח וְיָצָא בָּהֶן לִרְשׁוּת הָרַבִּים וְנִזְכַּר שֶׁיֵּשׁ לוֹ תְּפִלִּין בְּרֹאשׁוֹ מְכַסֶּה אֶת רֹאשׁוֹ עַד שֶׁמַּגִּיעַ לְבֵיתוֹ אוֹ לְבֵית הַמִּדְרָשׁ:"],"Mishneh Torah, Sabbath 3":["מֻתָּר לְהַתְחִיל מְלָאכָה מֵעֶרֶב שַׁבָּת אַף עַל פִּי שֶׁהִיא נִגְמֶרֶת מֵאֵלֶיהָ בְּשַׁבָּת. שֶׁלֹּא נֶאֱסַר עָלֵינוּ לַעֲשׂוֹת מְלָאכָה אֶלָּא בְּעַצְמוֹ שֶׁל יוֹם. אֲבָל כְּשֶׁתֵּעָשֶׂה הַמְּלָאכָה מֵעַצְמָהּ בְּשַׁבָּת מֻתָּר לָנוּ לֵהָנוֹת בְּמַה שֶּׁנַּעֲשָׂה בְּשַׁבָּת מֵאֵלָיו:","כֵּיצַד. פּוֹתְקִין מַיִם לַגִּנָּה עֶרֶב שַׁבָּת עִם חֲשֵׁכָה וְהִיא מִתְמַלֵּאת וְהוֹלֶכֶת כָּל הַיּוֹם כֻּלּוֹ. וּמַנִּיחִין מֻגְמָר תַּחַת הַכֵּלִים וְהֵן מִתְגַּמְּרִין וְהוֹלְכִין כָּל הַשַּׁבָּת כֻּלָּהּ. וּמַנִּיחִים קִילוֹר עַל גַּב הָעַיִן וְאִסְפְּלָנִית עַל גַּבֵּי הַמַּכָּה וּמִתְרַפְּאִין וְהוֹלְכִין כָּל הַשַּׁבָּת כֻּלָּהּ. וְשׁוֹרִין דְּיוֹ וְסַמָּנִין עִם חֲשֵׁכָה וְהֵן שׁוֹרִין וְהוֹלְכִין כָּל הַשַּׁבָּת כֻּלָּהּ. וְנוֹתְנִין צֶמֶר לְיוּרָה וְאוּנִין שֶׁל פִּשְׁתָּן לַתַּנּוּר וְהֵם מִשְׁתַּנִּין וְהוֹלְכִין כָּל הַשַּׁבָּת כֻּלָּהּ. וּפוֹרְשִׂים מְצוּדוֹת לְחַיָּה וּלְעוֹפוֹת וּלְדָגִים עִם חֲשֵׁכָה וְהֵן נִצּוֹדִין וְהוֹלְכִין כָּל הַשַּׁבָּת כֻּלָּהּ. וְטוֹעֲנִין בְּקוֹרוֹת בֵּית הַבַּד וּבְעִגּוּלֵי הַגַּת עִם חֲשֵׁכָה וְהַמַּשְׁקִין זָבִין וְהוֹלְכִין כָּל הַשַּׁבָּת כֻּלָּהּ. וּמַדְלִיקִין אֶת הַנֵּר אוֹ אֶת הַמְּדוּרָה מִבָּעֶרֶב וְהִיא דּוֹלֶקֶת וְהוֹלֶכֶת כָּל הַשַּׁבָּת כֻּלָּהּ:","מַנִּיחִין קְדֵרָה עַל גַּבֵּי הָאֵשׁ אוֹ בָּשָׂר בַּתַּנּוּר אוֹ עַל גַּבֵּי גֶּחָלִים וְהֵן מִתְבַּשְּׁלִים וְהוֹלְכִין כָּל הַשַּׁבָּת וְאוֹכְלִין אוֹתָהּ בְּשַׁבָּת. וְיֵשׁ בְּדָבָר זֶה דְּבָרִים שֶׁהֵן אֲסוּרִין גְּזֵרָה שֶׁמָּא יַחְתֶּה בַּגֶּחָלִים בְּשַׁבָּת:","כֵּיצַד. תַּבְשִׁיל שֶׁלֹּא בָּשֵׁל כָּל צָרְכּוֹ וְחַמִּין שֶׁלֹּא הוּחַמּוּ כָּל צָרְכָּן אוֹ תַּבְשִׁיל שֶׁבָּשֵׁל כָּל צָרְכּוֹ וְכָל זְמַן שֶׁמִּצְטַמֵּק הוּא יָפֶה לוֹ אֵין מַשְהִין אוֹתוֹ עַל גַּבֵּי הָאֵשׁ בְּשַׁבָּת אַף עַל פִּי שֶׁהֻנַּח מִבְּעוֹד יוֹם גְּזֵרָה שֶׁמָּא יַחְתֶּה בַּגֶּחָלִים כְּדֵי לְהַשְׁלִים בִּשּׁוּלוֹ אוֹ כְּדֵי לְצַמְּקוֹ. לְפִיכָךְ אִם גָּרַף הָאֵשׁ אוֹ שֶׁכִּסָּה אֵשׁ הַכִּירָה בְּאֵפֶר אוֹ בִּנְעֹרֶת פִּשְׁתָּן הַדַּקָּה אוֹ שֶׁעָמְמוּ הַגֶּחָלִים שֶׁהֲרֵי הֵן כִּמְכֻסּוֹת בְּאֵפֶר אוֹ שֶׁהִסִּיקוּהָ בְּקַשׁ אוֹ בִּגְבָבָא אוֹ בִּגְלָלֵי בְּהֵמָה דַּקָּה שֶׁהֲרֵי אֵין שָׁם גֶּחָלִים בּוֹעֲרוֹת הֲרֵי זֶה מֻתָּר לִשְׁהוֹת עָלֶיהָ. שֶׁהֲרֵי הִסִּיחַ דַּעְתּוֹ מִזֶּה הַתַּבְשִׁיל וְאֵין גּוֹזְרִין שֶׁמָּא יַחְתֶּה בָּאֵשׁ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּכִירָה שֶׁהֶבְלָהּ מֻעָט. אֲבָל הַתַּנּוּר אַף עַל פִּי שֶׁגָּרַף הָאֵשׁ אוֹ כִּסָּה בְּאֵפֶר אוֹ שֶׁהִסִּיקוּהוּ בְּקַשׁ אוֹ בִגְבָבָא אֵין מַשְׁהִין בְּתוֹכוֹ וְלֹא עַל גַּבָּיו וְלֹא סוֹמְכִין לוֹ תַּבְשִׁיל שֶׁלֹּא בָּשֵׁל כָּל צָרְכּוֹ אוֹ שֶׁבָּשֵׁל כָּל צָרְכּוֹ וּמִצְטַמֵּק וְיָפֶה לוֹ. הוֹאִיל וְהֶבְלוֹ חַם בְּיוֹתֵר אֵינוֹ מַסִּיחַ דַּעְתּוֹ וְחוֹשְׁשִׁים שֶׁמָּא יַחְתֶּה בְּזוֹ הָאֵשׁ הַמְּעוּטָה אַף עַל פִּי שֶׁהוּא אֵשׁ קַשׁ וּגְבָבָא אוֹ מְכֻסָּה:","וְלָמָּה אָסְרוּ לִשְׁהוֹת בַּתַּנּוּר אַף עַל פִּי שֶׁגָּרוּף. מִפְּנֵי שֶׁהַגּוֹרֵף אֵינוֹ גּוֹרֵף אֶלָּא רֹב הָאֵשׁ וְעַצְמָהּ. וְאִי אֶפְשָׁר לִגְרֹף כָּל הָאֵשׁ עַד שֶׁלֹּא תִּשָּׁאֵר נִיצוֹץ אַחַת מִפְּנֵי שֶׁהֶבְלוֹ חַם שֶׁמָּא יַחְתֶּה כְּדֵי לְבַעֵר הַנִּיצוֹצוֹת הַנִּשְׁאָרוֹת בַּתַּנּוּר:","הַכֻּפָּח הֶבְלוֹ רַב מֵהֶבֶל הַכִּירָה וּמְעַט מֵהֶבֶל הַתַּנּוּר. לְפִיכָךְ אִם הִסִּיקוּהוּ בְּגֶפֶת אוֹ בְּעֵצִים הֲרֵי הוּא כְּתַנּוּר וְאֵין מַשְׁהִין בְּתוֹכוֹ וְלֹא עַל גַּבָּיו וְלֹא סוֹמְכִין לוֹ תַּבְשִׁיל שֶׁלֹּא בָּשֵׁל כָּל צָרְכּוֹ אוֹ מִצְטַמֵּק וְיָפֶה לוֹ אַף עַל פִּי שֶׁגָּרַף אוֹ כִּסָּה בְּאֵפֶר. וְאִם הִסִּיקוּהוּ בְּקַשׁ אוֹ בִּגְבָבָא הֲרֵי הוּא כְּכִירָה שֶׁהֻסְּקָה בְּקַשׁ וּגְבָבָא וּמַשְׁהִין עָלָיו. וּמֻתָּר לִסְמֹךְ לְכִירָה מִבָּעֶרֶב וְאַף עַל פִּי שֶׁאֵינָהּ גְּרוּפָה וּקְטוּמָה. וְאֵיזוֹ הִיא כִּירָה וְאֵי זוֹ כֻּפָּח כִּירָה מְקוֹם שְׁפִיתַת שְׁתֵּי קְדֵרוֹת כֻּפָּח מְקוֹם שְׁפִיתַת קְדֵרָה אַחַת:","תַּבְשִׁיל חַי שֶׁלֹּא בָּשֵׁל כְּלָל אוֹ שֶׁבָּשֵׁל כָּל צָרְכּוֹ וּמִצְטַמֵּק וְרַע לוֹ מֻתָּר לִשְׁהוֹתוֹ עַל גַּבֵּי הָאֵשׁ בֵּין בְּכִירָה וְכֻפָּח בֵּין בְּתַנּוּר. וְכֵן כָּל תַּבְשִׁיל שֶׁבָּשֵׁל וְלֹא בָּשֵׁל כָּל צָרְכּוֹ אוֹ בָּשֵׁל כָּל צָרְכּוֹ וּמִצְטַמֵּק וְיָפֶה לוֹ אִם הִשְׁלִיךְ לְתוֹכוֹ אֵבָר חַי סָמוּךְ לְבֵין הַשְּׁמָשׁוֹת נַעֲשָׂה הַכּל כְּתַבְשִׁיל חַי וּמֻתָּר לִשְׁהוֹתוֹ עַל הָאֵשׁ אַף עַל פִּי שֶׁלֹּא גָּרַף וְלֹא כִּסָּה. מִפְּנֵי שֶׁכְּבָר הִסִּיחַ דַּעְתּוֹ מִמֶּנּוּ וְאֵינוֹ בָּא לַחְתּוֹת בָּגֶחָלִים:","כָּל תַּבְשִׁיל שֶׁאָסוּר לִשְׁהוֹתוֹ אִם עָבַר וְשִׁהָה אוֹתוֹ אָסוּר לְאָכְלוֹ עַד מוֹצָאֵי שַׁבָּת וְיַמְתִּין בִּכְדֵי שֶׁיֵּעָשׂוּ. וְאִם שְׁכָחוֹ. אִם תַּבְשִׁיל שֶׁלֹּא בָּשֵׁל כָּל צָרְכּוֹ הוּא אָסוּר עַד מוֹצָאֵי שַׁבָּת. וְאִם תַּבְשִׁיל שֶׁבָּשֵׁל כָּל צָרְכּוֹ הוּא וּמִצְטַמֵּק וְיָפֶה לוֹ מֻתָּר לְאָכְלוֹ מִיָּד בְּשַׁבָּת:","כָּל שֶׁמֻּתָּר לִשְׁהוֹתוֹ עַל גַּבֵּי הָאֵשׁ כְּשֶׁנּוֹטְלִים אוֹתוֹ בְּשַׁבָּת אָסוּר לְהַחֲזִירוֹ לִמְקוֹמוֹ. וְאֵין מַחְזִירִין לְעוֹלָם אֶלָּא עַל גַּבֵּי כִּירָה גְּרוּפָה אוֹ מְכֻסָּה אוֹ בְּכִירָה וְכֻפָּח שֶׁהֻסְּקוּ בְּקַשׁ וּגְבָבָא. וְהוּא שֶׁלֹּא הִנִּיחַ הַקְּדֵרָה עַל גַּבֵּי הַקַּרְקַע אֲבָל מִשֶּׁהִנִּיחָה עַל גַּבֵּי קַרְקַע אֵין מַחְזִירִין אוֹתָהּ. וַאֲפִלּוּ עַל גַּבֵּי כִּירָה גְּרוּפָה אוֹ מְכֻסָּה. וְאֵין מַחְזִירִין לַתַּנּוּר וְלֹא לְכֻפָּח שֶׁהֻסְּקוּ בְּגֶפֶת אוֹ בְּעֵצִים אַף עַל פִּי שֶׁגָּרַף אוֹ כִּסָּה מִפְּנֵי שֶׁהֶבְלָן חַם בְּיוֹתֵר. וְכָל שֶׁאֵין מַחְזִירִין עָלָיו אֵין סוֹמְכִין לוֹ בְּשַׁבָּת:","אָסוּר לְהַכְנִיס מַגְרֵפָה לִקְדֵרָה בְּשַׁבָּת וְהִיא עַל הָאֵשׁ לְהוֹצִיא מִמֶּנָּה בְּשַׁבָּת מִפְּנֵי שֶׁמֵּגִיס בָּהּ וְזֶה מִצָּרְכֵי הַבִּשּׁוּל הוּא וְנִמְצָא כִּמְבַשֵּׁל בְּשַׁבָּת. וּמֻתָּר לְהַחֲזִיר מִכִּירָה לְכִירָה אֲפִלּוּ מִכִּירָה שֶׁהֶבְלָהּ מֻעָט לְכִירָה שֶׁהֶבְלָהּ מְרֻבֶּה אֲבָל לֹא מִכִּירָה לִטְמִינָה וְלֹא מִטְּמִינָה לְכִירָה:","לֹא יְמַלֵּא אָדָם קְדֵרָה עֲסַסִיוֹת וְתוּרְמוּסִין אוֹ חָבִית שֶׁל מַיִם וְיִתֵּן לְתוֹךְ הַתַּנּוּר עֶרֶב שַׁבָּת עִם חֲשֵׁכָה וְיַשְׁהֶה אוֹתָן. שֶׁאֵלּוּ וְכָל כַּיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁלֹּא בָּשְׁלוּ כָּל עִקָּר כְּתַבְשִׁיל שֶׁלֹּא בָּשֵׁל כָּל צָרְכּוֹ הֵן מִפְּנֵי שֶׁאֵינָן צְרִיכִים בִּשּׁוּל הַרְבֵּה וְדַעְתּוֹ עֲלֵיהֶן לְאָכְלָן לְאַלְתַּר. וּלְפִיכָךְ אָסוּר לִשְׁהוֹתָן בַּתַּנּוּר. וְאִם עָבַר וְשִׁהָה אֲסוּרִין עַד מוֹצָאֵי שַׁבָּת וְיַמְתִּין בִּכְדֵי שֶׁיֵּעָשׂוּ:","תַּנּוּר שֶׁנָּתַן לְתוֹכוֹ בָּשָׂר מִבְּעוֹד יוֹם וְשִׁהָה אוֹתוֹ בְּשַׁבָּת אִם בְּשַׂר גְּדִי הוּא וְכַיּוֹצֵא בּוֹ מֻתָּר. שֶׁאִם יַחְתֶּה בְּגֶחָלִים יִתְחָרֵךְ הַבָּשָׂר שֶׁאֵינוֹ צָרִיךְ אֶלָּא חֲמִימוּת הָאֵשׁ בִּלְבַד. וְאִם בְּשַׂר עֵז אוֹ בְּשַׂר שׁוֹר הוּא אָסוּר שֶׁמָּא יַחְתֶּה בְּגֶחָלִים לְבַשְּׁלוֹ. וְאִם טָח פִּי הַתַּנּוּר בְּטִיט מֻתָּר. שֶׁאִם בָּא לִפְתֹּחַ הַתַּנּוּר וְלַחְתּוֹת תִּכָּנֵס הָרוּחַ וְיִתְקַשֶּׁה הַבָּשָׂר וְיִפָּסֵד וְיִצְטַנֵּן הַתַּנּוּר וְיַפְסִיד הַבָּשָׂר:","וְכֵן כָּל דָּבָר שֶׁהָרוּחַ מַפְסֶדֶת אוֹתוֹ אֵין גּוֹזְרִין עָלָיו שֶׁמָּא יְגַלֵּהוּ וְיַחְתֶּה. וּמִפְּנֵי זֶה נוֹתְנִין אוּנִין שֶׁל פִּשְׁתָּן לְתוֹךְ הַתַּנּוּר עִם חֲשֵׁכָה שֶׁאִם גִלָּהוּ יִפָּסְדוּ:","נָתַן גְּדִי שָׁלֵם לְתוֹךְ הַתַּנּוּר הֲרֵי הוּא כִּבְשַׂר עֵז אוֹ כִּבְשַׂר שׁוֹר וְאָסוּר לִשְׁהוֹתוֹ שֶׁמָּא יַחְתֶּה בְּגֶחָלִים אֶלָּא אִם כֵּן טָח הַתַּנּוּר. וּמֻתָּר לְשַׁלְשֵׁל כֶּבֶשׂ הַפֶּסַח לַתַּנּוּר עִם חֲשֵׁכָה וְאַף עַל פִּי שֶׁאֵינוֹ טָח מִפְּנֵי שֶׁבְּנֵי חֲבוּרָה זְרִיזִים הֵן:","אֵין צוֹלִין בָּשָׂר וּבָצָל וּבֵיצָה עַל גַּבֵּי הָאֵשׁ אֶלָּא כְּדֵי שֶׁיִּצוֹלוּ מִבְּעוֹד יוֹם וְיִהְיוּ רְאוּיִין לַאֲכִילָה. וְאִם נִשְׁאֲרוּ אַחַר כֵּן עַל הָאֵשׁ בְּשַׁבָּת עַד שֶׁיִּצוֹלוּ הַרְבֵּה מֻתָּר מִפְּנֵי שֶׁהֵן כְּמִצְטַמֵּק וְרַע לוֹ שֶׁאִם יַחְתֶּה יַחֲרֹךְ אוֹתָן שֶׁעַל גּוּף הָאֵשׁ הֵם. וּמִפְּנֵי זֶה מַנִּיחִין מֻגְמָר תַּחַת הַכֵּלִים עִם חֲשֵׁכָה שֶׁאִם יַחְתֶּה בְּגֶחָלִים יִשָּׂרֵף הַמֻּגְמָר וִיעַשֵּׁן הַכֵּלִים:","הָא לָמַדְתָּ שֶׁכָּל דָּבָר שֶׁאָנוּ אוֹסְרִין בְּעִנְיָן זֶה אֵינוֹ אָסוּר מִשּׁוּם שֶׁהוּא נַעֲשָׂה בְּשַׁבָּת אֶלָּא גְּזֵרָה שֶׁמָּא יַחְתֶּה בְּגֶחָלִים. לְפִיכָךְ אֵין נוֹתְנִין צֶמֶר לְיוּרָה אֶלָּא אִם כֵּן הָיְתָה עֲקוּרָה מֵעַל הָאֵשׁ שֶׁמָּא יַחְתֶּה בְּגֶחָלִים. וְהוּא שֶׁיִּהְיֶה פִּיהָ טוּחַ בְּטִיט שֶׁמָּא יָגִיס בָּהּ מִשֶּׁחֲשֵׁכָה:","אֵין נוֹתְנִין אֶת הַפַּת בַּתַּנּוּר עִם חֲשֵׁכָה וְלֹא חֲרָרָה עַל גַּבֵּי הַגֶּחָלִים אֶלָּא כְּדֵי שֶׁיִּקָּרְמוּ פָּנֶיהָ שֶׁהֵם מֻדְבָּקִים בַּתַּנּוּר אוֹ בָּאֵשׁ. וְאִם נִשְׁאֲרוּ אַחֲרֵי כֵן עַד שֶׁיִּגְמֹר אֲפִיָּתָן מֻתָּר שֶׁאִם יַחְתֶּה יַפְסִיד אוֹתָן. וְאִם נָתַן סָמוּךְ לַחֲשֵׁכָה וְחָשְׁכָה וַעֲדַיִן לֹא קָרְמוּ פָּנֶיהָ. אִם בְּמֵזִיד אָסוּר לֶאֱכל מֵהֶן עַד מוֹצָאֵי שַׁבָּת וְיַמְתִּין בִּכְדֵי שֶׁיֵּעָשׂוּ. וְאִם בְּשׁוֹגֵג מֻתָּר לוֹ לִרְדּוֹת מִמֶּנָּה מְזוֹן שָׁלֹשׁ סְעֻדּוֹת שֶׁל שַׁבָּת. וּכְשֶׁהוּא רוֹדֶה לֹא יִרְדֶּה בְּמִרְדֶּה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל אֶלָּא בְּסַכִּין וְכַיּוֹצֵא בָּהּ:","עוֹשֶׂה אָדָם מְדוּרָה מִכָּל דָּבָר שֶׁיִּרְצֶה בֵּין עַל גַּבֵּי קַרְקַע בֵּין עַל גַּבֵּי מְנוֹרָה וּמַדְלִיקָהּ מִבְּעוֹד יוֹם וּמִשְׁתַּמֵּשׁ לְאוֹרָהּ אוֹ מִתְחַמֵּם כְּנֶגְדָּהּ בְּשַׁבָּת. וְצָרִיךְ שֶׁיַּדְלִיק רֹב הַמְּדוּרָה קֹדֶם חֲשֵׁכָה עַד שֶׁתְּהֵא שַׁלְהֶבֶת עוֹלָה מֵאֵלֶיהָ קֹדֶם הַשַּׁבָּת. וְאִם לֹא הִדְלִיק רֻבָּהּ אָסוּר לֵהָנוֹת בָּהּ בְּשַׁבָּת גְּזֵרָה שֶׁמָּא יַחְתֶּה בָּהּ וְיָנִיד הָעֵצִים כְּדֵי שֶׁתַּעֲלֶה הַשַּׁלְהֶבֶת. וְאִם הִדְלִיק עֵץ יְחִידִי צָרִיךְ לְהַדְלִיק רֹב עָבְיוֹ וְרֹב הֶקֵּפוֹ מִבְּעוֹד יוֹם:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּגְבוּלִין אֲבָל בַּמִּקְדָּשׁ מַאֲחִיזִין אֶת הָאוּר בָּעֵצִים בִּמְדוּרַת בֵּית הַמּוֹקֵד עִם חֲשֵׁכָה וְאֵין חוֹשְׁשִׁין שֶׁמָּא יַחְתֶּה בְּגֶחָלִים שֶׁהַכֹּהֲנִים זְרִיזִין הֵן:","הָיְתָה מְדוּרָה שֶׁל קָנִים אוֹ שֶׁל גַּרְעִינִין אֵינוֹ צָרִיךְ לְהַדְלִיק הָרֹב אֶלָּא כֵּיוָן שֶׁהִתְחִיל בָּהֶן הָאֵשׁ קֹדֶם הַשַּׁבָּת מֻתָּר לְהִשְׁתַּמֵּשׁ בָּהּ. מִפְּנֵי שֶׁהָאֵשׁ נִתְלֵית בָּהֶן בִּמְהֵרָה וְאֵינוֹ צָרִיךְ לַחְתּוֹת. לְפִיכָךְ אִם אָגַד הַקָּנִים אוֹ הִנִּיחַ הַגַּרְעִינִין בְּחוֹתָלוֹת הֲרֵי הֵן כְּעֵצִים וְצָרִיךְ שֶׁתַּעֲלֶה בָּהֶן שַׁלְהֶבֶת מֵאֵלֶיהָ קֹדֶם הַשַּׁבָּת:","מְדוּרָה שֶׁל זֶפֶת אוֹ שֶׁל גָּפְרִית אוֹ שֶׁל רְבָב אוֹ שֶׁל קִירָה אוֹ שֶׁל קַשׁ אוֹ שֶׁל גְּבָבָא אֵינוֹ צָרִיךְ לְהַדְלִיק רֻבָּהּ קֹדֶם הַשַּׁבָּת מִפְּנֵי שֶׁהָאֵשׁ מַדְלֶקֶת אוֹתָם בִּמְהֵרָה:"],"Mishneh Torah, Sabbatical Year and the Jubilee 13":["שֵׁבֶט לֵוִי אַף עַל פִּי שֶׁאֵין לָהֶם חֵלֶק בָּאָרֶץ כְּבָר נִצְטַוּוּ יִשְׂרָאֵל לִתֵּן לָהֶם עָרִים לָשֶׁבֶת וּמִגְרְשֵׁיהֶם. וְהֶעָרִים הֵם שֵׁשׁ עָרֵי מִקְלָט וַעֲלֵיהֶן שְׁתַּיִם וְאַרְבָּעִים עִיר. וּכְשֶׁמּוֹסִיפִין עָרֵי מִקְלָט אֲחֵרוֹת בִּימֵי הַמָּשִׁיחַ הַכּל לַלְוִיִּם:","מִגְרְשֵׁי הֶעָרִים כְּבָר נִתְפָּרְשׁוּ בַּתּוֹרָה שֶׁהֵם שְׁלֹשֶׁת אֲלָפִים אַמָּה לְכָל רוּחַ מִקִּיר הָעִיר וְחוּצָה שֶׁנֶּאֱמַר (במדבר לה ד) \"מִקִּיר הָעִיר וָחוּצָה אֶלֶף אַמָּה סָבִיב\". וּלְהַלָּן הוּא אוֹמֵר (במדבר לה ה) \"וּמַדֹּתֶם מִחוּץ לָעִיר אֶת פְּאַת קֵדְמָה אַלְפַּיִם בָּאַמָּה\" וְגוֹ'. אֶלֶף הָרִאשׁוֹנִים מִגְרַשׁ וְאַלְפַּיִם שֶׁמּוֹדְדִין חוּץ לַמִּגְרָשׁ לְשָׂדוֹת וּכְרָמִים:","וְנוֹתְנִין לְכָל עִיר בֵּית הַקְּבָרוֹת חוּץ לִתְחוּם זֶה. שֶׁאֵין קוֹבְרִין מֵתֵיהֶם לִתְחוּם עָרֵיהֶם שֶׁנֶּאֱמַר (במדבר לה ג) \"וּמִגְרְשֵׁיהֶם יִהְיוּ לִבְהֶמְתָּם וְלִרְכֻשָׁם וּלְכל חַיָּתָם\" לְחַיִּים נִתְּנוּ וְלֹא לִקְבוּרָה:","אֵין עוֹשִׂין בְּעָרֵי הַלְוִיִּם עִיר מִגְרָשׁ וְלֹא מִגְרָשׁ עִיר וְלֹא מִגְרָשׁ שָׂדֶה וְלֹא שָׂדֶה מִגְרָשׁ שֶׁנֶּאֱמַר (ויקרא כה לד) \"וּשְׂדֵה מִגְרַשׁ עָרֵיהֶם לֹא יִמָּכֵר\":","ומִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר (ויקרא כה לד) \"לֹא יִמָּכֵר\" לֹא יְשׁוּנֶה אֶלָּא הַשָּׂדֶה וְהַמִּגְרָשׁ וְהָעִיר כָּל אֶחָד מִשְּׁלָשְׁתָּן כְּמוֹת שֶׁהוּא לְעוֹלָם. וְכֵן בִּשְׁאָר עָרֵי יִשְׂרָאֵל:","לֹא יִסְתֹּר אָדָם אֶת בֵּיתוֹ לַעֲשׂוֹתוֹ גִּנָּה וְלֹא יִטַּע חֻרְבָּתוֹ גִּנָּה שֶׁלֹּא יַחֲרִיבוּ אֶרֶץ יִשְׂרָאֵל:","כֹּהֲנִים וּלְוִיִּם שֶׁמָּכְרוּ שָׂדֶה מִשְּׂדֵה עָרֵיהֶם אוֹ בַּיִת מִבָּתֵּי עָרֵי חוֹמָה שֶׁלָּהֶן אֵין גּוֹאֲלִין כַּסֵּדֶר הַזֶּה. אֶלָּא מוֹכְרִין הַשָּׂדוֹת וַאֲפִלּוּ סָמוּךְ לַיּוֹבֵל וְגוֹאֲלִין מִיָּד. וְאִם הִקְדִּישׁוּ שָׂדֶה גּוֹאֲלִים מִיַּד הַהֶקְדֵּשׁ לְאַחַר הַיּוֹבֵל. וְגוֹאֲלִים בָּתֵּי עָרֵי חוֹמָה כָּל זְמַן שֶׁיִּרְצוּ אֲפִלּוּ אַחַר כַּמָּה שָׁנִים שֶׁנֶּאֱמַר (ויקרא כה לב) \"גְּאֻלַּת עוֹלָם תִּהְיֶה לַלְוִיִּם\":","יִשְׂרָאֵל שֶׁיָּרַשׁ אֶת אֲבִי אִמּוֹ לֵוִי הֲרֵי זֶה גּוֹאֵל כִּלְוִיִּם אַף עַל פִּי שֶׁאֵינוֹ לֵוִי הוֹאִיל וְהֶעָרִים אוֹ הַשָּׂדוֹת שֶׁל לְוִיִּם גּוֹאֵל לְעוֹלָם. שֶׁדִּין זֶה תָּלוּי בִּמְקוֹמוֹת אֵלּוּ וְלֹא בַּבְּעָלִים:","וְלֵוִי שֶׁיָּרַשׁ אֶת אֲבִי אִמּוֹ יִשְׂרָאֵל גּוֹאֵל כְּיִשְׂרָאֵל וְלֹא כִּלְוִיִּם שֶׁלֹּא נֶאֱמַר (ויקרא כה לב) \"גְּאֻלַּת עוֹלָם תִּהְיֶה לַלְוִיִּם\" אֶלָּא בְּעָרֵי הַלְוִיִּם:","כָּל שֵׁבֶט לֵוִי מֻזְהָרִין שֶׁלֹּא יִנְחֲלוּ בְּאֶרֶץ כְּנַעַן. וְכֵן הֵן מֻזְהָרִין שֶׁלֹּא יִטְּלוּ חֵלֶק בַּבִּזָּהּ בְּשָׁעָה שֶׁכּוֹבְשִׁין אֶת הֶעָרִים שֶׁנֶּאֱמַר (דברים יח א) \"לֹא יִהְיֶה לַכֹּהֲנִים הַלְוִיִּם כָּל שֵׁבֶט לֵוִי חֵלֶק וְנַחֲלָה עִם יִשְׂרָאֵל\". חֵלֶק בַּבִּזָּה וְנַחֲלָה בָּאָרֶץ. וְכֵן הוּא אוֹמֵר (במדבר יח כ) \"בְּאַרְצָם לֹא תִנְחָל וְחֵלֶק לֹא יִהְיֶה לְךָ בְּתוֹכָם\" בַּבִּזָּה. וּבֶן לֵוִי אוֹ כֹּהֵן שֶׁנָּטַל חֵלֶק בַּבִּזָּה לוֹקֶה. וְאִם נָטַל נַחֲלָה בָּאָרֶץ מַעֲבִירִין אוֹתָהּ מִמֶּנּוּ:","יֵרָאֶה לִי שֶׁאֵין הַדְּבָרִים אֲמוּרִים אֶלָּא בָּאָרֶץ שֶׁנִּכְרְתָה עָלֶיהָ בְּרִית לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב וִירָשׁוּהָ בְּנֵיהֶם וְנִתְחַלְּקָה לָהֶם. אֲבָל שְׁאָר כָּל הָאֲרָצוֹת שֶׁכּוֹבֵשׁ מֶלֶךְ מִמַּלְכֵי יִשְׂרָאֵל הֲרֵי הַכֹּהֲנִים וְהַלְוִיִּם בְּאוֹתָן הָאֲרָצוֹת וּבְבִזָּתָן כְּכָל יִשְׂרָאֵל:","וְלָמָּה לֹא זָכָה לֵוִי בְּנַחֲלַת אֶרֶץ יִשְׂרָאֵל וּבְבִזָּתָהּ עִם אֶחָיו מִפְּנֵי שֶׁהֻבְדַּל לַעֲבֹד אֶת ה' לְשָׁרְתוֹ וּלְהוֹרוֹת דְּרָכָיו הַיְשָׁרִים וּמִשְׁפָּטָיו הַצַּדִּיקִים לָרַבִּים שֶׁנֶּאֱמַר (דברים לג י) \"יוֹרוּ מִשְׁפָּטֶיךָ לְיַעֲקֹב וְתוֹרָתְךָ לְיִשְׂרָאֵל\". לְפִיכָךְ הֻבְדְּלוּ מִדַּרְכֵי הָעוֹלָם לֹא עוֹרְכִין מִלְחָמָה כִּשְׁאָר יִשְׂרָאֵל וְלֹא נוֹחֲלִין וְלֹא זוֹכִין לְעַצְמָן בְּכֹחַ גּוּפָן. אֶלָּא הֵם חֵיל הַשֵּׁם שֶׁנֶּאֱמַר (דברים לג יא) \"בָּרֵךְ ה' חֵילוֹ\". וְהוּא בָּרוּךְ הוּא זוֹכֶה לָהֶם שֶׁנֶּאֱמַר (במדבר יח כ) \"אֲנִי חֶלְקְךָ וְנַחֲלָתְךָ\":","וְלֹא שֵׁבֶט לֵוִי בִּלְבַד אֶלָּא כָּל אִישׁ וְאִישׁ מִכָּל בָּאֵי הָעוֹלָם אֲשֶׁר נָדְבָה רוּחוֹ אוֹתוֹ וֶהֱבִינוֹ מַדָּעוֹ לְהִבָּדֵל לַעֲמֹד לִפְנֵי ה' לְשָׁרְתוֹ וּלְעָבְדוֹ לְדֵעָה אֶת ה' וְהָלַךְ יָשָׁר כְּמוֹ שֶׁעֲשָׂהוּ הָאֱלֹהִים וּפָרַק מֵעַל צַוָּארוֹ עֹל הַחֶשְׁבּוֹנוֹת הָרַבִּים אֲשֶׁר בִּקְּשׁוּ בְּנֵי הָאָדָם הֲרֵי זֶה נִתְקַדֵּשׁ קֹדֶשׁ קָדָשִׁים וְיִהְיֶה ה' חֶלְקוֹ וְנַחֲלָתוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים וְיִזְכֶּה לוֹ בָּעוֹלָם הַזֶּה דָּבָר הַמַּסְפִּיק לוֹ כְּמוֹ שֶׁזָּכָה לַכֹּהֲנִים לַלְוִיִּם. הֲרֵי דָּוִד עָלָיו הַשָּׁלוֹם אוֹמֵר (תהילים טז ה) \"ה' מְנָת חֶלְקִי וְכוֹסִי אַתָּה תּוֹמִיךְ גּוֹרָלִי\":"],"Mishneh Torah, Sacrifices Rendered Unfit 12":["שְׁתֵי הַלֶּחֶם וְלֶחֶם הַפָּנִים וְעֹמֶר הַתְּנוּפָה שֶׁהוֹסִיף בְּמִדָּתָן אוֹ חִסֵּר כָּל שֶׁהוּא פְּסוּלוֹת:","חַלּוֹת תּוֹדָה וּרְקִיקֵי נָזִיר שֶׁחָסְרוּ עַד שֶׁלֹּא נִזְרַק דַּם הַזֶּבַח פְּסוּלִין. מִשֶּׁנִּזְרַק דַּם הַזֶּבַח כְּשֵׁרִין:","וְכֵן שְׁתֵּי הַלֶּחֶם שֶׁחָסְרוּ עַד שֶׁלֹּא נִזְרַק דָּמָן שֶׁל כְּבָשִׂים פְּסוּלִין. מִשֶּׁנִּזְרַק דָּמָן כְּשֵׁרִים:","וְכֵן שְׁנֵי סְדָרִים שֶׁחָסְרוּ עַד שֶׁלֹּא הֻקְטְרוּ הַבְּזִיכִין פְּסוּלִין. מִשֶּׁהֻקְטְרוּ כְּשֵׁרִים:","אֲבָל הַנְּסָכִים שֶׁחָסְרוּ בֵּין מִשֶּׁקָּרַב הַזֶּבַח בֵּין עַד שֶׁלֹּא קָרַב כְּשֵׁרִים. וְיָבִיא נְסָכִים אֲחֵרִים לְמַלְּאוֹתָן:","נְסָכִים שֶׁקָּדְשׁוּ בִּכְלֵי שָׁרֵת וְנִפְסַל הַזֶּבַח. אִם נִפְסַל בִּשְׁחִיטָה לֹא קָדְשׁוּ הַנְּסָכִים לִקָּרֵב. נִפְסַל מִקַּבָּלָה וְאֵילָךְ קָדְשׁוּ הַנְּסָכִים לִקָּרֵב. שֶׁאֵין הַנְּסָכִים מִתְקַדְּשִׁים לִקָּרֵב אֶלָּא בִּשְׁחִיטַת הַזֶּבַח. וּמַה יַּעֲשֶׂה בָּהֶן. אִם הָיָה שָׁם זֶבַח אַחַר זָבוּחַ בְּאוֹתָהּ שָׁעָה יִקָּרְבוּ עִמּוֹ. וְאִם לֹא הָיָה שָׁם זֶבַח אַחַר זָבוּחַ בְּאוֹתָהּ שָׁעָה נַעֲשׂוּ כְּמִי שֶׁנִּפְסְלוּ בְּלִינָה וְיִשָּׂרְפוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּקָרְבַּן צִבּוּר מִפְּנֵי שֶׁלֵּב בֵּית דִּין מַתְנֶה עֲלֵיהֶן. אֲבָל בְּקָרְבַּן יָחִיד הֲרֵי אֵלּוּ לֹא יִקָּרְבוּ עִם זֶבַח אַחֵר וְאַף עַל פִּי שֶׁהוּא זָבוּחַ בְּאוֹתָהּ שָׁעָה אֶלָּא מַנִּיחָן עַד שֶׁיִּפָּסְלוּ בְּלִינָה וְיִשָּׂרְפוּ:","וְכָל הַזְּבָחִים שֶׁנִּזְבְּחוּ שֶׁלֹּא לִשְׁמָן יִקָּרְבוּ נִסְכֵּיהֶם:","וְלַד תּוֹדָה וּתְמוּרָתָהּ. וְהַמַּפְרִישׁ תּוֹדָתוֹ וְאָבְדָה וְהִפְרִישׁ אַחֶרֶת תַּחְתֶּיהָ. אִם הֱבִיאָן לְאַחַר שֶׁכִּפֵּר בְּתוֹדָה רִאשׁוֹנָה אֵינָן טְעוּנִין לֶחֶם. וְאִם עֲדַיִן לֹא כִּפֵּר בָּהּ וַהֲרֵי הִיא וַחֲלִיפָתָהּ אוֹ הִיא וּוְלָדָהּ אוֹ הִיא וּתְמוּרָתָהּ. עוֹמֶדֶת. הֲרֵי שְׁנֵיהֶן צְרִיכִין לֶחֶם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּנוֹדֵר תּוֹדָה. אֲבָל תּוֹדַת נְדָבָה חֲלִיפָתָהּ וּתְמוּרָתָהּ טְעוּנִין לֶחֶם. וּוְלָדָהּ אֵינוֹ טָעוּן לֶחֶם. בֵּין לִפְנֵי כַּפָּרָה בֵּין לְאַחַר כַּפָּרָה:","הִפְרִישׁ תּוֹדָתוֹ וְאָבְדָה. וְהִפְרִישׁ אַחֶרֶת תַּחְתֶּיהָ וְאָבְדָה. וְהִפְרִישׁ אַחֶרֶת תַּחְתֶּיהָ וְנִמְצְאוּ הָרִאשׁוֹנוֹת וַהֲרֵי שְׁלָשְׁתָּן עוֹמְדוֹת. נִתְכַּפֵּר בָּרִאשׁוֹנָה. שְׁנִיָּה אֵינָהּ טְעוּנָה לֶחֶם. שְׁלִישִׁית טְעוּנָה לֶחֶם. נִתְכַּפֵּר בַּשְּׁלִישִׁית. שְׁנִיָּה אֵינָהּ טְעוּנָה לֶחֶם. רִאשׁוֹנָה טְעוּנָה לֶחֶם. נִתְכַּפֵּר בָּאֶמְצָעִית שְׁתֵּיהֶן אֵינָן טְעוּנוֹת לֶחֶם:","הַמַּפְרִישׁ מָעוֹת לְתוֹדָתוֹ וְאָבְדוּ וְהִפְרִישׁ מָעוֹת אֲחֵרוֹת תַּחְתֵּיהֶן וְלֹא הִסְפִּיק לִקַּח בָּהֶן תּוֹדָה עַד שֶׁנִּמְצְאוּ מָעוֹת הָרִאשׁוֹנוֹת. יָבִיא מֵאֵלּוּ וּמֵאֵלּוּ תּוֹדָה בְּלַחְמָהּ. וְהַשְּׁאָר יָבִיא בָּהֶן תּוֹדָה. וְאֵינָהּ טְעוּנָה לֶחֶם אֲבָל טְעוּנָה נְסָכִים. וְכֵן הַמַּפְרִישׁ תּוֹדָתוֹ וְאָבְדָה וְהִפְרִישׁ מָעוֹת תַּחְתֶּיהָ וְאַחַר כָּךְ נִמְצֵאת. יָבִיא בַּמָּעוֹת תּוֹדָה בְּלֹא לֶחֶם. וְכֵן הַמַּפְרִישׁ מָעוֹת לְתוֹדָתוֹ וְאָבְדוּ וְהִפְרִישׁ תּוֹדָה תַּחְתֵּיהֶן וְאַחַר כָּךְ נִמְצְאוּ הַמָּעוֹת. יָבִיא מִן הַמָּעוֹת תּוֹדָה וְלַחְמָהּ. וְזוֹ הַתּוֹדָה הָאַחֲרוֹנָה תִּקָּרֵב בְּלֹא לֶחֶם:","הָאוֹמֵר הֲרֵי זוֹ תּוֹדָה וַהֲרֵי זֶה לַחְמָהּ. אָבַד הַלֶּחֶם מֵבִיא לֶחֶם אַחֵר. אָבְדָה הַתּוֹדָה אֵינוֹ מֵבִיא תּוֹדָה אַחֶרֶת. מִפְּנֵי שֶׁהַלֶּחֶם בָּא בִּגְלַל הַתּוֹדָה וְאֵין הַתּוֹדָה בָּאָה בִּגְלַל הַלֶּחֶם:","הִפְרִישׁ מָעוֹת לְתוֹדָתוֹ וְנוֹתְרוּ מֵבִיא בָּהֶן לֶחֶם. הִפְרִישׁ לַלֶּחֶם וְהוֹתִיר אֵינוֹ מֵבִיא בָּהֶן תּוֹדָה:","הָאוֹמֵר הֲרֵי זוֹ תּוֹדָה וְנִתְעָרְבָה בִּתְמוּרָתָהּ וּמֵתָה אַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ הִיא. הֲרֵי זוֹ הַנִּשְׁאֶרֶת אֵין לָהּ תַּקָּנָה שֶׁאִם יָבִיא עִמָּהּ לֶחֶם שֶׁמָּא הַתְּמוּרָה הִיא. וְאִם הֱבִיאָהּ בְּלֹא לֶחֶם שֶׁמָּא הַתּוֹדָה הִיא. לְפִיכָךְ לֹא תִּקָּרֵב זוֹ לְעוֹלָה אֶלָּא תִּרְעֶה עַד שֶׁיִּפּל בָּהּ מוּם:","תּוֹדָה שֶׁנִּפְרְסָה חַלָּה מֵחַלּוֹתֶיהָ כֻּלָּן פְּסוּלוֹת. יָצָאת הַחַלָּה אוֹ נִטְמְאָה. שְׁאָר הַחַלּוֹת כְּשֵׁרוֹת. נִפְרַס לַחְמָהּ אוֹ נִטְמָא אוֹ יָצָא עַד שֶׁלֹּא נִשְׁחֲטָה הַתּוֹדָה. מֵבִיא לֶחֶם אַחֵר וְשׁוֹחֵט. וְאִם אַחַר שֶׁנִּשְׁחַט נִפְרַס אוֹ נִטְמָא אוֹ יָצָא. הַדָּם יִזָּרֵק וְהַבָּשָׂר יֵאָכֵל. וְהַלֶּחֶם כֻּלּוֹ פָּסוּל וִידֵי נִדְרוֹ לֹא יָצָא. נִזְרַק הַדָּם וְאַחַר כָּךְ נִפְרַס מִקְצָת הַלֶּחֶם אוֹ נִטְמָא אוֹ יָצָא. תּוֹרֵם מִן הַשָּׁלֵם עַל הַפָּרוּס וּמִן הַטָּהוֹר עַל הַטָּמֵא וּמִמַּה שֶּׁבִּפְנִים עַל שֶׁבַּחוּץ:","תּוֹדָה שֶׁנִּשְׁחֲטָה עַל שְׁמוֹנִים חַלּוֹת. לֹא קָדְשׁוּ אַרְבָּעִים מִתּוֹךְ שְׁמוֹנִים. וְאִם אָמַר יִקָּדְשׁוּ אַרְבָּעִים מִתּוֹךְ שְׁמוֹנִים מוֹשֵׁךְ אַרְבָּעִים מִתּוֹךְ שְׁמוֹנִים וּמֵרִים מֵהֶם אַחַת מִכָּל קָרְבָּן. וְהָאַרְבָּעִים הַשְּׁנִיּוֹת יִפָּדוּ וְיֵצְאוּ לְחֻלִּין:","הַשּׁוֹחֵט אֶת הַתּוֹדָה וְהָיָה לַחְמָהּ חוּץ לְחוֹמַת בֵּית פַּגִי לֹא קָדַשׁ הַלֶּחֶם. אֲבָל אִם הָיָה חוּץ לָעֲזָרָה קָדַשׁ הַלֶּחֶם אַף עַל פִּי שֶׁאֵינוֹ לְפָנִים:","שְׁחָטָהּ עַד שֶׁלֹּא קָרְמוּ פְּנֵי הַלֶּחֶם בַּתַּנּוּר וַאֲפִלּוּ קָרְמוּ כֻּלָּן חוּץ מֵאַחַת מֵהֶן. לֹא קָדַשׁ הַלֶּחֶם:","שְׁחָטָהּ וְנִפְסְלָה בִּשְׁחִיטָתָהּ בְּמַחְשֶׁבֶת זְמַן אוֹ בְּמַחְשֶׁבֶת מָקוֹם קָדַשׁ הַלֶּחֶם. נִמְצֵאת בַּעֲלַת מוּם אוֹ טְרֵפָה אוֹ שֶׁשְּׁחָטָהּ שֶׁלֹּא לִשְׁמָהּ לֹא קָדַשׁ הַלֶּחֶם. וְכֵן הַדִּין בְּאֵיל נָזִיר עִם הַלֶּחֶם שֶׁלּוֹ:"],"Mishneh Torah, Sacrifices Rendered Unfit 6":["כָּל הַזְּבָחִים שֶׁנִּתְעָרֵב בָּהֶן אַחַת מֵחַטָּאוֹת הַמֵּתוֹת. אוֹ שׁוֹר הַנִּסְקָל. אֲפִלּוּ אֶחָד בְּרִבּוֹא כֻּלָּן יָמוּתוּ לְפִי שֶׁבַּעֲלֵי חַיִּים חֲשׁוּבִין הֵן וְאֵינָם בְּטֵלִין. וְאִם הִקְרִיב הֻרְצָה שֶׁאֵין בַּעֲלֵי חַיִּין נִדְחִין:","נִתְעָרֵב בָּהֶן אֶחָד מֵאִסּוּרֵי הַמִּזְבֵּחַ. יִרְעוּ כֻּלָּם עַד שֶׁיִּפּל בָּהֶן מוּם וְיִמָּכְרוּ וְיָבִיא בִּדְמֵי הַיָּפֶה שֶׁבָּהֶן מֵאוֹתוֹ הַמִּין שֶׁל קָדָשִׁים שֶׁנִּתְעָרֵב:","נִתְעָרְבוּ קָדָשִׁים בְּחֻלִּין תְּמִימִים יִמָּכְרוּ הַחֻלִּין שֶׁבַּתַּעֲרֹבֶת לְצָרְכֵי אוֹתוֹ הַמִּין וְיִקָּרְבוּ כֻּלָּן. כֵּיצַד. אַרְבַּע בְּהֵמוֹת שְׁלָמִים שֶׁנִּתְעָרְבוּ בְּאַרְבַּע בְּהֵמוֹת חֻלִּין תְּמִימִים. יִמָּכְרוּ הָאַרְבַּע שֶׁל חֻלִּין לְמִי שֶׁהוּא צָרִיךְ לְהָבִיא שְׁלָמִים וְיִקָּרְבוּ הַכּל שְׁלָמִים. וְכֵן בְּעוֹלָה אוֹ בְּאָשָׁם. וְהַדָּמִים חֻלִּין לְכָל דָּבָר שֶׁהֲרֵי דְּמֵי חֻלִּין הֵן:","נִתְעָרֵב שׁוֹר הֶקְדֵּשׁ בִּשְׁוָרִים שֶׁל חֹל. גָּדוֹל שֶׁבְּכֻלָּן הֶקְדֵּשׁ וְיִמָּכְרוּ הַשְּׁאָר לְצָרְכֵי אוֹתוֹ הַמִּין. נִתְעָרְבוּ קָדָשִׁים בְּקָדָשִׁים מִין בְּמִינוֹ. זֶה יִקְרַב לְשֵׁם בְּעָלָיו וְזֶה יִקְרַב לְשֵׁם בְּעָלָיו אַף עַל פִּי שֶׁאֵין כָּל אֶחָד מֵהֶן מַכִּיר קָרְבָּנוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּקָרְבְּנוֹת נָשִׁים שֶׁאֵין בָּהֶם סְמִיכָה. אֲבָל קָרְבְּנוֹת אֲנָשִׁים הוֹאִיל וְכָל אֶחָד צָרִיךְ לִסְמֹךְ עַל רֹאשׁ קָרְבָּנוֹ הֲרֵי אֵלּוּ לֹא יִקָּרְבוּ עַד שֶׁיִּתֵּן הָאֶחָד חֶלְקוֹ לַחֲבֵרוֹ. אוֹ עַד שֶׁיִּפּל מוּם בַּכּל וְיִמָּכְרוּ וְיָבִיאוּ כָּל אֶחָד בִּדְמֵי הַיָּפֶה שֶׁבָּהֶן מֵאוֹתוֹ הַמִּין:","נִתְעָרְבוּ מִין בְּשֶׁאֵינוֹ מִינוֹ כְּגוֹן עוֹלָה בִּשְׁלָמִים. לֹא יִקָּרְבוּ אֲפִלּוּ כַּחֲמוּרָה שֶׁבָּהֶן. שֶׁאֵין מְבִיאִין קָדָשִׁים לְבֵית הַפָּסוּל:","וּכְשֵׁם שֶׁאֵין מְמַעֲטִין בִּזְמַן אֲכִילָתָן כָּךְ אֵין מְמַעֲטִין בְּאוֹכְלֵיהֶן וְלֹא בִּמְקוֹם אֲכִילָתָן. אֶלָּא כֵּיצַד יַעֲשֶׂה. יִרְעוּ הַכּל עַד שֶׁיִּפּל בָּהֶם מוּם וְיִמָּכֵר כָּל אֶחָד מֵהֶן לְבַדּוֹ וְיָבִיא בִּדְמֵי הַיָּפֶה שֶׁבָּהֶן מִמִּין זֶה וּבִדְמֵי הַיָּפֶה שֶׁבָּהֵן מִמִּין הָאַחֵר וְיַפְסִיד הַמּוֹתָר מִבֵּיתוֹ:","אַף עַל פִּי שֶׁכְּבָר הִקְרִיב עוֹלָה שֶׁחַיָּב בָּהּ אוֹ שְׁלָמִים שֶׁהָיָה חַיָּב לְהַקְרִיבָן. הֲרֵי זֶה מַקְרִיב מִדְּמֵי הַתַּעֲרֹבֶת עוֹלָה אַחֶרֶת וּשְׁלָמִים אֲחֵרִים:","חַטָּאת שֶׁנִּתְעָרְבָה בִּשְׁלָמִים יִרְעוּ הַכּל עַד שֶׁיִּפּל בָּהֶן מוּם וְיָבִיא בִּדְמֵי הַיָּפֶה שֶׁבָּהֶן שְׁלָמִים וּבִדְמֵי הַיָּפֶה שֶׁבָּהֶן חַטָּאת. וְאִם קָדַם וְהִקְרִיב חַטָּאת אַחֶרֶת עַל חַטָּאת שֶׁהִפְרִישָׁהּ לוֹ כֻּלָּן יָמוּתוּ:","וְכֵן אִם נִתְעָרְבוּ מְעוֹת חַטָּאת בִּמְעוֹת אָשָׁם. לוֹקֵחַ שְׁתֵּי בְּהֵמוֹת וּמְחַלֵּל דְּמֵי חַטָּאת בְּכָל מָקוֹם שֶׁהוּא עַל חַטָּאת וּדְמֵי אָשָׁם עַל אָשָׁם. וְאִם כְּבָר קָרְבָה חַטָּאתוֹ יוֹלִיךְ כָּל הַמָּעוֹת לְיָם הַמֶּלַח. וְאִם כְּבָר קָרְבָה אֲשָׁמוֹ יִפְּלוּ הַכּל לִנְדָבָה:","תּוֹדָה שֶׁנִּתְעָרְבָה בִּתְמוּרָתָהּ שְׁתֵּיהֶן תִּקָּרַבְנָה וְיָנִיף הַלֶּחֶם עִמָּהֶן. וְכָךְ אִם נִתְעָרְבָה תּוֹדָה בִּשְׁאָר זְבָחִים אַף עַל פִּי שֶׁקָּרְבָה תּוֹדָתוֹ יִרְעוּ הַכּל עַד שֶׁיִּפּל בָּהֶן מוּם וְיָבִיא בִּדְמֵי הַיָּפֶה תּוֹדָה אַחֶרֶת. וּבִדְמֵי הַיָּפֶה זֶבַח אַחֵר:","נִתְעָרְבָה בְּאֵיל נָזִיר שְׁתֵּיהֶם תִּקָּרַבְנָה וְיָנִיף הַלֶּחֶם עִמָּהֶן:","בְּכוֹר שֶׁנִּתְעָרֵב בְּפֶסַח שְׁנֵיהֶם יִרְעוּ עַד שֶׁיִּפּל בָּהֶם מוּם וְיֵאָכְלוּ כִּבְכוֹר. וְלָמָּה לֹא יִקָּרְבוּ. לְפִי שֶׁהַפֶּסַח נֶאֱכָל לְכָל אָדָם עַד חֲצוֹת וְהַבְּכוֹר לִשְׁנֵי יָמִים וְאֵינוֹ נֶאֱכָל אֶלָּא לַכֹּהֲנִים. וְאֵין מְבִיאִין קָדָשִׁים לְבֵית הַפְּסוּל וְאֵין מְמַעֲטִין בַּאֲכִילָתָן:","וְכֵן מַעֲשֵׂר שֶׁנִּתְעָרֵב בְּפֶסַח כְּשֶׁיִּפּל בָּהֶן מוּם יֵאָכְלוּ כְּמַעֲשֵׂר. הַבְּכוֹר וְהַמַּעֲשֵׂר שֶׁנִּתְעָרְבוּ יֵאָכְלוּ בְּמוּמָן:","וְכֵן שְׁאָר קָדָשִׁים שֶׁנִּתְעָרְבוּ בִּבְכוֹר וּבְמַעֲשֵׂר יִרְעוּ עַד שֶׁיִּפּל בָּהֶם מוּם וְיֵאָכְלוּ כִּבְכוֹר שֶׁנָּפַל בּוֹ מוּם אוֹ כְּמַעֲשֵׂר שֶׁנָּפַל בּוֹ מוּם:","אָשָׁם שֶׁנִּתְעָרֵב בִּשְׁלָמִים. אַף עַל פִּי שֶׁאֵין מַקְרִיבִין מִשְּׁנֵיהֶן אֶלָּא הָאֵימוּרִין אֲבָל הַבָּשָׂר נֶאֱכָל. לֹא יִקָּרְבוּ אֶלָּא יִרְעוּ עַד שֶׁיִּפּל בָּהֶן מוּם וְיָבִיא בִּדְמֵי הַיָּפֶה אָשָׁם וּבִדְמֵי הַיָּפֶה שְׁלָמִים וְהַמּוֹתָר יַפְסִיד מִבֵּיתוֹ. וְאִם קָדַם וְהִקְרִיב אֲשָׁמוֹ שְׁנֵיהֶן יִפְּלוּ לִנְדָבָה:","כָּל הַקָּדָשִׁים אֶפְשָׁר שֶׁיִּתְעָרְבוּ מִין בְּמִינוֹ. חוּץ מִן הַחַטָּאת עִם הָאָשָׁם שֶׁאֵין הָאָשָׁם אֶלָּא מִזִּכְרֵי כְּבָשִׂים. וְאֵין לְךָ חַטָּאת מִן הַכְּבָשִׂים אֶלָּא נְקֵבָה:","וְכָל אֵלּוּ הַמִּתְעָרְבִין בַּחַיִּים אִם הִקְרִיב הֻרְצָה שֶׁאֵין בַּעֲלֵי חַיִּים נִדְחִין:","בְּהֵמָה שֶׁנִּמְצֵאת מִירוּשָׁלַיִם וְעַד מִגְדַּל עֵדֶר וּכְמִדָּתָה לְכָל רוּחַ. אִם נְקֵבָה בַּת שְׁנָתָהּ הִיא כּוֹנְסָהּ לְכִפָּה עַד שֶׁתָּמוּת שֶׁמָּא חַטָּאת הִיא. הָיְתָה בַּת שְׁתַּיִם יְבִיאֶנָּה שְׁלָמִים וְיָבִיא עִמָּהּ לֶחֶם שֶׁמָּא תּוֹדָה הִיא. מָצָא זָכָר בֶּן שְׁתֵּי שָׁנִים אֵין לוֹ תַּקָּנָה. שֶׁמָּא אָשָׁם הוּא וַעֲדַיִן לֹא כִּפְּרוּ בְּעָלָיו. מָצָא זָכָר בֶּן שָׁנָה מַנִּיחוֹ עַד שֶׁיִּפּל בּוֹ מוּם. וּמֵבִיא שְׁתֵּי בְּהֵמוֹת תַּחְתָּיו וּמַתְנֶה וְאוֹמֵר אִם עוֹלָה הָיָה זֶה עוֹלָה תַּחְתָּיו וְאִם שְׁלָמִים הָיָה זֶה שְׁלָמִים תַּחְתָּיו. וּמַקְרִיב הָאֶחָד עוֹלָה וּנְסָכָיו מִשֶּׁל צִבּוּר. וְהָאַחֵר שְׁלָמִים עִם הַלֶּחֶם שֶׁמָּא תּוֹדָה הָיָה. וּמַה יַּעֲשֶׂה בָּזֶה הַנִּמְצָא יֵאָכֵל בְּמוּמוֹ שֶׁאֲפִלּוּ הָיָה בְּכוֹר אוֹ מַעֲשֵׂר בְּמוּמוֹ הוּא נֶאֱכָל. וְאִם פֶּסַח אַחַר זְמַנּוֹ הוּא הֲרֵי זֶה שְׁלָמִים וּבִזְמַנּוֹ הַכּל נִזְהָרִין בּוֹ. וְאִם תֹּאמַר שֶׁמָּא אֲשַׁם נָזִיר אוֹ אֲשַׁם מְצֹרָע הוּא. אֵינָן מְצוּיִין תָּמִיד. לְפִיכָךְ לֹא חָשׁוּ לָהֶן:","נִתְעָרְבוּ קָדָשִׁים בְּקָדָשִׁים אַחַר שֶׁנִּשְׁחֲטוּ יֵאָכְלוּ כֶּחָמוּר שֶׁבָּהֶן. נִתְעָרְבוּ בִּפְסוּלֵי הַמֻּקְדָּשִׁין אוֹ בְּחֻלִּין שֶׁנִּשְׁחֲטוּ בָּעֲזָרָה תְּעֻבַּר צוּרָתָן וְיֵצְאוּ לְבֵית הַשְּׂרֵפָה:","אֵיבְרֵי חַטָּאת שֶׁנִּתְעָרְבוּ בְּאֵיבְרֵי עוֹלָה. מַנִּיחִין הַכּל עַד שֶׁיִּפָּסְדוּ וּתְעֻבַּר צוּרָתָן. וְשׂוֹרְפִין אוֹתָן בָּעֲזָרָה בְּמָקוֹם שֶׁשּׂוֹרְפִין פְּסוּלֵי הַמֻּקְדָּשִׁין:","אֵיבָר שֶׁל בַּעֲלֵי מוּמִין שֶׁנִּתְעָרֵב בְּאֵיבְרֵי קָדָשִׁים אֲפִלּוּ אֵיבָר בְּאֶלֶף אֵיבָרִים. יֵצְאוּ הַכּל לְבֵית הַשְּׂרֵפָה. וַאֲפִלּוּ קָרְבוּ כֻּלָּן חוּץ מֵאֶחָד מִן הַתַּעֲרֹבֶת. הֲרֵי זֶה יִשָּׂרֵף בָּעֲזָרָה בְּמָקוֹם שֶׁשּׂוֹרְפִין פְּסוּלֵי הַמֻּקְדָּשִׁין:","חֲתִיכוֹת קָדְשֵׁי קָדָשִׁים שֶׁנִּתְעָרְבוּ בַּחֲתִיכוֹת קָדָשִׁים קַלִּים. אוֹ הַנֶּאֱכָלִין לְיוֹם אֶחָד בְּנֶאֱכָלִין לִשְׁנֵי יָמִים. יֵאָכְלוּ כֶּחָמוּר שֶׁבָּהֶן:","חֲתִיכָה שֶׁל חַטָּאת טְמֵאָה שֶׁנִּתְעָרְבָה בְּמֵאָה חֲתִיכוֹת שֶׁל חַטָּאת טְהוֹרָה. וְכֵן פְּרוּסָה שֶׁל לֶחֶם הַפָּנִים שֶׁנִּטְמָא שֶׁנִּתְעָרְבָה בְּמֵאָה פְּרוּסוֹת שֶׁל לֶחֶם הַפָּנִים הַטָּהוֹר. הֲרֵי זוֹ תַּעֲלֶה כְּמוֹ שֶׁבֵּאַרְנוּ בִּתְרוּמוֹת:","אֲבָל חֲתִיכָה שֶׁל חַטָּאת שֶׁנִּתְעָרְבָה בְּמֵאָה חֲתִיכוֹת שֶׁל חֻלִּין. וְכֵן פְּרוּסָה שֶׁל לֶחֶם הַפָּנִים הַטָּהוֹר שֶׁנִּתְעָרְבָה בְּמֵאָה פְּרוּסוֹת שֶׁל חֻלִּין. הֲרֵי אֵלּוּ לֹא יַעֲלוּ אֶלָּא יֵאָכֵל הַכּל לַכֹּהֲנִים כְּכָל הַמְדֻמָּעוֹת:"],"Mishneh Torah, Sacrificial Procedure 17":["הַנּוֹדֵר מִנְחָה מַאֲפֵה תַּנּוּר לֹא יָבִיא מאֲפֵה כֻּפָּח וְלֹא מַאֲפֵה רְעָפִים וְלֹא מַאֲפֵה יוֹרוֹת הָעַרְבִיִּים:","הָאוֹמֵר הֲרֵי עָלַי בְּמַחֲבַת וְהֵבִיא בְּמַרְחֶשֶׁת. בְּמַרְחֶשֶׁת וְהֵבִיא בְּמַחֲבַת. מַה שֶּׁהֵבִיא הֵבִיא וִידֵי חוֹבָתוֹ לֹא יָצָא. וְאִם אָמַר זוֹ לְהָבִיא בְּמַרְחֶשֶׁת וֶהֱבִיאָהּ בְּמַחֲבַת. אוֹ בְּמַחֲבַת וֶהֱבִיאָהּ בְּמַרְחֶשֶׁת. הֲרֵי זוֹ פְּסוּלָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן הָאוֹמֵר הֲרֵי עָלַי שְׁנֵי עֶשְׂרוֹנוֹת לַהֲבִיאָן בִּכְלִי אֶחָד וֶהֱבִיאָן בִּשְׁנֵי כֵּלִים. בִּשְׁנֵי כֵּלִים וֶהֱבִיאָן בִּכְלִי אֶחָד. מַה שֶּׁהֵבִיא הֵבִיא וִידֵי חוֹבָתוֹ לֹא יָצָא. שֶׁנֶּאֱמַר (דברים כג כד) \"כַּאֲשֶׁר נָדַרְתָּ לַה'\":","אָמַר אֵלּוּ לְהָבִיא בִּכְלִי אֶחָד וְהֵבִיא בִּשְׁנֵי כֵּלִים אוֹ לְהָבִיא בִּשְׁנֵי כֵּלִים וְהֵבִיא בִּכְלִי אֶחָד הֲרֵי אֵלּוּ פְּסוּלִין. לֹא קְבָעָן בִּשְׁעַת הַנֵּדֶר אֶלָּא אָמַר הֲרֵי עָלַי שְׁנֵי עֶשְׂרוֹנוֹת וּבִשְׁעַת הַפְרָשָׁה קְבָעָן וְהִפְרִישָׁן בִּשְׁנֵי כֵּלִים וְחָזַר וֶהֱבִיאָן בִּכְלִי אֶחָד הֲרֵי אֵלּוּ כְּשֵׁרִים שֶׁנֶּאֱמַר (דברים כג כד) \"כַּאֲשֶׁר נָדַרְתָּ\" וְלֹא כַּאֲשֶׁר הִפְרַשְׁתָּ. אָמַר הֲרֵי עָלַי שְׁנֵי עֶשְׂרוֹנוֹת לְהָבִיא בִּכְלִי אֶחָד וֶהֱבִיאָן בִּשְׁנֵי כֵּלִים. אָמְרוּ לוֹ בִּכְלִי אֶחָד נָדַרְתָּ. הִקְרִיבָם בִּשְׁנֵי כֵּלִים הֲרֵי אֵלּוּ פְּסוּלִין. הִקְרִיבָם בִּכְלִי אֶחָד הֲרֵי אֵלּוּ כְּשֵׁרִים:","אָמַר הֲרֵי עָלַי שְׁנֵי עֶשְׂרוֹנוֹת לְהָבִיא בִּשְׁנֵי כֵּלִים וְהֵבִיא בִּכְלִי אֶחָד. אָמְרוּ לוֹ בִּשְׁנֵי כֵּלִים נָדַרְתָּ. הִקְרִיבָן בִּשְׁנֵי כֵּלִים הֲרֵי אֵלּוּ כְּשֵׁרִים. הִקְרִיבָן בִּכְלִי אֶחָד הֲרֵי אֵלּוּ כִּשְׁתֵּי מְנָחוֹת שֶׁנִּתְעָרְבוּ:","האוֹמֵר הֲרֵי עָלַי מִנְחָה. יָבִיא אַחַת מֵחֲמֵשֶׁת מִינֵי מְנָחוֹת הַבָּאוֹת בְּנֵדֶר וּנְדָבָה. אָמַר הֲרֵי עָלַי מְנָחוֹת יָבִיא שְׁנֵי (מִינֵי) מְנָחוֹת מֵחֲמִשְׁתָּן. אָמַר הֲרֵי עָלַי מִין מְנָחוֹת יָבִיא שְׁנֵי מְנָחוֹת מִמִּין אֶחָד. הֲרֵי עָלַי מִינֵי מְנָחוֹת יָבִיא שְׁתֵּי מְנָחוֹת מִשְּׁנֵי מִינִים. וְכֵן אִם אָמַר מִינֵי מִנְחָה יָבִיא שְׁנֵי מִינִין. קָבַע נִדְרוֹ בְּמִין מֵהֶן וּשְׁכָחוֹ מֵבִיא חֲמִשְּׁתָן:","אֵין הַיָּחִיד מֵבִיא מִנְחָה בִּכְלִי אֶחָד יוֹתֵר מִשִּׁשִּׁים עִשָּׂרוֹן. וְאִם נָדַר יוֹתֵר מִשִּׁשִּׁים מֵבִיא שִׁשִּׁים בִּכְלִי אֶחָד וְהַשְּׁאָר בִּכְלִי שֵׁנִי. שֶׁאֵין יְכוֹלִין לְהִבָּלֵל כְּאֶחָד אֶלָּא שִׁשִּׁים אֲבָל יֶתֶר עַל שִׁשִּׁים אֵין נִבְלָלִין. אַף עַל פִּי שֶׁאֵין הַבְּלִילָה מְעַכֶּבֶת כְּמוֹ שֶׁבֵּאַרְנוּ אָמְרוּ חֲכָמִים כָּל הָרָאוּי לְבִילָה אֵין הַבִּילָה מְעַכֶּבֶת בּוֹ וְכָל שֶׁאֵינוֹ רָאוּי לְבִילָה הַבִּילָה מְעַכֶּבֶת בּוֹ:","אָמַר הֲרֵי עָלַי מֵאָה וְעֶשְׂרִים וְאֶחָד עִשָּׂרוֹן מֵבִיא מֵאָה וְעֶשְׂרִים בִּשְׁנֵי כֵּלִים שִׁשִּׁים בְּכָל כְּלִי וּמֵבִיא עִשָּׂרוֹן אֶחָד בַּכְּלִי הַשְּׁלִישִׁי. אָמַר הֲרֵי עָלַי עִשָּׂרוֹן יָבִיא עִשָּׂרוֹן אֶחָד. הֲרֵי עָלַי עֶשְׂרוֹנוֹת יָבִיא שְׁנַיִם. פֵּרֵשׁ נִדְרוֹ וְשָׁכַח כַּמָּה עִשָּׂרוֹן פֵּרֵשׁ יָבִיא שִׁשִּׁים עִשָּׂרוֹן בִּכְלִי אֶחָד. שָׁכַח כַּמָּה עִשָּׂרוֹן פֵּרֵשׁ וּבְאֵי זֶה מִין קְבָעוֹ. הֲרֵי זֶה מֵבִיא שִׁשִּׁים עִשָּׂרוֹן מִכָּל מִין וָמִין מֵחֲמִשְׁתָּן:","קָבַע נִדְרוֹ וְשָׁכַח כַּמָּה עֶשְׂרוֹנוֹת נָדַר וּבְכַמָּה כֵּלִים נָדַר הֲרֵי זֶה מֵבִיא מֵאֶחָד וְעַד שִׁשִּׁים בְּשִׁשִּׁים כֵּלִים. כֵּיצַד. מֵבִיא עִשָּׂרוֹן אֶחָד בִּכְלִי רִאשׁוֹן וּשְׁנֵי עֶשְׂרוֹנִים בִּכְלִי שֵׁנִי וּשְׁלֹשָׁה עֶשְׂרוֹנִים בַּשְּׁלִישִׁי עַד שֶׁיִּהְיוּ עַד שִׁשִּׁים עִשָּׂרוֹן בַּכְּלִי הָאַחֲרוֹן. וְאִם שָׁכַח אַף בְּאֵי זֶה מִין קָבַע מֵבִיא עַל סֵדֶר זֶה שִׁשִּׁים כֵּלִים מִכָּל מִין וְנִמְצָא מֵבִיא מִכָּל מִין אֶלֶף וּשְׁמוֹנֶה מֵאוֹת וּשְׁלֹשִׁים עִשָּׂרוֹן:","הָאוֹמֵר הֲרֵי עָלַי מִנְחַת שְׂעוֹרִים אוֹ מִנְחַת חֲצִי עִשָּׂרוֹן אוֹ מִנְחַת בְּלֹא שֶׁמֶן וּלְבוֹנָה הֲרֵי זֶה פָּטוּר. שֶׁלֹּא הִתְנַדֵּב דָּבָר שֶׁכָּמוֹהוּ מַקְרִיבִין. אָמַר הֲרֵי עָלַי מִנְחָה מִן הַשְּׂעוֹרִים אוֹ מִן הָעֲדָשִׁים אוֹ מִנְחָה בְּלֹא שֶׁמֶן וּלְבוֹנָה אוֹ מִנְחָה חֲצִי עִשָּׂרוֹן. שׁוֹאֲלִין אוֹתוֹ אִם אָמַר לֹא נָדַרְתִּי אֶלָּא עַל דַּעַת שֶׁמֻּתָּר לְהַקְרִיב כָּזֶה וְאִלּוּ יָדַעְתִּי שֶׁאֵין מַקְרִיבִין אֶלָּא עִשָּׂרוֹן שָׁלֵם סלֶת בְּשֶׁמֶן וּלְבוֹנָה לֹא הָיִיתִי נוֹדֵר הֲרֵי זֶה פָּטוּר. וְאִם אָמַר אִלּוּ הָיִיתִי יוֹדֵעַ הָיִיתִי נוֹדֵר כְּדֶרֶךְ שֶׁמַּקְרִיבִין הֲרֵי זֶה חַיָּב לְהַקְרִיב כְּדֶרֶךְ שֶׁמַּקְרִיבִין:","נָדַר עִשָּׂרוֹן וּמֶחֱצָה וְאָמַר אִלּוּ הָיִיתִי יוֹדֵעַ הָיִיתִי נוֹדֵר כְּדֶרֶךְ הַמִּתְנַדְּבִין הֲרֵי זֶה מֵבִיא שְׁנַיִם. אָמַר הֲרֵי עָלַי קֶמַח אוֹ הֲרֵי עָלַי חֲצִי עִשָּׂרוֹן וְלֹא הִזְכִּיר שֵׁם מִנְחָה הֲרֵי זֶה פָּטוּר כְּמִי שֶׁלֹּא נָדַר מֵעוֹלָם. וְכֵן הָאוֹמֵר הֲרֵי עָלַי תּוֹדָה בְּלֹא לֶחֶם וְזֶבַח בְּלֹא נְסָכִים הֲרֵי זֶה פָּטוּר. וְאִם אָמַר אִלּוּ הָיִיתִי יוֹדֵעַ שֶׁאֵין מַקְרִיבִין כָּךְ הָיִיתִי נוֹדֵר כְּדֶרֶךְ הַנּוֹדְרִין הֲרֵי זֶה חַיָּב לְהַקְרִיב כְּדֶרֶךְ הַמַּקְרִיבִין:","הָאוֹמֵר הֲרֵי עָלַי לַחְמֵי תּוֹדָה יָבִיא תּוֹדָה וְלַחְמָהּ. שֶׁהַדָּבָר יָדוּעַ שֶׁאֵין מַקְרִיבִין לֶחֶם בְּלֹא תּוֹדָה וְסוֹף הַקָּרְבָּן הִזְכִּיר. אָמַר הֲרֵי עָלַי לֶחֶם לִפְטֹר תּוֹדָתוֹ שֶׁל פְּלוֹנִי יָבִיא לֶחֶם תּוֹדָה עִם תּוֹדַת חֲבֵרוֹ:","מִתְנַדֵּב אוֹ נוֹדֵר אָדָם יַיִן בִּפְנֵי עַצְמוֹ. וְאֵין מִתְנַדְּבִין לוֹג יַיִן וְלֹא שְׁנֵי לוֹגִין. שֶׁאֵין בִּנְסָכִים לֹא לוֹג וְלֹא שְׁנַיִם. וְאֵין מִתְנַדְּבִין חֲמִשָּׁה שֶׁאֵין חֲמֵשֶׁת לוֹגִין רְאוּיִין לֹא לְנִסְכֵּי בְּהֵמָה אַחַת וְלֹא לְנִסְכֵּי שְׁתֵּי בְּהֵמוֹת. אֲבָל מִתְנַדְּבִין שְׁלֹשָׁה וְאַרְבָּעָה וְשִׁשָּׁה וּמִשִּׁשָּׁה וָמַעְלָה מִפְּנֵי שֶׁהֵן רְאוּיִין לְנִסְכֵּי בְּהֵמוֹת:","כֵּיצַד. נָדַר שִׁבְעָה הֲרֵי הֵן כְּנִסְכֵּי כֶּבֶשׂ וְאַיִל. נָדַר שְׁמוֹנָה הֲרֵי אֵלּוּ כְּנִסְכֵּי שְׁנֵי אֵילִים. תִּשְׁעָה כְּנִסְכֵּי שׁוֹר וְכֶבֶשׂ אוֹ כְּנִסְכֵּי שְׁלֹשָׁה כְּבָשִׂים. נָדַר עֲשָׂרָה הֲרֵי אֵלּוּ כְּנִסְכֵּי שׁוֹר וְאַיִל אוֹ שְׁנֵי כְּבָשִׂים וְאַיִל וְכֵן עַד לְעוֹלָם:","נָדַר חֲמִשָּׁה לוֹגִין אוֹמְרִין לוֹ הַשְׁלֵם שִׁשָּׁה שֶׁהֲרֵי קְבָעָן לְקָרְבָּן. אֲבָל אִם נָדַר לוֹג אוֹ שְׁנַיִם פָּטוּר שֶׁהֲרֵי אֵינָן רְאוּיִין כְּלָל לֹא הֵן וְלֹא מִקְצָתָן. וְאֵין מִתְנַדְּבִין וְלֹא נוֹדְרִין פָּחוֹת מִלּוֹג שֶׁמֶן. שֶׁאֵין לְךָ מִנְחָה פְּחוּתָה מֵעִשָּׂרוֹן וְהִיא צְרִיכָה לוֹג אֶחָד שֶׁמֶן:","הָאוֹמֵר הֲרֵי עָלַי יַיִן לֹא יִפְחֹת מִשְּׁלֹשָׁה לוֹגִין. הֲרֵי עָלַי שֶׁמֶן לֹא יִפְחֹת מִלּוֹג. פֵּרֵשׁ נִדְרוֹ וְשָׁכַח כַּמָּה לוֹג נָדַר מִן הַיַּיִן אוֹ מִן הַשֶּׁמֶן יָבִיא אַרְבָּעִים וּמֵאָה לוֹג. שֶׁאֵין לְךָ יוֹם שֶׁמַּקְרִיבִין בּוֹ הַצִּבּוּר קָרְבָּנוֹת מְרֻבּוֹת יוֹתֵר מִיּוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג שֶׁחָל לִהְיוֹת בְּשַׁבָּת וְהָיוּ הַנְּסָכִים בּוֹ מֵאָה וְאַרְבָּעִים לוֹג שֶׁמֶן וּכְמוֹתָם יַיִן כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת תְּמִידִין וּמוּסָפִין:"],"Mishneh Torah, Sales 10":["מִי שֶׁאֲנָסוּהוּ עַד שֶׁמָּכַר וְלָקַח דְּמֵי הַמִּקָּח. אֲפִלּוּ תָּלוּהוּ עַד שֶׁמָּכַר מִמְכָּרוֹ מִמְכָּר בֵּין בְּמִטַּלְטְלִין בֵּין בְּקַרְקָעוֹת שֶׁמִּפְּנֵי אָנְסוֹ גָּמַר וּמַקְנֶה. אַף עַל פִּי שֶׁלֹּא לָקַח הַדָּמִים בִּפְנֵי הָעֵדִים. לְפִיכָךְ אִם מָסַר מוֹדָעָה קֹדֶם שֶׁיִּמְכֹּר וְאָמַר לִשְׁנֵי עֵדִים דְּעוּ שֶׁזֶּה שֶׁאֲנִי מוֹכֵר חֵפֶץ פְּלוֹנִי אוֹ שָׂדֶה פְּלוֹנִי לִפְלוֹנִי מִפְּנֵי שֶׁאֲנִי אָנוּס. הֲרֵי הַמִּמְכָּר בָּטֵל. וַאֲפִלּוּ הֶחֱזִיק כַּמָּה שָׁנִים מוֹצִיאִין אוֹתָהּ מִיָּדוֹ וּמַחֲזִיר הַדָּמִים:","וּצְרִיכִין הָעֵדִים לֵידַע שֶׁהוּא מוֹכֵר מִפְּנֵי הָאֹנֶס וְשֶׁהוּא אָנוּס וַדַּאי. לֹא שֶׁיִּסְמְכוּ עַל פִּיו. וְכָל מוֹדָעָה שֶׁאֵין כָּתוּב בָּהּ וְאָנוּ הָעֵדִים יָדַעְנוּ שֶׁפְּלוֹנִי זֶה אָנוּס הָיָה אֵינָהּ מוֹדָעָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמוֹכֵר אוֹ בְּעוֹשֶׂה פְּשָׁרָה. אֲבָל בְּמַתָּנָה אוֹ בִּמְחִילָה אִם מָסַר מוֹדָעָה קֹדֶם מַתָּנָה אַף עַל פִּי שֶׁאֵינוֹ אָנוּס הֲרֵי הַמַּתָּנָה בְּטֵלָה. שֶׁאֵין הוֹלְכִין בְּמַתָּנָה אֶלָּא אַחַר גִּלּוּי דַּעַת הַנּוֹתֵן שֶׁאִם אֵינוֹ רוֹצֶה לְהַקְנוֹת בְּכָל לִבּוֹ לֹא קָנָה הַמְקַבֵּל מַתָּנָה. וְהַמְּחִילָה מַתָּנָה הִיא:","אֶחָד הָאוֹנֵס אֶת חֲבֵרוֹ בְּשֶׁהִכָּהוּ אוֹ תְּלָאָהוּ עַד שֶׁמָּכַר אוֹ שֶׁהִפְחִידוֹ בְּדָבָר שֶׁאֶפְשָׁר לוֹ לַעֲשׂוֹת בֵּין בִּידֵי עַכּוּ\"ם בֵּין בִּידֵי יִשְׂרָאֵל הֲרֵי זֶה אוֹנֵס. וּמַעֲשֶׂה בְּאֶחָד שֶׁשָּׂכַר פַּרְדֵּס מֵחֲבֵרוֹ לְעֶשֶׂר שָׁנִים וְלֹא הָיָה שְׁטַר חוֹב בְּיַד הַמַּשְׂכִּיר וְאַחַר שֶׁאֲכָלוֹ הַשּׂוֹכֵר שָׁלֹשׁ שָׁנִים אָמַר לוֹ אִם לֹא תִּמְכְּרֶנוּ לִי אֶכְבּשׁ שְׁטַר שְׂכִירוּת וְאֶטְעֹן שֶׁהוּא לָקוּחַ בְּיָדִי וְאָמְרוּ חֲכָמִים שֶׁזֶּה אוֹנֵס. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. לְפִיכָךְ אִם תְּבָעוֹ הַמַּשְׂכִּיר בְּבֵית דִּין וְכָפַר בּוֹ וְטָעַן שֶׁהַפַּרְדֵּס שֶׁלּוֹ וְאַחַר כָּךְ מָסַר הַמַּשְׂכִּיר מוֹדָעָה וְאַחַר כָּךְ מָכַר לַשּׂוֹכֵר שֶׁכָּפַר בּוֹ הֲרֵי הַמִּמְכָּר בָּטֵל. שֶׁהֲרֵי יֵשׁ לוֹ עֵדִים שֶׁהוּא אָנוּס. וְהֵם הָעֵדִים שֶׁכָּפַר בִּפְנֵיהֶם בְּבֵית דִּין וְהֵם עֵדֵי הַמּוֹדָעָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּאַנָּס שֶׁהֲרֵי הוּא חַמְסָן מִפְּנֵי שֶׁכּוֹפֶה אֶת הַמּוֹכֵר לִמְכֹּר שֶׁלֹּא בִּרְצוֹנוֹ. אֲבָל הַגּוֹזֵל וְהֻחְזַק בְּגַזְלָן וְאַחַר כָּךְ לָקַח שָׂדֶה שֶׁגָּזַל אֵין הַמּוֹכֵר צָרִיךְ לִמְסֹר מוֹדָעָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת גְּזֵלָה:","עֵדֵי הַמּוֹדָעָה יֵשׁ לָהֶם לַחְתֹּם הֵם עַצְמָן בְּאוֹתוֹ הַמִּמְכָּר שֶׁנִּמְסְרָה לָהֶם הַמּוֹדָעָה עָלָיו וְאֵין בְּכָךְ כְּלוּם. וַאֲפִלּוּ אָמַר לָהֶם בִּפְנֵי הָאַנָּס בִּרְצוֹנִי מָכַרְתִּי בְּלֹא אֹנֶס הֲרֵי הַמּוֹדָעָה קַיֶּמֶת. כְּשֵׁם שֶׁאֲנָסוֹ שֶׁמָּכַר בְּלֹא רָצוֹן כָּךְ אֲנָסוֹ עַד שֶׁאָמַר בִּרְצוֹנִי אֲנִי מוֹכֵר:","וְכֵן אִם הוֹדָה בִּפְנֵיהֶם שֶׁלָּקַח הַדָּמִים אַחַר שֶׁמָּסַר מוֹדָעָה עַל כָּךְ אֵינוֹ חַיָּב לְהַחְזִיר כְּלוּם. שֶׁהָאוֹנֵס אֲנָסוֹ עַד שֶׁיּוֹדֶה וְהָעֵדִים כְּבָר יָדְעוּ שֶׁהוּא אָנוּס. אֲבָל אִם מָנָה הַדָּמִים בִּפְנֵיהֶם חַיָּב לְהַחְזִיר:","הֵעִידוּ עָלָיו עֵדֵי הַמֶּכֶר שֶׁבִּטֵּל הַמּוֹדָעָה הֲרֵי הַמּוֹדָעָה בְּטֵלָה. וְאִם אָמַר לְעֵדֵי הַמּוֹדָעָה הֱיוּ יוֹדְעִין שֶׁכָּל קִנְיָן שֶׁאֲנִי לוֹקֵחַ לְבַטֵּל הַמּוֹדָעָה וּמוֹדָעֵי דְּמוֹדָעֵי שֶׁהַכּל בָּטֵל וְאֵינִי אוֹמֵר כָּךְ אֶלָּא מִפְּנֵי הָאֹנֶס שֶׁאַתֶּם יוֹדְעִין וְאֵין בְּדַּעְתִּי לְהַקְנוֹת לְזֶה הָאַנָּס לְעוֹלָם. הֲרֵי הַמֶּכֶר בָּטֵל. וְאַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ לְבַטֵּל הַמּוֹדָעָה עַל הַדֶּרֶךְ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Sales 21":["הַמַּקְנֶּה לַחֲבֵרוֹ דָּבָר שֶׁאֵינוֹ מְסֻיָּם. אִם הָיָה מִינוֹ יָדוּעַ אַף עַל פִּי שֶׁאֵין מִדָּתוֹ וּמִשְׁקָלוֹ וּמִנְיָנוֹ יָדוּעַ הֲרֵי זֶה קָנָה. וְאִם אֵין מִינוֹ יָדוּעַ לֹא קָנָה:","כֵּיצַד. עֲרֵמָה זוֹ שֶׁל חִטִּים אֲנִי מוֹכֵר לְךָ בְּכָךְ וְכָךְ. מַרְתֵּף זֶה שֶׁל יַיִן אֲנִי מוֹכֵר לְךָ בְּכָךְ וְכָךְ. שַׂק שֶׁל תְּאֵנִים אֲנִי מוֹכֵר לְךָ בְּכָךְ וְכָךְ. אַף עַל פִּי שֶׁאֵין מִדַּת הָעֲרֵמָה יְדוּעָה וְלֹא מִשְׁקַל הַתְּאֵנִים וְלֹא מִנְיַן הַקַּנְקַנִּים יָדוּעַ הֲרֵי זֶה מִמְכָּרוֹ קַיָּם אַף עַל פִּי שֶׁנִּמְצָא חָסֵר אוֹ יָתֵר עַל הָאֹמֶד שֶׁהָיָה בְּדַעְתָּם. וְיֵשׁ לָהֶם הוֹנָיָה לְפִי הַשַּׁעַר שֶׁבַּשּׁוּק כְּמוֹ שֶׁבֵּאַרְנוּ:","אֲבָל הָאוֹמֵר לַחֲבֵרוֹ כָּל מַה שֶּׁיֵּשׁ בְּבַיִת זֶה אֲנִי מוֹכֵר לְךָ בְּכָךְ וְכָךְ. וְכָל מַה שֶּׁיֵּשׁ בְּתֵבָה זוֹ אֲנִי מוֹכֵר לְךָ בְּכָךְ וְכָךְ. אוֹ בַּשַּׂק הַזֶּה אֲנִי מוֹכֵר לְךָ בְּכָךְ וְכָךְ. וְרָצָה הַלּוֹקֵחַ וּמָשַׁךְ אֵין כָּאן קִנְיָן. שֶׁלֹּא סָמְכָה דַּעְתּוֹ שֶׁל לוֹקֵחַ. שֶׁהֲרֵי אֵינוֹ יוֹדֵעַ מַה שֶּׁיֵּשׁ בּוֹ אִם תֶּבֶן אוֹ זָהָב. וְאֵין זֶה אֶלָּא כִּמְשַׂחֵק בְּקֻבִּיָּא. וְכֵן כָּל הַיּוֹצֵא בָּזֶה:","וְכֵן הַמּוֹכֵר לַחֲבֵרוֹ בַּעֲשָׂרָה דִּינָרִין חִטִּים וְלֹא פָּסַק כַּמָּה סְאָה מָכַר לוֹ נוֹתֵן לוֹ כַּשַּׁעַר שֶׁבַּשּׁוּק בִּשְׁעַת הַמְּכִירָה. וְכָל הַחוֹזֵר בּוֹ מֵאַחַר נְתִינַת הַדָּמִים וְלֹא רָצָה כַּשַּׁעַר שֶׁהָיָה בַּשּׁוּק בִּשְׁעַת נְתִינַת הַמָּעוֹת מְקַבֵּל מִי שֶׁפָּרַע כְּמוֹ שֶׁבֵּאַרְנוּ:","הַמּוֹכֵר מָקוֹם לַחֲבֵרוֹ לַעֲשׂוֹת בַּיִת אוֹ רֶפֶת בָּקָר. וְכֵן הַמְקַבֵּל מֵחֲבֵרוֹ לַעֲשׂוֹת לוֹ בֵּית חַתְנוּת לִבְנוֹ אוֹ בֵּית אַלְמָנוּת לְבִתּוֹ עוֹשֶׂה לוֹ אַרְבַּע אַמּוֹת עַל שֵׁשׁ. מָכַר לוֹ מְקוֹם בַּיִת גָּדוֹל עוֹשֶׂה שְׁמוֹנֶה עַל עֶשֶׂר. מָכַר לוֹ מְקוֹם טְרַקְלִין עוֹשֶׂה עֶשֶׂר עַל עֶשֶׂר. תַּרְבָּץ שֶׁל חָצֵר שְׁתֵּים עֶשְׂרֵה עַל שְׁתֵּים עֶשְׂרֵה. וְרוּם כָּל בַּיִת וּבַיִת כַּחֲצִי אָרְכּוֹ וַחֲצִי רָחְבּוֹ:","הַמּוֹכֵר מָקוֹם לַחֲבֵרוֹ לַעֲשׂוֹת לוֹ קְבוּרָה. אוֹ הַמְקַבֵּל מֵחֲבֵרוֹ לַעֲשׂוֹת לוֹ קְבוּרָה. עוֹשֶׂה מְעָרָה וּפוֹתֵחַ לְתוֹכָהּ שְׁמוֹנָה קְבָרִים שְׁלֹשָׁה מִכָּאן וּשְׁלֹשָׁה מִכָּאן וּשְׁנַיִם מִכְּנֶגֶד הַנִּכְנָס לַמְּעָרָה. מִדַּת הַמְּעָרָה אַרְבַּע אַמּוֹת עַל שֵׁשׁ. וְכָל קֶבֶר וְקֶבֶר אַרְבַּע אַמּוֹת אֹרֶךְ וְרֹחַב שִׁשָּׁה טְפָחִים וְרוּם שִׁבְעָה. נִמְצָא בֵּין כָּל קֶבֶר וְקֶבֶר שֶׁמִּן הַצְּדָדִין אַמָּה וּמֶחֱצָה. וּבֵין הַשְּׁנַיִם הָאֶמְצָעִיִּים שְׁתֵּי אַמּוֹת:","הַמּוֹכֵר לַחֲבֵרוֹ בְּתוֹךְ שָׂדֵהוּ מְקוֹם אַמַּת מַיִם לְהַשְׁקוֹת בָּהּ בֵּית הַשְּׁלָחִין. נוֹתֵן לוֹ בְּתוֹךְ שָׂדֵהוּ אַמָּה שֶׁרָחְבָּהּ שְׁתֵּי אַמּוֹת וְאַמָּה מִכָּאן וְאַמָּה מִכָּאן לַאֲגַפֶּיהָ. וְאִם מָכַר לוֹ אַמַּת הַמַּיִם לְהַשְׁקוֹת בָּהּ בְּסִילוֹן. נוֹתֵן לוֹ אַמָּה שֶׁרָחְבָּהּ אַמָּה וַחֲצִי אַמָּה מִכָּאן וַחֲצִי אַמָּה מִכָּאן לַאֲגַפֶּיהָ:","אֵלּוּ הָאֲגַפִּין בַּעַל הַשָּׂדֶה נוֹטְעָן אֲבָל אֵינוֹ זוֹרְעָן. שֶׁהַזְּרָעִים מְחַלְחְלִין אֶת הַקַּרְקַע וּמְקַלְקְלִין אֶת אַמַּת הַמַּיִם. וְאַמַּת הַמַּיִם זֹאת שֶׁכָּלוּ אֲגַפֶּיהָ בַּעַל הָאַמָּה מְתַקְּנָן בַּעֲפַר אוֹתָהּ שָׂדֶה. שֶׁעַל מְנָת כֵּן קִבֵּל עָלָיו הַמּוֹכֵר לִהְיוֹת אַמַּת הַמַּיִם בְּתוֹךְ שָׂדֵהוּ:","הַמּוֹכֵר לַחֲבֵרוֹ דֶּרֶךְ בְּתוֹךְ שָׂדֵהוּ. אִם דֶּרֶךְ יָחִיד מָכַר לוֹ נוֹתֵן לוֹ שְׁתֵּי אַמּוֹת וּמֶחֱצָה רֹחַב כְּדֵי שֶׁיַּעֲמֹד חֲמוֹר בְּמַשָּׂאוֹ עַל אֹרֶךְ הַדֶּרֶךְ. מָכַר לוֹ דֶּרֶךְ בֵּין עִיר לָעִיר נוֹתֵן לוֹ רֹחַב שְׁמוֹנֶה אַמּוֹת בְּאֹרֶךְ הַדֶּרֶךְ. מָכַר לוֹ דֶּרֶךְ הָרַבִּים נוֹתֵן לוֹ רֹחַב שֵׁשׁ עֶשְׂרֵה אַמָּה:","דֶּרֶךְ הַמֶּלֶךְ וְדֶרֶךְ הַקֶּבֶר אֵין לָהּ שִׁעוּר. וְנִרְאָה לִי שֶׁזֶּה כְּמוֹכֵר דָּבָר שֶׁאֵין מִינוֹ יָדוּעַ:","מָכַר לוֹ מָקוֹם לְמַעֲמָד נוֹתֵן לוֹ בֵּית אַרְבָּעָה קַבִּים:","הָאוֹמֵר לַחֲבֵרוֹ בּוֹר וּכְתָלֶיהָ אֲנִי מוֹכֵר לְךָ נוֹתֵן לוֹ רֹחַב הַכֹּתֶל שְׁלֹשָׁה טְפָחִים:","הַמּוֹכֵר שָׂדֶה לַחֲבֵרוֹ וּמֵצֵר לוֹ מֵצַר אֶחָד אָרוֹךְ וּמֵצַר אֶחָד קָצָר. אִם הָיָה הָאָרֹךְ שֶׁל אִישׁ אֶחָד לֹא קָנָה מִן הָאָרֹךְ אֶלָּא כְּנֶגֶד קָצָר. וְאִם הָיָה שֶׁל שְׁנַיִם יִקְנֶה כְּנֶגֶד רֹאשׁ תּוֹר:","הָיָה מֵצַר רְאוּבֵן מִזְרָח וּמַעֲרָב וּמֵצַר שִׁמְעוֹן צָפוֹן וְדָרוֹם צָרִיךְ שֶׁיִּכְתֹּב לוֹ מֵצַר רְאוּבֵן מִשְּׁתֵי רוּחוֹת וּמֵצַר שִׁמְעוֹן מִשְּׁתֵי רוּחוֹת:","מֵצֵר לוֹ מֵצַר רִאשׁוֹן וּמֵצַר שֵׁנִי וּמֵצַר שְׁלִישִׁי וְלֹא מֵצֵר מֵצַר רְבִיעִי קָנָה הַשָּׂדֶה כֻּלָּהּ אֲבָל מֵצַר הָרְבִיעִי לֹא קָנָה. וְאִם הָיָה מֻבְלָע בֵּין הַמְּצָרִים וְאֵין עָלָיו רֶכֶב שֶׁל דְּקָלִים וְאֵין בּוֹ תִּשְׁעָה קַבִּין קָנָה אַף הַמֵּצַר הָרְבִיעִי. וְאִם לֹא הָיָה מֻבְלָע וְיֵשׁ עָלָיו רֶכֶב שֶׁל דְּקָלִים אוֹ שֶׁיֵּשׁ בּוֹ תִּשְׁעָה קַבִּין לֹא קָנָהוּ. הָיָה מֻבְלָע וְיֵשׁ עָלָיו רֶכֶב דְּקָלִים אוֹ שֶׁיֵּשׁ בּוֹ תִּשְׁעָה קַבִּין. אוֹ שֶׁלֹּא הָיָה מֻבְלָע וְאֵין עָלָיו רֶכֶב דְּקָלִים וְאֵין בּוֹ תִּשְׁעָה קַבִּין. הֲרֵי הַדָּבָר מָסוּר לְבֵית דִּין כְּפִי מַה שֶּׁיִּרְאוּ לְאֵיזוֹ דֶּרֶךְ שֶׁדַּעְתָּן נוֹטָה יַעֲשׂוּ:","סִיֵּם לוֹ אֶת הַזָּוִיּוֹת בִּלְבַד וְלֹא סִיֵּם לוֹ אֶת הַמֵּצַר שֶׁלְּכָל רוּחַ. אוֹ שֶׁסִּיֵּם לוֹ שְׁנֵי מְצָרִים כְּמִין גַּא\"ם. אוֹ שֶׁסִּיֵּם לוֹ חֵלֶק מִכָּל רוּחַ וְרוּחַ. הֲרֵי זֶה לֹא קָנָה אֶת כֻּלָּם אֶלָּא יִקְנֶה מִמֶּנָּה כְּפִי מַה שֶּׁמָּסַר לוֹ וְכַמָּה שֶׁיִּרְאוּ הַדַּיָּנִין:","הַמּוֹכֵר בַּיִת לַחֲבֵרוֹ בְּבִירָה גְּדוֹלָה. אַף עַל פִּי שֶׁמֵּצֵר לוֹ מְצָרִים הַחִיצוֹנִים. וְאַף עַל פִּי שֶׁיֵּשׁ שָׁם מְעַט שֶׁקּוֹרְאִין לְבִירָה בַּיִת. לֹא קָנָה אֶלָּא הַבַּיִת בִּלְבַד. שֶׁהַמְּצָרִים הוּא שֶׁהִרְחִיב לוֹ. וְאִלּוּ מָכַר לוֹ כָּל הַבִּירָה הָיָה כּוֹתֵב לוֹ וְלֹא הִנַּחְתִּי לְפָנַי בְּמֶכֶר זֶה כְּלוּם. וְכֵן הַמּוֹכֵר שָׂדֶה בְּבִקְעָה גְּדוֹלָה וּמֵצֵר לוֹ מְצַרֵי הַבִּקְעָה. מְצָרִים הֵם שֶׁהִרְחִיב לוֹ:","האוֹמֵר לַחֲבֵרוֹ שָׂדוֹת אֲנִי מוֹכֵר לְךָ. מִעוּט שָׂדוֹת שְׁתַּיִם. אָמַר לוֹ כָּל שָׂדוֹת אֲפִלּוּ שָׁלֹשׁ וְאַרְבַּע חוּץ מִגַּנּוֹת וּפַרְדֵּסִים. אָמַר לוֹ נְכָסִים אֲפִלּוּ גַנּוֹת וּפַרְדֵּסִים חוּץ מִבָּתִּים וַעֲבָדִים. וְאִם אָמַר לוֹ כָּל נְכָסַי אֲפִלּוּ עֲבָדִים וּבָתִּים וְכָל הַמִּטַּלְטְלִין הַיְּדוּעִים לוֹ. וַאֲפִלּוּ תְּפִלִּין שֶׁבְּרֹאשׁוֹ בִּכְלַל הַמֶּכֶר:","הָאוֹמֵר לַחֲבֵרוֹ בַּיִת מִבָּתַּי וְשׁוֹר מִשְּׁוָרַי אֲנִי מוֹכֵר לְךָ. נוֹתֵן לוֹ הַקָּטָן שֶׁבָּהֶן. מֵת אֶחָד מִן הַשְּׁוָרִים אוֹ שֶׁנָּפַל אֶחָד מִן הַבָּתִּים. מַרְאֶה לוֹ זֶה שֶׁמֵּת אוֹ שֶׁנָּפַל. שֶׁיַּד בַּעַל הַשְּׁטָר עַל הַתַּחְתּוֹנָה:","הָאוֹמֵר לַחֲבֵרוֹ שָׂדֶה דְּבֵי חִיָּא אֲנִי מוֹכֵר לְךָ. וְהָיוּ שְׁתֵּי שָׂדוֹת הַנִּקְרָאִים בְּשֵׁם זֶה. אֵינוֹ קוֹנֶה אֶלָּא הַפָּחוּת שֶׁבָּהֶן. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","הָאוֹמֵר לַחֲבֵרוֹ שְׂדֵה רְאוּבֵן אֲנִי מוֹכֵר לְךָ. וְכֵיוָן שֶׁבָּא הַלּוֹקֵחַ לְהִשְׁתַּמֵּשׁ בָּהּ אָמַר לוֹ הַמּוֹכֵר אֵינָהּ זוֹ הַשָּׂדֶה שֶׁהָיְתָה שֶׁל רְאוּבֵן אֶלָּא כָּךְ הִיא קְרוּיָה וּלְעוֹלָם לֹא הָיְתָה לוֹ אֶלָּא זוֹ הִיא שֶׁהָיְתָה שֶׁל רְאוּבֵן וּלְקַחְתִּיהָ מִמֶּנּוּ וְהִיא שֶׁמְּכַרְתִּיהָ לְךָ. עַל הַמּוֹכֵר לְהָבִיא רְאָיָה. וְאִם לֹא הֵבִיא זוֹכֶה הַלּוֹקֵחַ בָּזוֹ שֶׁכָּל הָעָם קוֹרְאִים שֶׁל רְאוּבֵן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה הַלֵּךְ אַחַר הַשֵּׁם שֶׁהוּא פָּשׁוּט בְּפִי הַכּל:","הָאוֹמֵר לַחֲבֵרוֹ חֲצִי שָׂדֶה אֲנִי מוֹכֵר לְךָ שָׁמִין כַּמָּה שָׁוֶה כָּל הַשָּׂדֶה וְנוֹתֵן לוֹ מִן הַכָּחוּשׁ שֶׁבָּהּ מַה שֶּׁשָּׁוֶה חֲצִי הַדָּמִים שֶׁל כָּל הַשָּׂדֶה. וְכֵן אִם אָמַר לוֹ חֶצְיָהּ בַּדָּרוֹם אֲנִי מוֹכֵר לְךָ שָׁמִין דְּמֵי כֻּלָּהּ וְנוֹתֵן לוֹ בִּדְרוֹמָהּ כַּחֲצִי כָּל הַדָּמִים וּמְקַבֵּל עָלָיו הַלּוֹקֵחַ לַעֲשׂוֹת בְּחֶלְקוֹ מְקוֹם הַגָּדֵר. וּמֵאֲחוֹרֵי הַגָּדֵר סָמוּךְ לַגָּדֵר חָרִיץ קָטָן רָחָב שְׁלֹשָׁה טְפָחִים. וְחוּצָה לוֹ חָרִיץ אֶחָד גָּדוֹל רָחָב שִׁשָּׁה טְפָחִים. וּבֵין שְׁנֵי הַחֲרִיצִין רָחָב טֶפַח. כָּל זֶה כְּדֵי שֶׁלֹּא תִּקְפֹּץ הַנְּמִיָּה בָּהּ וְכַיּוֹצֵא בָּהּ:","הָיְתָה לוֹ חֲצִי שָׂדֶה וְאָמַר לַחֲבֵרוֹ חֲצִי שֶׁיֵּשׁ לִי בַּשָּׂדֶה מָכַרְתִּי לְךָ. קָנָה הַחֵצִי כֻּלּוֹ. אָמַר לוֹ חֲצִי הַשָּׂדֶה שֶׁיֵּשׁ לִי לֹא קָנָה אֶלָּא רְבִיעַ. אָמַר לוֹ מֵצַר שָׂדֶה שֶׁמִּמֶּנָּה [נֶחְלֶקֶת אוֹ שֶׁמִּמֶּנָּה נִפְסֶקֶת אוֹ שֶׁמִּמֶּנָּה] נֶחֱצֵת. אִם אָמַר לוֹ וְאֵלּוּ מְצָרֶיהָ קָנָה חֶצְיָהּ. וְאִם לֹא מֵצֵר לוֹ מְצָרֶיהָ לֹא קָנָה אֶלָּא בֵּית תִּשְׁעָה קַבִּין:"],"Mishneh Torah, Sales 5":["כָּל הַמִּטַּלְטְלִין קוֹנִין זֶה אֶת זֶה. כֵּיצַד. הֶחְלִיף פָּרָה בַּחֲמוֹר אוֹ יַיִן בְּשֶׁמֶן אַף עַל פִּי שֶׁמַּקְפִּידִין עַל הַדָּמִים וְשִׁעֲרוּ כַּמָּה שָׁוֶה זֶה וְכַמָּה שָׁוֶה זֶה וְאַחַר כָּךְ הֶחְלִיפוּ. כֵּיוָן שֶׁמָּשַׁךְ הָאֶחָד אוֹ הִגְבִּיהוֹ קָנָה הַשֵּׁנִי הַמִּטַּלְטְלִין הָאֲחֵרִים בְּכָל מָקוֹם שֶׁהֵם וְנַעֲשׂוּ בִּרְשׁוּתוֹ. וְאַף עַל פִּי שֶׁעֲדַיִן לֹא מְשָׁכָן:","הֶחְלִיף חֲמוֹר בְּפָרָה וְטָלֶה וּמָשַׁךְ הַפָּרָה וַעֲדַיִן לֹא מָשַׁךְ אֶת הַטָּלֶה לֹא קָנָה שֶׁאֵין כָּאן מְשִׁיכָה גְּמוּרָה. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","דָּמִים שֶׁאֵין מַקְפִּידִין עֲלֵיהֶם הֲרֵי הֵן כִּשְׁאָר מִטַּלְטְלִין וְקוֹנִין. כֵּיצַד. הֲרֵי שֶׁחָפַן מָעוֹת בְּלֹא מִשְׁקָל וּבְלֹא מִנְיָן אֶלָּא נְטָלָן אַכְסָרָה. וְאָמַר לוֹ מְכֹר לִי פָּרָתְךָ אוֹ יַיִן זֶה בְּאֵלּוּ וְנָתַן לוֹ אֶת הַדָּמִים קָנָה וְאֵין אֶחָד מֵהֶם יָכוֹל לַחְזֹר בּוֹ. שֶׁזֶּה דָּבָר שֶׁאֵינוֹ מָצוּי הוּא וְלֹא הִצְרִיכוּ בּוֹ מְשִׁיכָה:","וְכֵן רְאוּבֵן שֶׁמָּכַר מִטַּלְטְלִין לְשִׁמְעוֹן בַּחֲמִשִּׁים זוּז. וְקָנָה שִׁמְעוֹן הַמִּטַּלְטְלִין וְנִתְחַיֵּב בְּדָמִים. וְאַחַר שֶׁנִּתְחַיֵּב שִׁמְעוֹן בַּחֲמִשִּׁים זוּז אֵלּוּ הָיָה לוֹ יַיִן אוֹ בְּהֵמָה אוֹ עֶבֶד וְכַיּוֹצֵא בָּהֶן מִשְּׁאָר הַמִּטַּלְטְלִין וְהָיָה רוֹצֶה לְמָכְרָן. וְאָמַר לוֹ רְאוּבֵן מְכֹר אוֹתוֹ לִי בַּחֲמִשִּׁים זוּז שֶׁיֵּשׁ לִי בְּיָדְךָ דְּמֵי הַמֶּכֶר וְאָמַר לוֹ הֵן. קָנָה רְאוּבֵן הַמִּטַּלְטְלִין בְּכָל מָקוֹם שֶׁהֵן וְאַף עַל פִּי שֶׁלֹּא מָשַׁךְ וְלֹא הִגְבִּיהַּ. שֶׁגַּם זֶה דָּבָר שֶׁאֵינוֹ מָצוּי הוּא וְלֹא הִצְרִיכוּ בּוֹ מְשִׁיכָה. אֲבָל אִם הָיָה חוֹב לוֹ עָלָיו שֶׁלֹּא מֵחֲמַת הַמֶּכֶר וְאָמַר לוֹ מְכֹר לִי מִטַּלְטְלִין בַּחוֹב שֶׁיֵּשׁ לִי אֶצְלְךָ וְרָצוּ שְׁנֵיהֶם. לֹא קָנָה עַד שֶׁיַּגְבִּיהַּ. אוֹ יִמְשֹׁךְ דָּבָר שֶׁאֵין דַּרְכּוֹ לְהַגְבִּיהַּ. אוֹ יִקְנֶה בְּאֶחָד מֵהַדְּרָכִים שֶׁהַמִּטַּלְטְלִין נִקְנִין בָּהּ:","הַקַּרְקָעוֹת וְהָעֲבָדִים וְהַבְּהֵמָה וּשְׁאָר כָּל הַמִּטַּלְטְלִין כָּל אֶחָד מֵהֶן נִקְנֶה בַּחֲלִיפִין וְהוּא הַנִּקְרָא קִנְיָן. וְעִקַּר הַדֶּרֶךְ הַזֹּאת שֶׁיִּתֵּן הַקּוֹנֶה לַמַּקְנֶה כְּלִי כָּל שֶׁהוּא וְיֹאמַר לוֹ קְנֵה כְּלִי זֶה חֵלֶף הֶחָצֵר. אוֹ הַיַּיִן. אוֹ הַבְּהֵמָה. אוֹ הָעֶבֶד שֶׁמָּכַרְתָּ לִי בְּכָךְ וְכָךְ. כֵּיוָן שֶׁהִגְבִּיהַּ הַמּוֹכֵר אֶת הַכְּלִי וְקָנָהוּ קָנָה הַלּוֹקֵחַ אוֹתוֹ הַקַּרְקַע אוֹ אוֹתָן הַמִּטַּלְטְלִין אַף עַל פִּי שֶׁעֲדַיִן לֹא מְשָׁכָן וְלֹא נָתַן הַדָּמִים. וְאֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ:","אֵין קוֹנִין אֶלָּא בְּכֵלִים וְאַף עַל פִּי שֶׁאֵין בּוֹ שְׁוֵה פְּרוּטָה. וְאֵין קוֹנִין בְּדָבָר שֶׁאָסוּר בַּהֲנָאָה. וְלֹא בְּפֵרוֹת וְלֹא בְּמַטְבֵּעַ. וְאֵין קוֹנִין בְּכֵלָיו שֶׁל מוֹכֵר אֶלָּא בְּכֵלָיו שֶׁל לוֹקֵחַ:","הִקְנָה אֶחָד כְּלִי לַמּוֹכֵר כְּדֵי שֶׁיִּקְנֶה הַלּוֹקֵחַ אוֹתוֹ הַמִּמְכָּר זָכָה הַלּוֹקֵחַ. וְאַף עַל פִּי שֶׁהִקְנָה לוֹ הַכְּלִי עַל מְנָת לְהַחְזִירוֹ נִקְנָה הַמִּקָּח וְזָכָה בּוֹ הַלּוֹקֵחַ. שֶׁהַמַּתָּנָה עַל מְנָת לְהַחְזִיר שְׁמָהּ מַתָּנָה. אַף עַל פִּי שֶׁלֹּא תָּפַס הַמּוֹכֵר כָּל הַכְּלִי שֶׁהִקְנָהוּ חֵלֶף מִמְכָּרוֹ אֶלָּא אָחַז מִקְצָתוֹ וְאָחַז הַמַּקְנֶה לוֹ מִקְצָתוֹ קָנָה הַלּוֹקֵחַ. וְהוּא שֶׁאָחַז מִמֶּנּוּ כְּדֵי שִׁעוּר כְּלִי אוֹ יֹאחֲזֶנּוּ אֲחִיזָה שֶׁהוּא יָכוֹל לְנַתֵּק אֶת כָּל הַכְּלִי מִיַּד הַמַּקְנֶה לוֹ. לְפִיכָךְ אִם הִקְנָה לוֹ בְּמִקְצָת הַבֶּגֶד צָרִיךְ שֶׁיֶּאֱחֹז מִן הַבֶּגֶד שָׁלֹשׁ אֶצְבָּעוֹת. שֶׁאִם יִפְסֹק מִמָּקוֹם שֶׁאָחַז הֲרֵי הוּא כְּלִי בִּפְנֵי עַצְמוֹ. שֶׁשָּׁלֹשׁ אֶצְבָּעוֹת מִבֶּגֶד קָרוּי כְּלִי כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן טֻמְאַת בְּגָדִים. וְכֵן אִם אָחַז פָּחוֹת מִשָּׁלֹשׁ וְהָיָה יָכוֹל לְנַתֵּק כָּל הַכְּלִי קָנָה:","זֶה שֶׁכּוֹתְבִין בִּשְׁטָרוֹת וְקָנִינָא מִפְּלוֹנִי בִּכְלִי הַכָּשֵׁר לִקְנוֹת בּוֹ. בִּכְלִי לְהוֹצִיא פֵּרוֹת וְכַיּוֹצֵא בָּהֶן. הַכָּשֵׁר לְהוֹצִיא אִסּוּרֵי הֲנָאָה. לִקְנוֹת בּוֹ לְהוֹצִיא כֶּלְיוֹ שֶׁל מוֹכֵר:","זֶה הַקִּנְיָן אֵין צָרִיךְ לִהְיוֹת בִּפְנֵי עֵדִים. אֶלָּא אִם הָיָה בֵּינוֹ וּבֵין חֲבֵרוֹ קָנָה. שֶׁלֹּא הִצְרִיכָה תּוֹרָה עֵדִים בְּדִינֵי מָמוֹנוֹת אֶלָּא לְכוֹפֵר. אֲבָל הַמּוֹכֵר אוֹ הַנּוֹתֵן אוֹ הַשּׂוֹכֵר אוֹ הַמַּשְׁאִיל וְכַיּוֹצֵא בָּהֶן אֵין צָרִיךְ עֵדִים. וְכֵיוָן שֶׁקָּנָה הַקּוֹנֶה בְּדֶרֶךְ אֶחָד מִן הַדְּרָכִים שֶׁקּוֹנִין בָּהֶן. בֵּין בְּהַגְבָּהָה. בֵּין בִּמְשִׁיכָה. בֵּין בִּמְסִירָה. בֵּין בְּקִנְיָן. בֵּין בְּכֶסֶף. בֵּין בִּשְׁטָר אוֹ בַּחֲזָקָה קָנָה. וְאַף עַל פִּי שֶׁאֵין שָׁם עֵדִים:","הַמּוֹכֵר אוֹ הַנּוֹתֵן שֶׁקָּנוּ מִיָּדוֹ יֵשׁ לְכָל אֶחָד מֵהֶן לַחְזֹר בּוֹ כָּל זְמַן שֶׁעוֹסְקִין בְּאוֹתוֹ עִנְיָן. וְאַף עַל פִּי שֶׁהַקִּנְיָן בִּפְנֵי עֵדִים. וְאִם הִפְסִיק הָעִנְיָן אֵין אֶחָד מֵהֶם יָכוֹל לַחְזֹר אַף עַל פִּי שֶׁאֵין בֵּינֵיהֶן עֵדִים. וּכְשֵׁם שֶׁחוֹזֵר הַמּוֹכֵר וְהַנּוֹתֵן כָּךְ חוֹזֵר הַלּוֹקֵחַ וְהַמְקַבֵּל כָּל זְמַן שֶׁעֲסוּקִין בְּאוֹתוֹ עִנְיַן מַה שֶּׁאֵין כֵּן בִּשְׁאָר דַּרְכֵי הַקְּנִיָּה:","יֵשׁ דְּבָרִים הַרְבֵּה שֶׁאֵינָן צְרִיכִין קִנְיָן וְאֵין לְקִנְיָן בָּהֶם טַעַם. כְּגוֹן הַמְשַׁחְרֵר אֶת עַבְדּוֹ. וְהַמְגָרֵשׁ אִשְׁתּוֹ. אוֹ עוֹשֶׂה שָׁלִיחַ. אוֹ הַמּוֹסֵר מוֹדָעָה. אוֹ הַמְבַטֵּל מוֹדָעָה. אוֹ הַמּוֹחֵל לַחֲבֵרוֹ חוֹב אוֹ פִּקָּדוֹן שֶׁיֵּשׁ לוֹ בְּיָדוֹ. וְכָל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ:","נָהֲגוּ רֹב הַמְּקוֹמוֹת לְהַקְנוֹת לְמִקְצָת אֵלּוּ הַדְּבָרִים אוֹ כַּיּוֹצֵא בְּאֵלּוּ. וְאוֹמְרִים וְקָנִינוּ מִפְּלוֹנִי שֶׁעָשָׂה פְּלוֹנִי שָׁלִיחַ. אוֹ שֶׁמָּחַל לִפְלוֹנִי חוֹב שֶׁיֵּשׁ לוֹ אֶצְלוֹ. אוֹ שֶׁבִּטֵּל הַמּוֹדָעָה שֶׁמָּסַר עַל גֵּט זֶה וְכַיּוֹצֵא בְּאֵלּוּ. אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ:","קִנְיָן זֶה שֶׁנָּהֲגוּ לְהַקְנוֹת בְּאֵלּוּ הַדְּבָרִים אֵינוֹ מוֹעִיל כְּלוּם. אֶלָּא לְהוֹדִיעַ שֶׁאֵינוֹ אוֹמֵר דְּבָרִים אֵלּוּ כִּמְשַׂחֵק וּמְהַתֵּל אֶלָּא שֶׁגָּמַר בְּלִבּוֹ וְאַחַר כָּךְ אָמַר. לְפִיכָךְ אִם אָמַר בְּלֵב שָׁלֵם אֲנִי אָמַרְתִּי וְגָמַרְתִּי לַעֲשׂוֹת דָּבָר זֶה אֵין צָרִיךְ דָּבָר אַחֵר כְּלָל:","הַדְּבָרִים שֶׁאֵין בָּהֶן מַמָּשׁ אֵין הַקִּנְיָן מוֹעִיל בָּהֶן. כֵּיצַד. הֲרֵי שֶׁכָּתַב בִּשְׁטָר וְקָנִינוּ מִפְּלוֹנִי שֶׁיֵּלֵךְ בִּסְחוֹרָה עִם פְּלוֹנִי. אוֹ שֶׁיַּחְלְקוּ הַשָּׂדֶה שֶׁבֵּינֵיהֶם. אוֹ שֶׁיִּשְׁתַּתְּפוּ שְׁנֵיהֶם בְּאֻמָּנוּת. וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ כֻּלָּן. הֲרֵי זֶה קִנְיַן דְּבָרִים וְאֵינוֹ מוֹעִיל כְּלוּם. שֶׁהֲרֵי לֹא הִקְנָה לַחֲבֵרוֹ דָּבָר מְסֻיָּם וְיָדוּעַ. לֹא עִקָּר וְלֹא פֵּרוֹת עִקָּר הַיָּדוּעַ:"],"Mishneh Torah, Sanctification of the New Month 16":["הָעֲגֻלָה שֶׁסּוֹבֶבֶת בָּהּ הַיָּרֵחַ תָּמִיד הִיא נוֹטָה מֵעַל הָעֲגֵלָּה שֶׁסּוֹבֶבֶת בָּהּ הַשֶּׁמֶשׁ תָּמִיד. חֶצְיָהּ נוֹטֶה לְצָפוֹן וְחֶצְיָהּ נוֹטֶה לְדָרוֹם. וּשְׁתֵּי נְקֻדּוֹת יֵשׁ בָּהּ זוֹ כְּנֶגֶד זוֹ שֶׁבָּהֶן פּוֹגְעוֹת שְׁתֵּי הָעֲגֻלּוֹת זוֹ בָּזוֹ. לְפִיכָךְ כְּשֶׁיִּהְיֶה הַיָּרֵחַ בְּאַחַת מִשְּׁתֵּיהֶן נִמְצָא סוֹבֵב בְּעִגּוּלָהּ שֶׁל שֶׁמֶשׁ כְּנֶגֶד הַשֶּׁמֶשׁ בְּשָׁוֶה. וְאִם יֵצֵא הַיָּרֵחַ מֵאַחַת מִשְּׁתֵּי הַנְּקֻדּוֹת נִמְצָא מְהַלֵּךְ לִצְפוֹן הַשֶּׁמֶשׁ אוֹ לִדְרוֹמָהּ. הַנְּקֻדָּה שֶׁמִּמֶּנָּה יַתְחִיל הַיָּרֵחַ לִנְטוֹת לִצְפוֹן הַשֶּׁמֶשׁ הִיא הַנִּקְרֵאת רֹאשׁ. וְהַנְּקֻדָּה שֶׁמִּמֶּנָּה יַתְחִיל הַיָּרֵחַ לִנְטוֹת לִדְרוֹם הַשֶּׁמֶשׁ הִיא הַנִּקְרֵאת זָנָב. וּמַהֲלָךְ שָׁוֶה יֵשׁ לְזֶה הָרֹאשׁ שֶׁאֵין בּוֹ לֹא תּוֹסֶפֶת וְלֹא גֵּרָעוֹן. וְהוּא הוֹלֵךְ בַּמַּזָּלוֹת אֲחוֹרַנִּית מִטָּלֶה לְדָגִים וּמִדָּגִים לִדְלִי וְכֵן הוּא סוֹבֵב תָּמִיד:","מַהֲלַךְ הָרֹאשׁ הָאֶמְצָעִי בְּיוֹם אֶחָד ג' חֲלָקִים וְי\"א שְׁנִיּוֹת. נִמְצָא מַהֲלָכוֹ בְּי' יָמִים ל\"א חֲלָקִים וּמ\"ז שְׁנִיּוֹת. וְנִמְצָא מַהֲלָכוֹ בְּק' יוֹם ה' מַעֲלוֹת וְי\"ז חֲלָקִים וּמ\"ג שְׁנִיּוֹת. סִימָנָם הי\"ז מ\"ג. וְנִמְצָא מַהֲלָכוֹ בְּאֶלֶף יוֹם נ\"ב מַעֲלוֹת וְנ\"ז חֲלָקִים וְי' שְׁנִיּוֹת. סִימָנָם נ\"ב נז\"י. וְנִמְצָא שְׁאֵרִית מַהֲלָכוֹ בַּעֲשֶׂרֶת אֲלָפִים יוֹם קס\"ט מַעֲלוֹת וְל\"א חֲלָקִים וּמ' שְׁנִיּוֹת. סִימָנָם קס\"ט לא\"מ. וְנִמְצָא מַהֲלָכוֹ לְכ\"ט יוֹם מַעֲלָה אַחַת וְל\"ב חֲלָקִים וְט' שְׁנִיּוֹת. סִימָנָם א' לב\"ט. וְנִמְצָא מַהֲלָכוֹ לְשָׁנָה סְדוּרָה י\"ח מַעֲלוֹת וּמ\"ד חֲלָקִים וּמ\"ב שְׁנִיּוֹת. סִימָנָם י\"ח מ\"ד מ\"ב. וְאֶמְצַע הָרֹאשׁ בִּתְחִלַּת לֵיל ה' שֶׁהוּא הָעִקָּר הָיָה ק\"פ מַעֲלוֹת וְנ\"ז חֲלָקִים וְכ\"ח שְׁנִיּוֹת. סִימָנָם ק\"פ נ\"ז כ\"ח:","אִם תִּרְצֶה לֵידַע מְקוֹם הָרֹאשׁ בְּכָל עֵת שֶׁתִּרְצֶה. תּוֹצִיא אֶמְצָעָם לְאוֹתוֹ הָעֵת כְּדֶרֶךְ שֶׁתּוֹצִיא אֶמְצַע הַשֶּׁמֶשׁ וְאֶמְצַע הַיָּרֵחַ. וְתִגְרַע הָאֶמְצַע מִש\"ס מַעֲלוֹת. וְהַנִּשְׁאָר הוּא מְקוֹם הָרֹאשׁ בְּאוֹתָהּ הָעֵת. וּכְנֶגְדּוֹ לְעוֹלָם יִהְיֶה מְקוֹם הַזָּנָב:","כֵּיצַד. הֲרֵי שֶׁרָצִינוּ לֵידַע מְקוֹם הָרֹאשׁ לִתְחִלַּת לֵיל עֶרֶב שַׁבָּת שֶׁיּוֹמוֹ שֵׁנִי לְחֹדֶשׁ אִיָּר מִשָּׁנָה זוֹ שֶׁהִיא שְׁנַת הָעִקָּר. וּמִנְיַן הַיָּמִים הַגְּמוּרִים מִתְּחִלַּת לֵיל הָעִקָּר עַד תְּחִלַּת לַיִל זוֹ שֶׁאָנוּ רוֹצִים לֵידַע מְקוֹם הָרֹאשׁ בּוֹ כ\"ט יוֹם:","תּוֹצִיא אֶמְצַע הָרֹאשׁ לָעֵת הַזֹּאת עַל הַדֶּרֶךְ שֶׁיָּדַעְתָּ. וְהוּא שֶׁתּוֹסִיף מַהֲלָכוֹ לְכ\"ט יוֹם עַל הָעִקָּר. יֵצֵא לְךָ אֶמְצַע הָרֹאשׁ קפ\"ב מַעֲלוֹת וְכ\"ט חֲלָקִים וְל\"ז שְׁנִיּוֹת. סִימָנָם קפ\"ב כ\"ט ל\"ז. תִּגְרַע אֶמְצַע זֶה מִש\"ס יִשָּׁאֵר לְךָ קע\"ז מַעֲלוֹת וְל' חֲלָקִים וְכ\"ג שְׁנִיּוֹת. סִימָנָם קע\"ז לִכְ\"ג. וְזֶה הוּא מְקוֹם הָרֹאשׁ. וְאַל תִּפְנֶה אֶל הַשְּׁנִיּוֹת. נִמְצָא מְקוֹם הָרֹאשׁ בְּמַזַּל בְּתוּלָה בְּכ\"ז מַעֲלוֹת וְל' חֲלָקִים. וּמְקוֹם הַזָּנָב כְּנֶגְדּוֹ בְּמַזַּל דָּגִים בְּכ\"ז מַעֲלוֹת וּשְׁלֹשִׁים חֲלָקִים:","לְעוֹלָם יִהְיֶה בֵּין הָרֹאשׁ וּבֵין הַזָּנָב חֲצִי הַגַּלְגַּל בְּשָׁוֶה. לְפִיכָךְ כָּל מַזָּל שֶׁתִּמְצָא בּוֹ מְקוֹם הָרֹאשׁ יִהְיֶה הַזָּנָב בְּמַזַּל ז' מִמֶּנּוּ בִּכְמוֹ מִנְיַן הַמַּעֲלוֹת וְהַחֲלָקִים בְּשָׁוֶה. אִם יִהְיֶה הָרֹאשׁ בְּי' מַעֲלוֹת בְּמַזַּל פְּלוֹנִי יִהְיֶה הַזָּנָב בְּי' מַעֲלוֹת מִמַּזַּל ז' מִמֶּנּוּ:","וּמֵאַחַר שֶׁתֵּדַע מְקוֹם הָרֹאשׁ וּמְקוֹם הַזָּנָב וּמְקוֹם הַיָּרֵחַ הָאֲמִתִּי. הִתְבּוֹנֵן בִּשְׁלָשְׁתָּן. אִם מָצָאתָ הַיָּרֵחַ עִם הָרֹאשׁ אוֹ עִם הַזָּנָב בְּמַעֲלָה אַחַת בְּחֵלֶק אֶחָד. תֵּדַע שֶׁאֵין הַיָּרֵחַ נוֹטֶה לֹא לִצְפוֹן הַשֶּׁמֶשׁ וְלֹא לִדְרוֹמָהּ. וְאִם רָאִיתָ מְקוֹם הַיָּרֵחַ לִפְנֵי מְקוֹם הָרֹאשׁ וְהוּא הוֹלֵךְ כְּנֶגֶד הַזָּנָב. תֵּדַע שֶׁהַיָּרֵחַ נוֹטֶה לִצְפוֹן הַשֶּׁמֶשׁ. וְאִם הָיָה הַיָּרֵחַ לִפְנֵי מְקוֹם הַזָּנָב וַהֲרֵי הוּא הוֹלֵךְ כְּנֶגֶד הָרֹאשׁ. תֵּדַע שֶׁהַיָּרֵחַ נוֹטֶה לִדְרוֹם הַשֶּׁמֶשׁ:","הַנְּטִיָּה שֶׁנּוֹטֶה הַיָּרֵחַ לִצְפוֹן הַשֶּׁמֶשׁ אוֹ לִדְרוֹמָהּ. הִיא הַנִּקְרֵאת רֹחַב הַיָּרֵחַ. וְאִם הָיָה נוֹטֶה לַצָּפוֹן נִקְרָא רֹחַב צְפוֹנִי. וְאִם הָיָה נוֹטֶה לַדָּרוֹם נִקְרָא רֹחַב דְּרוֹמִי. וְאִם הָיָה הַיָּרֵחַ בְּאַחַת מִשְּׁתֵּי הַנְּקֻדּוֹת לֹא יִהְיֶה לוֹ רֹחַב כְּמוֹ שֶׁבֵּאַרְנוּ:","לְעוֹלָם לֹא יִהְיֶה רֹחַב הַיָּרֵחַ יֶתֶר עַל ה' מַעֲלוֹת בֵּין בַּצָּפוֹן בֵּין בַּדָּרוֹם. אֶלָּא כָּךְ הוּא דַּרְכּוֹ יַתְחִיל מִן הָרֹאשׁ וְיִתְרַחֵק מִמֶּנּוּ מְעַט מְעַט. וְהַמֶּרְחָק הוֹלֵךְ וְנוֹסָף עַד שֶׁיַּגִּיעַ לְחָמֵשׁ מַעֲלוֹת. וְיַחֲזֹר וְיִתְקָרֵב מְעַט מְעַט עַד שֶׁלֹּא יִהְיֶה לוֹ רֹחַב כְּשֶׁיַּגִּיעַ לַזָּנָב. וְיַחֲזֹר וְיִתְרַחֵק מְעַט מְעַט וְהַמֶּרְחָק נוֹסָף עַד שֶׁיַּגִּיעַ לְחָמֵשׁ מַעֲלוֹת. וְיַחֲזֹר וְיִתְקָרֵב עַד שֶׁלֹּא יִהְיֶה לוֹ רֹחַב:","אִם תִּרְצֶה לֵידַע רֹחַב הַיָּרֵחַ כַּמָּה הוּא בְּכָל עֵת שֶׁתִּרְצֶה. וְאִם צְפוֹנִי הוּא אוֹ דְּרוֹמִי. תּוֹצִיא מְקוֹם הָרֹאשׁ וּמְקוֹם הַיָּרֵחַ הָאֲמִתִּי לְאוֹתָהּ הָעֵת. וְתִגְרַע מְקוֹם הָרֹאשׁ מִמְּקוֹם הַיָּרֵחַ הָאֲמִתִּי. וְהַנִּשְׁאָר הוּא הַנִּקְרָא מַסְלוּל הָרֹחַב. וְאִם יִהְיֶה מַסְלוּל הָרֹחַב מִמַּעֲלָה אַחַת עַד ק\"פ. תֵּדַע שֶׁרֹחַב הַיָּרֵחַ צְפוֹנִי. וְאִם הָיָה הַמַּסְלוּל יֶתֶר עַל ק\"פ תֵּדַע שֶׁרֹחַב הַיָּרֵחַ דְּרוֹמִי. וְאִם הָיָה ק\"פ בְּשָׁוֶה אוֹ ש\"ס בְּשָׁוֶה אֵין לַיָּרֵחַ רֹחַב כְּלָל. וְתַחֲזֹר וְתִרְאֶה מְנַת מַסְלוּל הָרֹחַב כַּמָּה הִיא. וְהוּא שִׁעוּר נְטִיָּתוֹ לַצָּפוֹן אוֹ לַדָּרוֹם. וְהוּא הַנִּקְרָא רֹחַב הַיָּרֵחַ הַדְּרוֹמִי אוֹ הַצְּפוֹנִי כְּמוֹ שֶׁבֵּאַרְנוּ:","וְכַמָּה הִיא מְנַת מַסְלוּל הָרֹחַב. אִם יִהְיֶה מַסְלוּל הָרֹחַב עֶשֶׂר מַעֲלוֹת תִּהְיֶה מְנָתוֹ נ\"ב חֲלָקִים. וְאִם יִהְיֶה הַמַּסְלוּל הַזֶּה כ' מַעֲלוֹת תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וּמ\"ג חֲלָקִים. וְאִם יִהְיֶה הַמַּסְלוּל ל' תִּהְיֶה מְנָתוֹ שְׁתֵּי מַעֲלוֹת וְל' חֲלָקִים. וְאִם יִהְיֶה הַמַּסְלוּל מ' תִּהְיֶה מְנָתוֹ שָׁלֹשׁ מַעֲלוֹת וְי\"ג חֲלָקִים. וְאִם יִהְיֶה הַמַּסְלוּל נ' מַעֲלוֹת תִּהְיֶה מְנָתוֹ שָׁלֹשׁ מַעֲלוֹת וְנ' חֲלָקִים. וְאִם יִהְיֶה הַמַּסְלוּל ס' תִּהְיֶה מְנָתוֹ אַרְבַּע מַעֲלוֹת וְכ' חֲלָקִים. וְאִם יִהְיֶה הַמַּסְלוּל ע' תִּהְיֶה מְנָתוֹ ד' מַעֲלוֹת וּמ\"ב חֲלָקִים. וְאִם יִהְיֶה הַמַּסְלוּל פ' תִּהְיֶה מְנָתוֹ ד' מַעֲלוֹת וְנ\"ה חֲלָקִים. וְאִם יִהְיֶה הַמַּסְלוּל צ' תִּהְיֶה מְנָתוֹ ה' מַעֲלוֹת:","וְאִם יִהְיוּ אֲחָדִים עִם הָעֲשָׂרוֹת תִּקַּח הָרָאוּי לָהֶם לְפִי הַיֶּתֶר שֶׁבֵּין שְׁתֵּי הַמָּנוֹת כְּמוֹ שֶׁעָשִׂיתָ בְּמַסְלוּל הַשֶּׁמֶשׁ וּבְמַסְלוּל הַיָּרֵחַ. כֵּיצַד. הֲרֵי שֶׁהָיָה מַסְלוּל הָרֹחַב נ\"ג מַעֲלוֹת. וּכְבָר יָדַעְתָּ שֶׁאִלּוּ הָיָה הַמַּסְלוּל נ' הָיְתָה מְנָתוֹ שָׁלֹשׁ מַעֲלוֹת וְנ' חֲלָקִים. וְאִלּוּ הָיָה הַמַּסְלוּל ס' הָיְתָה מְנָתוֹ ד' מַעֲלוֹת וְכ' חֲלָקִים. נִמְצָא הַיֶּתֶר בֵּין שְׁתֵּי הַמָּנוֹת ל' חֲלָקִים ג' חֲלָקִים לְכָל מַעֲלָה. וְנִמְצָא לְפִי חֶשְׁבּוֹן מַסְלוּל זֶה שֶׁהוּא נ\"ג שָׁלֹשׁ מַעֲלוֹת וְנ\"ט חֲלָקִים. וְעַל דֶּרֶךְ זוֹ תַּעֲשֶׂה בְּכָל מִנְיָן וּמִנְיָן:","מֵאַחַר שֶׁתֵּדַע מְנָתוֹ שֶׁל מַסְלוּל הָרֹחַב עַד צ' כְּמוֹ שֶׁהוֹדַעְנוּךָ. תֵּדַע מָנוֹת שֶׁל כָּל מִנְיְנוֹת הַמַּסְלוּל. שֶׁאִם יִהְיֶה הַמַּסְלוּל יֶתֶר עַל צ' עַד ק\"פ תִּגְרַע הַמַּסְלוּל מִק\"פ וְהַנִּשְׁאָר תֵּדַע בּוֹ הַמָּנָה:","וְזֶה הוּא רֹחַב הַיָּרֵחַ בִּתְחִלַּת לַיִל זֶה. וְהוּא דְּרוֹמִי שֶׁהֲרֵי הַמַּסְלוּל יֶתֶר עַל ק\"פ. וְכֵן אִם הָיָה הַמַּסְלוּל יֶתֶר מִק\"פ עַד ר\"ע תִּגְרַע מִמֶּנּוּ ק\"פ וְהַנִּשְׁאָר תֵּדַע בּוֹ הַמָּנָה:","וְאִם הָיָה הַמַּסְלוּל יֶתֶר עַל ר\"ע עַד ש\"ס. תִּגְרַע אוֹתוֹ מִש\"ס וְהַנִּשְׁאָר תֵּדַע בּוֹ הַמָּנָה:","כֵּיצַד. הֲרֵי שֶׁהָיָה הַמַּסְלוּל ק\"נ תִּגְרַע אוֹתוֹ מִק\"פ נִשְׁאָר ל'. וּכְבָר יָדַעְתָּ שֶׁמְּנַת שְׁלֹשִׁים שְׁתֵּי מַעֲלוֹת וּשְׁלֹשִׁים חֲלָקִים וְכָךְ תִּהְיֶה מְנַת ק\"נ שְׁתֵּי מַעֲלוֹת וּשְׁלֹשִׁים חֲלָקִים:","הֲרֵי שֶׁהָיָה הַמַּסְלוּל ר'. תִּגְרַע מִמֶּנּוּ ק\"פ יִשָּׁאֵר כ'. וּכְבָר יָדַעְתָּ שֶׁמְּנַת כ' הִיא מַעֲלָה אַחַת וּמ\"ג חֲלָקִים. וְכֵן אִם תִּהְיֶה מְנַת ר' תִּהְיֶה מַעֲלָה אַחַת וּמ\"ג חֲלָקִים:","הֲרֵי שֶׁהָיָה הַמַּסְלוּל ש' תִּגְרַע אוֹתוֹ מִש\"ס נִשְׁאַר ס'. וּכְבָר יָדַעְתָּ שֶׁמְּנַת שִׁשִּׁים אַרְבַּע מַעֲלוֹת וְכ' חֲלָקִים. וְכָךְ הִיא מְנַת ש' ד' מַעֲלוֹת וְכ' חֲלָקִים. וְעַל דֶּרֶךְ זוֹ בְּכָל הַמִּנְיָנוֹת:","הֲרֵי שֶׁרָצִינוּ לֵידַע רֹחַב הַיָּרֵחַ כַּמָּה הוּא וּבְאֵיזוֹ רוּחַ הוּא אִם צְפוֹנִי אוֹ דְּרוֹמִי בִּתְחִלַּת לֵיל עֶרֶב שַׁבָּת שֵׁנִי לְחֹדֶשׁ אִיָּר מִשָּׁנָה זוֹ. וּכְבָר יָדַעְתָּ שֶׁמְּקוֹם הַיָּרֵחַ הָאֲמִתִּי הָיָה בְּלַיִל זֶה בְּי\"ח מַעֲלוֹת וְל\"ו חֲלָקִים מִמַּזַּל שׁוֹר. סִימָנוֹ י\"ח ל\"ו. וּמְקוֹם הָרֹאשׁ הָיָה בְּאוֹתָהּ הָעֵת בְּכ\"ז מַעֲלוֹת וְל' חֲלָקִים מִמַּזַּל בְּתוּלָה. סִימָנוֹ כז\"ל. תִּגְרַע מְקוֹם הָרֹאשׁ מִמְּקוֹם הַיָּרֵחַ. יֵצֵא לְךָ מַסְלוּל הָרֹחַב רל\"א מַעֲלוֹת ו' חֲלָקִים. סִימָנוֹ רל\"א ו'. לְפִי שֶׁאֵין מַשְׁגִּיחִין עַל הַחֲלָקִים בְּכָל הַמַּסְלוּל. וְנִמְצֵאת הַמָּנָה שֶׁל מַסְלוּל זֶה בַּדְּרָכִים שֶׁבֵּאַרְנוּ בְּפֶרֶק זֶה שָׁלֹשׁ מַעֲלוֹת וְנ\"ג חֲלָקִים. וְזֶהוּ רֹחַב הַיָּרֵחַ בִּתְחִלַּת לַיִל זֶה. וְהוּא דְּרוֹמִי שֶׁהֲרֵי הַמַּסְלוּל יֶתֶר עַל ק\"פ:"],"Mishneh Torah, Scroll of Esther and Hanukkah 1":["קְרִיאַת הַמְּגִלָּה בִּזְמַנָּהּ מִצְוַת עֲשֵׂה מִדִּבְרֵי סוֹפְרִים. וְהַדְּבָרִים יְדוּעִים שֶׁהִיא תַּקָּנַת הַנְּבִיאִים. וְהַכּל חַיָּבִים בִּקְרִיאָתָהּ אֲנָשִׁים וְנָשִׁים וְגֵרִים וַעֲבָדִים מְשֻׁחְרָרִים. וּמְחַנְּכִין אֶת הַקְּטַנִּים לִקְרוֹתָהּ. וַאֲפִלּוּ כֹּהֲנִים בַּעֲבוֹדָתָן מְבַטְּלִין עֲבוֹדָתָן וּבָאִין לִשְׁמֹעַ מִקְרָא מְגִלָּה. וְכֵן מְבַטְּלִים תַּלְמוּד תּוֹרָה לִשְׁמֹעַ מִקְרָא מְגִלָּה קַל וָחֹמֶר לִשְׁאָר מִצְוֹת שֶׁל תּוֹרָה שֶׁכֻּלָּן נִדְחִין מִפְּנֵי מִקְרָא מְגִלָּה. וְאֵין לְךָ דָּבָר שֶׁנִּדְחֶה מִקְרָא מְגִלָּה מִפָּנָיו חוּץ מִמֵּת מִצְוָה שֶׁאֵין לוֹ קוֹבְרִין שֶׁהַפּוֹגֵעַ בּוֹ קוֹבְרוֹ תְּחִלָּה וְאַחַר כָּךְ קוֹרֵא:","אֶחָד הַקּוֹרֵא וְאֶחָד הַשּׁוֹמֵעַ מִן הַקּוֹרֵא יָצָא יְדֵי חוֹבָתוֹ וְהוּא שֶׁיִּשְׁמַע מִפִּי מִי שֶׁהוּא חַיָּב בִּקְרִיאָתָהּ. לְפִיכָךְ אִם הָיָה הַקּוֹרֵא קָטָן אוֹ שׁוֹטֶה הַשּׁוֹמֵעַ מִמֶּנּוּ לֹא יָצָא:","מִצְוָה לִקְרוֹת אֶת כֻּלָּהּ. וּמִצְוָה לִקְרוֹתָהּ בַּלַּיְלָה וּבַיּוֹם. וְכָל הַלַּיְלָה כָּשֵׁר לִקְרִיאַת הַלַּיְלָה. וְכָל הַיּוֹם כָּשֵׁר לִקְרִיאַת הַיּוֹם. וּמְבָרֵךְ קֹדֶם קְרִיאָתָהּ בַּלַּיְלָה שָׁלֹשׁ בְּרָכוֹת וְאֵלּוּ הֵן. בָּרוּךְ אַתָּה ה' אֱלֹקֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל מִקְרָא מְגִלָּה. בָּרוּךְ אַתָּה ה' אֱלֹקֵינוּ מֶלֶךְ הָעוֹלָם שֶׁעָשָׂה נִסִּים לַאֲבוֹתֵינוּ בַּיָּמִים הָהֵם וּבַזְּמַן הַזֶּה. בָּרוּךְ אַתָּה ה' אֱלֹקֵינוּ מֶלֶךְ הָעוֹלָם שֶׁהֶחֱיָנוּ וְקִיְּמָנוּ וְהִגִּיעָנוּ לַזְּמַן הַזֶּה. וּבַיּוֹם אֵינוֹ חוֹזֵר וּמְבָרֵךְ שֶׁהֶחֱיָנוּ. וּמָקוֹם שֶׁנָּהֲגוּ לְבָרֵךְ אַחֲרֶיהָ מְבָרֵךְ בָּרוּךְ אַתָּה ה' אֱלֹקֵינוּ מֶלֶךְ הָעוֹלָם הָאֵל הָרָב אֶת רִיבֵנוּ וְהַדָּן אֶת דִּינֵנוּ וְהַנּוֹקֵם אֶת נִקְמָתֵנוּ וְהַנִּפְרָע לָנוּ מִצָּרֵינוּ וְהַמְשַׁלֵּם גְּמוּל לְכָל אֹיְבֵי נַפְשֵׁנוּ בָּרוּךְ אַתָּה ה' הַנִּפְרָע לְיִשְׂרָאֵל מִכָּל צָרֵיהֶם הָאֵל הַמּוֹשִׁיעַ:","אֵיזֶהוּ זְמַן קְרִיאָתָהּ. זְמַנִּים הַרְבֵּה תִּקְּנוּ לָהּ חֲכָמִים שֶׁנֶּאֱמַר (אסתר ט לא) \"בִּזְמַנֵּיהֶם\". וְאֵלּוּ הֵן זְמַנֵּי קְרִיאָתָהּ. כָּל מְדִינָה שֶׁהָיְתָה מֻקֶּפֶת חוֹמָה מִימֵי יְהוֹשֻׁעַ בִּן נוּן בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ אַף עַל פִּי שֶׁאֵין לָהּ עַכְשָׁו חוֹמָה קוֹרִין בְּט\"ו בַּאֲדָר. וּמְדִינָה זוֹ הִיא הַנִּקְרֵאת כְּרַךְ. וְכָל מְדִינָה שֶׁלֹּא הָיְתָה מֻקֶּפֶת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ וְאַף עַל פִּי שֶׁהִיא מֻקֶּפֶת עַתָּה קוֹרְאִין בְּי\"ד. וּמְדִינָה זוֹ הִיא הַנִּקְרֵאת עִיר:","שׁוּשַׁן הַבִּירָה אַף עַל פִּי שֶׁלֹּא הָיְתָה מֻקֶּפֶת חוֹמָה בִּימֵי יְהוֹשֻׁעַ בִּן נוּן קוֹרְאִין בְּט\"ו שֶׁבָּהּ הָיָה הַנֵּס שֶׁנֶּאֱמַר (אסתר ט יח) \"וְנוֹחַ בַּחֲמִשָּׁה עָשָׂר בּוֹ\". וְלָמָּה תָּלוּ הַדָּבָר בִּימֵי יְהוֹשֻׁעַ כְּדֵי לַחֲלֹק כָּבוֹד לְאֶרֶץ יִשְׂרָאֵל שֶׁהָיְתָה חֲרֵבָה בְּאוֹתוֹ הַזְּמַן. כְּדֵי שֶׁיִּהְיוּ קוֹרְאִין כִּבְנֵי שׁוּשָׁן וְיֵחָשְׁבוּ כְּאִלּוּ הֵן כְּרַכִּין הַמֻּקָּפִין חוֹמָה אַף עַל פִּי שֶׁהֵן עַתָּה חֲרֵבִין הוֹאִיל וְהָיוּ מֻקָּפִין בִּימֵי יְהוֹשֻׁעַ קוֹרִין בְּט\"ו וְיִהְיֶה זִכָּרוֹן לְאֶרֶץ יִשְׂרָאֵל בְּנֵס זֶה:","בְּנֵי הַכְּפָרִים שֶׁאֵינָם מִתְקַבְּצִים בְּבָתֵּי כְּנֵסִיּוֹת אֶלָּא בְּשֵׁנִי וּבַחֲמִישִׁי תִּקְּנוּ לָהֶם שֶׁיִּהְיוּ מַקְדִּימִין וְקוֹרְאִים בְּיוֹם הַכְּנִיסָה. כֵּיצַד. אִם חָל יוֹם י\"ד לִהְיוֹת בְּשֵׁנִי אוֹ בַּחֲמִישִׁי קוֹרְאִין בּוֹ בַּיּוֹם. וְאִם חָל בְּיוֹם אַחֵר חוּץ מִשֵּׁנִי וַחֲמִישִׁי מַקְדִּימִין וְקוֹרְאִין בְּשֵׁנִי אוֹ בַּחֲמִישִׁי הַסָּמוּךְ לְי\"ד:","כֵּיצַד. חָל י\"ד לִהְיוֹת בְּאֶחָד בְּשַׁבָּת מַקְדִּימִין וְקוֹרְאִין בַּחֲמִישִׁי שֶׁהוּא יוֹם י\"א. חָל לִהְיוֹת בִּשְׁלִישִׁי קוֹרְאִין בְּשֵׁנִי שֶׁהוּא יוֹם י\"ג. חָל לִהְיוֹת בִּרְבִיעִי קוֹרְאִין בְּשֵׁנִי שֶׁהוּא יוֹם י\"ב. וְכָל אֵלּוּ שֶׁמַּקְדִּימִין וְקוֹרְאִין קֹדֶם י\"ד אֵין קוֹרְאִין אוֹתָהּ בְּפָחוֹת מֵעֲשָׂרָה:","כְּפָר שֶׁמַּקְדִּימִין וְקוֹרְאִין בְּיוֹם הַכְּנִיסָה בִּזְמַן שֶׁאֵין נִכְנָסִין בּוֹ בְּשֵׁנִי וּבַחֲמִישִׁי אֵין קוֹרְאִין אוֹתָהּ אֶלָּא בְּי\"ד. וְכָל עִיר שֶׁאֵין בָּהּ עֲשָׂרָה בַּטְלָנִין קְבוּעִין בְּבֵית הַכְּנֶסֶת לְצָרְכֵי הַצִּבּוּר הֲרֵי הִיא כִּכְפָר וּמַקְדִּימִין וְקוֹרְאִין בְּיוֹם הַכְּנִיסָה. וְאִם אֵין שָׁם עֲשָׂרָה בְּנֵי אָדָם תַּקָּנָתוֹ קַלְקָלָתוֹ וַהֲרֵי הֵם כְּאַנְשֵׁי עִיר גְּדוֹלָה וְאֵין קוֹרְאִין אֶלָּא בְּי\"ד:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמַּקְדִּימִין וְקוֹרְאִין בְּיוֹם הַכְּנִיסָה בִּזְמַן שֶׁיֵּשׁ לָהֶם לְיִשְׂרָאֵל מַלְכוּת. אֲבָל בַּזְּמַן הַזֶּה אֵין קוֹרְאִין אוֹתָהּ אֶלָּא בִּזְמַנָּהּ שֶׁהוּא יוֹם י\"ד וְיוֹם ט\"ו. בְּנֵי הַכְּפָרִים וּבְנֵי עֲיָרוֹת קוֹרְאִין בְּי\"ד. וּבְנֵי כְּרַכִּין קוֹרְאִין בְּט\"ו:","בֶּן עִיר שֶׁהָלַךְ לַכְּרַךְ אוֹ בֶּן כְּרַךְ שֶׁהָלַךְ לָעִיר אִם הָיָה דַּעְתּוֹ לַחֲזֹר לִמְקוֹמוֹ בִּזְמַן קְרִיאָה וְנִתְעַכֵּב וְלֹא חָזַר קוֹרֵא כִּמְקוֹמוֹ. וְאִם לֹא הָיָה בְּדַעְתּוֹ לַחֲזֹר אֶלָּא לְאַחַר זְמַן הַקְּרִיאָה קוֹרֵא עִם אַנְשֵׁי הַמָּקוֹם שֶׁהוּא שָׁם. וּכְרַךְ וְכָל הַסָּמוּךְ לוֹ וְכָל הַנִּרְאֶה עִמּוֹ אִם אֵין בֵּינֵיהֶם יֶתֶר עַל אַלְפַּיִם אַמָּה הֲרֵי זֶה כִּכְרַךְ וְקוֹרְאִין בַּחֲמִשָּׁה עָשָׂר:","עִיר שֶׁהִיא סָפֵק וְאֵין יָדוּעַ אִם הָיְתָה מֻקֶּפֶת חוֹמָה בִּימוֹת יְהוֹשֻׁעַ בִּן נוּן אוֹ אַחַר כֵּן הֻקְּפָה קוֹרְאִין בִּשְׁנֵי הַיָּמִים שֶׁהֵן י\"ד וְט\"ו וּבְלֵילֵיהֶם. וּמְבָרְכִין עַל קְרִיאָתָהּ בְּי\"ד בִּלְבַד הוֹאִיל וְהוּא זְמַן קְרִיאָתָהּ לְרֹב הָעוֹלָם:","קָרְאוּ אֶת הַמְּגִלָּה בַּאֲדָר רִאשׁוֹן וְאַחַר כָּךְ עִבְּרוּ בֵּית דִּין אֶת הַשָּׁנָה חוֹזְרִים וְקוֹרְאִים אוֹתָהּ בָּאֲדָר הַשֵּׁנִי בִּזְמַנָּהּ:","אֵין קוֹרְאִין אֶת הַמְּגִלָּה בְּשַׁבָּת גְּזֵרָה שֶׁמָּא יִטּל אוֹתָהּ בְּיָדוֹ וְיֵלֵךְ אֵצֶל מִי שֶׁהוּא בָּקִי לִקְרוֹתָהּ וְיַעֲבִירֶנָּה אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים. שֶׁהַכּל חַיָּבִים בִּקְרִיאָתָהּ וְאֵין הַכּל בְּקִיאִין בִּקְרִיאָתָהּ. לְפִיכָךְ אִם חָל זְמַן קְרִיאָתָהּ בְּשַׁבָּת מַקְדִּימִין וְקוֹרְאִין אוֹתָהּ קֹדֶם הַשַּׁבָּת. וְשׁוֹאֲלִין וְדוֹרְשִׁין בְּהִלְכוֹת פּוּרִים בְּאוֹתָהּ שַׁבָּת כְּדֵי לְהַזְכִּיר שֶׁהוּא פּוּרִים:","כֵּיצַד. יוֹם אַרְבָּעָה עָשָׂר שֶׁחָל לִהְיוֹת בְּשַׁבָּת בְּנֵי עֲיָרוֹת מַקְדִּימִין וְקוֹרְאִין בְּעֶרֶב שַׁבָּת וּבְנֵי כְּרַכִּים קוֹרְאִים בִּזְמַנָּם בְּאֶחָד בְּשַׁבָּת. חָל יוֹם ט\"ו לִהְיוֹת בְּשַׁבָּת בְּנֵי כְּרַכִּים מַקְדִּימִין וְקוֹרְאִין בְּעֶרֶב שַׁבָּת שֶׁהוּא יוֹם אַרְבָּעָה עָשָׂר וּבְנֵי עֲיָרוֹת קוֹרְאִין בּוֹ בַּיּוֹם שֶׁהוּא זְמַנָּם וְנִמְצְאוּ הַכּל קוֹרְאִין בְּאַרְבָּעָה עָשָׂר:"],"Mishneh Torah, Second Tithes and Fourth Year's Fruit 7":["פֵּרוֹת הַנִּלְקָחוֹת בְּכֶסֶף מַעֲשֵׂר שֵׁנִי אֵינָן נִפְדִּין בְּרִחוּק מָקוֹם אֶלָּא אִם כֵּן נִטְמְאוּ בְּאַב הַטֻּמְאָה אֶלָּא יַעֲלוּ הֵן עַצְמָן וְיֵאָכְלוּ בִּירוּשָׁלַיִם:","זֶה חֹמֶר בְּלָקוּחַ בְּכֶסֶף מַעֲשֵׂר מִפֵּרוֹת מַעֲשֵׂר עַצְמָן. וְאִם נִטְמָא בִּוְלַד הַטֻּמְאָה מִדִּבְרֵיהֶם יִפָּדוּ וְיֵאָכְלוּ בִּירוּשָׁלַיִם:","אֵין נִלְקָח בְּכֶסֶף מַעֲשֵׂר אֶלָּא מַאֲכַל אָדָם שֶׁגִּדּוּלָיו מִן הָאָרֶץ. אוֹ גִּדּוּלֵי גִּדּוּלָיו מִן הָאָרֶץ. כְּגוֹן הַפְּרָט הַמְפֹרָשׁ בַּתּוֹרָה (דברים יד כו) \"בַּבָּקָר וּבַצֹּאן וּבַיַּיִן וּבַשֵּׁכָר\":","לְפִיכָךְ אֵין לוֹקְחִין בְּכֶסֶף מַעֲשֵׂר מַיִם וּמֶלַח כְּמֵהִין וּפִטְרִיּוֹת לְפִי שֶׁאֵין גִּדּוּלֵיהֶם מִן הָאָרֶץ. וְלֹא פֵּרוֹת מְחֻבָּרִין לַקַּרְקַע. וְלֹא פֵּרוֹת שֶׁאֵינָן יְכוֹלִים לְהַגִּיעַ לִירוּשָׁלַיִם. לְפִי שֶׁאֵינָן דּוֹמִין לְבָקָר וָצֹאן:","הַדְּבַשׁ וְהַבֵּיצִים וְהֶחָלָב הֲרֵי הֵן כְּבָקָר וָצֹאן שֶׁאַף עַל פִּי שֶׁאֵינָן גִּדּוּלֵי קַרְקַע הֲרֵי הֵן גִּדּוּלֵי גִּדּוּלֶיהָ:","הַתֶּמֶד עַד שֶׁלֹּא הֶחְמִיץ אֵינוֹ נִלְקָח בְּכֶסֶף מַעֲשֵׂר מִפְּנֵי שֶׁהוּא כְּמַיִם. וּמִשֶּׁהֶחְמִיץ נִלְקָח כַּיַּיִן וּכְשֵׁכָר. לְקָחוֹ עַד שֶׁלֹּא הֶחְמִיץ וְהֶחֱמִיץ קָנָה מַעֲשֵׂר:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּנָתַן שְׁלֹשָׁה מַיִם וּמָצָא פָּחוֹת מֵאַרְבָּעָה. אֲבָל אִם נָתַן שְׁלֹשָׁה וְהוֹצִיא אַרְבָּעָה הֲרֵי זֶה כְּיַיִן מָזוּג וְנִלְקָח בְּכֶסֶף מַעֲשֵׂר:","לוּלְבֵי זְרָדִין וְהֶחָרוּבִין עַד שֶׁלֹּא יַמְתִּיקוּ אֵין נִלְקָחִין. אַחַר שֶׁיַּמְתִּיקוּ נִלְקָחִין. אֲבָל הַלּוּף וְהַחַרְדָּל וְהַתֻּרְמוּסִין וּשְׁאָר כָּל הַנִּכְבָּשִׁים בֵּין מִשֶּׁיַּמְתִּיקוּ בֵּין עַד שֶׁלֹּא הִמְתִּיקוּ נִלְקָחִין. וְהַקּוֹר נִלְקָח בְּכֶסֶף מַעֲשֵׂר:","הַכַּרְכּוֹם אֵינוֹ נִלְקָח שֶׁאֵינוֹ אֶלָּא לְמַרְאֶה. וְכֵן כָּל כַּיּוֹצֵא בּוֹ מִנּוֹתְנֵי רֵיחַ וּמַרְאֶה וְטַעַם הוֹאִיל וְאֵינָן לַאֲכִילַת גּוּפָן אֶלָּא לְטַעַם שֶׁנּוֹתְנִין אֵינָן נִלְקָחִין בְּכֶסֶף מַעֲשֵׂר. לְפִיכָךְ רָאשֵׁי בְּשָׂמִים וְהַפִּלְפְּלִין וְהַקֹּשְׁטְ וְהַחִלְתִּית וְחַלּוֹת חֲרִיעַ וְכָל כַּיּוֹצֵא בָּאֵלּוּ אֵינָן נִלְקָחִין בְּכֶסֶף מַעֲשֵׂר:","הַשֶּׁבֶת אִם לִתֵּן טַעַם בִּקְדֵרָה אֵינָהּ נִלְקַחַת בְּכֶסֶף מַעֲשֵׂר. וְאִם לִכְמַךְ וְכַיּוֹצֵא בּוֹ שֶׁהוּא אוֹכֵל גּוּפָהּ נִלְקַחַת בְּכֶסֶף מַעֲשֵׂר. עֵרֵב מַיִם וּמֶלַח אִם נָתַן לְתוֹכוֹ שֶׁמֶן הֲרֵי הֵן כְּמֻרְיָס וְלוֹקֵחַ מֵהֶן בְּכֶסֶף מַעֲשֵׂר. וּמַבְלִיעַ דְּמֵי הַמַּיִם וְהַמֶּלַח בִּדְמֵי הַשֶּׁמֶן:","אֵין לוֹקְחִין תְּרוּמוֹת בְּכֶסֶף מַעֲשֵׂר מִפְּנֵי שֶׁהוּא מְמַעֵט אֲכִילָתוֹ וַאֲכִילָתָהּ. שֶׁאֵין אוֹכְלִין אוֹתָהּ אֶלָּא כֹּהֲנִים מְעֹרְבֵי שֶׁמֶשׁ וּמֻתֶּרֶת לְאוֹנֵן וְנֶאֱכֶלֶת בְּכָל מָקוֹם. וְהַמַּעֲשֵׂר מֻתָּר לְזָרִים וְלִטְבוּל יוֹם וְאָסוּר לְאוֹנֵן וְאֵינוֹ נֶאֱכָל אֶלָּא בִּירוּשָׁלַיִם. נִמְצָא מְמַעֵט אֲכִילַת מַעֲשֵׂר וַאֲכִילַת הַתְּרוּמָה:","לוֹקְחִין בְּהֵמָה לְזִבְחֵי הַשְּׁלָמִים מִכֶּסֶף הַמַּעֲשֵׂר. שֶׁהַשְּׁלָמִים נֶאֱכָלִים לְזָרִים. בָּרִאשׁוֹנָה הָיוּ לוֹקְחִין בְּהֵמוֹת לְאָכְלָן חֻלִּין מִכֶּסֶף מַעֲשֵׂר שֵׁנִי כְּדֵי לְהַבְרִיחָם מֵעַל הַמִּזְבֵּחַ. גָּזְרוּ בֵּית דִּין שֶׁאֵין לוֹקְחִין בְּהֵמָה מִמְּעוֹת מַעֲשֵׂר אֶלָּא לִשְׁלָמִים. אֲבָל חַיָּה וְעוֹף לוֹקְחִין שֶׁאֵינָן רְאוּיִין לִשְׁלָמִים:","אֵין לוֹקְחִין פֵּרוֹת שְׁבִיעִית בְּכֶסֶף מַעֲשֵׂר. לְפִי שֶׁהוּא חַיָּב לְבַעֵר כְּמוֹ שֶׁיִּתְבָּאֵר:","הַלּוֹקֵחַ מַיִם וּמֶלַח אוֹ פֵּרוֹת מְחֻבָּרִין אוֹ פֵּרוֹת שֶׁאֵינָן יְכוֹלִין לְהַגִּיעַ לִירוּשָׁלַיִם לֹא קָנָה הַמַּעֲשֵׂר אַף עַל פִּי שֶׁיָּצְאוּ הַמָּעוֹת לְחֻלִּין:","הַלּוֹקֵחַ פֵּרוֹת חוּץ לִירוּשָׁלַיִם בְּכֶסֶף מַעֲשֵׂר. בְּשׁוֹגֵג כּוֹפִין אֶת הַמּוֹכֵר לְהַחֲזִיר הַדָּמִים לַבְּעָלִים וְהֵן מַעֲשֵׂר כְּמוֹת שֶׁהָיוּ. בְּמֵזִיד יַעֲלוּ הַפֵּרוֹת וְיֵאָכְלוּ בִּירוּשָׁלַיִם. וְאִם אֵין מִקְדָּשׁ יַנִּיחֵם עַד שֶׁיֵּרָקְבוּ:","וְכֵן אֵין לוֹקְחִין בְּהֵמָה בְּכֶסֶף מַעֲשֵׂר חוּץ לִירוּשָׁלַיִם. וְאִם לָקַח בְּשׁוֹגֵג יַחְזְרוּ הַדָּמִים לִמְקוֹמָן. בְּמֵזִיד תַּעֲלֶה וְתֵאָכֵל בִּירוּשָׁלַיִם. וְאִם אֵין מִקְדָּשׁ תִּקָּבֵר הִיא וְעוֹרָהּ:","לָקַח עֲבָדִים וְקַרְקָעוֹת וּבְהֵמָה טְמֵאָה בֵּין בְּמֵזִיד בֵּין בְּשׁוֹגֵג אִם בָּרַח הַמּוֹכֵר הֲרֵי זֶה יֵאָכֵל כְּנֶגֶד אוֹתָן הַמָּעוֹת בִּירוּשָׁלַיִם בְּתוֹרַת מַעֲשֵׂר. זֶה הַכְּלָל כָּל שֶׁהוֹצִיא חוּץ לַאֲכִילָה וּשְׁתִיָּה וְסִיכָה מִדְּמֵי מַעֲשֵׂר וּבָרַח הַמּוֹכֵר אוֹ מֵת יֵאָכֵל כְּנֶגְדּוֹ. וְאִם הָיָה הַמּוֹכֵר קַיָּם יַחְזְרוּ הַדָּמִים לִמְקוֹמָן. וְכֵן אִם הֵבִיא עוֹלוֹת וְחַטָּאוֹת וַאֲשָׁמוֹת מִדְּמֵי מַעֲשֵׂר יֹאכַל כְּנֶגְדָּן:","לָקַח חַיָּה לְזִבְחֵי שְׁלָמִים. וּבְהֵמָה לִבְשַׂר תַּאֲוָה. הֲרֵי זֶה כְּמִי שֶׁקָּנָה שׁוֹר לַחֲרִישָׁה וְלֹא קָנָה שְׁלָמִים. לָקַח בְּהֵמָה לִשְׁלָמִים וְנָפַל בָּהּ מוּם פָּקְעָה מִמֶּנָּה קְדֻשַּׁת מַעֲשֵׂר וּפוֹדֶה אוֹתָהּ. וְאֵין הַדָּמִים מַעֲשֵׂר. וְאַף עַל פִּי כֵן אִם פְּדָאָהּ לְעַצְמוֹ מוֹסִיף חֹמֶשׁ:","הַמַּתְפִּיס מְעוֹת מַעֲשֵׂר לִשְׁלָמִים לֹא קָנוּ שְׁלָמִים. שֶׁקְּדֻשַּׁת שְׁלָמִים אֵינָהּ חָלָה עַל קְדֻשַּׁת מַעֲשֵׂר. שֶׁהַמַּעֲשֵׂר מָמוֹן גָּבוֹהַּ הוּא. וְאֵין צָרִיךְ לוֹמַר אִם הִתְפִּיס הַמַּעֲשֵׂר עַצְמָן לִשְׁלָמִים שֶׁלֹּא קָנוּ שְׁלָמִים:","הָאוֹכֵל מַעֲשֵׂר שֵׁנִי בְּתוֹרַת חֻלִּין אֲפִלּוּ בְּמֵזִיד אִם פֵּרוֹת הַמַּעֲשֵׂר עַצְמָן אָכַל יָצָא יְדֵי שָׁמַיִם. וְאִם כֶּסֶף מַעֲשֵׂר אָכַל יַחְזְרוּ דָּמִים לִמְקוֹמָם וְיַעֲלוּ וְיֵאָכְלוּ בִּירוּשָׁלַיִם. אוֹ יֹאכַל כְּנֶגְדָּן בִּירוּשָׁלַיִם אִם אֵין יָכוֹל לְהַחֲזִיר אֶת הַדָּמִים:"],"Mishneh Torah, Shofar, Sukkah and Lulav 1":["מִצְוַת עֲשֵׂה שֶׁל תּוֹרָה לִשְׁמֹעַ תְּרוּעַת הַשּׁוֹפָר בְּרֹאשׁ הַשָּׁנָה שֶׁנֶּאֱמַר (במדבר כט א) \"יוֹם תְּרוּעָה יִהְיֶה לָכֶם\". וְשׁוֹפָר שֶׁתּוֹקְעִין בּוֹ בֵּין בְּרֹאשׁ הַשָּׁנָה בֵּין בְּיוֹבֵל הוּא קֶרֶן הַכְּבָשִׂים הַכָּפוּף. וְכָל הַשּׁוֹפָרוֹת פְּסוּלִין חוּץ מִקֶּרֶן הַכֶּבֶשׂ. וְאַף עַל פִּי שֶׁלֹּא נִתְפָּרֵשׁ בַּתּוֹרָה תְּרוּעָה בְּשׁוֹפָר בְּרֹאשׁ הַשָּׁנָה הֲרֵי הוּא אוֹמֵר בְּיוֹבֵל (ויקרא כה ט) \"וְהַעֲבַרְתָּ שׁוֹפַר\" וְכוּ' (ויקרא כה ט) \"תַּעֲבִירוּ שׁוֹפָר\". וּמִפִּי הַשְּׁמוּעָה לָמְדוּ מַה תְּרוּעַת יוֹבֵל בְּשׁוֹפָר אַף תְּרוּעַת רֹאשׁ הַשָּׁנָה בְּשׁוֹפָר:","בַּמִּקְדָּשׁ הָיוּ תּוֹקְעִין בְּרֹאשׁ הַשָּׁנָה בְּשׁוֹפָר אֶחָד וּשְׁתֵּי חֲצוֹצְרוֹת מִן הַצְּדָדִין. הַשּׁוֹפָר מַאֲרִיךְ וְהַחֲצוֹצְרוֹת מְקַצְּרוֹת שֶׁמִּצְוַת הַיּוֹם בְּשׁוֹפָר. וְלָמָּה תּוֹקְעִין עִמּוֹ בַּחֲצוֹצְרוֹת מִשּׁוּם שֶׁנֶּאֱמַר (תהילים צח ו) \"בַּחֲצֹצְרוֹת וְקוֹל שׁוֹפָר הָרִיעוּ לִפְנֵי הַמֶּלֶךְ ה'\". אֲבָל בִּשְׁאָר מְקוֹמוֹת אֵין תּוֹקְעִין בְּרֹאשׁ הַשָּׁנָה אֶלָּא בְּשׁוֹפָר בִּלְבַד:","שׁוֹפָר שֶׁל עַכּוּ\"ם אֵין תּוֹקְעִין בּוֹ לְכַתְּחִלָּה וְאִם תָּקַע יָצָא. וְשֶׁל עִיר הַנִּדַּחַת אִם תָּקַע בּוֹ לֹא יָצָא. שׁוֹפָר הַגָּזוּל שֶׁתָּקַע בּוֹ יָצָא שֶׁאֵין הַמִּצְוָה אֶלָּא בִּשְׁמִיעַת הַקּוֹל אַף עַל פִּי שֶׁלֹּא נָגַע בּוֹ וְלֹא הִגְבִּיהוֹ הַשּׁוֹמֵעַ יָצָא וְאֵין בַּקּוֹל דִּין גֵּזֶל. וְכֵן שׁוֹפָר שֶׁל עוֹלָה לֹא יִתְקַע בּוֹ וְאִם תָּקַע יָצָא שֶׁאֵין בַּקּוֹל דִּין מְעִילָה. וְאִם תֹּאמַר וַהֲלֹא נֶהֱנָה בִּשְׁמִיעַת הַקּוֹל. מִצְוֹת לֹא לֵהָנוֹת נִתְּנוּ. לְפִיכָךְ הַמֻּדָּר הֲנָיָה מִשּׁוֹפָר מֻתָּר לִתְקֹעַ בּוֹ תְּקִיעָה שֶׁל מִצְוָה:","שׁוֹפָר שֶׁל רֹאשׁ הַשָּׁנָה אֵין מְחַלְּלִין עָלָיו אֶת יוֹם טוֹב וַאֲפִלּוּ בְּדָבָר שֶׁהוּא מִשּׁוּם שְׁבוּת. כֵּיצַד. הָיָה הַשּׁוֹפָר בְּרֹאשׁ הָאִילָן אוֹ מֵעֵבֶר הַנָּהָר וְאֵין לוֹ שׁוֹפָר אֶלָּא הוּא אֵינוֹ עוֹלֶה בָּאִילָן וְאֵינוֹ שָׁט עַל פְּנֵי הַמַּיִם כְּדֵי לַהֲבִיאוֹ. וְאֵין צָרִיךְ לוֹמַר שֶׁאֵין חוֹתְכִין אוֹתוֹ אוֹ עוֹשִׂין בּוֹ מְלָאכָה. מִפְּנֵי שֶׁתְּקִיעַת שׁוֹפָר מִצְוַת עֲשֵׂה וְיוֹם טוֹב עֲשֵׂה וְלֹא תַּעֲשֶׂה וְאֵין עֲשֵׂה דּוֹחֶה לֹא תַּעֲשֶׂה וַעֲשֵׂה. מֻתָּר לִתֵּן בְּתוֹכוֹ מַיִם אוֹ יַיִן אוֹ חֹמֶץ בְּיוֹם טוֹב כְּדֵי לְצַחְצְחוֹ. וְלֹא יִתֵּן לְתוֹכוֹ מֵי רַגְלַיִם לְעוֹלָם מִפְּנֵי הַכָּבוֹד שֶׁלֹּא יִהְיוּ מִצְוֹת בְּזוּיוֹת עָלָיו:","שִׁעוּר הַשּׁוֹפָר כְּדֵי שֶׁיֹּאחֲזֶנּוּ בְּיָדוֹ וְיֵרָאֶה לְכָאן וּלְכָאן. נִסְדַּק לְאָרְכּוֹ פָּסוּל. לְרָחְבּוֹ אִם נִשְׁתַּיֵּר בּוֹ כַּשִּׁעוּר כָּשֵׁר וּכְאִלּוּ נִכְרַת מִמְּקוֹם הַסֶּדֶק. נִקַּב אִם סְתָמוֹ שֶׁלֹּא בְּמִינוֹ פָּסוּל. סְתָמוֹ בְּמִינוֹ אִם נִשְׁתַּיֵּר רֻבּוֹ שָׁלֵם וְלֹא עִכְּבוּ הַנְּקָבִים שֶׁנִּסְתְּמוּ אֶת הַתְּקִיעָה הֲרֵי זֶה כָּשֵׁר. קְדָחוֹ בְּזִכְרוּתוֹ כָּשֵׁר שֶׁמִּין בְּמִינוֹ אֵינוֹ חוֹצֵץ. דִּבֵּק שִׁבְרֵי שׁוֹפָרוֹת עַד שֶׁהִשְׁלִימוֹ לְאֶחָד פָּסוּל:","הוֹסִיף עָלָיו כָּל שֶׁהוּא בֵּין בְּמִינוֹ בֵּין שֶׁלֹּא בְּמִינוֹ פָּסוּל. צִפָּהוּ זָהָב מִבִּפְנִים אוֹ בִּמְקוֹם הַנָּחַת פֶּה פָּסוּל. צִפָּהוּ מִבַּחוּץ אִם נִשְׁתַּנָּה קוֹלוֹ מִכְּמוֹת שֶׁהָיָה פָּסוּל וְאִם לֹא נִשְׁתַּנָּה כָּשֵׁר. נָתַן שׁוֹפָר בְּתוֹךְ שׁוֹפָר אִם קוֹל פְּנִימִי שָׁמַע יָצָא וְאִם קוֹל חִיצוֹן שָׁמַע לֹא יָצָא. הִרְחִיב אֶת הַקָּצָר וְקִצֵּר אֶת הָרָחָב פָּסוּל:","הָיָה אָרֹךְ וְקִצְּרוֹ כָּשֵׁר. גֵּרְדוֹ בֵּין מִבִּפְנִים בֵּין מִבַּחוּץ אֲפִלּוּ הֶעֱמִידוֹ עַל גִּלְדּוֹ כָּשֵׁר. הָיָה קוֹלוֹ עָב אוֹ דַּק אוֹ צָרוּר כָּשֵׁר שֶׁכָּל הַקּוֹלוֹת כְּשֵׁרִין בְּשׁוֹפָר:","הַתּוֹקֵעַ בְּתוֹךְ הַבּוֹר אוֹ בְּתוֹךְ הַמְּעָרָה. אוֹתָן הָעוֹמְדִים בְּתוֹךְ הַבּוֹר וְהַמְּעָרָה יָצְאוּ. וְהָעוֹמְדִים בַּחוּץ אִם קוֹל שׁוֹפָר שָׁמְעוּ יָצְאוּ. וְאִם קוֹל הֲבָרָה שָׁמְעוּ לֹא יָצְאוּ. וְכֵן הַתּוֹקֵעַ לְתוֹךְ חָבִית גְּדוֹלָה וְכַיּוֹצֵא בָּהּ. אִם קוֹל שׁוֹפָר שָׁמַע יָצָא וְאִם קוֹל הֲבָרָה שָׁמַע לֹא יָצָא:"],"Mishneh Torah, Slaves 5":["עֶבֶד כְּנַעֲנִי נִקְנֶה בַּחֲמִשָּׁה דְּבָרִים וְקוֹנֶה אֶת עַצְמוֹ בִּשְׁלֹשָׁה. נִקְנֶה בְּכֶסֶף אוֹ בִּשְׁטָר אוֹ בַּחֲזָקָה אוֹ בַּחֲלִיפִין אוֹ בִּמְשִׁיכָה. וְקוֹנֶה אֶת עַצְמוֹ בְּכֶסֶף אוֹ בִּשְׁטָר אוֹ בְּרָאשֵׁי אֵיבָרִים. וְעֶבֶד קָטָן הֲרֵי הוּא כִּבְהֵמָה וְנִקְנֶה בִּמְשִׁיכָה כִּמְשִׁיכַת הַבְּהֵמָה. וּכְבָר בֵּאַרְנוּ בִּתְחִלַּת סֵפֶר זֶה כָּל הַדְּרָכִים שֶׁהָעֲבָדִים נִקְנִין בָּהֶן:","כֵּיצַד קוֹנֶה אֶת עַצְמוֹ בְּכֶסֶף. כְּגוֹן שֶׁנָּתַן אֶחָד לְרַבּוֹ מָעוֹת וְאָמַר לוֹ עַל מְנָת שֶׁיֵּצֵא עַבְדְּךָ בָּהֶם לְחֵרוּת כֵּיוָן שֶׁקִּבֵּל הָרַב אֶת הַכֶּסֶף אוֹ שְׁוֵה כֶּסֶף יָצָא הָעֶבֶד לְחֵרוּת. וְאֵין צָרִיךְ דַּעַת הָעֶבֶד שֶׁזְּכוּת הִיא לוֹ וְזָכִין לְאָדָם שֶׁלֹּא בְּפָנָיו. וְכֵן אִם נָתַן אֶחָד לְעֶבֶד מָעוֹת וְאָמַר עַל מְנָת שֶׁתֵּצֵא בָּהֶם לְחֵרוּת אִם רָצָה הָאָדוֹן לְקַבֵּל הַמָּעוֹת יָצָא הָעֶבֶד לְחֵרוּת וְאִם לֹא רָצָה לֹא קָנָה הָעֶבֶד הַמָּעוֹת שֶׁלֹּא נָתַן לוֹ אֶלָּא עַל מְנָת שֶׁיֵּצֵא בָּהֶם לְחֵרוּת. וְאֶחָד הַכֶּסֶף אוֹ שְׁוֵה כֶּסֶף בֵּין לִקְנוֹתוֹ בֵּין לְהַקְנוֹת עַצְמוֹ לוֹ:","כֵּיצַד בִּשְׁטָר. כּוֹתֵב לוֹ עַל הַנְּיָר אוֹ עַל הַחֶרֶס הֲרֵי אַתְּ בֶּן חוֹרִין אוֹ הֲרֵי אַתְּ שֶׁל עַצְמְךָ אוֹ אֵין לִי עֵסֶק בְּךָ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה בְּעִנְיָן זֶה שֶׁזֶּה הוּא גּוּפוֹ שֶׁל גֵּט שִׁחְרוּר. וּמוֹסֵר לוֹ אֶת הַשְּׁטָר בִּפְנֵי שְׁנֵי עֵדִים אוֹ שֶׁהָיוּ הָעֵדִים חֲתוּמִים בּוֹ וּמְסָרוֹ לוֹ בֵּינוֹ לְבֵינוֹ. הֲרֵי זֶה יָצָא לְחֵרוּת שֶׁהֲרֵי גִּטּוֹ וְיָדוֹ בָּאִין כְּאֶחָד. אָמַר לוֹ שֶׁלֹּא בִּכְתָב הֲרֵי אַתְּ בֶּן חוֹרִין הֲרֵי אַתְּ שֶׁל עַצְמְךָ אַף עַל פִּי שֶׁהֵעִידוּ עָלָיו עֵדִים בְּבֵית דִּין וְאַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ עֲדַיִן לֹא נִשְׁתַּחְרֵר שֶׁאֵין הָעֶבֶד יוֹצֵא לְחֵרוּת אֶלָּא בְּכֶסֶף אוֹ בִּשְׁטָר אוֹ בְּרָאשֵׁי אֵיבָרִים. והַכּוֹתֵב לְשִׁפְחָתוֹ הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם לֹא אָמַר כְּלוּם:","כֵּיצַד בְּרָאשֵׁי אֵיבָרִים. הַמַּכֶּה אֶת עַבְדּוֹ בְּכַוָּנָה וחִסְרוֹ אֶחָד מֵעֶשְׂרִים וְאַרְבָּעָה רָאשֵׁי אֵיבָרִים שֶׁאֵינָן חוֹזְרִין יָצָא לְחֵרוּת וְצָרִיךְ גֵּט שִׁחְרוּר. אִם כֵּן לָמָּה נֶאֱמַר בַּתּוֹרָה (שמות כא כז) \"שֵׁן\" וְ (שמות כא כו) \"עַיִן\" לִדּוֹן מֵהֶן מָה שֵׁן וְעַיִן מוּמִין שֶׁבְּגָלוּי וְאֵינָן חוֹזְרִין אַף כָּל מוּמִין שֶׁבְּגָלוּי וְאֵינָן חוֹזְרִין יֵצֵא הָעֶבֶד בּוֹ לְחֵרוּת. אֲבָל הַמְסָרֵס עַבְדּוֹ בַּבֵּיצִים אוֹ הַחוֹתֵךְ לְשׁוֹנוֹ אֵינוֹ יוֹצֵא לְחֵרוּת שֶׁאֵינָן מוּמִין שֶׁבְּגָלוּי. וְכֵן הַמַּפִּיל שֵׁן הַקָּטָן אֵינוֹ יוֹצֵא לְחֵרוּת שֶׁהֲרֵי סוֹפוֹ לַחְזֹר:","אֵין יוֹצֵא בְּרָאשֵׁי אֵיבָרִים אֶלָּא עֲבָדִים שֶׁמָּלוּ וְטָבְלוּ שֶׁהֲרֵי יֶשְׁנָן בְּמִקְצָת מִצְוֹת אֲבָל הָעֶבֶד שֶׁהוּא בְּגֵיוּתוֹ אֵינוֹ יוֹצֵא בְּרָאשֵׁי אֵיבָרִים. אֵלּוּ הֵן רָאשֵׁי אֵיבָרִים שֶׁאֵינָן חוֹזְרִין. אֶצְבְּעוֹת יָדַיִם וְרַגְלַיִם עֶשְׂרִים רָאשֵׁי הָאָזְנַיִם וְרֹאשׁ הַחֹטֶם וְרֹאשׁ הַגְּוִיָּה וְרָאשֵׁי הַדָּדִין שֶׁבָּאִשָּׁה אֲבָל הָעֵינַיִם וְהַשִּׁנַּיִם הֲרֵי הֵן מְפֹרָשִׁין בַּתּוֹרָה:","הָיְתָה לוֹ אֶצְבַּע יְתֵרָה וַחֲתָכָהּ אִם נִסְפֶּרֶת עַל גַּב הַיָּד עֶבֶד יוֹצֵא בָּהּ לְחֵרוּת. הָיְתָה עֵינוֹ סְמוּיָה וְחִטְטָהּ עֶבֶד יוֹצֵא בָּהּ לְחֵרוּת שֶׁהֲרֵי חִסְּרוֹ אֵיבָר. וְהוּא הַדִּין לְאֶחָד מֵרָאשֵׁי אֵיבָרִים שֶׁהוּא בָּטֵל וְאֵינוֹ עוֹשֶׂה בּוֹ מְלָאכָה שֶׁאִם חֲתָכוֹ הֲרֵי חִסְּרוֹ אֵיבָר וְיָצָא לְחֵרוּת:","הִכָּהוּ עַל עֵינוֹ וְסִמְּאָהּ עַל אָזְנוֹ וְחֵרְשָׁהּ עֶבֶד יוֹצֵא בָּהֶן לְחֵרוּת. הִכָּהוּ כְּנֶגֶד עֵינוֹ וְאֵינוֹ רוֹאֶה כְּנֶגֶד אָזְנוֹ וְאֵינוֹ שׁוֹמֵעַ אֵין עֶבֶד יוֹצֵא בָּהֶן לְחֵרוּת:","הִכָּהוּ עַל עֵינוֹ וְחָסְרָה מֵאוֹרָהּ. עַל שִׁנּוֹ וְנִדְּדָהּ. אִם יָכוֹל לְהִשְׁתַּמֵּשׁ בָּהֶם אֵינוֹ יוֹצֵא לְחֵרוּת וְאִם לָאו יֵצֵא לְחֵרוּת:","הָיְתָה עֵינוֹ כֵּהָה וְחִסֵּר מֵאוֹרָהּ אוֹ שִׁנּוֹ נוֹדֶדֶת וְהִכָּהוּ הָאָדוֹן וְהִפִּיל הַשֵּׁן הַנּוֹדֶדֶת אוֹ סִמֵּא הָעַיִן הַכֵּהָה אִם הָיָה מִשְׁתַּמֵּשׁ בָּהֶן כָּל שֶׁהוּא יֵצֵא לְחֵרוּת וְאִם לָאו לֹא יֵצֵא לְחֵרוּת:","הִכָּהוּ עַל יָדוֹ וְצָבְתָה יָדוֹ וְסוֹפָהּ לַחְזֹר אֵינוֹ יוֹצֵא לְחֵרוּת. תָּלַשׁ בִּזְקָנוֹ וְדִלְדֵּל בּוֹ עֶצֶם מִן הַלֶּחִי יֵצֵא לְחֵרוּת שֶׁהֲרֵי בִּטֵּל מַעֲשֵׂה הַשִּׁנַּיִם הַקְּבוּעוֹת בְּאוֹתוֹ הָעֶצֶם:","הִפִּיל אֶת שִׁנּוֹ אוֹ סִמֵּא אֶת עֵינוֹ בְּלֹא כַּוָּנָה כְּגוֹן שֶׁזָּרַק אֶבֶן לִבְהֵמָה וְנָפְלָה בָּעֶבֶד וְהִפִּילָה אֶת שִׁנּוֹ וְחָתְכָה אֶצְבָּעוֹ לֹא יֵצֵא לְחֵרוּת שֶׁנֶּאֱמַר (שמות כא כז) \"אִם שֵׁן עַבְדּוֹ אוֹ שֵׁן אֲמָתוֹ יַפִּיל\" עַד שֶׁיִּתְכַּוֵּן:","הוֹשִׁיט יָדוֹ לִמְעֵי שִׁפְחָתוֹ וְסִמֵּא עֵין הָעֻבָּר שֶׁבְּמֵעֶיהָ לֹא יֵצֵא לְחֵרוּת שֶׁהֲרֵי לֹא יָדַע דָּבָר שֶׁיִּתְכַּוֵּן לוֹ:","הֲרֵי שֶׁהָיָה רַבּוֹ רוֹפֵא וְאָמַר לוֹ כְּחל לִי עֵינִי וְסִמְּאָהּ חֲתֹר לִי שִׁנִּי וְהִפִּילָהּ שָׂחַק בָּאָדוֹן וְיֵצֵא לְחֵרוּת שֶׁאַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן לְהַזִּיק הֲרֵי נִתְכַּוֵּן לִנְגֹּעַ בְּאֵיבְרֵי הָעֶבֶד וְנִסְתַּכֵּן בָּהֶן. וְאֵין צָרִיךְ לוֹמַר אִם הָיְתָה עֵין הָעֶבֶד כּוֹאֶבֶת וְהָיָה רַבּוֹ אֻמָּן וַעֲקָרָהּ לוֹ שֶׁהֲרֵי יֵצֵא לְחֵרוּת:","הַמַּפִּיל שֵׁן עַבְדּוֹ וְסִמֵּא אֶת עֵינוֹ הֲרֵי יֵצֵא לְחֵרוּת בְּשִׁנּוֹ וְנוֹתֵן לוֹ דְּמֵי עֵינוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין וְעֶבֶד שֶׁל שְׁנֵי שֻׁתָּפִין אֵינוֹ יוֹצֵא בְּרָאשֵׁי אֵיבָרִים לְפִי שֶׁאֵינוֹ מְיֻחָד לְרַבּוֹ שֶׁחָבַל בּוֹ:","עַבְדֵי צֹאן בַּרְזֶל יוֹצְאִין בְּרָאשֵׁי אֵיבָרִים אִם חִסְּרָן הַבַּעַל אֲבָל לֹא הָאִשָּׁה. וְעַבְדֵי מְלוֹג אֵינָן יוֹצְאִין בְּרָאשֵׁי אֵיבָרִים לֹא אִם הִפִּיל הַבַּעַל שֶׁהֲרֵי אֵין לוֹ בָּהֶם אֶלָּא פֵּרוֹת וְלֹא אִם הִפִּילָה אוֹתָן הָאִשָּׁה מִפְּנֵי שֶׁאֵינָן מְיֻחָדִין לָהּ:","יְצִיאַת הָעֶבֶד בְּרָאשֵׁי אֵיבָרִים נוֹהֵג בְּכָל מָקוֹם וּבְכָל זְמַן וְאֵין דָּנִין בּוֹ אֶלָּא בְּבֵית דִּין סְמוּכִין מִפְּנֵי שֶׁהוּא קְנָס. לְפִיכָךְ הָעֶבֶד שֶׁאָמַר לְרַבּוֹ הִפַּלְתָּ אֶת שִׁנִּי וְסִמֵּיתָ אֶת עֵינִי וְהָאָדוֹן אוֹמֵר לוֹ עָשִׂיתִי זֶה פָּטוּר שֶׁאִם יוֹדֶה מֵעַצְמוֹ אֵינוֹ חַיָּב לְהוֹצִיאוֹ לְחֵרוּת בְּלֹא עֵדִים שֶׁהַמּוֹדֶה בִּקְנָס פָּטוּר כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת גְּנֵבָה שֶׁכָּל מוֹדֶה בִּקְנָס פָּטוּר מִלְּשַׁלְּמוֹ:"],"Mishneh Torah, Tefillin, Mezuzah and the Torah Scroll 3":["שְׁמוֹנֶה הֲלָכוֹת יֵשׁ בְּמַעֲשֵׂה הַתְּפִלִּין כֻּלָּן הֲלָכָה לְמשֶׁה מִסִּינַי. וּלְפִיכָךְ כֻּלָּן מְעַכְּבוֹת וְאִם שִׁנָּה בְּאַחַת מֵהֶן פָּסַל. וְאֵלּוּ הֵם. שֶׁיִּהְיוּ מְרֻבָּעוֹת. וְכֵן תְּפִירָתָן בְּרִבּוּעַ. וַאֲלַכְסוֹנָן בְּרִבּוּעַ עַד שֶׁיִּהְיֶה לָהֶן אַרְבַּע זָוִיּוֹת שָׁווֹת. וְשֶׁיִּהְיֶה בָּעוֹר שֶׁל רֹאשׁ צוּרַת שִׁי״ן מִיָּמִין וּמִשְּׂמֹאל. וְשֶׁיִּכְרֹךְ הַפָּרָשִׁיּוֹת בְּמַטְלִית. וְשֶׁיִּכְרֹךְ אוֹתָן בְּשֵׂעָר מֵעַל הַמַּטְלִית. וְאַחַר כָּךְ מַכְנִיסָן בְּבָתֵּיהֶן. וְשֶׁיִּהְיוּ תּוֹפְרִין אוֹתָן בְּגִידִין. וְשֶׁעוֹשִׂין לָהֶן מַעְבֹּרֶת מֵעוֹר הַחִפּוּי שֶׁתִּכָּנֵס בָּהּ הָרְצוּעָה עַד שֶׁתְּהֵא עוֹבֶרֶת וְהוֹלֶכֶת בְּתוֹךְ תּוֹבָר שֶׁלָּהּ. וְשֶׁיִּהְיוּ הָרְצוּעוֹת שְׁחוֹרוֹת. וְשֶׁיִּהְיֶה הַקֶּשֶׁר שֶׁלָּהֶן קֶשֶׁר יָדוּעַ כְּצוּרַת דָּלֶ״ת:","כֵּיצַד עוֹשִׂים תְּפִלִּין שֶׁל רֹאשׁ. לוֹקְחִין עֵץ מְרֻבָּע אָרְכּוֹ כְּרָחְבּוֹ וּכְגָבְהוֹ. וְאִם הָיָה גָּבְהוֹ יוֹתֵר עַל רָחְבּוֹ אוֹ פָּחוֹת מִמֶּנּוּ אֵין בְּכָךְ כְּלוּם. וְאֵין מַקְפִּידִין אֶלָּא עַל אָרְכּוֹ שֶׁיְּהֵא כְּרָחְבּוֹ. וְחוֹפְרִין בּוֹ שְׁלֹשָׁה חֲרִיצִין כְּדֵי שֶׁיֵּעָשֶׂה לוֹ אַרְבַּע רָאשִׁים כְּגוֹן זֶה:וְלוֹקְחִין עוֹר וּמַרְטִיבִין אוֹתוֹ בְּמַיִם וּמְשִׂימִין בּוֹ אֶת הָעֵץ וּמַכְנִיסִין אֶת הָעוֹר בֵּין כָּל חָרִיץ וְחָרִיץ וּמְכַמְּשִׁים אוֹתוֹ וְהוּא רָטֹב מִכָּאן וּמִכָּאן עַד שֶׁעוֹשִׂין בּוֹ דְּמוּת שִׁי״ן שֶׁיֵּשׁ לָהּ שְׁלֹשָׁה רָאשִׁין מִיָּמִין הַמֵּנִיחַ תְּפִלִּין וּדְמוּת שִׁי״ן שֶׁיֵּשׁ לָהּ אַרְבָּעָה רָאשִׁים מִשְּׂמֹאל הַמֵּנִיחַ:","וּמַנִּיחִין אֶת הָעוֹר עַל הָעֵץ עַד שֶׁיִּיבַשׁ. וְאַחַר כָּךְ חוֹלֵץ הָעוֹר מֵעַל גַּבֵּי הָאִמּוּם שֶׁל עֵץ וְנִמְצָא הָעוֹר שֶׁיֵּשׁ בּוֹ אַרְבָּעָה בָּתִּים פְּנוּיִין. וּמַכְנִיסִין פָּרָשָׁה בְּכָל בַּיִת וּבַיִת. וּמַחְזִירִין מִקְצָת הָעוֹר מִלְּמַטָּה וְתוֹפְרִין אוֹתוֹ מֵאַרְבַּע פִּנּוֹתָיו. וּמַנִּיחִין מִן הָעוֹר שֶׁלְּמַטָּה מָקוֹם שֶׁתִּכָּנֵס בּוֹ הָרְצוּעָה כְּמוֹ תּוֹבָר וְהוּא הַנִּקְרָא מַעְבֹּרֶת:","וְכֵיצַד עוֹשִׂין תְּפִלִּין שֶׁל יָד. לוֹקְחִין עֵץ מְרֻבָּע אָרְכּוֹ כְּרָחְבּוֹ וְיִהְיֶה גָּבְהוֹ כְּאֶצְבַּע אוֹ יָתֵר עַל זֶה מְעַט אוֹ פָּחוֹת מְעַט וּמְחַפִּין אוֹתוֹ בְּעוֹר רָטֹב וּמַנִּיחִין אֶת הָעוֹר עַל הָאִמּוּם עַד שֶׁיִּיבַשׁ וְחוֹלֵץ אֶת הָעוֹר וּמַנִּיחַ אֶת אַרְבַּע הַפָּרָשִׁיּוֹת בִּמְקוֹם הָעֵץ וּמַחֲזִיר מִקְצָת הָעוֹר מִלְּמַטָּה וְתוֹפְרוֹ מֵאַרְבַּע פִּנּוֹתָיו. וּמַנִּיחִין מִן הָעוֹר תּוֹבָר מְקוֹם הָרְצוּעוֹת:","כֵּיצַד סִדּוּר הַפָּרָשִׁיּוֹת בִּתְפִלָּה שֶׁל רֹאשׁ. מַכְנִיס פָּרָשָׁה אַחֲרוֹנָה שֶׁהִיא (דברים יא יג) ״וְהָיָה אִם שָׁמֹעַ״ בְּבַיִת רִאשׁוֹן שֶׁהוּא עַל יְמִין הַמֵּנִיחַ. וּ (דברים ו ד) ״שְׁמַע״ סְמוּכָה לָהּ. (שמות יג יא) ״וְהָיָה כִי יְבִיאֲךָ״ בְּבַיִת שְׁלִישִׁי סְמוּכָה לִשְׁמַע. וְ(שמות יג ב) ״קַדֶּשׁ לִי״ בְּבַיִת רְבִיעִי שֶׁהוּא לִשְׂמֹאל הַמֵּנִיחַ תְּפִלִּין כְּדֵי שֶׁיְּהֵא הַקּוֹרֵא שֶׁלְּפָנָיו כְּנֶגֶד פְּנֵי הַמֵּנִיחַ קוֹרֵא עַל הַסֵּדֶר הַזֶּה כְּגוֹן זֶה: וְאִם הֶחֱלִיף סִדּוּר זֶה פְּסוּלוֹת:","תְּפִלָּה שֶׁל יָד כּוֹתְבָם בְּאַרְבָּעָה דַּפִּין בְּעוֹר אֶחָד אָרֹךְ כְּסֵפֶר תּוֹרָה עַל סִדּוּרָן בַּתּוֹרָה כְּגוֹן זֶהאִם כְּתָבָן עַל אַרְבַּע עוֹרוֹת וְהִכְנִיסָן בְּבַיִת אֶחָד יָצָא וְאֵינוֹ צָרִיךְ לְדַבְּקָם:","כְּשֶׁהוּא גּוֹלֵל הַפָּרָשִׁיּוֹת בֵּין שֶׁל רֹאשׁ בֵּין שֶׁל יָד גּוֹלֵל אוֹתָן מִסּוֹפָן לִתְחִלָּתָן עַד שֶׁתִּמְצָא כְּשֶׁתִּפְתַּח הַפָּרָשָׁה תִּקְרָא כָּל פָּרָשָׁה וּפָרָשָׁה מִתְּחִלָּתָהּ עַד סוֹפָהּ:","וּכְשֶׁמַּכְנִיסִין אֶת הַפָּרָשִׁיּוֹת בַּבָּתִּים שֶׁלָּהֶם כּוֹרְכִין אוֹתָן בְּמַטְלִית וְעַל הַמַּטְלִית שֵׂעָר וְאַחַר כָּךְ מַכְנִיסִין אוֹתָן בְּבָתֵּיהֶן. וְשֵׂעָר זֶה צָרִיךְ לִהְיוֹת שְׂעַר בְּהֵמָה אוֹ שֶׁל חַיָּה טְהוֹרָה וַאֲפִלּוּ מִנְּבֵלוֹת וּטְרֵפוֹת שֶׁלָּהֶן. וּכְבָר נָהֲגוּ כָּל הָעָם (לְבָרְכָן) [לְכָרְכָן] בִּשְׂעַר זְנַב הָעֲגָלִים:","כְּשֶׁתּוֹפְרִין אֶת הַתְּפִלִּין אֵין תּוֹפְרִין אֶלָּא בְּגִידִין שֶׁל בְּהֵמָה אוֹ שֶׁל חַיָּה טְהוֹרָה וַאֲפִלּוּ מִנְּבֵלוֹת וּטְרֵפוֹת שֶׁלָּהֶן. לוֹקְחִין הַגִּידִין שֶׁיֵּשׁ בַּעֲקֵב הַבְּהֵמָה אוֹ הַחַיָּה טְהוֹרִים וְהֵם לְבָנִים. וְאִם הֵם קָשִׁים מְרַכְּכִין אוֹתָן בַּאֲבָנִים וְכַיּוֹצֵא בָּהֶן עַד שֶׁיֵּעָשׂוּ כְּפִשְׁתָּן וְטוֹוִין אוֹתָן וְשׁוֹזְרִין אוֹתָן וּבָהֶן תּוֹפְרִין הַתְּפִלִּין וִירִיעוֹת סֵפֶר תּוֹרָה:","כְּשֶׁתּוֹפְרִין הַתְּפִלִּין תּוֹפְרִין אוֹתָן בְּרִבּוּעַ. וַהֲלָכָה רוֹוַחַת שֶׁיִּהְיוּ בְּכָל צַד שָׁלֹשׁ תְּפִירוֹת עַד שֶׁיִּהְיוּ הַכּל שְׁתֵּים עֶשְׂרֵה תְּפִירוֹת בֵּין שֶׁל יָד בֵּין שֶׁל רֹאשׁ. וְאִם עָשָׂה הַתְּפִירוֹת עֶשֶׂר אוֹ אַרְבַּע עֶשְׂרֵה עוֹשֶׂה. וְכָל הַתְּפִירוֹת יִהְיֶה הַחוּט שֶׁלָּהֶן סוֹבֵב מִשְּׁתֵּי רוּחוֹת:","וְצָרִיךְ שֶׁיַּגִּיעַ הֶחָרִיץ שֶׁל תְּפִלִּין שֶׁל רֹאשׁ עַד מְקוֹם הַתֶּפֶר. וְאִם הָיָה הֶחָרִיץ נִכָּר כְּדֵי שֶׁיִּהְיוּ אַרְבָּעָה רָאשִׁין נִרְאִין לַכּל וְאַף עַל פִּי שֶׁאֵין הֶחָרִיץ מַגִּיעַ לִמְקוֹם הַתֶּפֶר כְּשֵׁרוֹת. וְאִם אֵין חָרִיץ נִכָּר פְּסוּלוֹת. וְצָרִיךְ לְהַעֲבִיר בְּתוֹךְ כָּל חָרִיץ וְחָרִיץ עַל גַּבֵּי הָעוֹר חוּט אוֹ מְשִׁיחָה לְהַבְדִּיל בֵּין בַּיִת לְבַיִת. וּמִנְהָג פָּשׁוּט לְהַעֲבִיר גִּיד מִגִּידֵי הַתְּפִירָה בְּכָל חָרִיץ וְחָרִיץ מִשְּׁלָשְׁתָּן:","וְכֵיצַד עוֹשִׂין הָרְצוּעוֹת. לוֹקְחִין רְצוּעָה שֶׁל עוֹר רְחָבָה כְּאֹרֶךְ הַשְּׂעוֹרָה. וְאִם הָיְתָה רְחָבָה מִזּוֹ הַשִּׁעוּר כְּשֵׁרָה. וְאֹרֶךְ רְצוּעָה שֶׁל רֹאשׁ כְּדֵי שֶׁתַּקִּיף אֶת הָרֹאשׁ וְיִקְשֹׁר מִמֶּנָּה הַקֶּשֶׁר וְתִמְתַּח שְׁתֵּי הָרְצוּעוֹת מִכָּאן וּמִכָּאן עַד שֶׁיַּגִּיעוּ לַטַּבּוּר אוֹ לְמַעְלָה מִמֶּנּוּ מְעַט. וְאֹרֶךְ רְצוּעָה שֶׁל יָד כְּדֵי שֶׁתַּקִּיף אֶת הַזְּרוֹעַ וְיִקְשֹׁר מִמֶּנָּה הַקֶּשֶׁר וְתִמָּתַח רְצוּעָה אַחַת עַל אֶצְבַּע אֶמְצָעִית וְיִכְרֹךְ מִמֶּנָּה עַל אֶצְבָּעוֹ שָׁלֹשׁ כְּרִיכוֹת וְיִקְשֹׁר. וְאִם הָיוּ הָרְצוּעוֹת אֲרֻכּוֹת יָתֵר עַל שִׁעוּרִים הָאֵלּוּ כְּשֵׁרוֹת:","וּמַכְנִיס רְצוּעָה שֶׁל רֹאשׁ בַּתּוֹבָר שֶׁלָּהּ. וּמַקִּיף בְּמִדַּת רֹאשׁוֹ וְקוֹשֵׁר קֶשֶׁר מְרֻבָּע כְּמִין דָּלֶ״ת. וְקֶשֶׁר זֶה צָרִיךְ כָּל תַּלְמִיד חָכָם לְלָמְדוֹ וְאִי אֶפְשָׁר לְהוֹדִיעַ צוּרָתוֹ בִּכְתָב אֶלָּא בִּרְאִיַּת הָעַיִן. וְכֵן בְּשֶׁל יָד קוֹשֵׁר קֶשֶׁר כְּמִין יוּ״ד. וְתִהְיֶה הָרְצוּעָה שֶׁל יָד עוֹלָה וְיוֹרֶדֶת בְּתוֹךְ הַקֶּשֶׁר כְּדֵי שֶׁיַּרְחִיב וִיקַצֵּר בְּעֵת שֶׁיִּרְצֶה לִקְשֹׁר עַל יָדוֹ:","הָרְצוּעוֹת שֶׁל תְּפִלִּין בֵּין שֶׁל רֹאשׁ בֵּין שֶׁל יָד פְּנֵיהֶם הַחִיצוֹנִים שְׁחוֹרִים וְזוֹ הֲלָכָה לְמשֶׁה מִסִּינַי. אֲבָל אֲחוֹרֵי הָרְצוּעוֹת הוֹאִיל וּמִבִּפְנִים הֵן אִם הָיוּ יְרֻקּוֹת אוֹ לְבָנוֹת כְּשֵׁרוֹת. אֲדֻמּוֹת לֹא יַעֲשֶׂה שֶׁמָּא תֵּהָפֵךְ הָרְצוּעָה וּגְנַאי הוּא לוֹ. וְלֹא יִהְיֶה אֲחוֹרֵי הָרְצוּעָה לְעוֹלָם אֶלָּא כְּעֵין הַקְּצִיצָה אִם יְרֻקָּה יְרֻקִּין וְאִם לְבָנָה לְבָנִים. וְנוֹי הוּא לַתְּפִלִּין שֶׁיִּהְיוּ כֻּלָּן שְׁחוֹרוֹת הַקְּצִיצָה וְהָרְצוּעָה כֻּלָּהּ:","הָעוֹר שֶׁמְּחַפִּין בּוֹ הַתְּפִלִּין וְשֶׁעוֹשִׂין מִמֶּנּוּ הָרְצוּעוֹת הוּא עוֹר שֶׁל בְּהֵמָה אוֹ חַיָּה אוֹ עוֹף הַטְּהוֹרִים וַאֲפִלּוּ נְבֵלוֹת וּטְרֵפוֹת שֶׁלָּהֶן. וְאִם עָשָׂה מֵעוֹר טְמֵאִים אוֹ שֶׁחִפָּה תְּפִלִּין בְּזָהָב פְּסוּלוֹת. וְעוֹר הָרְצוּעָה צָרִיךְ עִבּוּד לִשְׁמָהּ. אֲבָל בְּעוֹר שֶׁמְּחַפִּין בּוֹ אֵינוֹ צָרִיךְ עִבּוּד כְּלָל אֲפִלּוּ עֲשָׂהוּ מַצָּה כָּשֵׁר. וּמְקוֹמוֹת הַרְבֵּה נָהֲגוּ לַעֲשׂוֹת אוֹתָן בְּעוֹר מַצָּה:","אֵין עוֹשִׂין הַתְּפִלִּין אֶלָּא יִשְׂרָאֵל שֶׁעֲשִׂיָּתָן כִּכְתִיבָתָן מִפְּנֵי הַשִּׁי״ן שֶׁעוֹשִׂין בָּעוֹר כְּמוֹ שֶׁאָמַרְנוּ. לְפִיכָךְ אִם חִפָּן הַכּוּתִי אוֹ תְּפָרָן פְּסוּלוֹת וְהוּא הַדִּין לְכָל הַפָּסוּל לְכָתְבָן שֶׁלֹּא יַעֲשֶׂה אוֹתָן:","תְּפִלָּה שֶׁל רֹאשׁ אֵין עוֹשִׂין אוֹתָהּ שֶׁל יָד וְשֶׁל יָד עוֹשִׂין אוֹתָהּ שֶׁל רֹאשׁ לְפִי שֶׁאֵין מוֹרִידִין מִקְּדֻשָּׁה חֲמוּרָה לִקְדֻשָּׁה קַלָּה. וְכֵן רְצוּעָה שֶׁל תְּפִלָּה שֶׁל רֹאשׁ אֵין עוֹשִׂין אוֹתָהּ לִתְפִלָּה שֶׁל יָד. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁלְּבָשָׁן. אֲבָל תְּפִלִּין שֶׁל רֹאשׁ שֶׁלֹּא לְבָשָׁן אָדָם מֵעוֹלָם אִם רָצָה לְהַחֲזִירָן לְיָד מֻתָּר. וְכֵיצַד עוֹשִׂין. טוֹלֶה עָלֶיהָ עוֹר עַד שֶׁתֵּעָשֶׂה אַחַת וְקוֹשְׁרָהּ עַל יָדוֹ:","תְּפִלִּין שֶׁנִּפְסְקוּ הַתְּפִירוֹת שֶׁלָּהֶן אִם הָיוּ שְׁתֵּי הַתְּפִירוֹת זוֹ בְּצַד זוֹ אוֹ שֶׁנִּפְסְקוּ שָׁלֹשׁ תְּפִירוֹת אֲפִלּוּ זוֹ שֶׁלֹּא כְּנֶגֶד זוֹ הֲרֵי אֵלּוּ פְּסוּלוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים בִּישָׁנוֹת אֲבָל בַּחֲדָשׁוֹת כָּל זְמַן שֶׁפְּנֵי טַבְלָן קַיָּמוֹת כְּשֵׁרוֹת. וְאֵלּוּ הֵן הַחֲדָשׁוֹת כָּל שֶׁאוֹחֲזִין מִקְצָת הָעוֹר שֶׁנִּקְרַע תִּפְרוֹ וְתוֹלִין בּוֹ הַתְּפִלִּין וְהוּא חָזָק וְאֵינוֹ נִכְרָת הֲרֵי אֵלּוּ חֲדָשׁוֹת. וְאִם אֵין רָאוּי לִתְלוֹת בּוֹ אֶלָּא הוּא נִפְסָק הֲרֵי אֵלּוּ יְשָׁנוֹת:","רְצוּעָה שֶׁנִּפְסְקָה אֵין קוֹשְׁרִין אוֹתָהּ וְאֵין תּוֹפְרִין אוֹתָהּ אֶלָּא מוֹצִיאָהּ וְגוֹנְזָהּ וְעוֹשִׂין אַחֶרֶת. וְשִׁיּוּרֵי הָרְצוּעָה פְּסוּלִין עַד שֶׁיְּהֵא אָרְכָּהּ וְרָחְבָּהּ כַּשִּׁעוּר אוֹ יָתֵר עָלָיו. וּלְעוֹלָם יִזָּהֵר לִהְיוֹת פְּנֵי הָרְצוּעָה לְמַעְלָה בְּעֵת שֶׁקּוֹשֵׁר אוֹתָן עַל יָדוֹ וְעַל רֹאשׁוֹ:"],"Mishneh Torah, Testimony 14":["כָּל מִי שֶׁאֵין אַתָּה מֵעיד לוֹ מִפְּנֵי שֶׁהוּא בַּעַל קְרוֹבָתְךָ. אִם מֵתָה אִשְׁתּוֹ אַף עַל פִּי שֶׁהִנִּיחָה לוֹ בָּנִים הֲרֵי זֶה נִתְרַחֵק וְכָשֵׁר:","מִי שֶׁהָיָה יוֹדֵעַ לַחֲבֵרוֹ עֵדוּת עַד שֶׁלֹּא נַעֲשָׂה חֲתָנוֹ וְנַעֲשָׂה חֲתָנוֹ. אוֹ שֶׁיָּדַע הָעֵדוּת וְהוּא פִּקֵּחַ וְאַחַר כָּךְ נִתְחָרֵשׁ. פָּתוּחַ וְנִסְתַּמֵּא אַף עַל פִּי שֶׁיָּכוֹל לְכַוֵּן מִדַּת הַקַּרְקַע שֶׁהוּא מֵעִיד בָּהּ וּמְסַיֵּם מְצָרֶיהָ. שָׁפוּי וְנִשְׁתַּטָּה. הֲרֵי זֶה פָּסוּל. אֲבָל אִם הָיָה יוֹדֵעַ לוֹ עֵדוּת עַד שֶׁלֹּא נַעֲשָׂה חֲתָנוֹ וְנַעֲשָׂה חֲתָנוֹ וּמֵתָה בִּתּוֹ. פִּקֵּחַ וְנִתְחָרֵשׁ וְחָזַר וְנִתְפַּקֵּחַ שָׁפוּי וְנִשְׁתַּטָּה וְחָזַר וְנִשְׁתַּפָּה פָּתוּחַ וְנִסְתַּמֵּא וְחָזַר וְנִתְפַּתֵּחַ כָּשֵׁר. זֶה הַכְּלָל כָּל שֶׁתְּחִלָּתוֹ וְסוֹפוֹ בְּכַשְׁרוּת אַף עַל פִּי שֶׁנִּפְסַל בֵּינְתַיִם כָּשֵׁר. תְּחִלָּתוֹ בְּפַסְלוּת אַף עַל פִּי שֶׁסּוֹפוֹ בְּכַשְׁרוּת פָּסוּל. לְפִיכָךְ מִי שֶׁהָיָה יוֹדֵעַ בְּעֵדוּת וְהוּא קָטָן וּבָא וְהֵעִיד בָּהּ כְּשֶׁהוּא גָּדוֹל אֵינָהּ כְּלוּם:","וְיֵשׁ דְּבָרִים שֶׁסּוֹמְכִין בָּהֶן עַל עֵדוּת שֶׁמֵּעִיד כְּשֶׁהוּא גָּדוֹל הוֹאִיל וְהֵם דְּבָרִים שֶׁל דִּבְרֵיהֶם. וְאֵלּוּ הֵן הַדְּבָרִים שֶׁאָדָם נֶאֱמָן לְהָעִיד בְּגָדְלוֹ עַל מַה שֶּׁרָאָה בְּקָטְנוֹ. נֶאֱמָן אָדָם לוֹמַר זֶה כְּתַב יָדוֹ שֶׁל אָבִי אוֹ שֶׁל רַבִּי אוֹ שֶׁל אָחִי מִפְּנֵי שֶׁקִּיּוּם שְׁטָרוֹת מִדִּבְרֵיהֶם. זָכוּר אֲנִי בִּפְלוֹנִית שֶׁנִּשֵּׂאת וְנַעֲשָׂה לָהּ מִנְהַג הַבְּתוּלוֹת. הוֹאִיל וְרֹב נָשִׁים בְּתוּלוֹת נִשָּׂאוֹת וּכְתֻבָּה מִדִּבְרֵיהֶם. שֶׁהַמָּקוֹם הַזֶּה בֵּית הַפְּרָס מִפְּנֵי שֶׁטֻּמְאָתוֹ מִדִּבְרֵיהֶם. וְעַד כָּאן הָיִינוּ בָּאִין בְּשַׁבָּת שֶׁצִּמְצוּם הַתְּחוּם עַד אַלְפַּיִם אַמָּה בִּלְבַד מִדִּבְרֵיהֶם. שֶׁהָיָה אִישׁ פְּלוֹנִי יוֹצֵא מִבֵּית הַסֵּפֶר לִטְבּל וְלֶאֱכל בִּתְרוּמָתוֹ לָעֶרֶב. וְשֶׁהָיָה חוֹלֵק עִמָּנוּ תְּרוּמָה. וְשֶׁהָיִינוּ מוֹלִיכִים חַלָּה וּמַתָּנוֹת לִפְלוֹנִי כֹּהֵן עַל יְדֵי עַצְמוֹ. וְאָמַר לִי אַבָּא מִשְׁפָּחָה זוֹ כְּשֵׁרָה מִשְׁפָּחָה זוֹ פְּסוּלָה. וְאָכַלְנוּ בַּקֳצָצָה שֶׁל פְּלוֹנִי שֶׁהֶאֱכִילוּנִי אֶחָיו כְּדֵי לְהוֹדִיעַ שֶׁאֲחִיהֶם פְּלוֹנִי נָשָׂא אִשָּׁה שֶׁאֵינָהּ הוֹגֶנֶת לוֹ. שֶׁכָּל אֵלּוּ הַדְּבָרִים לְהַחֲזִיק זֶה הַכֹּהֵן לֶאֱכל בִּתְרוּמָה שֶׁל דִּבְרֵיהֶם אוֹ לִדְחוֹתוֹ מִמֶּנָּה:","כָּל אֵלּוּ שֶׁמֵּעִיד בָּהֶן הַגָּדוֹל בְּמַה שֶּׁיָּדַע כְּשֶׁהָיָה קָטָן. אִם הָיָה עַכּוּ\"ם אוֹ עֶבֶד כְּשֶׁרָאָה דְּבָרִים אֵלּוּ וְהֵעִיד אַחַר שֶׁנִּתְגַּיֵּר וְנִשְׁתַּחְרֵר אֵינוֹ נֶאֱמָן:","מִי שֶׁהָיָה יוֹדֵעַ לַחֲבֵרוֹ בְּעֵדוּת עַד שֶׁלֹּא נַעֲשָׂה גַּזְלָן וְנַעֲשָׂה גַּזְלָן. הוּא אֵינוֹ מֵעִיד עַל כְּתַב יָדוֹ. אֲבָל אִם הֻחְזַק כְּתַב יָדוֹ שֶׁבִּשְׁטָר זֶה בְּבֵית דִּין קֹדֶם שֶׁיֵּעָשֶׂה גַּזְלָן הֲרֵי זֶה שְׁטַר כָּשֵׁר. וְכֵן אִם נַעֲשָׂה חֲתָנוֹ הוּא אֵינוֹ מֵעִיד עַל כְּתַב יָדוֹ אֲבָל אֲחֵרִים מְעִידִין. אַף עַל פִּי שֶׁלֹּא הֻחְזַק בְּבֵית דִּין אֶלָּא אַחַר שֶׁנַּעֲשָׂה חֲתָנוֹ הֲרֵי זֶה כָּשֵׁר. שֶׁאֵינוֹ דּוֹמֶה הַפָּסוּל בַּעֲבֵרָה לְפָסוּל בִּקְרִיבָה. שֶׁהַפָּסוּל בַּעֲבֵרָה חָשׁוּד לְזַיֵּף:","שְׁטָר שֶׁיֵּשׁ בּוֹ שְׁנֵי עֵדִים בִּלְבַד וּשְׁנֵיהֶם קְרוֹבִים זֶה לָזֶה אוֹ אֶחָד מִשְּׁנֵיהֶם פָּסוּל בַּעֲבֵרָה. אַף עַל פִּי שֶׁמָּסַר לוֹ הַשְּׁטָר בִּפְנֵי עֵדִים כְּשֵׁרִים הֲרֵי הוּא כְּחֶרֶס מִפְּנֵי שֶׁהוּא מְזֻיָּף מִתּוֹכוֹ:","הַכּוֹתֵב כָּל נְכָסָיו לִשְׁנֵי בְּנֵי אָדָם בְּעֵדוּת אַחַת וְהָעֵדִים קְרוֹבִים לְאֶחָד מִמְּקַבְּלֵי הַמַּתָּנָה וּרְחוֹקִים מִן הַשֵּׁנִי. הֲרֵי הַשְּׁטָר פָּסוּל מִפְּנֵי שֶׁהוּא עֵדוּת אַחַת. אֲבָל אִם כָּתַב בִּשְׁטָר אֶחָד שֶׁנָּתַתִּי לִרְאוּבֵן חָצֵר פְּלוֹנִית וְשֶׁנָּתַתִּי לְשִׁמְעוֹן שָׂדֶה פְּלוֹנִית. נִמְצְאוּ הָעֵדִים קְרוֹבִים לָזֶה וּרְחוֹקִים מִזֶּה. זֶה שֶׁהֵם רְחוֹקִים מִמֶּנּוּ מַתְּנָתוֹ קַיֶּמֶת שֶׁאֵלּוּ שְׁתֵּי עֵדוּיוֹת אַף עַל פִּי שֶׁהֵן בִּשְׁטָר אֶחָד. לְמָה זֶה דּוֹמֶה לְאוֹמֵר הֱיוּ עָלַי עֵדִים שֶׁנָּתַתִּי לִרְאוּבֵן כָּךְ וְכָךְ וְשֶׁנָּתַתִּי לְשִׁמְעוֹן כָּךְ וְכָךְ וְשֶׁלָּוִיתִי מִלֵּוִי כָּךְ וְכָךְ שֶׁאַף עַל פִּי שֶׁכָּתַב בִּשְׁטָר אֶחָד וְהַמַּקְנֶה אִישׁ אֶחָד הֲרֵי אֵלּוּ שָׁלֹשׁ עֵדֻיּוֹת שֶׁאֵינָן תְּלוּיוֹת זוֹ בָּזוֹ:"],"Mishneh Torah, Testimony 5":["אֵין חוֹתְכִין דִּין מִן הַדִּינִין עַל פִּי עֵד אֶחָד לֹא דִּינֵי מָמוֹנוֹת וְלֹא דִּינֵי נְפָשׁוֹת. שֶׁנֶּאֱמַר (דברים יט טו) \"לֹא יָקוּם עֵד אֶחָד בְּאִישׁ לְכָל עָוֹן וּלְכָל חַטָּאת\". וּמִפִּי הַשְּׁמוּעָה לָמַדְנוּ שֶׁקָּם הוּא לִשְׁבוּעָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת טוֹעֵן:","בִּשְׁנֵי מְקוֹמוֹת הֶאֱמִינָה תּוֹרָה עֵד אֶחָד. בְּסוֹטָה שֶׁלֹּא תִּשְׁתֶּה מֵי מָרִים וּבְעֶגְלָה עֲרוּפָה שֶׁלֹּא תֵּעָרֵף כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן מִדִּבְרֵיהֶן בְּעֵדוּת אִשָּׁה שֶׁיָּעִיד לָהּ שֶׁמֵּת בַּעְלָהּ:","וְכָל מָקוֹם שֶׁעֵד אֶחָד מוֹעִיל אִשָּׁה וּפָסוּל כְּמוֹ כֵן מְעִידִים. חוּץ מֵעֵד אֶחָד שֶׁל שְׁבוּעָה שֶׁאֵין מְחַיְּבִין שְׁבוּעָה אֶלָּא בְּעֵדוּת כָּשֵׁר הָרָאוּי לְהִצְטָרֵף עִם אַחֵר וְיִתְחַיֵּב זֶה הַנִּשְׁבָּע מָמוֹן עַל פִּיו. עַל פִּי שְׁנַיִם עֵדִים אוֹ עַל פִּי שְׁלֹשָׁה עֵדִים לַעֲשׂוֹת שְׁלֹשָׁה כִּשְׁנַיִם מַה שְּׁנַיִם נִמְצָא אֶחָד מֵהֶן קָרוֹב אוֹ פָּסוּל בָּטֵל הָעֵדוּת אַף שְׁלֹשָׁה וְהוּא הַדִּין לְמֵאָה. נִמְצָא אֶחָד מֵהֶן קָרוֹב אוֹ פָּסוּל בְּטֵלָה הָעֵדוּת בֵּין בְּדִינֵי מָמוֹנוֹת בֵּין בְּדִינֵי נְפָשׁוֹת:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁנִּתְכַּוְּנוּ כֻּלָּם לְהָעִיד. אֲבָל אִם לֹא נִתְכַּוְּנוּ כֻּלָּם לְהָעִיד מַה יַּעֲשׂוּ שְׁנֵי אַחִים בִּכְלַל הָעָם וְרָאוּ הָעָם כְּשֶׁהָרַג זֶה אֶת זֶה אוֹ כְּשֶׁחָבַל בּוֹ אוֹ כְּשֶׁחָטַף חֵפֶץ מִיָּדוֹ:","וְכֵיצַד בּוֹדְקִין אֶת הַדָּבָר. כְּשֶׁיָּבוֹאוּ לְבֵית דִּין עֵדִים מְרֻבִּין. כַּת אַחַת אוֹמֵר לָהֶם כְּשֶׁרְאִיתֶם זֶה שֶׁהָרַג אוֹ חָבַל לְהָעִיד בָּאתֶם אוֹ לִרְאוֹת. כָּל מִי שֶׁאוֹמֵר לֹא לְהָעִיד עָלָיו אֶלָּא לִרְאוֹת מָה הַדָּבָר וּבִכְלַל הָעָם בָּאתִי מַפְרִישִׁין אוֹתוֹ. וְכָל מִי שֶׁאוֹמֵר לֹא הָיִיתִי עוֹמֵד אֶלָּא לְהָעִיד וּלְכַוֵּן הָעֵדוּת מַפְרִישִׁין אוֹתוֹ. אִם נִמְצָא בְּאֵלּוּ שֶׁנִּתְכַּוְּנוּ לְהָעִיד קָרוֹב אוֹ פָּסוּל עֵדוּת כֻּלָּם בְּטֵלָה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה בָּהֶן קָרוֹב אוֹ פָּסוּל. אֲבָל אִם כֻּלָּם כְּשֵׁרִים אֶחָד שֶׁנִּתְכַּוֵּן לְהָעִיד אוֹ שֶׁלֹּא נִתְכַּוֵּן לְהָעִיד הוֹאִיל וְרָאָה הַדָּבָר וְכִוֵּן עֵדוּתוֹ וְהָיָה שָׁם הַתְרָאָה חוֹתְכִין הַדִּין עַל פִּיו. בֵּין בְּדִינֵי מָמוֹנוֹת בֵּין בְּדִינֵי נְפָשׁוֹת:","שְׁטָר שֶׁהָיוּ עֵדָיו מְרֻבִּין וְנִמְצָא אֶחָד מֵהֶן קָרוֹב אוֹ פָּסוּל אוֹ שֶׁהָיוּ בָּהֶם שְׁנַיִם קְרוֹבִים זֶה לָזֶה. וַהֲרֵי אֵין הָעֵדִים קַיָּמִין כְּדֵי לִשְׁאל אוֹתָן. אִם יֵשׁ שָׁם עֵדוּת בְּרוּרָה שֶׁכֻּלָּם יָשְׁבוּ לַחְתֹּם שֶׁהֲרֵי נִתְכַּוְּנוּ לְהָעִיד הֲרֵי זֶה בָּטֵל. וְאִם לָאו תִּתְקַיֵּם הָעֵדוּת בַּשְּׁאָר. וְלָמָּה מְקַיְּמִין הָעֵדוּת בַּשְּׁאָר שֶׁהֲרֵי אֶפְשָׁר שֶׁחָתְמוּ הַכְּשֵׁרִים וְהִנִּיחוּ מָקוֹם לַגָּדוֹל לַחְתֹּם וּבָא זֶה הַקָּרוֹב אוֹ הַפָּסוּל וְחָתַם שֶׁלֹּא מִדַּעְתָּם:","אַף עַל פִּי שֶׁהָעֵד שֶׁחָתוּם מִתְּחִלָּה בַּשְּׁטָר הוּא הַפָּסוּל הֲרֵי הַשְּׁטָר כָּשֵׁר:","כָּל עֵד שֶׁהֵעִיד בְּדִינֵי נְפָשׁוֹת אֵינוֹ מוֹרֶה בְּדִין זֶה הַנֶּהֱרָג וְלֹא יְלַמֵּד עָלָיו לֹא זְכוּת וְלֹא חוֹבָה. וְאִם אָמַר יֵשׁ לִי לְלַמֵּד עָלָיו זְכוּת מְשַׁתְּקִין אוֹתוֹ שֶׁנֶּאֱמַר (במדבר לה ל) \"וְעֵד אֶחָד לֹא יַעֲנֶה בְנֶפֶשׁ לָמוּת\". בֵּין לִזְכוּת בֵּין לְחוֹבָה. וּמַהוּ זֶה שֶׁנֶּאֱמַר לָמוּת כְּלוֹמַר עֵד שֶׁהֵעִיד בְּנֶפֶשׁ לָמוּת לֹא יַעֲנֶה דָּבָר אֶלָּא יָעִיד וְיִשְׁתֹּק. אֲבָל בְּדִינֵי מָמוֹנוֹת יֵשׁ לוֹ לְלַמֵּד עָלָיו זְכוּת אוֹ חוֹבָה. אֲבָל לֹא יִמָּנֶה עִם הַדַּיָּנִים וְלֹא יֵעָשֶׂה דַּיָּן שֶׁאֵין עֵד נַעֲשֶׂה דַּיָּן אֲפִלּוּ בְּדִינֵי מָמוֹנוֹת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּדָבָר שֶׁצָּרִיךְ עֵדִים מִן הַתּוֹרָה וְצָרִיךְ דַּיָּנִים לָדוּן בְּאוֹתוֹ הַדָּבָר מִן הַתּוֹרָה. אֲבָל בְּשֶׁל דִּבְרֵיהֶם עֵד נַעֲשֶׂה דַּיָּן. כֵּיצַד. אֶחָד שֶׁהֵבִיא הַגֵּט וְאָמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם. הוּא וּשְׁנַיִם נוֹתְנִין אוֹתוֹ לָהּ וְנִמְצָא כְּאִלּוּ נְטָלוּהוּ מִבֵּית דִּין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, The Chosen Temple 8":["שְׁמִירַת הַמִּקְדָּשׁ מִצְוַת עֲשֵׂה. וְאַף עַל פִּי שֶׁאֵין שָׁם פַּחַד מֵאוֹיְבִים וְלֹא מִלִּסְטִים. שֶׁאֵין שְׁמִירָתוֹ אֶלָּא כָּבוֹד לוֹ. אֵינוֹ דּוֹמֶה פַּלְטֵרִין שֶׁיֵּשׁ עָלָיו שׁוֹמְרִין לְפַלְטֵרִין שֶׁאֵין עָלָיו שׁוֹמְרִין:","וּשְׁמִירָה זוֹ מִצְוָתָהּ כָּל הַלַּיְלָה. וְהַשּׁוֹמְרִים הֵם הַכֹּהֲנִים וְהַלְוִיִּם שֶׁנֶּאֱמַר (במדבר יח ב) \"וְאַתָּה וּבָנֶיךָ אִתָּךְ לִפְנֵי אֹהֶל הָעֵדֻת\". כְּלוֹמַר אַתֶּם תִּהְיוּ שׁוֹמְרִים לוֹ. וַהֲרֵי נֶאֱמַר (במדבר יח ד) \"וְשָׁמְרוּ אֶת מִשְׁמֶרֶת אֹהֶל מוֹעֵד\" וְנֶאֱמַר (במדבר ג לח) \"וְהַחֹנִים קֵדְמָה לִפְנֵי אֹהֶל מוֹעֵד מִזְרָחָה משֶׁה וְאַהֲרֹן וּבָנָיו שֹׁמְרֵי מִשְׁמֶרֶת הַקֹּדֶשׁ\":","וְאִם בִּטְּלוּ שְׁמִירָה עָבְרוּ בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (במדבר יח ה) \"וְשָׁמְרוּ אֶת מִשְׁמֶרֶת הַקֹּדֶשׁ\". וּלְשׁוֹן שְׁמִירָה אַזְהָרָה הִיא הָא לָמַדְתָּ שֶׁשְּׁמִירָתוֹ מִצְוַת עֲשֵׂה. וּבִטּוּל שְׁמִירָתוֹ מִצְוַת לֹא תַּעֲשֶׂה:","מִצְוַת שְׁמִירָתוֹ שֶׁיִּהְיוּ הַכֹּהֲנִים שׁוֹמְרִים מִבִּפְנִים וְהַלְוִיִּם מִבַּחוּץ. וְכ\"ד עֵדָה שׁוֹמְרִין אוֹתוֹ בְּכָל לַיְלָה תָּמִיד בְּכ\"ד מָקוֹם. הַכֹּהֲנִים בִּשְׁלֹשָׁה מְקוֹמוֹת וְהַלְוִיִּם בְּכ\"א מָקוֹם:","וְהֵיכָן הָיוּ שׁוֹמְרִים. כֹּהֲנִים הָיוּ שׁוֹמְרִים בְּבֵית אַבְטִינַס וּבְבֵית הַנִּיצוֹץ וּבְבֵית הַמּוֹקֵד. בֵּית אַבְטִינַס וּבֵית הַנִּיצוֹץ הָיוּ עֲלִיּוֹת בְּנוּיוֹת בְּצַד שַׁעֲרֵי הָעֲזָרָה וְהָרוֹבִין הָיוּ שׁוֹמְרִים שָׁם. בֵּית הַמּוֹקֵד כִּפָּה וּבַיִת גָּדוֹל הָיָה מֻקָּף רְבָדִין שֶׁל אֶבֶן וְזִקְנֵי בֵּית אָב שֶׁל אוֹתוֹ הַיּוֹם הָיוּ יְשֵׁנִים שָׁם וּמַפְתְּחוֹת הָעֲזָרָה בְּיָדָם:","לֹא הָיוּ הַכֹּהֲנִים הַשּׁוֹמְרִים יְשֵׁנִים בְּבִגְדֵי כְּהֻנָּה אֶלָּא מְקַפְּלִין אוֹתָן וּמַנִּיחִין אוֹתָן כְּנֶגֶד רָאשֵׁיהֶן וְלוֹבְשִׁין בִּגְדֵי עַצְמָן וִישֵׁנִים עַל הָאָרֶץ. כְּדֶרֶךְ כָּל שׁוֹמְרֵי חַצְרוֹת הַמְּלָכִים שֶׁלֹּא יִישְׁנוּ עַל הַמִּטּוֹת:","אֵרַע קֶרִי לָאֶחָד מֵהֶן. הוֹלֵךְ בַּמְּסִבָּה שֶׁתַּחַת הַקַּרְקַע שֶׁהַמְּחִלּוֹת הַפְּתוּחוֹת לְהַר הַבַּיִת לֹא נִתְקַדְּשׁוּ וְטוֹבֵל וְחוֹזֵר וְיוֹשֵׁב אֵצֶל אֶחָיו הַכֹּהֲנִים עַד שֶׁנִּפְתָּחִין הַשְּׁעָרִים בַּבֹּקֶר יוֹצֵא וְהוֹלֵךְ לוֹ:","וְהֵיכָן הָיוּ הַלְוִיִּם שׁוֹמְרִים. עַל חֲמִשָּׁה שַׁעֲרֵי הַר הַבַּיִת. וְעַל אַרְבַּע פִּנּוֹתָיו מִתּוֹכוֹ. וְעַל אַרְבַּע פִּנּוֹת הָעֲזָרָה מִבַּחוּץ שֶׁאָסוּר לֵישֵׁב בָּעֲזָרָה. וְעַל חֲמִשָּׁה שַׁעֲרֵי הָעֲזָרָה חוּץ לָעֲזָרָה שֶׁהֲרֵי הַכֹּהֲנִים שׁוֹמְרִים עַל שַׁעַר הַמּוֹקֵד וְעַל שַׁעַר הַנִּיצוֹץ. הֲרֵי שְׁמוֹנָה עָשָׂר מָקוֹם:","וְעוֹד שׁוֹמְרִים בְּלִשְׁכַּת הַקָּרְבָּן וּבְלִשְׁכַּת הַפָּרֹכֶת וַאֲחוֹרֵי בֵּית הַכַּפֹּרֶת:","וּמַעֲמִידִין מְמֻנֶּה אֶחָד עַל כָּל מִשְׁמְרוֹת הַשּׁוֹמְרִים. וְאִישׁ הַר הַבַּיִת הָיָה נִקְרָא. וְהָיָה מְחַזֵּר עַל כָּל מִשְׁמָר וּמִשְׁמָר כָּל הַלַּיְלָה. וַאֲבוּקוֹת דְּלוּקוֹת לְפָנָיו. וְכָל מִשְׁמָר שֶׁאֵינוֹ עוֹמֵד וְאוֹמֵר לוֹ אִישׁ הַר הַבַּיִת שָׁלוֹם עָלֶיךָ נִכָּר שֶׁהוּא יָשֵׁן חוֹבְטוֹ בְּמַקְּלוֹ. וּרְשׁוּת הָיָה לוֹ לִשְׂרֹף אֶת כְּסוּתוֹ עַד שֶׁהָיוּ אוֹמְרִין בִּירוּשָׁלַיִם מַה קּוֹל בָּעֲזָרָה קוֹל בֶּן לֵוִי לוֹקֶה וּבְגָדָיו נִשְׂרָפִין שֶׁיָּשַׁן עַל מִשְׁמַרְתּוֹ:","בַּשַּׁחַר קֹדֶם שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר סָמוּךְ לוֹ יָבוֹא הַמְמֻנֶּה שֶׁל מִקְדָּשׁ וְיִדְפֹּק עַל הַכֹּהֲנִים שֶׁבְּבֵית הַמּוֹקֵד וְהֵן פּוֹתְחִין לוֹ. נָטַל אֶת הַמַּפְתֵּחַ וּפָתַח אֶת הַשַּׁעַר הַקָּטָן שֶׁבֵּין בֵּית הַמּוֹקֵד וּבֵין הָעֲזָרָה וְנִכְנַס מִבֵּית הַמּוֹקֵד לָעֲזָרָה וְנִכְנְסוּ אַחֲרָיו הַכֹּהֲנִים וּשְׁתֵּי אֲבוּקוֹת שֶׁל אוּר בְּיָדָם וְנֶחְלְקוּ לִשְׁתֵּי כִּתּוֹת. כַּת הוֹלֶכֶת לְמִזְרָח וְכַת הוֹלֶכֶת לְמַעֲרָב. וְהָיוּ בּוֹדְקִין וְהוֹלְכִין אֶת כָּל הָעֲזָרָה עַד שֶׁיַּגִּיעוּ שְׁתֵּי הַכִּתּוֹת לִמְקוֹם בֵּית עוֹשֵׂי חֲבִיתִין. הִגִּיעוּ אֵלּוּ וְאֵלּוּ אוֹמְרִין שָׁלוֹם הַכּל שָׁלוֹם. וְהֶעֱמִידוּ עוֹשֵׂי חֲבִיתִין לַעֲשׂוֹת חֲבִיתִין:","כַּסֵּדֶר הַזֶּה עוֹשִׂין בְּכָל לַיְלָה וְלַיְלָה חוּץ מִלֵּילֵי שַׁבָּת שֶׁאֵין בְּיָדָם אוּר אֶלָּא בּוֹדְקִין בַּנֵּרוֹת הַדְּלוּקִין שָׁם מֵעֶרֶב שַׁבָּת:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 15":["כֵּיצַד מִצְוַת הַנִּסְקָלִין. רָחוֹק מִבֵּית הַסְּקִילָה אַרְבַּע אַמּוֹת מַפְשִׁיטִין אֶת הַמְחֻיָּב סְקִילָה בְּגָדָיו וּמְכַסִּין עֶרְוָתוֹ מִלְּפָנָיו. וְאֵין הָאִשָּׁה נִסְקֶלֶת עֲרֻמָּה אֶלָּא בְּחָלוּק אֶחָד. וּבֵית הַסְּקִילָה גָּבוֹהַּ שְׁתֵּי קוֹמוֹת עוֹלֶה לְשָׁם הוּא וְעֵדָיו וְיָדָיו אֲסוּרוֹת. וְאֶחָד מִן הָעֵדִים דּוֹחֲפוֹ עַל מָתְנָיו מֵאֲחוֹרָיו וְהוּא נֶהֱפָךְ וְנוֹפֵל עַל לִבּוֹ לָאָרֶץ. אִם מֵת בָּהּ יָצָא שֶׁהֲרֵי נֶאֱמַר (שמות יט יג) \"סָקוֹל יִסָּקֵל אוֹ יָרֹה יִיָּרֶה\" הִנֵּה הִשְׁוָה הַנִּסְקָל שֶׁנָּפַל אֶת הָאֶבֶן עָלָיו עִם הַנִּדְחָף שֶׁנָּפַל הוּא בְּעַצְמוֹ עַל הָאָרֶץ. וְאִם לֹא מֵת מִדְּחִיפָה זוֹ מַגְבִּיהִין הָעֵדִים אֶבֶן שֶׁהָיְתָה מֻנַּחַת שָׁם מַשָּׂא שְׁנֵי בְּנֵי אָדָם וְהָעֵד הַשֵּׁנִי מַרְפֶּה אֶת יָדוֹ וּמַשְׁלִיךְ הָאֶבֶן עַל לִבּוֹ. אִם מֵת בּוֹ יָצָא וְאִם לָאו רְגִימָתוֹ בְּכָל יִשְׂרָאֵל שֶׁנֶּאֱמַר (דברים יז ז) \"יַד הָעֵדִים תִּהְיֶה בּוֹ בָרִאשֹׁנָה לַהֲמִיתוֹ וְיַד כָּל הָעָם בָּאַחֲרֹנָה\":","עוֹבֵד עֲבוֹדָה זָרָה אֵין סוֹקְלִין אוֹתוֹ אֶלָּא עַל שַׁעַר שֶׁעָבַד בּוֹ. וְאִם הָיְתָה עִיר שֶׁרֻבָּהּ עַכּוּ\"ם סוֹקְלִין אוֹתוֹ עַל פֶּתַח בֵּית דִּין. וְדָבָר זֶה קַבָּלָה מִפִּי הַשְּׁמוּעָה אֶל שְׁעָרֶיךָ זֶה שַׁעַר שֶׁעָבַד בּוֹ וְלֹא שֶׁנִּגְמַר דִּינוֹ בּוֹ:","מִצְוַת הַנִּשְׂרָפִין הָיוּ מְשַׁקְּעִין אוֹתוֹ בְּזֶבֶל עַד אַרְכֻּבּוֹתָיו וְנוֹתְנִים סוּדָר קָשֶׁה לְתוֹךְ הָרַךְ וְכוֹרֵךְ עַל צַוָּארוֹ. וּשְׁנֵי עֵדָיו זֶה מוֹשֵׁךְ אֶצְלוֹ וְזֶה מוֹשֵׁךְ אֶצְלוֹ עַד שֶׁהוּא פּוֹתֵחַ אֶת פִּיו. וּמַתִּיכִים אֶת הַבְּדִיל וְאֶת הָעוֹפֶרֶת וְכַיּוֹצֵא בָּהֶן וְהוּא זוֹרֵק לְתוֹךְ פִּיו וְהִיא יוֹרֶדֶת וְשׂוֹרֶפֶת אֶת בְּנֵי מֵעָיו:","מִצְוַת הַנֶּהֱרָגִין מַתִּיזִין אֶת רֹאשׁוֹ בְּסַיִף כְּדֶרֶךְ שֶׁהַמְּלָכִים עוֹשִׂים:","מִצְוַת הַנֶּחְנָקִין מְשַׁקְּעִין אֶת הַמְחֻיָּב בְּזֶבֶל עַד אַרְכֻּבּוֹתָיו וְנוֹתְנִין סוּדָר קָשֶׁה לְתוֹךְ הָרַךְ וְכוֹרְכִין עַל צַוָּארוֹ זֶה מוֹשֵׁךְ אֶצְלוֹ וְזֶה מוֹשֵׁךְ אֶצְלוֹ עַד שֶׁתֵּצֵא נַפְשׁוֹ:","מִצְוַת עֲשֵׂה לִתְלוֹת אֶת הַמְגַדֵּף וְעוֹבֵד עַכּוּ\"ם שֶׁנֶּאֱמַר (דברים כא כג) \"כִּי קִלְלַת אֱלֹהִים תָּלוּי\" הֲרֵי מְגַדֵּף אָמוּר וּבְעוֹבֵד עַכּוּ\"ם נֶאֱמַר (במדבר טו ל) \"אֶת ה' הוּא מְגַדֵּף\". וְהָאִישׁ נִתְלֶה וְאֵין הָאִשָּׁה נִתְלֵית שֶׁנֶּאֱמַר (דברים כא כב) \"כִּי יִהְיֶה בְאִישׁ חֵטְא מִשְׁפַּט מָוֶת וְהוּמָת וְתָלִיתָ אֹתוֹ\":","כֵּיצַד מִצְוַת הַנִּתְלִין. אַחַר שֶׁסּוֹקְלִין אוֹתָן מְשַׁקְּעִין אֶת הַקּוֹרָה בָּאָרֶץ וְעֵץ יוֹצֵא מִמֶּנָּה וּמַקִּיפִין שְׁתֵּי יָדָיו זוֹ לָזוֹ וְתוֹלֵהוּ סָמוּךְ לִשְׁקִיעַת הַחַמָּה וּמַתִּירִין אוֹתוֹ מִיָּד. וְאִם לָן עוֹבְרִין עָלָיו בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כא כג) \"לֹא תָלִין נִבְלָתוֹ עַל הָעֵץ\":","וּמִצְוַת עֲשֵׂה לִקְבֹּר אֶת כָּל הֲרוּגֵי בֵּית דִּין בְּיוֹם הַהֲרִיגָה שֶׁנֶּאֱמַר (דברים כא כג) \"כִּי קָבוֹר תִּקְבְּרֶנּוּ בַּיּוֹם הַהוּא\". וְלֹא הֲרוּגֵי בֵּית דִּין בִּלְבַד אֶלָּא כָּל הַמֵּלִין אֶת מֵתוֹ עוֹבֵר עָלָיו בְּלֹא תַּעֲשֶׂה. הֱלִינוֹ לִכְבוֹדוֹ לְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין אֵינוֹ עוֹבֵר עָלָיו:","אֵין תּוֹלִין עַל אִילָן הַמְחֻבָּר לַקַּרְקַע אֶלָּא עַל הַתָּלוּשׁ כְּדֵי שֶׁלֹּא יְהֵא מְחֻסַּר קְצִיצָה. שֶׁהָעֵץ שֶׁנִּתְלָה עָלָיו נִקְבָּר עִמּוֹ שֶׁלֹּא יְהֵא לוֹ זִכָּרוֹן רַע וְיֹאמְרוּ זֶה הָעֵץ שֶׁנִּתְלָה עָלָיו פְּלוֹנִי. וְכֵן הָאֶבֶן שֶׁנִּסְקַל בָּהּ וְהַסַּיִף שֶׁנֶּהֱרַג בּוֹ הַנֶּהֱרָג וְהַסּוּדָרִין שֶׁחוֹנְקִין בָּהֶן הַכּל נִקְבָּרִין בִּתְפִישַׂת הַנֶּהֱרָג אֲבָל לֹא בַּקֶּבֶר עַצְמוֹ:","כָּל הַנִּסְקָלִין שֶׁבַּתּוֹרָה שְׁמוֹנָה עָשָׂר וְאֵלּוּ הֵן. הַבָּא עַל הָאֵם. וְעַל אֵשֶׁת אָב. וְעַל כַּלָּתוֹ. וְעַל נַעֲרָה הַמְאֹרָסָה. וְעַל הַזָּכוּר. וְהַשּׁוֹכֵב עִם בְּהֵמָה. וְהָאִשָּׁה הַמְּבִיאָה אֶת הַבְּהֵמָה עָלֶיהָ. וְהַמְגַדֵּף. וְעוֹבֵד עַכּוּ\"ם. וְהַנּוֹתֵן מִזַּרְעוֹ לַמּלֶךְ. וּבַעַל אוֹב. וּבַעַל יִדְּעוֹנִי. וְהַמַּסִּית. וְהַמַּדִּיחַ. וְהַמְכַשֵּׁף. וְהַמְחַלֵּל אֶת הַשַּׁבָּת. וּמְקַלֵּל אָבִיו אוֹ אִמּוֹ. וּבֶן סוֹרֵר וּמוֹרֶה:","כָּל הַנִּשְׂרָפִין עֲשָׂרָה וְאֵלּוּ הֵן. בַּת כֹּהֵן שֶׁזִּנְּתָה תַּחַת בַּעְלָהּ. וּבָא עַל בִּתּוֹ. וְעַל בַּת בִּתּוֹ. וְעַל בַּת בְּנוֹ. וְעַל בַּת אִשְׁתּוֹ. וְעַל בַּת בִּתָּהּ. וְעַל בַּת בְּנָהּ. וְעַל חֲמוֹתוֹ. וְעַל אֵם חֲמוֹתוֹ. וְעַל אֵם חָמִיו. וְהוּא שֶׁבָּא עֲלֵיהֶן בְּחַיֵּי אִשְׁתּוֹ. אֲבָל לְאַחַר מִיתַת אִשְׁתּוֹ הֲרֵי הֵן בְּכָרֵת בִּלְבַד בִּכְלַל הָעֲרָיוֹת:","הַנֶּהֱרָגִין שְׁנַיִם. הָרוֹצֵחַ וְהַנִּדָּח:","הַנֶּחְנָקִין שִׁשָּׁה וְאֵלּוּ הֵן. הַבָּא עַל אֵשֶׁת אִישׁ. הַחוֹבֵל בְּאָבִיו אוֹ בְּאִמּוֹ. וְגוֹנֵב נֶפֶשׁ מִיִּשְׂרָאֵל. וְזָקֵן מַמְרֵא. וּנְבִיא הַשֶּׁקֶר. וְהַמִּתְנַבֵּא בְּשֵׁם עֲבוֹדָה זָרָה. נִמְצְאוּ כָּל הֲרוּגֵי בֵּית דִּין שִׁשָּׁה וּשְׁלֹשִׁים:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 26":["כָּל הַמְקַלֵּל דַּיָּן מִדַּיָּנֵי יִשְׂרָאֵל עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כב כז) \"אֱלֹהִים לֹא תְקַלֵּל\". וְכֵן אִם קִלֵּל הַנָּשִׂיא אֶחָד רֹאשׁ סַנְהֶדְרִי גְּדוֹלָה אוֹ הַמֶּלֶךְ הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כב כז) \"וְנָשִׂיא בְעַמְּךָ לֹא תָאֹר\". וְלֹא דַּיָּן וְנָשִׂיא בִּלְבַד אֶלָּא כָּל הַמְקַלֵּל אֶחָד מִיִּשְׂרָאֵל לוֹקֶה שֶׁנֶּאֱמַר (ויקרא יט יד) \"לֹא תְקַלֵּל חֵרֵשׁ\". וְלָמָּה נֶאֱמַר חֵרֵשׁ שֶׁאֲפִלּוּ זֶה שֶׁהוּא אֵינוֹ שׁוֹמֵעַ וְלֹא נִצְטַעֵר בִּקְלָלָה זוֹ לוֹקֶה עַל קִלְלָתוֹ. וְיֵרָאֶה לִי שֶׁהַמְקַלֵּל אֶת הַקָּטָן הַנִּכְלָם לוֹקֶה (הֲרֵי הוּא כְחֵרֵשׁ):","הַמְקַלֵּל אֶת הַמֵּת פָּטוּר. הוֹאִיל וּמְקַלֵּל כָּל אָדָם מִיִּשְׂרָאֵל חַיָּב לָמָּה יִחֵד לָאו עַל דַּיָּן וְלָאו עַל נָשִׂיא לְחַיְּבוֹ שְׁתַּיִם. נִמְצֵאתָ לָמֵד שֶׁהַמְקַלֵּל אֶחָד מִיִּשְׂרָאֵל בֵּין אִישׁ בֵּין אִשָּׁה בֵּין גָּדוֹל בֵּין קָטָן לוֹקֶה אַחַת. וְאִם קִלֵּל דַּיָּן לוֹקֶה שְׁתַּיִם. וְאִם קִלֵּל נָשִׂיא לוֹקֶה שָׁלֹשׁ. וּבֵן נָשִׂיא שֶׁקִּלֵּל אָבִיו חַיָּב מִשּׁוּם אַרְבָּעָה שֵׁמוֹת. שְׁלֹשָׁה שֶׁל כָּל אָדָם וְאֶחָד מִשּׁוּם הָאָב:","הַמְקַלֵּל עַצְמוֹ לוֹקֶה כְּמוֹ שֶׁקִּלֵּל אֲחֵרִים שֶׁנֶּאֱמַר (דברים ד ט) \"הִשָּׁמֶר לְךָ וּשְׁמֹר נַפְשְׁךָ\". וְאֶחָד הַמְקַלֵּל עַצְמוֹ אוֹ חֲבֵרוֹ אוֹ נָשִׂיא אוֹ דַּיָּן אֵינוֹ לוֹקֶה עַד שֶׁיְּקַלֵּל בְּשֵׁם מִן הַשֵּׁמוֹת. כְּגוֹן יָהּ וֵאלֹהִים וְשַׁדַּי וְכַיּוֹצֵא בָּהֶן. אוֹ בְּכִנּוּי מִן הַכִּנּוּיִים כְּגוֹן חַנּוּן וְקַנֹּא וְכַיּוֹצֵא בָּהֶן. הוֹאִיל וְהוּא חַיָּב אִם קִלֵּל בְּכָל הַכִּנּוּיִים כָּךְ אִם קִלֵּל בְּכָל לָשׁוֹן חַיָּב שֶׁהַשֵּׁמוֹת שֶׁקּוֹרְאִין בָּהֶן הַגּוֹיִם לְהַקָּדוֹשׁ בָּרוּךְ הוּא הֲרֵי הֵן כְּכָל הַכִּנּוּיִים. וְאָרוּר בּוֹ שְׁבוּעָה בּוֹ קְלָלָה בּוֹ נִדּוּי:","אֵינוֹ לוֹקֶה עַד שֶׁיַּתְרוּ בּוֹ בִּפְנֵי עֵדִים כִּשְׁאָר כָּל חַיָּבֵי לָאוִין. אֲבָל אִם לֹא הָיְתָה שָׁם הַתְרָאָה אוֹ שֶׁקִּלֵּל בְּלֹא שֵׁם וּבְלֹא כִּנּוּי כְּגוֹן שֶׁאָמַר אָרוּר פְּלוֹנִי אוֹ שֶׁהָיְתָה הַקְּלָלָה בָּאָה מִכְּלַל הַדְּבָרִים כְּגוֹן שֶׁאָמַר אַל יְהִי פְּלוֹנִי בָּרוּךְ לַה' אוֹ אַל יְבָרְכֵהוּ אֵל וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ אֵינוֹ לוֹקֶה:","אַף עַל פִּי שֶׁאֵינוֹ לוֹקֶה אִם חֵרֵף תַּלְמִיד חָכָם מְנַדִּין אוֹתוֹ. וְאִם רָצוּ הַדַּיָּנִים לְהַכּוֹתוֹ מַכַּת מַרְדּוּת מַכִּין וְעוֹנְשִׁין אוֹתוֹ כְּפִי מַה שֶּׁיִּרְאוּ שֶׁהֲרֵי בִּזָּה אֶת הַזָּקֵן. וְאִם חֵרֵף עַם הָאָרֶץ עוֹנְשִׁין הַדַּיָּנִים בַּדָּבָר כְּפִי מַה שֶּׁהַשָּׁעָה צְרִיכָה לוֹ לְפִי הַמְחָרֵף וּלְפִי זֶה שֶׁנִּתְחָרֵף:","אַף עַל פִּי שֶׁיֵּשׁ לוֹ לַדַּיָּן אוֹ לַנָּשִׂיא לִמְחל עַל כְּבוֹדוֹ אֵינוֹ יָכוֹל לִמְחל עַל קִלְלָתוֹ. וְכֵן שְׁאָר הָעָם אַף עַל פִּי שֶׁמָּחַל הַמְקֻלָּל מַלְקִין אֶת הַמְקַלֵּל שֶׁכְּבָר חָטָא וְנִתְחַיֵּב. אֲבָל מִי שֶׁנִּתְחַיֵּב נִדּוּי מִפְּנֵי שֶׁהִפְקִיר בְּבֵית דִּין וְרָצוּ בֵּית דִּין לִמְחל עַל כְּבוֹדָן וְלֹא נִדּוּהוּ הָרְשׁוּת בְּיָדָן. וְהוּא שֶׁלֹּא יִהְיֶה בַּדָּבַר הֶפְסֵד בִּכְבוֹד הַבּוֹרֵא. כְּגוֹן שֶׁהָיוּ הָעָם מְבַעֲטִין בְּדִבְרֵי תּוֹרָה וּבַדַּיָּנִים הוֹאִיל וּפָקְרוּ הָעָם בַּדָּבָר צְרִיכִין לְחַזֵּק וְלַעֲנשׁ כְּפִי מַה שֶּׁיֵּרָאֶה לָהֶם:","כָּל הַדָּן בְּדַיָּנֵי עַכּוּ\"ם וּבְעַרְכָּאוֹת שֶׁלָּהֶן אַף עַל פִּי שֶׁהָיוּ דִּינֵיהֶם כְּדִינֵי יִשְׂרָאֵל הֲרֵי זֶה רָשָׁע וּכְאִלּוּ חֵרֵף וְגִדֵּף וְהֵרִים יָד בְּתוֹרַת משֶׁה רַבֵּנוּ שֶׁנֶּאֱמַר (שמות כא א) \"וְאֵלֶּה הַמִּשְׁפָּטִים אֲשֶׁר תָּשִׂים לִפְנֵיהֶם\" לִפְנֵיהֶם וְלֹא לִפְנֵי עַכּוּ\"ם לִפְנֵיהֶם וְלֹא לִפְנֵי הֶדְיוֹטוֹת. הָיְתָה יַד הָעַכּוּ\"ם תַּקִּיפָה וּבַעַל דִּינוֹ אַלָּם וְאֵינוֹ יָכוֹל לְהוֹצִיא מִמֶּנּוּ בְּדַיָּנֵי יִשְׂרָאֵל יִתְבָּעֶנּוּ לְדַיָּנֵי יִשְׂרָאֵל תְּחִלָּה. אִם לֹא רָצָה לָבוֹא נוֹטֵל רְשׁוּת מִבֵּית דִּין וּמַצִּיל בְּדַיָּנֵי עַכּוּ\"ם מִיַּד בַּעַל דִּינוֹ: סְלִיקוּ לְהוּ הִלְכוֹת סַנְהֶדְרִין בְּסַ\"ד"],"Mishneh Torah, Theft 5":["אָסוּר לִקְנוֹת מִן הַגַּנָּב הַחֵפֶץ שֶׁגָּנַב. וְעָוֹן גָּדוֹל הוּא שֶׁהֲרֵי מַחֲזִיק יְדֵי עוֹבְרֵי עֲבֵרָה וְגוֹרֵם לוֹ לִגְנֹב גְּנֵבוֹת אֲחֵרוֹת שֶׁאִם לֹא יִמְצָא לוֹקֵחַ אֵינוֹ גּוֹנֵב וְעַל זֶה נֶאֱמַר (משלי כט כד) \"חוֹלֵק עִם גַּנָּב שׂוֹנֵא נַפְשׁוֹ\":","הַגּוֹנֵב וּמָכַר וְלֹא נִתְיָאֲשׁוּ הַבְּעָלִים וְאַחַר כָּךְ הֻכַּר הַגַּנָּב וּבָאוּ עֵדִים שֶׁזֶּה הַחֵפֶץ שֶׁמְּכָרוֹ פְּלוֹנִי זֶה הוּא גְּנָבוֹ בְּפָנֵינוּ. חוֹזֵר הַחֵפֶץ לִבְעָלָיו וְהַבְּעָלִים נוֹתְנִין לַלּוֹקֵחַ דָּמִים שֶׁשָּׁקַל לַגַּנָּב מִפְּנֵי תַּקָּנַת הַשּׁוּק. וְהַבְּעָלִים חוֹזְרִין וְעוֹשִׂים דִּין עִם הַגַּנָּב. וְאִם גָּנַב מְפֻרְסָם הוּא לֹא עָשׂוּ בּוֹ תַּקָּנַת הַשּׁוּק וְאֵין הַבְּעָלִים נוֹתְנִין לַלּוֹקֵחַ כְּלוּם אֶלָּא חוֹזֵר הַלּוֹקֵחַ וְעוֹשֶׂה דִּין עִם הַגַּנָּב וּמוֹצִיא מִמֶּנּוּ דָּמִים שֶּׁשָּׁקַל לוֹ:","נִתְיָאֲשׁוּ הַבְּעָלִים מִן הַגְּנֵבָה בֵּין שֶׁנִּתְיָאֲשׁוּ וְאַחַר כָּךְ מָכַר הַגַּנָּב בֵּין שֶׁנִּתְיָאֲשׁוּ אַחַר שֶׁמָּכַר. קָנָה הַלּוֹקֵחַ בְּיֵאוּשׁ וְשִׁנּוּי רְשׁוּת וְאֵינוֹ מַחְזִיר הַגְּנֵבָה עַצְמָהּ לִבְעָלֶיהָ אֶלָּא נוֹתֵן לָהֶם הַדָּמִים אִם לָקַח מִגַּנָּב מְפֻרְסָם. אוֹ אֵינוֹ נוֹתֵן כְּלָל לֹא חֵפֶץ וְלֹא דָּמִים מִפְּנֵי תַּקָּנַת הַשּׁוּק אִם לֹא הָיָה זֶה הַמּוֹכֵר גַּנָּב מְפֻרְסָם:","בִּזְמַן שֶׁהַלּוֹקֵחַ עוֹשֶׂה דִּין עִם בַּעַל הַבַּיִת. אִם אֵין עֵדִים בְּכַמָּה לָקַח הֲרֵי הַתַּגָּר נִשְׁבָּע בִּנְקִיטַת חֵפֶץ בְּכַמָּה לָקַח וְנוֹטֵל מִן הַבְּעָלִים. וְכָל הַנִּשְׁבָּע וְנוֹטֵל שְׁבוּעָתוֹ מִדִּבְרֵיהֶם וְנִשְׁבָּע בִּנְקִיטַת חֵפֶץ כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","בִּזְמַן שֶׁהַלּוֹקֵחַ עוֹשֶׂה דִּין עִם הַגַּנָּב וְהוּא אוֹמֵר בְּכָךְ וְכָךְ לָקַחְתִּי מִמְּךָ וְהוּא אוֹמֵר לֹא מָכַרְתִּי לְךָ אֶלָּא בְּפָחוֹת מִזֶּה. הַתַּגָּר נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל מִן הַגַּנָּב. שֶׁאֵין הַגַּנָּב יָכוֹל לִשָּׁבַע מִפְּנֵי שֶׁהוּא חָשׁוּד עַל הַשְּׁבוּעָה:","גָּנַב וּפָרַע בְּחוֹבוֹ גָּנַב וּפָרַע בְּהֶקֵּפוֹ אֵין בָּזֶה תַּקָּנַת הַשּׁוּק אֶלָּא הַבְּעָלִים נוֹטְלִים הַגְּנֵבָה בְּלֹא דָּמִים וְיִשָּׁאֵר חוֹב אֵלּוּ עַל הַגַּנָּב כְּשֶׁהָיָה. מִשְׁכֵּן הַגְּנֵבָה בֵּין שֶׁמִּשְׁכְּנָהּ בְּיֶתֶר עַל דָּמֶיהָ אוֹ בְּפָחוֹת מִדָּמֶיהָ הַבְּעָלִים נוֹתְנִין לְבַעַל הַמַּשְׁכּוֹן וְחוֹזְרִין וְעוֹשִׂין דִּין עִם הַגַּנָּב אֶלָּא אִם כֵּן הָיָה הַגַּנָּב מְפֻרְסָם כְּמוֹ שֶׁבֵּאַרְנוּ:","הַלּוֹקֵחַ מִגַּנָּב שֶׁאֵינוֹ מְפֻרְסָם בֵּין שֶׁלָּקַח מִמֶּנּוּ שְׁוֵה מֵאָה בְּמָאתַיִם אוֹ שְׁוֵה מָאתַיִם בְּמֵאָה הֲרֵי זֶה נוֹטֵל הַדָּמִים מִבַּעַל הַבַּיִת וְאַחַר כָּךְ מַחְזִיר הַגְּנֵבָה מִפְּנֵי תַּקָּנַת הַשּׁוּק כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיָה נוֹשֶׁה בְּגַנָּב מֵאָה זוּז וְגָנַב וְהֵבִיא לְבַעַל חוֹבוֹ וְנָתַן לוֹ מֵאָה אַחֶרֶת הֲרֵי הַגְּנֵבָה חוֹזֶרֶת לִבְעָלֶיהָ וְאוֹמְרִין לָזֶה לֵךְ וּתְבַע הַגַּנָּב בְּמָאתַיִם שֶׁלֹּא נָתַתָּ לוֹ הַמֵּאָה הָאַחֶרֶת מִפְּנֵי הַחֵפֶץ שֶׁהֵבִיא לְךָ בִּלְבַד כְּשֵׁם שֶׁהֶאֱמַנְתּוֹ בָּרִאשׁוֹנָה הֶאֱמַנְתּוֹ בָּאַחֲרוֹנָה:","לָקַח מִגַּנָּב שֶׁאֵינוֹ מְפֻרְסָם בְּמֵאָה וּמָכַר לְאַחֵר בְּמֵאָה וְעֶשְׂרִים וְהֻכַּר הַגַּנָּב. בַּעַל הַגְּנֵבָה נוֹתֵן לְזֶה הָאַחֲרוֹן מֵאָה וְעֶשְׂרִים וְנוֹטֵל גְּנֵבָתוֹ וְחוֹזֵר הַבַּעַל וְנוֹטֵל עֶשְׂרִים שֶׁל שָׂכָר מִן הַמּוֹכֵר וְנוֹטֵל הַמֵּאָה מִן הַגַּנָּב. וְאִם גַּנָּב מְפֻרְסָם הוּא נוֹטֵל הַמֵּאָה וְעֶשְׂרִים מִן הַתַּגָּר שֶׁלָּקַח מִן הַגַּנָּב וְהוֹלֵךְ הַתַּגָּר וְתוֹבֵעַ הַגַּנָּב בְּמֵאָה שֶׁל קֶרֶן. וְהוּא הַדִּין אִם מָכַר הַשֵּׁנִי לִשְׁלִישִׁי וְהַשְּׁלִישִׁי לִרְבִיעִי אֲפִלּוּ מֵאָה שֶׁהוּא נוֹטֵל מִכָּל אֶחָד וְאֶחָד מַה שֶּׁנִּשְׂכַּר וְנוֹטֵל הַקֶּרֶן מִן הַגַּנָּב. וְכָל הַדְּבָרִים הָאֵלּוּ לִפְנֵי יֵאוּשׁ כְּמוֹ שֶׁבֵּאַרְנוּ:","בַּעַל הַבַּיִת שֶׁאֵינוֹ עָשׂוּי לִמְכֹּר אֶת כֵּלָיו וְיָצָא לוֹ שֵׁם גְּנֵבָה בָּעִיר וְהִכִּיר כֵּלָיו וּסְפָרָיו בְּיַד אֲחֵרִים. אוֹ שֶׁהָיָה עָשׂוּי לִמְכֹּר וְהָיוּ כֵּלִים אֵלּוּ שֶׁהִכִּיר מִכֵּלִים הָעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר. אִם בָּאוּ עֵדִים שֶׁזֶּה כֵּלָיו שֶׁל זֶה יִשָּׁבַע זֶה שֶׁהֵן בְּיָדוֹ בִּנְקִיטַת חֵפֶץ בְּכַמָּה לָקַח וְיִטּל מִבַּעַל הַבַּיִת וְיַחְזִיר לוֹ כֵּלָיו:","הָיָה בַּעַל הַבַּיִת עָשׂוּי לִמְכֹּר אֶת כֵּלָיו וְלֹא הָיוּ מִדְּבָרִים הָעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר אַף עַל פִּי שֶׁיָּצָא לוֹ שֵׁם גְּנֵבָה בָּעִיר וְהֻכְּרוּ כֵּלָיו אֵינוֹ מַחֲזִירָן מִיַּד הַלָּקוֹחוֹת שֶׁמָּא הוּא מְכָרָן לַאֲחֵרִים. אֲבָל אִם בָּאוּ בְּנֵי אָדָם וְלָנוּ בְּתוֹךְ בֵּיתוֹ וְעָמַד וְזָעַק בַּלַּיְלָה נִגְנְבוּ כֵּלַי וּסְפָרַי וּבָאוּ בְּנֵי אָדָם וּמָצְאוּ מַחְתֶּרֶת חֲתוּרָה וּבְנֵי אָדָם שֶׁלָּנוּ בְּתוֹךְ בֵּיתוֹ יוֹצְאִין וּצְרוֹרוֹת שֶׁל כֵּלִים עַל כִּתְפֵיהֶם וְהַכּל אוֹמְרִים הַלָּלוּ כֵּלָיו וּסְפָרָיו שֶׁל פְּלוֹנִי הֲרֵי זֶה נֶאֱמָן. וְיִשָּׁבַע זֶה שֶׁהַכֵּלִים בְּיָדוֹ בִּנְקִיטַת חֵפֶץ כַּמָּה הוֹצִיא וְיִטּל מִבַּעַל הַגְּנֵבָה וְיַחְזִיר לוֹ כֵּלָיו:","גָּנַב שֶׁהֻחְזַק וְנִתְפַּרְסֵם שֶׁנִּכְנַס לְתוֹךְ בֵּית חֲבֵרוֹ וְעֵדִים מְעִידִים שֶׁיָּצָא וְכֵלִים טְמוּנִים לוֹ תַּחַת כְּנָפָיו אַף עַל פִּי שֶׁהָיָה שָׁם בַּעַל הַבַּיִת וְטָעַן וְאָמַר לְקוּחִין הֵן בְּיָדִי וּבַעַל הַבַּיִת אוֹמֵר גְּנוּבִים הֵם. אִם הָיָה בַּעַל הַבַּיִת שֶׁאֵין דַּרְכּוֹ לִמְכֹּר אֶת כֵּלָיו וְאוֹתָם כֵּלִים אֵין דֶּרֶךְ בְּנֵי אָדָם לְהַטְמִינָן וְאֵין דֶּרֶךְ אוֹתוֹ הַמֻּחְזָק לְהַצְנִיעַ כֵּלָיו תַּחַת כְּנָפָיו. הֲרֵי בַּעַל הַבַּיִת נֶאֱמָן וְיִשָּׁבַע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל כֵּלָיו. וְאִם אֵין אָדָם זֶה מֻחְזָק בִּגְנֵבָה אֵין בַּעַל הַבַּיִת נֶאֱמָן אֶלָּא נִשְׁבָּע זֶה שֶׁהַכֵּלִים בְּיָדוֹ שְׁבוּעַת הֶסֵּת שֶׁהַכֵּלִים הָאֵלּוּ לְקוּחִים בְּיָדוֹ וְהוֹלֵךְ:"],"Mishneh Torah, Those Who Defile Bed or Seat 1":["הַזָּב וְהַזָּבָה וְהַנִּדָּה וְהַיּוֹלֶדֶת כָּל אֶחָד מֵאַרְבַּעְתָּן אָב מֵאֲבוֹת הַטֻּמְאוֹת. מְטַמְּאִין כֵּלִים בְּמַגָּע. וּמְטַמֵּא אָדָם בְּמַגָּע וּבְמַשָּׂא. וּמְטַמֵּא מִשְׁכָּב וּמוֹשָׁב וּמֶרְכָּב מִתַּחְתָּיו וְעוֹשֶׂה אוֹתָן אַב טֻמְאָה. וּמְטַמֵּא מַדָּף עַל גַּבּוֹ:","אֶחָד זָבָה קְטַנָּה וְאֶחָד זָבָה גְּדוֹלָה. וְאֶחָד זָבָה מֵחֲמַת עַצְמָהּ אוֹ מֵחֲמַת אֹנֶס. וְאֶחָד זָב בַּעַל שְׁתֵּי רְאִיוֹת אוֹ בַּעַל שָׁלֹשׁ. טֻמְאַת כֻּלָּן שָׁוָה לְטַמֵּא אֲחֵרִים:","קְטַנָּה בַּת יוֹם אֶחָד מִטַּמְּאָה בְּנִדָּה. בַּת עֲשָׂרָה יָמִים בְּזִיבָה. בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד מְטַמְּאָה אֶת בּוֹעֲלָהּ כְּמוֹ שֶׁיִּתְבָּאֵר:","קָטָן בֶּן יוֹם אֶחָד מִטַּמֵּא בְּזִיבָה. וְאֶחָד גֵּרִים וַעֲבָדִים וְאֶחָד יִשְׂרָאֵל מִטַּמְּאִין בְּנִדָּה וּבְזִיבָה:","סְרִיס אָדָם סְרִיס חַמָּה מִטַּמְּאִין בְּזִיבָה כִּשְׁאָר הַבְּרִיאִין:","אֵין הָאִשָּׁה מִטַּמְּאָה בְּלֹבֶן וְלֹא הָאִישׁ בְּאֹדֶם אֶלָּא הָאִשָּׁה בְּאֹדֶם וְהָאִישׁ בְּלֹבֶן:","טֻמְטוּם וְאַנְדְרוֹגִינוּס נוֹתְנִין עֲלֵיהֶם חֻמְרֵי הָאִישׁ וְחֻמְרֵי הָאִשָּׁה. מִטַּמְּאִין בְּלֹבֶן כְּאִישׁ וּבְאֹדֶם כְּאִשָּׁה. וְטֻמְאָתָן בְּסָפֵק לְפִיכָךְ אֵין שׂוֹרְפִין עֲלֵיהֶן תְּרוּמָה וְקָדָשִׁים וְאֵין חַיָּבִין עֲלֵיהֶן עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו. רָאָה לֹבֶן וְאֹדֶם כְּאַחַד שׂוֹרְפִין עֲלֵיהֶן אֶת הַתְּרוּמָה וְאֶת הַקָּדָשִׁים אֲבָל אֵין חַיָּבִין עֲלֵיהֶן עַל בִּיאַת מִקְדָּשׁ וְקָדָשָׁיו שֶׁנֶּאֱמַר (במדבר ה ג) \"מִזָּכָר עַד נְקֵבָה תְּשַׁלֵּחוּ\" עַד שֶׁיִּהְיֶה הַטֻּמְאָה טֻמְאַת זָכָר וַדַּאי אוֹ טֻמְאַת נְקֵבָה וַדָּאִית. וְכֵן הַנּוֹגֵעַ בַּלֹּבֶן וְאֹדֶם שֶׁלּוֹ כְּאַחַת אֵינוֹ חַיָּב עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו. נָגַע הוּא בְּעַצְמוֹ בְּלֹבֶן וְאֹדֶם שֶׁרָאָה הֲרֵי זֶה חַיָּב עַל בִּיאַת הַמִּקְדָּשׁ:","דַּם הַנִּדָּה אוֹ דַּם הַזָּבָה אוֹ דַּם הַיּוֹלֶדֶת מְטַמֵּא בְּכָל שֶׁהוּא בְּמַגָּע וּבְמַשָּׂא שֶׁנֶּאֱמַר (ויקרא טו לג) \"וְהַדָּוָה בְּנִדָּתָהּ וְהַזָּב\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁמַּדְוֶה כָּמוֹהָ. וּכְבָר בֵּאַרְנוּ בְּעִנְיַן אִסּוּר נִדָּה שֶׁחֲמִשָּׁה דָּמִים טְמֵאִים בָּאִשָּׁה אֲבָל אִם רָאֲתָה דָּם יָרֹק הֲרֵי הוּא טָהוֹר וְאֵינוֹ כְּמוֹ רֻקָּהּ וּשְׁאָר מַשְׁקִין הַיּוֹצְאִין מִמֶּנָּה שֶׁהָרֹק מִתְעַגֵּל וְיוֹצֵא וְזֶה שׁוֹתֵת וְיוֹרֵד:","אִשָּׁה שֶׁיָּצָא הַוָּלָד מִדָּפְנָהּ וְיוֹצֵא עִמּוֹ דָּם מִן הַדֹּפֶן הֲרֵי אוֹתוֹ דָּם אָב מֵאֲבוֹת הַטֻּמְאוֹת כְּדַם הַנִּדָּה וְהַלֵּדָה וְהַזִּיבָה שֶׁהַמָּקוֹר מְקוֹמוֹ טָמֵא. וְהָאִשָּׁה טְהוֹרָה עַד שֶׁיֵּצֵא מִמֶּנָּה דָּם דֶּרֶךְ הָרֶחֶם:","מְקוֹר הָאִשָּׁה שֶׁנֶּעֱקַר וְנָפַל לָאָרֶץ הָאִשָּׁה טְמֵאָה טֻמְאַת עֶרֶב וְכֵן מָקוֹר שֶׁהִזִּיעַ כִּשְׁנֵי טִפֵּי מַרְגָּלִיּוֹת הָאִשָּׁה טְמֵאָה טֻמְאַת עֶרֶב. אֲבָל אֵינָהּ נִדָּה עַד שֶׁתִּרְאֶה אֶחָד מֵחֲמִשָּׁה דָּמִים הַמְטַמְּאִין אוֹתָהּ:","הֵזִיעָה טִפָּה אַחַת הֲרֵי הָאִשָּׁה טְהוֹרָה שֶׁאֵינָהּ אֶלָּא מִחוּץ לַמָּקוֹר:","זוֹבוֹ שֶׁל זָב אָב מֵאֲבוֹת הַטֻּמְאוֹת כְּזָב שֶׁנֶּאֱמַר (ויקרא טו ב) \"זוֹבוֹ טָמֵא הוּא\" וּמְטַמֵּא בְּמַגָּע וּבְמַשָּׂא בְּכָל שֶׁהוּא. רְאִיָּה רִאשׁוֹנָה שֶׁל זָב אֵינָהּ מְטַמְּאָה בְּמַשָּׂא וַהֲרֵי הִיא כְּשִׁכְבַת זֶרַע בֵּין מֵאִישׁ גָּדוֹל בֵּין מֵאִישׁ קָטָן וְכֵן הַמִּשְׁכָּבוֹת וְהַמּוֹשָׁבוֹת שֶׁיָּשַׁב עֲלֵיהֶם מִשֶּׁרָאָה רְאִיָּה רִאשׁוֹנָה עַד שֶׁרָאָה הַשְּׁנִיָּה טְהוֹרִים שֶׁאֵינוֹ קָרוּי זָב אֶלָּא אַחַר רְאִיָּה שְׁנִיָּה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מְחֻסְּרֵי כַּפָּרָה. רָאָה אַחַת מְרֻבָּה כִּשְׁתַּיִם אֵין טָמֵא אֶלָּא הַמֵּסִיט טִפָּה אַחֲרוֹנָה:","רְאִיָּה רִאשׁוֹנָה שֶׁל מְצֹרָע מְטַמֵּא בְּמַשָּׂא שֶׁנֶּאֱמַר (במדבר ה ב) \"כָּל צָרוּעַ וְכָל זָב וְכל טָמֵא לָנָפֶשׁ\" הֲרֵי הַצָּרוּעַ כְּזָב גָּמוּר מַה זָּב גָּמוּר זוֹבוֹ מְטַמֵּא בְּמַשָּׂא אַף מְצֹרָע רְאִיָּתוֹ הָרִאשׁוֹנָה מְטַמֵּא בְּמַשָּׂא:","רֹק הַזָּב וְשִׁכְבַת זַרְעוֹ וּמֵימֵי רַגְלָיו כָּל אֶחָד מִשְּׁלָשְׁתָּן אַב טֻמְאָה דִּין תּוֹרָה. וּמְטַמֵּא בְּכָל שֶׁהוּא בְּמַגָּע וּבְמַשָּׂא הֲרֵי הוּא אוֹמֵר בְּרֹק (ויקרא טו ח) \"וְכִי יָרֹק הַזָּב בַּטָּהוֹר\". וּמֵימֵי רַגְלָיו וְשִׁכְבַת זַרְעוֹ אִי אֶפְשָׁר שֶׁלֹּא יִהְיֶה בָּהֶם צִחְצוּחֵי זִיבָה כָּל שֶׁהוּא:","אֶחָד זָב וְאֶחָד נִדָּה וְיוֹלֶדֶת וְזָבָה כָּל אֶחָד מֵהֶן רֻקּוֹ וּמֵימֵי רַגְלָיו אַב טֻמְאָה כְּזָב. וְכֵן כָּל מָקוֹם שֶׁנֶּאֱמַר בַּהֲלָכוֹת אֵלּוּ הַזָּב אֶחָד הַזָּב וְאֶחָד שְׁאָר הָאַרְבָּעָה:","תִּשְׁעָה מַשְׁקִין בְּזָב שְׁלֹשָׁה מֵהֶן אָב טֻמְאָה וְהֵן רֻקּוֹ וְשִׁכְבַת זַרְעוֹ וּמֵימֵי רַגְלָיו. כָּל אֶחָד מֵאֵלּוּ מְטַמֵּא אָדָם וְכֵלִים בְּכָל שֶׁהוּא כְּמוֹ שֶׁבֵּאַרְנוּ. שְׁלֹשָׁה מֵהֶן כִּוְלַד הַטֻּמְאָה וְאֵלּוּ הֵן דִּמְעַת עֵינוֹ וְדַם מַגַּפְתּוֹ וַחֲלֵב הָאִשָּׁה. כָּל אֶחָד מֵאֵלּוּ כְּמַשְׁקִין טְמֵאִין שֶׁאֵין מְטַמְּאִין אָדָם אֲבָל מְטַמְּאִין כֵּלִים מִדִּבְרֵי סוֹפְרִים כְּמוֹ שֶׁבֵּאַרְנוּ. וּשְׁלֹשָׁה מֵהֶן טְהוֹרִין וְאֵלּוּ הֵן זֵעָתוֹ וְלֵחָה סְרוּחָה הַיּוֹצְאִים מִמֶּנּוּ וְהָרֵעִי. הֲרֵי אֵלּוּ שְׁלֹשָׁה מִן הַזָּב וַחֲבֵרָיו כְּמוֹתָן מִשְּׁאָר הָאָדָם. כִּיחוֹ וְנִיעוֹ וְרִירוֹ וּמֵי הָאַף שֶׁלּוֹ הֲרֵי הֵן כְּרֻקּוֹ לְכָל דָּבָר וּבִכְלַל הָרֹק הֵן חֲשׁוּבִין. דָּם הַיּוֹצֵא מִפִּי אַמָּה וְדָם הַשּׁוֹתֵת מִפִּיו הֲרֵי הֵן בִּכְלַל דָּם מַגַּפְתּוֹ. הָיָה מוֹצֵץ וְרוֹקֵק דָּם הֲרֵי זֶה מְטַמֵּא כְּרֹק. שֶׁהַדָּם שֶׁמּוֹצֵץ אִי אֶפְשָׁר לוֹ בְּלֹא צִחְצוּחֵי רֹק:"],"Mishneh Torah, Those Who Defile Bed or Seat 9":["דָבָר שֶׁהָיָה מְחֻבָּר בָּאָרֶץ אוֹ מְסֻמָּר בְּמַסְמְרִים. אִם הָיָה כֹּחוֹ יָפֶה וְחָזָק וְהִקִּישׁ עָלָיו הַזָּב וּבְעֵת שֶׁהִקִּישׁ הֵנִיד כְּלִי אוֹ אֳכָלִין וּמַשְׁקִין מִכֹּחַ הַכָּאָתוֹ אוֹ שֶׁהִפִּילָן הֲרֵי אֵלּוּ טְהוֹרִים. וְאִם לֹא הָיָה כֹּחוֹ יָפֶה וְחָזָק אֶלָּא מִתְנַדְנֵד וְהִקִּישׁ עָלָיו הַזָּב וְהִפִּיל אוֹ הֵנִיד בְּכֹחַ הַכָּאָתוֹ כֵּלִים אוֹ אֳכָלִים וּמַשְׁקִין הֲרֵי אֵלּוּ טְמֵאִין. וּכְאִלּוּ הֱסִיטָן שֶׁהֲרֵי מִכֹּחוֹ נָפְלוּ. זֶה הַכְּלָל כָּל שֶׁנָּפַל מִכֹּחַ הֶסֵּטוֹ טָמֵא. מִכֹּחַ הָרְעָדָה טָהוֹר. כֵּיצַד. הִקִּישׁ עַל אִילָן אוֹ סֻכָּה שֶׁכֹּחָן רַע. אוֹ עַל סֻלָּם מִצְרִי שֶׁאֵינוֹ קָבוּעַ בְּמַסְמֵר. אוֹ עַל קוֹרָה וְדֶלֶת וְכֶבֶשׁ שֶׁאֵינָם מְחֻבָּרִים בְּטִיט. אוֹ שֶׁהִקִּישׁ עַל הַנֶּגֶר עַל הַמַּנְעוּל וְהַמָּשׁוֹט. וּבְשָׁעָה שֶׁהִקִּישׁ הִפִּיל אֳכָלִין וּמַשְׁקִין אוֹ כֵּלִים אֲפִלּוּ הֱנִידָן וְלֹא נָפְלוּ הֲרֵי אֵלּוּ טְמֵאִים. אֲבָל אִם הִקִּישׁ עַל אִילָן אוֹ עַל סֻכָּה שֶׁכֹּחָן יָפֶה. אוֹ עַל סֻלָּם מְסֻמָּר. אוֹ עַל כֶּבֶשׁ אוֹ עַל דֶּלֶת אוֹ קוֹרָה הַמְחֻבָּרִין בְּטִיט. אוֹ עַל הַמָּרִישׁ. אוֹ עַל הַתַּנּוּר. וּבְשָׁעָה שֶׁהִקִּישׁ הֵנִיד כֵּלִים אוֹ אֳכָלִין וּמַשְׁקִין אֲפִלּוּ הִפִּילָן הֲרֵי אֵלּוּ טְהוֹרִין. וְכֵן כָּל כַּיּוֹצֵא בָּאֵלּוּ:","תַּנּוּר שֶׁהָיְתָה הַפַּת דְּבוּקָה בּוֹ וְהִקִּישׁ עַל הַתַּנּוּר וְנָפַל כִּכָּר אֲפִלּוּ הָיָה תְּרוּמָה הֲרֵי זֶה טָהוֹר. וְאִם הָיָה חֶרֶס מִן הַתַּנּוּר מְדֻבָּק בַּכִּכָּר שֶׁנָּפַל אֲפִלּוּ הָיָה חֻלִּין הֲרֵי זֶה טָמֵא:","אֵין הַמִּשְׁכָּב אוֹ הַמֶּרְכָּב מְטַמֵּא כֵּלִים אוֹ אֳכָלִין וּמַשְׁקִין אֶלָּא בְּמַגָּע בִּלְבַד. אֲבָל אִם הָיוּ כֵּלִים אוֹ אֳכָלִים וּמַשְׁקִין לְמַעְלָה מִן הַמִּדְרָס אוֹ שֶׁהָיָה הַמִּדְרָס לְמַעְלָה מֵהֶן אֲפִלּוּ לֹא הִפְסִיק בֵּינֵיהֶם אֶלָּא נְיָר הוֹאִיל וְלֹא נָגַע בָּהֶן הֲרֵי אֵלּוּ טְהוֹרִין. וְכֵן אִם הֵסִיט הַמִּשְׁכָּב אֶת הַכֵּלִים אוֹ אֶת הָאֳכָלִים וְהַמַּשְׁקִין הֲרֵי אֵלּוּ טְהוֹרִין:","הַזָּב וְהַטָּהוֹר שֶׁיָּשְׁבוּ בִּסְפִינָה קְטַנָּה הַיְכוֹלָה לְהָמִיט בָּאָדָם אֶחָד אוֹ בְּאַסְדָּא אוֹ שֶׁרָכְבוּ עַל גַּבֵּי בְּהֵמָה אַף עַל פִּי שֶׁאֵין בִּגְדֵיהֶן נוֹגְעִין זֶה בָּזֶה הֲרֵי בִּגְדֵי הַטָּהוֹר טְמֵאִים מִדְרָס וְטֻמְאָתָן בְּסָפֵק שֶׁמָּא דָּרַס הַזָּב עֲלֵיהֶן. וְכֵן נִדָּה שֶׁיָּשְׁבָה עִם הַטְּהוֹרָה בַּמִּטָּה בְּגָדֶיהָ טְמֵאִין מִדְרָס חוּץ מִכִּפָּה שֶׁבְּרֹאשָׁהּ. וְכֵן הַבְּגָדִים שֶׁבְּרֹאשׁ הַנֵּס שֶׁבַּסְּפִינָה טְהוֹרִין:","הַנִּדְחָק בְּרֵחַיִם שֶׁהָעַכּוּ\"ם בְּתוֹכָם אוֹ זָב וְכַיּוֹצֵא בּוֹ הֲרֵי בְּגָדָיו טְמֵאִין מִדְרָס. בְּאֵי זֶה רֵחַיִם אָמְרוּ בְּרֵחַיִם שֶׁמְּנַדְנְדִין אֶת הַקַּרְקַע עַד שֶׁעוֹקְרִין אֶת הָעוֹמֵד כָּאן וְדוֹחֲפִין אוֹתוֹ מִמְּקוֹמוֹ. וְדָבָר בָּרוּר הוּא שֶׁטֻּמְאָה זוֹ בְּסָפֵק שֶׁמָּא נֶעֱקַר הַטָּמֵא וְדָרַס עַל בִּגְדֵי הַטָּהוֹר:"],"Mishneh Torah, Tithes 7":["מִי שֶׁהָיוּ לוֹ מֵאָה לוֹג שֶׁל יַיִן טָבוּל מִן הַתּוֹרָה וְאָמַר שְׁנֵי לוֹגִין שֶׁאֲנִי עָתִיד לְהַפְרִישׁ מֵהֶן הֲרֵי הֵן תְּרוּמָה וַעֲשָׂרָה מַעֲשֵׂר רִאשׁוֹן וְתִשְׁעָה מַעֲשֵׂר שֵׁנִי. לֹא יַתְחִיל וְיִשְׁתֶּה עַד שֶׁיַּנִּיחַ בְּסוֹף שִׁעוּר תְּרוּמָה וּמַעַשְׂרוֹת. אֶלָּא יַפְרִישׁ וְאַחַר כָּךְ יִשְׁתֶּה. וְאֵין אוֹמְרִין זֶה שֶׁהִנִּיחַ בַּסּוֹף כְּאִלּוּ נִבְרַר תְּחִלָּה מִפְּנֵי שֶׁחִיּוּב תְּרוּמָה וּמַעַשְׂרוֹת מִן הַתּוֹרָה וְאֵין אוֹמְרִין בְּשֶׁל תּוֹרָה נַחְשֹׁב כְּאִלּוּ נִבְרַר עַד שֶׁיִּבְרֹר:","הַקּוֹבֵעַ מַעַשְׂרוֹתָיו בְּפִי הֶחָבִית לֹא יִשְׁתֶּה מִשּׁוּלֶיהָ. בְּשׁוּלֶיהָ לֹא יִשְׁתֶּה מִפִּיהָ. מִפְּנֵי שֶׁהַמַּשְׁקִין מְעֹרָבִין. אֲבָל הַקּוֹבֵעַ בְּפִי הַמְּגוּרָה אוֹכֵל מִשּׁוּלֶיהָ. קָבַע בְּשׁוּלֶיהָ אוֹכֵל מִפִּיהָ:","וְיֵשׁ לָאָדָם לִקְבֹּעַ מַעֲשֵׂר שֵׁנִי וּפוֹדֵהוּ וְעוֹשֵׂהוּ מַעֲשֵׂר רִאשׁוֹן עַל אוֹתָן הַפֵּרוֹת אוֹ תְּרוּמַת מַעֲשֵׂר לְמָקוֹם אַחֵר:","הַמַּנִּיחַ פֵּרוֹת לִהְיוֹת מַפְרִישׁ עֲלֵיהֶן מַעַשְׂרוֹת מַפְרִישׁ עֲלֵיהֶן בְּחֶזְקַת שֶׁהֵן קַיָּמִין וְאוֹכֵל וְשׁוֹתֶה עַד שֶׁיֵּעָשׂוּ כָּל אוֹתָן הַפֵּרוֹת שֶׁהִנִּיחַ מַעֲשֵׂר וְנוֹתֵן לַלֵּוִי. מְצָאָן שֶׁאָבְדוּ הֲרֵי זֶה חוֹשֵׁשׁ לְכָל שֶׁהִפְרִישׁ וְאֵינוֹ מְעַשֵּׂר וַדַּאי:","הַמַּלְוֶה מָעוֹת אֶת הַכֹּהֵן וְאֶת הַלֵּוִי וְאֶת הֶעָנִי לִהְיוֹת מַפְרִישׁ עַל אוֹתָן הַמָּעוֹת מֵחֶלְקוֹ מַפְרִישׁ עֲלֵיהֶן בְּחֶזְקַת שֶׁהֵן קַיָּמִין וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא מֵתוּ הַכֹּהֵן אוֹ הַלֵּוִי אוֹ הֶעֱשִׁיר הֶעָנִי:","כֵּיצַד מַפְרִישׁ עֲלֵיהֶן. מַפְרִישׁ תְּרוּמָה אוֹ מַעֲשֵׂר רִאשׁוֹן אוֹ מַעֲשֵׂר שֵׁנִי מִפֵּרוֹתָיו וּמְזַכֶּה בָּהֶן עַל יְדֵי אַחֵר לְאוֹתוֹ כֹּהֵן אוֹ הַלֵּוִי אוֹ הֶעָנִי שֶׁהִלְווּם. וְאִם הָיוּ רְגִילִין לִטּל מִמֶּנּוּ וְהוּא רָגִיל שֶׁלֹּא יִתֵּן אֶלָּא לָהֶן אֵינוֹ צָרִיךְ לְזַכּוֹת עַל יְדֵי אַחֵר. וְאַחַר שֶּׁמַּפְרִישׁ מְחַשֵּׁב כַּמָּה שָׁוֶה זֶה שֶׁהִפְרִישׁ וּמְנַכֶּה מִן הַמִּלְוֶה עַד שֶׁיִּפְרַע כָּל חוֹבוֹ וּמוֹכֵר הַתְּרוּמָה לְכָל כֹּהֵן שֶׁיִּרְצֶה וְאוֹכֵל הַמַּעַשְׂרוֹת:","כְּשֶׁהוּא מְחַשֵּׁב מַה שָּׁוִים הַפֵּרוֹת שֶׁהִפְרִישׁ יֵשׁ לוֹ לְחַשֵּׁב כַּשַּׁעַר הַזּוֹל וְאֵינוֹ חוֹשֵׁשׁ מִשּׁוּם רִבִּית. וְאֵין הַשְּׁבִיעִית מְשַׁמֶּטֶת חוֹב זֶה. וְאִם בָּא בַּעַל הַבַּיִת לַחֲזֹר אֵינוֹ חוֹזֵר. אֲבָל אִם רָצוּ אֵלּוּ שֶׁלָּקְחוּ הַמָּעוֹת לַחֲזֹר חוֹזְרִין. נִתְיָאֲשׁוּ מֵהֶן הַבְּעָלִים אֵין מַפְרִישִׁין עֲלֵיהֶן שֶׁאֵין מַפְרִישִׁין עַל הָאָבוּד. מֵת הַכֹּהֵן אוֹ הַלֵּוִי אוֹ הֶעָנִי שֶׁהִלְווּם אֵינוֹ יָכוֹל לְהַפְרִישׁ עֲלֵיהֶן מֵחֶלְקָן כַּדֶּרֶךְ הַזּוֹ עַד שֶׁיִּטּל רְשׁוּת מִן הַיּוֹרְשִׁין. וְהוּא שֶׁיַּנִּיחַ לָהֶן קַרְקַע אֲפִלּוּ מְלֹא מַחַט. אֲבָל אִם הִנִּיחַ כְּסָפִים אֵין רְשׁוּת הַיּוֹרֵשׁ מוֹעֶלֶת. וְאִם הִלְוָם בְּבֵית דִּין עַל מְנָת שֶׁיַּפְרִישׁ עַל מָעוֹת אֵלּוּ מֵחֶלְקָם אֵינוֹ צָרִיךְ לִטּל רְשׁוּת מִן הַיּוֹרְשִׁין. הֶעֱשִׁיר הֶעָנִי אֵין מַפְרִישִׁין עָלָיו אַף עַל פִּי שֶׁהִלְווּהוּ בְּבֵית דִּין זוֹכֶה הַלָּה בְּמַה שֶּׁבְּיָדוֹ:","יִשְׂרָאֵל שֶׁאָמַר לְבֶן לֵוִי כּוֹר מַעֲשֵׂר יֵשׁ לְךָ בְּיָדִי רַשַּׁאי בֶּן לֵוִי לַעֲשׂוֹתוֹ תְּרוּמַת מַעֲשֵׂר עַל מָקוֹם אַחֵר אַף עַל פִּי שֶׁלֹּא מָשַׁךְ. וְאִם נְתָנוֹ הַיִּשְׂרָאֵל לְלֵוִי אַחֵר אֵין לוֹ עָלָיו אֶלָּא תַּרְעֹמֶת:","מִי שֶׁהָיוּ לוֹ פֵּרוֹת בִּמְגוּרָה וְנָתַן סְאָה לְלֵוִי וּסְאָה לְעָנִי לֹא יַפְרִישׁ שְׁמֹנֶה סְאִין מִן הַמְּגוּרָה וְיֹאכְלֵם. אֶלָּא אִם כֵּן יוֹדֵעַ שֶׁשְּׁתֵּי סְאִין שֶׁל מַעַשְׂרוֹת קַיָּמִין. אֲבָל אִם אָכְלוּ מֵהֶן הַלֵּוִי וְהֶעָנִי אֵינוֹ מַפְרִישׁ עֲלֵיהֶן אֶלָּא לְפִי חֶשְׁבּוֹן הַנִּשְׁאָר מִשְּׁתֵּי הַסְּאִין:","עֲנִיִּים שֶׁהֶחְלִיפוּ מַתְּנוֹתֵיהֶן עִם בַּעַל הַבַּיִת כְּגוֹן שֶׁנָּתְנוּ לוֹ סְאָה שֶׁל לֶקֶט אוֹ שִׁכְחָה וּפֵאָה וּמַעֲשֵׂר עָנִי וְנָטְלוּ סְאָה מִן הַגֹּרֶן. זֶה שֶׁנָּטַל מֵהֶם פָּטוּר מִן הַמַּעֲשֵׂר אַף עַל פִּי שֶׁנַּעֲשָׂה בִּרְשׁוּת בַּעַל הַבַּיִת. וְזֶה שֶׁנָּטְלוּ מִמֶּנּוּ חַיָּב אַף עַל פִּי שֶׁהוּא חֵלֶף מַתְּנוֹתֵיהֶן הַפְּטוּרִין:","מִי שֶׁהָיוּ לְפָנָיו שְׁתֵּי כַּלְכָּלוֹת שֶׁל טֶבֶל שֶׁנִּטְּלָה תְּרוּמָתָן וְאָמַר מַעַשְׂרוֹת זוֹ בָּזוֹ הָרִאשׁוֹנָה מְעֻשֶּׂרֶת. אָמַר מַעַשְׂרוֹת זוֹ בָּזוֹ וְזוֹ בָּזוֹ הָרִאשׁוֹנָה מְעֵשֶּׂרֶת שֶׁהֲרֵי קָבַע מַעַשְׂרוֹתֶיהָ בַּשְּׁנִיָּה. וְאֵין הַשְּׁנִיָּה מְעֵשֶּׂרֶת שֶׁאֵין מַפְרִישִׁין מַעֲשֵׂר מִן הָרִאשׁוֹנָה שֶׁכְּבָר נִפְטְרָה עַל הַשְּׁנִיָּה שֶׁעֲדַיִן הִיא חַיֶּבֶת בְּמַעֲשַׂר שְׁתֵּיהֶן:","אָמַר מַעַשְׂרוֹת שְׁתֵּי כַּלְכָּלוֹת אֵלּוּ מַעֲשֵׂר כָּל אַחַת מֵהֶן קָבוּעַ בַּחֲבֶרְתָּהּ קָרָא שֵׁם וּכְבָר קָבַע מַעַשְׂרוֹתֵיהֶן בָּהֶן וּמוֹצִיא הַמַּעַשְׂרוֹת שֶׁלָּהֶן וְאֵינוֹ יָכוֹל לְהוֹצִיא עֲלֵיהֶן מַעַשְׂרוֹת מִמָּקוֹם אַחֵר:","וְכֵיצַד מְעַשְּׂרָן. מוֹצִיא מַעֲשַׂר שְׁתֵּיהֶן מֵאַחַת מֵהֶן אוֹ מְעַשֵּׂר כָּל אַחַת מֵהֶן מִמֶּנָּה אִם הָיוּ שָׁווֹת. וְאִם הָיְתָה אַחַת גְּדוֹלָה מֵחֲבֶרְתָּהּ מַפְרִישׁ מִן הַקְּטַנָּה מַעֲשַׂר הַגְּדוֹלָה וּמִן הַגְּדוֹלָה מַעֲשַׂר הַקְּטַנָּה:"],"Mishneh Torah, Transmission of the Oral Law 11":["רַבַּן גַּמְלִיאֵל הַזָּקֵן קִבַּל מֵרַבַּן שִׁמְעוֹן אָבִיו, בְּנוֹ שֶׁלְּהִלֵּל; וְרַבַּן שִׁמְעוֹן בְּנוֹ קִבַּל מִמֶּנּוּ, וְרַבַּן גַּמְלִיאֵל בְּנוֹ קִבַּל מִמֶּנּוּ, וְרַבַּן שִׁמְעוֹן בְּנוֹ קִבַּל מִמֶּנּוּ. וְרִבִּי יְהוּדָה בְּנוֹ שֶׁלְּרַבַּן שִׁמְעוֹן, זֶה הוּא הַנִּקְרָא רַבֵּנוּ הַקָּדוֹשׁ, וְהוּא קִבַּל מֵאָבִיו, וּמֵרִבִּי אֶלְעָזָר בֶּן שַׁמּוּעַ וּמֵרִבִּי שִׁמְעוֹן חֲבֵרוֹ."],"Mishneh Torah, Transmission of the Oral Law 22":["כָּל אֵלּוּ הַחֲכָמִים הַנִּזְכָּרִים, הֶם גְּדוֹלֵי הַדּוֹרוֹת – מֵהֶם רָאשֵׁי יְשִׁיבוֹת, וּמֵהֶם רָאשֵׁי גָּלִיּוֹת, וּמֵהֶם מִסַּנְהֶדְּרֵי גְּדוֹלָה. וְעִמָּהֶם בְּכָל דּוֹר וָדוֹר, אֲלָפִים וּרְבָבוֹת שֶׁשָּׁמְעוּ מֵהֶם וְעִמָּהֶם."],"Mishneh Torah, Transmission of the Oral Law 33":["לְפִיכָּךְ אֵין כּוֹפִין אַנְשֵׁי מְדִינָה זוֹ לִנְהֹג בְּמִנְהַג מְדִינָה אַחֶרֶת, וְאֵין אוֹמְרִין לְבֵית דִּין זֶה לִגְזֹר גְּזֵרָה שֶׁגְּזָרָהּ בֵּית דִּין אַחֵר בִּמְדִינָתוֹ. וְכֵן אִם לִמַּד אֶחָד מִן הַגְּאוֹנִים שֶׁדֶּרֶךְ הַמִּשְׁפָּט כָּךְ הוּא, וְנִתְבָּאַר לְבֵית דִּין אַחֵר שֶׁעָמַד אַחֲרָיו שְׁאֵין זֶה דֶּרֶךְ הַמִּשְׁפָּט הַכָּתוּב בַּתַּלְמוּד – אֵין שׁוֹמְעִין לָרִאשׁוֹן, אֵלָא לְמִי שֶׁהַדַּעַת נוֹטָה לִדְבָרָיו, בֵּין רִאשׁוֹן, בֵּין אַחֲרוֹן."],"Mishneh Torah, Transmission of the Oral Law 44":["אֵלּוּ הַהֲלָכוֹת שֶׁבְּכָל עִנְיָן וְעִנְיָן – יֵשׁ מֵהֶן הֲלָכוֹת שְׁהֶן מִשְׁפְּטֵי מִצְוָה אַחַת בִּלְבָד, וְהִיא הַמִּצְוָה שֶׁיֵּשׁ בָּהּ דִּבְרֵי קַבָּלָה הַרְבֵּה וְהִיא עִנְיָן בִּפְנֵי עַצְמוֹ; וְיֵשׁ מֵהֶן הֲלָכוֹת שְׁהֶן כּוֹלְלִין מִשְׁפְּטֵי מִצְווֹת הַרְבֵּה, אִם יִהְיוּ אוֹתָן הַמִּצְווֹת כֻּלָּן בְּעִנְיָן אֶחָד: מִפְּנֵי שֶׁחִלּוּק חִבּוּר זֶה הוּא לְפִי הָעִנְיָנִים לֹא לְפִי מִנְיַן הַמִּצְווֹת, כְּמוֹ שֶׁיִּתְבָּאַר לַקּוֹרֶא בּוֹ."],"Mishneh Torah, Trespass 6":["יֵשׁ דְּבָרִים שֶׁהָאָדָם נֶהֱנֶה בָּהֶן וְלֹא יִפָּגְמוּ כְּגוֹן הַמִּשְׁתַּמֵּשׁ בִּכְלִי זָהָב טָהוֹר. וְיֵשׁ דְּבָרִים שֶׁיִּפָּגְמוּ כְּגוֹן בְּגָדִים וּכְלֵי כֶּסֶף וּנְחשֶׁת וּבַרְזֶל וְכַיּוֹצֵא בָּהֶן. וְהַנֶּהֱנֶה בִּשְׁוֵה פְּרוּטָה מִן הַהֶקְדֵּשׁ שֶׁאֵינוֹ מְחֻבָּר בַּקַּרְקַע אִם נֶהֱנֶה בְּדָבָר שֶׁאֵין בּוֹ פְּגָם כְּגוֹן שֶׁנִּשְׁתַּמֵּשׁ בִּכְלִי זָהָב שֶׁל הֶקְדֵּשׁ מָעַל. נֶהֱנֶה בְּדָבָר שֶׁנִּפְגַּם כְּגוֹן שֶׁלָּבַשׁ בִּגְדֵי הֶקְדֵּשׁ אוֹ בָּקַע בְּקוֹרְדוֹם לֹא מָעַל עַד שֶׁיִּפְגֹּם בַּהֶקְדֵּשׁ בִּשְׁוֵה פְּרוּטָה בְּאוֹתוֹ דָּבָר עַצְמוֹ שֶׁנֶּהֱנָה בּוֹ וְיִתְכַּוֵּן לֵהָנוֹת וְיִפְגֹּם וְיֵהָנֶה כְּאַחַת. נֶהֱנָה בְּכַחֲצִי פְּרוּטָה וּפָגַם בְּכַחֲצִי פְּרוּטָה אוֹ שֶׁנֶּהֱנָה בִּשְׁוֵה פְּרוּטָה וּפָגַם בִּשְׁוֵה פְּרוּטָה בְּדָבָר אַחֵר וְלֹא נֶהֱנָה בְּמַה שֶּׁפָּגַם וְלֹא פָּגַם בְּמַה שֶּׁנֶּהֱנָה הֲרֵי זֶה לֹא מָעַל עַד שֶׁיֵּהָנֶה בִּשְׁוֵה פְּרוּטָה וְיִפְגֹּם בְּאוֹתָהּ הֲנָיָה בִּשְׁוֵה פְּרוּטָה בַּדָּבָר עַצְמוֹ. כֵּיצַד. הֲרֵי שֶׁהִתִּיר מַטְלִית מִבֶּגֶד הֶקְדֵּשׁ וּתְפָרָהּ בְּבִגְדוֹ וּלְבָשָׁהּ וְנֶהֱנָה בָּהּ בִּשְׁוֵה פְּרוּטָה וְהִפְסִיד בַּבֶּגֶד שֶׁהִתִּירָהּ מִמֶּנָּה בִּשְׁוֵה פְּרוּטָה וְלֹא הִפְסִיד בַּמַּטְלִית כְּלוּם הֲרֵי זֶה לֹא מָעַל מִפְּנֵי שֶׁנֶּהֱנָה בְּדָבָר אֶחָד וּפָגַם בְּדָבָר אַחֵר. וּכְבָר בֵּאַרְנוּ שֶׁהַנֶּהֱנֶה וּמְהַנֶּה חֲבֵרוֹ מִצְטָרֵף וַאֲפִלּוּ לִזְמַן מְרֻבֶּה:","קָדְשֵׁי קָדָשִׁים הַתְּמִימִים שֶׁתָּלַשׁ מִצִּמְרָן. כֵּיוָן שֶׁנֶּהֱנָה בִּפְרוּטָה מָעַל אַף עַל פִּי שֶׁלֹּא פָּגַם. שֶׁהֲרֵי הֵן דּוֹמִים לְכוֹס שֶׁל זָהָב שֶׁאֵינוֹ נִפְגָּם שֶׁאֵין תְּלִישַׁת הַצֶּמֶר פּוֹסֶלֶת אוֹתָן מִלִּקָּרֵב. אֲבָל אִם נָפַל בָּהֶן מוּם הוֹאִיל וְלִמְכִירָה עוֹמְדִים וְהַגִּזָּה פּוֹגֶמֶת דְּמֵיהֶן לֹא מָעַל עַד שֶׁיֵּהָנֶה וְיִפְגֹּם בִּפְרוּטָה. תָּלַשׁ מֵהֶן אַחַר שֶׁמֵּתוּ כֵּיוָן שֶׁנֶּהֱנָה מָעַל שֶׁאֵין פְּגָם לְמֵתָה. וּמְעִילָה זוֹ מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ:","הַמּוֹעֵל בְּקָדְשֵׁי בֶּדֶק הַבַּיִת כֵּיוָן שֶׁמָּעַל בִּשְׁגָגָה נִתְחַלֵּל הֶקְדֵּשׁ וְזֶה שֶׁנֶּהֱנָה אַחֲרָיו פָּטוּר. מָעַל בְּזָדוֹן הוֹאִיל וְאֵינוֹ חַיָּב בְּקָרְבַּן מְעִילָה לֹא נִתְחַלֵּל הֶקְדֵּשׁ אֶלָּא הֲרֵי הוּא בַּהֲוָיָתוֹ וְאִם בָּא אַחֵר וְנֶהֱנָה בּוֹ בִּשְׁגָגָה מָעַל. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁמָּעַל בַּקֹּדֶשׁ וְהוֹצִיאוֹ בְּתוֹרַת חֻלִּין וְהִקְנָהוּ לְאַחֵר. אֲבָל אִם נֶהֱנָה בּוֹ וּפְגָמוֹ וְלֹא הִקְנָה לְאַחֵר יֵשׁ בּוֹ מוֹעֵל אַחַר מוֹעֵל:","וְאֵין מוֹעֵל אַחַר מוֹעֵל בְּמֻקְדָּשִׁים. אֶלָּא בִּבְהֵמָה וּכְלֵי תַּשְׁמִישׁ בִּלְבַד. כֵּיצַד. בָּקַע בְּקוֹרְדוֹם שֶׁל הֶקְדֵּשׁ וְנֶהֱנָה בִּפְרוּטָה וּפָגַם וּבָא חֲבֵרוֹ וּבָקַע בּוֹ וְנֶהֱנָה וּפָגַם כֻּלָּם מָעֲלוּ. נָטַל הַקּוֹרְדוֹם וּנְתָנוֹ לַחֲבֵרוֹ הוּא מָעַל אֲבָל חֲבֵרוֹ לֹא מָעַל. שָׁתָה בְּכוֹס שֶׁל זָהָב וְנֶהֱנָה בִּפְרוּטָה וּבָא חֲבֵרוֹ וְשָׁתָה וְנֶהֱנָה וּבָא חֲבֵרוֹ וְשָׁתָה וְנֶהֱנָה כֻּלָּם מָעֲלוּ. נָטַל הַכּוֹס וּנְתָנוֹ לַחֲבֵרוֹ מַתָּנָה אוֹ מְכָרוֹ הוּא מָעַל וַחֲבֵרוֹ לֹא מָעַל. רָכַב עַל גַּבֵּי הַחֲמוֹר וְנֶהֱנָה בִּפְרוּטָה וּפָגַם וּבָא חֲבֵרוֹ וְרָכַב עָלָיו וְנֶהֱנָה וּפָגַם וּבָא חֲבֵרוֹ וְרָכַב עָלָיו וְנֶהֱנָה וּפָגַם. כֻּלָּם מָעֲלוּ. נָתַן הַחֲמוֹר לַחֲבֵרוֹ מַתָּנָה אוֹ מְכָרוֹ אוֹ הִשְׂכִּירוֹ הוּא מָעַל וַחֲבֵרוֹ לֹא מָעַל. וְכֵן הַמַּשְׁאִיל קַרְדֹּם שֶׁל הֶקְדֵּשׁ הוּא מָעַל לְפִי טוֹבַת הֲנָאָה שֶׁבּוֹ וַחֲבֵרוֹ מֻתָּר לִבְקֹעַ בּוֹ לְכַתְּחִלָּה. וְהוּא הַדִּין לִבְהֵמָה:","בֶּהֱמַת קָדְשֵׁי מִזְבֵּחַ אֵינָהּ כֵּן אֶלָּא יֵשׁ בָּהּ מוֹעֵל אַחַר מוֹעֵל עַד כַּמָּה פְּעָמִים. כֵּיצַד. תָּלַשׁ מִן הַחַטָּאת וּבָא חֲבֵרוֹ וְתָלַשׁ וּבָא חֲבֵרוֹ וְתָלַשׁ כֻּלָּן מָעֲלוּ. וְכֵן אִם נְתָנָהּ לַחֲבֵרוֹ וַחֲבֵרוֹ לַחֲבֵרוֹ כֻּלָּן מָעֲלוּ. וְיֵרָאֶה לִי שֶׁדִּין הַמְּנָחוֹת וְהָעוֹפוֹת וְהַנְּסָכִים וּכְלֵי שָׁרֵת כְּדִין הַבְּהֵמָה שֶׁכֻּלָּן קְדֻשַּׁת הַגּוּף הֵן:","בֶּהֱמַת קָדְשֵׁי הַקָּדָשִׁים שֶׁנָּפַל בָּהּ מוּם הוֹאִיל וְהִיא עוֹמֶדֶת לְפִדְיוֹן הֲרֵי הוּא כְּקָדְשֵׁי בֶּדֶק הַבַּיִת שֶׁהִיא קְדֻשַּׁת דָּמִים. וְאִם נְתָנָהּ לַחֲבֵרוֹ וַחֲבֵרוֹ לַחֲבֵרוֹ הָרִאשׁוֹן בִּלְבַד מָעַל:","אָמְרוּ חֲכָמִים שֶׁהַנּוֹטֵל אֶבֶן אוֹ קוֹרָה שֶׁל הֶקְדֵּשׁ וּנְתָנָהּ לַחֲבֵרוֹ שְׁנֵיהֶם מָעֲלוּ. וְאִם נְתָנָהּ לְזֶה הַגִּזְבָּר שֶׁהָיְתָה תַּחַת יָדוֹ הוּא מָעַל וְהַגִּזְבָּר לֹא מָעַל. וְיֵרָאֶה לִי שֶׁאֵין אֵלּוּ הַדְּבָרִים אֲמוּרִים אֶלָּא בְּמוֹעֵל בְּזָדוֹן שֶׁהֲרֵי לֹא נִתְחַלֵּל הֶקְדֵּשׁ. הַנּוֹטֵל פְּרוּטָה שֶׁל הֶקְדֵּשׁ עַל דַּעַת שֶׁהִיא שֶׁלּוֹ לֹא מָעַל עַד שֶׁיּוֹצִיא אוֹתָהּ בַּחֲפָצָיו אוֹ עַד שֶׁיִּתֵּן אוֹתָהּ בְּמַתָּנָה. נְתָנָהּ לַחֲבֵרוֹ הוּא מָעַל וַחֲבֵרוֹ לֹא מָעַל. שֶׁאֵין מוֹעֵל אַחַר מוֹעֵל בִּשְׁאָר הֶקְדֵּשׁוֹת כְּמוֹ שֶׁבֵּאַרְנוּ וְכָל כַּיּוֹצֵא בָּזֶה:","נָטַל אֶבֶן אוֹ קוֹרָה שֶׁל הֶקְדֵּשׁ לֹא מָעַל שֶׁהֲרֵי לֹא נֶהֱנָה עֲדַיִן. בָּנָה אוֹתָהּ בְּתוֹךְ בֵּיתוֹ מָעַל. נְתָנָהּ עַל גַּבֵּי חַלּוֹן שֶׁבַּתִּקְרָה וְלֹא חִבְּרָהּ לֹא מָעַל עַד שֶׁיָּדוּר תַּחְתֶּיהָ בִּשְׁוֵה פְּרוּטָה שֶׁאֵין זוֹ הֲנָיָה הַנִּכֶּרֶת:","נָטַל פְּרוּטָה שֶׁל הֶקְדֵּשׁ וּנְתָנָהּ לְבַלָּן אַף עַל פִּי שֶׁלֹּא רָחַץ מָעַל שֶׁהֲרֵי נֶהֱנָה בִּהְיוֹתוֹ רוֹחֵץ בְּכָל עֵת שֶׁיִּרְצֶה. וְכֵן אִם נְתָנָהּ לְאֶחָד מִבַּעֲלֵי אֻמָּנֻיּוֹת מָעַל אַף עַל פִּי שֶׁעֲדַיִן לֹא עָשׂוּ מְלַאכְתּוֹ:","קָנָה בָּהּ חֵפֶץ וְלֹא מָשַׁךְ אִם מִן הָעַכּוּ\"ם מָעַל. וְאִם מִן יִשְׂרָאֵל לֹא מָעַל:","הַמּוֹצִיא מְעוֹת הֶקְדֵּשׁ בִּצְרָכָיו עַל דַּעַת שֶׁהֵן חֻלִּין אַף עַל פִּי שֶׁלֹּא הוֹצִיאָן בְּדִבְרֵי חֹל מָעַל. כֵּיצַד. הַמֵּבִיא חַטָּאתוֹ וַאֲשָׁמוֹ וּפִסְחוֹ מִן הַהֶקְדֵּשׁ וְכֵן מְחֻסַּר כַּפָּרָה שֶׁהֵבִיא כַּפָּרָתוֹ מִן הַהֶקְדֵּשׁ מָעַל. וְכֻלָּם אֵין מוֹעֲלִין עַד שֶׁיִּזָּרֵק הַדָּם. לְפִיכָךְ הַמֵּבִיא מְנָחוֹת וּנְסָכִים וְלֶחֶם תּוֹדָה מִן הַהֶקְדֵּשׁ אַף עַל פִּי שֶׁעָבַר עֲבֵרָה לֹא מָעַל שֶׁאֵין כָּאן זְרִיקַת דָּם לְכַפֵּר עָלָיו:","נָתַן שִׁקְלוֹ מִמְּעוֹת הֶקְדֵּשׁ כְּשֶׁיִּתְרְמוּ הַתְּרוּמָה וְיִקְנוּ מִמֶּנָּה אֲפִלּוּ בְּהֵמָה אַחַת וְיִזָּרֵק דָּמָהּ יִמְעל הַשּׁוֹקֵל. שֶׁהֲרֵי חָלְקוּ בְּאוֹתָהּ הַבְּהֵמָה שֶׁנִּזְרַק דָּמָהּ:","הַמַּפְרִישׁ שִׁקְלוֹ וְהוֹצִיאוֹ בִּשְׁאָר צְרָכָיו. בֵּין הוּא בֵּין חֲבֵרוֹ מָעַל. נְתָנוֹ לַחֲבֵרוֹ לְשָׁקְלוֹ עַל יָדוֹ הָלַךְ וּשְׁקָלוֹ עַל יְדֵי עַצְמוֹ אִם כְּבָר נִתְרְמָה הַתְּרוּמָה מָעַל הַשּׁוֹקֵל שֶׁהַתּוֹרֵם תוֹרֵם עַל הֶעָתִיד לְהִגָּבוֹת כְּמוֹ שֶׁבֵּאַרְנוּ בִּשְׁקָלִים וּכְאִלּוּ הִגִּיעַ שֶׁקֶל זֶה לַלִּשְׁכָּה וּלְפִיכָךְ מָעַל. וְאִם עֲדַיִן לֹא נִתְרְמָה תְּרוּמָה לֹא מָעַל. וּלְעוֹלָם אֵין מוֹעֲלִין בִּשְׁיָרֵי הַלִּשְׁכָּה:"],"Mishneh Torah, Vessels 18":["כְּלִי חֶרֶס אֵינוֹ מְקַבֵּל טֻמְאָה עַד שֶׁיִּהְיֶה מְקַבֵּל וְעָשׂוּי לְקַבָּלה. אֲבָל אִם לֹא הָיָה לוֹ בֵּית קִבּוּל אוֹ שֶׁהָיָה מְקַבֵּל וְלֹא נַעֲשָׂה לְקַבָּלָה אֵינוֹ מְקַבֵּל טֻמְאָה כְּלָל לֹא מִן הַתּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים. לְפִיכָךְ הַכִּסֵּא וְהַמִּטָּה וְהַסַּפְסָל וְהַמְּנוֹרָה וְהַשֻּׁלְחָן שֶׁל חֶרֶס. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן מִכֵּלִים שֶׁאֵין לָהֶם תּוֹךְ אֵינָן מְקַבְּלִין טֻמְאָה. וְכֵן הַסִּילוֹנוֹת שֶׁהַמַּיִם מְהַלְּכִין בָּהֶן אַף עַל פִּי שֶׁהֵן כְּפוּפִין וְאַף עַל פִּי שֶׁהֵן מְקַבְּלִין הֲרֵי הֵן טְהוֹרִין מִפְּנֵי שֶׁלֹּא נַעֲשׂוּ לְקַבָּלָה אֶלָּא כְּדֵי שֶׁיֵּצְאוּ מֵהֶן הַמַּיִם. וְכֵן חָבִית שֶׁל שַׁיָּטִים וְחָבִית הַדְּפוּנָה בְּשׁוּלֵי הַמַּחַץ הוֹאִיל וְנַעֲשֵׂית כְּמוֹ בֵּית יָד שֶׁנּוֹשְׂאִין בָּהּ הַמַּחַץ וְלֹא נַעֲשֵׂית לְקַבָּלָה אֵינָהּ מְקַבֶּלֶת טֻמְאָה:","פָּנָס שֶׁהָיָה בּוֹ בֵּית קִבּוּל שֶׁמֶן מְקַבֵּל טֻמְאָה וְשֶׁאֵין בּוֹ טָהוֹר. וְכֵן מְגוּפַת הַיּוֹצְרִים שֶׁיֵּשׁ לָהּ תּוֹךְ טְמֵאָה:","מַשְׁפֵּךְ שֶׁל בַּעֲלֵי בָּתִּים טָהוֹר. וְשֶׁל רוֹכְלִין מִתְטַמֵּא מִפְּנֵי שֶׁמַּטֵּהוּ עַל צִדּוֹ וּמֵרִיחַ בּוֹ לַלּוֹקֵחַ:","כִּסּוּי כַּדֵּי יַיִן וְכַדֵּי שֶׁמֶן וְהֶחָבִיּוֹת טְהוֹרוֹת שֶׁלֹּא נַעֲשׂוּ לְקַבָּלָה. וְאִם הִתְקִינָן לְתַשְׁמִישׁ מִתְטַמְּאִין:","כִּסּוּי הָאִלְפָּס בִּזְמַן שֶׁהוּא נָקוּב וְיֵשׁ לוֹ חִדּוּד טָהוֹר. וְאִם אֵינוֹ נָקוּב וְאֵין לוֹ חִדּוּד מִתְטַמֵּא מִפְּנֵי שֶׁהָאִשָּׁה מְסַנֶּנֶת לְתוֹכוֹ אֶת הַיָּרָק. זֶה הַכְּלָל כָּל הַמְשַׁמֵּשׁ בִּכְלִי חֶרֶס כְּשֶׁהוּא כָּפוּי טָהוֹר:","טִיטְרוֹס אַף עַל פִּי שֶׁהוּא נָקוּב וּמוֹצִיא פְּרוּטוֹת מִתְטַמֵּא שֶׁהֲרֵי הַמַּיִם מִתְכַּנְּסִין בַּצְּדָדִין וְהֵן עֲשׂוּיִין לְקַבָּלָה:","הַלַּפִּיד שֶׁל חֶרֶס שֶׁמַּנִּיחִין מַטְלִיּוֹת הַבְּגָדִים וְהַשֶּׁמֶן בְּתוֹכוֹ וְהוּא דּוֹלֵק מִתְטַמֵּא. וְכֵן כְּלִי שֶׁמַּנִּיחִין תַּחַת הַנֵּרוֹת לְקַבֵּל הַשֶּׁמֶן מִתְטַמֵּא:","גִּסְטְרָא שֶׁמַּנִּיחִין תַּחַת הַכֵּלִים לְקַבֵּל מַשְׁקִין הַנּוֹזְלִין מִן הַכְּלִי מְקַבְּלִין טֻמְאָה:","סְפִינָה שֶׁל חֶרֶס אַף עַל פִּי שֶׁהִיא מְקַבֶּלֶת אֵינָהּ מְקַבֶּלֶת טֻמְאָה שֶׁאֵין הַסְּפִינָה בִּכְלַל הַכֵּלִים הָאֲמוּרִין בַּתּוֹרָה בֵּין הִיא שֶׁל חֶרֶס בֵּין הִיא שֶׁל עֵץ בֵּין גְּדוֹלָה בֵּין קְטַנָּה:","כָּל הַכֵּלִים שֶׁנִּשְׁבְּרוּ וְנִפְסְדָה צוּרָתָן אֵין שִׁבְרֵיהֶן מְקַבְּלִין טֻמְאָה אַף עַל פִּי שֶׁאוֹתָן הַשְּׁבָרִים רְאוּיִין לְתַשְׁמִישׁ. חוּץ מִשִּׁבְרֵי כְּלֵי חֶרֶס שֶׁאִם הָיָה בָּהֶן חֶרֶס הָרָאוּי לְקַבֵּל הֲרֵי הוּא מְקַבֵּל טֻמְאָה שֶׁנֶּאֱמַר (ויקרא יא לג) \"וְכָל כְּלִי חֶרֶס\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה לֹא בָּא לְרַבּוֹת אֶלָּא שִׁבְרֵי כְּלֵי חֶרֶס. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה לְחֶרֶס זֶה תּוֹךְ לְקַבֵּל בּוֹ הַמַּשְׁקִין כְּשֶׁהָיָה הַחֶרֶס יוֹשֵׁב לֹא סָמוּךְ. אֲבָל אִם אֵינוֹ יָכוֹל לְקַבֵּל אֶלָּא אִם כֵּן סוֹמְכִין אוֹתוֹ אֵינוֹ מְקַבֵּל טֻמְאָה:","הַחֶרֶס שֶׁאֵינוֹ יָכוֹל לֵישֵׁב כְּדֵי שֶׁיְּקַבֵּל מִפְּנֵי אָזְנוֹ אוֹ שֶׁהָיָה בּוֹ חִדּוּד וְהַחִדּוּד מַכְרִיעוֹ לְצַד אַחֵר הֲרֵי זֶה טָהוֹר אַף עַל פִּי שֶׁנִּטְּלָה הָאֹזֶן אוֹ נִשְׁבַּר הַחִדּוּד שֶׁכָּל כְּלִי חֶרֶס שֶׁטָּהַר שָׁעָה אַחַת אֵין לוֹ טֻמְאָה לְעוֹלָם:","כְּלֵי חֶרֶס שֶׁשּׁוּלֵיהֶן חַדִּין כְּמִזְרָקוֹת שֶׁנִּשְׁבְּרוּ וְשׁוּלֵיהֶן מְקַבְּלִין אַף עַל פִּי שֶׁאֵינָן מְקַבְּלִין אֶלָּא אִם כֵּן נִסְמְכוּ כְּגוֹן שׁוּלֵי הַקֻּרְפִיוֹת וְהַכּוֹסוֹת הֲרֵי אֵלּוּ מְקַבְּלִין טֻמְאָה. שֶׁלְּכָךְ נַעֲשׂוּ מִתְּחִלָּתָן שֶׁיִּהְיוּ שׁוּלֵיהֶן מְקַבְּלִין בִּסְמִיכָה אוֹ בַּאֲחִיזָה:","כַּמָּה יְקַבֵּל הַחֶרֶס וְיִהְיֶה מְקַבֵּל טֻמְאָה. אִם הָיָה הַכְּלִי כְּשֶׁהָיָה שָׁלֵם וּמֵכִיל כְּדֵי סִכַּת אָדָם קָטָן עַד חָבִיּוֹת שֶׁהֵן מְקַבְּלוֹת כִּסְאָהּ אוֹ קָרוֹב וְנִשְׁבְּרוּ וְנִשְׁאַר בָּחֲרָסִים בֵּין מִקַּרְקְעֵיהֶן בֵּין מִדָּפְנֵיהֶן חֶרֶס שֶׁהוּא מְקַבֵּל כְּשֶׁהוּא יוֹשֵׁב רְבִיעִית הֲרֵי זֶה מְקַבֵּל טֻמְאָה:","הָיָה הַכְּלִי מֵחָבִית הַמְּכִילָה כִּסְאָה עַד חָבִית הַמְכִילָה סָאתַיִם אוֹ יֶתֶר וְנִשְׁבְּרָה אִם הָיָה בַּחֶרֶס הַנִּשְׁאָר כְּדֵי לְקַבֵּל חֲצִי לוֹג הֲרֵי זֶה מְקַבֵּל טֻמְאָה. הָיָה הַכְּלִי מֵחָבִית הַמְכִילָה סָאתַיִם עַד חֲצָבִים גְּדוֹלִים וְנִשְׁבְּרוּ אִם נִשְׁאַר מֵהֶן חֶרֶס הַמְקַבֵּל לוֹג הֲרֵי זֶה מְקַבֵּל טֻמְאָה. הָיוּ הַחֲרָסִים מְקַבְּלִין פָּחוֹת מִשִּׁעוּרִין אֵלּוּ אֵין מְקַבְּלִין טֻמְאָה:","כְּלִי חֶרֶס קָטָן כְּגוֹן הַפַּךְ וְכַיּוֹצֵא בּוֹ שֶׁנִּשְׁבַּר וְנִשְׁאַר מִקַּרְקָעִיתוֹ חֶרֶס הַמְקַבֵּל כָּל שֶׁהוּא כְּשֶׁהוּא יוֹשֵׁב וְהָיָה חַד בְּיוֹתֵר שֶׁנִּמְצָא כִּכְלִי קָטָן הֲרֵי זֶה מְקַבֵּל טֻמְאָה. וְאִם נִשְׁאַר מִדָּפְנוֹתֵיהֶן חֶרֶס הַמְקַבֵּל אֵינוֹ מְקַבֵּל טֻמְאָה לְפִי שֶׁדָּפְנוֹת כֵּלִים אֵלּוּ וְכַיּוֹצֵא בָּהֶן כְּשָׁוִין הֵן וְאֵין לָהֶן תּוֹךְ הַנִּכָּר וְנִמְצְאוּ כִּפְשׁוּטֵי כְּלֵי חֶרֶס:","חֶזְקַת חֲרָסִים הַנִּמְצָאִים בְּכָל מָקוֹם טְהוֹרִים חוּץ מֵהַנִּמְצָאִים בְּבֵית הַיּוֹצֵר מִפְּנֵי שֶׁרֻבָּן גִּסְטְרָיוֹת הֵן לַכֵּלִים וְהַגִּסְטְרָא מְקַבֶּלֶת טֻמְאָה אַף עַל פִּי שֶׁהִיא מִשִּׁבְרֵי כֵּלִים:"],"Mishneh Torah, Vessels 3":["כָּל כְּלִי עֵץ הֶעָשׂוּי לְנַחַת אֲפִלּוּ אֵינוֹ מְקַבֵּל אֶלָּא דָּבָר מוּעָט אֵינוֹ מְקַבֵּל טֻמְאָה לֹא מִן הַתּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים. וְכָל כְּלִי עֵץ הֶעָשׂוּי לְהִתְטַלְטֵל מָלֵא וְרֵיקָן כְּשַׂק אֲפִלּוּ הָיָה מַחֲזִיק מֵאָה סְאָה וְאַף עַל פִּי שֶׁיֵּשׁ לוֹ שׁוּלַיִם הוֹאִיל וְאֵינוֹ עָשׂוּי לְנַחַת הֲרֵי זֶה מְקַבֵּל טֻמְאָה דִּין תּוֹרָה כִּשְׁאָר כְּלֵי קִבּוּל. וְכָל כְּלִי עֵץ שֶׁהוּא סְתָם אִם הָיוּ לוֹ שׁוּלַיִם לֵישֵׁב עֲלֵיהֶם עַל הַקַּרְקַע כְּדֵי שֶׁלֹּא יְהֵא נוֹחַ לְהִתְגַּלְגֵּל וְהָיָה מַחֲזִיק אַרְבָּעִים סְאָה בְּלַח שֶׁהֵן כּוֹרַיִים בְּיָבֵשׁ אֵינוֹ מְקַבֵּל טֻמְאָה כְּלָל לֹא מִן הַתּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים מִפְּנֵי שֶׁחֶזְקָתוֹ שֶׁעָשׂוּי לְנַחַת. וּדְבָרִים אֵלּוּ דִּבְרֵי קַבָּלָה הֵן. מִפִּי הַשְּׁמוּעָה לָמְדוּ מָה שַׂק שֶׁהוּא מִתְטַלְטֵל מָלֵא וְרֵיקָן אַף כְּלִי עֵץ לֹא יִטְמָא אֶלָּא אִם כֵּן הָיָה מִטַּלְטֵל מָלֵא וְרֵיקָן לְהוֹצִיא כְּלִי עֵץ הֶעָשׂוּי לְנַחַת:","הַכֵּלִים שֶׁחֶזְקָתָן שֶׁהֵן עֲשׂוּיִין לְנַחַת כְּגוֹן שִׁדָּה תֵּבָה וּמִגְדָּל וְכַוֶּרֶת הַקַּשׁ וְכַוֶּרֶת הַקָּנִים וּבוֹר סְפִינָה גְּדוֹלָה וְכַיּוֹצֵא בְּאֵלּוּ. אִם הֵן מַחֲזִיקִין אַרְבָּעִים סְאָה אֵין מְקַבְּלִין טֻמְאָה. וְאֵלּוּ הֵן הַכֵּלִים שֶׁל עֵץ שֶׁהֵן עֲשׂוּיִין לְהִתְטַלְטֵל בִּמְלוֹאָן. דִּרְדּוּר שֶׁמַּנִּיחִין אוֹתוֹ עַל הָעֲגָלָה וְקוֹסְטוֹת הַמְּלָכִים וַעֲרֵבַת הַעֲבְּדָן וּבוֹר סְפִינָה קְטַנָּה שֶׁאֵינָהּ יְכוֹלָה לְהַלֵּךְ בְּאֶמְצַע הַיָּם הַגָּדוֹל וְהָאָרוֹן. כָּל אֶחָד מֵחֲמֵשֶׁת כְּלֵי עֵץ אֵלּוּ אַף עַל פִּי שֶׁהֵן מְקַבְּלִין יוֹתֵר מֵאַרְבָּעִים סְאָה הֲרֵי אֵלּוּ מְקַבְּלִין טֻמְאָה שֶׁלֹּא נַעֲשׂוּ מִתְּחִלָּתָן אֶלָּא לְהִטַּלְטֵל מְלֵאִין. וּשְׁאָר כָּל כְּלֵי עֵץ אִם הָיוּ מְקַבְּלִין אַרְבָּעִים סְאָה וְיֵשׁ לָהֶם שׁוּלַיִם חֶזְקָתָן שֶׁאֵינָן עֲשׂוּיִין לְהִתְטַלְטֵל בִּמְלוֹאָן וּלְפִיכָךְ אֵין מְקַבְּלִין טֻמְאָה. וְכֵן כְּלֵי עֶצֶם וּכְלֵי הָעוֹר הַמְקַבְּלִין אַרְבָּעִים סְאָה בְּלַח אֵין מְקַבְּלִין טֻמְאָה אֶלָּא אִם כֵּן נַעֲשׂוּ מִתְּחִלָּתָן כְּשֶׁהֵן מְלֵאִין:","הַשִּׁדָּה וְהַתֵּבָה וְהַמִּגְדָּל שֶׁל זְכוּכִית הַבָּאִים בְּמִדָּה טְהוֹרִין וּשְׁאָר כְּלֵי זְכוּכִית אַף עַל פִּי שֶׁמְּקַבְּלִין אַרְבָּעִים סְאָה הֲרֵי הֵן מְקַבְּלִין טֻמְאָה. וְזֶה חֹמֶר בִּכְלֵי זְכוּכִית מִבִּכְלֵי עֵץ:","כָּל כְּלִי שֶׁיֵּשׁ בְּשִׁבּוּרוֹ אַמָּה עַל אַמָּה בְּרוּם שָׁלֹשׁ הֲרֵי הוּא מַחֲזִיק אַרְבָּעִים סְאָה בְּלַח. וּכְשֶׁמּוֹדְדִין אֶת הַכְּלִי מוֹדְדִין אוֹתוֹ מִבַּחוּץ אִם הָיָה בּוֹ אַמָּה עַל אַמָּה בְּרוּם שָׁלֹשׁ אַף עַל פִּי שֶׁאֵין תּוֹכוֹ אֶלָּא פָּחוֹת מִזֶּה הֲרֵי הוּא טָהוֹר שֶׁאֵין עֳבִי הַדְּפָנוֹת מְמַעֵט. אֲבָל עֳבִי הָרַגְלַיִם וָעֳבִי הַזֵּר אִם הָיָה לוֹ זֵר אֵין נִמְדָּדִין עִמּוֹ:","הָיָה בְּתוֹךְ הַכְּלִי תֵּבָה קְטַנָּה כְּגוֹן מוּכְנִי שֶׁבְּתוֹךְ הַשִּׁדָּה בִּזְמַן שֶׁהִיא נִשְׁמֶטֶת אֵינָהּ נִמְדֶּדֶת עִמָּהּ וְאֵינָהּ חִבּוּר לָהּ וְאֵינָהּ מַצֶּלֶת עִמָּהּ בְּאֹהֶל הַמֵּת. וְאִם אֵינָהּ נִשְׁמֶטֶת נִמְדֶּדֶת עִמָּהּ וַהֲרֵי הֵן כִּכְלִי אֶחָד:","הָיָה לַכְּלִי כִּסּוּי קָמוּר בִּזְמַן שֶׁהוּא קָבוּעַ נִמְדָּד עִמּוֹ. אֵינוֹ קָבוּעַ אֵינוֹ נִמְדָּד עִמּוֹ. הָיוּ בּוֹ מְגוּרוֹת מִבִּפְנִים נִמְדֶּדֶת עִמּוֹ. וְאִם הָיוּ מִבַּחוּץ אֵינָן נִמְדָּדוֹת עִמּוֹ:","כְּלִי עֵץ שֶׁאֵינוֹ מְקַבֵּל אַרְבָּעִים סְאָה כְּדַרְכּוֹ אֶלָּא אִם כֵּן הִטָּהוּ עַל צִדּוֹ אוֹ סְמָכוֹ בְּדָבָר אַחֵר הוֹאִיל וּמְקַבֵּל אַרְבָּעִים סְאָה מִכָּל מָקוֹם טָהוֹר:","הַשִּׁדָּה וְהַתֵּבָה שֶׁנִּטְּלָה אַחַת מֵרַגְלֵיהֶן אַף עַל פִּי שֶׁלֹּא נִקְּבוּ אֶלָּא הֲרֵי הֵן מְקַבְּלִין הֲרֵי אֵלּוּ טְהוֹרִין וַעֲדַיִן יֵשׁ לָהֶם שׁוּלַיִם וְחֶזְקָתָן שֶׁהֵן לְנַחַת כְּשֶׁהָיוּ:"],"Mishneh Torah, Vessels of the Sanctuary and Those Who Serve Therein 5":["כֹּהֵן גָּדוֹל צָרִיךְ שֶׁיִּהְיֶה גָּדוֹל מִכָּל אֶחָיו הַכֹּהֲנִים בְּנוֹי בְּכֹחַ בְּעשֶׁר בְּחָכְמָה וּבְמַרְאֶה. אֵין לוֹ מָמוֹן כָּל הַכֹּהֲנִים נוֹתְנִין לוֹ מִשֶּׁלָּהֶן כָּל אֶחָד לְפִי עָשְׁרוֹ עַד שֶׁיַּעֲשִׁיר יוֹתֵר מֵעָשִׁיר שֶׁבְּכֻלָּן:","וְאֵין אֶחָד מִכָּל אֵלּוּ מְעַכֵּב אֶלָּא כָּל זֶה לְמִצְוָה אֲבָל אִם נִתְרַבָּה מִכָּל מָקוֹם נִתְרַבָּה:","וְחַיָּב כֹּהֵן גָּדוֹל לִנְהֹג כָּבוֹד בְּעַצְמוֹ. וְלֹא יָקֵל בְּעַצְמוֹ עִם שְׁאָר הָעָם וְלֹא יִרְאוּ אוֹתוֹ עָרוּם לֹא בְּבֵית הַמֶּרְחָץ וְלֹא בְּבֵית הַכִּסֵּא וְלֹא כְּשֶׁמִּסְתַּפֵּר שֶׁנֶּאֱמַר (ויקרא כא י) \"הַכֹּהֵן הַגָּדוֹל מֵאֶחָיו\" מְלַמֵּד שֶׁנּוֹהֲגִין בּוֹ גְּדֻלָּה יְתֵרָה. רָצָה הוּא שֶׁיִּרְחֲצוּ אֲחֵרִים עִמּוֹ הָרְשׁוּת בְּיָדוֹ:","לֹא יִכָּנֵס לְבֵית הַמִּשְׁתֶּה וְלֹא לִסְעֻדָּה שֶׁל רַבִּים אֲפִלּוּ הֵם שֶׁל מִצְוָה. אֲבָל הוֹלֵךְ הוּא אִם רָצָה לְבֵית הָאָבֵל. וּכְשֶׁהוּא הוֹלֵךְ אֵינוֹ הוֹלֵךְ בְּעִרְבּוּבְיָא עִם שְׁאָר הַכֹּהֲנִים. אֶלָּא מְסַבְּבִין אוֹתוֹ הַכֹּהֲנִים וְחוֹלְקִין לוֹ כָּבוֹד. וְהַסְּגָן מְמַצְּעוֹ בֵּינוֹ לְבֵין הָעָם. וְהַסְּגָן וּמָשׁוּחַ שֶׁעָבַר מִימִינוֹ. וְרֹאשׁ בֵּית אָב וְהָאֲבֵלִים וְכָל הָעָם מִשְּׂמֹאלוֹ. וְאוֹמֵר לַאֲבֵלִים תְּנֻחֲמוּ. וְהֵן מְכַבְּדִין אוֹתוֹ כְּפִי כֹּחָן:","מֵת לוֹ מֵת אֵינוֹ יוֹצֵא אַחֲרָיו. וְאֵינוֹ יוֹצֵא מִפֶּתַח בֵּיתוֹ אוֹ מִן הַמִּקְדָּשׁ. וְכָל הָעָם בָּאִים לְנַחֲמוֹ לְבֵיתוֹ. וְהוּא עוֹמֵד בְּשׁוּרָה וּסְגָן מִימִינוֹ וְרֹאשׁ בֵּית אָב וְכָל הָעָם מִשְּׂמֹאלוֹ. וְאוֹמְרִים לוֹ אָנוּ כַּפָּרָתְךָ וְהוּא אוֹמֵר לָהֶם תִּתְבָּרְכוּ מִן הַשָּׁמַיִם:","וּכְשֶׁמַּבְרִין אוֹתוֹ כָּל הָעָם מְסֻבִּין עַל הָאָרֶץ וְהוּא מֵסֵב עַל הַסַּפְסָל. וְאֵינוֹ קוֹרֵעַ עַל מֵתוֹ כִּשְׁאָר הַכֹּהֲנִים שֶׁנֶּאֱמַר (ויקרא כא י) \"וּבְגָדָיו לֹא יִפְרֹם\". וְאִם קָרַע לוֹקֶה. אֲבָל קוֹרֵעַ הוּא מִלְּמַטָּה כְּנֶגֶד רַגְלָיו. וְאֵינוֹ מַרְבֶּה פֶּרַע לְעוֹלָם שֶׁנֶּאֱמַר (ויקרא כא י) \"אֶת רֹאשׁוֹ לֹא יִפְרָע\" וַאֲפִלּוּ בְּעֵת שֶׁלֹּא יִכָּנֵס לַמִּקְדָּשׁ. אֶלָּא מְסַפֵּר מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת. וְאֵינוֹ מְסַפֵּר בְּתַעַר אֶלָּא בְּזוּג רֹאשׁ שַׂעֲרָה זוֹ בְּעִקָּר זוֹ עַד שֶׁיֵּרָאֶה כְּאִלּוּ הוּא צָמַח כְּאַחַת שֶׁנֶּאֱמַר (יחזקאל מד כ) \"רֹאשָׁם לֹא יְגַלֵּחוּ וּפֶרַע לֹא יְשַׁלֵּחוּ כָּסוֹם יִכְסְמוּ אֶת רָאשֵׁיהֶן\":","וּבַיִת יִהְיֶה לוֹ מוּכָן בַּמִּקְדָּשׁ וְהוּא הַנִּקְרָא לִשְׁכַּת כֹּהֵן גָּדוֹל. וְתִפְאַרְתּוֹ וּכְבוֹדוֹ שֶׁיִּהְיֶה יוֹשֵׁב בַּמִּקְדָּשׁ כָּל הַיּוֹם. וְלֹא יֵצֵא אֶלָּא לְבֵיתוֹ בִּלְבַד בַּלַּיְלָה אוֹ שָׁעָה אוֹ שְׁתַּיִם בַּיּוֹם. וְיִהְיֶה בֵּיתוֹ בִּירוּשָׁלַיִם וְאֵינוֹ זָז מִשָּׁם:","כֹּהֵן גָּדוֹל דָּן וְדָנִין אוֹתוֹ וּמְעִידִין עָלָיו. וְאֵין דָּנִין אוֹתוֹ דִּינֵי נְפָשׁוֹת אֶלָּא בְּבֵית דִּין הַגָּדוֹל בִּלְבַד שֶׁנֶּאֱמַר (שמות יח כב) \"כָּל הַדָּבָר הַגָּדל יָבִיאוּ אֵלֶיךָ\":","הָיָה יוֹדֵעַ עֵדוּת אֵינוֹ חַיָּב לְהָעִיד וַאֲפִלּוּ בְּבֵית דִּין הַגָּדוֹל שֶׁזֶּה אֵינוֹ כָּבוֹד לוֹ שֶׁיֵּלֵךְ וְיָעִיד. וְאִם הָיְתָה עֵדוּת לְמֶלֶךְ יִשְׂרָאֵל הֲרֵי זֶה הוֹלֵךְ בְּבֵית דִּין הַגָּדוֹל וּמֵעִיד לוֹ:","וּכְבָר בֵּאַרְנוּ בְּסֵפֶר קְדֻשָּׁה שֶׁהוּא אָסוּר בְּאַלְמָנָה וּמְצֻוֶּה עַל הַבְּתוּלָה. וְאֵינוֹ נוֹשֵׂא שְׁתֵּי נָשִׁים וְאִם נָשָׂא שְׁתַּיִם אֵינוֹ יָכוֹל לַעֲבֹד בְּיוֹם הַצּוֹם עַד שֶׁיְּגָרֵשׁ לְאַחַת. וְחוֹלֵץ וְחוֹלְצִים לְאִשְׁתּוֹ. וּמְיַבְּמִין אֶת אִשְׁתּוֹ. וְאִם גֵּרֵשׁ אִשָּׁה מֻתֶּרֶת לְהִנָּשֵׂא לִשְׁאָר הָעָם:","בִּזְמַן שֶׁכֹּהֵן גָּדוֹל נִכְנַס לַהֵיכָל לְהִשְׁתַּחֲווֹת שְׁלֹשָׁה אוֹחֲזִין בּוֹ. אֶחָד בִּימִינוֹ וְאֶחָד בִּשְׂמֹאלוֹ וְאֶחָד בַּאֲבָנִים טוֹבוֹת שֶׁבָּאֵפוֹד מֵאֲחוֹרָיו. וְיִכָּנֵס לַהֵיכָל וְיִשְׁתַּחֲוֶה. וְכֵיוָן שֶׁיִּשְׁמַע הַסְּגָן קוֹל רַגְלָיו שֶׁל כֹּהֵן גָּדוֹל שֶׁהוּא יוֹצֵא מַגְבִּיהַּ לוֹ אֶת הַפָּרֹכֶת. וְאַחַר שֶׁיֵּצֵא יִכָּנְסוּ אֶחָיו הַכֹּהֲנִים וְיִשְׁתַּחֲווּ וְיֵצְאוּ:","בְּכָל יוֹם שֶׁיִּרְצֶה לְהַקְטִיר הַקְּטֹרֶת מַקְטִיר וְנוֹטֵל חֵלֶק בָּרֹאשׁ בְּקָדְשֵׁי הַמִּקְדָּשׁ כֻּלָּן. כֵּיצַד. כְּשֶׁיִּרְצֶה אוֹמֵר זוֹ הַחַטָּאת שֶׁלִּי וְזֶה הָאָשָׁם שֶׁלִּי. וְאֵינוֹ עוֹבֵד בְּפַיִס. אֶלָּא כָּל עֵת שֶׁיִּרְצֶה לְהַקְרִיב מַקְרִיב כָּל מַה שֶּׁיִּרְצֶה. וַהֲרֵי הוּא בְּקָדְשֵׁי הַגְּבוּל כִּשְׁאָר הַכֹּהֲנִים:","בִּזְמַן שֶׁרוֹצֶה כֹּהֵן גָּדוֹל לְהַקְרִיב הָיָה עוֹלֶה בַּכֶּבֶשׁ וְהַסְּגָן מִימִינוֹ. הִגִּיעַ לְמַחֲצִית הַכֶּבֶשׁ אָחַז הַסְּגָן בִּימִינוֹ וְהֶעֱלָהוּ. וְהוֹשִׁיט לוֹ הַכֹּהֵן שֶׁהוּא מוֹלִיךְ אֶת רֹאשׁ הָעוֹלָה הָאֵיבָרִים שֶׁבְּיָדוֹ וְסוֹמֵךְ עֲלֵיהֶן וְזוֹרְקָן לָאֵשׁ:","וְכָךְ הָיוּ מוֹשִׁיטִין לוֹ שְׁאָר הָאֵיבָרִים. כָּל אֶחָד וְאֶחָד נוֹתֵן הָאֵיבָרִים שֶׁבְּיָדוֹ לָרִאשׁוֹן. וְהָרִאשׁוֹן נוֹתֵן לְכֹהֵן גָּדוֹל וְהוּא סוֹמֵךְ וְזוֹרֵק לָאֵשׁ. וְאִם רָצָה לִסְמֹךְ בִּלְבַד וְיִהְיֶה [כֹּהֵן] אַחֵר זוֹרֵק לָאֵשׁ עוֹשֶׂה. וְאֵין שָׁם סְמִיכָה עַל הָאֵיבָרִים אֶלָּא לְכֹהֵן גָּדוֹל בִּלְבַד מִפְּנֵי כְּבוֹדוֹ. אֲבָל כָּל הַסְּמִיכוֹת עַל בַּעֲלֵי חַיִּים הֵם:","כְּשֶׁיִּגְדַּל הַכֹּהֵן וְיֵעָשֶׂה אִישׁ הֲרֵי הוּא כָּשֵׁר לַעֲבוֹדָה. אֲבָל אֶחָיו הַכֹּהֲנִים לֹא הָיוּ מְנִיחִין אוֹתוֹ לַעֲבֹד בַּמִּקְדָּשׁ עַד שֶׁיִּהְיֶה בֶּן עֶשְׂרִים שָׁנָה. וְאֵינוֹ נִכְנָס לָעֲזָרָה לַעֲבוֹדָה תְּחִלָּה אֶלָּא בְּשָׁעָה שֶׁהַלְוִיִּם אוֹמְרִים שִׁירָה:","אֵין הַכֹּהֵן עוֹבֵד תְּחִלָּה וְכֵן כֹּהֵן גָּדוֹל אֵינוֹ עוֹבֵד תְּחִלָּה עַד שֶׁיָּבִיא עֲשִׂירִית הָאֵיפָה מִשֶּׁלּוֹ וְעוֹבֵד בְּיָדוֹ שֶׁנֶּאֱמַר (ויקרא ו יג) \"זֶה קָרְבַּן אַהֲרֹן וּבָנָיו אֲשֶׁר יַקְרִיבוּ לַה' בְּיוֹם הִמָּשַׁח אֹתוֹ\". וְאִם עָבַד קֹדֶם שֶׁיָּבִיא עֲשִׂירִית הָאֵיפָה וְכֵן כֹּהֵן גָּדוֹל שֶׁעָבַד בִּכְהֻנָּה גְּדוֹלָה קֹדֶם שֶׁיָּבִיא עֲשִׂירִית הָאֵיפָה עֲבוֹדָתוֹ כְּשֵׁרָה:","כֹּהֵן שֶׁלֹּא עָבַד עֲדַיִן מִיָּמָיו שֶׁמִּנּוּהוּ כֹּהֵן גָּדוֹל הֲרֵי זֶה מֵבִיא עֲשִׂירִית הָאֵיפָה וְעוֹבְדָהּ בְּיָדוֹ בַּתְּחִלָּה כִּשְׁאָר חִנּוּךְ כָּל כֹּהֵן הֶדְיוֹט וְאַחַר כָּךְ מַקְרִיב עֲשִׂירִית הָאֵיפָה שְׁנִיָּה שֶׁהִיא חִנּוּךְ כֹּהֵן גָּדוֹל. וְאַחַר כָּךְ מַקְרִיב עֲשִׂירִית הָאֵיפָה שְׁלִישִׁית שֶׁהִיא חֲבִיתֵי כֹּהֵן גָּדוֹל שֶׁמַּקְרִיב בְּכָל יוֹם כְּמוֹ שֶׁיִּתְבָּאֵר וּמַעֲשֵׂה שְׁלָשְׁתָּן שָׁוֶה הוּא:"],"Mishneh Torah, Vows 13":["מֵפֵר אָדָם אוֹ מְקַיֵּם דִּבְרֵי אִשְׁתּוֹ אוֹ בִּתּוֹ בִּכָל לָשׁוֹן וְאַף עַל פִּי שֶׁאֵינָהּ מַכֶּרֶת. שֶׁאֵין הָאִשָּׁה צְרִיכָה לִשְׁמֹעַ הַהֲפָרָה אוֹ הַקִּיּוּם:","וְכֵיצַד מֵפֵר. אוֹמֵר מוּפָר אוֹ בָּטֵל אוֹ אֵין נֵדֶר זֶה כְּלוּם וְכַיּוֹצֵא בִּדְבָרִים שֶׁעִנְיָנָם עֲקִירַת הַנֵּדֶר מֵעִקָּרוֹ. בֵּין בְּפָנֶיהָ בֵּין שֶׁלֹּא בְּפָנֶיהָ. אֲבָל אִם אָמַר לָהּ אִי אֶפְשִׁי שֶׁתִּדֹּרִי אוֹ אֵין כָּאן נֵדֶר הֲרֵי זֶה לֹא הֵפֵר. וְכֵן הָאוֹמֵר לְאִשְׁתּוֹ אוֹ לְבִתּוֹ מָחוּל לִיךְ אוֹ מֻתָּר לִיךְ אוֹ שָׁרוּי לִיךְ וְכָל כַּיּוֹצֵא בְּעִנְיָן זֶה לֹא אָמַר כְּלוּם. שֶׁאֵין הָאָב וְהַבַּעַל מַתִּיר כְּמוֹ הֶחָכָם אֶלָּא עוֹקֵר הַנֵּדֶר מִתְּחִלָּתוֹ וּמְפֵרוֹ:","וְכֵיצַד מְקַיֵּם. כְּגוֹן שֶׁיֹּאמַר לָהּ קַיָּם לֵיכִי אוֹ יָפֶה נָדַרְתְּ אוֹ אֵין כְּמוֹתֵךְ אוֹ אִלּוּ לֹא נָדַרְתְּ הָיִיתִי מַדִּירֵךְ וְכָל כַּיּוֹצֵא בִּדְבָרִים שֶׁמַּשְׁמָעָן שֶׁרָצָה בְּנֵדֶר זֶה:","הַמְבַטֵּל נִדְרֵי אִשְׁתּוֹ אוֹ בִּתּוֹ אֵינוֹ צָרִיךְ לוֹמַר כְּלוּם וְנִתְבַּטְּלוּ כָּל הַנְּדָרִים:","וּמַהוּ הַבִּטּוּל שֶׁיָּכֹף אוֹתָהּ לַעֲשׂוֹת דָּבָר שֶׁאָסְרָה אוֹתוֹ. אֲבָל הַהֲפָרָה אֵינוֹ כּוֹפֶה אוֹתָהּ אֶלָּא מֵפֵר לָהּ וּמְנִיחָהּ אִם רָצְתָה עוֹשָׂה וְאִם רָצְתָה אֵינָהּ עוֹשָׂה:","כֵּיצַד. נָדְרָה אוֹ נִשְׁבְּעָה שֶׁלֹּא תֹּאכַל אוֹ שֶׁלֹּא תִּשְׁתֶּה וְאָמַר לָהּ מוּפָר לָךְ הֲרֵי זֶה הֵפֵר וּמֻתֶּרֶת לֶאֱכל וְלִשְׁתּוֹת. נָטַל וְנָתַן לָהּ וְאָמַר לָהּ טְלִי וְאִכְלִי טְלִי וּשְׁתִי הֲרֵי זוֹ אוֹכֶלֶת וְשׁוֹתָת וְהַנֵּדֶר בָּטֵל מֵאֵלָיו:","הַמֵּפֵר נִדְרֵי בִּתּוֹ אוֹ אִשְׁתּוֹ צָרִיךְ לְהוֹצִיא בִּשְׂפָתָיו. וְאִם הֵפֵר בְּלִבּוֹ אֵינוֹ מוּפָר. אֲבָל הַמְבַטֵּל אֵינוֹ צָרִיךְ לְהוֹצִיא בִּשְׂפָתָיו אֶלָּא מְבַטֵּל בְּלִבּוֹ בִּלְבַד וְכוֹפֶה אוֹתָהּ לַעֲשׂוֹת בֵּין עָשְׂתָה בֵּין לֹא עָשְׂתָה בָּטֵל הַנֵּדֶר:","מְפֵרִין נְדָרִים בְּשַׁבָּת בֵּין לְצֹרֶךְ הַשַּׁבָּת בֵּין שֶׁלֹּא לְצֹרֶךְ הַשַּׁבָּת. וְלֹא יֹאמַר לָהּ בְּשַׁבָּת מוּפָר לִיךְ כְּדֶרֶךְ שֶׁאוֹמֵר בְּחל אֶלָּא מְבַטֵּל בְּלִבּוֹ וְאוֹמֵר לָהּ טְלִי אִכְלִי טְלִי וּשְׁתִי וְכַיּוֹצֵא בָּזֶה:","הָאוֹמֵר לְאִשְׁתּוֹ אוֹ לְבִתּוֹ כָּל הַנְּדָרִים שֶׁתִּדֹּרִי מִכָּאן וְעַד שֶׁאָבוֹא מִמָּקוֹם פְּלוֹנִי הֲרֵי הֵן קַיָּמִין אוֹ הֲרֵי הֵן מוּפָרִין לֹא אָמַר כְּלוּם. עָשָׂה שָׁלִיחַ לְהָפֵר לָהּ אוֹ לְקַיֵּם לָהּ אֵינוֹ כְּלוּם שֶׁנֶּאֱמַר (במדבר ל יד) \"אִישָׁהּ יְקִימֶנּוּ וְאִישָׁהּ יְפֵרֶנּוּ\". וְכֵן הָאָב בְּעַצְמוֹ וְלֹא בִּשְׁלוּחוֹ:","אָסְרָה עַצְמָהּ בִּתְאֵנִים וַעֲנָבִים בֵּין בְּנֵדֶר בֵּין בִּשְׁבוּעָה. בֵּין שֶׁאָסְרָה עַצְמָהּ בְּכָל הַמִּין. בֵּין שֶׁאָמְרָה תְּאֵנִים וַעֲנָבִים אֵלּוּ. וְקִיֵּם לִתְאֵנִים וְהֵפֵר לַעֲנָבִים. אוֹ שֶׁקִּיֵּם לַעֲנָבִים וְהֵפֵר לִתְאֵנִים. מַה שֶּׁקִּיֵּם קַיָּם וּמַה שֶּׁהֵפֵר מוּפָר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאֵין אוֹמְרִין בַּהֲפָרָה נֵדֶר שֶׁהוּפַר מִקְצָתוֹ הוּפַר כֻּלּוֹ כְּדֶרֶךְ שֶׁאוֹמְרִין בְּהַתָּרָה:","מִי שֶׁנָּדְרָה אִשְׁתּוֹ וְשָׁמַע וְהִתְפִּיס עַצְמוֹ בְּנִדְרָהּ אֵינוֹ יָכוֹל לְהָפֵר שֶׁהֲרֵי קִיֵּם לָהּ. נָדַר הוּא וְהִתְפִּיסָה עַצְמָהּ בְּנִדְרוֹ מֵפֵר אֶת שֶׁלָּהּ וְשֶׁלּוֹ קַיָּם:","כֵּיצַד. שָׁמַע אִשְׁתּוֹ אוֹ בִּתּוֹ אוֹמְרִין הֲרֵינִי נְזִירָה וְאָמַר וַאֲנִי. אֵינוֹ יָכוֹל לְהָפֵר וּשְׁנֵיהֶם נְזִירִים. אָמַר הוּא הֲרֵינִי נָזִיר וְשָׁמְעָה הִיא וְאָמְרָה וַאֲנִי. מֵפֵר לָהּ וְשֶׁלּוֹ קַיָּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","נָדַר לְעַצְמוֹ וְהִדִּירָהּ כְּמוֹתוֹ וְגָמַר בְּלִבּוֹ לְהַדִּירָהּ וְאָמְרָה אָמֵן הֲרֵי זֶה אֵינוֹ יָכוֹל לְהָפֵר. וְאִם נָדַר וְהִדִּירָהּ דֶּרֶךְ שְׁאֵלָה לֵידַע מַה בְּלִבָּהּ כְּמוֹ שֶׁאָמַר לָהּ הֲתִרְצִי בְּנֵדֶר זֶה לִהְיוֹת כְּמוֹתִי אוֹ לֹא וְאָמְרָה אָמֵן הֲרֵי זֶה מֵפֵר לָהּ:","כֵּיצַד. אָמַר לָהּ הֲרֵינִי נָזִיר וְאַתְּ כְּלוֹמַר וְאַתְּ נְזִירָה כְּמוֹתִי וְאָמְרָה אָמֵן אֵינוֹ יָכוֹל לְהָפֵר. אָמַר לָהּ הֲרֵינִי נָזִיר וּמַה תֹּאמְרִי הַאַתְּ נְזִירָה כְּמוֹתִי וְאָמְרָה אָמֵן הֲרֵי זֶה יָפֵר. וְאִם הֵפֵר לָהּ שֶׁלּוֹ בָּטֵל שֶׁזֶּה כְּמִי שֶׁתָּלָה נִדְרוֹ בְּנִדְרָהּ. אָמְרָה לוֹ הֲרֵינִי נְזִירָה וְאַתָּה וְאָמַר אָמֵן אֵינוֹ יָכוֹל לְהָפֵר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאִשָּׁה שֶׁנָּדְרָה וְשָׁמַע אַחֵר וְהִתְפִּיס עַצְמוֹ בְּנִדְרָהּ וְאָמַר וַאֲנִי. וְשָׁמַע אָבִיהָ אוֹ בַּעְלָהּ וְהֵפֵר לָהּ שֶׁלָּהּ מוּפָר וְזֶה שֶׁהִתְפִּיס עַצְמוֹ חַיָּב:","הָאִשָּׁה שֶׁאֵין לָהּ בַּעַל וְאֵינָהּ בִּרְשׁוּת אָב וְאָמְרָה הֲרֵי הַבָּשָׂר אָסוּר עָלַי לְאַחַר שְׁלֹשִׁים יוֹם וְנִשֵּׂאת בְּתוֹךְ שְׁלֹשִׁים יוֹם. אַף עַל פִּי שֶׁבְּשָׁעָה שֶׁחָל הַנֵּדֶר הֲרֵי הִיא בִּרְשׁוּת הַבַּעַל אֵינוֹ יָכוֹל לְהָפֵר. שֶׁבִּשְׁעַת הַנֵּדֶר לֹא הָיְתָה בִּרְשׁוּתוֹ וְעַל זֶה נֶאֱמַר (במדבר ל י) \"וְנֵדֶר אַלְמָנָה וּגְרוּשָׁה\" וְגוֹ'. וַאֲפִלּוּ הָיְתָה מְאֹרֶסֶת לוֹ בִּשְׁעַת הַנֵּדֶר. שֶׁאֵין הַבַּעַל מֵפֵר בְּקוֹדְמִין כְּמוֹ שֶׁבֵּאַרְנוּ:","נָדְרָה תַּחַת בַּעְלָהּ שֶׁיִּהְיֶה הַבָּשָׂר אָסוּר עָלֶיהָ לְאַחַר שְׁלֹשִׁים יוֹם. אוֹ שֶׁתִּהְיֶה נְזִירָה לְאַחַר שְׁלֹשִׁים יוֹם. וְהֵפֵר לָהּ בַּעְלָהּ וּמֵת אוֹ גֵּרְשָׁהּ בְּתוֹךְ שְׁלֹשִׁים יוֹם. אַף עַל פִּי שֶׁבְּשָׁעָה שֶׁהָיָה לַנֵּדֶר לָחוּל הֲרֵי הִיא גְּרוּשָׁה אוֹ אַלְמָנָה הֲרֵי זוֹ מֻתֶּרֶת שֶׁכְּבָר הֵפֵר לָהּ נֵדֶר זֶה:","אַלְמָנָה אוֹ גְּרוּשָׁה שֶׁאָמְרָה הֲרֵינִי אֲסוּרָה בְּיַיִן כְּשֶׁאֶנָּשֵׂא וְנִשֵּׂאת אֵין הַבַּעַל יָכוֹל לְהָפֵר. אָמְרָה וְהִיא תַּחַת בַּעְלָהּ הֲרֵינִי אֲסוּרָה בְּבָשָׂר כְּשֶׁאֶתְגָּרֵשׁ הֲרֵי הַבַּעַל מֵפֵר וּכְשֶׁתִּתְגָּרֵשׁ תִּהְיֶה מֻתֶּרֶת:","הַמְקַיֵּם בְּלִבּוֹ הֲרֵי זֶה קַיָּם. וְהַמֵּפֵר בְּלִבּוֹ אֵינוֹ מוּפָר כְּמוֹ שֶׁבֵּאַרְנוּ. לְפִיכָךְ אִם הֵפֵר בְּלִבּוֹ הֲרֵי זֶה יָכוֹל לַחְזֹר וּלְקַיֵּם. וְאִם קִיֵּם בְּלִבּוֹ אֵינוֹ יָכוֹל לַחְזֹר וּלְהָפֵר אֶלָּא אִם חָזַר בְּתוֹךְ כְּדֵי דִּבּוּר. כְּדֵי שֶׁלֹּא יִהְיֶה כֹּחַ דְּבָרִים שֶׁבְּלִבּוֹ גָּדוֹל מִכֹּחַ הַמּוֹצִיא בִּשְׂפָתָיו:","הַמְקַיֵּם נִדְרֵי בִּתּוֹ אוֹ אִשְׁתּוֹ וְנִחַם הֲרֵי זֶה נִשְׁאָל לְחָכָם וּמַתִּיר לוֹ הֲקָמָתוֹ וְחוֹזֵר וּמֵפֵר לָהּ בּוֹ בַּיּוֹם. אֲבָל אִם הֵפֵר לָהּ וְנִחַם אֵינוֹ יָכוֹל לְהִשָּׁאֵל לְחָכָם כְּדֵי שֶׁיַּחֲזֹר וִיקַיֵּם:","נַעֲרָה מְאֹרָסָה שֶׁנָּדְרָה וְקִיֵּם לָהּ אָבִיהָ לְבַדּוֹ אוֹ בַּעְלָהּ לְבַדּוֹ וְהֵפֵר לָהּ הָאַחֵר אַף עַל פִּי שֶׁנִּשְׁאַל לְחָכָם וְהִתִּיר לוֹ הֲקָמָתוֹ אֵינוֹ חוֹזֵר וּמֵפֵר לָהּ עִם הָאַחֵר שֶׁכְּבָר הֵפֵר לָהּ. שֶׁאֵין לָהֶם לְהָפֵר אֶלָּא שְׁנֵיהֶם כְּאֶחָד:","אָמַר לְבִתּוֹ אוֹ לְאִשְׁתּוֹ קַיָּם לִיךְ קַיָּם לִיךְ וְנִשְׁאַל עַל הֲקָמָה הָרִאשׁוֹנָה הֲרֵי הַשְּׁנִיָּה חָלָה עָלָיו. אָמַר לָהּ קַיָּם לִיךְ וּמוּפָר לִיךְ וְלֹא תָּחוּל הֲקָמָה אֶלָּא אִם כֵּן חָלָה הֲפָרָה הֲרֵי זֶה מוּפָר שֶׁאֵין הַהֲקָמָה מוֹעִיל אַחַר הַהֲפָרָה. אָמַר לָהּ קַיָּם וּמוּפָר לִיךְ בְּבַת אַחַת הֲרֵי זֶה קַיָּם. אָמַר לָהּ קַיָּם לִיךְ הַיּוֹם הֲרֵי זֶה קַיָּם לְעוֹלָם. אָמַר לָהּ מוּפָר לִיךְ לְמָחָר אֵינוֹ מוּפָר שֶׁהֲרֵי קִיְּמוֹ הַיּוֹם וּלְמָחָר אֵינוֹ יָכוֹל לְהָפֵר. אָמַר לָהּ קַיָּם לִיךְ שָׁעָה אַחַת וְעָבַר הַיּוֹם וְלֹא הֵפֵר הֲרֵי זֶה קַיָּם. וְאֵין אוֹמְרִין שֶׁזֶּה כְּמִי שֶׁאָמַר לָהּ הֲרֵי מוּפָר לִיךְ לְאַחַר שָׁעָה שֶׁהֲרֵי לֹא הוֹצִיא הֲפָרָה מִפִּיו. אָמַר לָהּ קַיָּם לֵיכִי שָׁעָה אַחַת וּכְשֶׁעָבְרָה הַשָּׁעָה אָמַר לָהּ מוּפָר לִיךְ הֲרֵי זֶה סָפֵק וּלְפִיכָךְ אֲסוּרָה בְּנִדְרָהּ. וְאִם עָבְרָה עַל נִדְרָהּ אֵינָהּ לוֹקָה:","מִי שֶׁנָּדַר נְדָרִים כְּדֵי לְכוֹנֵן דֵּעוֹתָיו וּלְתַקֵּן מַעֲשָׂיו הֲרֵי זֶה זָרִיז וּמְשֻׁבָּח. כֵּיצַד. כְּגוֹן מִי שֶׁהָיָה זוֹלֵל וְאָסַר עָלָיו הַבָּשָׂר שָׁנָה אוֹ שְׁתַּיִם. אוֹ מִי שֶׁהָיָה שׁוֹגֶה בַּיַּיִן וְאָסַר הַיַּיִן עַל עַצְמוֹ זְמַן מְרֻבֶּה. אוֹ אָסַר הַשִּׁכְרוּת לְעוֹלָם. וְכֵן מִי שֶׁהָיָה רוֹדֵף שַׁלְמוֹנִים וְנִבְהָל לְהוֹן וְאָסַר עַל עַצְמוֹ הַמַּתָּנוֹת אוֹ הֲנָיַת אַנְשֵׁי מְדִינָה זוֹ. וְכֵן מִי שֶׁהָיָה מִתְגָּאֶה בְּיָפְיוֹ וְנָדַר בְּנָזִיר וְכַיּוֹצֵא בִּנְדָרִים אֵלּוּ. כֻּלָּן דֶּרֶךְ עֲבוֹדָה לַשֵּׁם הֵם. וּבִנְדָרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶן אָמְרוּ חֲכָמִים נְדָרִים סְיָג לִפְרִישׁוּת:","וְאַף עַל פִּי שֶׁהֵן עֲבוֹדָה (לַשֵּׁם) לֹא יַרְבֶּה אָדָם בְּנִדְרֵי אִסּוּר וְלֹא יַרְגִּיל עַצְמוֹ בָּהֶם. אֶלָּא יִפְרשׁ מִדְּבָרִים שֶׁרָאוּי לִפְרשׁ מֵהֶן בְּלֹא נֵדֶר:","אָמְרוּ חֲכָמִים (גמרא נדרים נט א) \"כָּל הַנּוֹדֵר כְּאִלּוּ בָּנָה בָּמָה\". וְאִם עָבַר וְנָדַר מִצְוָה לְהִשָּׁאֵל עַל נִדְרוֹ כְּדֵי שֶׁלֹּא יְהֵא מִכְשׁוֹל לְפָנָיו. בַּמֶּה דְּבָרִים אֲמוּרִים בְּנִדְרֵי אִסָּר. אֲבָל נִדְרֵי הֶקְדֵּשׁ מִצְוָה לְקַיְּמָן וְלֹא יִשָּׁאֵל עֲלֵיהֶן אֶלָּא מִדֹּחַק שֶׁנֶּאֱמַר (תהילים קטז יד) (תהילים קטז יח) \"נְדָרַי לַה' אֲשַׁלֵּם\": סְלִיקוּ לְהוּ הִלְכוֹת נְדָרִים בְּסִיַעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Woman Suspected of Infidelity 4":["בַּחֲמִשָׁה עָשָׂר בַּאֲדָר נִפְנִין בֵּית דִּין לְצָרְכֵי הָרַבִּים. וּבוֹדְקִין עַל הָרְאוּיָה לִשְׁתּוֹת לְהַשְׁקוֹתָהּ. וְעַל הָרְאוּיָה לְקַנֵּא לָהּ וּלְהוֹצִיאָהּ בְּלֹא כְּתֻבָּה. וּבְכָל זְמַן מַשְׁקִין אֶת הַסּוֹטוֹת:","וְאֵין מַשְׁקִין אֶת הַסּוֹטָה אֶלָּא בַּיּוֹם. וְכָל הַיּוֹם כָּשֵׁר לְהַשְׁקוֹת סוֹטָה. וְאֵין מַשְׁקִין שְׁתֵּי סוֹטוֹת כְּאַחַת שֶׁנֶּאֱמַר (במדבר ה טז) \"וְהֶעֱמִיד אֹתָהּ הַכֹּהֵן\":","סוֹטָה שֶׁאָמְרָה אֵינִי שׁוֹתָה מֵחֲמַת יִרְאָה וָפַחַד שֶׁיֵּשׁ לָהּ יְכוֹלָה לַחֲזֹר וְלוֹמַר הֲרֵינִי שׁוֹתָה. אֲבָל אָמְרָה אֵינִי שׁוֹתָה וְהִיא בְּרִיאָה וְאֵינָהּ יְרֵאָה וְלֹא פּוֹחֶדֶת אֵינָהּ יְכוֹלָה לַחֲזֹר וְלוֹמַר הִנְנִי שׁוֹתָה:","אָמְרָה אֵינִי שׁוֹתָה קֹדֶם שֶׁתִּמָּחֵק הַמְּגִלָּה הֲרֵי מְגִלָּתָהּ נִגְנֶזֶת וְאֵינָהּ כְּשֵׁרָה לְהַשְׁקוֹת בָּהּ סוֹטָה אַחֶרֶת. וּמִנְחָתָהּ מִתְפַּזֶּרֶת עַל הַדֶּשֶׁן. וְאִם אָמְרָה אֵינִי שׁוֹתָה אַחַר שֶׁנִּמְחֲקָה הַמְּגִלָּה מְעַרְעֲרִין אוֹתָהּ וּמַשְׁקִין אוֹתָהּ בְּעַל כָּרְחָהּ:","וּמְאַיְּמִין עָלֶיהָ שֶׁתִּשְׁתֶּה וְאוֹמְרִין לָהּ בִּתִּי אִם בָּרוּר לָךְ הַדָּבָר שֶׁטְּהוֹרָה אַתְּ עִמְדִי עַל בֻּרְיֵךְ וּשְׁתִי וְאַל תִּפְחֲדִי לְפִי שֶׁאֵין הַמַּיִם דּוֹמִין אֶלָּא לְסַם יָבֵשׁ מֻנָּח עַל בָּשָׂר חַי. יֵשׁ שָׁם מַכָּה מְחַלְחֵל וְיוֹרֵד. אֵין שָׁם מַכָּה אֵינוֹ עוֹשֶׂה כְּלוּם:","אָמְרָה טְמֵאָה אֲנִי אַף עַל פִּי שֶׁנִּמְחֲקָה הַמְּגִלָּה הַמַּיִם נִשְׁפָּכִין מִפְּנֵי שֶׁאֵין בָּהֶן קְדֻשָּׁה. וּמִנְחָתָהּ מִתְפַּזֶּרֶת עַל הַדֶּשֶׁן:","מְגִלַּת סוֹטָה שֶׁכְּתָבָהּ בַּלַּיְלָה פְּסוּלָה שֶׁנֶּאֱמַר וְכָתַב וְגוֹ' (במדבר ה כד) \"וְהִשְׁקָה\" וְגוֹ' (במדבר ה כה) \"וְהִקְרִיב\" וְגוֹ' כְּשֵׁם שֶׁקָּרְבָּנָהּ בַּיּוֹם כָּךְ כְּתִיבַת הַמְּגִלָּה וְהַשְׁקָיָתָהּ בַּיּוֹם. כְּתָבָהּ לְמַפְרֵעַ פְּסוּלָה שֶׁנֶּאֱמַר הָאָלָה עַל הַסֵּדֶר. כְּתָבָהּ קֹדֶם שֶׁתְּקַבֵּל עָלֶיהָ הַשְּׁבוּעָה פְּסוּלָה שֶׁנֶּאֱמַר (במדבר ה כא) \"וְהִשְׁבִּיעַ\" וְכָתַב:","כְּתָבָהּ אִגֶּרֶת פְּסוּלָה שֶׁנֶּאֱמַר (במדבר ה כג) \"בַּסֵּפֶר\". כְּתָבָהּ עַל שְׁנֵי דַּפִּין פְּסוּלָה שֶׁנֶּאֱמַר בַּסֵּפֶר סֵפֶר אֶחָד וְלֹא שְׁנַיִם וּשְׁלֹשָׁה. וְאֵינוֹ כּוֹתֵב לֹא עַל הַנְּיָר וְלֹא עַל הַדִּפְתְּרָא אֶלָּא בִּמְגִלַּת סֵפֶר שֶׁנֶּאֱמַר בַּסֵּפֶר. וְאִם כְּתָבָהּ עַל נְיָר אוֹ דִּפְתְּרָא פְּסוּלָה:","וְאִם כְּתָבָהּ יִשְׂרָאֵל אוֹ כֹּהֵן קָטָן פְּסוּלָה שֶׁנֶּאֱמַר (במדבר ה כג) \"וְכָתַב הַכֹּהֵן\". אֵינוֹ כּוֹתְבָהּ לֹא בְּקוֹמוֹס וְלֹא בְּקַנְקַנְתּוֹם וְלֹא בְּכָל דָּבָר שֶׁרִשּׁוּמוֹ נִכָּר וְעוֹמֵד אֶלָּא בִּדְיוֹ שֶׁאֵין בּוֹ קַנְקַנְתּוֹם שֶׁנֶּאֱמַר וְכָתַב (במדבר ה כג) \"וּמָחָה\" כְּתָב שֶׁהוּא יָכוֹל לְהִמָּחוֹת. וְאִם כָּתַב בְּדָבָר הַמִּתְקַיֵּם פְּסוּלָה:","נִשְׁאַר בַּמְּגִלָּה רשֶׁם כְּתָב נִכָּר פְּסוּלָה עַד שֶׁיִּמְחֹק יָפֶה יָפֶה. כָּתַב אוֹת אַחַת וּמְחָקָהּ וְחָזַר וְכָתַב אוֹת שְׁנִיָּה וּמְחָקָהּ עַד שֶׁהִשְׁלִים פְּסוּלָה עַד שֶׁתִּהְיֶה כֻּלָּהּ כְּתוּבָה:","כְּתָבָהּ שֶׁלֹּא לִשְׁמָהּ אוֹ מְחָקָהּ שֶׁלֹּא לִשְׁמָהּ פְּסוּלָה. כָּתַב שְׁתֵּי מְגִלּוֹת לִשְׁתֵּי סוֹטוֹת וּמְחָקָן לְתוֹךְ כּוֹס אֶחָד אוֹ לְתוֹךְ שְׁתֵּי כּוֹסוֹת וְעֵרְבָן בְּכוֹס אֶחָד וְהִשְׁקָה לִשְׁתֵּיהֶן פְּסוּלָה. לְפִי שֶׁכָּל אַחַת מֵהֶן לֹא שָׁתְתָה מְגִלָּתָהּ. מְחָקָן בִּשְׁנֵי כּוֹסוֹת וְעֵרְבָן וְחָזַר וְחִלְּקָן לִשְׁנֵי הַכּוֹסוֹת לֹא יַשְׁקֶה אוֹתָן וְאִם הִשְׁקָה כָּשֵׁר. וְאִם נִשְׁפְּכוּ הַמַּיִם הֲרֵי זֶה כּוֹתֵב מְגִלָּה אַחֶרֶת וּמֵבִיא מַיִם אֲחֵרִים. נִשְׁפְּכוּ וְנִשְׁתַּיֵּר מֵהֶן לֹא יַשְׁקֶה אֶת הַשְּׁאָר. וְאִם הִשְׁקָה כָּשֵׁר:","מֵי סוֹטָה שֶׁלָּנוּ נִפְסָלִין בְּלִינָה. הִקְדִּים עָפָר לַמַּיִם פְּסוּלָה. לֹא הָיָה שָׁם עָפָר בַּהֵיכָל מֵבִיא עָפָר מִבַּחוּץ וּמַנִּיחוֹ בַּהֵיכָל וְלוֹקֵחַ מִמֶּנּוּ וְנוֹתֵן עַל פְּנֵי הַמַּיִם. וְאֵינוֹ מֵבִיא אֵפֶר אֲבָל מֵבִיא רַקְבּוּבִית שֶׁהִיא כְּעָפָר:","וְלֹא יַחְפֹּר בְּקוֹרְדוֹם בַּהֵיכָל וְיוֹצִיא עָפָר שֶׁנֶּאֱמַר (במדבר ה יז) \"אֲשֶׁר יִהְיֶה בְּקַרְקַע הַמִּשְׁכָּן\". וְאִם חָפַר וְהוֹצִיא עָפָר כָּשֵׁר:","הִקְרִיב אֶת מִנְחָתָהּ וְאַחַר כָּךְ הִשְׁקָהּ כְּשֵׁרָה. נִטְמֵאת מִנְחָתָהּ קֹדֶם שֶׁיַּנִּיחֶנָה בִּכְלִי שָׁרֵת הֲרֵי זוֹ תִּפָּדֶה כְּכָל הַמְּנָחוֹת שֶׁנִּטְמְאוּ קֹדֶם שֶׁיִּתְקַדְּשׁוּ בִּכְלִי שָׁרֵת וְיָבִיאוּ מִנְחָה אַחֶרֶת. נִטְמֵאת הַמִּנְחָה אַחַר שֶׁקִּדְּשָׁהּ בִּכְלִי שָׁרֵת הֲרֵי זוֹ תִּשָּׂרֵף. וְכֵן אִם אָמְרָה טְמֵאָה אֲנִי קֹדֶם שֶׁתִּקָּמֵץ הַמִּנְחָה. אוֹ שֶׁאָמְרָה אֵינִי שׁוֹתָה. אוֹ שֶׁלֹּא רָצָה בַּעְלָהּ לְהַשְׁקוֹתָהּ. אוֹ שֶׁבָּאוּ עֵדֵי טֻמְאָה. אוֹ שֶׁמֵּת הוּא. אוֹ שֶׁמֵּתָה הִיא. הֲרֵי הַמִּנְחָה כֻּלָּהּ נִשְׂרֶפֶת. וְאִם אֵרַע אֶחָד מֵאֵלּוּ אַחַר שֶׁקָּרַב הַקֹּמֶץ אֵין הַשְּׁיָרִים נֶאֱכָלִין:","הָיָה בַּעְלָהּ כֹּהֵן אֵין שְׁיָרֵי מִנְחָתָהּ נֶאֱכָלִין מִפְּנֵי שֶׁיֵּשׁ לַבַּעַל חֵלֶק בָּהֶם. וְאֵינָהּ עוֹלָה כֻּלָּהּ לְאִשִּׁים כְּמִנְחַת זִכְרֵי כְּהֻנָּה מִפְּנֵי שֶׁיֵּשׁ לָהּ חֵלֶק בָּהּ. אֶלָּא הַקֹּמֶץ קָרֵב לְעַצְמוֹ וּשְׁיָרִים מִתְפַּזְּרִין עַל בֵּית הַדֶּשֶׁן. נִמְצְאוּ עֵדֵיהָ זוֹמְמִין מִנְחָתָהּ תֵּצֵא לְחֻלִּין:","הַמְקַנֵּא לְאִשְׁתּוֹ עַל יְדֵי אֲנָשִׁים הַרְבֵּה וְנִסְתְּרָה עִם כָּל אֶחָד וְאֶחָד מֵהֶם הֲרֵי זֶה מֵבִיא מִנְחָה אַחַת עַל יְדֵי כֻּלָּן כְּשֶׁמַּשְׁקֶה אוֹתָהּ שֶׁנֶּאֱמַר (במדבר ה טו) \"מִנְחַת קְנָאֹת הִיא\". מִנְחָה אַחַת לְקִנּוּיִין הַרְבֵּה:","יֵשׁ לַבַּעַל לְגַלְגֵּל בִּשְׁבוּעָה עָלֶיהָ שֶׁלֹּא זִנְּתָה עִם אִישׁ זֶה שֶׁקִּנֵּא לָהּ בּוֹ וְלֹא עִם אִישׁ אַחֵר. וְשֶׁלֹּא זִנְּתָה תַּחְתָּיו מִשֶּׁנִּתְאָרְסָה קֹדֶם שֶׁתִּנָּשֵׂא וְלֹא אַחַר שֶׁנִּשֵּׂאת. אֲבָל אֵינוֹ מְגַלְגֵּל עָלֶיהָ שֶׁלֹּא זִנְּתָה קֹדֶם הָאֵרוּסִין וְלֹא אַחַר שֶׁגֵּרְשָׁהּ אִם גֵּרְשָׁהּ וְהֶחֱזִירָהּ. שֶׁאִם זִנְּתָה בְּעֵת זֶה לֹא תֵּאָסֵר עָלָיו. וְכָל שֶׁתִּבָּעֵל וְלֹא תִּהְיֶה אֲסוּרָה לוֹ אֵינוֹ מַתְנֶה עִמָּהּ. לְפִיכָךְ אִם כָּנַס יְבִמְתּוֹ אֵינוֹ מְגַלְגֵּל עָלֶיהָ שֶׁלֹּא זִנְּתָה כְּשֶׁהָיְתָה שׁוֹמֶרֶת יָבָם. אֲבָל מְגַלְגֵּל עָלֶיהָ שֶׁלֹּא זִנְּתָה תַּחַת אָחִיו שֶׁאִם זִנְּתָה תַּחַת אָחִיו הֲרֵי זוֹ אֲסוּרָה עָלָיו. וְכֵן אִם גֵּרְשָׁהּ וְהֶחֱזִירָהּ מְגַלְגֵּל עָלֶיהָ שֶׁלֹּא זִנְּתָה תַּחְתָּיו בַּנִּשּׂוּאִין הָרִאשׁוֹנִים. וְיֵשׁ לוֹ לְגַלְגֵּל עָלֶיהָ בִּלְהַבָּא שֶׁלֹּא תִּזְנֶה תַּחְתָּיו וְשֶׁלֹּא תִּזְנֶה אַחַר שֶׁיַּחְזִירֶנָּה אִם יְגָרֵשׁ וְיַחֲזִיר. לְפִיכָךְ כְּשֶׁתִּזְנֶה לְהַבָּא מַיִם בּוֹדְקִין אוֹתָהּ וְיֶאֶרְעוּ לָהּ אוֹתָן הַמְאֹרָעוֹת. לְכָךְ נֶאֱמַר (במדבר ה כב) \"אָמֵן אָמֵן\". אָמֵן מֵאִישׁ זֶה אָמֵן מֵאִישׁ אַחֵר. אָמֵן נְשׂוּאָה אָמֵן אֲרוּסָה. אָמֵן לְשֶׁעָבַר אָמֵן לְהַבָּא:","מִצְוַת חֲכָמִים עַל בְּנֵי יִשְׂרָאֵל לְקַנְּאוֹת לִנְשֵׁיהֶן שֶׁנֶּאֱמַר (במדבר ה יד) \"וְקִנֵּא אֶת אִשְׁתּוֹ\". וְכָל הַמְקַנֵּא אֶת אִשְׁתּוֹ נִכְנְסָה בּוֹ רוּחַ טָהֳרָה. וְלֹא יְקַנֵּא לָהּ לֹא מִתּוֹךְ שְׂחוֹק וְלֹא מִתּוֹךְ שִׂיחָה וְלֹא מִתּוֹךְ קַלּוּת רֹאשׁ וְלֹא מִתּוֹךְ מְרִיבָה וְלֹא לְהַטִּיל עָלֶיהָ אֵימָה. וְאִם עָבַר וְקִנֵּא לָהּ בִּפְנֵי עֵדִים מִתּוֹךְ אֶחָד מִכָּל הַדְּבָרִים הָאֵלּוּ הֲרֵי זֶה קִנּוּי:","אֵין רָאוּי לִקְפֹּץ וּלְקַנְּאוֹת בִּפְנֵי עֵדִים תְּחִלָּה אֶלָּא בֵּינוֹ לְבֵינָהּ בְּנַחַת וּבְדֶרֶךְ טָהֳרָה וְאַזְהָרָה כְּדֵי לְהַדְרִיכָהּ בְּדֶרֶךְ יְשָׁרָה וּלְהָסִיר הַמִּכְשׁוֹל. וְכָל מִי שֶׁאֵינוֹ מַקְפִּיד עַל אִשְׁתּוֹ וְעַל בָּנָיו וּבְנֵי בֵּיתוֹ וּמַזְהִירָן וּפוֹקֵד דַּרְכֵיהֶן תָּמִיד עַד שֶׁיֵּדַע שֶׁהֵן שְׁלֵמִין מִכָּל חֵטְא וּמֵעָוֹן הֲרֵי זֶה חוֹטֵא שֶׁנֶּאֱמַר (איוב ה כד) \"וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךָ וּפָקַדְתָּ נָוְךָ וְלֹא תֶחֱטָא\":"]} as Record<string, string[]>;
